#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <pigpio.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_POINTER_CONVERT 0x00
#define ADS1115_REG_POINTER_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0000
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_MODE_SINGLE 0x0100

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int setup_ads1115() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    int fd = pi_i2c_open(1, ADS1115_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pi_i2c_errorstr());
        return -1;
    }

    uint16_t config = ADS1115_CONFIG_OS_SINGLE |
                      ADS1115_CONFIG_MUX_SINGLE_0 |
                      ADS1115_CONFIG_PGA_4_096V |
                      ADS1115_CONFIG_DR_128SPS |
                      ADS1115_CONFIG_MODE_SINGLE;

    if (pi_i2c_write(fd, ADS1115_REG_POINTER_CONFIG, &config, 2) != 2) {
        fprintf(stderr, "Failed to write to ADS1115: %s\n", pi_i2c_errorstr());
        pi_i2c_close(fd);
        return -1;
    }

    return fd;
}

int read_adc(int fd) {
    uint16_t data;
    if (pi_i2c_read(fd, ADS1115_REG_POINTER_CONVERT, &data, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115: %s\n", pi_i2c_errorstr());
        return -1;
    }

    // Convert the 16-bit data to a signed 16-bit integer
    int16_t result = (int16_t)((data & 0x000Fu) << 12 | (data & 0x0FF0u) << 4 | (data & 0xF000u) >> 4);

    return result;
}

double convert_to_amperes(int16_t adc_value) {
    // ADS1115 16-bit signed value range: -32768 to 32767
    // Full-scale range for ±4.096V: 32767 corresponds to 4.096V
    double voltage = adc_value * (4.096 / 32767.0);
    // Assuming the MLX91219 has a sensitivity of 185 mV/A
    double current = voltage / 0.185;
    return current;
}

int main() {
    signal(SIGINT, handle_sigint);

    int fd = setup_ads1115();
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int16_t adc_value = read_adc(fd);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            break;
        }

        double current = convert_to_amperes(adc_value);
        printf("Current: %.3f A\n", current);

        usleep(500000); // Sleep for 500 ms
    }

    pi_i2c_close(fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

