#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CS_PIN 8
#define FLAME_SENSOR_PIN 4
#define MCP3008_CHANNEL 0

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    if (gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(MCP3008_CS_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set MCP3008 CS high\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Failed to read flame sensor\n");
        return -1;
    }
    return value;
}

int read_mcp3008() {
    unsigned int adc_value = 0;
    if (gpioSPIDataRW(SPI_CHANNEL, &adc_value, 3) < 0) {
        fprintf(stderr, "Failed to read MCP3008\n");
        return -1;
    }

    // Extract the 10-bit ADC value
    adc_value = (adc_value >> 6) & 0x03FF;
    return adc_value;
}

double calculate_temperature(int adc_value) {
    // Assuming a linear relationship for demonstration purposes
    // Replace with actual conversion logic as needed
    return (adc_value * 330.0 / 1023.0) * 100.0; // Example conversion
}

int main() {
    signal(SIGINT, handle_sigint);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    FILE *file = fopen("flame_data.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open flame_data.csv\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(file, "Timestamp,Flame Detected,Temperature (C)\n");

    while (keep_running) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor, skipping entry\n");
            continue;
        }

        int adc_value = read_mcp3008();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading MCP3008, skipping entry\n");
            continue;
        }

        double temperature = calculate_temperature(adc_value);

        fprintf(file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
        fflush(file);

        sleep(1);
    }

    fclose(file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

