volatile sig_atomic_t running = 1;
FILE *log_file = NULL;
struct ads1x15 *ads = NULL;
int flame_sensor_line = -1;
int buzzer_line = -1;
int last_flame_state = -1;
time_t last_flame_change_time = 0;

void handle_sigint(int sig) {
    running = 0;
}

void log_event(const char *message) {
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %s\n", ctime(&now), message);
        fflush(log_file);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library: %s\n", strerror(errno));
        return 1;
    }

    if ((log_file = fopen("fire_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if ((ads = ads1x15_init(1, ADS1015_ADDRESS_GND)) == NULL) {
        fprintf(stderr, "Failed to initialize ADS1115: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (ads1x15_setGain(ads, ADS1115_PGA_6_144V) != 0) {
        fprintf(stderr, "Failed to set gain on ADS1115: %s\n", strerror(errno));
        ads1x15_close(ads);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (ads1x15_setMode(ads, ADS1115_MODE_SINGLE) != 0) {
        fprintf(stderr, "Failed to set mode on ADS1115: %s\n", strerror(errno));
        ads1x15_close(ads);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (ads1x15_setDataRate(ads, ADS1115_DR_128SPS) != 0) {
        fprintf(stderr, "Failed to set data rate on ADS1115: %s\n", strerror(errno));
        ads1x15_close(ads);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (ads1x15_setChannel(ads, ADS1115_CHANNEL_0) != 0) {
        fprintf(stderr, "Failed to set channel on ADS1115: %s\n", strerror(errno));
        ads1x15_close(ads);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode: %s\n", strerror(errno));
        ads1x15_close(ads);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode: %s\n", strerror(errno));
        gpioSetMode(BUZZER_PIN, PI_OUTPUT);
        ads1x15_close(ads);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        int flame_state = gpioRead(FLAME_SENSOR_PIN);
        int current_time = time(NULL);

        if (flame_state != last_flame_state) {
            last_flame_change_time = current_time;
            last_flame_state = flame_state;
        }

        if (flame_state && (current_time - last_flame_change_time) * 1000 >= DEBOUNCE_TIME_MS) {
            if (last_flame_state == 0) {
                log_event("Flame detected!");
            }
        }

        int16_t adc_value = ads1x15_read(ads);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read from ADS1115: %s\n", strerror(errno));
        } else {
            float voltage = adc_value * 0.1875 / 1000.0;
            float temperature = (voltage - 0.5) * 100.0;

            if (temperature > FIRE_THRESHOLD_TEMP) {
                log_event("Temperature exceeds threshold!");
            }
        }

        if (flame_state && temperature > FIRE_THRESHOLD_TEMP) {
            gpioWrite(BUZZER_PIN, 1);
            log_event("Fire event detected!");
            usleep(BEEP_DURATION_MS * 1000);
            gpioWrite(BUZZER_PIN, 0);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    gpioWrite(BUZZER_PIN, 0);
    ads1x15_close(ads);
    fclose(log_file);
    gpioTerminate();

    return 0;
}
