#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP_NAME "gpiochip5"
#define FAN_GPIO 18
#define CURRENT_THRESHOLD 512 // Example threshold for 8-bit ADC
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

static int spi_fd = -1;
static struct gpiod_line *fan_line = NULL;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_spi_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(fd, SPI_IOC_RD_MODE, &mode) < 0 ||
        ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &bits) < 0 ||
        ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0 ||
        ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI parameters");
        close(fd);
        return -1;
    }

    return fd;
}

int open_gpio_chip(const char *chip_name) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            perror("Failed to open GPIO chip");
            return -1;
        }
    }
    return chip;
}

int setup_fan_gpio(struct gpiod_chip *chip) {
    fan_line = gpiod_chip_get_line(chip, FAN_GPIO);
    if (!fan_line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        perror("Failed to request GPIO line");
        return -1;
    }

    return 0;
}

void cleanup() {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (fan_line) {
        gpiod_line_release(fan_line);
    }
    if (gpiod_chip_close(fan_line->chip)) {
        perror("Failed to close GPIO chip");
    }
}

int read_adc_value() {
    uint8_t tx[] = {0x01}; // Command to read from MCP3008
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 1
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    uint16_t adc_value = (rx[1] & 0x03) << 8 | rx[2];
    return adc_value;
}

void log_current_value(int value) {
    FILE *log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s: %d\n", timestamp, value);
    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    spi_fd = open_spi_device(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = open_gpio_chip(GPIO_CHIP_NAME);
    if (chip < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (setup_fan_gpio(chip) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int adc_value = read_adc_value();
        if (adc_value < 0 || adc_value == 0 || adc_value == 0xFF) {
            fprintf(stderr, "Sensor absent or SPI transfer failed\n");
            continue;
        }

        log_current_value(adc_value);

        if (adc_value > CURRENT_THRESHOLD) {
            gpiod_line_set_value(fan_line, 1);
        } else {
            gpiod_line_set_value(fan_line, 0);
        }

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

