#define ADS1115_CONFIG_PGA_6_144V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_860SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

double convert_to_ppm(int raw_value) {
    // Placeholder for the actual conversion logic using a calibrated logarithmic curve
    // This is a dummy conversion for demonstration purposes
    return (double)raw_value / 32768.0 * 1000.0; // Example conversion
}

int read_adc_value(gpiod_i2c_chip *chip) {
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 |
                      ADS1115_CONFIG_PGA_6_144V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_860SPS | ADS1115_CONFIG_CQUE_NONE;
    uint16_t data[2] = {0};

    if (gpiod_i2c_write(chip, ADS1115_REG_POINTER_CONFIG, &config, sizeof(config)) < 0) {
        syslog(LOG_ERR, "Failed to write configuration to ADS1115: %s", strerror(errno));
        return -1;
    }

    usleep(10000); // Wait for conversion to complete

    if (gpiod_i2c_read(chip, ADS1115_REG_POINTER_CONVERT, data, sizeof(data)) < 0) {
        syslog(LOG_ERR, "Failed to read conversion result from ADS1115: %s", strerror(errno));
        return -1;
    }

    return (data[0] << 8) | data[1];
}

