int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return -1;
    }
    return 0;
}

int init_spi() {
    int spi_handle = spiOpen(0, SPI_SPEED, SPI_MODE_0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        return -1;
    }
    return spi_handle;
}

int read_flame_sensor() {
    int line = gpiod_chip_open("/dev/gpiochip0");
    if (line < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    int flame_sensor = gpiod_line_request_output(line, "flame_sensor", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT, 0);
    if (flame_sensor < 0) {
        fprintf(stderr, "Failed to request GPIO line for flame sensor\n");
        gpiod_chip_close(line);
        return -1;
