#define I2C_DEVICE "/dev/i2c-1"
#define MICS4514_ADDR 0x58
#define OX_CHANNEL 0x00
#define RED_CHANNEL 0x01
#define CO_CONVERSION_FACTOR 0.4 // Example conversion factor, adjust as needed

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, MICS4514_ADDR) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

int main() {
    int i2c_fd;
    uint8_t data[4];
    int ox, red;
    float co_ppm;
    FILE *co_log, *alert_log;
    struct sigaction sa;

    // Setup signal handling
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to setup signal handling");
        return EXIT_FAILURE;
    }

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Open log files
    co_log = fopen("co_log.txt", "a");
    if (!co_log) {
        perror("Failed to open co_log.txt");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    alert_log = fopen("alert_log.txt", "a");
    if (!alert_log) {
        perror("Failed to open alert_log.txt");
        fclose(co_log);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Read OX channel
        if (i2c_read(i2c_fd, OX_CHANNEL, data, 2) != 0) {
            fprintf(stderr, "Error reading OX channel\n");
            break;
        }
        ox = (data[0] << 8) | data[1];

        // Read RED channel
        if (i2c_read(i2c_fd, RED_CHANNEL, data, 2) != 0) {
            fprintf(stderr, "Error reading RED channel\n");
            break;
        }
        red = (data[0] << 8) | data[1];

        // Convert OX value to CO concentration in ppm
        co_ppm = ox * CO_CONVERSION_FACTOR;

        // Log CO concentration
        if (fprintf(co_log, "CO: %.2f ppm\n", co_ppm) < 0) {
            perror("Failed to write to co_log.txt");
            break;
        }
        fflush(co_log);

        // Check for alert threshold
        if (co_ppm >= 25.0) {
            if (fprintf(alert_log, "ALERT: CO concentration %.2f ppm exceeds threshold\n", co_ppm) < 0) {
                perror("Failed to write to alert_log.txt");
                break;
            }
            fflush(alert_log);
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    if (co_log) fclose(co_log);
    if (alert_log) fclose(alert_log);
    if (i2c_fd >= 0) close(i2c_fd);

    return EXIT_SUCCESS;
}

