#include <gpiod.h>

#define SAMPLES 100
#define HIGH_LEVEL_THRESHOLD 0.5
#define LED_GPIO 27
#define CE0_GPIO 8
#define CE1_GPIO 9
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int setup_gpio(gpiod_chip *chip, int line, int flags) {
    gpiod_line *gpio_line = gpiod_chip_get_line(chip, line);
    if (!gpio_line) {
        fprintf(stderr, "Failed to get line %d\n", line);
        return -1;
    }
    if (gpiod_line_request_rising_edge(gpio_line, "audio_app") < 0) {
        fprintf(stderr, "Failed to request line %d\n", line);
        gpiod_line_release(gpio_line);
        return -1;
    }
    return 0;
}

int setup_spi(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(*fd);
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(*fd);
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) < 0) {
        perror("Failed to set SPI max speed");
        close(*fd);
        return -1;
    }

    return 0;
}

int read_adc(int fd, int ce_pin, uint8_t *buffer, size_t length) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)buffer,
        .rx_buf = (unsigned long)buffer,
        .len = length,
        .delay_usecs = 0,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to transfer SPI message");
        return -1;
    }

    return 0;
}

void set_gpio_value(gpiod_chip *chip, int line, int value) {
    gpiod_line *gpio_line = gpiod_chip_get_line(chip, line);
    if (gpio_line) {
        gpiod_line_set_value(gpio_line, value);
        gpiod_line_release(gpio_line);
    }
}

double compute_rms(int16_t *samples, size_t count) {
    double sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += samples[i] * samples[i];
    }
    return sqrt(sum / count);
}

int main() {
    int spi_fd;
    gpiod_chip *chip;
    gpiod_line *led_line;
    int ce0_fd, ce1_fd;
    uint8_t buffer[3];
    int16_t mic1_samples[SAMPLES], mic2_samples[SAMPLES];
    double mic1_rms, mic2_rms;
    FILE *file;
    struct timespec ts;
    int i;

    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    if (setup_gpio(chip, LED_GPIO, GPIOD_OUT) < 0 ||
        setup_gpio(chip, CE0_GPIO, GPIOD_OUT) < 0 ||
        setup_gpio(chip, CE1_GPIO, GPIOD_OUT) < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (setup_spi(&spi_fd) < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    file = fopen("audio_events.csv", "a");
    if (!file) {
        perror("Failed to open file");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        clock_gettime(CLOCK_REALTIME, &ts);

        for (i = 0; i < SAMPLES; ++i) {
            buffer[0] = 0x01; // Start bit
            buffer[1] = 0x80 | (0x00 << 4); // Single-ended, channel 0
            buffer[2] = 0x00; // Dummy byte

