#include <math.h>
#include <gpiod.h>
#include <libi2c.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_A0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_1600SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_GAIN 0x0200
#define ADS1115_CONFIG_MODE 0x0100
#define ADS1115_CONFIG_DR 0x0080
#define ADS1115_CONFIG_CQUE 0x0003

#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define CURRENT_THRESHOLD 50.0
#define LED_GPIO 17

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

double convert_to_current(int16_t raw_value) {
    // Conversion factor for ADS1115 with 4.096V range and 16-bit resolution
    double voltage = raw_value * 4.096 / 32767.0;
    // Conversion factor for MLX91204: 1V = 10A
    return voltage * 10.0;
}

void error_exit(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

int main() {
    struct i2c_adapter *adapter;
    struct i2c_msg msgs[2];
    uint8_t config[2];
    uint8_t data[2];
    int16_t raw_value;
    double current;
    double buffer[BUFFER_SIZE];
    int buffer_index = 0;
    double sum = 0.0;
    int fd_led;
    int ret;

    // Set up signal handler for graceful shutdown
    signal(SIGINT, handle_sigint);

    // Initialize GPIO for LED
    fd_led = gpiod_chip_open("/dev/gpiochip0");
    if (fd_led < 0) {
        error_exit("Failed to open GPIO chip");
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(fd_led, LED_GPIO);
    if (!led_line) {
        gpiod_chip_close(fd_led);
        error_exit("Failed to get GPIO line");
    }

    ret = gpiod_line_request_output(led_line, "warning_led", 0);
    if (ret < 0) {
        gpiod_chip_close(fd_led);
        error_exit("Failed to request GPIO line");
    }

    // Initialize I2C adapter
    adapter = i2c_get_adapter(1);
    if (!adapter) {
        gpiod_line_release(led_line);
        gpiod_chip_close(fd_led);
        error_exit("Failed to get I2C adapter");
    }

    // Configure ADS1115
    config[0] = ADS1115_REG_CONFIG;
    config[1] = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_A0 | ADS1115_CONFIG_PGA_4_096V |
                ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_1600SPS | ADS1115_CONFIG_CQUE_NONE;

    msgs[0].addr = ADS1115_ADDRESS;
    msgs[0].flags = 0;
    msgs[0].len = 2;
    msgs[0].buf = config;

    msgs[1].addr = ADS1115_ADDRESS;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 2;
    msgs[1].buf = data;

    while (keep_running) {
        // Start conversion
        ret = i2c_transfer(adapter, msgs, 1);
        if (ret < 0) {
            fprintf(stderr, "I2C write error\n");
            break;
        }

        // Wait for conversion to complete
        usleep(1000000 / SAMPLE_RATE_HZ);

        // Read conversion result
        ret = i2c_transfer(adapter, msgs, 1);
        if (ret < 0) {
            fprintf(stderr, "I2C read error\n");
            break;
        }

        // Convert raw data to 16-bit signed integer
        raw_value = (int16_t)(data[0] << 8 | data[1]);

        // Convert raw value to current
        current = convert_to_current(raw_value);

        // Update circular buffer
        sum -= buffer[buffer_index];
        buffer[buffer_index] = current;
        sum += current;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Check average current
        double average_current = sum / BUFFER_SIZE;
        if (average_current > CURRENT_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep to maintain sample rate
        usleep(1000000 / SAMPLE_RATE_HZ);
    }

    // Clean up
    gpiod_line_release(led_line);
    gpiod_chip_close(fd_led);
    i2c_put_adapter(adapter);

    return 0;
}

