#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <libgpiod.h>
#include "Adafruit_TCS34725.h"

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define SENSOR_ID 0x44
#define MAX_CONSECUTIVE_FAILURES 3

static volatile sig_atomic_t keep_running = 1;
static FILE *csv_file = NULL;
static int consecutive_failures = 0;
static Adafruit_TCS34725 tcs;

void handle_signal(int sig) {
    keep_running = 0;
}

void write_header() {
    fprintf(csv_file, "Timestamp,Clear,Red,Green,Blue\n");
    fflush(csv_file);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (tcs.begin(TCS34725_INTEGRATIONTIME_50MS, TCS34725_GAIN_4X) == false) {
        fprintf(stderr, "Failed to initialize the TCS34725 sensor\n");
        return EXIT_FAILURE;
    }

    uint8_t id = tcs.read8(TCS34725_ID);
    if (id != SENSOR_ID) {
        fprintf(stderr, "Unexpected sensor ID: 0x%02X\n", id);
        return EXIT_FAILURE;
    }

    if (access("color_log.csv", F_OK) == -1) {
        csv_file = fopen("color_log.csv", "w");
        if (!csv_file) {
            perror("Failed to create color_log.csv");
            return EXIT_FAILURE;
        }
        write_header();
    } else {
        csv_file = fopen("color_log.csv", "a");
        if (!csv_file) {
            perror("Failed to open color_log.csv");
            return EXIT_FAILURE;
        }
    }

    struct timespec sleep_time = {0, 300000000}; // 300ms

    while (keep_running) {
        usleep(3000); // Wait at least 3ms after power-on

        uint16_t clear, red, green, blue;
        if (tcs.getRawData(&red, &green, &blue, &clear) == false) {
            fprintf(stderr, "I2C read error\n");
            consecutive_failures++;
            if (consecutive_failures >= MAX_CONSECUTIVE_FAILURES) {
                break;
            }
        } else {
            consecutive_failures = 0;

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(csv_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
            fflush(csv_file);
        }

        nanosleep(&sleep_time, NULL);
    }

    if (csv_file) {
        fclose(csv_file);
    }

    tcs.begin(); // Cleanup

    return consecutive_failures >= MAX_CONSECUTIVE_FAILURES ? EXIT_FAILURE : EXIT_SUCCESS;
}

