#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define MCP3008_CHANNEL 0
#define MAX_SPI_RETRIES 3
#define CURRENT_THRESHOLD 10.0
#define MOTOR_CONTROL_GPIO 17
#define MOTOR_CONTROL_LINE "gpio17"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_spi_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    return fd;
}

int configure_spi(int fd) {
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(fd, SPI_IOC_RD_MODE, &mode) < 0 ||
        ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &bits) < 0 ||
        ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0 ||
        ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to configure SPI device");
        return -1;
    }
    return 0;
}

int read_adc(int fd, uint8_t channel, uint16_t *adc_value) {
    uint8_t tx[] = {0b11000000 | (channel << 4), 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; ++attempt) {
        if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("SPI transfer failed");
            if (attempt == MAX_SPI_RETRIES - 1) {
                return -1;
            }
            continue;
        }
        *adc_value = (rx[1] & 0x03) << 8 | rx[2];
        return 0;
    }
    return -1;
}

double adc_to_current(uint16_t adc_value) {
    // Assuming a 3.3V reference and 10-bit ADC resolution
    double voltage = (adc_value / 1023.0) * 3.3;
    // Assuming a 66mV/A sensitivity for the MLX91211
    return voltage / 0.066;
}

int setup_gpio(gpiod_line_handle_t *motor_control_line) {
    *motor_control_line = gpiod_chip_open("/dev/gpiochip0");
    if (!*motor_control_line) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    *motor_control_line = gpiod_line_request(*motor_control_line, MOTOR_CONTROL_LINE, GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    if (!*motor_control_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(*motor_control_line);
        return -1;
    }
    return 0;
}

void cleanup(int fd, gpiod_line_handle_t motor_control_line, FILE *log_file) {
    if (fd >= 0) {
        close(fd);
    }
    if (motor_control_line) {
        gpiod_line_release(motor_control_line);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int spi_fd = -1;
    gpiod_line_handle_t motor_control_line = NULL;
    FILE *log_file = NULL;
    uint16_t adc_value;
    double current;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    spi_fd = open_spi_device(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    if (configure_spi(spi_fd) < 0) {
        cleanup(spi_fd, motor_control_line, log_file);
        return EXIT_FAILURE;
    }

    if (setup_gpio(&motor_control_line) < 0) {
        cleanup(spi_fd, motor_control_line, log_file);
        return EXIT_FAILURE;
    }

    log_file = fopen("current_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(spi_fd, motor_control_line, log_file);
        return EXIT_FAILURE;
    }

    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
    }

    while (keep_running) {
        if (read_adc(spi_fd, MCP3008_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        current = adc_to_current(adc_value);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.3f\n", timestamp, current);
        fflush(log_file);

        if (current > CURRENT_THRESHOLD) {
            gpiod_line_set_value(motor_control_line, 0);
            fprintf(log_file, "%s,Overcurrent detected: %.3f A\n", timestamp, current);
            fflush(log_file);
            sleep(1);
            gpiod_line_set_value(motor_control_line, 1);
        }

        sleep(1);
    }

    cleanup(spi_fd, motor_control_line, log_file);
    return EXIT_SUCCESS;
}

