    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" PRIu32, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus", errno);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90817_I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address", errno);
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Read pressure register
        if (read(i2c_fd, buffer, MLX90817_PRESSURE_REGISTER_SIZE) != MLX90817_PRESSURE_REGISTER_SIZE) {
            log_error("Failed to read from I2C", errno);
            retries++;
            if (retries > max_retries) {
                fprintf(stderr, "Repeated I2C read failures, exiting\n");
                break;
            }
            sleep(1);
            continue;
        }
        retries = 0;

        // Convert pressure reading
        int16_t pressure_raw = (buffer[0] << 8) | buffer[1];
        float pressure_kPa = pressure_raw * 0.001;

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        struct tm *utc_time = gmtime(&ts.tv_sec);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

        // Log data
        fprintf(log_file, "%s,%.3f\n", timestamp, pressure_kPa);
        if (fflush(log_file) != 0) {
            perror("Failed to flush log file");
            break;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}
