#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_POINTER_CONVERT 0x00
#define ADS1115_REG_POINTER_CONFIG 0x01
#define ADS1115_REG_CONFIG_OS_SINGLE 0x8000
#define ADS1115_REG_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_REG_CONFIG_MUX_SINGLE_1 0x5000
#define ADS1115_REG_CONFIG_PGA_6_144V 0x0200
#define ADS1115_REG_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_REG_CONFIG_DR_860SPS 0x0080
#define ADS1115_REG_CONFIG_CQUE_NONE 0x0003
#define ADS1115_REG_CONFIG_GAIN_6_144V 0x0200
#define ADS1115_REG_CONFIG_GAIN_4_096V 0x0000
#define ADS1115_REG_CONFIG_GAIN_2_048V 0x0400
#define ADS1115_REG_CONFIG_GAIN_1_024V 0x0600
#define ADS1115_REG_CONFIG_GAIN_0_512V 0x0800
#define ADS1115_REG_CONFIG_GAIN_0_256V 0x0A00

#define LED_GPIO_CHIP "gpiochip0"
#define LED_GPIO_LINE 17

volatile sig_atomic_t stop = 0;

void handle_sigint(int sig) {
    stop = 1;
}

int read_adc(int fd, uint8_t config, int *value) {
    uint16_t data;
    int retries = 3;
    while (retries--) {
        if (ioctl(fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
            perror("Failed to set I2C address");
            return -1;
        }

        if (i2c_smbus_write_byte_data(fd, ADS1115_REG_POINTER_CONFIG, config) < 0) {
            perror("Failed to write config");
            continue;
        }

        usleep(10000); // Wait for conversion

        if (i2c_smbus_read_word_data(fd, ADS1115_REG_POINTER_CONVERT) < 0) {
            perror("Failed to read conversion");
            continue;
        }

        data = i2c_smbus_data;
        *value = (int16_t)data;
        return 0;
    }
    return -1;
}

int main() {
    int i2c_fd, led_fd;
    struct gpiod_line *led_line;
    int pressure_value, temp_value;
    float pressure_kPa, temperature_C;
    uint8_t config;

    signal(SIGINT, handle_sigint);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Open GPIO for LED
    led_fd = gpiod_chip_open_by_name(LED_GPIO_CHIP);
    if (led_fd < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(led_fd, LED_GPIO_LINE);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(led_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "pressure_warning", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(led_line);
        gpiod_chip_close(led_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure ADS1115 for AIN0 (pressure) and AIN1 (temperature)
    config = ADS1115_REG_CONFIG_OS_SINGLE | ADS1115_REG_CONFIG_MUX_SINGLE_0 |
             ADS1115_REG_CONFIG_PGA_6_144V | ADS1115_REG_CONFIG_MODE_SINGLE |
             ADS1115_REG_CONFIG_DR_860SPS | ADS1115_REG_CONFIG_CQUE_NONE;

    while (!stop) {
        // Read pressure from AIN0
        if (read_adc(i2c_fd, config, &pressure_value) < 0) {
            fprintf(stderr, "Failed to read pressure\n");
            continue;
        }
        pressure_kPa = (pressure_value * 6.144) / 32768.0; // Convert to kPa

        // Read temperature from AIN1
        config = ADS1115_REG_CONFIG_OS_SINGLE | ADS1115_REG_CONFIG_MUX_SINGLE_1 |
                 ADS1115_REG_CONFIG_PGA_6_144V | ADS1115_REG_CONFIG_MODE_SINGLE |
                 ADS1115_REG_CONFIG_DR_860SPS | ADS1115_REG_CONFIG_CQUE_NONE;

        if (read_adc(i2c_fd, config, &temp_value) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }
        temperature_C = (temp_value * 6.144) / 32768.0; // Convert to °C

        // Print values
        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure_kPa, temperature_C);

        // Drive LED if pressure exceeds 105.0 kPa
        if (pressure_kPa > 105.0) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        sleep(1);
    }

    // Clean up
    gpiod_line_release(led_line);
    gpiod_chip_close(led_fd);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

