#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define GPIO_CE 8
#define GPIO_SCLK 11
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_SHUTDOWN 27
#define CURRENT_THRESHOLD 10.0
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL 100

volatile sig_atomic_t terminate = 0;

void handle_signal(int sig) {
    terminate = 1;
}

int read_adc(int channel) {
    uint8_t buffer[3];
    int adc_value = 0;

    buffer[0] = 1 << 7 | (channel & 0x07) << 4 | 0x08;
    buffer[1] = 0x00;
    buffer[2] = 0x00;

    if (gpioSPIReadBuffer(SPI_CHANNEL, buffer, 3, buffer, 3) < 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    adc_value = ((buffer[1] & 0x03) << 8) | buffer[2];
    return adc_value;
}

double convert_adc_to_current(int adc_value) {
    // Assuming a 3.3V reference and 10-bit ADC
    double voltage = (adc_value / 1023.0) * 3.3;
    // Assuming a linear relationship for the sensor
    // Adjust the conversion factor based on the sensor's datasheet
    double current = voltage * 20.0; // Example conversion factor
    return current;
}

void log_current(double current) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(file, "%s: %f A\n", timestamp, current);
    fflush(file);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSPISetup(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_CE, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_SCLK, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_MOSI, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_MISO, PI_INPUT) < 0 ||
        gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Invalid ADC value\n");
            break;
        }

        double current = convert_adc_to_current(adc_value);
        log_current(current);

        if (current > CURRENT_THRESHOLD) {
            fprintf(stderr, "OVERCURRENT event\n");
            gpioWrite(GPIO_SHUTDOWN, 1);
            log_current(current);
            break;
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    gpioWrite(GPIO_SHUTDOWN, 0);
    gpioSPIClose(SPI_CHANNEL);
    gpioTerminate();

    return EXIT_SUCCESS;
}

