This code initializes the pigpio library, sets up the SPI interface, and reads the current sensor value every 100 ms. It logs the current with a timestamp and checks for overcurrent conditions. If an overcurrent is detected, it logs the event, sets GPIO27 high, and exits. The program also handles signals to clean up resources properly.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CE_PIN 8
#define ALARM_PIN 4
#define ADC_CHANNEL 0
#define VREF 3.3
#define THRESHOLD_VOLTAGE 2.5

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

void log_error(const char *message) {
    FILE *log_file = fopen("co_log.txt", "a");
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "%s,ERROR: %s\n", timestamp, message);
        fclose(log_file);
    }
}

void log_voltage(double voltage) {
    FILE *log_file = fopen("co_log.txt", "a");
    if (log_file) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage);
        fclose(log_file);
    }
}

int read_adc(int channel) {
    unsigned char buffer[3] = {0x01, (8 + channel) << 4, 0x00};
    unsigned char response[3];
    int result = pi_spi_xfer(SPI_CHANNEL, buffer, 3, response, 3);
    if (result < 0) {
        log_error("SPI transfer failed");
        return -1;
    }
    int adc_value = ((response[1] & 0x03) << 8) | response[2];
    return adc_value;
}

double calculate_voltage(int adc_value) {
    return (adc_value / 1023.0) * VREF;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(CE_PIN, PI_OUTPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, PI_LOW);
}

void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    while (!stop) {
        gpioWrite(CE_PIN, PI_LOW);
        int adc_value = read_adc(ADC_CHANNEL);
        gpioWrite(CE_PIN, PI_HIGH);

        if (adc_value >= 0) {
            double voltage = calculate_voltage(adc_value);
            log_voltage(voltage);
            gpioWrite(ALARM_PIN, voltage > THRESHOLD_VOLTAGE ? PI_HIGH : PI_LOW);
        } else {
            sleep(1); // Wait before retrying
        }
        sleep(1); // Sample once per second
    }

    // Cleanup
    gpioWrite(ALARM_PIN, PI_LOW);
    cleanup_gpio();

    return 0;
}

