#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_6_144V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

#define MLX90830_MIN_PRESSURE 0.0
#define MLX90830_MAX_PRESSURE 100.0

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return -1;
    }
    if (gpioI2CSetup(1, ADS1115_ADDRESS) < 0) {
        fprintf(stderr, "Failed to setup I2C: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }
    return 0;
}

int read_adc() {
    uint16_t data;
    if (gpioI2CReadReg16(1, ADS1115_REG_CONVERSION, &data) < 0) {
        fprintf(stderr, "Failed to read ADC: %s\n", strerror(errno));
        return -1;
    }
    return data;
}

double convert_to_pressure(uint16_t adc_value) {
    // Assuming a linear conversion for simplicity
    // Adjust the conversion formula based on the actual sensor characteristics
    double voltage = adc_value * (6.144 / 32767.0);
    double pressure = (voltage / 5.0) * 100.0; // Example conversion
    return pressure;
}

void log_pressure(double pressure) {
    FILE *file = fopen("pressure_log.txt", "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(file, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(file);
}

int main() {
    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        return EXIT_FAILURE;
    }

    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 |
                      ADS1115_CONFIG_PGA_6_144V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    if (gpioI2CWriteReg16(1, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Failed to configure ADC: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (read_adc() < 0) {
            break;
        }

        uint16_t adc_value = read_adc();
        double pressure = convert_to_pressure(adc_value);

        if (pressure >= MLX90830_MIN_PRESSURE && pressure <= MLX90830_MAX_PRESSURE) {
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
        }

        sleep(1);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

