#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define MCP3208_CS_PIN 8
#define MCP3208_SPI_CHANNEL 0
#define MCP3208_SPI_SPEED 1000000
#define HUMIDITY_THRESHOLD 80.0

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return -1;
    }
    if (gpioSetMode(MCP3208_CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(MCP3208_CS_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO pin high: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }
    return 0;
}

int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    if (gpioSPIDataRW(MCP3208_SPI_CHANNEL, tx, len) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    memcpy(rx, tx, len);
    return 0;
}

double read_adc_channel(int channel) {
    uint8_t tx[3] = {0x00, 0x00, 0x00};
    uint8_t rx[3] = {0x00, 0x00, 0x00};
    int adc_value = 0;

    tx[1] = 0b11 << 6 | channel << 3 | 0b10;
    if (spi_transfer(tx, rx, 3) < 0) {
        return -1.0;
    }

    adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value * 3.3 / 4096.0;
}

double read_humidity() {
    double voltage = read_adc_channel(0);
    if (voltage < 0) {
        fprintf(stderr, "Failed to read humidity sensor\n");
        return -1.0;
    }
    return (voltage - 0.96) / 0.006; // Example conversion formula
}

double read_temperature() {
    double voltage = read_adc_channel(1);
    if (voltage < 0) {
        fprintf(stderr, "Failed to read temperature sensor\n");
        return -1.0;
    }
    return (voltage - 0.5) / 0.01; // Example conversion formula
}

void log_reading(double humidity, double temperature) {
    FILE *file = fopen("humidity_log.txt", "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    if (fprintf(file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    }

    fclose(file);
}

void send_email_alert(double humidity) {
    FILE *mail = popen("ssmtp user@example.com", "w");
    if (!mail) {
        fprintf(stderr, "Failed to open ssmtp: %s\n", strerror(errno));
        return;
    }

    if (fprintf(mail, "Subject: Humidity Alert\n\nHumidity level exceeded threshold: %.2f%%\n", humidity) < 0) {
        fprintf(stderr, "Failed to write to ssmtp: %s\n", strerror(errno));
    }

    pclose(mail);
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR || signal(SIGTERM, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    while (keep_running) {
        double humidity = read_humidity();
        double temperature = read_temperature();

        if (humidity >= 0 && temperature >= 0) {
            log_reading(humidity, temperature);
            if (humidity > HUMIDITY_THRESHOLD) {
                send_email_alert(humidity);
            }
        }

        sleep(1);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

