#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define TMP36_VREF 3.3
#define TMP36_VOUT_MAX 1.25
#define TMP36_VOUT_MIN 0.0
#define TMP36_OFFSET 500.0
#define TMP36_SCALE 10.0
#define TMP36_MIN_TEMP -40.0
#define TMP36_MAX_TEMP 125.0

#define MCP3208_CMD_SINGLE_ENDED 0x01
#define MCP3208_CHANNEL 0x00

static int spi_fd = -1;
static int gpio_fd = -1;
static int log_fd = -1;
static struct timespec last_conversion_time = {0, 0};

void cleanup_and_exit(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_fd >= 0) {
        gpiod_line_release(gpio_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
    exit(0);
}

int setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "CE0", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpio_fd = gpiod_line_get_fd(line);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

int setup_spi() {
    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret == -1) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret == -1) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret == -1) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_adc() {
    uint8_t tx[] = {MCP3208_CMD_SINGLE_ENDED | (MCP3208_CHANNEL << 4), 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Failed to perform SPI transfer");
        return -1;
    }

    int adc_value = ((rx[1] & 0x0F) << 8) | rx[2];
    return adc_value;
}

double convert_to_celsius(int adc_value) {
    double voltage = (adc_value / 4095.0) * TMP36_VREF;
    double temperature = (voltage - TMP36_VOUT_MIN) * TMP36_SCALE - TMP36_OFFSET;
    return temperature;
}

void log_temperature(double temperature) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);

    if (log_fd < 0) {
        log_fd = open("temperature_log.csv", O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_fd < 0) {
            perror("Failed to open log file");
            return;
        }

        dprintf(log_fd, "timestamp,temperature_celsius\n");
    }

    dprintf(log_fd, "%ld.%09ld,%f\n", now.tv_sec, now.tv_nsec, temperature);
}

int main() {
    if (setup_gpio() < 0 || setup_spi() < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    while (1) {
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);

        if (last_conversion_time.tv_sec == 0 || now.tv_sec - last_conversion_time.tv_sec >= 1) {
            int adc_value = read_adc();
            if (adc_value < 0) {
                fprintf(stderr, "Sensor absent or error reading ADC\n");
                continue;
            }

            double temperature = convert_to_celsius(adc_value);
            if (temperature < TMP36_MIN_TEMP || temperature > TMP36_MAX_TEMP) {
                fprintf(stderr, "Temperature out of range: %f\n", temperature);
                continue;
            }

            log_temperature(temperature);
            last_conversion_time = now;
        }

        nanosleep(&((struct timespec){1, 0}), NULL);
    }

    cleanup_and_exit(0);
    return EXIT_SUCCESS;
}

