#define ADC_MAX_VALUE 1023
#define SAMPLE_RATE_HZ 100
#define IMPACT_THRESHOLD 500

static int spi_fd = -1;
static int cs_fd = -1;
static FILE *log_file = NULL;
static int impact_threshold = IMPACT_THRESHOLD;

void cleanup_and_exit(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (cs_fd != -1) {
        gpiod_line_release(cs_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int setup_gpio() {
    cs_fd = gpiod_chip_open("/dev/gpiochip0");
    if (cs_fd < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    struct gpiod_line_request req = {
        .consumer = "ADXL335_SPI_CS",
        .type = GPIOD_LINE_REQ_DIR_OUT,
        .flags = GPIOD_LINE_REQUEST_DIRECTIONS,
    };

    cs_fd = gpiod_line_request_by_offset(cs_fd, 8, &req);
    if (cs_fd < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(cs_fd);
        return -1;
    }

    gpiod_line_set_value(cs_fd, 1);
    return 0;
}

int setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_adc(uint8_t channel) {
    uint8_t tx[] = {0x01, (8 + channel) << 4, 0x00};
    uint8_t rx[3] = {0};

    gpiod_line_set_value(cs_fd, 0);
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx) < 0) {
        perror("SPI transfer failed");
        gpiod_line_set_value(cs_fd, 1);
        return -1;
    }
    gpiod_line_set_value(cs_fd, 1);

    uint16_t adc_value = (rx[1] & 0x03) << 8 | rx[2];
    return adc_value;
}

void log_data(int x, int y, int z) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, %d, %d, %d\n", time_str, x, y, z);

    if (x > impact_threshold || y > impact_threshold || z > impact_threshold) {
        fprintf(log_file, "IMPACT DETECTED\n");
    }
}

