    if (signal(SIGINT, cleanup_and_exit) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0 || setup_spi() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("impact_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup_and_exit(0);
    }

    while (1) {
        int x = read_adc(0);
        int y = read_adc(1);
        int z = read_adc(2);

        if (x < 0 || y < 0 || z < 0 || x > ADC_MAX_VALUE || y > ADC_MAX_VALUE || z > ADC_MAX_VALUE) {
            fprintf(stderr, "Invalid ADC read\n");
            continue;
        }

        log_data(x, y, z);
        usleep(1000000 / SAMPLE_RATE_HZ);
    }

    cleanup_and_exit(0);
    return EXIT_SUCCESS;
}

