#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED_HZ 1000000
#define ADC_CHANNEL 0
#define LOG_FILE "flow_log.csv"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_spi_device(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode_reg = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_reg) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &mode_reg) < 0) {
        perror("Failed to get SPI mode");
        close(fd);
        return -1;
    }

    uint8_t bits_reg = bits;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_reg) < 0) {
        perror("Failed to set bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &bits_reg) < 0) {
        perror("Failed to get bits per word");
        close(fd);
        return -1;
    }

    uint32_t speed_reg = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_reg) < 0) {
        perror("Failed to set max speed");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed_reg) < 0) {
        perror("Failed to get max speed");
        close(fd);
        return -1;
    }

    return fd;
}

int read_adc(int fd, uint8_t channel, uint16_t *adc_value) {
    uint8_t tx[] = {0x01, (8 + channel) << 4, 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to perform SPI transfer");
        return -1;
    }

    *adc_value = (rx[1] & 0x03) << 8 | rx[2];
    return 0;
}

double convert_adc_to_flow_rate(uint16_t adc_value) {
    if (adc_value == 0 || adc_value == 0x3FF) {
        fprintf(stderr, "Sensor absent condition detected\n");
        return -1.0;
    }

    double voltage = (adc_value / 1023.0) * 3.3;
    double flow_rate = (voltage - 0.2) / 0.04 * 5.0;
    return flow_rate;
}

void log_flow_rate(double flow_rate, FILE *log_file) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("Failed to get time");
        return;
    }

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    fprintf(log_file, "%s.%06ld,%f\n", timestamp, ts.tv_nsec / 1000, flow_rate);
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int spi_fd = open_spi_device(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED_HZ);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint16_t adc_value;
        if (read_adc(spi_fd, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Error reading ADC\n");
            continue;
        }

        double flow_rate = convert_adc_to_flow_rate(adc_value);
        if (flow_rate < 0.0 || flow_rate > 5.0) {
            fprintf(stderr, "Out-of-range flow rate: %f L/min\n", flow_rate);
            continue;
        }

        log_flow_rate(flow_rate, log_file);
        usleep(1000000); // Sleep for 1 second
    }

    fclose(log_file);
    close(spi_fd);
    return EXIT_SUCCESS;
}

