#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <gpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CS_PIN 8
#define MCP3008_DOUT_PIN 7
#define MCP3008_DIN_PIN 11
#define MCP3008_CLK_PIN 10

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }
    return 0;
}

int setup_spi() {
    if (gpioSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        return -1;
    }
    return 0;
}

int read_adc(int channel) {
    unsigned char buffer[3];
    buffer[0] = 1; // Start bit
    buffer[1] = (8 + channel) << 4; // Single-ended bit + channel
    buffer[2] = 0; // Don't care

    if (gpioSPIDataRW(SPI_CHANNEL, buffer, 3) < 0) {
        fprintf(stderr, "SPI data read/write failed\n");
        return -1;
    }

    int adc_value = ((buffer[1] & 3) << 8) | buffer[2];
    return adc_value;
}

void cleanup() {
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain1> <gain2>\n", argv[0]);
        return EXIT_FAILURE;
    }

    float gain1 = atof(argv[1]);
    float gain2 = atof(argv[2]);

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (setup_spi() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        int adc_value1 = read_adc(0);
        int adc_value2 = read_adc(1);

        if (adc_value1 < 0 || adc_value2 < 0) {
            fprintf(stderr, "Error reading ADC values\n");
            break;
        }

        int noise_cancellation = (int)(adc_value1 * gain1 - adc_value2 * gain2);
        printf("%d,%d,%d\n", adc_value1, adc_value2, noise_cancellation);

        usleep(100000); // 100 ms delay
    }

    cleanup();
    return EXIT_SUCCESS;
}

