#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define MCP3008_CHANNEL 0
#define BUZZER_GPIO 18
#define LOG_FILE "flame_log.txt"
#define TEMP_FILE "ambient_temp.txt"
#define SAMPLE_INTERVAL 500000 // 500 ms in microseconds

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int open_spi_device(const char *device, uint8_t mode, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }

    uint8_t mode_reg = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_reg) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

int read_adc(int fd, uint8_t channel, uint16_t *adc_value) {
    uint8_t tx[] = {0x01, (0x08 | (channel << 4)), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((uint16_t)rx[1] & 0x0F) << 8 | rx[2];
    return 0;
}

double read_ambient_temperature() {
    FILE *file = fopen(TEMP_FILE, "r");
    if (!file) {
        return 25.0;
    }

    double temp;
    if (fscanf(file, "%lf", &temp) != 1) {
        fclose(file);
        return 25.0;
    }

    fclose(file);
    return temp;
}

void log_flame_detection(FILE *log_file, time_t raw_time, uint16_t raw_adc, double voltage, double compensated_voltage, double temperature, int flame_detected) {
    char time_str[20];
    struct tm *time_info = localtime(&raw_time);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(log_file, "%s,%u,%f,%f,%f,%d\n", time_str, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_sigint);

    int spi_fd = open_spi_device(SPI_DEVICE, SPI_MODE, SPI_SPEED);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line\n");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line\n");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    double ambient_temp = read_ambient_temperature();

    while (keep_running) {
        uint16_t adc_value = 0;
        int retries = 3;
        int success = 0;

        while (retries-- > 0 && !success) {
            if (read_adc(spi_fd, MCP3008_CHANNEL, &adc_value) == 0) {
                if (adc_value >= 0 && adc_value <= 1023) {
                    success = 1;
                } else {
                    fprintf(stderr, "ADC value out of range: %u\n", adc_value);
                }
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read ADC value after retries\n");
            gpiod_line_set_value(buzzer_line, 0);
            usleep(SAMPLE_INTERVAL);
            continue;
        }

        double voltage = (adc_value / 1023.0) * 3.3;
        double compensated_voltage = voltage * (1 + 0.01 * (ambient_temp - 25.0));
        int flame_detected = (voltage > 1.0); // Example threshold

        gpiod_line_set_value(buzzer_line, flame_detected);

        time_t raw_time = time(NULL);
        log_flame_detection(log_file, raw_time, adc_value, voltage, compensated_voltage, ambient_temp, flame_detected);

        usleep(SAMPLE_INTERVAL);
    }

    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(spi_fd);

    return EXIT_SUCCESS;
}

