#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS 8
#define LED_PIN 17
#define READ_INTERVAL 5
#define HYSTERESIS_HIGH 75
#define HYSTERESIS_LOW 70

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        return -1;
    }
    if (gpioSetMode(SPI_CS, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI CS pin mode\n");
        return -1;
    }
    return 0;
}

int setup_spi() {
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return -1;
    }
    if (gpioSetPullUpDown(SPI_CS, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set SPI CS pull-up/down\n");
        return -1;
    }
    return spi_handle;
}

int read_adc(int spi_handle) {
    unsigned char tx[] = {1, 0x8C, 0x00};
    unsigned char rx[3] = {0};
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }
    int adc_value = ((rx[1] & 3) << 8) | rx[2];
    return adc_value;
}

double calculate_percentage(int adc_value) {
    return (adc_value / 1023.0) * 100.0;
}

void write_json_entry(FILE *file, double percentage) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "\"%Y-%m-%dT%H:%M:%S", tm_info);
    strncat(timestamp, ".", sizeof(timestamp) - strlen(timestamp) - 1);
    char ms[4];
    snprintf(ms, sizeof(ms), "%03ld\"", (long) (1000.0 * (now - (time_t)tm_info)));
    fprintf(file, "{\"timestamp\": %s%s, \"percentage\": %.2f},\n", timestamp, ms, percentage);
    fflush(file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    int spi_handle = setup_spi();
    if (spi_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *file = fopen("water_levels.json", "w");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(file, "[\n");
    fflush(file);

    int last_led_state = 0;
    while (keep_running) {
        int adc_value = read_adc(spi_handle);
        if (adc_value < 0) {
            continue;
        }

        double percentage = calculate_percentage(adc_value);
        printf("Water level: %.2f%%\n", percentage);

        write_json_entry(file, percentage);

        int led_state = (percentage > HYSTERESIS_HIGH) ? 1 : (percentage < HYSTERESIS_LOW) ? 0 : last_led_state;
        if (led_state != last_led_state) {
            gpioWrite(LED_PIN, led_state);
            last_led_state = led_state;
        }

        for (int i = 0; i < READ_INTERVAL * 10; i++) {
            if (!keep_running) break;
            usleep(100000);
        }
    }

    fprintf(file, "\n]");
    fclose(file);

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();

