#include <gpiod.h>
#include <sys/wait.h>

#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 500000

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int spi_init(const char *device, int *fd) {
    *fd = open(device, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0 ||
        ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) < 0) {
        fprintf(stderr, "Failed to set SPI parameters: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int read_adc(int spi_fd, int adc_channel, int *value) {
    uint8_t tx[] = {1 << 7 | (adc_channel & 0x07), 0};
    uint8_t rx[3] = {0};

    if (spi_transfer(spi_fd, tx, rx, sizeof(tx)) < 0) {
        return -1;
    }

    *value = ((int)rx[1] & 0x03) << 8 | rx[2];
    return 0;
}

void log_moisture(const char *filename, const char *timestamp, int moisture_percent) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%s, %d\n", timestamp, moisture_percent);
    fclose(file);
}

void send_email(const char *msmtp_config, const char *recipient, int moisture_percent) {
    char command[256];
    snprintf(command, sizeof(command), "msmtp -C %s -t %s", msmtp_config, recipient);

    FILE *fp = popen(command, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open pipe to msmtp: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "Subject: Plant Moisture Alert\n\n");
    fprintf(fp, "The plant moisture level is critically low: %d%%\n", moisture_percent);
    pclose(fp);

    int status;
    waitpid(-1, &status, 0);
    if (WEXITSTATUS(status) != 0) {
        fprintf(stderr, "msmtp failed with status %d\n", WEXITSTATUS(status));
    }
}

int main(int argc, char *argv[]) {
    if (argc != 9) {
        fprintf(stderr, "Usage: %s <spi_channel> <adc_channel> <min_value> <max_value> <threshold> <interval> <recipient> <msmtp_config>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int spi_channel = atoi(argv[1]);
    int adc_channel = atoi(argv[2]);
    int min_value = atoi(argv[3]);
    int max_value = atoi(argv[4]);
    int threshold = atoi(argv[5]);
    int interval = atoi(argv[6]);
    const char *recipient = argv[7];
    const char *msmtp_config = argv[8];

    if (min_value >= max_value) {
        fprintf(stderr, "Invalid calibration values: min_value >= max_value\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    char spi_device[64];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev0.%d", spi_channel);

    int spi_fd;
    if (spi_init(spi_device, &spi_fd) < 0) {
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int adc_value;
        if (read_adc(spi_fd, adc_channel, &adc_value) < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            sleep(1);
            continue;
        }

        int moisture_percent = (adc_value - min_value) * 100 / (max_value - min_value);
        if (moisture_percent < 0) moisture_percent = 0;
        if (moisture_percent > 100) moisture_percent = 100;

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        log_moisture("plant_data.txt", timestamp, moisture_percent);

        if (moisture_percent < threshold) {
            send_email(msmtp_config, recipient, moisture_percent);
        }

        sleep(interval);
    }

    close(spi_fd);
    return EXIT_SUCCESS;
}

