#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8

#define MCP3008_CHANNEL 0
#define MCP3008_DUMMY 0x00
#define MCP3008_START 0x01
#define MCP3008_SINGLE_ENDED 0x80

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_spi_device(const char *device, uint32_t speed, uint8_t mode) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode_reg = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_reg) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

int read_adc(int spi_fd, uint8_t channel) {
    uint8_t tx[] = {MCP3008_START | (channel << 4) | MCP3008_SINGLE_ENDED, MCP3008_DUMMY};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    uint16_t adc_value = (rx[1] & 0x03) << 8 | rx[2];
    return adc_value;
}

void log_moisture(int log_fd, uint16_t adc_value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    uint8_t moisture_percentage = (adc_value * 100) / 1023;
    dprintf(log_fd, "%s, %u, %u%%\n", timestamp, adc_value, moisture_percentage);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int interval = 1;
    if (argc > 1) {
        interval = atoi(argv[1]);
        if (interval <= 0) {
            fprintf(stderr, "Invalid interval. Using default 1 second.\n");
            interval = 1;
        }
    }

    int spi_fd = open_spi_device(SPI_DEVICE, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    int log_fd = open("soil_moisture.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int adc_value = read_adc(spi_fd, MCP3008_CHANNEL);
        if (adc_value >= 0) {
            log_moisture(log_fd, adc_value);
        } else {
