#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_MAX_VALUE 1023
#define ADC_REF_VOLTAGE 3.3
#define PRESSURE_SENSOR_MAX_VOLTAGE 3.3
#define PRESSURE_SENSOR_MIN_VOLTAGE 0.0
#define PRESSURE_SENSOR_MAX_PRESSURE 100.0 // Example max pressure in kPa
#define PRESSURE_SENSOR_MIN_PRESSURE 0.0   // Example min pressure in kPa

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return -1;
    }
    return 0;
}

int setup_spi() {
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return -1;
    }
    return spi_handle;
}

int read_adc(int spi_handle, int channel) {
    uint8_t tx_buffer[3] = {0x01, (8 + channel) << 4, 0x00};
    uint8_t rx_buffer[3] = {0};

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

double convert_adc_to_voltage(int adc_value) {
    return (adc_value / (double)ADC_MAX_VALUE) * ADC_REF_VOLTAGE;
}

double convert_voltage_to_pressure(double voltage) {
    if (voltage <= PRESSURE_SENSOR_MIN_VOLTAGE || voltage >= PRESSURE_SENSOR_MAX_VOLTAGE) {
        return NAN; // Sensor absent condition
    }
    return ((voltage / PRESSURE_SENSOR_MAX_VOLTAGE) * (PRESSURE_SENSOR_MAX_PRESSURE - PRESSURE_SENSOR_MIN_PRESSURE)) + PRESSURE_SENSOR_MIN_PRESSURE;
}

void log_reading(double pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    if (isnan(pressure)) {
        printf("%s - Sensor absent (voltage out of range)\n", timestamp);
    } else {
        printf("%s - Pressure: %.2f kPa\n", timestamp, pressure);
    }
}

int main() {
    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int spi_handle = setup_spi();
    if (spi_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int adc_value = read_adc(spi_handle, 0);
        if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
            fprintf(stderr, "ADC value out of range: %d\n", adc_value);
            continue;
        }

        double voltage = convert_adc_to_voltage(adc_value);
        double pressure = convert_voltage_to_pressure(voltage);
        log_reading(pressure);

        sleep(1);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

