#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define GPIO_CE0 8

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_spi_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        return -1;
    }
    return fd;
}

int configure_spi(int fd) {
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(fd, SPI_IOC_RD_MODE, &mode) < 0 ||
        ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &bits) < 0 ||
        ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0 ||
        ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) < 0) {
        syslog(LOG_ERR, "Failed to configure SPI device: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int read_adc(int fd, uint8_t channel, uint16_t *adc_value) {
    uint8_t tx[] = {0b11000000 | (channel << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    *adc_value = (rx[1] & 0x03) << 8 | rx[2];
    return 0;
}

void log_reading(uint16_t adc_value) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    if (adc_value == 0 || adc_value == 1023) {
        syslog(LOG_WARNING, "[%s] ADC value stuck at %u: Possible sensor-absent or wiring fault", timestamp, adc_value);
    } else {
        syslog(LOG_INFO, "[%s] ADC value: %u", timestamp, adc_value);
    }
}

int main() {
    openlog("soil_moisture_sensor", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int fd = open_spi_device(SPI_DEVICE);
    if (fd < 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (configure_spi(fd) < 0) {
        close(fd);
        closelog();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint16_t adc_value;
        if (read_adc(fd, 0, &adc_value) < 0) {
            close(fd);
            closelog();
            return EXIT_FAILURE;
        }
        log_reading(adc_value);
        sleep(5);
    }

    close(fd);
    closelog();
    return EXIT_SUCCESS;
}

