        syslog(LOG_WARNING, "[%s] ADC value stuck at %u: Possible sensor-absent or wiring fault", timestamp, adc_value);
    } else {
        syslog(LOG_INFO, "[%s] ADC value: %u", timestamp, adc_value);
    }
}

int main() {
    openlog("soil_moisture_sensor", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int fd = open_spi_device(SPI_DEVICE);
    if (fd < 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (configure_spi(fd) < 0) {
        close(fd);
        closelog();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint16_t adc_value;
        if (read_adc(fd, 0, &adc_value) < 0) {
            close(fd);
            closelog();
            return EXIT_FAILURE;
        }
        log_reading(adc_value);
        sleep(5);
    }

    close(fd);
    closelog();
    return EXIT_SUCCESS;
}
