#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define MCP3008_CHANNEL_COUNT 4
#define MCP3008_DUMMY_BYTES 3
#define MCP3008_SINGLE_ENDED 0x01
#define MCP3008_START_BIT 0x18

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_spi_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    return fd;
}

int configure_spi(int fd) {
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(fd, SPI_IOC_RD_MODE, &mode) < 0 ||
        ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &bits) < 0 ||
        ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0 ||
        ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to configure SPI device");
        return -1;
    }
    return 0;
}

int read_adc(int fd, uint8_t channel) {
    uint8_t tx[] = {MCP3008_START_BIT | (MCP3008_SINGLE_ENDED << 4) | (channel & 0x07), 0x00, 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    uint16_t result = ((rx[1] & 0x03) << 8) | rx[2];
    return result;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int spi_fd = open_spi_device(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    if (configure_spi(spi_fd) < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *file = fopen("environmental_data.csv", "w");
    if (!file) {
        perror("Failed to open file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fprintf(file, "Timestamp,Channel 0,Channel 1,Channel 2,Channel 3\n");

    while (keep_running) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        int values[MCP3008_CHANNEL_COUNT];
        for (int i = 0; i < MCP3008_CHANNEL_COUNT; i++) {
            int adc_value = read_adc(spi_fd, i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading ADC channel %d\n", i);
                values[i] = -1;
            } else {
                values[i] = (adc_value * 3.3) / 1023.0; // Convert to voltage
            }
        }

        fprintf(file, "%s,%f,%f,%f,%f\n", timestamp, values[0], values[1], values[2], values[3]);
        fflush(file);

        sleep(1);
    }

    fclose(file);
    close(spi_fd);

    return EXIT_SUCCESS;
}

