#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>
#include <sys/time.h>

#define MCP3008_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BUS 0
#define SPI_CS_PIN 0
#define PUMP_PIN 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define BUFFER_SIZE 20

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int log_index = 0;
int pump_state = 0;
int running = 1;

void handle_signal(int sig) {
    running = 0;
}

int read_mcp3008(int channel) {
    unsigned char tx[] = {0b11000000 | (channel << 4), 0, 0};
    unsigned char rx[3] = {0};

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 1) {
        perror("SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx[1] & 3) << 8) | rx[2];
    return adc_value;
}

void log_entry(int moisture_level) {
    log_buffer[log_index].timestamp = time(NULL);
    log_buffer[log_index].moisture_level = moisture_level;
    log_buffer[log_index].pump_state = pump_state;
    log_index = (log_index + 1) % BUFFER_SIZE;
}

void print_log_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        struct tm *timeinfo = localtime(&log_buffer[i].timestamp);
        printf("%02d:%02d:%02d - Moisture: %d, Pump: %d\n",
               timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
               log_buffer[i].moisture_level, log_buffer[i].pump_state);
    }
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(PUMP_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void setup_spi() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    spi_transfer.tx_buf = (unsigned long)tx;
    spi_transfer.rx_buf = (unsigned long)rx;
    spi_transfer.len = 3;
    spi_transfer.delay_usecs = 0;
    spi_transfer.speed_hz = SPI_SPEED;
    spi_transfer.bits_per_word = 8;
    spi_transfer.cs_change = 0;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_transfer.bits_per_word) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_transfer.speed_hz) < 0) {
        perror("Failed to set SPI parameters");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    gpioWrite(PUMP_PIN, 0);
    gpioTerminate();
    close(spi_fd);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    setup_gpio();
    setup_spi();

    while (running) {
        int moisture_level = read_mcp3008(MCP3008_CHANNEL);
        if (moisture_level < 0) {
            continue;
        }

        if (moisture_level < LOW_THRESHOLD && !pump_state) {
            gpioWrite(PUMP_PIN, 1);
            pump_state = 1;
        } else if (moisture_level > HIGH_THRESHOLD && pump_state) {
            gpioWrite(PUMP_PIN, 0);
            pump_state = 0;
        }

        log_entry(moisture_level);
        print_log_buffer();

        sleep(5);
    }

    cleanup();
    return 0;
}

