        } else if (moisture_level > HIGH_THRESHOLD && pump_state) {
            gpioWrite(PUMP_PIN, 0);
            pump_state = 0;
        }

        log_entry(moisture_level);
        print_log_buffer();

        sleep(5);
    }

    cleanup();
    return 0;
