#define I2C_BUS "/dev/i2c-1"
#define MAX30102_ADDRESS 0x57
#define PART_ID_REG 0x00
#define PART_ID_EXPECTED 0x1D
#define SPO2_REG 0x5F
#define HEARTRATE_REG 0x5D
#define LOG_FILE "health_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_error(const char *message) {
    FILE *log = fopen(ERROR_LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s: %s\n", message, strerror(errno));
        fclose(log);
    } else {
        fprintf(stderr, "Failed to open error log file: %s\n", strerror(errno));
    }
}

void log_health(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s\n", message);
        fclose(log);
    } else {
        fprintf(stderr, "Failed to open health log file: %s\n", strerror(errno));
    }
}

int read_i2c_register(int fd, uint8_t reg, uint8_t *value) {
    uint8_t buffer[2] = {reg, 0};
    if (write(fd, buffer, 1) != 1) {
        log_error("Failed to write register address");
        return -1;
    }
    if (read(fd, buffer, 1) != 1) {
        log_error("Failed to read register value");
        return -1;
    }
    *value = buffer[0];
    return 0;
}

int verify_sensor(int fd) {
    uint8_t part_id;
    if (read_i2c_register(fd, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Failed to read Part ID register\n");
        return -1;
    }
    if (part_id != PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X\n", part_id);
        return -1;
    }
    return 0;
}

int main() {
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MAX30102_ADDRESS) < 0) {
        log_error("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (verify_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Sensor verification failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        uint8_t spo2, heartrate;
        if (read_i2c_register(i2c_fd, SPO2_REG, &spo2) != 0 || read_i2c_register(i2c_fd, HEARTRATE_REG, &heartrate) != 0) {
            log_error("Failed to read SpO2 or heart rate");
            break;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        if (spo2 < 95) {
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "%s: SpO2 reading below 95%%: %d%%", timestamp, spo2);
            log_health(log_message);
        }

        if (heartrate > 100) {
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "%s: Heart rate above 100 BPM: %d BPM", timestamp, heartrate);
            log_health(log_message);
        }

        sleep(1);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

