#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <syslog.h>
#include <errno.h>

#define SPI_BUS 0
#define SPI_CS_PIN 8
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL_MASK 0x07
#define MCP3008_SINGLE_ENDED 0x01
#define MCP3008_DUMMY_BYTE 0x00
#define MCP3008_START_BIT 0x18
#define MCP3008_READ_BIT 0x01
#define MCP3008_MAX_RETRIES 3
#define LOG_FILE "analog_log.csv"
#define INTERVAL_MS 500

static volatile sig_atomic_t keep_running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

void handle_sigint(int sig) {
    keep_running = 0;
}

int setup_spi() {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)&MCP3008_DUMMY_BYTE,
        .rx_buf = (unsigned long)&MCP3008_DUMMY_BYTE,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode or speed: %s", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_mcp3008(int channel) {
    unsigned char tx[3] = {
        MCP3008_START_BIT | (MCP3008_SINGLE_ENDED << 4) | (channel & MCP3008_CHANNEL_MASK),
        MCP3008_DUMMY_BYTE,
        MCP3008_DUMMY_BYTE
    };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    for (int attempt = 0; attempt < MCP3008_MAX_RETRIES; ++attempt) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
            syslog(LOG_WARNING, "SPI communication error on attempt %d: %s", attempt + 1, strerror(errno));
            continue;
        }

        int result = ((rx[1] & 3) << 8) | rx[2];
        if (result < 0) {
            syslog(LOG_WARNING, "Invalid MCP3008 result: %d", result);
            continue;
        }

        return result;
    }

    syslog(LOG_ERR, "Failed to read MCP3008 after %d attempts", MCP3008_MAX_RETRIES);
    return -1;
}

void log_voltage(int channel, int raw_value) {
    if (raw_value < 0) {
        fprintf(log_file, "%s,Channel %d,Error\n", get_timestamp(), channel);
    } else {
        float voltage = (raw_value * 3.3) / 1023.0;
        fprintf(log_file, "%s,Channel %d,%.4f\n", get_timestamp(), channel, voltage);
    }
    fflush(log_file);
}

const char *get_timestamp() {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    static char buffer[20];
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", tm_info);
    return buffer;
}

int main() {
    openlog("analog_reader", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_sigint);

    if (setup_spi() != 0) {
        syslog(LOG_ERR, "SPI setup failed");
        closelog();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        close(spi_fd);
        closelog();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Channel,Voltage\n");
    fflush(log_file);

    while (keep_running) {
        for (int channel = 0; channel < 3; ++channel) {
            int raw_value = read_mcp3008(channel);
            log_voltage(channel, raw_value);
        }
        usleep(INTERVAL_MS * 1000);
    }

    fclose(log_file);
    close(spi_fd);
    closelog();
    return EXIT_SUCCESS;
}

