#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <string.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_CHANNEL 0
#define GPIO_BUZZER 24
#define GPIO_THRESHOLD 500

static int spi_fd = -1;
static struct gpiod_line *buzzer_line = NULL;

void cleanup() {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
}

int setup_spi() {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)0,
        .rx_buf = (unsigned long)malloc(3),
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 1,
        .tx_nbits = 0,
        .rx_nbits = 8 * 3
    };

    if (transfer.rx_buf == NULL) {
        fprintf(stderr, "Failed to allocate memory for SPI transfer\n");
        return -1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        free(transfer.rx_buf);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI parameters");
        close(spi_fd);
        spi_fd = -1;
        free(transfer.rx_buf);
        return -1;
    }

    return 0;
}

int read_adc(uint8_t channel) {
    uint8_t tx[] = {0x01, (8 + channel) << 4, 0x00};
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)tx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 1,
        .tx_nbits = 8 * 3,
        .rx_nbits = 8 * 3
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Failed to read from SPI device");
        return -1;
    }

    int value = ((tx[1] & 3) << 8) | tx[2];
    return value;
}

int setup_gpio() {
    buzzer_line = gpiod_line_request(GPIO_BUZZER, "buzzer", GPIOD_OUT_LOW);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        return -1;
    }
    return 0;
}

void signal_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    cleanup();
    exit(0);
}

int main() {
    if (setup_spi() != 0) {
        fprintf(stderr, "SPI setup failed\n");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        int adc_value = read_adc(SPI_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        if (gpiod_line_set_value(buzzer_line, adc_value >= GPIO_THRESHOLD) < 0) {
            fprintf(stderr, "Failed to set GPIO value\n");
        }

        usleep(500000); // Sleep for 500 ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

