        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 1,
        .tx_nbits = 8 * 3,
        .rx_nbits = 8 * 3
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Failed to read from SPI device");
        return -1;
    }

    int value = ((tx[1] & 3) << 8) | tx[2];
    return value;
}

int setup_gpio() {
    buzzer_line = gpiod_line_request(GPIO_BUZZER, "buzzer", GPIOD_OUT_LOW);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        return -1;
    }
    return 0;
}

void signal_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    cleanup();
    exit(0);
}

int main() {
    if (setup_spi() != 0) {
        fprintf(stderr, "SPI setup failed\n");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        int adc_value = read_adc(SPI_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        if (gpiod_line_set_value(buzzer_line, adc_value >= GPIO_THRESHOLD) < 0) {
            fprintf(stderr, "Failed to set GPIO value\n");
        }

        usleep(500000); // Sleep for 500 ms
    }

    cleanup();
    return EXIT_SUCCESS;
}
