    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_lines[0] = gpiod_chip_get_line(chip, CS0_GPIO);
    cs_lines[1] = gpiod_chip_get_line(chip, CS1_GPIO);
    cs_lines[2] = gpiod_chip_get_line(chip, CS2_GPIO);

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (!cs_lines[i]) {
            perror("Failed to get GPIO line");
            return -1;
        }
        if (gpiod_line_request_output(cs_lines[i], "CS", 1) < 0) {
            perror("Failed to request GPIO line");
            return -1;
        }
    }

    return 0;
}

void release_resources() {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (cs_lines[i]) {
            gpiod_line_release(cs_lines[i]);
            cs_lines[i] = NULL;
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }

    if (log_fd >= 0) {
        close(log_fd);
        log_fd = -1;
    }
}

int read_adc(int cs_index) {
    uint8_t tx[] = {0b11000000 | (CHANNEL << 4), 0x00};
    uint8_t rx[3] = {0};

    if (gpiod_line_set_value(cs_lines[cs_index], 0) < 0) {
        perror("Failed to set CS low");
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = SPI_DELAY_USEC,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        gpiod_line_set_value(cs_lines[cs_index], 1);
        return -1;
    }

    gpiod_line_set_value(cs_lines[cs_index], 1);

    return (rx[1] & 0x03) << 8 | rx[2];
}

void log_data(int sensor1, int sensor2, int sensor3) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    dprintf(log_fd, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (open_spi_device() < 0) {
        release_resources();
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        release_resources();
        return EXIT_FAILURE;
    }

    log_fd = open("soil_moisture_log.csv", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        release_resources();
        return EXIT_FAILURE;
    }

    if (lseek(log_fd, 0, SEEK_END) == 0) {
        dprintf(log_fd, "timestamp,sensor1,sensor2,sensor3\n");
    }

    while (keep_running) {
        int sensor_values[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_adc(i);
            if (sensor_values[i] == -1) {
                sensor_values[i] = -1;
            }
        }

        log_data(sensor_values[0], sensor_values[1], sensor_values[2]);
        sleep(5);
    }

    release_resources();
    return EXIT_SUCCESS;
}
