        syslog(LOG_ERR, "Failed to set SPI mode or speed: %s", strerror(errno));
        close(spi_fd);
        gpioWrite(pump_gpio, 0);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    while (keep_running) {
        int adc_value = read_adc(0);
        if (adc_value != -1) {
            int moisture_level = (adc_value * 100) / 1023;
            char log_buffer[128];
            snprintf(log_buffer, sizeof(log_buffer), "Moisture level: %d%%", moisture_level);
            log_message(log_buffer);

            if (moisture_level < threshold) {
                gpioWrite(pump_gpio, 1);
                log_message("Pump activated");
                sleep(pump_duration);
                gpioWrite(pump_gpio, 0);
                log_message("Pump deactivated");
            }
        }
        sleep(sleep_interval);
    }

    gpioWrite(pump_gpio, 0);
    gpioTerminate();
    close(spi_fd);
    closelog();
    return 0;
}

