#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <errno.h>
#include <syslog.h>
#include <gpiod.h>
#include <pigpio.h>

#define MCP3008_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_CS_PIN 8
#define SPI_CLK_PIN 11
#define SPI_MOSI_PIN 10
#define SPI_MISO_PIN 9
#define SAMPLE_INTERVAL 10 // in milliseconds
#define INITIAL_THRESHOLD 1000

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio library");
        return -1;
    }
    if (gpioSetMode(SPI_CS_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SPI_CLK_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SPI_MOSI_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SPI_MISO_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        return -1;
    }
    return 0;
}

int read_adc(uint8_t channel) {
    uint8_t buffer[3];
    buffer[0] = 1; // Start bit
    buffer[1] = (8 + channel) << 4; // Single-ended, channel
    buffer[2] = 0; // Don't care

    if (gpioSPIDataRW(SPI_CHANNEL, buffer, 3) < 0) {
        syslog(LOG_ERR, "SPI data read/write failed");
        return -1;
    }

    uint16_t result = ((uint16_t)buffer[1] & 3) << 8 | buffer[2];
    return result;
}

void log_peak(uint16_t value) {
    time_t now = time(NULL);
    char timestamp[20];
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    int log_fd = open("/var/log/sound_events.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return;
    }

    dprintf(log_fd, "%s - Peak detected: %u\n", timestamp, value);
    close(log_fd);
}

int main() {
    openlog("sound_sampler", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (setup_gpio() < 0) {
        closelog();
        return EXIT_FAILURE;
    }

    uint16_t threshold = INITIAL_THRESHOLD;
    uint16_t peak_value = 0;

    while (keep_running) {
        uint16_t adc_value = read_adc(MCP3008_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "ADC read error");
            continue;
        }

        if (adc_value > peak_value) {
            peak_value = adc_value;
        }

        if (peak_value > threshold) {
            log_peak(peak_value);
            threshold = peak_value * 1.1; // Increase threshold by 10%
            peak_value = 0;
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

