#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define PCF8591_ADDRESS 0x48
#define PCF8591_REG_CMD 0x40
#define PCF8591_CMD_READ_AIN0 0x00

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int main() {
    int i2c_fd;
    unsigned char dummy_read;
    unsigned char read_cmd;
    unsigned char data[2];
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];
    int ret;

    // Install SIGINT handler
    signal(SIGINT, handle_sigint);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Prepare dummy read message
    messages[0].addr = PCF8591_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = &dummy_read;

    // Prepare read command message
    read_cmd = PCF8591_REG_CMD | PCF8591_CMD_READ_AIN0;
    messages[1].addr = PCF8591_ADDRESS;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 1;
    messages[1].buf = &read_cmd;

    packets.msgs = messages;
    packets.nmsgs = 2;

    // Main loop
    while (keep_running) {
        // Perform dummy read
        ret = ioctl(i2c_fd, I2C_RDWR, &packets);
        if (ret < 0) {
            perror("Failed to perform dummy read");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Prepare read data message
        messages[0].flags = I2C_M_RD;
        messages[0].len = 2;
        messages[0].buf = data;

        packets.msgs = messages;
        packets.nmsgs = 1;

        // Read current sample
        ret = ioctl(i2c_fd, I2C_RDWR, &packets);
        if (ret < 0) {
            perror("Failed to read data");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Print the 8-bit sample
        printf("%d\n", data[1]);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    close(i2c_fd);
    return EXIT_SUCCESS;
}
