#include <unistd.h>
#include <syslog.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <errno.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <inttypes.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_POINTER_CONVERT 0x00
#define ADS1115_REG_POINTER_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_6_144V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADC_RESOLUTION 32768.0
#define VREF 3.3
#define BUFFER_SIZE 10
#define THRESHOLD_GAUSS 500.0
#define GPIO_PIN 27

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

double voltage_to_gauss(double voltage) {
    // Convert voltage to Gauss using the SS49E datasheet
    // SS49E sensitivity is 2.5 mV/Gauss
    return (voltage - 2.5) / 0.0025;
}

void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

int main() {
    int gpio_fd, i2c_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    uint16_t config;
    uint16_t data;
    double buffer[BUFFER_SIZE];
    int buffer_index = 0;
    double sum = 0.0;
    double average = 0.0;
    struct sigaction sa;

    // Setup signal handling
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open syslog
    openlog("hall_effect_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize GPIO
    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        log_message("Failed to open GPIO chip");
        closelog();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_get(gpio_fd);
    if (!chip) {
        log_message("Failed to get GPIO chip");
        gpiod_chip_close(gpio_fd);
        closelog();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        log_message("Failed to get GPIO line");
        gpiod_chip_put(chip);
        gpiod_chip_close(gpio_fd);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "hall_effect_motor_shutdown", 0) < 0) {
        log_message("Failed to request GPIO line");
        gpiod_chip_put(chip);
        gpiod_chip_close(gpio_fd);
        closelog();
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_message("Failed to open I2C bus");
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        gpiod_chip_close(gpio_fd);
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        log_message("Failed to set I2C address");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        gpiod_chip_close(gpio_fd);
        closelog();
        return EXIT_FAILURE;
    }

    // Configure ADS1115
    config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 |
             ADS1115_CONFIG_PGA_6_144V | ADS1115_CONFIG_MODE_SINGLE |
             ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    if (write(i2c_fd, &config, 2) != 2) {
        log_message("Failed to write ADS1115 configuration");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        gpiod_chip_close(gpio_fd);
        closelog();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Read ADC value
        if (write(i2c_fd, &config, 2) != 2) {
            log_message("Failed to start ADC conversion");
            continue;
        }

        usleep(1000000); // Wait for conversion to complete

        if (read(i2c_fd, &data, 2) != 2) {
            log_message("Failed to read ADC value");
            continue;
        }

        // Convert ADC value to voltage
        double voltage = (data * VREF) / ADC_RESOLUTION;
        if (voltage < 0 || voltage > VREF) {
            log_message("Voltage out of range");
            continue;
        }

        // Convert voltage to Gauss
        double gauss = voltage_to_gauss(voltage);
        log_message("Voltage: %.3f V, Gauss: %.2f G", voltage, gauss);

        // Update circular buffer
        sum -= buffer[buffer_index];
        buffer[buffer_index] = gauss;
        sum += gauss;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        average = sum / BUFFER_SIZE;

        log_message("Average Gauss: %.2f G", average);

        // Check threshold
        if (average > THRESHOLD_GAUSS) {
            log_message("Threshold exceeded, shutting down motor");
            gpiod_line_set_value(line, 1);
        }

        sleep(1); // Sample at 1 Hz
    }

    // Cleanup
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_put(chip);
    gpiod_chip_close(gpio_fd);
    close(i2c_fd);
    closelog();

    return EXIT_SUCCESS;
}

