#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define ADC_THRESHOLD 300
#define PUMP_GPIO 18
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_CHANNEL 0
#define WATERING_DURATION 10
#define LOG_FILE "watering_events.txt"

static volatile sig_atomic_t keep_running = 1;
static int pump_gpio = -1;

void handle_signal(int sig) {
    keep_running = 0;
    if (pump_gpio != -1) {
        gpioWrite(pump_gpio, 0);
        gpioTerminate();
    }
    exit(0);
}

void setup_signal_handling() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }
    pump_gpio = gpioOpen(PUMP_GPIO, O_RDWR);
    if (pump_gpio < 0) {
        fprintf(stderr, "Failed to open GPIO %d\n", PUMP_GPIO);
        gpioTerminate();
        return -1;
    }
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    return 0;
}

void cleanup_gpio() {
    if (pump_gpio != -1) {
        gpioWrite(pump_gpio, 0);
        gpioClose(pump_gpio);
        gpioTerminate();
    }
}

int read_soil_moisture() {
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long) &ADC_CHANNEL,
        .rx_buf = (unsigned long) &ADC_CHANNEL,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .cs_change = 0,
        .pad = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("SPI transfer failed");
        close(fd);
        return -1;
    }

    close(fd);

    int adc_value = (ADC_CHANNEL & 0x0FFF);
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

void log_watering_event(int moisture_level) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "Watering event at %s: Moisture level = %d\n", timestamp, moisture_level);
    fclose(log_file);
}

int main() {
    setup_signal_handling();

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int moisture_level = read_soil_moisture();
        if (moisture_level < 0) {
            continue; // Skip this iteration if ADC read fails
        }

        if (moisture_level < ADC_THRESHOLD) {
            gpioWrite(pump_gpio, 1);
            log_watering_event(moisture_level);
            sleep(WATERING_DURATION);
            gpioWrite(pump_gpio, 0);
        }

        sleep(60);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

