This code sets up a Raspberry Pi Zero W to read soil moisture levels using an MCP3008 ADC and controls a water pump based on the readings. It handles signals for graceful shutdown and logs watering events with timestamps.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define MCP3008_BITS 10
#define MCP3008_MAX_VALUE 1023
#define MCP3008_SINGLE_ENDED 0x01
#define MCP3008_START_BIT 0x01
#define MCP3008_SINGLE_ENDED_BIT 0x08

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

int read_adc(int fd) {
    uint8_t tx[] = {
        MCP3008_START_BIT | (MCP3008_SINGLE_ENDED_BIT << 4) | (MCP3008_CHANNEL << 3),
        0x00
    };
    uint8_t rx[3] = {0};

    if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0) {
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

void log_rainfall_intensity(int adc_value) {
    const char *intensity_levels[] = {
        "No rain",
        "Light rain",
        "Moderate rain",
        "Heavy rain"
    };

    int level = adc_value * 3 / MCP3008_MAX_VALUE;
    if (level > 3) level = 3;

    time_t now = time(NULL);
