#include <i2c/smbus.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0000
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

#define GPIO_LED 17
#define GPIO_LED_ACTIVE_LOW 0

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

double read_adc(int fd) {
    uint16_t data;
    if (ioctl(fd, I2C_SMBUS_READ_I2C_BLOCK_DATA, ADS1115_ADDRESS, 1, ADS1115_REG_CONVERSION, (unsigned char *)&data, 2) < 0) {
        perror("I2C read error");
        return -1.0;
    }
    int16_t raw = (data >> 4) & 0x0FFF;
    if (raw > 0x07FF) {
        raw |= 0xF000;
    }
    return (double)raw * 4.096 / 32767.0;
}

void blink_led(struct gpiod_chip *chip, struct gpiod_line *line) {
    gpiod_line_request_output(line, "led_blink", GPIO_LED_ACTIVE_LOW);
    for (int i = 0; i < 10; i++) {
        gpiod_line_set_value(line, 1);
        usleep(50000);
        gpiod_line_set_value(line, 0);
        usleep(50000);
    }
}

int main(int argc, char *argv[]) {
    double threshold = 100.0;
    if (argc > 1) {
        char *endptr;
        threshold = strtod(argv[1], &endptr);
        if (*endptr != '\0' || errno == ERANGE) {
            fprintf(stderr, "Invalid threshold value\n");
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    if (i2c_smbus_write_word_data(i2c_fd, ADS1115_REG_CONFIG, config) < 0) {
        perror("Failed to write configuration to ADS1115");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    gpiod_line_request_output(line, "led_control", GPIO_LED_ACTIVE_LOW);

    while (keep_running) {
        double voltage = read_adc(i2c_fd);
        if (voltage < 0) {
            fprintf(stderr, "Error reading ADC\n");
            break;
        }

        double gauss = voltage * 1000.0; // Assuming 1V = 1000 Gauss for this sensor
        printf("Magnetic field strength: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            blink_led(chip, line);
        }

        usleep(100000);
    }

    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

