#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC_PUBLISH "soil_moisture"
#define MQTT_TOPIC_SUBSCRIBE "pump_control"

static int relay_gpio = -1;
static int spi_fd = -1;
static mosquitto *mosq = NULL;
static int running = 1;

void handle_signal(int sig) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", sig);
    if (relay_gpio != -1) {
        gpioWrite(relay_gpio, 0);
        gpioTerminate();
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    closelog();
    exit(0);
}

void on_connect(struct mosquitto *mosq, void *obj, int rc) {
    if (rc == 0) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_SUBSCRIBE, 0);
    } else {
        syslog(LOG_ERR, "Failed to connect to MQTT broker, return code %d", rc);
    }
}

void on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, (char *)message->payload);
        if (strcmp(message->payload, "pump_on") == 0) {
            gpioWrite(relay_gpio, 1);
        } else if (strcmp(message->payload, "pump_off") == 0) {
            gpioWrite(relay_gpio, 0);
        }
    }
}

int read_adc(int fd, int channel) {
    uint8_t tx[] = {1 << 7 | (channel & 0x07), 0x00, 0x00};
    uint8_t rx[3] = {0};

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tx) < 1) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    memcpy(&rx, &tx[1], 3);
    int result = ((rx[0] & 0x03) << 8) | rx[1];
    return result;
}

void publish_moisture(int moisture) {
    char payload[50];
    snprintf(payload, sizeof(payload), "Moisture: %d%%", moisture);
    mosquitto_publish(mosq, NULL, MQTT_TOPIC_PUBLISH, strlen(payload), payload, 0, false);
}

int main() {
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return EXIT_FAILURE;
    }

    relay_gpio = gpioOpen(relay_gpio, O_WRONLY);
    if (relay_gpio < 0) {
        syslog(LOG_ERR, "Failed to open relay GPIO");
        return EXIT_FAILURE;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device");
        return EXIT_FAILURE;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        syslog(LOG_ERR, "Failed to set SPI parameters");
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT instance");
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60)) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        return EXIT_FAILURE;
    }

    mosquitto_loop_start(mosq);

    int last_moisture = -1;
    int pump_state = 0;

    while (running) {
        int moisture = read_adc(spi_fd, SPI_CHANNEL);
        if (moisture < 0) {
            syslog(LOG_WARNING, "Failed to read moisture sensor");
            sleep(1);
            continue;
        }

        int percentage = (moisture * 100) / 1023;

        if (percentage < MOISTURE_THRESHOLD_LOW && !pump_state) {
            gpioWrite(relay_gpio, 1);
            pump_state = 1;
            syslog(LOG_INFO, "Pump activated");
        } else if (percentage > MOISTURE_THRESHOLD_HIGH && pump_state) {
            gpioWrite(relay_gpio, 0);
            pump_state = 0;
            syslog(LOG_INFO, "Pump deactivated");
        }

        if (last_moisture != percentage) {
            publish_moisture(percentage);
            last_moisture = percentage;
        }

        sleep(60);
    }

    handle_signal(0);
    return EXIT_SUCCESS;
}

