#include <signal.h>
#include <errno.h>
#include <string.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED_HZ 1000000
#define CS_PIN 8
#define VDD 3.3
#define VREF 3.3

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int setup_spi(int *fd) {
    struct spi_ioc_transfer transfer;
    uint8_t tx[] = {1, 0x80, 0x00};
    uint8_t rx[3] = {0};

    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)tx;
    transfer.rx_buf = (unsigned long)rx;
    transfer.len = sizeof(tx);
    transfer.delay_usecs = 0;
    transfer.speed_hz = SPI_SPEED_HZ;
    transfer.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(*fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Failed to perform SPI transfer: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

int read_adc(int fd, uint16_t *adc_value) {
    uint8_t tx[] = {1, 0x80 | 0x00, 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer transfer;
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)tx;
    transfer.rx_buf = (unsigned long)rx;
    transfer.len = sizeof(tx);
    transfer.delay_usecs = 0;
    transfer.speed_hz = SPI_SPEED_HZ;
    transfer.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Failed to perform SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = (rx[1] & 0x03) << 8 | rx[2];
    return 0;
}

double calculate_voltage(uint16_t adc_value) {
    return (adc_value / 1023.0) * VREF;
}

int main() {
    int fd;
    if (setup_spi(&fd) != 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        uint16_t adc_value;
        if (read_adc(fd, &adc_value) != 0) {
            close(fd);
            return EXIT_FAILURE;
        }

        double voltage = calculate_voltage(adc_value);
        printf("Raw ADC Value: %u, Voltage: %.3f V\n", adc_value, voltage);

        usleep(500000); // Sleep for 500 ms
    }

    close(fd);
    return EXIT_SUCCESS;
}

