#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 0
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define VREF 3.3
#define SAMPLE_INTERVAL 5

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_spi_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

int read_adc(int fd, uint8_t channel) {
    uint8_t tx[] = {1 << 7 | (channel << 4) | 0x08, 0x00, 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    uint16_t adc_value = ((uint16_t)rx[1] & 0x03) << 8 | rx[2];
    return adc_value;
}

float convert_to_voltage(uint16_t adc_value) {
    return (adc_value * VREF) / 1023.0;
}

void write_to_csv(const char *filename, float voltages[3]) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open CSV file");
        exit(EXIT_FAILURE);
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s,%.4f,%.4f,%.4f\n", time_str, voltages[0], voltages[1], voltages[2]);
    fclose(file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int spi_fd = open_spi_device(SPI_DEVICE);
    if (spi_fd < 0) {
        exit(EXIT_FAILURE);
    }

    while (keep_running) {
        float voltages[3];
        for (int i = 0; i < 3; i++) {
            int adc_value = read_adc(spi_fd, i);
            if (adc_value < 0) {
                close(spi_fd);
                exit(EXIT_FAILURE);
            }
            voltages[i] = convert_to_voltage(adc_value);
        }

        write_to_csv("sensor_data.csv", voltages);
        sleep(SAMPLE_INTERVAL);
    }

    close(spi_fd);
    return 0;
}

