        if (adc_value > NOISE_THRESHOLD) {
            gpioPWM(MOTOR_GPIO_17, PWM_FREQUENCY, duty_cycle);
            gpioPWM(MOTOR_GPIO_27, PWM_FREQUENCY, duty_cycle);

            clock_gettime(CLOCK_REALTIME, &ts);
            snprintf(log_buffer, sizeof(log_buffer), "Vibration event at %ld.%09ld", ts.tv_sec, ts.tv_nsec);
            if (log_event(log_buffer) < 0) {
                fprintf(stderr, "Failed to log vibration event\n");
            }
        } else {
            gpioPWM(MOTOR_GPIO_17, PWM_FREQUENCY, 0);
            gpioPWM(MOTOR_GPIO_27, PWM_FREQUENCY, 0);
        }

        usleep(10000); // Sleep for 10 ms
    }

    cleanup(spi_fd);
    return EXIT_SUCCESS;
}

