#include <pigpio.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_CS_PIN 8
#define LOG_INTERVAL 5
#define BH1750_READ_DELAY 180

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int read_bh1750(int fd, float *lux) {
    unsigned char data[2];
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        return -1;
    }

    if (write(fd, "\x23", 1) != 1) {
        return -2;
    }

    usleep(BH1750_READ_DELAY * 1000);

    if (read(fd, data, 2) != 2) {
        return -3;
    }

    *lux = (data[0] << 8 | data[1]) / 1.2;
    return 0;
}

int read_mcp3008(int fd, int channel, float *value) {
    unsigned char buf[3];
    buf[0] = 1 << 7 | (channel & 0x07) << 4;
    buf[1] = 0x0;
    buf[2] = 0x0;

    if (write(fd, buf, 3) != 3) {
        return -1;
    }

    if (read(fd, buf, 3) != 3) {
        return -2;
    }

    int result = ((buf[1] & 0x03) << 8) | buf[2];
    *value = (result * 3.3) / 1023.0;
    return 0;
}

void log_data(FILE *file, time_t timestamp, float sound_level_db, float light_level_lux, int error_code) {
    fprintf(file, "%ld,%f,%f,%d\n", (long)timestamp, sound_level_db, light_level_lux, error_code);
    fflush(file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to configure SPI");
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_CS_PIN, PI_OUTPUT) < 0) {
        perror("Failed to set SPI CS pin mode");
        gpioTerminate();
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("tamper_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    fflush(log_file);

    while (keep_running) {
        time_t now = time(NULL);
        float sound_level_db = 0.0;
        float light_level_lux = 0.0;
        int error_code = 0;

        if (gpioWrite(SPI_CS_PIN, 0) < 0) {
            error_code = -1;
        } else {
            if (read_mcp3008(spi_fd, 0, &sound_level_db) != 0) {
                error_code = -2;
            }
            if (gpioWrite(SPI_CS_PIN, 1) < 0) {
                error_code = -3;
            }
        }

        if (read_bh1750(i2c_fd, &light_level_lux) != 0) {
            error_code = -4;
        }

        log_data(log_file, now, sound_level_db, light_level_lux, error_code);
        sleep(LOG_INTERVAL);
    }

    fclose(log_file);
    gpioTerminate();
    close(spi_fd);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

