#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define MCP3008_CS_PIN 8
#define MCP3008_CHANNEL 0
#define PUMP_PIN 17
#define SPI_SPEED 1000000
#define READ_INTERVAL 60
#define MOISTURE_THRESHOLD 30

static volatile sig_atomic_t keep_running = 1;
static int spi_handle;
static int pump_gpio;

void handle_signal(int sig) {
    keep_running = 0;
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }
    pump_gpio = gpioExport(PUMP_PIN);
    if (pump_gpio < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", PUMP_PIN);
        return -1;
    }
    if (gpioSetMode(PUMP_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_PIN);
        return -1;
    }
    gpioWrite(PUMP_PIN, 0);
    return 0;
}

int init_spi() {
    spi_handle = spiOpen(0, SPI_SPEED, SPI_MODE_0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel 0\n");
        return -1;
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }
    if (gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MCP3008_CS_PIN);
        return -1;
    }
    gpioWrite(MCP3008_CS_PIN, 1);
    return 0;
}

int read_adc() {
    unsigned char tx[] = {1, (8 + MCP3008_CHANNEL) << 4, 0};
    unsigned char rx[3] = {0};
    int retries = 3;
    int result;

    while (retries--) {
        gpioWrite(MCP3008_CS_PIN, 0);
        result = spiXfer(spi_handle, tx, rx, 3);
        gpioWrite(MCP3008_CS_PIN, 1);

        if (result == 3) {
            int adc_value = ((rx[1] & 3) << 8) | rx[2];
            return adc_value;
        }
        usleep(100000); // Wait 100ms before retrying
    }
    fprintf(stderr, "Failed to read from ADC after 3 attempts\n");
    return -1;
}

void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (pump_gpio >= 0) {
        gpioWrite(PUMP_PIN, 0);
        gpioUnexport(PUMP_PIN);
    }
    gpioTerminate();
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR || signal(SIGTERM, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handlers\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0 || init_spi() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int adc_value = read_adc();
