#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define CE0_GPIO 8
#define SPI_CHANNEL 0
#define SPI_SPEED_HZ 1000000
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_DELAY_MS 1000
#define DISTANCE_THRESHOLD_CM 20
#define LOG_FILE "door_events.log"

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for relay\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(CE0_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for CE0\n");
        gpioTerminate();
        return -1;
    }

    gpioWrite(RELAY_GPIO, 0);
    gpioWrite(CE0_GPIO, 1);

    return 0;
}

int setup_spi() {
    if (gpioSPISetup(SPI_CHANNEL, SPI_SPEED_HZ) < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        return -1;
    }

    return 0;
}

int read_adc() {
    unsigned char buffer[3] = {0x01, 0x80, 0x00}; // Start bit, single-ended, channel 0
    unsigned char response[3] = {0};

    if (gpioSPIDataRW(SPI_CHANNEL, buffer, sizeof(buffer), response) < 0) {
        fprintf(stderr, "SPI data read/write failed\n");
        return -1;
    }

    int adc_value = ((response[1] & 0x03) << 8) | response[2];
    return adc_value;
}

float convert_adc_to_distance(int adc_value) {
    // Conversion formula for GP2Y0A21YK0F
    float voltage = adc_value * (3.3 / 1023.0);
    float distance = 27.86 / (voltage - 0.46);
    return distance;
}

int log_event(const char *event) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(file, "[%s] %s\n", timestamp, event);
    fclose(file);

    return 0;
}

int main() {
    signal(SIGINT, handle_sigint);

    if (setup_gpio() < 0 || setup_spi() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_detection_time = 0;

    while (keep_running) {
        gpioWrite(CE0_GPIO, 0);
        usleep(1); // Ensure CE0 is low for at least 1us

        int adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC\n");
            continue;
        }

        gpioWrite(CE0_GPIO, 1);

        float distance = convert_adc_to_distance(adc_value);
        if (distance < 0) {
            fprintf(stderr, "Invalid distance reading\n");
            continue;
        }

        if (distance < DISTANCE_THRESHOLD_CM) {
            time_t now = time(NULL);
            if (now - last_detection_time > DEBOUNCE_DELAY_MS / 1000) {
                gpioWrite(RELAY_GPIO, 1);
                if (log_event("Door opened") < 0) {
                    fprintf(stderr, "Failed to log event\n");
                }
                last_detection_time = now;
                usleep(DEBOUNCE_DELAY_MS * 1000);
                gpioWrite(RELAY_GPIO, 0);
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

