#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GPIO_ADC_CS 8
#define GPIO_VALVE 17
#define PWM_FREQUENCY 100
#define LOG_INTERVAL 5

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

int read_adc_value(int fd) {
    uint8_t tx[] = {1, 0x00, 0x00};
    uint8_t rx[3] = {0};

    gpioSetMode(GPIO_ADC_CS, PI_OUTPUT);
    gpioWrite(GPIO_ADC_CS, 1);

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "Failed to read from ADC\n");
        return -1;
    }

    gpioWrite(GPIO_ADC_CS, 0);

    int adc_value = (rx[1] & 0x0F) << 8 | rx[2];
    return adc_value;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI parameters\n");
        close(fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_VALVE, PI_OUTPUT);
    gpioPWM(GPIO_VALVE, PWM_FREQUENCY, 0);

    while (keep_running) {
        int adc_values[3];
        int valid_reads = 0;
        int sum = 0;

        for (int i = 0; i < 3; i++) {
            int adc_value = read_adc_value(fd);
            if (adc_value >= 0) {
                adc_values[i] = adc_value;
                sum += adc_value;
                valid_reads++;
            }
        }

        if (valid_reads > 0) {
            int average = sum / valid_reads;
            int duty_cycle = (average * 100) / 1023; // Assuming 10-bit ADC

            gpioPWMRange(GPIO_VALVE, 100);
            gpioPWM(GPIO_VALVE, PWM_FREQUENCY, duty_cycle);

            char log_buffer[256];
            snprintf(log_buffer, sizeof(log_buffer),
                     "ADC Readings: %d, %d, %d | Average: %d | Valve Position: %d%%",
                     adc_values[0], adc_values[1], adc_values[2], average, duty_cycle);
            log_message(log_buffer);
        }

        sleep(LOG_INTERVAL);
    }

    gpioPWM(GPIO_VALVE, PWM_FREQUENCY, 0);
    close(fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

