static struct gpiod_line *ce0_line;
static struct gpiod_line *lines[5];
static struct gpiod_spi *spi;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, 7);
    sclk_line = gpiod_chip_get_line(chip, 11);
    mosi_line = gpiod_chip_get_line(chip, 10);
    miso_line = gpiod_chip_get_line(chip, 9);
    ce0_line = gpiod_chip_get_line(chip, 8);

    if (!cs_line || !sclk_line || !mosi_line || !miso_line || !ce0_line) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        return -1;
    }

    lines[0] = cs_line;
    lines[1] = sclk_line;
    lines[2] = mosi_line;
    lines[3] = miso_line;
    lines[4] = ce0_line;

    for (int i = 0; i < 5; i++) {
        if (gpiod_line_request_output(lines[i], "spi", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0) {
            syslog(LOG_ERR, "Failed to request GPIO line: %s", strerror(errno));
            return -1;
        }
    }

    return 0;
}

void cleanup_gpio() {
    for (int i = 0; i < 5; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
}

int setup_spi() {
    spi = gpiod_spi_open("/dev/spidev0.0", SPI_SPEED, SPI_MODE, SPI_BITS);
    if (!spi) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        return -1;
    }

    if (gpiod_spi_set_cs_line(spi, ce0_line) < 0) {
        syslog(LOG_ERR, "Failed to set CS line: %s", strerror(errno));
        return -1;
    }

    return 0;
}

void cleanup_spi() {
    gpiod_spi_close(spi);
}

