    uint8_t command = 0x01; // Start bit + single-ended mode + channel 0
    uint8_t tx_buf[3] = {command, 0x00, 0x00};
    uint8_t rx_buf[3] = {0};

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (gpiod_spi_transfer(spi, tx_buf, sizeof(tx_buf), rx_buf, sizeof(rx_buf)) == 0) {
            uint16_t adc_value = (rx_buf[1] & 0x03) << 8 | rx_buf[2];
            return adc_value;
        } else {
            retries++;
            usleep(BACKOFF_BASE * (1 << retries));
        }
    }

    syslog(LOG_ERR, "SPI transfer failed after %d retries", MAX_RETRIES);
    return -1;
}

