    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    if (error) {
        fprintf(file, "[%s] ERROR: SPI communication failed\n", timestamp);
    } else {
        int moisture_percentage = (1023 - adc_value) * 100 / 1023;
        fprintf(file, "[%s] ADC Value: %d, Moisture: %d%%\n", timestamp, adc_value, moisture_percentage);
    }

    fclose(file);
}

int main() {
    openlog("soil_sensor", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (setup_gpio() < 0 || setup_spi() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO or SPI");
        closelog();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint16_t adc_value = read_adc();
        if (adc_value >= 0 && adc_value <= 1023) {
            log_data(adc_value, 0);
        } else {
            log_data(adc_value, 1);
        }
        sleep(5);
    }

    cleanup_spi();
    cleanup_gpio();
    closelog();
    return EXIT_SUCCESS;
}

