#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_TRANSFER_SIZE 3
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define MAX_VOLUME 100
#define CONFIG_FILE "theremin_config.txt"
#define TIMEOUT_US 30000

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

double read_distance() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    uint64_t echo_value;
    uint64_t start, end;
    double distance;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trig_line, "trig", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0 ||
        gpiod_line_request_input(echo_line, "echo", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0) {
        perror("Failed to request GPIO lines");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(trig_line, 1);
    usleep(10);
    gpiod_line_set_value(trig_line, 0);

    start = gpiod_line_get_both_edges(echo_line, TIMEOUT_US);
    if (start < 0) {
        perror("Echo timeout");
        gpiod_chip_close(chip);
        return -1;
    }

    end = gpiod_line_get_both_edges(echo_line, TIMEOUT_US);
    if (end < 0) {
        perror("Echo timeout");
        gpiod_chip_close(chip);
        return -1;
    }

    distance = (end - start) * 0.034 / 2;
    gpiod_chip_close(chip);

    return distance;
}

int read_ldr() {
    uint8_t tx[] = {1, 0, 0};
    uint8_t rx[3] = {0};
    int fd, ret;

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = SPI_TRANSFER_SIZE,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 0) {
        perror("SPI transfer failed");
        close(fd);
        return -1;
    }

    close(fd);

    return (rx[1] << 8) | rx[2];
}

void save_config(double distance, int volume) {
    FILE *file = fopen(CONFIG_FILE, "w");
    if (file) {
        fprintf(file, "%lf %d\n", distance, volume);
        fclose(file);
    }
}

void load_config(double *distance, int *volume) {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (file) {
        fscanf(file, "%lf %d", distance, volume);
        fclose(file);
    }
}

void cleanup() {
    gpioTerminate();
}

int main() {
    double last_valid_distance = 0;
    int last_valid_volume = 50;
    double distance;
    int volume;
    int pwm_fd;
    char pwm_path[64];
    int freq, duty_cycle;

    signal(SIGINT, handle_sigint);

    load_config(&last_valid_distance, &last_valid_volume);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip0/pwm0");
    pwm_fd = open(pwm_path, O_WRONLY);
    if (pwm_fd < 0) {
        perror("Failed to open PWM device");
        cleanup();
        return 1;
    }

    if (write(pwm_fd, "1", 1) < 0) {
        perror("Failed to enable PWM");
        close(pwm_fd);
        cleanup();
        return 1;
    }

    while (keep_running) {
        distance = read_distance();
        if (distance >= 0 && distance <= MAX_DISTANCE) {
            last_valid_distance = distance;
        }

        volume = read_ldr();
        if (volume >= 0) {
            last_valid_volume = volume;
        }

        freq = (int)((MAX_DISTANCE - last_valid_distance) * 1000 / (MAX_DISTANCE - MIN_DISTANCE));
        duty_cycle = (int)(last_valid_volume * 100 / MAX_VOLUME);

        snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
        if (write(pwm_fd, &duty_cycle, sizeof(duty_cycle)) < 0) {
            perror("Failed to set duty cycle");
        }

        snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip0/pwm0/period");
        if (write(pwm_fd, &freq, sizeof(freq)) < 0) {
            perror("Failed to set period");
        }

        save_config(last_valid_distance, last_valid_volume);
        usleep(10000);
    }

    close(pwm_fd);
    cleanup();
    return 0;
}

