        return 1;
    }

    if (write(pwm_fd, "1", 1) < 0) {
        perror("Failed to enable PWM");
        close(pwm_fd);
        cleanup();
        return 1;
    }

    while (keep_running) {
        distance = read_distance();
        if (distance >= 0 && distance <= MAX_DISTANCE) {
            last_valid_distance = distance;
        }

        volume = read_ldr();
        if (volume >= 0) {
            last_valid_volume = volume;
        }

        freq = (int)((MAX_DISTANCE - last_valid_distance) * 1000 / (MAX_DISTANCE - MIN_DISTANCE));
        duty_cycle = (int)(last_valid_volume * 100 / MAX_VOLUME);

        snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
        if (write(pwm_fd, &duty_cycle, sizeof(duty_cycle)) < 0) {
            perror("Failed to set duty cycle");
        }

        snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip0/pwm0/period");
        if (write(pwm_fd, &freq, sizeof(freq)) < 0) {
            perror("Failed to set period");
        }

        save_config(last_valid_distance, last_valid_volume);
        usleep(10000);
    }

    close(pwm_fd);
    cleanup();
    return 0;
}
