#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <syslog.h>
#include <gpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define ADC_MAX_VALUE 1023
#define ADC_MIN_VALUE 0
#define RETRY_LIMIT 3
#define RETRY_DELAY_MS 100
#define VREF 3.3
#define RESISTOR_DIVIDER_RATIO 11.0
#define MQ3_SENSOR_THRESHOLD_LOW 20
#define MQ3_SENSOR_THRESHOLD_HIGH 50

static int log_fd = -1;
static int spi_handle = -1;
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

void log_error(const char *message) {
    syslog(LOG_ERR, "%s: %s", message, strerror(errno));
}

void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

void close_resources() {
    if (log_fd != -1) {
        close(log_fd);
    }
    if (spi_handle != -1) {
        gpioTerminate();
    }
}

uint16_t read_adc() {
    uint8_t tx[] = {1, (8 + SPI_CHANNEL) << 4, 0};
    uint8_t rx[3] = {0};
    int retries = 0;
    uint16_t adc_value = 0;

    while (retries < RETRY_LIMIT) {
        if (gpioSPIDataRW(spi_handle, tx, sizeof(tx), rx, sizeof(rx)) == 0) {
            adc_value = ((uint16_t)rx[1] & 0x0F) << 8 | rx[2];
            if (adc_value != ADC_MAX_VALUE && adc_value != ADC_MIN_VALUE) {
                return adc_value;
            }
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return ADC_MAX_VALUE; // Indicate failure
}

void log_reading(uint16_t adc_value) {
    char timestamp[64];
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    char log_entry[128];
    float voltage = (adc_value / (float)ADC_MAX_VALUE) * VREF;
    float alcohol_ppm = (voltage / VREF) * RESISTOR_DIVIDER_RATIO * 1000;

    if (alcohol_ppm > MQ3_SENSOR_THRESHOLD_HIGH) {
        snprintf(log_entry, sizeof(log_entry), "%s - Voltage: %.2fV, Alcohol: %.2fppm - Alcohol detected! Limit exceeded.\n", timestamp, voltage, alcohol_ppm);
    } else if (alcohol_ppm < MQ3_SENSOR_THRESHOLD_LOW) {
        snprintf(log_entry, sizeof(log_entry), "%s - Voltage: %.2fV, Alcohol: %.2fppm - Sobriety confirmed.\n", timestamp, voltage, alcohol_ppm);
    } else {
        snprintf(log_entry, sizeof(log_entry), "%s - Voltage: %.2fV, Alcohol: %.2fppm - Alcohol level within acceptable range.\n", timestamp, voltage, alcohol_ppm);
    }

    if (write(log_fd, log_entry, strlen(log_entry)) == -1) {
        log_error("Failed to write to log file");
    }
}

int main() {
    openlog("alcohol_sensor", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((log_fd = open("alcohol_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644)) == -1) {
        log_error("Failed to open log file");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        close(log_fd);
        closelog();
        return EXIT_FAILURE;
    }

    spi_handle = gpioSPISetup(0, SPI_SPEED_HZ, SPI_MODE, SPI_BITS_PER_WORD);
    if (spi_handle < 0) {
        log_error("Failed to setup SPI");
        gpioTerminate();
        close(log_fd);
        closelog();
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint16_t adc_value = read_adc();
        if (adc_value == ADC_MAX_VALUE) {
            log_message("Sensor absent or ADC read error");
        } else {
            log_reading(adc_value);
        }
        sleep(1);
    }

    close_resources();
    closelog();
    return EXIT_SUCCESS;
}

