void handle_signal(int sig) {
    keep_running = 0;
}

int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return -1;
    }
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for pump\n");
        gpioTerminate();
        return -1;
    }
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially
    return 0;
}

int setup_spi() {
    spi_handle = spiOpen(0, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI interface\n");
        return -1;
    }
    return 0;
}

int read_soil_moisture() {
    uint8_t tx[] = {1 << 7 | (MCP3008_CHANNEL << 4) | 0x0};
    uint8_t rx[3] = {0};
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    int adc_value = ((rx[1] & 3) << 8) | rx[2];
    return adc_value;
}

void log_message(const char *message) {
    if (log_fd < 0) {
        fprintf(stderr, "Log file not open\n");
        return;
    }
    time_t now = time(NULL);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&now));
    dprintf(log_fd, "[%s] %s\n", time_str, message);
}

int main() {
    if (setup_gpio() < 0 || setup_spi() < 0) {
        return EXIT_FAILURE;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int moisture = read_soil_moisture();
        if (moisture < 0) {
            log_message("Error reading soil moisture");
            sleep(60);
            continue;
        }

        char log_entry[100];
        snprintf(log_entry, sizeof(log_entry), "Moisture: %d", moisture);
        log_message(log_entry);

        if (moisture < THRESHOLD) {
            gpioWrite(PUMP_GPIO, 1);
            log_message("Pump: ON");
        } else {
            gpioWrite(PUMP_GPIO, 0);
            log_message("Pump: OFF");
        }

        sleep(60);
    }

    gpioWrite(PUMP_GPIO, 0);
    log_message("Pump: OFF");

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}
