This code sets up the Raspberry Pi to read from two potentiometers using an MCP3008 ADC over SPI, maps the readings to motor speeds, and controls two motors using PWM. It handles signals for graceful shutdown and includes error handling for GPIO and SPI operations.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>
#include <string.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_CHANNEL 0
#define GPIO_LED 17
#define GPIO_CS 8
#define DEBOUNCE_TIME 10 // milliseconds

static int spi_fd = -1;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *cs_line;
static int led_value = 0;
static int baseline = 0;
static bool running = true;

void handle_sigint(int sig) {
    running = false;
}

int init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led_control", 0)) {
        fprintf(stderr, "Failed to request LED line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, GPIO_CS);
    if (!cs_line) {
        fprintf(stderr, "Failed to get CS line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "cs_control", 1)) {
        fprintf(stderr, "Failed to request CS line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_adc(uint8_t channel) {
    uint8_t tx[] = {0x01, (8 + channel) << 4, 0x00};
    uint8_t rx[3] = {0};

    if (gpiod_line_set_value(cs_line, 0)) {
        fprintf(stderr, "Failed to set CS low\n");
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to perform SPI transfer");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    gpiod_line_set_value(cs_line, 1);

    return ((rx[1] & 3) << 8) | rx[2];
}

void cleanup() {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    gpiod_line_set_value(led_line, 0);
}

int main() {
    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handler\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0 || init_spi() != 0) {
        return EXIT_FAILURE;
    }

    // Calibrate baseline
    int sum = 0;
    for (int i = 0; i < 50 && running; ++i) {
        int value = read_adc(0);
        if (value >= 0) {
            sum += value;
        }
        usleep(100000); // 100 ms
    }
    baseline = sum / 50;

    while (running) {
        int value = read_adc(0);
        if (value >= 0 && value > baseline) {
            if (led_value == 0) {
                gpiod_line_set_value(led_line, 1);
                led_value = 1;
            }
        } else {
            if (led_value == 1) {
                usleep(DEBOUNCE_TIME * 1000);
                if (read_adc(0) <= baseline) {
                    gpiod_line_set_value(led_line, 0);
                    led_value = 0;
                }
            }
        }
        usleep(10000); // 10 ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

