#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CS 8
#define GPIO_CS_PIN (1 << GPIO_CS)
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define SAMPLE_RATE_HZ 1000
#define LOG_FILE "audio_log.txt"

static int spi_fd = -1;
static int gpio_fd = -1;
static int log_fd = -1;

void cleanup() {
    if (gpio_fd != -1) {
        ioctl(gpio_fd, GPIO_SET_LINE_LOW, GPIO_CS);
        close(gpio_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
}

void handle_signal(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int setup_gpio() {
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd == -1) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    struct gpiohandle_request req = {
        .lineoffsets = &GPIO_CS,
        .flags = GPIOHANDLE_REQUEST_OUTPUT,
        .lines = 1,
    };

    int gpio_handle = ioctl(gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, &req);
    if (gpio_handle == -1) {
        perror("Failed to get GPIO line handle");
        close(gpio_fd);
        return -1;
    }

    ioctl(gpio_handle, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &GPIO_CS_PIN);
    close(gpio_handle);
    return 0;
}

int setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    uint32_t speed = SPI_MAX_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int setup_log_file() {
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd == -1) {
        perror("Failed to open log file");
        return -1;
    }
    return 0;
}

uint16_t read_adc() {
    uint8_t tx[] = {1, 0x00}; // Start bit, single-ended channel 0
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    ioctl(gpio_fd, GPIO_SET_LINE_HIGH, GPIO_CS);
    usleep(1); // Ensure CS is high for at least 1us

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Failed to send SPI message");
        return 0;
    }

    ioctl(gpio_fd, GPIO_SET_LINE_LOW, GPIO_CS);

    uint16_t adc_value = (rx[1] & 0x03) << 8 | rx[2];
    return adc_value;
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR ||
        signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (setup_gpio() == -1 || setup_spi() == -1 || setup_log_file() == -1) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct timespec ts;
    struct timespec sleep_time = {0, 1000000}; // 1ms

    while (1) {
        clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
        uint16_t adc_value = read_adc();

        char log_entry[64];
        snprintf(log_entry, sizeof(log_entry), "%ld|%u\n", ts.tv_nsec, adc_value);

        if (write(log_fd, log_entry, strlen(log_entry)) == -1) {
            perror("Failed to write to log file");
            cleanup();
            return EXIT_FAILURE;
        }

        if (fsync(log_fd) == -1) {
            perror("Failed to flush log file");
            cleanup();
            return EXIT_FAILURE;
        }

        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

