#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define MCP3008_CHANNEL 0
#define MCP3008_SINGLE_ENDED 0x01
#define MCP3008_START_BIT 0x01
#define MCP3008_SINGLE_ENDED_BIT 0x80
#define MCP3008_DUMMY_BYTE 0x00
#define MCP3008_COMMAND_BYTE (MCP3008_START_BIT | (MCP3008_CHANNEL & 0x07) | (MCP3008_SINGLE_ENDED << 4))
#define RETRY_DELAY 100000 // 100 ms in microseconds

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int spi_init(int *spi_fd) {
    *spi_fd = open(SPI_DEVICE, O_RDWR);
    if (*spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(*spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0 ||
        ioctl(*spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(*spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI parameters");
        close(*spi_fd);
        return -1;
    }

    return 0;
}

int read_adc(int spi_fd, uint16_t *adc_value) {
    uint8_t tx[] = {MCP3008_COMMAND_BYTE, MCP3008_DUMMY_BYTE};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    *adc_value = (rx[1] & 0x03) << 8 | rx[2];
    return 0;
}

int main() {
    int spi_fd;
    FILE *log_file;
    uint16_t adc_value;
    float voltage;
    const float reference_voltage = 3.3;
    const float resolution = reference_voltage / 1023.0;

    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handler\n");
        return EXIT_FAILURE;
    }

    if (spi_init(&spi_fd) != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("gas_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int retry_count = 0;
        while (read_adc(spi_fd, &adc_value) != 0) {
            if (++retry_count > 5) {
                fprintf(stderr, "Failed to read ADC after multiple retries\n");
                break;
            }
            usleep(RETRY_DELAY);
        }

        if (retry_count <= 5) {
            voltage = adc_value * resolution;
            printf("Voltage: %.3f V, PPM: Placeholder\n", voltage);

            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s, %.3f V, Placeholder PPM\n", timestamp, voltage);
            fflush(log_file);
        }

        sleep(1);
    }

    fclose(log_file);
    close(spi_fd);
    return EXIT_SUCCESS;
}

