#define SPI_MODE 0
#define MCP3008_CS 8
#define REF_VOLTAGE 3.3
#define G_TO_MSS 9.80665
#define SAMPLE_RATE_HZ 10
#define KALMAN_Q 0.001
#define KALMAN_R 0.01

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

double kalman_filter(double measurement, double *estimate, double *error_estimate) {
    double kalman_gain = *error_estimate / (*error_estimate + KALMAN_R);
    *estimate = *estimate + kalman_gain * (measurement - *estimate);
    *error_estimate = (1 - kalman_gain) * *error_estimate + fabs(*estimate - measurement) * KALMAN_Q;
    return *estimate;
}

double read_adc_channel(int channel) {
    uint32_t adc_value = 0;
    if (gpioSPIDataRW(SPI_CHANNEL, &channel, 1, &adc_value, 3) < 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }
    return ((adc_value & 0x03) << 8) | ((adc_value >> 2) & 0x0FF);
}

double convert_to_g(double adc_value) {
    return (adc_value / 1023.0) * REF_VOLTAGE / (330.0 / 1000.0) * G_TO_MSS;
}

