        gpioSetMode(10, PI_OUTPUT) < 0 ||
        gpioSetMode(9, PI_INPUT) < 0 ||
        gpioSetMode(11, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO mode setting failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSPISetup(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "SPI setup failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    double x_estimate = 0, y_estimate = 0, z_estimate = 0;
    double x_error_estimate = 1, y_error_estimate = 1, z_error_estimate = 1;

    while (keep_running) {
        int channels[3] = {0x01, 0x02, 0x04};
        double adc_values[3] = {0};

        for (int i = 0; i < 3; i++) {
            gpioWrite(MCP3008_CS, 0);
            usleep(1);
            adc_values[i] = read_adc_channel(channels[i]);
            gpioWrite(MCP3008_CS, 1);
            if (adc_values[i] < 0) {
                fprintf(stderr, "ADC read error on channel %d\n", i);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }

        double x_g = convert_to_g(adc_values[0]);
        double y_g = convert_to_g(adc_values[1]);
        double z_g = convert_to_g(adc_values[2]);

        double x_filtered = kalman_filter(x_g, &x_estimate, &x_error_estimate);
        double y_filtered = kalman_filter(y_g, &y_estimate, &y_error_estimate);
        double z_filtered = kalman_filter(z_g, &z_estimate, &z_error_estimate);

        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x_filtered, y_filtered, z_filtered);

        usleep(1000000 / SAMPLE_RATE_HZ);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

