#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <string.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define LOG_FILE "magnetic_log.txt"
#define READ_INTERVAL 100000000 // 100 milliseconds in nanoseconds

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

double convert_to_magnetic_field(int state) {
    return state ? 3.3 : 0.0;
}

void log_magnetic_field(FILE *file, double sensor1, double sensor2, double sensor3) {
    if (sensor1 < -100 || sensor1 > 100 || sensor2 < -100 || sensor2 > 100 || sensor3 < -100 || sensor3 > 100) {
        fprintf(stderr, "Warning: Magnetic field out of range: %f, %f, %f\n", sensor1, sensor2, sensor3);
        return;
    }
    fprintf(file, "%f,%f,%f\n", sensor1, sensor2, sensor3);
    fflush(file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2, *line3;
    int ret;
    FILE *file;
    double sensor1, sensor2, sensor3;

    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    line3 = gpiod_chip_get_line(chip, SENSOR3_PIN);

    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line1, "sensor1", GPIOD_LINE_REQ_EV_NONE);
    ret |= gpiod_line_request_input(line2, "sensor2", GPIOD_LINE_REQ_EV_NONE);
    ret |= gpiod_line_request_input(line3, "sensor3", GPIOD_LINE_REQ_EV_NONE);

    if (ret) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    file = fopen(LOG_FILE, "w");
    if (!file) {
        perror("Failed to open log file");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int state1 = gpiod_line_get_value(line1);
        int state2 = gpiod_line_get_value(line2);
        int state3 = gpiod_line_get_value(line3);

        if (state1 == -1 || state2 == -1 || state3 == -1) {
            fprintf(stderr, "Failed to read GPIO state\n");
            continue;
        }

        sensor1 = convert_to_magnetic_field(state1);
        sensor2 = convert_to_magnetic_field(state2);
        sensor3 = convert_to_magnetic_field(state3);

        log_magnetic_field(file, sensor1, sensor2, sensor3);

        nanosleep((const struct timespec[]){{0, READ_INTERVAL}}, NULL);
    }

    fclose(file);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

