#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>
#include <fcntl.h>
#include <errno.h>

#define LOG_FILE "watering.log"
#define PUMP_GPIO 17
#define MCP3008_CHANNEL 0
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY_USEC 0
#define MOISTURE_THRESHOLD 30

static int pump_gpio_chip;
static int pump_gpio_line;
static int spi_fd;
static volatile sig_atomic_t keep_running = 1;

void log_event(const char *event) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log, "[%s] %s\n", timestamp, event);
        fclose(log);
    }
}

void handle_signal(int sig) {
    keep_running = 0;
    if (pump_gpio_line >= 0) {
        gpiod_line_set_value(pump_gpio_line, 0);
        log_event("Pump turned off due to signal");
    }
}

int init_gpio() {
    pump_gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!pump_gpio_chip) {
        log_event("Failed to open GPIO chip");
        return -1;
    }

    pump_gpio_line = gpiod_chip_get_line(pump_gpio_chip, PUMP_GPIO);
    if (!pump_gpio_line) {
        log_event("Failed to get GPIO line");
        gpiod_chip_close(pump_gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(pump_gpio_line, "pump_control", 0)) {
        log_event("Failed to request GPIO line");
        gpiod_chip_close(pump_gpio_chip);
        return -1;
    }

    return 0;
}

int init_spi() {
    char spi_device[64];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);

    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        log_event("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &mode) < 0) {
        log_event("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) < 0) {
        log_event("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_adc() {
    uint8_t tx[] = {1 << 7 | MCP3008_CHANNEL << 4 | 0x0};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = SPI_DELAY_USEC,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        log_event("SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx[1] & 3) << 8) | rx[2];
    return adc_value;
}

void cleanup() {
    if (pump_gpio_line >= 0) {
        gpiod_line_release(pump_gpio_line);
    }
    if (pump_gpio_chip >= 0) {
        gpiod_chip_close(pump_gpio_chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

int main() {
    log_event("Program started");

    if (init_gpio() < 0 || init_spi() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int pump_state = 0;
    while (keep_running) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            continue; // Log error but continue
        }

        int moisture_level = (adc_value * 100) / 1023;
        if (moisture_level < MOISTURE_THRESHOLD && !pump_state) {
            gpiod_line_set_value(pump_gpio_line, 1);
            log_event("Pump turned on");
            pump_state = 1;
        } else if (moisture_level >= MOISTURE_THRESHOLD && pump_state) {
            gpiod_line_set_value(pump_gpio_line, 0);
            log_event("Pump turned off");
            pump_state = 0;
        }

        sleep(60);
    }

    if (pump_state) {
        gpiod_line_set_value(pump_gpio_line, 0);
        log_event("Pump turned off on exit");
    }

    log_event("Program terminated");
    cleanup();
    return EXIT_SUCCESS;
}

