#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <mosquitto.h>
#include <jansson.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60

static volatile sig_atomic_t stop = 0;
static struct mosquitto *mosq = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static int reconnect_delay = 1;

void log_error(const char *message) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

void handle_signal(int sig) {
    stop = 1;
}

void on_connect(struct mosquitto *mosq, void *obj, int rc) {
    if (rc) {
        log_error("Connection failed");
    } else {
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    }
}

void on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *message) {
    if (message->payloadlen == 0) {
        log_error("Received empty message");
        return;
    }

    json_error_t error;
    json_t *root = json_loads((const char *)message->payload, 0, &error);
    if (!root) {
        log_error("JSON parsing error");
        return;
    }

    json_t *led_state = json_object_get(root, "led_state");
    if (!led_state || !json_is_boolean(led_state)) {
        log_error("Invalid JSON payload");
        json_decref(root);
        return;
    }

    int state = json_boolean_value(led_state);
    gpiod_line_set_value(line, state);

    json_decref(root);
}

void on_disconnect(struct mosquitto *mosq, void *obj, int rc) {
    log_error("Disconnected");
}

void reconnect() {
    while (!stop) {
        if (mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60)) {
            log_error("Reconnect failed");
        } else {
            break;
        }
        sleep(reconnect_delay);
        reconnect_delay = reconnect_delay < MAX_RECONNECT_DELAY ? reconnect_delay * 2 : MAX_RECONNECT_DELAY;
    }
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        log_error("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "rpi_led_control", 0)) {
        log_error("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    gpiod_line_set_value(line, 0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create MQTT client");
        cleanup();
        exit(EXIT_FAILURE);
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    if (mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60)) {
        log_error("Initial connection failed");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (!stop) {
        int ret = mosquitto_loop(mosq, -1, 1);
        if (ret) {
            log_error("MQTT loop error");
            reconnect();
        }
    }

    cleanup();
    mosquitto_lib_cleanup();
    return 0;
}

