#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_GPIO 17
#define ALARM_LED_GPIO 18
#define DELAY_MS 100
#define ALARM_DURATION_MS 1000

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_gpio_line(gpiod_chip *chip, int line_offset, gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, line_offset);
    if (!*line) {
        fprintf(stderr, "Failed to get line %d\n", line_offset);
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    gpiod_chip *chip;
    gpiod_line *sensor_line = NULL;
    gpiod_line *alarm_line = NULL;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    if (setup_gpio_line(chip, SENSOR_GPIO, &sensor_line) == -1) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (setup_gpio_line(chip, ALARM_GPIO, &alarm_line) == -1) {
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor_line, "sound_sensor") < 0) {
        fprintf(stderr, "Failed to request input line\n");
        gpiod_line_release(sensor_line);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(alarm_line, "alarm_led", 0) < 0) {
        fprintf(stderr, "Failed to request output line\n");
        gpiod_line_release(sensor_line);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int value = gpiod_line_get_value(sensor_line);
        if (value < 0) {
            fprintf(stderr, "Failed to read sensor value\n");
            break;
        }

        printf("Sound level: %d\n", value);

        if (value == 0) { // Sound detected
            gpiod_line_set_value(alarm_line, 1);
            usleep(ALARM_DURATION_MS * 1000);
            gpiod_line_set_value(alarm_line, 0);
        }

        usleep(DELAY_MS * 1000);
    }

    gpiod_line_release(sensor_line);
    gpiod_line_release(alarm_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

