#include <string.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <syslog.h>
#include <math.h>

#define BMP280_I2C_BUS 1
#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_REGISTER_PRESSUREDATA 0xF7
#define BMP280_REGISTER_TEMPDATA 0xFA
#define BMP280_REGISTER_CONTROL 0xF4
#define BMP280_REGISTER_CONFIG 0xF5
#define BMP280_REGISTER_RESET 0xE0
#define BMP280_RESET_VALUE 0xB6
#define BMP280_OSR_PRESS 0x01
#define BMP280_OSR_TEMP 0x01
#define BMP280_MODE_NORMAL 0x03
#define BMP280_STANDBY_TIME_0_5_MS 0x00
#define BMP280_FILTER_COEFF_16 0x00
#define BMP280_IIR_FILTER_COEFF_16 0x00

#define SEALEVEL_PRESSURE 1013.25

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

void log_error(const char *message) {
    fprintf(stderr, "%s: %s\n", message, strerror(errno));
    syslog(LOG_ERR, "%s: %s", message, strerror(errno));
}

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int init_i2c() {
    i2c_fd = open("/dev/i2c-" PRIuMAX, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        log_error("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int read_register(uint8_t reg, uint8_t *data, size_t length) {
    if (write(i2c_fd, &reg, 1) != 1) {
        log_error("Failed to write register address");
        return -1;
    }

    if (read(i2c_fd, data, length) != length) {
        log_error("Failed to read data from register");
        return -1;
    }

    return 0;
}

int write_register(uint8_t reg, uint8_t *data, size_t length) {
    uint8_t buffer[length + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, data, length);

    if (write(i2c_fd, buffer, length + 1) != length + 1) {
        log_error("Failed to write data to register");
        return -1;
    }

    return 0;
}

int reset_sensor() {
    uint8_t reset_value = BMP280_RESET_VALUE;
    return write_register(BMP280_REGISTER_RESET, &reset_value, 1);
}

int read_chip_id(uint8_t *chip_id) {
    return read_register(BMP280_CHIP_ID_REG, chip_id, 1);
}

int read_raw_data(int16_t *temperature, int32_t *pressure) {
    uint8_t data[6];

    if (read_register(BMP280_REGISTER_PRESSUREDATA, data, 3) < 0) {
        return -1;
    }

    *pressure = (int32_t)data[0] << 16 | (int32_t)data[1] << 8 | (int32_t)data[2];

    if (read_register(BMP280_REGISTER_TEMPDATA, data, 3) < 0) {
        return -1;
    }

    *temperature = (int16_t)data[0] << 8 | (int16_t)data[1];

    return 0;
}

void configure_sensor() {
    uint8_t config[3];

    config[0] = BMP280_MODE_NORMAL | BMP280_OSR_PRESS | BMP280_OSR_TEMP;
    config[1] = BMP280_STANDBY_TIME_0_5_MS | BMP280_FILTER_COEFF_16 | BMP280_IIR_FILTER_COEFF_16;
    config[2] = 0x00; // Standby time

    if (write_register(BMP280_REGISTER_CONTROL, config, 1) < 0 ||
        write_register(BMP280_REGISTER_CONFIG, &config[1], 1) < 0) {
        log_error("Failed to configure sensor");
        exit(EXIT_FAILURE);
    }
}

double calculate_altitude(int32_t pressure) {
    return 44330.0 * (1.0 - pow(pressure / 101325.0, 0.1903));
}

void log_altitude(double altitude) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    if (fprintf(log_file, "%s, %.2f\n", timestamp, altitude) < 0) {
        log_error("Failed to write to log file");
    }

    fflush(log_file);
}

int main() {
    if (init_i2c() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (reset_sensor() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t chip_id;
    if (read_chip_id(&chip_id) < 0 || chip_id != BMP280_CHIP_ID) {
        log_error("Sensor not found or invalid chip ID");
        cleanup();
        return EXIT_FAILURE;
    }

    configure_sensor();

    if ((log_file = fopen("altitude_log.txt", "a")) == NULL) {
        log_error("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        int16_t temperature;
        int32_t pressure;

        if (read_raw_data(&temperature, &pressure) < 0) {
            log_error("Failed to read raw data");
            continue;
        }

        double altitude = calculate_altitude(pressure);
        log_altitude(altitude);

        sleep(5);
    }

    cleanup();
    return EXIT_SUCCESS;
}

