#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

#define BUFFER_SIZE 120
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define CE0_PIN 8

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

float read_temperature(int fd) {
    uint8_t tx[] = {1, 0x00, 0x00}; // Start bit, single-ended, channel 0
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI transfer failed");
        return -1.0;
    }

    uint16_t adc_value = (rx[1] << 8) | rx[2];
    float voltage = adc_value * 3.3 / 1023.0;
    float temperature = voltage * 100.0;

    return temperature;
}

int main() {
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    uint8_t mode;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &mode) < 0 ||
        mode != SPI_MODE) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &bits) < 0 ||
        bits != SPI_BITS_PER_WORD) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint32_t speed;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) < 0 ||
        speed != SPI_MAX_SPEED_HZ) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *file = fopen("temp_log.dat", "wb+");
    if (file == NULL) {
        perror("Failed to open file");
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    float buffer[BUFFER_SIZE];
    int index = 0;

    while (keep_running) {
        float temperature = read_temperature(spi_fd);
        if (temperature >= 0) {
            buffer[index] = temperature;
            printf("Temperature: %.2f °C\n", temperature);
            index = (index + 1) % BUFFER_SIZE;

            if (file != NULL) {
                fseek(file, 0, SEEK_SET);
                fwrite(buffer, sizeof(float), BUFFER_SIZE, file);
            }
        }

        sleep(5);
    }

    if (file != NULL) {
        fclose(file);
    }

    close(spi_fd);
    return EXIT_SUCCESS;
}

