#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <syslog.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define MCP3008_CS_PIN 8
#define MCP3008_CHANNEL 0
#define MCP4725_ADDR 0x60
#define SPI_SPEED 500000
#define SPI_MODE 0
#define SAMPLE_INTERVAL 0.5
#define TMP36_OFFSET 500
#define TMP36_SCALE 10.0
#define DAC_MAX_VOLTAGE 5.0
#define DAC_MAX_COUNT 4095

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_spi_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        return -1;
    }
    return fd;
}

int configure_spi(int fd) {
    uint8_t mode = SPI_MODE;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        syslog(LOG_ERR, "Failed to configure SPI: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int read_adc(int spi_fd, uint8_t channel) {
    uint8_t tx[] = {0b11000000 | (channel << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        syslog(LOG_ERR, "Failed to read from ADC: %s", strerror(errno));
        return -1;
    }

    return (rx[1] << 8) | rx[2];
}

int open_i2c_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, MCP4725_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

int write_dac(int i2c_fd, uint16_t value) {
    uint8_t buf[3] = {0x40, (value >> 4) & 0x3F, (value << 4) & 0xF0};
    if (write(i2c_fd, buf, sizeof(buf)) != sizeof(buf)) {
        syslog(LOG_ERR, "Failed to write to DAC: %s", strerror(errno));
        return -1;
    }
    return 0;
}

void log_temperature(int raw_adc, double temperature, double dac_voltage) {
    FILE *log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, raw_adc, temperature, dac_voltage);
    fclose(log_file);

    printf("%s, %d, %.2f, %.2f\n", timestamp, raw_adc, temperature, dac_voltage);
}

int main() {
    openlog("temperature_sensor", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);

    int spi_fd = open_spi_device(SPI_DEVICE);
    if (spi_fd < 0) goto cleanup;

    if (configure_spi(spi_fd) < 0) goto cleanup;

    int i2c_fd = open_i2c_device(I2C_DEVICE);
    if (i2c_fd < 0) goto cleanup;

    FILE *log_file = fopen("temperature_log.txt", "w");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        goto cleanup;
    }
    fclose(log_file);

    while (keep_running) {
        int raw_adc = read_adc(spi_fd, MCP3008_CHANNEL);
        if (raw_adc < 0) {
            syslog(LOG_WARNING, "Retrying ADC read...");
            continue;
        }

        double voltage = (raw_adc / 1023.0) * 3.3;
        double temperature = (voltage - TMP36_OFFSET / 1023.0 * 3.3) * TMP36_SCALE;
        double dac_voltage = (temperature / 100.0) * DAC_MAX_VOLTAGE;
        uint16_t dac_value = (uint16_t)(dac_voltage / DAC_MAX_VOLTAGE * DAC_MAX_COUNT);

        if (write_dac(i2c_fd, dac_value) < 0) {
            syslog(LOG_WARNING, "Retrying DAC write...");
            continue;
        }

        log_temperature(raw_adc, temperature, dac_voltage);
        usleep(SAMPLE_INTERVAL * 1000000);
    }

cleanup:
    if (spi_fd >= 0) close(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    closelog();
    return 0;
}

