#define SLEEP_INTERVAL 60

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }
    return pi_spi_writeread(SPI_CHANNEL, (channel & 7) | 0x18, 3, NULL, 0);
}

void log_error_and_exit(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(1);
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error_and_exit("Failed to initialize pigpio");
    }

    if (pi_spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        gpioTerminate();
        log_error_and_exit("Failed to open SPI interface");
    }

    FILE *log_file = fopen("soil_data.txt", "a");
    if (!log_file) {
        pi_spi_close(SPI_CHANNEL);
        gpioTerminate();
        log_error_and_exit("Failed to open log file");
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        for (int i = 0; i < ADC_CHANNELS; i++) {
