#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RELAY_COUNT 4
#define RELAY_PINS {17, 22, 23, 24}
#define RELAY_ACTIVE_HIGH 1

static struct gpiod_chip *chip;
static struct gpiod_line *lines[RELAY_COUNT];
static int relay_values[RELAY_COUNT] = {0}; // 0 for LOW, 1 for HIGH

// Signal handler to clean up GPIO resources
static void handle_signal(int signum) {
    for (int i = 0; i < RELAY_COUNT; i++) {
        if (gpiod_line_set_value(lines[i], 0) < 0) {
            fprintf(stderr, "Failed to set line %d to LOW\n", i);
        }
    }
    for (int i = 0; i < RELAY_COUNT; i++) {
        if (gpiod_line_release(lines[i]) < 0) {
            fprintf(stderr, "Failed to release line %d\n", i);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int pin_numbers[RELAY_COUNT] = RELAY_PINS;
    struct gpiod_line_request req = {
        .consumer = "relay_control",
        .type = GPIOD_LINE_REQ_DIR_OUT,
        .flags = 0
    };

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    for (int i = 0; i < RELAY_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_numbers[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", pin_numbers[i]);
            handle_signal(SIGINT); // Clean up and exit
        }

        if (gpiod_line_request(lines[i], &req) < 0) {
            fprintf(stderr, "Failed to request line %d\n", pin_numbers[i]);
            handle_signal(SIGINT); // Clean up and exit
        }
    }

    // Set all relays to inactive (LOW)
    for (int i = 0; i < RELAY_COUNT; i++) {
        if (gpiod_line_set_value(lines[i], 0) < 0) {
            fprintf(stderr, "Failed to set line %d to LOW\n", i);
            handle_signal(SIGINT); // Clean up and exit
        }
    }

    // Main loop to activate/deactivate relays
    while (1) {
        for (int i = 0; i < RELAY_COUNT; i++) {
            // Activate relay
            if (gpiod_line_set_value(lines[i], RELAY_ACTIVE_HIGH) < 0) {
                fprintf(stderr, "Failed to set line %d to HIGH\n", i);
                handle_signal(SIGINT); // Clean up and exit
            }
            sleep(1);

            // Deactivate relay
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set line %d to LOW\n", i);
                handle_signal(SIGINT); // Clean up and exit
            }
            sleep(1);
        }
    }

    // This point is never reached due to infinite loop
    return EXIT_SUCCESS;
}

