#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CS_PIN 8
#define MCP3008_CHANNEL 0
#define IN1_PIN 17
#define IN2_PIN 18
#define ENA_PIN 27
#define PWM_DUTY 150
#define RAIN_THRESHOLD 5
#define LOG_FILE "rain_log.txt"
#define MOTOR_RUN_TIME 3

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int sig) {
    stop_flag = 1;
}

int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return -1;
    }

    if (gpioSetMode(IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(IN2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ENA_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

int setup_spi() {
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(fd, SPI_IOC_RD_MODE, &mode) < 0 ||
        ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &bits) < 0 ||
        ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0 ||
        ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI parameters: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

int read_adc(int spi_fd) {
    uint8_t tx[] = {1, (8 + MCP3008_CHANNEL) << 4, 0};
    uint8_t rx[3] = {0};

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    rx[0] = tx[2];
    int adc_value = ((rx[1] & 3) << 8) | rx[0];
    return adc_value;
}

void drive_motor(int direction) {
    if (direction == 1) { // Forward
        gpioWrite(IN1_PIN, 1);
        gpioWrite(IN2_PIN, 0);
    } else { // Reverse
        gpioWrite(IN1_PIN, 0);
        gpioWrite(IN2_PIN, 1);
    }
    gpioPWM(ENA_PIN, PWM_DUTY);
    sleep(MOTOR_RUN_TIME);
    gpioPWM(ENA_PIN, 0);
}

void log_rain_level(int level, FILE *log_file) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fprintf(log_file, "%s - Rain Level: %d\n", time_str, level) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    }
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    int spi_fd = setup_spi();
    if (spi_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int window_open = 1;

    while (!stop_flag) {
        int adc_value = read_adc(spi_fd);
        if (adc_value < 0) {
            continue;
        }

        log_rain_level(adc_value, log_file);

        if (adc_value > RAIN_THRESHOLD) {
            if (window_open) {
                drive_motor(1);
                window_open = 0;
            }
        } else {
            if (!window_open) {
                drive_motor(0);
                window_open = 1;
            }
        }

        sleep(1);
    }

    gpioPWM(ENA_PIN, 0);
    close(spi_fd);
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}
