#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <stdbool.h>
#include <gpiod.h>

#define ADC_PIN 26
#define LED_PIN 16
#define SAMPLE_INTERVAL_US 10000
#define CLAP_THRESHOLD 1000
#define DEBOUNCE_INTERVAL_MS 50
#define LED_ON_DURATION_MS 500

static volatile bool keep_running = true;
static struct gpiod_chip *chip;
static struct gpiod_line *adc_line;
static struct gpiod_line *led_line;
static int last_clap_time = 0;

void handle_sigint(int sig) {
    keep_running = false;
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
    }
    if (adc_line) {
        gpiod_line_release(adc_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Exiting gracefully...\n");
    exit(0);
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    adc_line = gpiod_chip_get_line(chip, ADC_PIN);
    if (!adc_line) {
        perror("Failed to get ADC line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(adc_line, "adc_input", GPIOD_LINE_REQ_EV_NONE)) {
        perror("Failed to request ADC line as input");
        gpiod_line_release(adc_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(adc_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "led_output", 0)) {
        perror("Failed to request LED line as output");
        gpiod_line_release(led_line);
        gpiod_line_release(adc_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

int read_adc() {
    int value = 0;
    for (int i = 0; i < 8; i++) {
        gpiod_line_set_value(adc_line, 1);
        usleep(1);
        gpiod_line_set_value(adc_line, 0);
        usleep(2);

        if (gpiod_line_get_value(adc_line) == 1) {
            value |= (1 << i);
        }
        usleep(2);
    }
    return value;
}

void print_timestamped_message() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("[%s] Clap detected!\n", buffer);
}

int main() {
    signal(SIGINT, handle_sigint);

    setup_gpio();

    while (keep_running) {
        int adc_value = read_adc();
        if (adc_value > CLAP_THRESHOLD) {
            int current_time = (int)(time(NULL) * 1000);
            if (current_time - last_clap_time > DEBOUNCE_INTERVAL_MS) {
                last_clap_time = current_time;
                gpiod_line_set_value(led_line, 1);
                print_timestamped_message();
                usleep(LED_ON_DURATION_MS * 1000);
                gpiod_line_set_value(led_line, 0);
            }
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    return 0;
}

