#include <errno.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define RETRY_DELAY 1

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_distance(int distance) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s: Distance = %d\n", timestamp, distance);
    fclose(file);
}

int read_gpio(int fd) {
    char buf;
    if (read(fd, &buf, 1) != 1) {
        if (errno == EAGAIN) {
            return -1; // Non-blocking read would block
        }
        perror("Failed to read GPIO");
        return -1;
    }
    return buf == '1' ? 1 : 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/gpiochip0", O_RDONLY);
    if (fd == -1) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiohandle_request req;
    memset(&req, 0, sizeof(req));
    req.lineoffsets = &GPIO_PIN;
    req.flags = GPIOHANDLE_REQUEST_INPUT;
    req.lines = 1;

    int gpio_fd = ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req);
    if (gpio_fd == -1) {
        perror("Failed to get line handle");
        close(fd);
        return EXIT_FAILURE;
    }
    close(fd);

    while (keep_running) {
        int distance = read_gpio(gpio_fd);
        if (distance == -1) {
            fprintf(stderr, "Error reading GPIO, retrying...\n");
            sleep(RETRY_DELAY);
            continue;
        }

        log_distance(distance);

        if (distance) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1); // Adjust as needed for your application
    }

    if (ioctl(gpio_fd, GPIO_UNEXPORT_IOCTL, &GPIO_PIN) == -1) {
        perror("Failed to unexport GPIO");
    }

    close(gpio_fd);
    return EXIT_SUCCESS;
}

