#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define ADC_CHANNEL 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "soil_moisture.log"

static volatile sig_atomic_t keep_running = 1;
static int pump_gpio_chip;
static struct gpiod_line *pump_line;
static int log_fd = -1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int init_gpio() {
    pump_gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!pump_gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    pump_line = gpiod_chip_get_line(pump_gpio_chip, PUMP_GPIO);
    if (!pump_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(pump_gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(pump_line, "pump_control", 0)) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(pump_gpio_chip);
        return -1;
    }

    return 0;
}

int init_spi() {
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    uint32_t speed = SPI_MAX_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

int read_adc(int spi_fd) {
    uint8_t tx[] = {0x01, (8 + ADC_CHANNEL) << 4, 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to read from SPI device");
        return -1;
    }

    uint16_t adc_value = (rx[1] & 0x03) << 8 | rx[2];
    return adc_value;
}

int convert_to_moisture_percentage(uint16_t adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        return -1;
    }
    return (1023 - adc_value) * 100 / 1023;
}

void log_moisture(int moisture, int pump_status) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    dprintf(log_fd, "%s - Moisture: %d%%, Pump: %s\n", timestamp, moisture, pump_status ? "ON" : "OFF");
}

void cleanup(int spi_fd) {
    if (pump_line) {
        gpiod_line_release(pump_line);
    }
    if (pump_gpio_chip) {
        gpiod_chip_close(pump_gpio_chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
}

int main() {
    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handler\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    int spi_fd = init_spi();
    if (spi_fd < 0) {
        cleanup(spi_fd);
        return EXIT_FAILURE;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        cleanup(spi_fd);
        return EXIT_FAILURE;
    }

    int pump_status = 0;

    while (keep_running) {
        int adc_value = read_adc(spi_fd);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        int moisture = convert_to_moisture_percentage(adc_value);
        if (moisture < 0) {
            fprintf(stderr, "Invalid ADC value\n");
            continue;
        }

        if (moisture < MOISTURE_THRESHOLD && !pump_status) {
            gpiod_line_set_value(pump_line, 1);
            pump_status = 1;
