    if (pump_line) {
        gpiod_line_release(pump_line);
    }
    if (pump_gpio_chip) {
        gpiod_chip_close(pump_gpio_chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
}

int main() {
    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handler\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    int spi_fd = init_spi();
    if (spi_fd < 0) {
        cleanup(spi_fd);
        return EXIT_FAILURE;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        cleanup(spi_fd);
        return EXIT_FAILURE;
    }

    int pump_status = 0;

    while (keep_running) {
        int adc_value = read_adc(spi_fd);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        int moisture = convert_to_moisture_percentage(adc_value);
        if (moisture < 0) {
            fprintf(stderr, "Invalid ADC value\n");
            continue;
        }

        if (moisture < MOISTURE_THRESHOLD && !pump_status) {
            gpiod_line_set_value(pump_line, 1);
            pump_status = 1;
        } else if (moisture >= MOISTURE_THRESHOLD && pump_status) {
            gpiod_line_set_value(pump_line, 0);
            pump_status = 0;
        }

        log_moisture(moisture, pump_status);
        sleep(60);
    }

    // Ensure pump is off on exit
    if (pump_status) {
        gpiod_line_set_value(pump_line, 0);
    }

    cleanup(spi_fd);
    return EXIT_SUCCESS;
