#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define LED_GPIO 21
#define THRESHOLD 10.0
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL 100000000 // 100 ms in nanoseconds

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void cleanup(int spi_fd, int led_gpio) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (led_gpio >= 0) {
        gpioWrite(led_gpio, 0);
        gpioTerminate();
    }
}

int main() {
    int spi_fd, led_gpio;
    FILE *log_file;
    struct timespec ts;
    uint8_t tx_buf[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
    uint8_t rx_buf[3] = {0};
    float voltage, magnetic_field;
    int adc_value;

    // Install SIGINT handler
    signal(SIGINT, handle_sigint);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up LED GPIO
    led_gpio = gpioOpen(LED_GPIO, O_RDWR);
    if (led_gpio < 0) {
        fprintf(stderr, "Failed to open LED GPIO\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure SPI
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = sizeof(tx_buf),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Failed to configure SPI\n");
        close(spi_fd);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(spi_fd);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Send SPI command
        if (write(spi_fd, tx_buf, sizeof(tx_buf)) != sizeof(tx_buf)) {
            fprintf(stderr, "Failed to write to SPI\n");
            break;
        }

        // Read SPI response
        if (read(spi_fd, rx_buf, sizeof(rx_buf)) != sizeof(rx_buf)) {
            fprintf(stderr, "Failed to read from SPI\n");
            break;
        }

        // Convert ADC value
        adc_value = ((rx_buf[1] & 3) << 8) | rx_buf[2];
        voltage = adc_value * 3.3 / 1023.0;
        magnetic_field = voltage * 1000.0; // Assuming 1V = 1000 mT for conversion

        // Log the reading with timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld: %f mT\n", ts.tv_sec, ts.tv_nsec, magnetic_field);
        fflush(log_file);

        // Control LED based on threshold
        if (magnetic_field > THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        // Sleep for the sample interval
        nanosleep(&ts, NULL);
        ts.tv_nsec += SAMPLE_INTERVAL;
        ts.tv_sec += ts.tv_nsec / 1000000000;
        ts.tv_nsec %= 1000000000;
    }

    // Cleanup
    cleanup(spi_fd, led_gpio);
    fclose(log_file);

    return EXIT_SUCCESS;
}

