#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <poll.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_PIN 17
#define ADC_CHANNEL 0
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define ADC_BITS 10
#define ADC_MAX_VALUE (1 << ADC_BITS)
#define VREF 5.0
#define ADC_CHANNEL_MASK (1 << ADC_CHANNEL)

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_spi_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_MAX_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

int configure_gpio(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "current_sensor_enable", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(line, 1);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

int read_adc(int spi_fd, uint8_t channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to read from SPI device");
        return -1;
    }

    uint16_t adc_value = (rx[1] & 3) << 8 | rx[2];
    return adc_value;
}

double convert_to_amperes(uint16_t adc_value) {
    double voltage = (adc_value / (double)ADC_MAX_VALUE) * VREF;
    return voltage / 0.1; // 100 mV/A
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int spi_fd = open_spi_device(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    if (configure_gpio(GPIO_PIN) < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint16_t adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC\n");
            break;
        }

        double current = convert_to_amperes(adc_value);
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%f\n", timestamp, current);
        fflush(log_file);

        sleep(1);
    }

    gpiod_line_request_output(gpiod_chip_get_line(gpiod_chip_open("/dev/gpiochip0"), GPIO_PIN), "current_sensor_enable", 0);
    gpiod_chip_close(gpiod_chip_open("/dev/gpiochip0"));
    fclose(log_file);
    close(spi_fd);

    return EXIT_SUCCESS;
}

