#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define SPI_SPEED 1000000
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds
#define VREF 5.0
#define ADC_MAX 1023

volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int sig) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioSetMode(8, PI_OUTPUT) < 0 || gpioSetMode(10, PI_OUTPUT) < 0 ||
        gpioSetMode(9, PI_INPUT) < 0 || gpioSetMode(11, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSPIClassMode(SPI_CHANNEL, PI_SPI_MODE0) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (!stop_flag) {
        unsigned int adc_value;
        if (gpioSPIDataRW(SPI_CHANNEL, &adc_value, 3) < 0) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        // Extract the 10-bit ADC value from the 3-byte response
        adc_value = (adc_value >> 16) & 0x03FF;

        if (adc_value > ADC_MAX) {
            fprintf(stderr, "Measured voltage out of range\n");
            continue;
        }

        double voltage = (adc_value / (double)ADC_MAX) * VREF;
        double current = voltage; // Assuming 1:1 conversion for simplicity

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s %.2f A\n", time_str, current);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

