#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define DEBOUNCE_READS 5
#define DEBOUNCE_DELAY_MS 2
#define LOG_INTERVAL 1

static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int read_sensor(gpiod_line *line) {
    int value;
    for (int i = 0; i < DEBOUNCE_READS; i++) {
        value += gpiod_line_get_value(line);
        usleep(DEBOUNCE_DELAY_MS * 1000);
    }
    return value > (DEBOUNCE_READS / 2);
}

void log_sensor_state(gpiod_chip *chip, gpiod_line *line1, gpiod_line *line2) {
    int state1 = read_sensor(line1);
    int state2 = read_sensor(line2);

    printf("%d %d\n", state1, state2);

    if (state1 == 0 && state2 == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    gpiod_line *line1 = gpiod_chip_get_line(chip, 4);
    if (!line1) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line *line2 = gpiod_chip_get_line(chip, 17);
    if (!line2) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line1, "sensor1", GPIOD_LINE_REQ_EV_NONE) < 0) {
        perror("gpiod_line_request_input");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line2, "sensor2", GPIOD_LINE_REQ_EV_NONE) < 0) {
        perror("gpiod_line_request_input");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        log_sensor_state(chip, line1, line2);
        sleep(LOG_INTERVAL);
    }

    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

