volatile sig_atomic_t stop_flag = 0;

typedef struct {
    int spi_channel;
    int baud;
} spi_config_t;

void signal_handler(int signal) {
    stop_flag = 1;
}

int spi_setup(spi_config_t config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return -1;
    }

    int spi_handle = spiOpen(0, config.baud, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        gpioTerminate();
        return -1;
    }

    return spi_handle;
}

int read_mcp3008(int spi_handle, int channel) {
    unsigned char tx[] = {0b11000000 | (channel & 0x07) << 4, 0, 0};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed, retrying...\n");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) adc_value = MIN_ADC;
    if (adc_value > MAX_ADC) adc_value = MAX_ADC;

    return ((adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
}

void log_data(double moisture_level) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file, continuing...\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s,%.2f\n", timestamp, moisture_level);
    printf("%s,%.2f\n", timestamp, moisture_level);

    fclose(file);
}

int main() {
    signal(SIGINT, signal_handler);

    spi_config_t config = {SPI_CHANNEL, SPI_BAUD};
    int spi_handle = spi_setup(config);
    if (spi_handle < 0) {
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        int adc_value = read_mcp3008(spi_handle, MCP3008_CHANNEL);
        if (adc_value < 0) {
            sleep(1);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        log_data(moisture_level);

        sleep(READ_DELAY);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

