#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/wait.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define POLL_INTERVAL_MS 50
#define OUTPUT_DIR "/home/pi/security_cam"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(const char *message) {
    openlog("PIR_Motion_Detector", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "%s", message);
    closelog();
}

int ensure_directory_exists(const char *dir) {
    struct stat st = {0};
    if (stat(dir, &st) == -1) {
        if (mkdir(dir, 0700) == -1) {
            log_event("Failed to create directory");
            return -1;
        }
    }
    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    int last_state = 0;
    int current_state;
    time_t now;
    struct tm *tm_info;
    char filename[256];
    pid_t pid;
    int status;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_event("Starting PIR Motion Detector");

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_event("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        log_event("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "PIR_Motion_Detector", GPIOD_LINE_REQ_DIR_NONE);
    if (ret < 0) {
        log_event("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ensure_directory_exists(OUTPUT_DIR) != 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        usleep(POLL_INTERVAL_MS * 1000);
        current_state = gpiod_line_get_value(line);

        if (current_state != last_state) {
            usleep(DEBOUNCE_DELAY_MS * 1000);
            current_state = gpiod_line_get_value(line);

            if (current_state != last_state) {
                last_state = current_state;

                if (current_state) {
                    log_event("Motion detected");

                    now = time(NULL);
                    tm_info = localtime(&now);
                    snprintf(filename, sizeof(filename), "%s/motion_%04d-%02d-%02dT%02d-%02d-%02d.jpg",
                             OUTPUT_DIR, tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                             tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec);

                    pid = fork();
                    if (pid == 0) {
                        execlp("libcamera-still", "libcamera-still", "-o", filename, (char *)NULL);
                        _exit(EXIT_FAILURE);
                    } else if (pid > 0) {
                        waitpid(pid, &status, 0);
                        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
                            log_event("Capture successful");
                        } else {
                            log_event("Capture failed");
                        }
                    } else {
                        log_event("Failed to fork process");
                    }
                }
            }
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    log_event("Shutting down PIR Motion Detector");

    return EXIT_SUCCESS;
}

