#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>
#include <linux/videodev2.h>

#define DEFAULT_DEVICE "/dev/video0"
#define BUFFER_COUNT 1
#define TIMEOUT_SEC 2
#define TIMEOUT_USEC 0

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int sig) {
    stop_flag = 1;
}

int open_device(const char *device) {
    int fd = open(device, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device, strerror(errno));
    }
    return fd;
}

int init_device(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying device capabilities: %s\n", strerror(errno));
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting pixel format: %s\n", strerror(errno));
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int mmap_buffers(int fd, struct v4l2_buffer *buffers, void **start, size_t *length) {
    for (int i = 0; i < BUFFER_COUNT; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer %d: %s\n", i, strerror(errno));
            return -1;
        }

        start[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (start[i] == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            return -1;
        }

        buffers[i] = buf;
        length[i] = buf.length;
    }
    return 0;
}

int queue_buffer(int fd, struct v4l2_buffer *buf) {
    if (ioctl(fd, VIDIOC_QBUF, buf) < 0) {
        fprintf(stderr, "Error queueing buffer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int dequeue_buffer(int fd, struct v4l2_buffer *buf) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = TIMEOUT_SEC;
    tv.tv_usec = TIMEOUT_USEC;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout occurred during select\n");
        return 0;
    }

    if (ioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        if (errno == EAGAIN) {
            fprintf(stderr, "EAGAIN encountered during dequeue\n");
            return 0;
        }
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }
    return 1;
}

int save_frame(void *start, size_t length, int frame_number) {
    char filename[32];
    snprintf(filename, sizeof(filename), "image_%04d.pgm", frame_number);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fprintf(file, "P5\n%d %d\n255\n", 640, 480);
    if (fwrite(start, 1, length, file) != length) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

void cleanup(int fd, struct v4l2_buffer *buffers, void **start, size_t *length) {
    for (int i = 0; i < BUFFER_COUNT; ++i) {
        if (start[i]) {
            munmap(start[i], length[i]);
        }
    }
    close(fd);
}

int main(int argc, char *argv[]) {
    const char *device = argc > 1 ? argv[1] : DEFAULT_DEVICE;
    int fd = open_device(device);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    if (init_device(fd) < 0) {
        cleanup(fd, NULL, NULL, NULL);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buffers[BUFFER_COUNT];
    void *start[BUFFER_COUNT];
    size_t length[BUFFER_COUNT];

    if (mmap_buffers(fd, buffers, start, length) < 0) {
        cleanup(fd, buffers, start, length);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < BUFFER_COUNT; ++i) {
        if (queue_buffer(fd, &buffers[i]) < 0) {
            cleanup(fd, buffers, start, length);
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int frame_number = 1;
    while (!stop_flag) {
        struct v4l2_buffer buf = buffers[0];
        int ret = dequeue_buffer(fd, &buf);
        if (ret == 1) {
            if (save_frame(start[buf.index], buf.bytesused, frame_number++) < 0) {
                cleanup(fd, buffers, start, length);
                return EXIT_FAILURE;
            }
            if (queue_buffer(fd, &buf) < 0) {
                cleanup(fd, buffers, start, length);
                return EXIT_FAILURE;
            }
        }
    }

    cleanup(fd, buffers, start, length);
    return EXIT_SUCCESS;
}

