#define DEVICE "/dev/video0"
#define BUFFER_COUNT 4
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define MAX_UDP_PAYLOAD 65507
#define YUYV_PIXEL_SIZE 2
#define YUYV_FRAME_SIZE (FRAME_WIDTH * FRAME_HEIGHT * YUYV_PIXEL_SIZE)

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_device(const char *device) {
    int fd = open(device, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Failed to open device");
        exit(EXIT_FAILURE);
    }
    return fd;
}

void init_device(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        exit(EXIT_FAILURE);
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set device format");
        exit(EXIT_FAILURE);
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        exit(EXIT_FAILURE);
    }

    struct v4l2_buffer buf;
    for (int i = 0; i < BUFFER_COUNT; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Failed to query buffer");
            exit(EXIT_FAILURE);
        }

        void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffer == MAP_FAILED) {
            perror("Failed to mmap buffer");
            exit(EXIT_FAILURE);
        }

        buf.m.userptr = (unsigned long)buffer;
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to queue buffer");
            exit(EXIT_FAILURE);
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        exit(EXIT_FAILURE);
    }
}

void cleanup_device(int fd, void *buffers[], struct v4l2_buffer *bufs) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Failed to stop streaming");
    }

    for (int i = 0; i < BUFFER_COUNT; ++i) {
        munmap(buffers[i], bufs[i].length);
    }

    close(fd);
}

void send_frame(int sockfd, struct sockaddr_in *addr, void *buffer, int frame_index) {
    int frame_size = YUYV_FRAME_SIZE;
    int fragment_size = MAX_UDP_PAYLOAD;
    int total_fragments = (frame_size + fragment_size - 1) / fragment_size;

    for (int frag_index = 0; frag_index < total_fragments; ++frag_index) {
        int payload_size = (frame_size - frag_index * fragment_size < fragment_size) ?
                           (frame_size - frag_index * fragment_size) : fragment_size;

        unsigned char header[12];
        header[0] = frame_index >> 24;
        header[1] = frame_index >> 16;
        header[2] = frame_index >> 8;
        header[3] = frame_index;
        header[4] = frag_index >> 24;
        header[5] = frag_index >> 16;
        header[6] = frag_index >> 8;
        header[7] = frag_index;
        header[8] = total_fragments >> 8;
        header[9] = total_fragments;
        header[10] = payload_size >> 8;
        header[11] = payload_size;

        unsigned char *payload = malloc(payload_size + 12);
        memcpy(payload, header, 12);
        memcpy(payload + 12, ((unsigned char *)buffer) + frag_index * fragment_size, payload_size);

        if (sendto(sockfd, payload, payload_size + 12, 0, (struct sockaddr *)addr, sizeof(*addr)) < 0) {
            perror("Failed to send UDP packet");
        }

        free(payload);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <target_ip> <target_port> <frame_index>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *target_ip = argv[1];
    int target_port = atoi(argv[2]);
    int frame_index = atoi(argv[3]);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int fd = open_device(DEVICE);
    init_device(fd);

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Failed to create socket");
        cleanup_device(fd, NULL, NULL);
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(target_port);
    if (inet_pton(AF_INET, target_ip, &addr.sin_addr) <= 0) {
        perror("Invalid target IP address");
        close(sockfd);
        cleanup_device(fd, NULL, NULL);
        exit(EXIT_FAILURE);
    }

    void *buffers[BUFFER_COUNT];
    struct v4l2_buffer bufs[BUFFER_COUNT];
    for (int i = 0; i < BUFFER_COUNT; ++i) {
        memset(&bufs[i], 0, sizeof(bufs[i]));
        bufs[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        bufs[i].memory = V4L2_MEMORY_MMAP;
        bufs[i].index = i;

        if (ioctl(fd, VIDIOC_DQBUF, &bufs[i]) < 0) {
            perror("Failed to dequeue buffer");
            close(sockfd);
            cleanup_device(fd, buffers, bufs);
            exit(EXIT_FAILURE);
        }

        buffers[i] = mmap(NULL, bufs[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, bufs[i].m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Failed to mmap buffer");
            close(sockfd);
            cleanup_device(fd, buffers, bufs);
            exit(EXIT_FAILURE);
        }

        if (ioctl(fd, VIDIOC_QBUF, &bufs[i]) < 0) {
            perror("Failed to queue buffer");
            close(sockfd);
            cleanup_device(fd, buffers, bufs);
            exit(EXIT_FAILURE);
        }
    }

    while (keep_running) {
        for (int i = 0; i < BUFFER_COUNT; ++i) {
            if (ioctl(fd, VIDIOC_DQBUF, &bufs[i]) < 0) {
                perror("Failed to dequeue buffer");
                close(sockfd);
                cleanup_device(fd, buffers, bufs);
                exit(EXIT_FAILURE);
            }

            send_frame(sockfd, &addr, buffers[i], frame_index++);
            if (ioctl(fd, VIDIOC_QBUF, &bufs[i]) < 0) {
                perror("Failed to queue buffer");
                close(sockfd);
                cleanup_device(fd, buffers, bufs);
                exit(EXIT_FAILURE);
            }
        }
    }

    cleanup_device(fd, buffers, bufs);
    close(sockfd);
    return 0;
