#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define PAN_GPIO 4
#define TILT_GPIO 5
#define TILT_UP_GPIO 6
#define TILT_DOWN_GPIO 7
#define PAN_LEFT_GPIO 8
#define PAN_RIGHT_GPIO 9

#define PWM_PERIOD_NS 20000000 // 20 ms
#define PWM_MIN_DUTY_NS 1000000 // 1 ms
#define PWM_MAX_DUTY_NS 2000000 // 2 ms
#define PWM_STEP_DUTY_NS 50000 // 50 us
#define PWM_MID_DUTY_NS 1500000 // 1.5 ms

#define BUTTON_POLL_INTERVAL_MS 50

static volatile int keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int setup_gpio_chip(gpiod_chip **chip) {
    *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!*chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    return 0;
}

int setup_gpio_line(gpiod_chip *chip, int gpio, int flags, gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, gpio);
    if (!*line) {
        perror("Failed to get GPIO line");
        return -1;
    }
    if (gpiod_line_request(*line, "servo_button", flags) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_unref(*line);
        return -1;
    }
    return 0;
}

int setup_pwm(gpiod_chip *chip, int gpio, gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, gpio);
    if (!*line) {
        perror("Failed to get PWM line");
        return -1;
    }
    if (gpiod_line_request(*line, "servo_pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0) {
        perror("Failed to request PWM line");
        gpiod_line_unref(*line);
        return -1;
    }
    if (gpiod_line_set_flags(*line, GPIOD_LINE_FLAG_ACTIVE_LOW) < 0) {
        perror("Failed to set active low flag");
        gpiod_line_unref(*line);
        return -1;
    }
    if (gpiod_line_set_period(*line, PWM_PERIOD_NS) < 0) {
        perror("Failed to set PWM period");
        gpiod_line_unref(*line);
        return -1;
    }
    return 0;
}

void set_pwm_duty(gpiod_line *line, int duty_ns) {
    if (gpiod_line_set_usec_val(*line, duty_ns / 1000) < 0) {
        perror("Failed to set PWM duty");
    }
}

void adjust_servo(gpiod_line *line, int *position) {
    int new_position = *position + 5;
    if (new_position > 125) new_position = 125;
    if (new_position < 25) new_position = 25;
    int duty_ns = PWM_MIN_DUTY_NS + (new_position - 25) * PWM_STEP_DUTY_NS;
    set_pwm_duty(line, duty_ns);
    *position = new_position;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    gpiod_chip *chip;
    if (setup_gpio_chip(&chip) < 0) {
        return EXIT_FAILURE;
    }

    gpiod_line *pan_line, *tilt_line;
    if (setup_pwm(chip, PAN_GPIO, &pan_line) < 0 || setup_pwm(chip, TILT_GPIO, &tilt_line) < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line *tilt_up_line, *tilt_down_line, *pan_left_line, *pan_right_line;
    if (setup_gpio_line(chip, TILT_UP_GPIO, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_OPEN_DRAIN | GPIOD_LINE_REQUEST_DEBOUNCE, &tilt_up_line) < 0 ||
        setup_gpio_line(chip, TILT_DOWN_GPIO, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_OPEN_DRAIN | GPIOD_LINE_REQUEST_DEBOUNCE, &tilt_down_line) < 0 ||
        setup_gpio_line(chip, PAN_LEFT_GPIO, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_OPEN_DRAIN | GPIOD_LINE_REQUEST_DEBOUNCE, &pan_left_line) < 0 ||
        setup_gpio_line(chip, PAN_RIGHT_GPIO, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_OPEN_DRAIN | GPIOD_LINE_REQUEST_DEBOUNCE, &pan_right_line) < 0) {
        gpiod_line_unref(pan_line);
        gpiod_line_unref(tilt_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    set_pwm_duty(pan_line, PWM_MID_DUTY_NS);
