int setup_gpio_chip(gpiod_chip **chip) {
    *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!*chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    return 0;
}

int setup_gpio_line(gpiod_chip *chip, int gpio, int flags, gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, gpio);
    if (!*line) {
        perror("Failed to get GPIO line");
        return -1;
    }
    if (gpiod_line_request(*line, "servo_button", flags) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_unref(*line);
        return -1;
    }
    return 0;
}

int setup_pwm(gpiod_chip *chip, int gpio, gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, gpio);
    if (!*line) {
        perror("Failed to get PWM line");
        return -1;
    }
    if (gpiod_line_request(*line, "servo_pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0) {
        perror("Failed to request PWM line");
        gpiod_line_unref(*line);
        return -1;
    }
    if (gpiod_line_set_flags(*line, GPIOD_LINE_FLAG_ACTIVE_LOW) < 0) {
        perror("Failed to set active low flag");
        gpiod_line_unref(*line);
        return -1;
    }
    if (gpiod_line_set_period(*line, PWM_PERIOD_NS) < 0) {
        perror("Failed to set PWM period");
        gpiod_line_unref(*line);
        return -1;
    }
    return 0;
}

