#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <linux/videodev2.h>
#include <jpeglib.h>

#define DEVICE "/dev/video0"
#define TIMEOUT 2
#define JPEG_QUALITY 75

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int open_device(const char *device) {
    int fd = open(device, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Failed to open device");
        return -1;
    }
    return fd;
}

int init_device(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set device format");
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Failed to query buffer");
        return -1;
    }

    void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Failed to mmap buffer");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Failed to queue buffer");
        munmap(buffer, buf.length);
        return -1;
    }

    struct v4l2_buffer buf_out;
    memset(&buf_out, 0, sizeof(buf_out));
    buf_out.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf_out.memory = V4L2_MEMORY_MMAP;

    struct v4l2_streamparm parm;
    memset(&parm, 0, sizeof(parm));
    parm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    parm.parm.capture.timeperframe.numerator = 1;
    parm.parm.capture.timeperframe.denominator = 30;

    if (ioctl(fd, VIDIOC_S_PARM, &parm) < 0) {
        perror("Failed to set streaming parameters");
        munmap(buffer, buf.length);
        return -1;
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf_out.type) < 0) {
        perror("Failed to start streaming");
        munmap(buffer, buf.length);
        return -1;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    while (keep_running) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = TIMEOUT;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR) continue;
            perror("Select error");
            munmap(buffer, buf.length);
            return -1;
        } else if (r == 0) {
            printf("Timeout occurred, no frame captured\n");
            continue;
        }

        if (ioctl(fd, VIDIOC_DQBUF, &buf_out) < 0) {
            perror("Failed to dequeue buffer");
            munmap(buffer, buf.length);
            return -1;
        }

        // Process the frame
        process_frame(buffer, buf_out.length);

        if (ioctl(fd, VIDIOC_QBUF, &buf_out) < 0) {
            perror("Failed to requeue buffer");
            munmap(buffer, buf.length);
            return -1;
        }
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &buf_out.type) < 0) {
        perror("Failed to stop streaming");
        munmap(buffer, buf.length);
        return -1;
    }

    munmap(buffer, buf.length);
    return 0;
}

void process_frame(void *buffer, size_t length) {
    // Convert YUYV to RGB24
    unsigned char *yuyv = buffer;
    unsigned char *rgb = malloc(640 * 480 * 3);
    if (!rgb) {
        perror("Failed to allocate RGB buffer");
        return;
    }

    for (int i = 0; i < 480; i++) {
        for (int j = 0; j < 640; j += 2) {
            int y1 = yuyv[i * 640 * 2 + j * 2];
            int u = yuyv[i * 640 * 2 + j * 2 + 1] - 128;
            int y2 = yuyv[i * 640 * 2 + j * 2 + 2];
            int v = yuyv[i * 640 * 2 + j * 2 + 3] - 128;

            int c = y1 - 16;
            int d = u;
            int e = v;

            int r = (298 * c + 409 * e + 128) >> 8;
            int g = (298 * c - 100 * d - 208 * e + 128) >> 8;
            int b = (298 * c + 516 * d + 128) >> 8;

            r = r < 0 ? 0 : r > 255 ? 255 : r;
            g = g < 0 ? 0 : g > 255 ? 255 : g;
            b = b < 0 ? 0 : b > 255 ? 255 : b;

            rgb[(i * 640 + j) * 3] = r;
            rgb[(i * 640 + j) * 3 + 1] = g;
            rgb[(i * 640 + j) * 3 + 2] = b;

            c = y2 - 16;

            r = (298 * c + 409 * e + 128) >> 8;
            g = (298 * c - 100 * d - 208 * e + 128) >> 8;
            b = (298 * c + 516 * d + 128) >> 8;

            r = r < 0 ? 0 : r > 255 ? 255 : r;
            g = g < 0 ? 0 : g > 255 ? 255 : g;
            b = b < 0 ? 0 : b > 255 ? 255 : b;

            rgb[(i * 640 + j + 1) * 3] = r;
            rgb[(i * 640 + j + 1) * 3 + 1] = g;
            rgb[(i * 640 + j + 1) * 3 + 2] = b;
        }
    }

    // Apply blur filter
    apply_blur(rgb, 640, 480);

    // Save as JPEG
    save_as_jpeg(rgb, 640, 480);

    free(rgb);
}

void apply_blur(unsigned char *rgb, int width, int height) {
    unsigned char *temp = malloc(width * height * 3);
    if (!temp) {
        perror("Failed to allocate temporary buffer for blur");
        return;
    }

    for (int i = 1; i < height - 1; i++) {
        for (int j = 1; j < width - 1; j++) {
            int r = 0, g = 0, b = 0;
            for (int di = -1; di <= 1; di++) {
                for (int dj = -1; dj <= 1; dj++) {
                    int idx = ((i + di) * width + (j + dj)) * 3;
                    r += rgb[idx];
                    g += rgb[idx + 1];
                    b += rgb[idx + 2];
                }
            }
            int idx = (i * width + j) * 3;
            temp[idx] = r / 9;
            temp[idx + 1] = g / 9;
            temp[idx + 2] = b / 9;
        }
    }

    memcpy(rgb, temp, width * height * 3);
    free(temp);
}

void save_as_jpeg(unsigned char *rgb, int width, int height) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    char filename[64];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    snprintf(filename, sizeof(filename), "capture_%04d%02d%02d_%02d%02d%02d.jpg",
             tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
             tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        perror("Failed to open JPEG file");
        return;
    }

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row_pointer[1];
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb[cinfo.next_scanline * width * 3];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    fclose(outfile);
}

int main() {
    signal(SIGINT, handle_sigint);

    int fd = open_device(DEVICE);
    if (fd < 0) return EXIT_FAILURE;

    if (init_device(fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    close(fd);
    return EXIT_SUCCESS;
}

