            b = b < 0 ? 0 : b > 255 ? 255 : b;

            rgb[(i * 640 + j + 1) * 3] = r;
            rgb[(i * 640 + j + 1) * 3 + 1] = g;
            rgb[(i * 640 + j + 1) * 3 + 2] = b;
        }
    }

    // Apply blur filter
    apply_blur(rgb, 640, 480);

    // Save as JPEG
    save_as_jpeg(rgb, 640, 480);

    free(rgb);
}

void apply_blur(unsigned char *rgb, int width, int height) {
    unsigned char *temp = malloc(width * height * 3);
    if (!temp) {
        perror("Failed to allocate temporary buffer for blur");
        return;
    }

    for (int i = 1; i < height - 1; i++) {
        for (int j = 1; j < width - 1; j++) {
            int r = 0, g = 0, b = 0;
            for (int di = -1; di <= 1; di++) {
                for (int dj = -1; dj <= 1; dj++) {
                    int idx = ((i + di) * width + (j + dj)) * 3;
                    r += rgb[idx];
                    g += rgb[idx + 1];
                    b += rgb[idx + 2];
                }
            }
            int idx = (i * width + j) * 3;
            temp[idx] = r / 9;
            temp[idx + 1] = g / 9;
            temp[idx + 2] = b / 9;
        }
    }

    memcpy(rgb, temp, width * height * 3);
    free(temp);
}

void save_as_jpeg(unsigned char *rgb, int width, int height) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    char filename[64];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    snprintf(filename, sizeof(filename), "capture_%04d%02d%02d_%02d%02d%02d.jpg",
             tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
             tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        perror("Failed to open JPEG file");
        return;
    }

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row_pointer[1];
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb[cinfo.next_scanline * width * 3];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    fclose(outfile);
}

int main() {
    signal(SIGINT, handle_sigint);

    int fd = open_device(DEVICE);
    if (fd < 0) return EXIT_FAILURE;

    if (init_device(fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    close(fd);
    return EXIT_SUCCESS;
}
