#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <string.h>

#define DEVICE "/dev/video0"

int main() {
    int fd = open(DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open device");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_fmtdesc fmt;
    fmt.index = 0;
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) == 0) {
        struct v4l2_frmsizeenum frmsize;
        frmsize.pixel_format = fmt.pixelformat;
        frmsize.index = 0;

        while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
            printf("Format: %s\n", fmt.description);
            printf("Frame Size Type: %s\n", (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) ? "Discrete" : "Continuous");
            printf("Width: %d, Height: %d\n", frmsize.discrete.width, frmsize.discrete.height);

            struct v4l2_frmivalenum frmintrvl;
            frmintrvl.pixel_format = fmt.pixelformat;
            frmintrvl.width = frmsize.discrete.width;
            frmintrvl.height = frmsize.discrete.height;
            frmintrvl.interval_type = V4L2_FRMIVAL_TYPE_DISCRETE;
            frmintrvl.index = 0;

            while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmintrvl) == 0) {
                printf("Frame Interval: %d/%d\n", frmintrvl.discrete.numerator, frmintrvl.discrete.denominator);
                frmintrvl.index++;
            }

            frmsize.index++;
        }
        fmt.index++;
    }

    struct v4l2_queryctrl ctrl;
    ctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) < 0) {
        if (errno == EINVAL) {
            printf("Autofocus control not supported\n");
        } else {
            perror("Failed to query autofocus control");
            close(fd);
            return EXIT_FAILURE;
        }
    } else {
        printf("Autofocus is %s\n", ctrl.flags & V4L2_CTRL_FLAG_DISABLED ? "disabled" : "supported");
    }

    close(fd);
    return EXIT_SUCCESS;
}

