#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define PAN_PIN 4
#define TILT_PIN 5
#define UP_BUTTON 6
#define DOWN_BUTTON 7
#define LEFT_BUTTON 8
#define RIGHT_BUTTON 9

#define PWM_FREQ 50
#define PWM_PERIOD_NS (1e9 / PWM_FREQ)
#define MIN_PULSE_WIDTH_NS 1000e3
#define MAX_PULSE_WIDTH_NS 2000e3
#define CENTER_PULSE_WIDTH_NS 1500e3
#define PULSE_INCREMENT_NS 10e3

static struct gpiod_chip *chip;
static struct gpiod_line *pan_line, *tilt_line;
static struct gpiod_line *up_button, *down_button, *left_button, *right_button;
static struct gpiod_line_event *up_event, *down_event, *left_event, *right_event;
static int pan_pwm, tilt_pwm;

void cleanup_and_exit(int signum) {
    if (pan_pwm) gpiod_pwm_stop(pan_pwm);
    if (tilt_pwm) gpiod_pwm_stop(tilt_pwm);
    gpiod_line_release(pan_line);
    gpiod_line_release(tilt_line);
    gpiod_line_release(up_button);
    gpiod_line_release(down_button);
    gpiod_line_release(left_button);
    gpiod_line_release(right_button);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    int ret;

    // Initialize signal handlers
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request PWM lines for pan and tilt servos
    pan_line = gpiod_chip_get_line(chip, PAN_PIN);
    tilt_line = gpiod_chip_get_line(chip, TILT_PIN);
    if (!pan_line || !tilt_line) {
        fprintf(stderr, "Failed to get PWM lines\n");
        cleanup_and_exit(0);
    }

    ret = gpiod_line_request(pan_line, "pan_servo", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    if (ret) {
        fprintf(stderr, "Failed to request pan line: %s\n", gpiod_strerror(ret));
        cleanup_and_exit(0);
    }

    ret = gpiod_line_request(tilt_line, "tilt_servo", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    if (ret) {
        fprintf(stderr, "Failed to request tilt line: %s\n", gpiod_strerror(ret));
        cleanup_and_exit(0);
    }

    // Request input lines for buttons
    up_button = gpiod_chip_get_line(chip, UP_BUTTON);
    down_button = gpiod_chip_get_line(chip, DOWN_BUTTON);
    left_button = gpiod_chip_get_line(chip, LEFT_BUTTON);
    right_button = gpiod_chip_get_line(chip, RIGHT_BUTTON);
    if (!up_button || !down_button || !left_button || !right_button) {
        fprintf(stderr, "Failed to get button lines\n");
        cleanup_and_exit(0);
    }

    ret = gpiod_line_request(up_button, "up_button", GPIOD_LINE_REQUEST_DIRECTIONS_INPUT);
    if (ret) {
        fprintf(stderr, "Failed to request up button: %s\n", gpiod_strerror(ret));
        cleanup_and_exit(0);
    }

    ret = gpiod_line_request(down_button, "down_button", GPIOD_LINE_REQUEST_DIRECTIONS_INPUT);
    if (ret) {
        fprintf(stderr, "Failed to request down button: %s\n", gpiod_strerror(ret));
        cleanup_and_exit(0);
    }

    ret = gpiod_line_request(left_button, "left_button", GPIOD_LINE_REQUEST_DIRECTIONS_INPUT);
    if (ret) {
        fprintf(stderr, "Failed to request left button: %s\n", gpiod_strerror(ret));
        cleanup_and_exit(0);
    }

    ret = gpiod_line_request(right_button, "right_button", GPIOD_LINE_REQUEST_DIRECTIONS_INPUT);
    if (ret) {
        fprintf(stderr, "Failed to request right button: %s\n", gpiod_strerror(ret));
        cleanup_and_exit(0);
    }

    // Set up button events
    up_event = gpiod_line_event_alloc(up_button, GPIOD_LINE_EVENT_FALLING_EDGE);
    down_event = gpiod_line_event_alloc(down_button, GPIOD_LINE_EVENT_FALLING_EDGE);
    left_event = gpiod_line_event_alloc(left_button, GPIOD_LINE_EVENT_FALLING_EDGE);
    right_event = gpiod_line_event_alloc(right_button, GPIOD_LINE_EVENT_FALLING_EDGE);

    if (!up_event || !down_event || !left_event || !right_event) {
        fprintf(stderr, "Failed to allocate button events\n");
        cleanup_and_exit(0);
    }

    // Set up PWM for pan and tilt servos
    pan_pwm = gpiod_line_request(pan_line, "pan_pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT | GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    tilt_pwm = gpiod_line_request(tilt_line, "tilt_pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT | GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);

    if (pan_pwm < 0 || tilt_pwm < 0) {
        fprintf(stderr, "Failed to request PWM lines: %s\n", gpiod_strerror(pan_pwm < 0 ? pan_pwm : tilt_pwm));
        cleanup_and_exit(0);
    }

    ret = gpiod_pwm_new_period_ns(pan_pwm, PWM_PERIOD_NS);
    if (ret) {
        fprintf(stderr, "Failed to set PWM period for pan: %s\n", gpiod_strerror(ret));
        cleanup_and_exit(0);
    }

    ret = gpiod_pwm_new_period_ns(tilt_pwm, PWM_PERIOD_NS);
    if (ret) {
        fprintf(stderr, "Failed to set PWM period for tilt: %s\n", gpiod_strerror(ret));
        cleanup_and_exit(0);
    }

    ret = gpiod_pwm_new_pulse_width_ns(pan_pwm, CENTER_PULSE_WIDTH_NS);
    if (ret) {
        fprintf(stderr, "Failed to set initial pulse width for pan: %s\n", gpiod_strerror(ret));
        cleanup_and_exit(0);
    }

    ret = gpiod_pwm_new_pulse_width_ns(tilt_pwm, CENTER_PULSE_WIDTH_NS);
    if (ret) {
        fprintf(stderr, "Failed to set initial pulse width for tilt: %s\n", gpiod_strerror(ret));
        cleanup_and_exit(0);
    }

    ret = gpiod_pwm_enable(pan_pwm);
    if (ret) {
        fprintf(stderr, "Failed to enable PWM for pan: %s\n", gpiod_strerror(ret));
        cleanup_and_exit(0);
    }

    ret = gpiod_pwm_enable(tilt_pwm);
    if (ret) {
        fprintf(stderr, "Failed to enable PWM for tilt: %s\n", gpiod_strerror(ret));
        cleanup_and_exit(0);
    }

    printf("Initialized GPIO pins:\n");
    printf("Pan servo: GPIO%d\n", PAN_PIN);
    printf("Tilt servo: GPIO%d\n", TILT_PIN);
    printf("UP button: GPIO%d\n", UP_BUTTON);
    printf("DOWN button: GPIO%d\n", DOWN_BUTTON);
    printf("LEFT button: GPIO%d\n", LEFT_BUTTON);
    printf("RIGHT button: GPIO%d\n", RIGHT_BUTTON);
    printf("Center position: %d us\n", CENTER_PULSE_WIDTH_NS / 1e3);

    while (1) {
        if (gpiod_line_event_wait(up_event, -1) == 0) {
            int new_pulse = gpiod_pwm_get_pulse_width_ns(pan_pwm) - PULSE_INCREMENT_NS;
            if (new_pulse >= MIN_PULSE_WIDTH_NS) {
                gpiod_pwm_set_pulse_width_ns(pan_pwm, new_pulse);
            }
        }

        if (gpiod_line_event_wait(down_event, -1) == 0) {
            int new_pulse = gpiod_pwm_get_pulse_width_ns(pan_pwm) + PULSE_INCREMENT_NS;
            if (new_pulse <= MAX_PULSE_WIDTH_NS) {
                gpiod_pwm_set_pulse_width_ns(pan_pwm, new_pulse);
            }
        }

        if (gpiod_line_event_wait(left_event, -1) == 0) {
            int new_pulse = gpiod_pwm_get_pulse_width_ns(tilt_pwm) - PULSE_INCREMENT_NS;
            if (new_pulse >= MIN_PULSE_WIDTH_NS) {
                gpiod_pwm_set_pulse_width_ns(tilt_pwm, new_pulse);
            }
        }

        if (gpiod_line_event_wait(right_event, -1) == 0) {
            int new_pulse = gpiod_pwm_get_pulse_width_ns(tilt_pwm) + PULSE_INCREMENT_NS;
            if (new_pulse <= MAX_PULSE_WIDTH_NS) {
                gpiod_pwm_set_pulse_width_ns(tilt_pwm, new_pulse);
            }
        }

        usleep(50000); // 50 ms delay
    }

    return 0;
}

