    ret = gpiod_pwm_enable(tilt_pwm);
    if (ret) {
        fprintf(stderr, "Failed to enable PWM for tilt: %s\n", gpiod_strerror(ret));
        cleanup_and_exit(0);
    }

    printf("Initialized GPIO pins:\n");
    printf("Pan servo: GPIO%d\n", PAN_PIN);
    printf("Tilt servo: GPIO%d\n", TILT_PIN);
    printf("UP button: GPIO%d\n", UP_BUTTON);
    printf("DOWN button: GPIO%d\n", DOWN_BUTTON);
    printf("LEFT button: GPIO%d\n", LEFT_BUTTON);
    printf("RIGHT button: GPIO%d\n", RIGHT_BUTTON);
    printf("Center position: %d us\n", CENTER_PULSE_WIDTH_NS / 1e3);

    while (1) {
        if (gpiod_line_event_wait(up_event, -1) == 0) {
            int new_pulse = gpiod_pwm_get_pulse_width_ns(pan_pwm) - PULSE_INCREMENT_NS;
            if (new_pulse >= MIN_PULSE_WIDTH_NS) {
                gpiod_pwm_set_pulse_width_ns(pan_pwm, new_pulse);
            }
        }

        if (gpiod_line_event_wait(down_event, -1) == 0) {
            int new_pulse = gpiod_pwm_get_pulse_width_ns(pan_pwm) + PULSE_INCREMENT_NS;
            if (new_pulse <= MAX_PULSE_WIDTH_NS) {
                gpiod_pwm_set_pulse_width_ns(pan_pwm, new_pulse);
            }
        }

        if (gpiod_line_event_wait(left_event, -1) == 0) {
            int new_pulse = gpiod_pwm_get_pulse_width_ns(tilt_pwm) - PULSE_INCREMENT_NS;
            if (new_pulse >= MIN_PULSE_WIDTH_NS) {
                gpiod_pwm_set_pulse_width_ns(tilt_pwm, new_pulse);
            }
        }

        if (gpiod_line_event_wait(right_event, -1) == 0) {
            int new_pulse = gpiod_pwm_get_pulse_width_ns(tilt_pwm) + PULSE_INCREMENT_NS;
            if (new_pulse <= MAX_PULSE_WIDTH_NS) {
                gpiod_pwm_set_pulse_width_ns(tilt_pwm, new_pulse);
            }
        }

        usleep(50000); // 50 ms delay
    }

    return 0;
}
