#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/wait.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 50
#define LOG_FILE "/home/pi/motion_capture.log"
#define IMAGE_DIR "/home/pi/images"
#define CAMERA_CMD "raspistill -o %s --width 640 --height 480 --quality 85 --timeout 2000 --nopreview"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

void capture_image() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char filename[64];
    snprintf(filename, sizeof(filename), "%s/%04d%02d%02d_%02d%02d%02d_%03d.jpg",
             IMAGE_DIR, tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
             tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, rand());

    char cmd[256];
    snprintf(cmd, sizeof(cmd), CAMERA_CMD, filename);

    int result = system(cmd);
    if (result == -1) {
        log_message("Failed to execute camera command");
    } else if (WIFEXITED(result) && WEXITSTATUS(result) != 0) {
        log_message("Camera command failed");
    } else {
        log_message("Image captured successfully");
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "PIR Sensor", GPIOD_LINE_REQ_EV_FALLING_EDGE);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        ret = gpiod_line_event_wait(line, DEBOUNCE_MS);
        if (ret < 0) {
            if (errno == EINTR) {
                continue; // Interrupted by signal, retry
            }
            perror("Failed to wait for GPIO event");
            break;
        }

        if (ret == 0) {
            log_message("Debounce timeout, ignoring event");
            continue;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("Failed to read GPIO event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            capture_image();
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

