#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <signal.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define TIMEOUT_SEC 2

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int sig) {
    stop_flag = 1;
}

int main() {
    int fd = open(DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open device");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "The device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Failed to query buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Failed to mmap buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Failed to queue buffer");
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    fd_set fds;
    struct timeval tv;
    int ret;

    while (!stop_flag) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = TIMEOUT_SEC;
        tv.tv_usec = 0;

        ret = select(fd + 1, &fds, NULL, NULL, &tv);
        if (ret == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("Select error");
            break;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout occurred\n");
            break;
        }

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Failed to dequeue buffer");
            break;
        }

        if (buf.bytesused != buf.length) {
            fprintf(stderr, "Incomplete frame\n");
            continue;
        }

        struct v4l2_format fmt_out;
        memset(&fmt_out, 0, sizeof(fmt_out));
        fmt_out.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(fd, VIDIOC_G_FMT, &fmt_out) < 0) {
            perror("Failed to get format");
            break;
        }

        if (fmt_out.fmt.pix.width != WIDTH || fmt_out.fmt.pix.height != HEIGHT ||
            fmt_out.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
            fprintf(stderr, "Captured frame format does not match requested format\n");
            continue;
        }

        FILE *file = fopen("cropped.yuv", "wb");
        if (!file) {
            perror("Failed to open file");
            break;
        }

        unsigned char *src = (unsigned char *)buffer;
        unsigned char *dst = malloc(CROP_WIDTH * CROP_HEIGHT * 2);
        if (!dst) {
            perror("Failed to allocate memory for cropped frame");
            fclose(file);
            break;
        }

        for (int y = 0; y < CROP_HEIGHT; ++y) {
            for (int x = 0; x < CROP_WIDTH; ++x) {
                int src_index = ((y + 50) * WIDTH + (x + 120)) * 2;
                int dst_index = (y * CROP_WIDTH + x) * 2;
                memcpy(&dst[dst_index], &src[src_index], 2);
            }
        }

        if (fwrite(dst, 1, CROP_WIDTH * CROP_HEIGHT * 2, file) != CROP_WIDTH * CROP_HEIGHT * 2) {
            perror("Failed to write to file");
            fclose(file);
            free(dst);
            break;
        }

        fclose(file);
        free(dst);

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to queue buffer");
            break;
        }
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Failed to stop streaming");
    }

    if (munmap(buffer, buf.length) < 0) {
        perror("Failed to unmap buffer");
    }

    close(fd);
    return EXIT_SUCCESS;
}

