#define NEUTRAL_POSITION 1500 // 1.5ms pulse width for 90 degrees
#define STEP_SIZE 10 // 10us per 1 degree
#define MIN_PULSE_WIDTH 500 // 0.5ms for 0 degrees
#define MAX_PULSE_WIDTH 2500 // 2.5ms for 180 degrees
#define DELAY_MS 100

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_pwm(gpiod_chip *chip, int pin, gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, pin);
    if (!*line) {
        fprintf(stderr, "Failed to get line for GPIO%d: %s\n", pin, strerror(errno));
        return -1;
    }

    if (gpiod_line_request(*line, "servo", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0) {
        fprintf(stderr, "Failed to request line for GPIO%d: %s\n", pin, strerror(errno));
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

void cleanup(gpiod_chip *chip, gpiod_line *pan_line, gpiod_line *tilt_line) {
    if (pan_line) {
        gpiod_line_set_value(pan_line, 0);
        gpiod_line_release(pan_line);
    }
    if (tilt_line) {
        gpiod_line_set_value(tilt_line, 0);
        gpiod_line_release(tilt_line);
    }
    gpiod_chip_close(chip);
}

int set_servo_position(gpiod_line *line, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Pulse width %d out of range\n", pulse_width);
        return -1;
    }

    int period = 1000000 / PWM_FREQUENCY;
    int high_time = pulse_width;
    int low_time = period - high_time;

    if (gpiod_line_set_polarity(line, GPIOD_LINE_POLARITY_NORMAL) < 0 ||
        gpiod_line_set_request_type(line, GPIOD_LINE_REQ_TYPE_PULSE) < 0 ||
        gpiod_line_set_pulse_params(line, high_time, low_time) < 0 ||
        gpiod_line_set_active_state(line, 1) < 0 ||
        gpiod_line_set_inactive_state(line, 0) < 0 ||
        gpiod_line_set_flags(line, GPIOD_LINE_FLAG_OPEN_DRAIN) < 0 ||
        gpiod_line_set_request_type(line, GPIOD_LINE_REQ_TYPE_AND_VALUE) < 0 ||
        gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set servo position: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    gpiod_line *pan_line = NULL, *tilt_line = NULL;
    if (setup_pwm(chip, PAN_SERVO_PIN, &pan_line) < 0 ||
        setup_pwm(chip, TILT_SERVO_PIN, &tilt_line) < 0) {
        cleanup(chip, pan_line, tilt_line);
        return 1;
    }

    int pan_position = NEUTRAL_POSITION;
    int tilt_position = NEUTRAL_POSITION;

    if (set_servo_position(pan_line, pan_position) < 0 ||
        set_servo_position(tilt_line, tilt_position) < 0) {
        cleanup(chip, pan_line, tilt_line);
        return 1;
    }

    char c;
    while (keep_running && (c = getchar()) != EOF) {
        switch (c) {
            case 'q':
                keep_running = 0;
                break;
            case 'w': // Tilt up
                if (tilt_position + STEP_SIZE <= MAX_PULSE_WIDTH) {
                    tilt_position += STEP_SIZE;
                    if (set_servo_position(tilt_line, tilt_position) < 0) {
                        cleanup(chip, pan_line, tilt_line);
                        return 1;
                    }
                }
                break;
            case 's': // Tilt down
                if (tilt_position - STEP_SIZE >= MIN_PULSE_WIDTH) {
                    tilt_position -= STEP_SIZE;
                    if (set_servo_position(tilt_line, tilt_position) < 0) {
                        cleanup(chip, pan_line, tilt_line);
                        return 1;
                    }
                }
                break;
            case 'a': // Pan left
                if (pan_position - STEP_SIZE >= MIN_PULSE_WIDTH) {
                    pan_position -= STEP_SIZE;
                    if (set_servo_position(pan_line, pan_position) < 0) {
                        cleanup(chip, pan_line, tilt_line);
                        return 1;
                    }
                }
                break;
            case 'd': // Pan right
                if (pan_position + STEP_SIZE <= MAX_PULSE_WIDTH) {
                    pan_position += STEP_SIZE;
                    if (set_servo_position(pan_line, pan_position) < 0) {
                        cleanup(chip, pan_line, tilt_line);
                        return 1;
                    }
                }
                break;
            default:
                break;
        }
        usleep(DELAY_MS * 1000);
    }

    // Cleanup
    if (set_servo_position(pan_line, NEUTRAL_POSITION) < 0 ||
        set_servo_position(tilt_line, NEUTRAL_POSITION) < 0) {
        fprintf(stderr, "Failed to reset servos to neutral position\n");
    }

    cleanup(chip, pan_line, tilt_line);
    return 0;
