#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>

#define I2C_BUS "/dev/i2c-1"
#define OLED_ADDRESS 0x3C
#define OLED_WIDTH 128
#define OLED_HEIGHT 64

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define STAT_FILE "/proc/stat"

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void i2c_write(int fd, uint8_t *data, size_t length) {
    if (write(fd, data, length) != length) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void oled_init(int fd) {
    uint8_t init_sequence[] = {
        0xAE, // Display off
        0xD5, 0x80, // Set display clock divide ratio/oscillator frequency
        0xA8, 0x3F, // Set multiplex ratio
        0xD3, 0x00, // Set display offset
        0x40, // Set display start line
        0x8D, 0x14, // Set charge pump
        0x20, 0x00, // Set memory addressing mode
        0xA1, // Set segment re-map
        0xC8, // Set COM output scan direction
        0xDA, 0x12, // Set COM pins hardware configuration
        0x81, 0xCF, // Set contrast control
        0xD9, 0xF1, // Set pre-charge period
        0xDB, 0x40, // Set VCOMH deselect level
        0xA4, // Entire display ON
        0xA6, // Normal display
        0xAF // Display ON
    };

    for (size_t i = 0; i < sizeof(init_sequence); i++) {
        i2c_write(fd, &init_sequence[i], 1);
    }
}

void oled_clear(int fd) {
    uint8_t clear_data[1024] = {0};
    i2c_write(fd, clear_data, sizeof(clear_data));
}

void oled_set_cursor(int fd, uint8_t x, uint8_t y) {
    uint8_t data[] = {0xB0 + y, 0x00 + (x & 0x0F), 0x10 + ((x >> 4) & 0x0F)};
    i2c_write(fd, data, sizeof(data));
}

void oled_display_text(int fd, const char *text, uint8_t x, uint8_t y) {
    // Basic 5x7 font
    static const uint8_t font5x7[][5] = {
        {0x00, 0x00, 0x00, 0x00, 0x00}, // space
        {0x00, 0x00, 0x5F, 0x00, 0x00}, // !
        // Add other characters as needed
    };

    for (size_t i = 0; text[i] != '\0'; i++) {
        uint8_t ch = text[i] - ' ';
        if (ch < sizeof(font5x7) / sizeof(font5x7[0])) {
            for (uint8_t row = 0; row < 5; row++) {
                oled_set_cursor(fd, x, y + row);
                uint8_t data[17] = {0x40 | x >> 3};
                for (uint8_t col = 0; col < 5; col++) {
                    data[col + 1] = (font5x7[ch][col] << (y & 7)) | (font5x7[ch][col] >> (1 - (y & 7)));
                }
                i2c_write(fd, data, sizeof(data));
            }
            x += 6;
        }
    }
}

double read_cpu_temperature() {
    FILE *file = fopen(TEMP_FILE, "r");
    if (!file) {
        fprintf(stderr, "Failed to open %s: %s\n", TEMP_FILE, strerror(errno));
        return -1.0;
    }

    double temp;
    if (fscanf(file, "%lf", &temp) != 1) {
        fprintf(stderr, "Failed to read temperature from %s\n", TEMP_FILE);
        fclose(file);
        return -1.0;
    }

    fclose(file);
    return temp / 1000.0;
}

double read_cpu_usage() {
    FILE *file = fopen(STAT_FILE, "r");
    if (!file) {
        fprintf(stderr, "Failed to open %s: %s\n", STAT_FILE, strerror(errno));
        return -1.0;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal;
    if (fscanf(file, "cpu %llu %llu %llu %llu %llu %llu %llu %llu", &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal) != 8) {
        fprintf(stderr, "Failed to read CPU stats from %s\n", STAT_FILE);
        fclose(file);
        return -1.0;
    }

    fclose(file);

    static unsigned long long prev_total = 0, prev_idle = 0;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal;
    unsigned long long idle_time = idle + iowait;
    unsigned long long total_diff = total - prev_total;
    unsigned long long idle_diff = idle_time - prev_idle;

    if (total_diff == 0) {
        return 0.0;
    }

    double usage = 100.0 * (1.0 - (double)idle_diff / total_diff);
    prev_total = total;
    prev_idle = idle_time;

    return usage;
}

int main() {
    signal(SIGINT, handle_sigint);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, OLED_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    oled_init(i2c_fd);
    oled_clear(i2c_fd);

    while (keep_running) {
        double temp = read_cpu_temperature();
        double usage = read_cpu_usage();

        char temp_str[32];
        char usage_str[32];

        if (temp < 0) {
            snprintf(temp_str, sizeof(temp_str), "Temp: Error");
        } else {
            snprintf(temp_str, sizeof(temp_str), "Temp: %.1fC", temp);
        }

        if (usage < 0) {
            snprintf(usage_str, sizeof(usage_str), "CPU: Error");
        } else {
            snprintf(usage_str, sizeof(usage_str), "CPU: %.1f%%", usage);
        }

        oled_clear(i2c_fd);
        oled_display_text(i2c_fd, temp_str, 0, 0);
        oled_display_text(i2c_fd, usage_str, 0, 8);

        sleep(1);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

