    exit(EXIT_FAILURE);
}

void init_gpio(gpiod_chip *chip, gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!*line) {
        log_error("Failed to get GPIO line");
