    init_gpio(chip, &line);

    int i2c_fd = -1;
    init_i2c(&i2c_fd);

    uint64_t pulse_count = 0;
    double total_volume = 0.0;
    double flow_rate = 0.0;
    time_t last_lcd_update = 0;

