#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define MCP3008_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SAMPLE_WINDOW_MS 500

volatile sig_atomic_t keep_running = 1;
volatile int pulse_count = 0;
volatile int wind_direction = 0;

void handle_signal(int sig) {
    keep_running = 0;
}

void gpio_callback_handler(void *user_data) {
    pulse_count++;
}

int read_mcp3008(int spi_fd, int channel) {
    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3] = {0};

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx) < 1) {
        fprintf(stderr, "SPI read error: %s\n", strerror(errno));
        return -1;
    }

    memcpy(rx, &tx[1], 3);
    int result = ((rx[1] & 3) << 8) | rx[2];
    return result;
}

void update_lcd(int i2c_fd, int wind_speed, int wind_direction) {
    char buffer[16];
    snprintf(buffer, sizeof(buffer), "Speed: %d m/s", wind_speed);
    i2c_smbus_write_i2c_block_data(i2c_fd, 0x00, 0, (uint8_t *)buffer, strlen(buffer));

    snprintf(buffer, sizeof(buffer), "Dir: %d deg", wind_direction);
    i2c_smbus_write_i2c_block_data(i2c_fd, 0x40, 0, (uint8_t *)buffer, strlen(buffer));
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return EXIT_FAILURE;
    }

    int gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(gpio_fd, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(gpio_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(line, "anemometer") < 0) {
        fprintf(stderr, "Failed to request rising edge events: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(gpio_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_callback(line, gpio_callback_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set GPIO callback: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(gpio_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE_0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(gpio_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", I2C_BUS);
    int i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        spiClose(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(gpio_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        spiClose(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(gpio_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        usleep(SAMPLE_WINDOW_MS * 1000);

        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0 || adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "ADC read error or sensor absent\n");
        } else {
            wind_direction = (adc_value * 360) / 1023;
        }

        int wind_speed = (pulse_count * 2) / SAMPLE_WINDOW_MS; // Example conversion
        pulse_count = 0;

        update_lcd(i2c_fd, wind_speed, wind_direction);
    }

    close(i2c_fd);
    spiClose(spi_fd);
    gpiod_line_release(line);
    gpiod_chip_close(gpio_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

