#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <gpiod.h>
#include <i2c/smbus.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>

#define GPIO_PIN 17
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CMD_CLEAR 0x01
#define LCD_CMD_RETURN_HOME 0x02
#define LCD_CMD_ENTRY_MODE_SET 0x04
#define LCD_CMD_DISPLAY_CONTROL 0x08
#define LCD_CMD_CURSOR_SHIFT 0x10
#define LCD_CMD_FUNCTION_SET 0x20
#define LCD_CMD_SET_CGRAM_ADDR 0x40
#define LCD_CMD_SET_DDRAM_ADDR 0x80
#define LCD_BACKLIGHT 0x08
#define LCD_FUNCTION_SET 0x28
#define LCD_DISPLAY_ON 0x0C
#define LCD_ENTRY_MODE_SET 0x06
#define LCD_CLEAR_DISPLAY 0x01

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void lcd_send_command(int fd, uint8_t cmd) {
    uint8_t buffer[2] = {cmd, 0x00};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write command to LCD");
        exit(EXIT_FAILURE);
    }
}

void lcd_send_data(int fd, uint8_t data) {
    uint8_t buffer[2] = {data | LCD_BACKLIGHT, 0x00};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write data to LCD");
        exit(EXIT_FAILURE);
    }
}

void lcd_init(int fd) {
    usleep(50000); // Wait for more than 40ms after VCC rises to 4.5V
    lcd_send_command(fd, LCD_FUNCTION_SET | 0x00);
    usleep(4500); // Wait for more than 4.1ms
    lcd_send_command(fd, LCD_FUNCTION_SET | 0x00);
    usleep(150);
    lcd_send_command(fd, LCD_FUNCTION_SET | 0x00);
    lcd_send_command(fd, LCD_FUNCTION_SET | LCD_BACKLIGHT);
    lcd_send_command(fd, LCD_DISPLAY_ON);
    lcd_send_command(fd, LCD_CLEAR_DISPLAY);
    lcd_send_command(fd, LCD_ENTRY_MODE_SET | 0x02);
}

void lcd_clear(int fd) {
    lcd_send_command(fd, LCD_CLEAR_DISPLAY);
    usleep(2000); // Clearing the display takes a long time
}

void lcd_set_cursor(int fd, uint8_t col, uint8_t row) {
    uint8_t address = (row == 0) ? 0x00 : 0x40;
    address += col;
    lcd_send_command(fd, LCD_CMD_SET_DDRAM_ADDR | address);
}

void lcd_print(int fd, const char *str) {
    while (*str) {
        lcd_send_data(fd, *str++);
    }
}

void cleanup(int gpio_fd, int lcd_fd) {
    if (gpio_fd >= 0) {
        gpiod_line_release(gpio_fd);
    }
    if (lcd_fd >= 0) {
        close(lcd_fd);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        exit(EXIT_FAILURE);
    }

    int gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *line = gpiod_chip_get_line(gpio_fd, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        cleanup(gpio_fd, -1);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line, "water_flow_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        perror("Failed to request GPIO line");
        cleanup(gpio_fd, -1);
        exit(EXIT_FAILURE);
    }

    int gpio_line_fd = gpiod_line_event_get_fd(line);
    if (gpio_line_fd < 0) {
        perror("Failed to get GPIO line event file descriptor");
        cleanup(gpio_fd, -1);
        exit(EXIT_FAILURE);
    }

    int lcd_fd = open("/dev/i2c-" + std::to_string(I2C_BUS), O_RDWR);
    if (lcd_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup(gpio_fd, -1);
