#include <gpiod.h>

#define ROW_COUNT 8
#define COL_COUNT 8
#define SCAN_DELAY 800000 // 800 microseconds

// GPIO line numbers for rows and columns
static const int row_pins[ROW_COUNT] = {17, 18, 27, 22, 23, 24, 25, 4};
static const int col_pins[COL_COUNT] = {5, 6, 12, 13, 19, 16, 26, 20};

static struct gpiod_chip *chip;
static struct gpiod_line *rows[ROW_COUNT];
static struct gpiod_line *cols[COL_COUNT];
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void setup_gpio() {
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < ROW_COUNT; i++) {
        rows[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!rows[i]) {
            fprintf(stderr, "Failed to get line for row %d\n", row_pins[i]);
            exit(EXIT_FAILURE);
        }
        ret = gpiod_line_request_output(rows[i], "row", GPIOD_OUT_LOW);
        if (ret < 0) {
            fprintf(stderr, "Failed to request row %d as output\n", row_pins[i]);
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < COL_COUNT; i++) {
        cols[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!cols[i]) {
            fprintf(stderr, "Failed to get line for column %d\n", col_pins[i]);
            exit(EXIT_FAILURE);
        }
        ret = gpiod_line_request_output(cols[i], "col", GPIOD_OUT_HIGH);
        if (ret < 0) {
            fprintf(stderr, "Failed to request column %d as output\n", col_pins[i]);
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup_gpio() {
    for (int i = 0; i < ROW_COUNT; i++) {
        gpiod_line_release(rows[i]);
    }
    for (int i = 0; i < COL_COUNT; i++) {
        gpiod_line_release(cols[i]);
    }
    gpiod_chip_close(chip);
}

void render_wave(int direction) {
    int wave[ROW_COUNT][COL_COUNT] = {0};

    for (int frame = 0; keep_running; frame++) {
        for (int row = 0; row < ROW_COUNT; row++) {
            int col = (direction == 1) ? (frame + row) % COL_COUNT : (COL_COUNT - 1 - (frame + row) % COL_COUNT);
            wave[row][col] = 1;
        }

        for (int row = 0; row < ROW_COUNT; row++) {
            gpiod_line_set_value(rows[row], 1);
            for (int col = 0; col < COL_COUNT; col++) {
                gpiod_line_set_value(cols[col], !wave[row][col]);
            }
            usleep(SCAN_DELAY);
            gpiod_line_set_value(rows[row], 0);
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);

    setup_gpio();

    printf("Starting left-to-right wave animation...\n");
    render_wave(1);

    printf("Starting right-to-left wave animation...\n");
    render_wave(-1);

    cleanup_gpio();
    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

