#define I2C_BUS "/dev/i2c-1"
#define VL53L3CX_I2C_ADDRESS 0x29
#define VL53L3CX_MODEL_ID_REG 0x010F
#define VL53L3CX_MODEL_ID 0x2104
#define VL53L3CX_NUM_TARGETS 4

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t *data, size_t length) {
    uint8_t buffer[256];
    buffer[0] = reg;
    memcpy(buffer + 1, data, length);
    if (write(fd, buffer, length + 1) != length + 1) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, data, length) != length) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

int verify_sensor_model_id(int fd) {
    uint8_t model_id[2];
