volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_distance(int fd, int *distance) {
    uint8_t reg = MLX75031_REG_DISTANCE;
    uint8_t data[2];

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

void log_distance(FILE *file, int distance) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s, %d\n", timestamp, distance);
    fflush(file);
}

int main() {
    signal(SIGINT, handle_sigint);

    FILE *file = fopen("depth_log.csv", "a");
    if (!file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (fseek(file, 0, SEEK_END) == 0 && ftell(file) == 0) {
        fprintf(file, "Timestamp,Distance\n");
        fflush(file);
    }

    int fd = open_i2c_device(I2C_BUS, MLX75031_I2C_ADDR);
    if (fd < 0) {
        fclose(file);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int distance = -1;
        if (read_distance(fd, &distance) != 0) {
            log_distance(file, distance);
            close(fd);
            fd = open_i2c_device(I2C_BUS, MLX75031_I2C_ADDR);
            if (fd < 0) {
                break;
            }
        } else {
            log_distance(file, distance);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    close(fd);
    fclose(file);
    return EXIT_SUCCESS;
}

