#include <gpiod.h>
#include <libi2c.h>

#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL 500 // milliseconds

static volatile sig_atomic_t keep_running = 1;
static struct i2c_client *i2c_client = NULL;
static FILE *log_file = NULL;

void handle_sigint(int sig) {
    keep_running = 0;
    if (i2c_client) {
        i2c_close(i2c_client);
    }
    if (log_file) {
        fclose(log_file);
    }
    // Assuming `si1145_call` is a function provided by the sensor's library
    // si1145_call();
    exit(EXIT_SUCCESS);
}

void log_error(const char *message) {
    fprintf(stderr, "%s: %s\n", message, strerror(errno));
}

void log_data(const char *timestamp, int proximity, int ambient_light) {
    if (log_file) {
        fprintf(log_file, "%s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity, ambient_light);
        fflush(log_file);
    }
}

void get_iso8601_timestamp(char *buffer, size_t buffer_size) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(buffer, buffer_size, "%Y-%m-%dT%H:%M:%S", tm_info);
}

int main() {
    struct i2c_adapter *adapter;
    struct i2c_msg msgs[2];
    uint8_t reg_addr = 0x00; // Example register address
    uint8_t data[2] = {0};   // Buffer to store sensor data

    signal(SIGINT, handle_sigint);

    adapter = i2c_get_adapter(I2C_BUS);
    if (!adapter) {
        log_error("Failed to get I2C adapter");
        return EXIT_FAILURE;
    }

    i2c_client = i2c_new_client(adapter, SI1145_ADDR);
    if (!i2c_client) {
        log_error("Failed to create I2C client");
        i2c_put_adapter(adapter);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        i2c_close(i2c_client);
        i2c_put_adapter(adapter);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        memset(msgs, 0, sizeof(msgs));

        msgs[0].addr = SI1145_ADDR;
        msgs[0].flags = I2C_M_RD;
        msgs[0].len = 2;
        msgs[0].buf = data;

        if (i2c_transfer(i2c_client, msgs, 1) < 0) {
            log_error("I2C read failed");
            continue;
        }

        int proximity = data[0]; // Example extraction
        int ambient_light = data[1]; // Example extraction

        char timestamp[20];
        get_iso8601_timestamp(timestamp, sizeof(timestamp));
        log_data(timestamp, proximity, ambient_light);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    if (i2c_client) {
        i2c_close(i2c_client);
    }
    if (log_file) {
        fclose(log_file);
    }
    i2c_put_adapter(adapter);

    // Assuming `si1145_call` is a function provided by the sensor's library
    // si1145_call();

    return EXIT_SUCCESS;
}

