#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define PROXIMITY_SENSOR_LINE 4
#define LED_LINE 17
#define POLL_INTERVAL 100000000 // 100 ms in nanoseconds
#define LED_ON_DURATION 10000000 // 10 ms in nanoseconds

static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *proximity_sensor_line = NULL;
static struct gpiod_line *led_line = NULL;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_detection() {
    FILE *log_file = fopen("proximity.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    if (fprintf(log_file, "%s Object detected\n", timestamp) < 0) {
        perror("Failed to write to log file");
    }

    fclose(log_file);
}

void blink_led() {
    gpiod_line_set_value(led_line, 1);
    usleep(LED_ON_DURATION / 1000);
    gpiod_line_set_value(led_line, 0);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(NULL);
    if (!chip) {
        chip = gpiod_chip_open("the library’s API call");
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
    }

    proximity_sensor_line = gpiod_chip_get_line(chip, PROXIMITY_SENSOR_LINE);
    if (!proximity_sensor_line) {
        fprintf(stderr, "Failed to get proximity sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(proximity_sensor_line, "proximity_sensor") < 0) {
        fprintf(stderr, "Failed to request proximity sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int last_state = gpiod_line_get_value(proximity_sensor_line);
    if (last_state < 0) {
        fprintf(stderr, "Failed to get initial proximity sensor value: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int current_state = gpiod_line_get_value(proximity_sensor_line);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read proximity sensor value: %s\n", strerror(errno));
            break;
        }

        if (last_state == 1 && current_state == 0) {
            log_detection();
            blink_led();
        }

        last_state = current_state;
        nanosleep((const struct timespec[]){{0, POLL_INTERVAL}}, NULL);
    }

    gpiod_line_release(proximity_sensor_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

