#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x60
#define SI1145_PART_ID_REG 0x00
#define SI1145_PART_ID 0x00
#define SI1145_COMMAND_REG 0x80
#define SI1145_COMMAND_READ_PROX 0x83
#define SI1145_COMMAND_READ_ALS 0x8F

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t *data, size_t length) {
    uint8_t buffer[256];
    buffer[0] = reg;
    memcpy(buffer + 1, data, length);
    if (write(fd, buffer, length + 1) != length + 1) {
        syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
        return -1;
    }
    if (read(fd, data, length) != length) {
        syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int verify_sensor(int fd) {
    uint8_t part_id;
    if (i2c_read(fd, SI1145_PART_ID_REG, &part_id, 1) != 0) {
        return -1;
    }
    return part_id == SI1145_PART_ID;
}

int read_proximity(int fd, uint16_t *proximity) {
    uint8_t data[2];
    if (i2c_write(fd, SI1145_COMMAND_REG, (uint8_t[]){SI1145_COMMAND_READ_PROX}, 1) != 0) {
        return -1;
    }
    if (i2c_read(fd, 0x00, data, 2) != 0) {
        return -1;
    }
    *proximity = (data[0] << 8) | data[1];
    return 0;
}

int read_ambient_light(int fd, uint16_t *ambient_light) {
    uint8_t data[2];
    if (i2c_write(fd, SI1145_COMMAND_REG, (uint8_t[]){SI1145_COMMAND_READ_ALS}, 1) != 0) {
        return -1;
    }
    if (i2c_read(fd, 0x00, data, 2) != 0) {
        return -1;
    }
    *ambient_light = (data[0] << 8) | data[1];
    return 0;
}

