    int i2c_fd;
    FILE *log_file;
    uint16_t proximity, ambient_light;

    openlog("si1145_reader", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_sigint);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (!verify_sensor(i2c_fd)) {
        syslog(LOG_ERR, "Si1145 sensor not found or invalid PART_ID");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    log_file = fopen("biometric_data.log", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (keep_running) {
        if (read_proximity(i2c_fd, &proximity) == 0 && read_ambient_light(i2c_fd, &ambient_light) == 0) {
            log_data(log_file, proximity, ambient_light);
        } else {
            syslog(LOG_WARNING, "Failed to read sensor data");
        }
        sleep(1);
    }

    fclose(log_file);
    close(i2c_fd);
    closelog();

    return EXIT_SUCCESS;
}

