#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define TRIGGER_GPIO_CHIP "gpiochip0"
#define ECHO_GPIO_CHIP "gpiochip0"
#define TRIGGER_LINE 17
#define ECHO_LINE 27
#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_CM 2
#define TIMEOUT_US 30000000 // 30 ms
#define PULSE_WIDTH_TIMEOUT_US 30000000 // 30 ms
#define TRIGGER_PULSE_WIDTH_US 10
#define LOG_INTERVAL 60 // seconds
#define ALERT_DISTANCE_CM 15

static volatile int keep_running = 1;
static FILE *log_file = NULL;

void handle_signal(int sig) {
    keep_running = 0;
}

double measure_distance(struct gpiod_line *trigger_line, struct gpiod_line *echo_line) {
    struct timespec start, end;
    long duration_ns;
    double distance_cm;

    // Send 10us trigger pulse
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        fprintf(stderr, "Failed to set trigger line high\n");
        return -1;
    }
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Failed to set trigger line low\n");
        return -1;
    }

    // Wait for echo to go high
    if (gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, TIMEOUT_US) < 0) {
        fprintf(stderr, "Echo line did not go high (timeout)\n");
        return -1;
    }

    // Record start time
    if (clock_gettime(CLOCK_MONOTONIC, &start) != 0) {
        perror("clock_gettime");
        return -1;
    }

    // Wait for echo to go low
    if (gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, PULSE_WIDTH_TIMEOUT_US) < 0) {
        fprintf(stderr, "Echo line did not go low (timeout)\n");
        return -1;
    }

    // Record end time
    if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
        perror("clock_gettime");
        return -1;
    }

    // Calculate duration in nanoseconds
    duration_ns = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);

    // Calculate distance in cm
    distance_cm = (duration_ns / 2.0) * 0.0343;

    return distance_cm;
}

void log_distance(double distance, const char *status) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "[%s] Distance: %.2f cm, Status: %s\n", timestamp, distance, status);

    if (distance >= 0 && distance < ALERT_DISTANCE_CM) {
        fprintf(log_file, "Time to water the plant!\n");
    }
}

int main() {
    struct gpiod_chip *trigger_chip, *echo_chip;
    struct gpiod_line *trigger_line, *echo_line;
    double distance;
    time_t last_log_time = 0;

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    trigger_chip = gpiod_chip_open_by_name(TRIGGER_GPIO_CHIP);
    if (!trigger_chip) {
        perror("gpiod_chip_open_by_name (trigger)");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    echo_chip = gpiod_chip_open_by_name(ECHO_GPIO_CHIP);
    if (!echo_chip) {
        perror("gpiod_chip_open_by_name (echo)");
        gpiod_chip_close(trigger_chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Get lines
    trigger_line = gpiod_chip_get_line(trigger_chip, TRIGGER_LINE);
    if (!trigger_line) {
        perror("gpiod_chip_get_line (trigger)");
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(echo_chip, ECHO_LINE);
    if (!echo_line) {
        perror("gpiod_chip_get_line (echo)");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Configure lines
    if (gpiod_line_request(trigger_line, "trigger", GPIOD_LINE_REQUEST_DIRECTIONS_OUT) < 0) {
        perror("gpiod_line_request (trigger)");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(echo_line, "echo", GPIOD_LINE_REQUEST_DIRECTIONS_IN) < 0) {
        perror("gpiod_line_request (echo)");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        distance = measure_distance(trigger_line, echo_line);

        if (distance < 0) {
            log_distance(-1, "Error or timeout");
        } else if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            log_distance(distance, "Out of range");
        } else {
            log_distance(distance, "Valid");
        }

        // Log every LOG_INTERVAL seconds
        if (difftime(time(NULL), last_log_time) >= LOG_INTERVAL) {
            last_log_time = time(NULL);
        }

        usleep(100000); // Sleep for 100ms
    }

    // Cleanup
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(trigger_chip);
    gpiod_chip_close(echo_chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

