        if (distance < 0) {
            log_distance(-1, "Error or timeout");
        } else if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            log_distance(distance, "Out of range");
        } else {
            log_distance(distance, "Valid");
        }

        // Log every LOG_INTERVAL seconds
        if (difftime(time(NULL), last_log_time) >= LOG_INTERVAL) {
            last_log_time = time(NULL);
        }

        usleep(100000); // Sleep for 100ms
    }

    // Cleanup
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(trigger_chip);
    gpiod_chip_close(echo_chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}
