#define PROXIMITY_THRESHOLD 200
#define POLL_INTERVAL 100000000 // 100 ms in nanoseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        return -1;
    }
    return fd;
}

int set_i2c_slave(int fd, uint8_t addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int read_i2c_block_data(int fd, uint8_t reg, uint8_t *data, uint8_t length) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
        return -1;
    }
    if (read(fd, data, length) != length) {
        syslog(LOG_ERR, "Failed to read from I2C device: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int write_i2c_block_data(int fd, uint8_t reg, const uint8_t *data, uint8_t length) {
    uint8_t buffer[length + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, data, length);
    if (write(fd, buffer, length + 1) != length + 1) {
        syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int init_apds9960(int fd) {
    uint8_t data[2];

    // Enable proximity sensor
    data[0] = 0x80; // Enable proximity
    if (write_i2c_block_data(fd, 0x8D, data, 1) < 0) return -1;

    // Set proximity gain
    data[0] = 0x01; // Gain 1x
    if (write_i2c_block_data(fd, 0x89, data, 1) < 0) return -1;

    // Set proximity integration time
    data[0] = 0x9C; // 63ms
    if (write_i2c_block_data(fd, 0x8F, data, 1) < 0) return -1;

    return 0;
}

int read_proximity(int fd, uint16_t *proximity) {
    uint8_t data[2];
    if (read_i2c_block_data(fd, 0x8F, data, 2) < 0) return -1;
    *proximity = (data[1] << 8) | data[0];
    return 0;
}

int read_color(int fd, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t data[6];
    if (read_i2c_block_data(fd, 0x94, data, 6) < 0) return -1;
    *red = (data[1] << 8) | data[0];
    *green = (data[3] << 8) | data[2];
    *blue = (data[5] << 8) | data[4];
    return 0;
}

void log_color_proximity(FILE *log_file, uint16_t red, uint16_t green, uint16_t blue, uint16_t proximity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file);
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    struct timespec interval = {0, POLL_INTERVAL};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    openlog("APDS9960", LOG_PID | LOG_CONS, LOG_USER);

    log_file = fopen("color_proximity_log.csv", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (i2c_fd < 0) {
            i2c_fd = open_i2c_device(I2C_BUS);
            if (i2c_fd < 0) {
                sleep(1);
                continue;
            }
        }

        if (set_i2c_slave(i2c_fd, APDS9960_I2C_ADDR) < 0 || init_apds9960(i2c_fd) < 0) {
            close(i2c_fd);
            i2c_fd = -1;
            sleep(1);
            continue;
        }

        uint16_t proximity, red, green, blue;
        if (read_proximity(i2c_fd, &proximity) == 0 && proximity > PROXIMITY_THRESHOLD) {
            if (read_color(i2c_fd, &red, &green, &blue) == 0) {
                log_color_proximity(log_file, red, green, blue, proximity);
            }
        }

        nanosleep(&interval, NULL);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }

    closelog();
    return EXIT_SUCCESS;
}

