#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B
#define GPIO_PIN 17
#define GPIO_LINE (1 << GPIO_PIN)

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

int main() {
    int i2c_fd, gpio_fd;
    struct timespec ts;
    FILE *log_file;
    struct gpiod_line *line;
    struct gpiod_chip *chip;
    uint8_t model_id;
    uint8_t interrupt_status;
    int ret;

    signal(SIGINT, handle_sigint);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L0X_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Verify sensor presence
    if (i2c_read(i2c_fd, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0 || model_id != VL53L0X_IDENTIFICATION_MODEL_ID) {
        fprintf(stderr, "Sensor not found or not responding\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure GPIO
    gpio_fd = gpiod_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_fd(gpio_fd);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(line, "vl53l0x_trigger") < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure sensor for interrupt on GPIO
    if (i2c_write(i2c_fd, VL53L0X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x04) < 0) {
        fprintf(stderr, "Failed to configure sensor interrupt\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Wait for falling edge
        ret = gpiod_line_event_wait(line, -1);
        if (ret < 0) {
            perror("Failed to wait for GPIO event");
            break;
        }

        // Trigger measurement
        if (i2c_write(i2c_fd, 0x00, 0x01) < 0) { // Assuming 0x00 is the start measurement register
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        // Poll for interrupt status
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += 1; // 1 second timeout

        while (keep_running) {
            if (i2c_read(i2c_fd, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &interrupt_status) < 0) {
                fprintf(stderr, "Failed to read interrupt status\n");
                break;
            }

            if (interrupt_status & 0x04) { // Assuming 0x04 is the interrupt status bit
                // Clear interrupt
                if (i2c_write(i2c_fd, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x04) < 0) {
                    fprintf(stderr, "Failed to clear interrupt\n");
                    break;
                }

                // Read distance (assuming 0x14 is the distance register)
                uint8_t distance_high, distance_low;
                if (i2c_read(i2c_fd, 0x14, &distance_high) < 0 || i2c_read(i2c_fd, 0x15, &distance_low) < 0) {
                    fprintf(stderr, "Failed to read distance\n");
                    break;
                }

                int distance = (distance_high << 8) | distance_low;

                // Log distance with timestamp
                time_t now = time(NULL);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
                fprintf(log_file, "%s,%d\n", timestamp, distance);
                fflush(log_file);

                break;
            }

            if (clock_nanosleep(CLOCK_REALTIME, TIMER_ABSTIME, &ts, NULL) < 0) {
                if (errno == EINTR) continue;
                perror("Timeout waiting for interrupt");
                break;
            }
        }
    }

    // Cleanup
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (gpio_fd >= 0) {
        close(gpio_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}
