    }
    return 0;
}

int read_i2c(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return 0;
}

void log_distance(const char *timestamp, int distance) {
    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_fp, "%s, %d\n", timestamp, distance);
    fclose(log_fp);
}

void get_timestamp(char *buffer, size_t size) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(buffer, size, "%Y-%m-%d %H:%M:%S", tm_info);
}

int main() {
    signal(SIGINT, handle_sigint);

    int i2c_fd = open_i2c_device(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    FILE *log_fp = fopen(LOG_FILE, "w");
    if (!log_fp) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    fclose(log_fp);

    char timestamp[20];
    uint8_t distance_high, distance_low;

    while (keep_running) {
        if (write_i2c(i2c_fd, 0x00, 0x51) < 0) {
            syslog(LOG_ERR, "I2C write error, skipping sample");
            usleep(WAIT_AFTER_TRIGGER);
            continue;
        }

        usleep(WAIT_AFTER_TRIGGER);

        if (read_i2c(i2c_fd, 0x02, &distance_high) < 0 || read_i2c(i2c_fd, 0x03, &distance_low) < 0) {
            syslog(LOG_ERR, "I2C read error, skipping sample");
            continue;
        }

        int distance = (distance_high << 8) | distance_low;
        get_timestamp(timestamp, sizeof(timestamp));
        printf("%s, %d\n", timestamp, distance);
        log_distance(timestamp, distance);

        usleep(SAMPLE_INTERVAL);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

