#define GPIO_LED 17
#define SAMPLE_INTERVAL_MS 100
#define DISTANCE_THRESHOLD_CM 20

static volatile int keep_running = 1;
static int i2c_fd = -1;
static int gpio_fd = -1;
static struct gpiod_line *gpio_line = NULL;

void handle_signal(int sig) {
    keep_running = 0;
}

int init_gpio() {
    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_fd, GPIO_LED);
    if (!gpio_line) {
        syslog(LOG_ERR, "Failed to get GPIO line: %s", strerror(errno));
        gpiod_chip_close(gpio_fd);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "distance_led", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line: %s", strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_fd);
        return -1;
    }

    return 0;
}

int init_i2c() {
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_distance(int *distance) {
    uint8_t buffer[2];
    int ret;

    buffer[0] = 0x00; // Command to read distance
    ret = write(i2c_fd, buffer, 1);
    if (ret != 1) {
        syslog(LOG_ERR, "Failed to write to I2C: %s", strerror(errno));
        return -1;
    }

    ret = read(i2c_fd, buffer, 2);
    if (ret != 2) {
        syslog(LOG_ERR, "Failed to read from I2C: %s", strerror(errno));
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

void log_distance(int distance) {
    FILE *log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s: %d cm\n", timestamp, distance);
    fclose(log_file);
}

void cleanup() {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_fd >= 0) {
        gpiod_chip_close(gpio_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

