    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    openlog("distance_sensor", LOG_PID | LOG_CONS, LOG_USER);

    if (init_gpio() < 0 || init_i2c() < 0) {
        syslog(LOG_ERR, "Initialization failed");
        cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int distance;
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            gpiod_line_set_value(gpio_line, distance < DISTANCE_THRESHOLD_CM);
        } else {
            syslog(LOG_WARNING, "Error reading distance");
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup();
    closelog();
    return EXIT_SUCCESS;
}
