#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x70
#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VALUE 0x20
#define TRIG_REG 0x02
#define DISTANCE_REG 0x04
#define GPIO_LED 17
#define POLL_INTERVAL 50 // milliseconds
#define DEFAULT_THRESHOLD 100 // mm

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_read_byte(int fd, uint8_t reg) {
    uint8_t buffer[1];
    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buffer, 1) != 1) {
        perror("Failed to read data");
        return -1;
    }
    return buffer[0];
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

void log_distance(int distance) {
    FILE *log_file = fopen("tof_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log_file, "%s: Distance = %d mm\n", timestamp, distance);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    int i2c_fd, gpio_fd;
    struct gpiod_line *led_line;
    uint8_t threshold = DEFAULT_THRESHOLD;
    int distance;

    if (argc > 1) {
        threshold = atoi(argv[1]);
    }

    signal(SIGINT, handle_signal);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Verify WHO_AM_I register
    if (i2c_read_byte(i2c_fd, WHO_AM_I_REG) != WHO_AM_I_VALUE) {
        fprintf(stderr, "Sensor not detected or WHO_AM_I mismatch\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    led_line = gpiod_chip_get_line(gpio_fd, GPIO_LED);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(led_line);
        gpiod_chip_close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Trigger measurement
        if (i2c_write_byte(i2c_fd, TRIG_REG, 0x01) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            break;
        }

        // Read distance
        distance = i2c_read_byte(i2c_fd, DISTANCE_REG);
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance\n");
            break;
        }

        // Log distance
        log_distance(distance);

        // Control LED
        if (distance < threshold) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Polling interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Cleanup
    gpiod_line_release(led_line);
    gpiod_chip_close(gpio_fd);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

