#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define OMRON_I2C_ADDRESS 0x62
#define COMMAND_FRAME {0x00, 0x00, 0x00, 0x00}
#define HEADER_VALUE 0x55
#define SAMPLES 10
#define DELAY_MS 100
#define THRESHOLD_DISTANCE 1000

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int address) {
    int file;
    if ((file = open(device, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }
    if (ioctl(file, I2C_SLAVE, address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return -1;
    }
    return file;
}

int write_i2c(int file, const uint8_t *data, size_t length) {
    if (write(file, data, length) != length) {
        perror("Failed to write to the i2c bus");
        return -1;
    }
    return 0;
}

int read_i2c(int file, uint8_t *data, size_t length) {
    if (read(file, data, length) != length) {
        perror("Failed to read from the i2c bus");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, handle_sigint);

    int i2c_file = open_i2c_device(I2C_DEVICE, OMRON_I2C_ADDRESS);
    if (i2c_file < 0) {
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("intrusion_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_file);
        return EXIT_FAILURE;
    }

    uint8_t command_frame[4] = COMMAND_FRAME;
    uint8_t response[15];
