#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L0X_ADDRESS 0x29
#define VL53L0X_IDENTIFICATION_MODEL_ID 0xC0
#define VL53L0X_IDENTIFICATION_MODEL_ID_VALUE 0xEE
#define VL53L0X_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_SYSRANGE_START 0x00
#define VL53L0X_SYSRANGE_START_STOP 0x00
#define VL53L0X_SYSRANGE_START_CONTINUOUS 0x02

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int read_i2c_byte(int fd, uint8_t reg) {
    uint8_t buffer[1] = {reg};
    if (write(fd, buffer, 1) != 1) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buffer, 1) != 1) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }

    return buffer[0];
}

int write_i2c_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L0X_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    uint8_t model_id = read_i2c_byte(i2c_fd, VL53L0X_IDENTIFICATION_MODEL_ID);
    if (model_id == -1 || model_id != VL53L0X_IDENTIFICATION_MODEL_ID_VALUE) {
        fprintf(stderr, "Failed to read or verify sensor model ID\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write_i2c_byte(i2c_fd, VL53L0X_SYSRANGE_START, VL53L0X_SYSRANGE_START_CONTINUOUS) != 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint8_t status = read_i2c_byte(i2c_fd, VL53L0X_RESULT_INTERRUPT_STATUS);
        if (status == -1) {
            fprintf(stderr, "Warning: Failed to read interrupt status, continuing...\n");
        } else if (status & 0x07) {
            uint8_t distance = read_i2c_byte(i2c_fd, 0x14);
            if (distance == -1) {
                fprintf(stderr, "Warning: Failed to read distance, continuing...\n");
            } else {
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char time_str[20];
                strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
                printf("%s Distance: %d mm\n", time_str, distance);
            }
        }

        usleep(100000); // 100 ms
    }

    if (write_i2c_byte(i2c_fd, VL53L0X_SYSRANGE_START, VL53L0X_SYSRANGE_START_STOP) != 0) {
        fprintf(stderr, "Warning: Failed to stop measurement\n");
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

