#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x60
#define PROXIMITY_REG 0x0A
#define PROXIMITY_DATA_REG 0x0B
#define POLL_INTERVAL 500 // milliseconds

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    if (read(fd, data, length) != length) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int main() {
    int i2c_fd;
    uint8_t proximity_data[2] = {0};
    struct sigaction sa;

    // Set up signal handler for SIGINT
    sa.sa_handler = handle_sigint;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Check for sensor presence
    if (i2c_write(i2c_fd, PROXIMITY_REG, 0x00) < 0) {
        fprintf(stderr, "Sensor absent or I2C error\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Trigger proximity measurement
        if (i2c_write(i2c_fd, PROXIMITY_REG, 0x01) < 0) {
            fprintf(stderr, "Failed to write to proximity register\n");
            continue;
        }

        // Read proximity data
        if (i2c_read(i2c_fd, PROXIMITY_DATA_REG, proximity_data, 2) < 0) {
            fprintf(stderr, "Failed to read proximity data\n");
            continue;
        }

        // Combine the two bytes into a 16-bit value
        uint16_t proximity_value = (proximity_data[0] << 8) | proximity_data[1];
        printf("Proximity: %u\n", proximity_value);

        // Wait for the next poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    close(i2c_fd);
    return EXIT_SUCCESS;
}

