        // Convert the two bytes to a 16-bit value
        distance = (buffer[0] << 8) | buffer[1];

        // Print the distance
        printf("Distance: %u mm\n", distance);

        // Sleep for 500 ms
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    close(i2c_fd);
    return 0;
}
