#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TRIGGER_GPIO_CHIP "gpiochip0"
#define ECHO_GPIO_CHIP "gpiochip0"
#define TRIGGER_LINE 17
#define ECHO_LINE 18
#define TRIGGER_PULSE_NS 10000
#define MAX_DISTANCE_US 38000
#define POLL_INTERVAL 1000000000 // 1 second in nanoseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

int main() {
    struct timespec ts;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    struct gpiod_chip *trigger_chip = NULL;
    struct gpiod_chip *echo_chip = NULL;
    struct gpiod_line_event event;
    int ret;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip for trigger
    trigger_chip = gpiod_chip_open(TRIGGER_GPIO_CHIP);
    if (!trigger_chip) {
        log_error("Failed to open GPIO chip for trigger");
        return EXIT_FAILURE;
    }

    // Open GPIO chip for echo
    echo_chip = gpiod_chip_open(ECHO_GPIO_CHIP);
    if (!echo_chip) {
        gpiod_chip_close(trigger_chip);
        log_error("Failed to open GPIO chip for echo");
        return EXIT_FAILURE;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(trigger_chip, TRIGGER_LINE);
    if (!trigger_line) {
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        log_error("Failed to get trigger line");
        return EXIT_FAILURE;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(echo_chip, ECHO_LINE);
    if (!echo_line) {
        gpiod_chip_put_line(trigger_line);
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        log_error("Failed to get echo line");
        return EXIT_FAILURE;
    }

    // Request trigger line as output
    ret = gpiod_line_request(trigger_line, "trigger", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    if (ret) {
        gpiod_chip_put_line(echo_line);
        gpiod_chip_put_line(trigger_line);
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        log_error("Failed to request trigger line");
        return EXIT_FAILURE;
    }

    // Request echo line as input with event detection
    ret = gpiod_line_request(echo_line, "echo", GPIOD_LINE_REQUEST_DIRECTIONS_INPUT);
    if (ret) {
        gpiod_line_release(trigger_line);
        gpiod_chip_put_line(echo_line);
        gpiod_chip_put_line(trigger_line);
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        log_error("Failed to request echo line");
        return EXIT_FAILURE;
    }

    // Set up event detection for echo line
    ret = gpiod_line_event_configure(echo_line, GPIOD_LINE_EVENT_BOTH_EDGES, &event);
    if (ret) {
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_put_line(echo_line);
        gpiod_chip_put_line(trigger_line);
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        log_error("Failed to configure event detection");
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Send trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo rising edge
        ret = gpiod_line_event_wait(echo_line, &event, POLL_INTERVAL);
        if (ret < 0) {
            log_error("Timeout waiting for echo rising edge");
            continue;
        }

        // Record start time
        if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
            log_error("Failed to get start time");
            continue;
        }

        // Wait for echo falling edge
        ret = gpiod_line_event_wait(echo_line, &event, POLL_INTERVAL);
        if (ret < 0) {
            log_error("Timeout waiting for echo falling edge");
            continue;
        }

        // Record end time
        if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
            log_error("Failed to get end time");
            continue;
        }

        // Calculate pulse duration
        long pulse_duration_us = (ts.tv_sec - event.ts.tv_sec) * 1000000 + (ts.tv_nsec - event.ts.tv_nsec) / 1000;
        if (pulse_duration_us <= 0 || pulse_duration_us > MAX_DISTANCE_US) {
            log_error("Invalid pulse duration");
            continue;
        }

        // Calculate distance in cm
        double distance_cm = pulse_duration_us / 58.0;

        // Log measurement with timestamp
        printf("Distance: %.2f cm at %ld.%09ld\n", distance_cm, ts.tv_sec, ts.tv_nsec);
    }

    // Cleanup
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_put_line(echo_line);
    gpiod_chip_put_line(trigger_line);
    gpiod_chip_close(trigger_chip);
    gpiod_chip_close(echo_chip);

    return EXIT_SUCCESS;
}

