    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening UART device");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error from tcgetattr");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B115200);
    cfsetispeed(&tty, B115200);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_oflag &= ~OPOST;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error from tcsetattr");
        close(fd);
        return -1;
    }

    return fd;
}

int setup_led() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int line_offset = LED_GPIO;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, line_offset);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "alert_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

void activate_led(int duration) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int line_offset = LED_GPIO;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return;
    }

    line = gpiod_chip_get_line(chip, line_offset);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return;
    }

    if (gpiod_line_request_output(line, "alert_led", 1) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return;
    }

    usleep(duration * 1000000);

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to reset GPIO line");
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
}

void log_intrusion(double distance) {
    FILE *file = fopen("intrusion_log.csv", "a");
    if (!file) {
        perror("Error opening log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(file, "%s,%.2f\n", timestamp, distance);
    fclose(file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd < 0) {
        return EXIT_FAILURE;
    }

    if (setup_led() < 0) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    uint8_t magic_word[MAGIC_WORD_SIZE];
    uint8_t data[DATA_SIZE];
    uint16_t distance_bins[64];

    while (!stop) {
        ssize_t bytes_read = read(uart_fd, magic_word, MAGIC_WORD_SIZE);
        if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EINTR) {
                continue;
            }
            perror("Error reading magic word");
            break;
        } else if (bytes_read != MAGIC_WORD_SIZE) {
            continue;
        }

        bytes_read = read(uart_fd, data, DATA_SIZE);
        if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EINTR) {
                continue;
            }
            perror("Error reading data");
            break;
        } else if (bytes_read != DATA_SIZE) {
            continue;
        }

        for (int i = 0; i < 64; i++) {
            distance_bins[i] = (data[2 * i] | (data[2 * i + 1] << 8));
            double distance = distance_bins[i] * 0.01; // Example conversion factor
            if (distance <= DISTANCE_THRESHOLD) {
                log_intrusion(distance);
                activate_led(ALERT_DURATION);
                break;
            }
        }
    }

    close(uart_fd);
    return EXIT_SUCCESS;
}
