        if (value < 0) {
            fprintf(stderr, "Failed to read sensor value: %s\n", gpiod_strerror(value));
            break;
        }

        if (value != last_state) {
            last_state = value;
            log_state_transition(value);
            gpiod_line_set_value(buzzer_line, value);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

