#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x70
#define ALERT_PIN 17
#define ALERT_PIN_NAME "gpio17"
#define ALERT_PIN_CHIP "gpiochip0"
#define ALERT_PIN_LINE 17
#define ALERT_PIN_FLAGS GPIOD_LINE_REQUEST_OUTPUT
#define ALERT_PIN_ACTIVE_HIGH 1
#define ALERT_PIN_ACTIVE_LOW 0
#define ALERT_PIN_ACTIVE ALERT_PIN_ACTIVE_HIGH
#define ALERT_PIN_POLARITY GPIOD_LINE_POLARITY_LOW
#define ALERT_PIN_EDGE GPIOD_LINE_EDGE_RISING
#define ALERT_DISTANCE_THRESHOLD 10.0
#define LOG_FILE "distance_log.txt"
#define READ_INTERVAL 100

static int i2c_fd = -1;
static int gpio_fd = -1;
static struct gpiod_line *alert_line = NULL;

void cleanup() {
    if (alert_line) {
        gpiod_line_release(alert_line);
        alert_line = NULL;
    }
    if (gpio_fd != -1) {
        close(gpio_fd);
        gpio_fd = -1;
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void handle_signal(int sig) {
    syslog(LOG_INFO, "Received signal %d, cleaning up and exiting.", sig);
    cleanup();
    exit(EXIT_SUCCESS);
}

void setup_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int setup_gpio() {
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    alert_line = gpiod_chip_get_line(gpio_fd, ALERT_PIN_LINE);
    if (!alert_line) {
        syslog(LOG_ERR, "Failed to get GPIO line: %s", strerror(errno));
        close(gpio_fd);
        gpio_fd = -1;
        return -1;
    }

    if (gpiod_line_request(alert_line, ALERT_PIN_NAME, ALERT_PIN_FLAGS) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line: %s", strerror(errno));
        gpiod_line_release(alert_line);
        alert_line = NULL;
        close(gpio_fd);
        gpio_fd = -1;
        return -1;
    }

    return 0;
}

int setup_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int read_distance(float *distance) {
    uint8_t buffer[2];
    int ret = i2c_smbus_read_i2c_block_data(i2c_fd, 0x00, 2, buffer);
    if (ret < 0) {
        syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
        return -1;
    }

    int raw_distance = (buffer[0] << 8) | buffer[1];
    if (raw_distance == 0xFFFF) {
        syslog(LOG_ERR, "Sensor not detected or out of range");
        return -1;
    }

    *distance = raw_distance * 0.01;
    return 0;
}

void log_distance(float distance) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
    fclose(log_file);
}

int main() {
    openlog("ultrasonic_sensor", LOG_PID | LOG_CONS, LOG_USER);
    setup_signal_handler();

    if (setup_gpio() < 0 || setup_i2c() < 0) {
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        float distance;
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            if (distance < ALERT_DISTANCE_THRESHOLD) {
                gpiod_line_set_value(alert_line, ALERT_PIN_ACTIVE_HIGH);
            } else {
                gpiod_line_set_value(alert_line, ALERT_PIN_ACTIVE_LOW);
            }
        }
        usleep(READ_INTERVAL * 1000);
    }

    cleanup();
    closelog();
    return 0;
}

