#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_I2C_ADDR 0x29
#define POLL_INTERVAL_MS 100
#define LOG_FILE "distance_log.csv"
#define HEADER "timestamp,distance_mm\n"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int init_i2c(int *fd) {
    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, VL53L1X_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(*fd);
        return -1;
    }

    return 0;
}

int deinit_i2c(int fd) {
    close(fd);
    return 0;
}

int read_distance(int fd, int *distance) {
    char buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

void log_distance(FILE *log_file, int distance) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file);
}

void print_guidance(int distance) {
    if (distance < 300) {
        printf("STOP\n");
