    if (init_i2c(&i2c_fd) != 0) {
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "a+")) == NULL) {
        perror("Failed to open log file");
        deinit_i2c(i2c_fd);
        return EXIT_FAILURE;
    }

    if (fseek(log_file, 0, SEEK_SET) == 0) {
        if (ftell(log_file) == 0) {
            fprintf(log_file, HEADER);
            fflush(log_file);
        }
        fseek(log_file, 0, SEEK_END);
    }

    while (keep_running) {
        if (read_distance(i2c_fd, &distance) != 0) {
            fprintf(stderr, "Error reading distance\n");
        } else {
            log_distance(log_file, distance);
            print_guidance(distance);
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    deinit_i2c(i2c_fd);

    return EXIT_SUCCESS;
}

