#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <sys/time.h>
#include <string.h>
#include <errno.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x70 // CH201 default I2C address
#define LED_GPIO 18
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_i2c *i2c;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led_blink", 0)) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int setup_i2c() {
    i2c = gpiod_i2c_open(I2C_BUS, I2C_ADDRESS);
    if (!i2c) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int read_distance(int *distance) {
    uint8_t buffer[2];
    int retries = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = gpiod_i2c_read(i2c, buffer, sizeof(buffer));
        if (ret == sizeof(buffer)) {
            *distance = (buffer[0] << 8) | buffer[1];
            return 0;
        } else if (ret < 0 && errno == EAGAIN) {
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
        } else {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(stderr, "Failed to read from I2C after %d retries\n", MAX_RETRIES);
    return -1;
}

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c) {
        gpiod_i2c_close(i2c);
    }
}

void blink_led(int distance) {
    int frequency = 1000 - (distance / 10); // Example mapping
    if (frequency < 100) frequency = 100;
    if (frequency > 1000) frequency = 1000;

    int half_cycle_time = (1000 / frequency) / 2;
    gpiod_line_set_value(led_line, 1);
    usleep(half_cycle_time * 1000);
    gpiod_line_set_value(led_line, 0);
    usleep(half_cycle_time * 1000);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (setup_gpio() != 0 || setup_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct timeval start_time;
    gettimeofday(&start_time, NULL);

    while (keep_running) {
        int distance;
        if (read_distance(&distance) == 0) {
            struct timeval current_time;
            gettimeofday(&current_time, NULL);
            long elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000 +
                                (current_time.tv_usec - start_time.tv_usec) / 1000;

            printf("%ld ms: Distance = %d cm, Frequency = %d Hz\n", elapsed_time, distance, 1000 - (distance / 10));
            blink_led(distance);
        } else {
            fprintf(stderr, "Sensor absent or bus error\n");
        }

        usleep(100000); // 100 ms delay
    }

    cleanup();
    return EXIT_SUCCESS;
}

