#include <syslog.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x39
#define MLX75030_CMD_TRIGGER 0x00
#define MLX75030_CMD_DISTANCE 0x02
#define MLX75030_DELAY_MS 50
#define RETRY_LIMIT 3
#define LOG_FILE "distance_log.csv"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int read_distance(int fd, uint16_t *distance) {
    uint8_t low_byte, high_byte;
    int retries = 0;

    while (retries < RETRY_LIMIT) {
        if (i2c_write(fd, MLX75030_CMD_TRIGGER, 0x00) == 0) {
            usleep(MLX75030_DELAY_MS * 1000);
            if (i2c_read(fd, MLX75030_CMD_DISTANCE, &low_byte) == 0 &&
                i2c_read(fd, MLX75030_CMD_DISTANCE + 1, &high_byte) == 0) {
                *distance = (high_byte << 8) | low_byte;
                return 0;
            }
        }
        retries++;
        syslog(LOG_WARNING, "Retrying I2C read, attempt %d", retries);
    }
    syslog(LOG_ERR, "Failed to read distance after %d attempts", RETRY_LIMIT);
    return -1;
}

int main() {
    int i2c_fd;
    uint16_t distance;
    FILE *log_file;
    struct timespec ts;
    struct sigaction sa;

    openlog("MLX75030_Logger", LOG_PID | LOG_CONS, LOG_USER);

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,distance_cm\n");

    while (keep_running) {
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[64];
        snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

        if (read_distance(i2c_fd, &distance) == 0) {
            fprintf(log_file, "%s,%u\n", timestamp, distance);
            fflush(log_file);
        }

        usleep(100000); // 100 ms
    }

    fclose(log_file);
    close(i2c_fd);
    closelog();

    return EXIT_SUCCESS;
}

