#define DEBOUNCE_TIME_MS 50
#define POLL_INTERVAL_MS 10

static int log_fd = -1;
static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static int last_state1 = -1, last_state2 = -1;
static int debounce1 = 0, debounce2 = 0;

void log_event(int sensor_id, const char *event_type) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    char log_entry[50];
    snprintf(log_entry, sizeof(log_entry), "%s Sensor %d %s\n", timestamp, sensor_id, event_type);

    if (write(log_fd, log_entry, strlen(log_entry)) != (ssize_t)strlen(log_entry)) {
        perror("Failed to write to log file");
    }
}

void handle_signal(int sig) {
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    if (log_fd != -1) close(log_fd);
    exit(0);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int main() {
    setup_signal_handlers();

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, 17);
