    if (!line2) {
        perror("Failed to get line 27");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line1, "sensor1", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        perror("Failed to request line 1 as input");
        gpiod_line_release(line2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

