#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_SLAVE_ADDRESS 0x29
#define MEAS_STATUS_REG 0x00
#define MEAS_DISTANCE_REG 0x04
#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500

static int i2c_fd = -1;
static FILE *log_file = NULL;

void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int open_i2c_device() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int write_then_read_i2c(uint8_t reg, uint8_t *data, size_t length) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(i2c_fd, data, length) != length) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int get_distance(uint16_t *distance) {
    uint8_t status;
    if (write_then_read_i2c(MEAS_STATUS_REG, &status, 1) < 0) {
        return -1;
    }

    if (status & 0x01) { // Check if measurement is ready
        uint8_t distance_data[2];
        if (write_then_read_i2c(MEAS_DISTANCE_REG, distance_data, 2) < 0) {
            return -1;
        }
        *distance = (distance_data[0] << 8) | distance_data[1];
        return 0;
    }
    return -1;
}

void log_distance(uint16_t distance) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (open_i2c_device() < 0) {
        exit(EXIT_FAILURE);
    }

    log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "timestamp,distance_mm\n");

    while (1) {
        uint16_t distance;
        if (get_distance(&distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "I2C read error, skipping sample\n");
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    return 0;
}

