    uint8_t buffer[256];
    buffer[0] = reg;
    memcpy(buffer + 1, data, length);
    if (write(fd, buffer, length + 1) != length + 1) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, data, length) != length) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

