    uint8_t zone_config = 0x00; // Configure for 8x8 zone grid
    if (i2c_write(fd, VL53L5CX_REG_ZONE_CONFIG, &zone_config, 1) != 0) {
        return -1;
    }
    return 0;
}

int read_zone_data(int fd, uint16_t *zone_data) {
    uint8_t buffer[128];
    if (i2c_read(fd, VL53L5CX_REG_ZONE_DATA_START, buffer, VL53L5CX_ZONE_COUNT * 2) != 0) {
        return -1;
    }
    for (int i = 0; i < VL53L5CX_ZONE_COUNT; i++) {
        zone_data[i] = (buffer[i * 2] << 8) | buffer[i * 2 + 1];
    }
    return 0;
}

