        fprintf(stderr, "Failed to configure sensor\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        uint16_t zone_data[VL53L5CX_ZONE_COUNT];
