#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define MLX75030_I2C_ADDR 0x39
#define MLX75030_REG_DISTANCE 0x00
#define MLX75030_REG_STATUS 0x01
#define MLX75030_STATUS_BUSY 0x01
#define MLX75030_STATUS_ERROR 0x02
#define MLX75030_STATUS_DATA_READY 0x04
#define RETRY_LIMIT 3
#define RETRY_DELAY_MS 10

static volatile int keep_running = 1;
static struct i2c_client *i2c_client = NULL;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_read_byte(struct i2c_client *client, uint8_t reg, uint8_t *value) {
    int ret;
    uint8_t buf[1] = {reg};
    ret = i2c_smbus_write_i2c_block_data(client, reg, 1, buf);
    if (ret < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(-ret));
        return ret;
    }

    ret = i2c_smbus_read_byte_data(client, reg);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(-ret));
    } else {
        *value = ret;
    }
    return ret;
}

int read_distance(struct i2c_client *client, uint16_t *distance) {
    uint8_t status, distance_high, distance_low;
    int ret, attempts = 0;

    while (attempts < RETRY_LIMIT) {
        ret = i2c_read_byte(client, MLX75030_REG_STATUS, &status);
        if (ret < 0) {
            usleep(RETRY_DELAY_MS * 1000);
            attempts++;
            continue;
        }

        if (status & (MLX75030_STATUS_BUSY | MLX75030_STATUS_ERROR)) {
            fprintf(stderr, "Sensor busy or error status: 0x%02X\n", status);
            usleep(RETRY_DELAY_MS * 1000);
            attempts++;
            continue;
        }

        if (status & MLX75030_STATUS_DATA_READY) {
            ret = i2c_read_byte(client, MLX75030_REG_DISTANCE, &distance_high);
            if (ret < 0) {
                usleep(RETRY_DELAY_MS * 1000);
                attempts++;
                continue;
            }

            ret = i2c_read_byte(client, MLX75030_REG_DISTANCE + 1, &distance_low);
            if (ret < 0) {
                usleep(RETRY_DELAY_MS * 1000);
                attempts++;
                continue;
            }

