#define I2C_BUS 1
#define VL53L4CX_I2C_ADDR 0x29
#define VL53L4CX_INTERRUPT_STATUS_REG 0x04
#define VL53L4CX_MEASURED_DISTANCE_HIGH_REG 0x14
#define VL53L4CX_MEASURED_DISTANCE_LOW_REG 0x15

static int i2c_fd = -1;
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int i2c_write(int fd, uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_msg msgs[2];
    uint8_t buf[256];

    buf[0] = reg;
    memcpy(buf + 1, data, len);

    msgs[0].addr = VL53L4CX_I2C_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = buf;

    msgs[1].addr = VL53L4CX_I2C_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = len;
    msgs[1].buf = buf + 1;

    if (i2c_transfer(fd, msgs, 2) != 2) {
        perror("i2c_transfer");
        return -1;
    }

    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (i2c_write(fd, reg, NULL, 0) < 0) {
        return -1;
    }

    return i2c_read(fd, reg, data, len);
}

void log_distance(uint16_t distance) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm *tm_info = localtime(&tv.tv_sec);

    printf("Timestamp: %04d-%02d-%02d %02d:%02d:%02d.%06ld, Distance: %u mm\n",
           tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
           tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
           tv.tv_usec, distance);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-" PRIu8, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L4CX_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint8_t status;
        if (i2c_read(i2c_fd, VL53L4CX_INTERRUPT_STATUS_REG, &status, 1) < 0) {
            fprintf(stderr, "Transient I2C read error, skipping cycle\n");
            usleep(500000);
            continue;
        }

        if (status & 0x01) { // Check if the interrupt status bit is set
            uint8_t distance_high, distance_low;
            if (i2c_read(i2c_fd, VL53L4CX_MEASURED_DISTANCE_HIGH_REG, &distance_high, 1) < 0 ||
                i2c_read(i2c_fd, VL53L4CX_MEASURED_DISTANCE_LOW_REG, &distance_low, 1) < 0) {
                fprintf(stderr, "Transient I2C read error, skipping cycle\n");
                usleep(500000);
                continue;
            }

            uint16_t distance = (distance_high << 8) | distance_low;
            log_distance(distance);
        }

        usleep(500000);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

