#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_ADDR 0x29
#define GPIO_PIN 22
#define CONTINUOUS_RANGING_MODE 0x80
#define MEASURE_START 0x00
#define MEASURE_RESULT 0x01
#define MEASURE_READY 0x04
#define MEASURE_TIMEOUT 1000
#define DISTANCE_THRESHOLD 100

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write error");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read error");
        return -1;
    }
    return 0;
}

int configure_sensor(int fd) {
    uint8_t value;
    if (i2c_write(fd, 0x00, 0x01) < 0) return -1; // System Reset
    usleep(20000); // Wait for reset

    if (i2c_write(fd, 0x80, 0x01) < 0) return -1; // Start continuous ranging
    return 0;
}

int get_distance(int fd, int *distance) {
    uint8_t value;
    if (i2c_read(fd, MEASURE_RESULT, &value) < 0) return -1;
    if (i2c_read(fd, MEASURE_RESULT + 1, &value) < 0) return -1;
    *distance = (value << 8) | value;
    return 0;
}

int main() {
    int i2c_fd, gpio_fd;
    struct gpiod_line *buzzer_line;
    struct sigaction sa;
    int distance;

    // Setup signal handler for graceful shutdown
    sa.sa_handler = handle_sigint;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C device address
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure sensor
    if (configure_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO for buzzer
    buzzer_line = gpiod_chip_open("/dev/gpiochip0");
    if (!buzzer_line) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    gpio_fd = gpiod_line_request(buzzer_line, "buzzer", GPIOD_OUT_LOW);
    if (gpio_fd < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(buzzer_line);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (get_distance(i2c_fd, &distance) < 0) {
            fprintf(stderr, "I2C read error, skipping iteration\n");
        } else {
            if (distance < DISTANCE_THRESHOLD) {
                gpiod_line_set_value(buzzer_fd, 1);
                usleep(100000); // Buzzer on for 100ms
                gpiod_line_set_value(buzzer_fd, 0);
            }
        }
        usleep(500000); // Wait for 500ms
    }

    // Cleanup
    gpiod_line_release(buzzer_fd);
    gpiod_chip_close(buzzer_line);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

