#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17
#define TIMEOUT_MS 50
#define PULSE_WIDTH_US 10
#define LOOP_DELAY_MS 200
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define MIN_ANGLE -90
#define MAX_ANGLE 90

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

double calculate_distance(int duration) {
    return (double)duration / 58.2;
}

int calculate_angle(double distance) {
    if (distance < MIN_DISTANCE_CM) return MIN_ANGLE;
    if (distance > MAX_DISTANCE_CM) return MAX_ANGLE;
    return MIN_ANGLE + ((distance - MIN_DISTANCE_CM) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM));
}

void log_distance(double distance) {
    FILE *log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s: Distance: %.2f cm\n", ctime(&now), distance);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioServo(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize servo\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        gpioWrite(TRIGGER_PIN, 1);
        usleep(PULSE_WIDTH_US);
        gpioWrite(TRIGGER_PIN, 0);

        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

