    if (distance < MIN_DISTANCE_CM) return MIN_ANGLE;
    if (distance > MAX_DISTANCE_CM) return MAX_ANGLE;
    return MIN_ANGLE + ((distance - MIN_DISTANCE_CM) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM));
