        fprintf(stderr, "Failed to initialize VL53L1X\n");
        goto cleanup_and_exit;
    }

    if (init_gpio() < 0) {
        goto cleanup_and_exit;
    }

    line = gpiod_chip_get_line(gpiod_chip_open("/dev/gpiochip0"), GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        goto cleanup_and_exit;
    }

    if (init_mq(&mq) < 0) {
        goto cleanup_and_exit;
    }

    while (keep_running) {
        int distance = read_distance(i2c_fd);
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance\n");
        } else {
            if (mq_send(mq, (const char *)&distance, sizeof(int), 0) < 0) {
                perror("Failed to send message to queue");
