            if (distance < DISTANCE_THRESHOLD) {
                gpiod_line_set_value(line, 1);
                usleep(100000); // Buzzer on for 100ms
                gpiod_line_set_value(line, 0);
            }
        }
        usleep(50000); // 50ms delay
    }

cleanup_and_exit:
    cleanup(i2c_fd, mq, line);
    return 0;
}

