#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <inttypes.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define TRIG_EDGE_RISING 0
#define ECHO_EDGE_RISING 1
#define ECHO_EDGE_FALLING 0
#define TRIG_PULSE_NS 10000
#define TRIG_INTERVAL_NS 200000000
#define MIN_PULSE_WIDTH_US 100
#define MAX_PULSE_WIDTH_US 30000
#define TIMEOUT_US 60000

static int log_fd = -1;
static struct gpiod_chip *chip;
static struct gpiod_line *trig_line;
static struct gpiod_line *echo_line;
static uint64_t last_trigger_time = 0;
static uint64_t last_falling_edge_time = 0;
static uint64_t last_rising_edge_time = 0;
static volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_distance(double distance) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    char log_entry[100];
    snprintf(log_entry, sizeof(log_entry), "%s: Distance: %.2f cm\n", timestamp, distance);

    if (log_fd != -1) {
        dprintf(log_fd, "%s", log_entry);
        fflush(log_fd);
    }
    printf("%s", log_entry);
}

void echo_callback(struct gpiod_line *line, unsigned int events, void *user_data) {
    uint64_t current_time = gpiod_line_event_time(line);
    uint64_t pulse_width_us;

    if (events & GPIOD_LINE_EVENT_RISING_EDGE) {
        last_rising_edge_time = current_time;
    } else if (events & GPIOD_LINE_EVENT_FALLING_EDGE) {
        last_falling_edge_time = current_time;

        // Handle 32-bit tick wraparound
        if (last_falling_edge_time < last_rising_edge_time) {
            pulse_width_us = (UINT64_MAX - last_rising_edge_time + last_falling_edge_time + 1) * 1000 / gpiod_chip_get_clock_frequency(chip);
        } else {
            pulse_width_us = (last_falling_edge_time - last_rising_edge_time) * 1000 / gpiod_chip_get_clock_frequency(chip);
        }

        if (pulse_width_us < MIN_PULSE_WIDTH_US) {
            fprintf(stderr, "Warning: Pulse width too short (%" PRIu64 " µs), likely noise.\n", pulse_width_us);
        } else if (pulse_width_us > MAX_PULSE_WIDTH_US) {
            fprintf(stderr, "Warning: Pulse width too long (%" PRIu64 " µs), likely timeout/no object.\n", pulse_width_us);
        } else if (current_time - last_trigger_time > TIMEOUT_US * gpiod_chip_get_clock_frequency(chip) / 1000000) {
            fprintf(stderr, "Warning: Timeout waiting for echo.\n");
        } else {
            double distance_cm = pulse_width_us * 0.0343 / 2;
            log_distance(distance_cm);
        }
    }
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR || signal(SIGTERM, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handlers.\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get TRIG line.\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get ECHO line.\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig_line, "trig", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0) {
        fprintf(stderr, "Failed to request TRIG line as output.\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo_line, "echo", GPIOD_LINE_REQUEST_DIRECTIONS_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to request ECHO line as input.\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_event_both_edges(echo_line) < 0) {
        fprintf(stderr, "Failed to set ECHO line to both edges.\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_callback_add(echo_line, echo_callback, NULL) < 0) {
        fprintf(stderr, "Failed to add callback to ECHO line.\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_fd = open("distance_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file.\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpiod_line_set_value(trig_line, 1) < 0) {
            fprintf(stderr, "Failed to set TRIG line high.\n");
            break;
        }
        usleep(TRIG_PULSE_NS / 1000);
        if (gpiod_line_set_value(trig_line, 0) < 0) {
            fprintf(stderr, "Failed to set TRIG line low.\n");
            break;
        }
        last_trigger_time = gpiod_chip_get_clock_counter(chip);
        usleep(TRIG_INTERVAL_NS / 1000);
    }

    gpiod_line_callback_remove(echo_line);
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    if (log_fd != -1) {
        close(log_fd);
    }

    return EXIT_SUCCESS;
}

