#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_MODEL_ID_REG 0xC0
#define VL53L1X_MODEL_ID 0xEE
#define VL53L1X_SHUTDOWN_PIN 23
#define VL53L1X_INTERRUPT_PIN 24
#define SERVO_PIN 18
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "parking_log.txt"
#define OPEN_DISTANCE 50
#define CLOSE_DISTANCE 60

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int log_event(const char *event, int distance) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "[%s] %s: %d cm\n", timestamp, event, distance);
    fclose(log_file);
    return 0;
}

int read_i2c_byte(int file, uint8_t reg) {
    if (ioctl(file, I2C_SLAVE, VL53L1X_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access");
        return -1;
    }

    if (write(file, &reg, 1) != 1) {
        perror("Failed to write to i2c bus");
        return -1;
    }

    uint8_t data;
    if (read(file, &data, 1) != 1) {
        perror("Failed to read from i2c bus");
        return -1;
    }

    return data;
}

int write_i2c_byte(int file, uint8_t reg, uint8_t value) {
    if (ioctl(file, I2C_SLAVE, VL53L1X_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access");
        return -1;
    }

    uint8_t buffer[2] = {reg, value};
    if (write(file, buffer, 2) != 2) {
        perror("Failed to write to i2c bus");
        return -1;
    }

    return 0;
}

int read_distance(int file) {
    // Assuming the distance is read from a specific register
    // This is a placeholder for the actual distance reading logic
    uint8_t distance_high = read_i2c_byte(file, 0x8F);
    uint8_t distance_low = read_i2c_byte(file, 0x8E);

    if (distance_high == -1 || distance_low == -1) {
        return -1;
    }

    int distance = (distance_high << 8) | distance_low;
    return distance;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_file = open(I2C_BUS, O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VL53L1X_SHUTDOWN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(VL53L1X_INTERRUPT_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO modes");
        close(i2c_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(VL53L1X_SHUTDOWN_PIN, 0); // Enable sensor

    int model_id = read_i2c_byte(i2c_file, VL53L1X_MODEL_ID_REG);
    if (model_id == -1 || model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "VL53L1X sensor not found or model ID mismatch\n");
        close(i2c_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int distance = 0;
    int gate_open = 0;

    while (keep_running) {
        distance = read_distance(i2c_file);
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance\n");
            break;
        }

        if (distance <= OPEN_DISTANCE && !gate_open) {
            gpioPWM(SERVO_PIN, 1500, 25000); // Open gate
            log_event("Gate opened", distance);
            gate_open = 1;
        } else if (distance > CLOSE_DISTANCE && gate_open) {
            gpioPWM(SERVO_PIN, 500, 25000); // Close gate
            log_event("Gate closed", distance);
            gate_open = 0;
        }

        usleep(100000); // 100 ms delay
    }

    if (gate_open) {
        gpioPWM(SERVO_PIN, 500, 25000); // Ensure gate is closed
        log_event("Gate closed", distance);
    }

    close(i2c_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

