#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>
#include <time.h>

#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_SOFT_RESET 0x00
#define VL53L1X_SYSRANGE_START 0x00
#define VL53L1X_RESULT_INTERRUPT_STATUS 0x13
#define VL53L1X_RESULT_RANGE_STATUS 0x14
#define VL53L1X_RESULT_RANGE_VAL 0x06
#define GPIO_FORWARD 17
#define GPIO_BACKWARD 18
#define GPIO_TRIGGER 24

static volatile int keep_running = 1;
static int i2c_fd = -1;
static int forward_gpio = -1;
static int backward_gpio = -1;
static int trigger_gpio = -1;

void handle_signal(int sig) {
    keep_running = 0;
}

void stop_motor() {
    if (forward_gpio != -1) {
        gpioWrite(forward_gpio, 0);
    }
    if (backward_gpio != -1) {
        gpioWrite(backward_gpio, 0);
    }
}

int i2c_write(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    int retries = 0;
    int delay = 10; // Start with 10ms delay

    while (retries < 5) {
        if (write(i2c_fd, buf, 2) == 2) {
            return 0;
        }
        fprintf(stderr, "I2C write failed, retrying...\n");
        usleep(delay * 1000);
        delay *= 2;
        retries++;
    }
    return -1;
}

int i2c_read(uint8_t reg, uint8_t *value) {
    uint8_t buf[1] = {reg};
    int retries = 0;
    int delay = 10; // Start with 10ms delay

    while (retries < 5) {
        if (write(i2c_fd, buf, 1) == 1) {
            if (read(i2c_fd, value, 1) == 1) {
                return 0;
            }
        }
        fprintf(stderr, "I2C read failed, retrying...\n");
        usleep(delay * 1000);
        delay *= 2;
        retries++;
    }
    return -1;
}

int read_distance(uint16_t *distance) {
    uint8_t status;
    uint8_t range_status;
    uint8_t range_val[2];

    // Wait for data ready
    while (1) {
        if (i2c_read(VL53L1X_RESULT_INTERRUPT_STATUS, &status) != 0) {
            fprintf(stderr, "Failed to read interrupt status\n");
            return -1;
        }
        if (status & 0x07) { // Data ready bit
            break;
        }
        usleep(1000); // 1ms delay
    }

    // Read range status
    if (i2c_read(VL53L1X_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Failed to read range status\n");
        return -1;
    }

    // Read range value
    if (i2c_read(VL53L1X_RESULT_RANGE_VAL, range_val) != 0) {
        fprintf(stderr, "Failed to read range value\n");
        return -1;
    }

    *distance = (range_val[0] << 8) | range_val[1];
    return 0;
}

void trigger_callback(int gpio, unsigned level, uint32_t tick, void *userdata) {
    uint16_t distance;
    if (read_distance(&distance) == 0) {
        printf("Distance: %u mm\n", distance);
        if (distance < 100) {
            if (forward_gpio != -1) {
                gpioWrite(forward_gpio, 1);
                gpioWrite(backward_gpio, 0);
                printf("Motor running forward\n");
            }
        } else if (distance > 300) {
            if (backward_gpio != -1) {
                gpioWrite(forward_gpio, 0);
                gpioWrite(backward_gpio, 1);
                printf("Motor running backward\n");
            }
        } else {
            stop_motor();
            printf("Motor stopped\n");
        }
    } else {
        stop_motor();
        printf("Sensor error, stopping motor\n");
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    forward_gpio = gpioOpen(GPIO_FORWARD, O_RDWR);
    backward_gpio = gpioOpen(GPIO_BACKWARD, O_RDWR);
    trigger_gpio = gpioOpen(GPIO_TRIGGER, O_RDONLY);

    if (forward_gpio == -1 || backward_gpio == -1 || trigger_gpio == -1) {
        fprintf(stderr, "Failed to open GPIOs\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(forward_gpio, PI_OUTPUT);
    gpioSetMode(backward_gpio, PI_OUTPUT);
    gpioSetMode(trigger_gpio, PI_INPUT);

    gpioSetPullUpDown(trigger_gpio, PI_PUD_UP);
    gpioSetAlertFuncEx(trigger_gpio, trigger_callback, NULL, 0);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        stop_motor();
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(i2c_fd);
        stop_motor();
        gpioTerminate();
        return 1;
    }

    // Soft reset
    if (i2c_write(VL53L1X_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Failed to perform soft reset\n");
        close(i2c_fd);
        stop_motor();
        gpioTerminate();
        return 1;
    }
    usleep(1000); // 1ms delay

    // Start measurement
    if (i2c_write(VL53L1X_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Failed to start measurement\n");
        close(i2c_fd);
        stop_motor();
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        sleep(1);
    }

    // Cleanup
    stop_motor();
    close(i2c_fd);
    gpioTerminate();
    return 0;
}

