#define I2C_ADDR 0x5A
#define MPR121_RESET 0x80
#define MPR121_CONFIG1 0x5B
#define MPR121_TOUCH_STATUS 0x00
#define MPR121_ELE0_TCH 0x01
#define MPR121_ELE11_TCH 0x0C

#define GPIO_LED0 17
#define GPIO_LED1 18
#define GPIO_LED2 27
#define GPIO_LED3 22

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, data, length) != length) {
        perror("Failed to read data from the sensor");
        return -1;
    }

    return 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t data) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    uint8_t buffer[2] = {reg, data};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write data to the sensor");
        return -1;
    }

    return 0;
}

int initialize_sensor(int fd) {
    uint8_t config1;
    if (i2c_read(fd, MPR121_CONFIG1, &config1, 1) != 0) {
        return -1;
    }

    if (config1 != 0x5B) {
        fprintf(stderr, "Sensor not responding correctly\n");
        return -1;
    }

    return 0;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_LED0, PI_OUTPUT);
    gpioSetMode(GPIO_LED1, PI_OUTPUT);
    gpioSetMode(GPIO_LED2, PI_OUTPUT);
    gpioSetMode(GPIO_LED3, PI_OUTPUT);
}

void cleanup_gpio() {
    gpioTerminate();
}

void set_led_pattern(int pattern) {
    gpioWrite(GPIO_LED0, (pattern >> 0) & 0x01);
    gpioWrite(GPIO_LED1, (pattern >> 1) & 0x01);
    gpioWrite(GPIO_LED2, (pattern >> 2) & 0x01);
    gpioWrite(GPIO_LED3, (pattern >> 3) & 0x01);
}

void log_event(const char *event) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    printf("[%s] %s\n", timestamp, event);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, MPR121_RESET, 0x63) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_fd) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    setup_gpio();

    while (keep_running) {
        uint8_t touch_status;
        if (i2c_read(i2c_fd, MPR121_TOUCH_STATUS, &touch_status, 1) != 0) {
            break;
        }

        for (int i = 0; i < 12; i++) {
            if (touch_status & (1 << i)) {
                char event[50];
                snprintf(event, sizeof(event), "Electrode %d touched", i);
                log_event(event);
                set_led_pattern(i);
            }
        }

        usleep(50000); // Poll every 50 ms
    }

    cleanup_gpio();
    close(i2c_fd);

    return EXIT_SUCCESS;
}

