#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define LED_GPIO 27
#define LED_CHIP "gpiochip0"
#define LED_LINE 27

#define MPR121_REG_DEVID 0x00
#define MPR121_REG_FFI 0x02
#define MPR121_REG_SFI 0x05
#define MPR121_REG_ESI 0x06
#define MPR121_REG_MHDR 0x2B
#define MPR121_REG_NHDR 0x2C
#define MPR121_REG_NCLR 0x2D
#define MPR121_REG_FDLR 0x2E
#define MPR121_REG_MHDF 0x2F
#define MPR121_REG_NHDF 0x30
#define MPR121_REG_NCLF 0x31
#define MPR121_REG_FDLF 0x32
#define MPR121_REG_AFE1 0x5D
#define MPR121_REG_AFE2 0x5E
#define MPR121_REG_ECR 0x5F
#define MPR121_REG_CONFIG1 0x7B
#define MPR121_REG_CONFIG2 0x7C
#define MPR121_REG_MHDR 0x2B
#define MPR121_REG_NHDR 0x2C
#define MPR121_REG_NCLR 0x2D
#define MPR121_REG_FDLR 0x2E
#define MPR121_REG_MHDF 0x2F
#define MPR121_REG_NHDF 0x30
#define MPR121_REG_NCLF 0x31
#define MPR121_REG_FDLF 0x32

#define MPR121_TOUCH_THRESHOLD 20
#define MPR121_RELEASE_THRESHOLD 6
#define MPR121_DEBOUNCE 5

static int i2c_fd;
static struct gpiod_line *led_line;
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int i2c_write(uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

int i2c_read(uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

int verify_device() {
    uint8_t devid;
    if (i2c_read(MPR121_REG_DEVID, &devid) != 0) {
        return -1;
    }
    if (devid != 0x5A) {
        fprintf(stderr, "MPR121 device not found\n");
        return -1;
    }
    return 0;
}

int configure_mpr121() {
    if (i2c_write(MPR121_REG_FFI, 0x00) != 0 ||
        i2c_write(MPR121_REG_SFI, 0x00) ||
        i2c_write(MPR121_REG_ESI, 0x00) ||
        i2c_write(MPR121_REG_MHDR, MPR121_TOUCH_THRESHOLD) ||
        i2c_write(MPR121_REG_NHDR, MPR121_TOUCH_THRESHOLD) ||
        i2c_write(MPR121_REG_NCLR, MPR121_RELEASE_THRESHOLD) ||
        i2c_write(MPR121_REG_FDLR, MPR121_DEBOUNCE) ||
        i2c_write(MPR121_REG_MHDF, MPR121_TOUCH_THRESHOLD) ||
        i2c_write(MPR121_REG_NHDF, MPR121_TOUCH_THRESHOLD) ||
        i2c_write(MPR121_REG_NCLF, MPR121_RELEASE_THRESHOLD) ||
        i2c_write(MPR121_REG_FDLF, MPR121_DEBOUNCE) ||
        i2c_write(MPR121_REG_AFE1, 0x60) ||
        i2c_write(MPR121_REG_AFE2, 0x00) ||
        i2c_write(MPR121_REG_ECR, 0x00) ||
        i2c_write(MPR121_REG_CONFIG1, 0x0C) ||
        i2c_write(MPR121_REG_CONFIG2, 0x00)) {
        return -1;
    }
    return 0;
}

int setup_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int setup_led() {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(LED_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(led_line, "proximity_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }
    gpiod_chip_close(chip);
    return 0;
}

void log_proximity_event() {
    FILE *log_file = fopen("proximity.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log_file, "Proximity event detected at %s\n", timestamp);
    fclose(log_file);
}

void turn_on_led() {
    gpiod_line_set_value(led_line, 1);
}

void turn_off_led() {
    gpiod_line_set_value(led_line, 0);
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR ||
        signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (setup_i2c() != 0 || setup_led() != 0 || verify_device() != 0 || configure_mpr121() != 0) {
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint8_t touch_status[2];
        if (i2c_read(0x00, touch_status) == 0) {
            if (touch_status[0] & 0x01) { // Check if any touch is detected
                turn_on_led();
                log_proximity_event();
                sleep(1);
                turn_off_led();
            }
        }
        usleep(100000); // 100 ms delay
    }

    turn_off_led();
    gpiod_line_release(led_line);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

