        i2c_write(MPR121_REG_AFE2, 0x00) ||
        i2c_write(MPR121_REG_ECR, 0x00) ||
        i2c_write(MPR121_REG_CONFIG1, 0x0C) ||
        i2c_write(MPR121_REG_CONFIG2, 0x00)) {
        return -1;
    }
    return 0;
}

int setup_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int setup_led() {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(LED_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(led_line, "proximity_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }
    gpiod_chip_close(chip);
    return 0;
}

void log_proximity_event() {
    FILE *log_file = fopen("proximity.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log_file, "Proximity event detected at %s\n", timestamp);
    fclose(log_file);
}

void turn_on_led() {
    gpiod_line_set_value(led_line, 1);
}

void turn_off_led() {
    gpiod_line_set_value(led_line, 0);
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR ||
        signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (setup_i2c() != 0 || setup_led() != 0 || verify_device() != 0 || configure_mpr121() != 0) {
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint8_t touch_status[2];
        if (i2c_read(0x00, touch_status) == 0) {
            if (touch_status[0] & 0x01) { // Check if any touch is detected
                turn_on_led();
                log_proximity_event();
                sleep(1);
                turn_off_led();
            }
        }
        usleep(100000); // 100 ms delay
    }

    turn_off_led();
    gpiod_line_release(led_line);
    close(i2c_fd);

    return EXIT_SUCCESS;
}
