#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 34300 // cm/s
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define TIMEOUT_US 30000000 // 30 ms

volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int sig) {
    stop_flag = 1;
}

double measure_distance(struct gpiod_chip *chip, struct gpiod_line *trigger, struct gpiod_line *echo) {
    struct timespec start, end;
    long duration_ns;
    double distance_cm;

    // Hold trigger low for 5 µs
    gpiod_line_set_value(trigger, 0);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error setting trigger low\n");
        return -1;
    }
    usleep(5);

    // Pulse trigger high for 10 µs
    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Error setting trigger high\n");
        return -1;
    }
    usleep(10);

    // Return trigger low
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error setting trigger low\n");
        return -1;
    }

    // Wait for echo rising edge
    if (gpiod_line_event_wait(echo, GPIOD_LINE_EVENT_RISING, TIMEOUT_US) < 0) {
        if (errno == ETIMEDOUT) {
            fprintf(stderr, "Echo rising edge timeout\n");
            return -1;
        } else {
            fprintf(stderr, "Error waiting for echo rising edge\n");
            return -1;
        }
    }

    // Measure echo pulse width
    if (gpiod_line_event_wait(echo, GPIOD_LINE_EVENT_FALLING, TIMEOUT_US) < 0) {
        if (errno == ETIMEDOUT) {
            fprintf(stderr, "Echo falling edge timeout\n");
            return -1;
        } else {
            fprintf(stderr, "Error waiting for echo falling edge\n");
            return -1;
        }
    }

    // Get start and end times
    if (gpiod_line_event_read(echo, &start) < 0) {
        fprintf(stderr, "Error reading start time\n");
        return -1;
    }
    if (gpiod_line_event_read(echo, &end) < 0) {
        fprintf(stderr, "Error reading end time\n");
        return -1;
    }

    // Calculate duration in nanoseconds
    duration_ns = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);

    // Calculate distance in cm
    distance_cm = (duration_ns / 2.0) * SPEED_OF_SOUND / 1000000000.0;

    return distance_cm;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger, *echo;
    FILE *log_file;
    struct timespec ts;
    double distance_cm;
    int ret;

    // Install SIGINT handler
    signal(SIGINT, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get trigger line
    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request trigger line as output
    ret = gpiod_line_request(trigger, "trigger", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to request trigger line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get echo line
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_line_release(trigger);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request echo line as input
    ret = gpiod_line_request(echo, "echo", GPIOD_LINE_REQUEST_DIRECTIONS_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to request echo line\n");
        gpiod_line_release(trigger);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(echo);
        gpiod_line_release(trigger);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        distance_cm = measure_distance(chip, trigger, echo);

        if (distance_cm < 0) {
            fprintf(log_file, "Error measuring distance\n");
        } else if (distance_cm < MIN_DISTANCE || distance_cm > MAX_DISTANCE) {
            fprintf(log_file, "Out of range: %.2f cm\n", distance_cm);
        } else {
            clock_gettime(CLOCK_REALTIME, &ts);
            char timestamp[30];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&ts.tv_sec));
            fprintf(log_file, "%s %.2f cm\n", timestamp, distance_cm);
        }

        fflush(log_file);
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(echo);
    gpiod_line_release(trigger);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

