#define ECHO_GPIO_CHIP "gpiochip0"
#define TRIG_GPIO_LINE 17
#define ECHO_GPIO_LINE 18
#define TRIG_PULSE_NS 10000
#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_CM 1
#define MAX_PULSE_WIDTH_NS (MAX_DISTANCE_CM * 58 * 1000 * 1000)
#define MIN_PULSE_WIDTH_NS (MIN_DISTANCE_CM * 58 * 1000 * 1000)

static struct gpiod_line *trig_line = NULL;
static struct gpiod_line *echo_line = NULL;
static struct gpiod_chip *trig_chip = NULL;
static struct gpiod_chip *echo_chip = NULL;
static FILE *log_file = NULL;
static bool running = true;

static volatile uint64_t start_time = 0;
static volatile uint64_t end_time = 0;

static void handle_signal(int signum) {
    running = false;
}

static void echo_callback(struct gpiod_line *line, unsigned int events, void *user_data) {
    uint64_t current_time = gpiod_line_event_time(line);
    if (events & GPIOD_LINE_EVENT_RISING_EDGE) {
        start_time = current_time;
    } else if (events & GPIOD_LINE_EVENT_FALLING_EDGE) {
        end_time = current_time;
    }
}

static void setup_gpio() {
    trig_chip = gpiod_chip_open_by_name(TRIG_GPIO_CHIP);
    if (!trig_chip) {
        fprintf(stderr, "Failed to open GPIO chip for TRIG\n");
        exit(EXIT_FAILURE);
    }

    echo_chip = gpiod_chip_open_by_name(ECHO_GPIO_CHIP);
    if (!echo_chip) {
        fprintf(stderr, "Failed to open GPIO chip for ECHO\n");
        gpiod_chip_close(trig_chip);
        exit(EXIT_FAILURE);
    }

    trig_line = gpiod_chip_get_line(trig_chip, TRIG_GPIO_LINE);
    if (!trig_line) {
        fprintf(stderr, "Failed to get TRIG line\n");
        gpiod_chip_close(trig_chip);
        gpiod_chip_close(echo_chip);
        exit(EXIT_FAILURE);
    }

    echo_line = gpiod_chip_get_line(echo_chip, ECHO_GPIO_LINE);
    if (!echo_line) {
        fprintf(stderr, "Failed to get ECHO line\n");
        gpiod_chip_close(trig_chip);
        gpiod_chip_close(echo_chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(trig_line, "trig", GPIOD_LINE_REQUEST_DIRECTIONS_NONE)) {
        fprintf(stderr, "Failed to request TRIG line as output\n");
        gpiod_chip_close(trig_chip);
        gpiod_chip_close(echo_chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(echo_line, "echo", GPIOD_LINE_REQ_EV_BOTH_EDGES)) {
        fprintf(stderr, "Failed to request ECHO line as input\n");
        gpiod_line_release(trig_line);
        gpiod_chip_close(trig_chip);
        gpiod_chip_close(echo_chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_callback(echo_line, echo_callback, NULL, NULL);
}

static void cleanup_gpio() {
    if (trig_line) {
        gpiod_line_release(trig_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (trig_chip) {
        gpiod_chip_close(trig_chip);
    }
    if (echo_chip) {
        gpiod_chip_close(echo_chip);
    }
}

static void log_distance(uint64_t pulse_width_ns) {
    double distance_cm = pulse_width_ns / 58.0;
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: %f cm\n", time_str, distance_cm);
    fflush(log_file);
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR || signal(SIGTERM, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handlers\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    setup_gpio();

    while (running) {
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        usleep(1000000); // Wait for 1 second

        uint64_t pulse_width_ns = end_time - start_time;
        if (pulse_width_ns > 0 && pulse_width_ns <= MAX_PULSE_WIDTH_NS && pulse_width_ns >= MIN_PULSE_WIDTH_NS) {
            log_distance(pulse_width_ns);
        }
    }

    cleanup_gpio();
    fclose(log_file);

    return EXIT_SUCCESS;
}

