static int i2c_fd = -1;
static struct gpiod_line *xshut_line = NULL;
static VL53L1X_Dev_t myDevice;
static int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_with_timestamp(const char *level, const char *message) {
    time_t now = time(NULL);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&now));
    syslog(level, "%s: %s", time_str, message);
}

void initialize_gpio() {
    xshut_line = gpiod_chip_get_line_by_name(GPIO_CHIP, "27");
    if (!xshut_line) {
        syslog(LOG_ERR, "Failed to get GPIO line for XSHUT");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(xshut_line, "xshut_control", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line for XSHUT");
        exit(EXIT_FAILURE);
    }
}

void initialize_i2c() {
    i2c_fd = open("/dev/i2c-" PRIuMAX, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void initialize_sensor() {
    if (VL53L1X_Initialize(&myDevice, i2c_fd) != VL53L1X_ERROR_NONE) {
        syslog(LOG_ERR, "Failed to initialize VL53L1X sensor");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (xshut_line) {
        gpiod_line_release(xshut_line);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    VL53L1X_DeInit(&myDevice);
}

void read_sensor() {
    VL53L1X_RangingMeasurementData_t measure;
    VL53L1X_PerformSingleRangingMeasurement(&myDevice, &measure);

    if (measure.RangeStatus != 4) {
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Distance: %d mm, Status: %d", measure.RangeMilliMeter, measure.RangeStatus);
        log_with_timestamp("LOG_INFO", log_message);
    } else {
        log_with_timestamp("LOG_ERR", "Failed to read distance");
    }
}

int main() {
    openlog("vl53l1x_reader", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    initialize_gpio();
    gpiod_line_set_value(xshut_line, 1); // Set XSHUT high to enable the sensor

    initialize_i2c();
    initialize_sensor();

    while (keep_running) {
        read_sensor();
        usleep(100000); // Sleep for 100 ms
    }

    cleanup();
    closelog();
    return 0;
}

