#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define GPIO_PIN 24
#define LOG_FILE "gate_log.txt"
#define POLL_INTERVAL 100000 // 100 ms in microseconds
#define DISTANCE_THRESHOLD 20 // in centimeters

static int i2c_fd = -1;
static int gpio_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t stop = 0;

void log_message(const char *message) {
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file);
    }
}

void handle_signal(int sig) {
    stop = 1;
}

int init_gpio() {
    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    struct gpiod_line_request req = {
        .consumer_label = "gate_actuator",
        .flags = GPIOD_LINE_REQUEST_OUTPUT,
        .line_offset = GPIO_PIN,
        .request_type = GPIOD_LINE_REQ_DIR_OUTPUT,
        .default_value = 0
    };

    int line = gpiod_chip_get_line(gpio_fd, GPIO_PIN);
    if (line < 0) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_fd);
        return -1;
    }

    int ret = gpiod_line_request(line, &req);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_fd);
        return -1;
    }

    gpiod_line_release(line);
    return 0;
}

int init_i2c() {
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return -1;
    }

    // Initialize VL53L1X sensor
    uint8_t init_data[] = {0x00, 0x01}; // Example initialization data
    if (write(i2c_fd, init_data, sizeof(init_data)) != sizeof(init_data)) {
        perror("Failed to initialize VL53L1X sensor");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_distance() {
    uint8_t distance_data[2] = {0x00, 0x01}; // Example register addresses
    if (write(i2c_fd, distance_data, sizeof(distance_data)) != sizeof(distance_data)) {
        perror("Failed to write to VL53L1X sensor");
        return -1;
    }

    if (read(i2c_fd, distance_data, sizeof(distance_data)) != sizeof(distance_data)) {
        perror("Failed to read from VL53L1X sensor");
        return -1;
    }

    int distance_mm = (distance_data[0] << 8) | distance_data[1];
    return distance_mm / 10; // Convert mm to cm
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    if (gpio_fd >= 0) {
        gpiod_chip_close(gpio_fd);
        gpio_fd = -1;
    }

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        log_message("GPIO initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        log_message("I2C initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("System initialized successfully");

    int gate_state = 0; // 0: closed, 1: open
    while (!stop) {
        int distance_cm = read_distance();
        if (distance_cm < 0) {
            log_message("Error reading distance");
        } else {
            char log_buffer[100];
            snprintf(log_buffer, sizeof(log_buffer), "Distance: %d cm", distance_cm);
            log_message(log_buffer);

            if (distance_cm < DISTANCE_THRESHOLD && gate_state == 0) {
                gpiod_line_set_value(gpio_fd, GPIO_PIN, 1);
                gate_state = 1;
                log_message("Gate opened");
            } else if (distance_cm >= DISTANCE_THRESHOLD && gate_state == 1) {
                gpiod_line_set_value(gpio_fd, GPIO_PIN, 0);
                gate_state = 0;
                log_message("Gate closed");
            }
        }

        usleep(POLL_INTERVAL);
    }

    cleanup();
    log_message("Program terminated gracefully");
    return EXIT_SUCCESS;
}

