#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_CM 2
#define TIMEOUT_MS 30
#define PULSE_WIDTH_US 10
#define SAMPLES 5

volatile sig_atomic_t stop_flag = 0;
volatile uint32_t pulse_width = 0;
volatile bool new_pulse = false;

void handle_sigint(int sig) {
    stop_flag = 1;
}

void echo_callback(int gpio, uint32_t level, uint32_t tick) {
    static uint32_t start_tick = 0;
    if (level == 1) {
        start_tick = tick;
    } else if (level == 0 && start_tick != 0) {
        uint32_t end_tick = tick;
        uint32_t duration = end_tick - start_tick;
        pulse_width = duration;
        new_pulse = true;
    }
}

double calculate_distance(uint32_t pulse_width) {
    double distance_cm = (pulse_width / 1000000.0) * 34300.0 / 2.0;
    return distance_cm;
}

double moving_average(double *buffer, double new_value) {
    for (int i = 0; i < SAMPLES - 1; i++) {
        buffer[i] = buffer[i + 1];
    }
    buffer[SAMPLES - 1] = new_value;
    double sum = 0.0;
    for (int i = 0; i < SAMPLES; i++) {
        sum += buffer[i];
    }
    return sum / SAMPLES;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback, 0) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    FILE *file = fopen("distance_log.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        gpioTerminate();
        return 1;
    }
    fprintf(file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");

    double distance_buffer[SAMPLES] = {0};
    double distance = 0.0;
    int servo_angle = 90;

    while (!stop_flag) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelayMicroseconds(PULSE_WIDTH_US);
        gpioWrite(TRIGGER_PIN, 0);

        usleep(100000); // 100 ms delay

        if (new_pulse) {
            new_pulse = false;
            distance = calculate_distance(pulse_width);
            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                distance = -1.0;
                servo_angle = 90;
            } else {
                distance = moving_average(distance_buffer, distance);
            }

            if (gpioServo(SERVO_PIN, servo_angle) < 0) {
                fprintf(stderr, "Failed to set servo angle\n");
            }

            time_t now = time(NULL);
            fprintf(file, "%ld,%f,%d\n", now, distance, servo_angle);
            fflush(file);
        }
    }

    gpioServo(SERVO_PIN, 0);
    fclose(file);
    gpioTerminate();
    return 0;
}

