#include <string.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_ADDR 0x29
#define GPIO_LED 17
#define BUFFER_SIZE 10
#define THRESHOLD_DISTANCE 200

static volatile int keep_running = 1;
static int i2c_fd;
static gpiod_chip *chip;
static gpiod_line *led_line;
static int buffer[BUFFER_SIZE];
static int buffer_index = 0;

void handle_sigint(int sig) {
    keep_running = 0;
}

void write_i2c(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write error");
    }
}

uint8_t read_i2c(uint8_t reg) {
    uint8_t buf[1] = {reg};
    uint8_t value;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("I2C write error");
        return 0;
    }
    if (read(i2c_fd, &value, 1) != 1) {
        perror("I2C read error");
        return 0;
    }
    return value;
}

void init_sensor() {
    // Set default configuration
    write_i2c(0x88, 0x00);
    write_i2c(0x80, 0x01);
    write_i2c(0xFF, 0x01);
    write_i2c(0x00, 0x00);
    write_i2c(0xFF, 0x00);

    // Enable signal-rate check
    write_i2c(0x83, 0x44);

    // Configure cross-talk compensation
    write_i2c(0x94, 0x00);
    write_i2c(0x83, 0x24);

    // Start ranging
    write_i2c(0x00, 0x01);
}

int read_distance() {
    write_i2c(0x00, 0x01);
    usleep(10000); // Wait for measurement

    uint8_t part_high = read_i2c(0x8F);
    uint8_t part_low = read_i2c(0x90);

    if (part_high == 0 && part_low == 0) {
        perror("Failed to read distance");
        return -1;
    }

    int distance = (part_high << 8) | part_low;
    return distance;
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "warning_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    gpiod_line_set_value(led_line, 0);
}

int main() {
    signal(SIGINT, handle_sigint);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    setup_gpio();

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int distance = read_distance();
        if (distance >= 0) {
            buffer[buffer_index] = distance;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            if (distance < THRESHOLD_DISTANCE) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        }

        usleep(50000); // 50 ms delay
    }

    cleanup();
    return EXIT_SUCCESS;
}

