#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pthread.h>

#define DEFAULT_I2C_ADDRESS 0x4A
#define DEFAULT_THRESHOLD 1000
#define GPIO_PIN 27
#define I2C_BUS "/dev/i2c-1"
#define PROXIMITY_LOG "proximity.log"

volatile sig_atomic_t stop_flag = 0;
volatile int proximity_value = 0;
int i2c_fd;
int log_fd;
int threshold = DEFAULT_THRESHOLD;
uint8_t i2c_address = DEFAULT_I2C_ADDRESS;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void handle_sigint(int sig) {
    stop_flag = 1;
}

void log_proximity_value(int value) {
    pthread_mutex_lock(&log_mutex);
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    char status[6] = "SAFE";
    if (value > threshold) {
        strcpy(status, "ALERT");
    }

    dprintf(log_fd, "%s %d %s\n", timestamp, value, status);
    pthread_mutex_unlock(&log_mutex);
}

void *interrupt_handler(void *arg) {
    struct gpiod_line *line = (struct gpiod_line *)arg;
    while (!stop_flag) {
        if (gpiod_line_event_wait(line, -1) == 0) {
            if (gpiod_line_event_read(line) == GPIOD_LINE_EVENT_RISING_EDGE) {
                uint8_t buffer[2];
                if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
                    fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
                    continue;
                }

                buffer[0] = 0x00; // Proximity register address
                if (write(i2c_fd, buffer, 1) != 1) {
                    fprintf(stderr, "Failed to write to I2C: %s\n", strerror(errno));
                    continue;
                }

                if (read(i2c_fd, buffer, 2) != 2) {
                    fprintf(stderr, "Failed to read from I2C: %s\n", strerror(errno));
                    continue;
                }

                proximity_value = (buffer[0] << 8) | buffer[1];
                log_proximity_value(proximity_value);
            }
        }
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_sigint);

    int opt;
    while ((opt = getopt(argc, argv, "t:a:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'a':
                i2c_address = (uint8_t)strtol(optarg, NULL, 0);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t <threshold>] [-a <i2c_address>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    log_fd = open(PROXIMITY_LOG, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        close(log_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        close(log_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line, "proximity_interrupt", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(log_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, interrupt_handler, line) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(log_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (!stop_flag) {
        sleep(1);
    }

    pthread_cancel(thread);
    pthread_join(thread, NULL);

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(log_fd);
    close(i2c_fd);

    return 0;
}

