#define ECHO_PIN 24
#define PWM_PIN 18
#define TIMEOUT_MS 200
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 200
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

double calculate_frequency(double distance_cm) {
    if (distance_cm < MIN_DISTANCE_CM) distance_cm = MIN_DISTANCE_CM;
    if (distance_cm > MAX_DISTANCE_CM) distance_cm = MAX_DISTANCE_CM;
    return MIN_FREQUENCY_HZ * pow(10, (log10(MAX_DISTANCE_CM / MIN_DISTANCE_CM) * (MAX_DISTANCE_CM - distance_cm) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM)));
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    int ret;
    unsigned int echo_value;
    unsigned long long pulse_start, pulse_end;
    double distance_cm, frequency;
    int pwm_handle;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    pwm_handle = pigpioMyNewPWM(PWM_PIN, 0, 0);
    if (pwm_handle < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        pigpioStop();
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(chip);
        pigpioStop();
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_chip_close(chip);
        pigpioStop();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(trigger_line, "trigger", GPIOD_LINE_REQUEST_DIRECTIONS_OUT);
    if (ret) {
        fprintf(stderr, "Failed to request trigger line\n");
        gpiod_chip_close(chip);
        pigpioStop();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(echo_line, "echo", GPIOD_LINE_REQUEST_DIRECTIONS_IN);
    if (ret) {
        fprintf(stderr, "Failed to request echo line\n");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        pigpioStop();
        return EXIT_FAILURE;
    }

    frequency = MIN_FREQUENCY_HZ;
    while (keep_running) {
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        pulse_start = gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, TIMEOUT_MS * 1000);
        if (pulse_start < 0) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            continue;
        }

        pulse_end = gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, TIMEOUT_MS * 1000);
        if (pulse_end < 0) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            continue;
        }

        echo_value = pulse_end - pulse_start;
        distance_cm = echo_value / 58.0;

        frequency = calculate_frequency(distance_cm);

        int period = 1000000 / frequency;
        int pulse_width = period / 2;
        ret = pigpioSetPWMRange(pwm_handle, period);
        if (ret < 0) {
            fprintf(stderr, "Failed to set PWM range\n");
            break;
        }
        ret = pigpioSetPWM(pwm_handle, pulse_width);
        if (ret < 0) {
            fprintf(stderr, "Failed to set PWM pulse width\n");
            break;
        }

        usleep(10000); // 10ms delay between measurements
    }

    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    pigpioStop();

    return EXIT_SUCCESS;
}
