#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 100000
#define MEASURE_DELAY_MS 10
#define MIN_DISTANCE_CM 5
#define MAX_DISTANCE_CM 50
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    keep_running = 0;
}

double measure_distance() {
    if (gpioTrigger(TRIGGER_PIN, 0) < 0 || gpioTrigger(TRIGGER_PIN, 1, TRIGGER_PULSE_US) < 0) {
        fprintf(stderr, "Error triggering sensor\n");
        return -1;
    }

    if (gpioWaitTrigger(ECHO_PIN, ECHO_TIMEOUT_US) < 0) {
        fprintf(stderr, "Echo timeout\n");
        return -1;
    }

    uint32_t start = gpioTick();
    if (gpioWaitTrigger(ECHO_PIN, 0) < 0) {
        fprintf(stderr, "Error waiting for echo\n");
        return -1;
    }

    uint32_t end = gpioTick();
    uint32_t pulse_width_us = gpioTickDiff(start, end);
    double distance_cm = pulse_width_us / 58.0;

    return distance_cm;
}

double map_distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE_CM) return MIN_FREQUENCY_HZ;
    if (distance > MAX_DISTANCE_CM) return MAX_FREQUENCY_HZ;
    return MIN_FREQUENCY_HZ + (distance - MIN_DISTANCE_CM) * (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 || gpioSetMode(ECHO_PIN, PI_INPUT) < 0 || gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double last_valid_distance = -1;
    double last_valid_frequency = 0;

    while (keep_running) {
        double distance = measure_distance();
        if (distance < 0) {
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        double frequency = map_distance_to_frequency(distance);
        if (frequency < MIN_FREQUENCY_HZ || frequency > MAX_FREQUENCY_HZ) {
            frequency = last_valid_frequency;
        } else {
            last_valid_frequency = frequency;
        }

        if (gpioPWM(BUZZER_PIN, frequency) < 0) {
            fprintf(stderr, "Failed to set PWM frequency\n");
            break;
        }

        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        usleep(MEASURE_DELAY_MS * 1000);
    }

    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

