#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <stdbool.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TRIGGER_GPIO_CHIP "bcm2835_gpio"
#define ECHO_GPIO_CHIP "bcm2835_gpio"
#define TRIGGER_GPIO_LINE TRIGGER_PIN
#define ECHO_GPIO_LINE ECHO_PIN
#define TRIGGER_PULSE_NS 10000
#define ECHO_TIMEOUT_NS 50000000
#define LOOP_DELAY_MS 500
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define TOO_CLOSE_DISTANCE_CM 10

volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int sig) {
    exit_flag = 1;
}

int main() {
    struct gpiod_chip *trigger_chip, *echo_chip;
    struct gpiod_line *trigger_line, *echo_line;
    struct gpiod_line_request *trigger_request, *echo_request;
    struct gpiod_line_event event;
    int ret;
    unsigned long long pulse_duration_ns;
    double distance_cm;

    // Install SIGINT handler
    signal(SIGINT, handle_sigint);

    // Open GPIO chip for trigger pin
    trigger_chip = gpiod_chip_open(TRIGGER_GPIO_CHIP);
    if (!trigger_chip) {
        fprintf(stderr, "Failed to open GPIO chip for trigger pin\n");
        return EXIT_FAILURE;
    }

    // Open GPIO chip for echo pin
    echo_chip = gpiod_chip_open(ECHO_GPIO_CHIP);
    if (!echo_chip) {
        fprintf(stderr, "Failed to open GPIO chip for echo pin\n");
        gpiod_chip_close(trigger_chip);
        return EXIT_FAILURE;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(trigger_chip, TRIGGER_GPIO_LINE);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        return EXIT_FAILURE;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(echo_chip, ECHO_GPIO_LINE);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        return EXIT_FAILURE;
    }

    // Request trigger line as output
    trigger_request = gpiod_line_request(trigger_line, "trigger_request", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    if (!trigger_request) {
        fprintf(stderr, "Failed to request trigger line\n");
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        return EXIT_FAILURE;
    }

    // Request echo line as input
    echo_request = gpiod_line_request(echo_line, "echo_request", GPIOD_LINE_REQUEST_DIRECTIONS_INPUT);
    if (!echo_request) {
        fprintf(stderr, "Failed to request echo line\n");
        gpiod_line_release(trigger_request);
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        return EXIT_FAILURE;
    }

    // Set trigger line to low
    gpiod_line_set_value(trigger_line, 0);

    while (!exit_flag) {
        // Send 10us pulse on trigger line
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo line to go high
        ret = gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, ECHO_TIMEOUT_NS);
        if (ret < 0) {
            fprintf(stderr, "Timeout waiting for echo line to go high\n");
            pulse_duration_ns = -1;
        } else {
            // Wait for echo line to go low
            ret = gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, ECHO_TIMEOUT_NS);
            if (ret < 0) {
                fprintf(stderr, "Timeout waiting for echo line to go low\n");
                pulse_duration_ns = -1;
            } else {
                // Get pulse duration
                ret = gpiod_line_event_read(echo_line, &event);
                if (ret < 0) {
                    fprintf(stderr, "Failed to read echo line event\n");
                    pulse_duration_ns = -1;
                } else {
                    pulse_duration_ns = event.ts.tv_nsec - event.ts_prev.tv_nsec;
                }
            }
        }

        // Calculate distance
        if (pulse_duration_ns == -1) {
            distance_cm = -1;
        } else {
            distance_cm = pulse_duration_ns * 0.0343 / 2;
        }

        // Print distance or error message
        if (distance_cm < 0) {
            printf("Invalid reading\n");
        } else if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm", distance_cm);
            if (distance_cm < TOO_CLOSE_DISTANCE_CM) {
                printf(" Too close!\n");
            } else {
                printf("\n");
            }
        }

        // Delay before next measurement
        usleep(LOOP_DELAY_MS * 1000);
    }

    // Release resources
    gpiod_line_release(trigger_request);
    gpiod_line_release(echo_request);
    gpiod_chip_close(trigger_chip);
    gpiod_chip_close(echo_chip);

    return EXIT_SUCCESS;
}

