#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SI1175_I2C_ADDRESS 0x39
#define ALS_VISIBLE_REG 0x0A

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int address) {
    int file;
    if ((file = open(device, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }
    if (ioctl(file, I2C_SLAVE, address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return -1;
    }
    return file;
}

int read_als_visible(int file) {
    uint8_t reg = ALS_VISIBLE_REG;
    uint8_t buffer[2];
    if (write(file, &reg, 1) != 1) {
        perror("Failed to write to i2c bus");
        return -1;
    }
    if (read(file, buffer, 2) != 2) {
        perror("Failed to read from i2c bus");
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

void log_als_value(int file, FILE *log_file) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    int als_value = read_als_visible(file);
    if (als_value < 0) {
        fprintf(stderr, "Error reading ALS value\n");
        return;
    }

    if (fprintf(log_file, "%s,%d\n", timestamp, als_value) < 0) {
        perror("Failed to write to log file");
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_file = open_i2c_device(I2C_DEVICE, SI1175_I2C_ADDRESS);
    if (i2c_file < 0) {
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("proximity_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_file);
        return EXIT_FAILURE;
    }

    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
        if (ferror(log_file)) {
            perror("Failed to write header to log file");
            fclose(log_file);
            close(i2c_file);
            return EXIT_FAILURE;
        }
    }

    while (keep_running) {
        log_als_value(i2c_file, log_file);
        fflush(log_file);
        sleep(5);
    }

    fclose(log_file);
    close(i2c_file);
    return EXIT_SUCCESS;
}

