#define SI1120_COMMAND 0x80
#define SI1120_RESET 0x30
#define SI1120_PART_ID 0x00
#define SI1120_EXPECTED_PART_ID 0x12
#define SI1120_ALS_DATA 0x0A
#define SI1120_PROX_DATA 0x0C
#define RETRY_LIMIT 3
#define RETRY_DELAY_MS 10

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    for (int attempt = 0; attempt < RETRY_LIMIT; ++attempt) {
        if (write(fd, buf, 2) == 2) {
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    for (int attempt = 0; attempt < RETRY_LIMIT; ++attempt) {
        if (read(fd, data, length) == length) {
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int initialize_sensor(int fd) {
    uint8_t part_id;
    if (i2c_write(fd, SI1120_COMMAND | SI1120_RESET, 0x00) != 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        return -1;
    }
    if (i2c_read(fd, SI1120_PART_ID, &part_id, 1) != 0) {
        fprintf(stderr, "Failed to read part ID\n");
        return -1;
    }
    if (part_id != SI1120_EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected part ID: 0x%02X\n", part_id);
        return -1;
    }
    return 0;
}

int read_sensor_data(int fd, uint16_t *als, uint16_t *prox) {
    uint8_t als_data[2], prox_data[2];
    if (i2c_read(fd, SI1120_ALS_DATA, als_data, 2) != 0) {
        fprintf(stderr, "Failed to read ALS data\n");
        return -1;
    }
    *als = (uint16_t)als_data[1] | ((uint16_t)als_data[0] << 8);
    if (i2c_read(fd, SI1120_PROX_DATA, prox_data, 2) != 0) {
        fprintf(stderr, "Failed to read proximity data\n");
        return -1;
    }
    *prox = (uint16_t)prox_data[1] | ((uint16_t)prox_data[0] << 8);
    return 0;
}

void log_data(FILE *log_file, uint16_t als, uint16_t prox) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s ALS: %u Proximity: %u\n", timestamp, als, prox);
    fflush(log_file);
}

