    signal(SIGINT, handle_signal);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1120_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_fd) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("si1120_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint16_t als, prox;
        if (read_sensor_data(i2c_fd, &als, &prox) == 0) {
            log_data(log_file, als, prox);
        }
        usleep(500 * 1000);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

