#define I2C_ADDRESS 0x5A
#define MAX_RETRIES 3

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct si1145_dev *sensor = NULL;

void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (sensor != NULL) {
        si1145_close(sensor);
    }
    exit(0);
}

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "[%s] ERROR: %s\n", time_str, message);
    fflush(log_file);
}

void log_proximity(uint16_t proximity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "[%s] Proximity: %u\n", time_str, proximity);
    fflush(log_file);
}

int read_proximity(uint16_t *proximity) {
    uint8_t ps1_data0, ps1_data1;
    int retries = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = si1145_read_reg(sensor, SI1145_REG_PS1_DATA0, &ps1_data0);
        if (ret == 0) {
            ret = si1145_read_reg(sensor, SI1145_REG_PS1_DATA1, &ps1_data1);
            if (ret == 0) {
                *proximity = (ps1_data1 << 8) | ps1_data0;
                return 0;
            }
        }
        retries++;
        log_error("I2C read error, retrying...");
    }
    log_error("I2C read error, retries exhausted.");
    return -1;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    sensor = si1145_open(i2c_fd);
    if (sensor == NULL) {
        log_error("Failed to initialize Si1145 sensor");
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t proximity;
        if (read_proximity(&proximity) == 0) {
            log_proximity(proximity);
        } else {
            handle_signal(SIGTERM);
        }
        usleep(100000); // Sleep for 100ms
    }

    handle_signal(SIGTERM);
    return EXIT_SUCCESS;
}

