#include <time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define TRIGGER_PULSE_WIDTH_NS 10
#define MAX_DISTANCE_CM 20
#define SPEED_OF_SOUND_CM_PER_US 0.0343

static volatile int running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line, *echo_line, *buzzer_line;
static struct timespec echo_start, echo_end;
static int echo_detected = 0;

void handle_sigint(int sig) {
    running = 0;
}

void echo_callback(struct gpiod_line *line, unsigned int ev_type, unsigned int ev_value) {
    if (ev_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        if (clock_gettime(CLOCK_MONOTONIC, &echo_start) == -1) {
            perror("clock_gettime");
            exit(EXIT_FAILURE);
        }
        echo_detected = 1;
    } else if (ev_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        if (clock_gettime(CLOCK_MONOTONIC, &echo_end) == -1) {
            perror("clock_gettime");
            exit(EXIT_FAILURE);
        }
        echo_detected = 0;
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request(trigger_line, "trigger", GPIOD_LINE_REQUEST_DIRECTIONS_OUT) < 0) {
        fprintf(stderr, "Failed to request trigger line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request(echo_line, "echo", GPIOD_LINE_REQUEST_DIRECTIONS_IN) < 0) {
        fprintf(stderr, "Failed to request echo line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_event_both_edges(echo_line) < 0) {
        fprintf(stderr, "Failed to set both edges for echo line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_callback(echo_line, echo_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set callback for echo line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request(buzzer_line, "buzzer", GPIOD_LINE_REQUEST_DIRECTIONS_OUT) < 0) {
        fprintf(stderr, "Failed to request buzzer line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        gpiod_line_set_value(trigger_line, 1);
        nanosleep((const struct timespec[]){{0, TRIGGER_PULSE_WIDTH_NS}}, NULL);
        gpiod_line_set_value(trigger_line, 0);

        while (echo_detected) {
            usleep(100); // Wait for echo to be detected
        }

        if (echo_detected) {
            double echo_duration_us = (echo_end.tv_sec - echo_start.tv_sec) * 1e6 +
                                      (echo_end.tv_nsec - echo_start.tv_nsec) / 1e3;
            double distance_cm = echo_duration_us * SPEED_OF_SOUND_CM_PER_US / 2;
            printf("Distance: %.2f cm\n", distance_cm);

            if (distance_cm < MAX_DISTANCE_CM) {
                gpiod_line_set_value(buzzer_line, 1);
            } else {
                gpiod_line_set_value(buzzer_line, 0);
            }
        }

        sleep(1);
    }

    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

