#define PULSE_MIN 500
#define PULSE_MAX 2500
#define PULSE_RANGE (PULSE_MAX - PULSE_MIN)
#define UPDATE_INTERVAL 100 // milliseconds

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

double measure_distance() {
    int trigger_fd = gpiod_chip_open("/dev/gpiochip0");
    if (trigger_fd < 0) {
        perror("Failed to open GPIO chip");
        return -1.0;
    }

    int trigger_line = gpiod_chip_get_line(trigger_fd, TRIGGER_PIN);
    if (trigger_line < 0) {
        perror("Failed to get trigger line");
        gpiod_chip_close(trigger_fd);
        return -1.0;
    }

    int echo_fd = gpiod_chip_open("/dev/gpiochip0");
    if (echo_fd < 0) {
        perror("Failed to open GPIO chip");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(trigger_fd);
        return -1.0;
    }

    int echo_line = gpiod_chip_get_line(echo_fd, ECHO_PIN);
    if (echo_line < 0) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(trigger_fd);
        gpiod_chip_close(echo_fd);
        return -1.0;
    }

    gpiod_line_request_output(trigger_line, "trigger", 0);
    gpiod_line_request_input(echo_line, "echo", GPIOD_LINE_REQ_EV_BOTH_EDGES);

    gpiod_line_set_value(trigger_line, 1);
    usleep(10);
    gpiod_line_set_value(trigger_line, 0);

    struct timespec start, end;
    if (clock_gettime(CLOCK_MONOTONIC, &start) != 0) {
        perror("Failed to get start time");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(trigger_fd);
        gpiod_chip_close(echo_fd);
        return -1.0;
    }

    int edge_count = 0;
    while (edge_count < 2) {
        if (gpiod_line_event_wait(echo_line, -1) < 0) {
            perror("Echo timeout");
            gpiod_line_release(trigger_line);
            gpiod_line_release(echo_line);
            gpiod_chip_close(trigger_fd);
            gpiod_chip_close(echo_fd);
            return -1.0;
        }
        edge_count++;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
        perror("Failed to get end time");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(trigger_fd);
        gpiod_chip_close(echo_fd);
        return -1.0;
    }

    double time_elapsed = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
    double distance = time_elapsed * 34300 / 2; // Speed of sound in cm/s

    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(trigger_fd);
    gpiod_chip_close(echo_fd);

    return distance;
}

void set_servo_angle(int angle) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    int pulse_width = PULSE_MIN + (PULSE_RANGE * (angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE));
    gpioPWM(SERVO_PIN, 50, pulse_width);

    gpioTerminate();
}

double map_distance_to_angle(double distance) {
    if (distance <= MIN_DISTANCE) return MAX_ANGLE;
    if (distance >= MAX_DISTANCE) return MIN_ANGLE;
    return MIN_ANGLE + (MAX_ANGLE - MIN_ANGLE) * (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Error measuring distance, retrying...\n");
            continue;
        }

        printf("Distance: %.2f cm\n", distance);

        double angle = map_distance_to_angle(distance);
        set_servo_angle((int)angle);

        printf("Servo Angle: %.0f°\n", angle);

        gpioDelay(UPDATE_INTERVAL);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

