#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_MODEL_ID_REG 0xC0
#define VL53L1X_MODEL_ID 0xEE
#define VL53L1X_SYSRANGE_START 0x00
#define VL53L1X_RESULT_RANGE_STATUS 0x14
#define VL53L1X_RESULT_RANGE_VAL 0x06
#define VL53L1X_SYSRANGE_START_STOP 0x00
#define VL53L1X_SYSRANGE_START_CONT 0x01
#define VL53L1X_GPIO_PWM_PIN 18
#define VL53L1X_I2C_BUS "/dev/i2c-1"
#define DISTANCE_THRESHOLD_FAR 250
#define DISTANCE_THRESHOLD_CLOSE 200
#define PULSE_WIDTH_FAR 1000
#define PULSE_WIDTH_CLOSE 2000

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_read_byte(int fd, uint8_t reg) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, buffer, 1) != 1) {
        perror("I2C read");
        return -1;
    }
    return buffer[0];
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buffer[3];
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, buffer, 2) != 2) {
        perror("I2C read");
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

void log_event(const char *event) {
    FILE *log_file = fopen("gate_log.txt", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %s\n", ctime(&now), event);
        fclose(log_file);
    } else {
        perror("Failed to open log file");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    int i2c_fd = open(VL53L1X_I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_read_byte(i2c_fd, VL53L1X_MODEL_ID_REG) != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Invalid sensor model ID\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(i2c_fd, 0x80, 0x01) < 0 || // System control register
        i2c_write_byte(i2c_fd, 0xFF, 0x01) < 0 || // System ranging start
        i2c_write_byte(i2c_fd, 0x00, 0x00) < 0 || // Intermeasurement period
        i2c_write_byte(i2c_fd, 0x91, 0x00) < 0 || // Final range timeout
        i2c_write_byte(i2c_fd, 0x00, 0x01) < 0) { // Start ranging
        fprintf(stderr, "Failed to configure sensor\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioServoSetup(VL53L1X_GPIO_PWM_PIN, 50) < 0) {
        fprintf(stderr, "Failed to setup PWM\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_gate_state = -1;
    while (keep_running) {
        if (i2c_write_byte(i2c_fd, VL53L1X_SYSRANGE_START, VL53L1X_SYSRANGE_START_CONT) < 0) {
            fprintf(stderr, "Failed to start ranging\n");
            break;
        }

        usleep(10000); // Wait for measurement to complete

        int status = i2c_read_byte(i2c_fd, VL53L1X_RESULT_RANGE_STATUS);
        if (status & 0x01) { // Check if measurement is valid
            int distance = i2c_read_word(i2c_fd, VL53L1X_RESULT_RANGE_VAL);
            int gate_state = (distance > DISTANCE_THRESHOLD_FAR) ? PULSE_WIDTH_FAR : PULSE_WIDTH_CLOSE;

            if (distance < DISTANCE_THRESHOLD_CLOSE) {
                gate_state = PULSE_WIDTH_CLOSE;
            }

            if (gate_state != last_gate_state) {
                gpioServoPulse(VL53L1X_GPIO_PWM_PIN, gate_state);
                char event[50];
                snprintf(event, sizeof(event), "Gate %s", (gate_state == PULSE_WIDTH_FAR) ? "opened" : "closed");
                log_event(event);
                last_gate_state = gate_state;
            }
        }
    }

    gpioServoPulse(VL53L1X_GPIO_PWM_PIN, 0);
    close(i2c_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

