#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <math.h>

#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define SERVO_GPIO 18
#define TRIGGER_PULSE_NS 10
#define TIMEOUT_NS 50000000
#define PAUSE_NS 100000000
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_SERVO_PULSE_US 500
#define MAX_SERVO_PULSE_US 2500
#define MIN_DISTANCE_SERVO_CM 20.0
#define MAX_DISTANCE_SERVO_CM 200.0

static volatile int keep_running = 1;
static gpiod_chip *chip;
static gpiod_line *trigger_line;
static gpiod_line *echo_line;
static gpiod_line *servo_line;

void handle_sigint(int sig) {
    keep_running = 0;
    gpiod_line_set_value(servo_line, 0); // Stop the servo
    gpiod_line_release(servo_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);
    printf("Program terminated gracefully.\n");
    exit(0);
}

double measure_distance() {
    struct gpiod_line_event event;
    struct timespec ts;
    int ret;

    // Send trigger pulse
    ret = gpiod_line_set_value(trigger_line, 1);
    if (ret < 0) {
        perror("Failed to set trigger line high");
        return -1.0;
    }
    nanosleep(&ts, NULL); // Sleep for 10us
    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        perror("Failed to set trigger line low");
        return -1.0;
    }

    // Wait for echo start
    ret = gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, TIMEOUT_NS, &event);
    if (ret < 0) {
        if (ret == -ETIMEDOUT) {
            printf("Timeout waiting for echo start\n");
            return -1.0;
        }
        perror("Failed to wait for echo start");
        return -1.0;
    }

    // Wait for echo end
    ret = gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, TIMEOUT_NS, &event);
    if (ret < 0) {
        if (ret == -ETIMEDOUT) {
            printf("Timeout waiting for echo end\n");
            return -1.0;
        }
        perror("Failed to wait for echo end");
        return -1.0;
    }

    // Calculate distance
    long long pulse_duration_ns = event.ts.tv_nsec - event.ts.tv_nsec;
    double distance_cm = pulse_duration_ns * 0.0343 / 2.0 / 1e9;
    return distance_cm;
}

void set_servo_angle(double distance_cm) {
    if (distance_cm < MIN_DISTANCE_SERVO_CM) {
        gpiod_line_set_value(servo_line, 0);
    } else if (distance_cm > MAX_DISTANCE_SERVO_CM) {
        gpiod_line_set_value(servo_line, 1);
    } else {
        double angle = (distance_cm - MIN_DISTANCE_SERVO_CM) / (MAX_DISTANCE_SERVO_CM - MIN_DISTANCE_SERVO_CM) * 180.0;
        double pulse_width_us = MIN_SERVO_PULSE_US + (MAX_SERVO_PULSE_US - MIN_SERVO_PULSE_US) * angle / 180.0;
        gpiod_line_set_value(servo_line, pulse_width_us);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
