        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_GPIO);
    if (!servo_line) {
        perror("Failed to get servo line");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request(servo_line, "servo", GPIOD_LINE_REQUEST_DIRECTIONS_OUT) < 0) {
        perror("Failed to request servo line");
        gpiod_line_release(servo_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
