#include <fcntl.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_HUMID_REG 0xE5
#define I2C_TIMEOUT 1000

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    usleep(10000); // Wait 10 ms

    if (read(fd, data, length) != length) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return 0;
}

void close_i2c_device(int *fd) {
    if (*fd >= 0) {
        close(*fd);
        *fd = -1;
    }
}

int main() {
    int i2c_fd = -1;
    signal(SIGINT, handle_sigint);

    while (keep_running) {
        if (i2c_fd < 0) {
            i2c_fd = open_i2c_device(I2C_BUS, SI7005_ADDR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Retrying to open I2C device...\n");
                sleep(1);
                continue;
            }
        }

        if (i2c_write(i2c_fd, CONFIG_REG, 0x01) < 0) {
            fprintf(stderr, "Error writing CONFIG register, retrying...\n");
            close_i2c_device(&i2c_fd);
            continue;
        }

        usleep(10000); // Wait 10 ms

        uint8_t data[2];
        if (i2c_read(i2c_fd, TEMP_HUMID_REG, data, 2) < 0) {
            fprintf(stderr, "Error reading temperature/humidity, retrying...\n");
            close_i2c_device(&i2c_fd);
            continue;
        }

        int temp_humid = (data[0] << 8) | data[1];
        float temperature = -6.0 + 175.72 * (temp_humid / 65536.0);
        float humidity = 125.0 * (temp_humid / 65536.0) - 6.0;

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        sleep(2);
    }

    close_i2c_device(&i2c_fd);
    return 0;
}

