int check_sensor_presence(int fd) {
    uint8_t who_am_i;
    if (ioctl(fd, I2C_SLAVE, MPU6050_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }

    if (read(fd, &who_am_i, 1) != 1) {
        perror("Failed to read WHO_AM_I register");
        return -1;
    }

    if (who_am_i != 0x68) {
        fprintf(stderr, "MPU6050 not found. WHO_AM_I = 0x%02X\n", who_am_i);
        return -1;
    }

    return 0;
}

void read_sensor_data(int fd) {
    uint8_t buffer[14];
    if (ioctl(fd, I2C_SLAVE, MPU6050_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return;
    }

    if (write(fd, &ACCEL_XOUT_H, 1) != 1) {
        perror("Failed to write register address");
        return;
    }

    if (read(fd, buffer, 14) != 14) {
        perror("Failed to read sensor data");
        return;
    }

    int16_t accel_x = (buffer[0] << 8) | buffer[1];
    int16_t accel_y = (buffer[2] << 8) | buffer[3];
    int16_t accel_z = (buffer[4] << 8) | buffer[5];
    int16_t temp = (buffer[6] << 8) | buffer[7];
    int16_t gyro_x = (buffer[8] << 8) | buffer[9];
    int16_t gyro_y = (buffer[10] << 8) | buffer[11];
    int16_t gyro_z = (buffer[12] << 8) | buffer[13];

    printf("Accel: X=%d Y=%d Z=%d Temp=%d Gyro: X=%d Y=%d Z=%d\n",
           accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z);
}

int main() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
