    if (check_sensor_presence(fd) != 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU6050 sensor detected. Starting data read loop...\n");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        read_sensor_data(fd);
        usleep(READ_INTERVAL_MS * 1000);
    }

    printf("Shutting down...\n");
    close(fd);
    printf("Clean shutdown complete.\n");

    return EXIT_SUCCESS;
}

