#define SHT40_ADDR 0x44
#define SHT40_CMD_HIGH_REPEATABILTY_MEASUREMENT 0x2C06
#define SHT40_RESPONSE_LENGTH 6

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0x31;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sht40(int fd, float *temperature, float *humidity) {
    uint8_t cmd[2] = {SHT40_CMD_HIGH_REPEATABILTY_MEASUREMENT >> 8, SHT40_CMD_HIGH_REPEATABILTY_MEASUREMENT & 0xFF};
    uint8_t response[SHT40_RESPONSE_LENGTH];
    int ret;

    ret = write(fd, cmd, sizeof(cmd));
    if (ret != sizeof(cmd)) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    usleep(10000); // Wait at least 10 ms

    ret = read(fd, response, sizeof(response));
    if (ret != sizeof(response)) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    uint8_t temp_crc = crc8(response, 2);
    uint8_t hum_crc = crc8(response + 3, 2);

    if (response[2] != temp_crc) {
        fprintf(stderr, "Temperature CRC error\n");
        return -1;
    }

    if (response[5] != hum_crc) {
        fprintf(stderr, "Humidity CRC error\n");
        return -1;
    }

    int16_t temp_raw = (response[0] << 8) | response[1];
    int16_t hum_raw = (response[3] << 8) | response[4];

    *temperature = -45.0 + 175.0 * temp_raw / 65535.0;
    *humidity = 100.0 * hum_raw / 65535.0;

    return 0;
}

