    return file;
}

int read_temperature(int file, int reg, float *temperature) {
    char buf[2];
    if (write(file, &reg, 1) != 1) {
        perror("Failed to write to the i2c bus");
        return -1;
    }
    if (read(file, buf, 2) != 2) {
        perror("Failed to read from the i2c bus");
        return -1;
    }
    int raw = (buf[0] << 8) | buf[1];
    *temperature = raw * 0.02 - 273.15; // Convert to Celsius
    return 0;
}

void log_temperature(FILE *file, float ambient, float object) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(file, "%s,%.2f,%.2f\n", time_str, ambient, object);
    fflush(file);
}

