    }

    FILE *log_file = fopen("temperature_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_file);
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "Timestamp,Ambient Temperature,Object Temperature\n");
    fflush(log_file);

