#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <syslog.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define CONTINUOUS_MEASUREMENT_CMD 0x00
#define MEASUREMENT_CMD 0x01
#define DATA_FRAME_SIZE 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int validate_crc8(const uint8_t *data, size_t length) {
    if (length < 3) return 0;
    uint8_t crc = calculate_crc8(data, length - 1);
    return crc == data[length - 1];
}

int read_sensor_data(i2c_context *ctx, uint8_t *data) {
    if (i2c_write(ctx, I2C_ADDRESS, &MEASUREMENT_CMD, 1) < 0) {
        syslog(LOG_ERR, "Failed to write measurement command: %s", strerror(errno));
        return -1;
    }
    usleep(1000); // Wait at least 1 ms
    if (i2c_read(ctx, I2C_ADDRESS, data, DATA_FRAME_SIZE) < 0) {
        syslog(LOG_ERR, "Failed to read sensor data: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    openlog("sdp810_reader", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_context *ctx = i2c_new_context();
    if (!ctx) {
        syslog(LOG_ERR, "Failed to create I2C context");
        exit(EXIT_FAILURE);
    }

    if (i2c_set_bus(ctx, I2C_BUS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C bus: %s", strerror(errno));
        i2c_free_context(ctx);
        exit(EXIT_FAILURE);
    }

    if (i2c_write(ctx, I2C_ADDRESS, &CONTINUOUS_MEASUREMENT_CMD, 1) < 0) {
        syslog(LOG_ERR, "Failed to set continuous measurement: %s", strerror(errno));
        i2c_free_context(ctx);
        exit(EXIT_FAILURE);
    }

    FILE *file = fopen("pressure_log.csv", "a");
    if (!file) {
        syslog(LOG_ERR, "Failed to open file: %s", strerror(errno));
        i2c_free_context(ctx);
        exit(EXIT_FAILURE);
    }

    if (fseek(file, 0, SEEK_SET) == 0) {
        if (ftell(file) == 0) {
            fprintf(file, "Timestamp,Pressure (Pa),Temperature (C)\n");
            fflush(file);
        }
    }

    uint8_t data[DATA_FRAME_SIZE];
    while (!stop) {
        if (read_sensor_data(ctx, data) < 0) {
            syslog(LOG_WARNING, "Error reading sensor data, retrying...");
            continue;
        }

        if (!validate_crc8(data, 3) || !validate_crc8(data + 3, 3) || !validate_crc8(data + 6, 3)) {
            syslog(LOG_WARNING, "CRC validation failed");
            continue;
        }

        int16_t pressure_raw = (data[0] << 8) | data[1];
        int16_t temperature_raw = (data[3] << 8) | data[4];
        int16_t pressure_scale = (data[6] << 8) | data[7];
        int16_t temperature_scale = (data[8] << 8) | data[9];

        double pressure = pressure_raw / (double)pressure_scale;
        double temperature = temperature_raw / (double)temperature_scale;

        time_t now = time(NULL);
        struct tm *tm_info = gmtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

        fprintf(file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
        fflush(file);

        sleep(1);
    }

    fclose(file);
    i2c_free_context(ctx);
    closelog();
    return 0;
}

