void handle_signal(int sig) {
    stop = 1;
}

uint8_t calculate_crc(uint8_t *data, uint8_t length) {
    uint8_t crc = SHT40_CRC_INITIAL_VALUE;
    for (uint8_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

