    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read measurement result");
        return -1;
    }

    // Validate CRC
    if (buffer[2] != calculate_crc(buffer, 2) || buffer[5] != calculate_crc(buffer + 3, 2)) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert to temperature and humidity
    int16_t raw_temperature = (buffer[0] << 8) | buffer[1];
    int16_t raw_humidity = (buffer[3] << 8) | buffer[4];

