#include <errno.h>
#include <string.h>
#include <gpiod.h>
#include <syslog.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define CMD_TRIGGER_CONTINUOUS_MEASUREMENT 0x00
#define CMD_READ_PRESSURE_AND_TEMPERATURE 0x10
#define RETRY_LIMIT 3
#define SAMPLING_INTERVAL 100000 // 100 ms in microseconds

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int sig) {
    stop_flag = 1;
}

int i2c_write_retry(int fd, uint8_t *data, size_t length) {
    int retries = 0;
    int delay = 1; // Start with 1 ms delay
    while (retries < RETRY_LIMIT) {
        if (write(fd, data, length) == length) {
            return 0; // Success
        }
        retries++;
        usleep(delay * 1000); // Exponential backoff
        delay *= 2;
    }
    return -1; // Failure after retries
}

int i2c_read_retry(int fd, uint8_t *buffer, size_t length) {
    int retries = 0;
    int delay = 1; // Start with 1 ms delay
    while (retries < RETRY_LIMIT) {
        if (read(fd, buffer, length) == length) {
            return 0; // Success
        }
        retries++;
        usleep(delay * 1000); // Exponential backoff
        delay *= 2;
    }
    return -1; // Failure after retries
}

int main() {
    struct timespec ts;
    int i2c_fd;
    uint8_t write_buffer[1];
    uint8_t read_buffer[6];
    FILE *log_file;
    struct sigaction sa;

    // Setup signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" + std::to_string(I2C_BUS), O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("airflow.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop_flag) {
        // Trigger continuous measurement
        write_buffer[0] = CMD_TRIGGER_CONTINUOUS_MEASUREMENT;
        if (i2c_write_retry(i2c_fd, write_buffer, 1) < 0) {
            syslog(LOG_ERR, "I2C write failed");
            continue;
        }

        // Wait at least 1 ms
        usleep(1000);

        // Read pressure and temperature
        write_buffer[0] = CMD_READ_PRESSURE_AND_TEMPERATURE;
        if (i2c_write_retry(i2c_fd, write_buffer, 1) < 0) {
            syslog(LOG_ERR, "I2C write failed");
            continue;
        }

        if (i2c_read_retry(i2c_fd, read_buffer, 6) < 0) {
            syslog(LOG_ERR, "I2C read failed");
            continue;
        }

        // Convert pressure and temperature
        int32_t pressure_raw = (read_buffer[0] << 8) | read_buffer[1];
        int16_t temperature_raw = (read_buffer[4] << 8) | read_buffer[5];

        double pressure_pa = pressure_raw / 1000.0;
        double temperature_c = temperature_raw / 16.0;

        // Get timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

        // Write to log file
        fprintf(log_file, "%s,%.3f,%.2f\n", timestamp, pressure_pa, temperature_c);
        fflush(log_file);

        // Wait for the next sample
        usleep(SAMPLING_INTERVAL - 1000); // Adjust for the 1 ms wait
    }

    // Cleanup
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

