        perror("I2C write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    struct i2c_msg msgs[2];
    uint8_t buf[256];

    buf[0] = reg;
    msgs[0].addr = SI7015_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = buf;

    msgs[1].addr = SI7015_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = length;
    msgs[1].buf = data;

    if (ioctl(fd, I2C_RDWR, &msgs) < 0) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

int read_sensor(int fd, uint8_t command, float *value) {
    uint8_t data[2];
    uint8_t status;
    int retries = 5;

    if (i2c_write(fd, command, NULL, 0) < 0) {
        return -1;
    }

    while (retries--) {
        if (i2c_read(fd, SI7015_STATUS_REG, &status, 1) < 0) {
            return -1;
        }

        if (!(status & SI7015_STATUS_BUSY)) {
            break;
        }

        usleep(10000); // 10 ms
    }

    if (retries < 0) {
        fprintf(stderr, "Sensor busy timeout\n");
        return -1;
    }

    if (i2c_read(fd, 0x00, data, 2) < 0) {
        return -1;
    }

    int16_t raw = (data[0] << 8) | data[1];
    *value = (float)raw / 65536.0 * 125.0 - 6.0;
    return 0;
}

int main() {
    int i2c_fd;
    FILE *log_file;
    struct timespec ts;
    float temperature, humidity;

    signal(SIGINT, handle_sigint);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI7015_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("sensor_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        clock_gettime(CLOCK_REALTIME, &ts);

        if (read_sensor(i2c_fd, SI7015_MEASURE_TEMP_HOLD, &temperature) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
        } else {
            printf("%ld.%09ld - Temperature: %.2f°C\n", ts.tv_sec, ts.tv_nsec, temperature);
            fprintf(log_file, "%ld.%09ld - Temperature: %.2f°C\n", ts.tv_sec, ts.tv_nsec, temperature);
        }

        if (read_sensor(i2c_fd, SI7015_MEASURE_HUMID_HOLD, &humidity) < 0) {
            fprintf(stderr, "Failed to read humidity\n");
        } else {
            printf("%ld.%09ld - Humidity: %.2f%%\n", ts.tv_sec, ts.tv_nsec, humidity);
            fprintf(log_file, "%ld.%09ld - Humidity: %.2f%%\n", ts.tv_sec, ts.tv_nsec, humidity);
        }

        fflush(log_file);
        sleep(5);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}
