#include <syslog.h>
#include <errno.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x40
#define MEASURE_CMD 0x2C
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL 5 // seconds

static int i2c_fd = -1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;
static volatile sig_atomic_t keep_running = 1;

void log_error(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    fprintf(error_log_file, "[%s] ERROR: %s\n", timestamp, message);
    fflush(error_log_file);
}

void log_temperature(double temperature) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    fprintf(log_file, "[%s] Temperature: %.2f°C\n", timestamp, temperature);
    fflush(log_file);
}

void handle_sigint(int sig) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_temperature() {
    uint8_t write_buf[1] = {MEASURE_CMD};
    uint8_t read_buf[3];
    int ret;

    ret = write(i2c_fd, write_buf, sizeof(write_buf));
    if (ret != sizeof(write_buf)) {
        log_error("Failed to write measurement command");
        return -1;
    }

    usleep(15000); // Wait for conversion

    ret = read(i2c_fd, read_buf, sizeof(read_buf));
    if (ret != sizeof(read_buf)) {
        log_error("Failed to read temperature data");
        return -1;
    }

    uint8_t crc = calculate_crc8(read_buf, 2);
    if (crc != read_buf[2]) {
        log_error("CRC mismatch");
        return -1;
    }

    int16_t raw_temp = (read_buf[0] << 8) | read_buf[1];
    double temperature = raw_temp / 16.0;
    return temperature;
}

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        perror("Failed to open error log file");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-" PRIuMAX, O_RDWR);
    if (i2c_fd == -1) {
        log_error("Failed to open I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) == -1) {
        log_error("Failed to set I2C address");
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        double temperature = read_temperature();
        if (temperature != -1) {
            log_temperature(temperature);
        }
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

