#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SHT40_ADDRESS 0x44
#define SHT40_MEASUREMENT_COMMAND 0x2C06
#define SHT40_LOG_FILE "sht40_log.txt"
#define SLEEP_INTERVAL 5

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    const uint8_t polynomial = 0x31;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sht40(int fd, float *temperature, float *humidity) {
    uint8_t command[2] = {SHT40_MEASUREMENT_COMMAND >> 8, SHT40_MEASUREMENT_COMMAND & 0xFF};
    uint8_t response[6];
    int ret;

    ret = write(fd, command, 2);
    if (ret != 2) {
        perror("I2C write error");
        return -1;
    }

    usleep(8500); // Wait at least 8.5 ms

    ret = read(fd, response, 6);
    if (ret != 6) {
        perror("I2C read error");
        return -1;
    }

    uint8_t temp_crc = crc8(response, 2);
    uint8_t rh_crc = crc8(response + 3, 2);

    if (response[2] != temp_crc || response[5] != rh_crc) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    int16_t temp = (response[0] << 8) | response[1];
    int16_t rh = (response[3] << 8) | response[4];

    *temperature = -45 + 175 * (temp / 65535.0);
    *humidity = 100 * (rh / 65535.0);

    return 0;
}

void log_reading(float temperature, float humidity) {
    FILE *log_file = fopen(SHT40_LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s - Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_sigint);

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SHT40_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return EXIT_FAILURE;
    }

    float temperature, humidity;

    while (keep_running) {
        if (read_sht40(fd, &temperature, &humidity) == 0) {
            log_reading(temperature, humidity);
        }
        sleep(SLEEP_INTERVAL);
    }

    close(fd);
    return EXIT_SUCCESS;
}

