#include <time.h>
#include <gpiod.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define TEMP_REG 0xE3
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define RETRY_LIMIT 3
#define FAN_ON 1
#define FAN_OFF 0

typedef struct {
    time_t timestamp;
    float temperature;
} SensorData;

volatile sig_atomic_t keep_running = 1;
gpiod_chip *chip;
gpiod_line *fan_line;
int i2c_fd;
SensorData buffer[BUFFER_SIZE];
int buffer_index = 0;

void handle_sigint(int sig) {
    keep_running = 0;
    gpiod_line_set_value(fan_line, FAN_OFF);
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

float read_temperature() {
    uint8_t buf[3] = {TEMP_REG, 0x00};
    uint8_t temp_data[2] = {0};
    int retries = 0;
    int ret;

    while (retries < RETRY_LIMIT) {
        ret = ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR);
        if (ret < 0) {
            perror("Failed to set I2C address");
            retries++;
            usleep(100000); // 100 ms
            continue;
        }

        ret = write(i2c_fd, buf, 2);
        if (ret != 2) {
            perror("Failed to write to I2C bus");
            retries++;
            usleep(100000); // 100 ms
            continue;
        }

        ret = read(i2c_fd, temp_data, 2);
        if (ret == 2) {
            int temp = (temp_data[0] << 8) | temp_data[1];
            return ((175.72 * temp) / 65536.0) - 46.85;
        } else {
            perror("Failed to read from I2C bus");
            retries++;
            usleep(100000); // 100 ms
        }
    }

    fprintf(stderr, "Sensor absent or I2C communication failed\n");
    return -1.0;
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    fan_line = gpiod_chip_get_line(chip, FAN_GPIO);
    if (!fan_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    setup_gpio();
    setup_i2c();

    float last_temperature = -1.0;
    int fan_state = FAN_OFF;

    while (keep_running) {
        float temperature = read_temperature();
        if (temperature >= 0.0) {
            time_t now = time(NULL);
            buffer[buffer_index].timestamp = now;
            buffer[buffer_index].temperature = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            printf("%s: Temperature = %.2f°C\n", ctime(&now), temperature);

            if (temperature > TEMP_THRESHOLD_HIGH && fan_state == FAN_OFF) {
                gpiod_line_set_value(fan_line, FAN_ON);
                fan_state = FAN_ON;
            } else if (temperature < TEMP_THRESHOLD_LOW && fan_state == FAN_ON) {
                gpiod_line_set_value(fan_line, FAN_OFF);
                fan_state = FAN_OFF;
            }

            last_temperature = temperature;
        } else {
            if (last_temperature >= 0.0) {
                gpiod_line_set_value(fan_line, FAN_OFF);
                fan_state = FAN_OFF;
            }
        }

        usleep(10000); // 10 ms
        sleep(2);
    }

    cleanup();
    return 0;
}

