#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <syslog.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SCD40_ADDR 0x61
#define SCD40_CMD_START_PERIODIC_MEASUREMENT 0x0015
#define SCD40_CMD_STOP_PERIODIC_MEASUREMENT 0x0016
#define SCD40_CMD_READ_MEASUREMENT 0x0000
#define SCD40_DATA_READY_FLAG 0x0020
#define SCD40_DATA_LENGTH 9

volatile sig_atomic_t stop_requested = 0;

void handle_signal(int sig) {
    stop_requested = 1;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int verify_crc(const uint8_t *data, size_t length) {
    if (length < 2) return -1;
    uint8_t crc = calculate_crc8(data, length - 2, 0xFF);
    return (crc == data[length - 2]) ? 0 : -1;
}

void log_air_quality(int fd, int co2_ppm, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    dprintf(fd, "%s,%d,%.2f,%.2f\n", timestamp, co2_ppm, temperature, humidity);
    fsync(fd);
}

int main() {
    int i2c_fd, log_fd;
    uint8_t buffer[SCD40_DATA_LENGTH];
    uint8_t cmd[2];
    struct timespec ts = {1, 0};

    signal(SIGINT, handle_signal);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    cmd[0] = SCD40_CMD_START_PERIODIC_MEASUREMENT >> 8;
    cmd[1] = SCD40_CMD_START_PERIODIC_MEASUREMENT & 0xFF;
    if (write(i2c_fd, cmd, 2) != 2) {
        perror("Failed to start periodic measurement");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    nanosleep(&ts, NULL);

    log_fd = open("air_quality.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (!stop_requested) {
        cmd[0] = SCD40_CMD_READ_MEASUREMENT >> 8;
        cmd[1] = SCD40_CMD_READ_MEASUREMENT & 0xFF;
        if (write(i2c_fd, cmd, 2) != 2) {
            perror("Failed to read measurement");
            continue;
        }

        if (read(i2c_fd, buffer, SCD40_DATA_LENGTH) != SCD40_DATA_LENGTH) {
            perror("Failed to read data");
            continue;
        }

        if (verify_crc(buffer, SCD40_DATA_LENGTH) != 0) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        if ((buffer[0] & SCD40_DATA_READY_FLAG) == 0) {
            continue;
        }

        int co2_ppm = (buffer[2] << 8) | buffer[3];
        float temperature = ((buffer[4] << 8) | buffer[5]) / 100.0;
        float humidity = ((buffer[6] << 8) | buffer[7]) / 100.0;

        log_air_quality(log_fd, co2_ppm, temperature, humidity);

        nanosleep(&ts, NULL);
    }

    cmd[0] = SCD40_CMD_STOP_PERIODIC_MEASUREMENT >> 8;
    cmd[1] = SCD40_CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;
    if (write(i2c_fd, cmd, 2) != 2) {
        perror("Failed to stop periodic measurement");
    }

    close(i2c_fd);
    close(log_fd);

    return EXIT_SUCCESS;
}

