#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SCD40_I2C_ADDR 0x61
#define CO2_WARNING_THRESHOLD 1000
#define GPIO_LED 17
#define BUFFER_SIZE 20

typedef struct {
    float co2;
    float temperature;
    float humidity;
} SensorData;

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(int i2c_fd, SensorData *data) {
    uint8_t cmd[2] = {0x20, 0x08}; // Command to read CO2, temperature, and humidity
    if (write(i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to write I2C command");
        return -1;
    }

    uint8_t response[14];
    if (read(i2c_fd, response, sizeof(response)) != sizeof(response)) {
        perror("Failed to read I2C response");
        return -1;
    }

    if (crc8(response, 12) != response[12]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    data->co2 = (response[0] << 8 | response[1]) / 1.0;
    data->temperature = (response[3] << 8 | response[4]) / 16.0 - 273.15;
    data->humidity = (response[6] << 8 | response[7]) / 1.0;

    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "co2_warning_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    SensorData buffer[BUFFER_SIZE];
    int buffer_index = 0;

    while (keep_running) {
        SensorData data;
        if (read_sensor_data(i2c_fd, &data) == 0) {
            buffer[buffer_index] = data;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            printf("CO2: %.2f ppm, Temperature: %.2f °C, Humidity: %.2f %%\n",
                   data.co2, data.temperature, data.humidity);

            if (data.co2 > CO2_WARNING_THRESHOLD) {
                gpiod_line_set_value(line, 1);
            } else {
                gpiod_line_set_value(line, 0);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

