#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 4
#define TIMEOUT_US 50000
#define SAMPLE_INTERVAL 5000000
#define MAX_FAILURES 3
#define TEMP_MIN -40.0
#define TEMP_MAX 150.0

volatile sig_atomic_t keep_running = 1;
FILE *log_file = NULL;
int consecutive_failures = 0;

void handle_signal(int signal) {
    keep_running = 0;
}

double compute_temperature(int high_time, int total_time) {
    if (total_time == 0 || high_time == 0) {
        return 0.0; // Guard against division by zero
    }
    double duty_cycle = (double)high_time / total_time;
    double temperature = (duty_cycle * 100.0 - 50.0) * 0.1;
    return temperature;
}

void log_temperature(double temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
        fprintf(log_file, "%s ERROR: Temperature out of range: %.2f°C\n", timestamp, temperature);
        consecutive_failures++;
        if (consecutive_failures >= MAX_FAILURES) {
            fprintf(log_file, "SENSOR MALFUNCTION\n");
            consecutive_failures = 0;
        }
    } else {
        fprintf(log_file, "%s Temperature: %.2f°C\n", timestamp, temperature);
        consecutive_failures = 0;
    }
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("temperature_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int high_time = 0, total_time = 0;
        int edge = 0;

        // Wait for rising edge
        edge = gpioWait(GPIO_PIN, GPIO_EDGE_RISING, TIMEOUT_US);
        if (edge < 0) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            continue;
        }

        // Measure high pulse width
        high_time = gpioTickDiff(gpioTick(), gpioWait(GPIO_PIN, GPIO_EDGE_FALLING, TIMEOUT_US));
        if (high_time < 0) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            continue;
        }

        // Measure total cycle width
        total_time = gpioTickDiff(gpioTick(), gpioWait(GPIO_PIN, GPIO_EDGE_RISING, TIMEOUT_US));
        if (total_time < 0) {
            fprintf(stderr, "Timeout waiting for next rising edge\n");
            continue;
        }

        double temperature = compute_temperature(high_time, total_time);
        log_temperature(temperature);

        // Sleep for the remainder of the sample interval
        int sleep_time = SAMPLE_INTERVAL - (high_time + total_time);
        if (sleep_time > 0) {
            usleep(sleep_time);
        }
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

