#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <gpiod.h>
#include <syslog.h>
#include <errno.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_CMD 0x2C06
#define RETRIES 3
#define DELAY_BETWEEN_READS 5
#define DELAY_BEFORE_RETRY 1
#define LOG_FILE "environmental_data.txt"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int fd, uint8_t *buffer) {
    for (int attempt = 0; attempt < RETRIES; attempt++) {
        if (write(fd, &MEASUREMENT_CMD, 2) != 2) {
            syslog(LOG_ERR, "Failed to write to I2C: %s", strerror(errno));
            sleep(DELAY_BEFORE_RETRY);
            continue;
        }

        usleep(15000); // Wait for at least 15 ms

        if (read(fd, buffer, 6) != 6) {
            syslog(LOG_ERR, "Failed to read from I2C: %s", strerror(errno));
            sleep(DELAY_BEFORE_RETRY);
            continue;
        }

        uint8_t temp_crc = buffer[3];
        uint8_t hum_crc = buffer[5];

        if (crc8(buffer, 2) != temp_crc || crc8(buffer + 2, 2) != hum_crc) {
            syslog(LOG_ERR, "CRC check failed");
            sleep(DELAY_BEFORE_RETRY);
            continue;
        }

        return 0;
    }
    return -1;
}

void log_data(double temperature, double humidity) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(file, "%s, %.2f, %.2f\n", timestamp, temperature, humidity);
    fclose(file);
}

int main() {
    openlog("SHT35Reader", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int fd = open("/dev/i2c-" PRIuMAX, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SHT35_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(fd);
        closelog();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file for writing: %s", strerror(errno));
        close(fd);
        closelog();
        return EXIT_FAILURE;
    }
    fclose(log_file);

    while (keep_running) {
        uint8_t buffer[6];
        if (read_sensor(fd, buffer) == 0) {
            int16_t raw_temp = (buffer[0] << 8) | buffer[1];
            int16_t raw_hum = (buffer[2] << 8) | buffer[3];

            double temperature = -45 + 175 * (raw_temp / 65535.0);
            double humidity = 100 * (raw_hum / 65535.0);

            time_t now = time(NULL);
            double seconds = difftime(now, 0);
            double offset_temp = 2 * sin(2 * M_PI * seconds / 3600);
            double offset_hum = 5 * sin(2 * M_PI * seconds / 3600);

            temperature += offset_temp;
            humidity += offset_hum;

            log_data(temperature, humidity);
        } else {
            log_data(NAN, NAN);
        }

        sleep(DELAY_BETWEEN_READS);
    }

    close(fd);
    closelog();
    return EXIT_SUCCESS;
}

