        return -1;
    }

    uint8_t crc_temperature = calculate_crc8(data, 2);
    uint8_t crc_humidity = calculate_crc8(data + 3, 2);

    if (crc_temperature != data[2] || crc_humidity != data[5]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * raw_temperature / 65535.0;
