#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define SI7021_MEASURE_TEMP_HOLD 0xE3
#define SI7021_MEASURE_HUM_HOLD 0xE5
#define SI7021_RESET 0xFE
#define POLL_INTERVAL 100000 // 100 ms in microseconds
#define LOG_INTERVAL 5000000 // 5 seconds in microseconds
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_i2c_data(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    struct timespec timeout = {0, POLL_INTERVAL};
    struct timespec remaining = {0, POLL_INTERVAL};
    ssize_t bytes_read = 0;

    while (bytes_read < length) {
        ssize_t result = read(fd, data + bytes_read, length - bytes_read);
        if (result < 0) {
            if (errno == EAGAIN || errno == EINTR) {
                if (nanosleep(&timeout, &remaining) != 0) {
                    perror("Nanosleep failed");
                    return -1;
                }
                continue;
            } else {
                perror("Failed to read data");
                return -1;
            }
        }
        bytes_read += result;
    }
    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("environment.log", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,temperature_C,humidity_percent\n");

    uint8_t data[3];
    uint8_t temp_cmd = SI7021_MEASURE_TEMP_HOLD;
    uint8_t hum_cmd = SI7021_MEASURE_HUM_HOLD;

    struct timespec last_log_time;
    clock_gettime(CLOCK_REALTIME, &last_log_time);

    while (keep_running) {
        // Measure temperature
        if (write(i2c_fd, &temp_cmd, 1) != 1) {
            perror("Failed to write temperature command");
            fprintf(stderr, "ERROR: Failed to write temperature command\n");
            write(i2c_fd, &SI7021_RESET, 1);
            continue;
        }

        if (read_i2c_data(i2c_fd, 0, data, 3) != 0) {
            fprintf(stderr, "ERROR: Failed to read temperature data\n");
            write(i2c_fd, &SI7021_RESET, 1);
            continue;
        }

        uint8_t temp_crc = calculate_crc8(data, 2);
        if (temp_crc != data[2]) {
            fprintf(stderr, "ERROR: Temperature CRC check failed\n");
            write(i2c_fd, &SI7021_RESET, 1);
            continue;
        }

        int16_t temp = (data[0] << 8) | data[1];
        float temperature = ((175.72 * temp) / 65536.0) - 46.85;

        // Measure humidity
        if (write(i2c_fd, &hum_cmd, 1) != 1) {
            perror("Failed to write humidity command");
            fprintf(stderr, "ERROR: Failed to write humidity command\n");
            write(i2c_fd, &SI7021_RESET, 1);
            continue;
        }

        if (read_i2c_data(i2c_fd, 0, data, 3) != 0) {
            fprintf(stderr, "ERROR: Failed to read humidity data\n");
            write(i2c_fd, &SI7021_RESET, 1);
            continue;
        }

        uint8_t hum_crc = calculate_crc8(data, 2);
        if (hum_crc != data[2]) {
            fprintf(stderr, "ERROR: Humidity CRC check failed\n");
            write(i2c_fd, &SI7021_RESET, 1);
            continue;
        }

        int16_t hum = (data[0] << 8) | data[1];
