int read_i2c_data(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    struct timespec timeout = {0, POLL_INTERVAL};
    struct timespec remaining = {0, POLL_INTERVAL};
    ssize_t bytes_read = 0;

    while (bytes_read < length) {
        ssize_t result = read(fd, data + bytes_read, length - bytes_read);
        if (result < 0) {
            if (errno == EAGAIN || errno == EINTR) {
                if (nanosleep(&timeout, &remaining) != 0) {
                    perror("Nanosleep failed");
                    return -1;
                }
                continue;
            } else {
                perror("Failed to read data");
                return -1;
            }
        }
        bytes_read += result;
    }
    return 0;
}

