#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define CMD_CONTINUOUS_MEASUREMENT 0x00
#define CMD_READ_DATA 0x0A
#define DATA_LENGTH 9
#define CRC_POLYNOMIAL 0x31
#define SIGINT_RECEIVED 0
#define SIGTERM_RECEIVED 1

volatile sig_atomic_t shutdown_flag = 0;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        shutdown_flag = signum == SIGINT ? SIGINT_RECEIVED : SIGTERM_RECEIVED;
    }
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int validate_crc8(const uint8_t *data, size_t length) {
    if (length < 3) return -1;
    uint8_t crc = calculate_crc8(data, length - 1);
    return crc == data[length - 1];
}

float convert_pressure(uint16_t raw_pressure) {
    return (raw_pressure * 500.0) / 0x10000;
}

float convert_temperature(uint16_t raw_temperature) {
    return (raw_temperature * 200.0) / 0x10000 - 50.0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open("/dev/i2c-" + std::to_string(I2C_BUS), O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t cmd = CMD_CONTINUOUS_MEASUREMENT;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Failed to write command");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *file = fopen("airflow.dat", "wb");
    if (!file) {
        perror("Failed to open file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (!shutdown_flag) {
        usleep(1000000); // Wait for 1 second

        uint8_t data[DATA_LENGTH];
        if (read(i2c_fd, data, DATA_LENGTH) != DATA_LENGTH) {
            perror("Failed to read data");
            break;
        }

        if (!validate_crc8(data, 3) || !validate_crc8(data + 4, 3)) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        uint16_t raw_pressure = (data[0] << 8) | data[1];
        uint16_t raw_temperature = (data[3] << 8) | data[4];

        float pressure = convert_pressure(raw_pressure);
        float temperature = convert_temperature(raw_temperature);

        if (fwrite(&pressure, sizeof(float), 1, file) != 1 ||
            fwrite(&temperature, sizeof(float), 1, file) != 1) {
            perror("Failed to write to file");
            break;
        }
    }

    if (shutdown_flag == SIGINT_RECEIVED) {
        printf("SIGINT received, shutting down...\n");
    } else if (shutdown_flag == SIGTERM_RECEIVED) {
        printf("SIGTERM received, shutting down...\n");
    }

    if (file) fclose(file);
    if (i2c_fd >= 0) close(i2c_fd);

    return EXIT_SUCCESS;
}

