#include <syslog.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define CMD_CONTINUOUS_MEASUREMENT 0x00
#define RESPONSE_LENGTH 9
#define CRC_POLYNOMIAL 0x31
#define LOG_INTERVAL 5

static int i2c_fd = -1;
static FILE *log_file = NULL;

void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_pressure() {
    uint8_t write_buf[1] = {CMD_CONTINUOUS_MEASUREMENT};
    uint8_t read_buf[RESPONSE_LENGTH];
    int ret;

    ret = write(i2c_fd, write_buf, sizeof(write_buf));
    if (ret != sizeof(write_buf)) {
        syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
        return -1;
    }

    usleep(45000); // Wait for conversion time

    ret = read(i2c_fd, read_buf, RESPONSE_LENGTH);
    if (ret != RESPONSE_LENGTH) {
        syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
        return -1;
    }

    for (int i = 0; i < 3; i++) {
        uint8_t crc = calculate_crc8(&read_buf[i * 3], 3);
        if (crc != read_buf[i * 3 + 3]) {
            syslog(LOG_ERR, "CRC check failed for data word %d", i + 1);
            return -1;
        }
    }

    int32_t pressure = (read_buf[0] << 16) | (read_buf[1] << 8) | read_buf[2];
    pressure = (pressure >> 2) & 0x3FFFFF; // Extract 23-bit pressure value

    if (pressure & 0x200000) { // Check if negative
        pressure |= 0xFFC00000;
    }

    return pressure;
}

int main() {
    openlog("pressure_reader", LOG_PID | LOG_CONS, LOG_USER);
    setup_signal_handlers();

    i2c_fd = open("/dev/i2c-" PRIu32, O_RDWR);
    if (i2c_fd == -1) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        int pressure = read_pressure();
        if (pressure != -1) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_file, "%s: %d Pa\n", time_str, pressure);
            fflush(log_file);
        }
        sleep(LOG_INTERVAL);
    }

    fclose(log_file);
    close(i2c_fd);
    closelog();
    return 0;
}

