}

void log_error(const char *message) {
    fprintf(stderr, "%s: %s\n", message, strerror(errno));
}

void cleanup(gpiod_chip *chip, gpiod_line *line, int i2c_fd, FILE *log_file) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    gpiod_chip_close(gpiod_chip_open_by_gpio(PWM_PIN));
    syslog(LOG_INFO, "Cleaned up resources and terminated.");
}

