#include <errno.h>
#include <gpiod.h>
#include <syslog.h>
#include <libi2c.h>

#define I2C_BUS "/dev/i2c-1"
#define LPS33HW_I2C_ADDR 0x5C
#define LOG_FILE "environmental_data.txt"

volatile sig_atomic_t terminate = 0;

void handle_sigint(int sig) {
    terminate = 1;
}

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm tm;
    localtime_r(&now, &tm);

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "[%s] ERROR: %s\n", timestamp, message);
        fflush(log);
        fclose(log);
    }
}

int main() {
    struct i2c_client *client;
    struct i2c_adapter *adapter;
    struct i2c_msg msgs[2];
    uint8_t buf[6];
    FILE *log;
    int ret;

    signal(SIGINT, handle_sigint);

    adapter = i2c_get_adapter(1);
    if (!adapter) {
        log_error("Failed to get I2C adapter");
        return EXIT_FAILURE;
    }

    client = i2c_new_client(adapter, LPS33HW_I2C_ADDR);
    if (!client) {
        log_error("Failed to create I2C client");
        i2c_free_adapter(adapter);
        return EXIT_FAILURE;
    }

    log = fopen(LOG_FILE, "a");
    if (!log) {
        log_error("Failed to open log file");
        i2c_unregister_device(client);
        i2c_free_adapter(adapter);
        return EXIT_FAILURE;
    }

    while (!terminate) {
        memset(msgs, 0, sizeof(msgs));
        memset(buf, 0, sizeof(buf));

        // Read pressure and temperature
        msgs[0].addr = LPS33HW_I2C_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = 1;
        msgs[0].buf = buf;
        buf[0] = 0x28; // Register address for pressure and temperature

        msgs[1].addr = LPS33HW_I2C_ADDR;
        msgs[1].flags = I2C_M_RD;
        msgs[1].len = 6;
        msgs[1].buf = buf;

        ret = i2c_transfer(adapter, msgs, 2);
        if (ret != 2) {
            log_error("I2C transfer failed");
            continue;
        }

        // Extract pressure and temperature
        int32_t pressure_raw = (buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4);
        int32_t temperature_raw = (buf[3] << 8) | buf[4];

        float pressure = pressure_raw * 0.001;
        float temperature = temperature_raw * 0.01;

        // Log data
        time_t now = time(NULL);
        struct tm tm;
        localtime_r(&now, &tm);

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

        fprintf(log, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
        fflush(log);

        sleep(1);
    }

    fclose(log);
    i2c_unregister_device(client);
    i2c_free_adapter(adapter);

    return EXIT_SUCCESS;
}

