#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x48
#define LED_PIN 17
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 280000 // 28.0°C in millidegrees

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    int i2c_fd, led_chip, led_line;
    float temperature_buffer[BUFFER_SIZE] = {0};
    int buffer_index = 0;
    float sum = 0.0;
    float average_temperature = 0.0;
    uint8_t data[2];
    int ret;

    // Setup signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO for LED
    led_chip = gpiod_chip_open("/dev/gpiochip0");
    if (led_chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(led_chip, LED_PIN);
    if (led_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(led_chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "led_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(led_chip);
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(led_chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(led_chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Read temperature from STLM75
        data[0] = 0x00; // Temperature register
        if (write(i2c_fd, data, 1) != 1) {
            fprintf(stderr, "Failed to write to I2C bus: %s\n", strerror(errno));
            continue;
        }

        if (read(i2c_fd, data, 2) != 2) {
            fprintf(stderr, "Failed to read from I2C bus: %s\n", strerror(errno));
            continue;
        }

        int16_t raw_temperature = (data[0] << 8) | data[1];
        float temperature = raw_temperature / 16.0;

        // Update circular buffer
        sum -= temperature_buffer[buffer_index];
        temperature_buffer[buffer_index] = temperature;
        sum += temperature;

        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        average_temperature = sum / BUFFER_SIZE;

        // Control LED based on average temperature
        if (average_temperature > TEMP_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(led_chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

