#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SCD30_I2C_ADDRESS 0x61
#define SCD30_CMD_MEASUREMENT_INTERVAL 0x05
#define SCD30_CMD_START_MEASUREMENT 0x03
#define SCD30_CMD_STOP_MEASUREMENT 0x04
#define SCD30_CMD_READ_MEASUREMENT 0x08
#define SCD30_CMD_READ_MEASUREMENT_READY 0x02
#define SCD30_CMD_READ_MEASUREMENT_CO2 0x09
#define SCD30_CMD_READ_MEASUREMENT_TEMP 0x0A
#define SCD30_CMD_READ_MEASUREMENT_HUM 0x0B

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int open_i2c_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, SCD30_I2C_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

int write_i2c_device(int fd, uint8_t *data, size_t length) {
    if (write(fd, data, length) != length) {
        syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int read_i2c_device(int fd, uint8_t *data, size_t length) {
    if (read(fd, data, length) != length) {
        syslog(LOG_ERR, "Failed to read from I2C device: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int start_measurement(int fd) {
    uint8_t cmd = SCD30_CMD_START_MEASUREMENT;
    return write_i2c_device(fd, &cmd, 1);
}

int stop_measurement(int fd) {
    uint8_t cmd = SCD30_CMD_STOP_MEASUREMENT;
    return write_i2c_device(fd, &cmd, 1);
}

int read_measurement_ready(int fd) {
    uint8_t cmd = SCD30_CMD_READ_MEASUREMENT_READY;
    uint8_t response[2] = {0};
    if (write_i2c_device(fd, &cmd, 1) < 0 || read_i2c_device(fd, response, 2) < 0) {
        return -1;
    }
    return response[0] & 0x01;
}

int read_measurement(int fd, uint8_t *data, size_t length) {
    uint8_t cmd = SCD30_CMD_READ_MEASUREMENT;
    if (write_i2c_device(fd, &cmd, 1) < 0 || read_i2c_device(fd, data, length) < 0) {
        return -1;
    }
    return 0;
}

int read_measurement_value(int fd, uint8_t cmd, int *value) {
    uint8_t data[4] = {0};
    if (write_i2c_device(fd, &cmd, 1) < 0 || read_i2c_device(fd, data, 4) < 0) {
        return -1;
    }
    *value = (data[0] << 16) | (data[1] << 8) | data[2];
    return 0;
}

void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
}

void log_air_quality(const char *filename, int co2, float temp, float humidity) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        log_error("Failed to open log file");
        return;
    }

