#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDR 0x28
#define DEFAULT_INTERVAL 1000
#define EXIT_SUCCESS 0
#define EXIT_FAILURE 1

volatile sig_atomic_t terminate = 0;

void handle_signal(int sig) {
    terminate = 1;
}

uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int verify_crc8(uint8_t msb, uint8_t lsb, uint8_t crc) {
    return crc == crc8(&msb, 2);
}

int read_sensor(int fd, uint8_t *buffer) {
    if (write(fd, buffer, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(fd, buffer, 9) != 9) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int interval = DEFAULT_INTERVAL;
    if (argc > 1) {
        interval = atoi(argv[1]);
        if (interval <= 0) {
            fprintf(stderr, "Invalid interval: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t buffer[9];
    buffer[0] = 0x00; // Command to read data

    while (!terminate) {
        if (read_sensor(fd, buffer) < 0) {
            fprintf(stderr, "I2C read error, sensor might be absent or bus error occurred\n");
            close(fd);
            return EXIT_FAILURE;
        }

        if (!verify_crc8(buffer[0], buffer[1], buffer[2]) ||
            !verify_crc8(buffer[3], buffer[4], buffer[5]) ||
            !verify_crc8(buffer[6], buffer[7], buffer[8])) {
            fprintf(stderr, "CRC check failed\n");
            close(fd);
            return EXIT_FAILURE;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        printf("%s - Pressure: %d, Temperature: %d, Scale-factor: %d\n",
               time_str,
               (int16_t)((buffer[0] << 8) | buffer[1]),
               (int16_t)((buffer[3] << 8) | buffer[4]),
               (int16_t)((buffer[6] << 8) | buffer[7]));

        usleep(interval * 1000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

