#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x28
#define READ_LENGTH 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(int fd, uint8_t *buffer) {
    if (write(fd, &SENSOR_ADDR, 1) != 1) {
        perror("Failed to write to I2C bus");
        return -1;
    }

    if (read(fd, buffer, READ_LENGTH) != READ_LENGTH) {
        perror("Failed to read from I2C bus");
        return -1;
    }

    return 0;
}

