#define I2C_BUS "/dev/i2c-1"
#define HDC1000_ADDR 0x40
#define HDC1000_TEMP_REG 0x00
#define HDC1000_HUMIDITY_REG 0x01
#define HDC1000_CONFIG_REG 0x02
#define HDC1000_CONFIG 0x00 // Continuous conversion mode

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

int write_i2c_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int read_i2c_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open_i2c_device(I2C_BUS, HDC1000_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "HDC1000 sensor not found\n");
        return EXIT_FAILURE;
    }

    if (write_i2c_register(i2c_fd, HDC1000_CONFIG_REG, HDC1000_CONFIG) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        usleep(20000); // Wait for conversion

        uint8_t temp_raw[2] = {0};
        uint8_t humidity_raw[2] = {0};

        if (read_i2c_register(i2c_fd, HDC1000_TEMP_REG, temp_raw[0]) < 0 ||
            read_i2c_register(i2c_fd, HDC1000_TEMP_REG + 1, temp_raw[1]) < 0 ||
            read_i2c_register(i2c_fd, HDC1000_HUMIDITY_REG, humidity_raw[0]) < 0 ||
            read_i2c_register(i2c_fd, HDC1000_HUMIDITY_REG + 1, humidity_raw[1]) < 0) {
            fprintf(stderr, "Error reading sensor data\n");
        } else {
