#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define SI7051_TEMP_MEASURE_NO_HOLD 0xF3

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int read_temperature(gpiod_i2c_chip *chip, float *temperature) {
    uint8_t cmd = SI7051_TEMP_MEASURE_NO_HOLD;
    uint8_t data[2];
    int ret;

    ret = gpiod_i2c_write(chip, &cmd, 1);
    if (ret < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(-ret));
        return -1;
    }

    ret = gpiod_i2c_read(chip, data, 2);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(-ret));
        return -1;
    }

    if (ret != 2) {
        fprintf(stderr, "Incomplete data read from sensor\n");
        return -1;
    }

    *temperature = ((175.72 * (data[0] << 8 | data[1])) / 65536.0) - 46.85;
    return 0;
}

int main() {
    struct sigaction sa;
    gpiod_i2c_chip *chip = NULL;
    float temperature;
    int ret;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_i2c_chip_open(I2C_BUS, SI7051_ADDR);
    if (!chip) {
        fprintf(stderr, "Failed to open I2C chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    while (keep_running) {
        ret = read_temperature(chip, &temperature);
        if (ret == 0) {
            printf("Temperature: %.2f°C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }
        sleep(5);
    }

    gpiod_i2c_chip_close(chip);
    return EXIT_SUCCESS;
}

