#include <syslog.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x77
#define TEMP_PRESSURE_REGISTER 0x00
#define DEFAULT_TEMP_PRESSURE_VALUE 0x0000

static int i2c_fd = -1;
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int init_i2c() {
    i2c_fd = open("/dev/i2c-" PRIuMAX, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int read_sensor(int *temperature, int *pressure) {
    uint8_t buffer[2];
    int ret = read(i2c_fd, buffer, sizeof(buffer));
    if (ret < 0) {
        perror("Failed to read from I2C device");
        return -1;
    } else if (ret != sizeof(buffer)) {
        fprintf(stderr, "Incomplete read from I2C device\n");
        return -1;
    }

    if (buffer[0] == 0x00 && buffer[1] == 0x00) {
        fprintf(stderr, "Sensor absent or default value detected\n");
        return -1;
    }

    *temperature = buffer[0];
    *pressure = buffer[1];

    return 0;
}

void print_timestamp() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[30];
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", tm_info);
    printf("%s - ", buffer);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_i2c() != 0) {
        syslog(LOG_ERR, "Failed to initialize I2C");
        return EXIT_FAILURE;
    }

    atexit(cleanup);

    while (!stop) {
        int temperature = 0, pressure = 0;

        if (read_sensor(&temperature, &pressure) == 0) {
            print_timestamp();
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n",
                   temperature * 0.1, pressure * 0.1);
        }

        usleep(7000); // Wait 7 ms
        sleep(5 - 0.007); // Sleep for the remaining time of the 5-second interval
    }

    cleanup();
    return EXIT_SUCCESS;
}

