#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x28 // Sensirion SDP800-500Pa I2C address
#define I2C_TIMEOUT 1000 // I2C timeout in milliseconds
#define SAMPLE_INTERVAL 45 // Sample interval in milliseconds
#define LOG_FILE "pressure_log.txt"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31; // Polynomial 0x31
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(int fd, uint16_t *pressure, uint16_t *temperature) {
    uint8_t command[1] = {0x00}; // Trigger measurement
    uint8_t data[9];
    uint8_t crc;

    if (write(fd, command, 1) != 1) {
        perror("I2C write error");
        return -1;
    }

    usleep(SAMPLE_INTERVAL * 1000);

    if (read(fd, data, 9) != 9) {
        perror("I2C read error");
        return -1;
    }

    crc = crc8(data, 2);
    if (crc != data[2]) {
        fprintf(stderr, "CRC error for pressure\n");
        return -1;
    }

    *pressure = (data[0] << 8) | data[1];

    crc = crc8(data + 3, 2);
    if (crc != data[5]) {
        fprintf(stderr, "CRC error for temperature\n");
        return -1;
    }

    *temperature = (data[3] << 8) | data[4];

    return 0;
}

void log_data(uint16_t pressure, uint16_t temperature) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d, %d, %d\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            pressure, temperature);

    fclose(file);
}

int main() {
    int i2c_fd;
    uint16_t pressure, temperature;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (read_sensor_data(i2c_fd, &pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        }
        usleep(SAMPLE_INTERVAL * 1000);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

