#include <errno.h>
#include <gpiod.h>
#include <syslog.h>
#include <sys/stat.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x28
#define I2C_TIMEOUT 1000
#define LOG_FILE "airflow_log.csv"
#define POLYNOMIAL 0x31
#define INITIAL_VALUE 0xFF

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int crc8(const uint8_t *data, size_t length) {
    uint8_t crc = INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_pressure(int fd, int16_t *pressure) {
    uint8_t cmd = 0x00; // Trigger measurement command
    uint8_t data[3];
    int ret;

    ret = ioctl(fd, I2C_SLAVE, SENSOR_ADDR);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        return -1;
    }

    ret = write(fd, &cmd, 1);
    if (ret != 1) {
        syslog(LOG_ERR, "Failed to write trigger command: %s", strerror(errno));
        return -1;
    }

    usleep(8000); // Wait at least 8 ms

    ret = read(fd, data, 3);
    if (ret != 3) {
        syslog(LOG_ERR, "Failed to read data: %s", strerror(errno));
        return -1;
    }

    uint8_t crc = crc8(data, 2);
    if (crc != data[2]) {
        syslog(LOG_ERR, "CRC check failed");
        return -1;
    }

    *pressure = (data[0] << 8) | data[1];
    return 0;
}

void log_pressure(int16_t pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return;
    }

    if (access(LOG_FILE, F_OK) == -1) {
        fprintf(log_file, "Timestamp,Pressure\n");
    }

    fprintf(log_file, "%s,%d\n", time_str, pressure);
    fclose(log_file);
}

int main() {
    openlog("airflow_logger", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    int16_t pressure;
    while (!stop) {
        if (read_pressure(fd, &pressure) == 0) {
            log_pressure(pressure);
        }
        usleep(10000); // Sleep for 10 ms between readings
    }

    close(fd);
    closelog();
    return EXIT_SUCCESS;
}

