#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90821_ADDR 0x4A
#define MLX90821_REG_PRESSURE 0x00
#define SAFE_PRESSURE_MIN 200
#define SAFE_PRESSURE_MAX 250

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int open_i2c_bus() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90821_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int read_pressure(int *pressure) {
    char buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        return -1;
    }
    *pressure = (buf[0] << 8) | buf[1];
    return 0;
}

void log_pressure(int pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }
    fprintf(log_file, "%s,%d\n", timestamp, pressure);
    fflush(log_file);

    if (pressure < SAFE_PRESSURE_MIN || pressure > SAFE_PRESSURE_MAX) {
        fprintf(stderr, "Warning: Pressure %d kPa is outside the safe range (%d-%d kPa)\n",
                pressure, SAFE_PRESSURE_MIN, SAFE_PRESSURE_MAX);
    }
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (open_i2c_bus() != 0) {
        cleanup();
        exit(EXIT_FAILURE);
    }

    log_file = fopen("pressure_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (!stop) {
        int pressure = 0;
        if (read_pressure(&pressure) != 0) {
            close(i2c_fd);
            i2c_fd = -1;
            if (open_i2c_bus() != 0) {
                fprintf(stderr, "Failed to reopen I2C bus\n");
                cleanup();
                exit(EXIT_FAILURE);
            }
            if (read_pressure(&pressure) != 0) {
                fprintf(stderr, "Failed to read pressure after retry\n");
                continue;
            }
        }
        log_pressure(pressure);
        sleep(1);
    }

    cleanup();
    return 0;
}

