#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define HIH6130_ADDR 0x27
#define HIH6130_REG_TEMP_HUM 0x00
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE 1048576 // 1 MB

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_humidity_temperature(int fd, float *humidity, float *temperature) {
    uint8_t data[4];
    int ret = i2c_smbus_read_i2c_block_data(fd, HIH6130_REG_TEMP_HUM, 4, data);
    if (ret < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }

    if ((data[0] & 0x80) || (data[2] & 0x80)) {
        fprintf(stderr, "Sensor status bits indicate an error\n");
        return -1;
    }

    uint16_t raw_humidity = (data[0] << 8) | data[1];
    uint16_t raw_temperature = (data[2] << 8) | data[3];

    *humidity = (float)raw_humidity * 100.0 / 65536.0;
    *temperature = ((float)raw_temperature * 165.0 / 65536.0) - 40.0;

    return 0;
}

void log_data(const char *filename, float humidity, float temperature) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
