#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_PIN 4
#define TICK_TIME_US 3
#define SYNC_PULSE_TICKS 56
#define MIN_PULSE_TICKS 12
#define MAX_PULSE_TICKS 271
#define TIMEOUT_MS 1000
#define LOG_FILE "pressure_log.txt"

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int read_sent_data(struct gpiod_line *line, uint8_t *status, uint8_t *data, uint8_t *checksum) {
    uint64_t ticks;
    uint8_t nibble;
    int i;

    for (i = 0; i < 5; i++) {
        if (gpiod_line_get_value(line, &ticks) < 0) {
            fprintf(stderr, "Error reading line value: %s\n", strerror(errno));
            return -1;
        }

        if (ticks > TIMEOUT_MS * 1000 / TICK_TIME_US) {
            fprintf(stderr, "Sensor absent condition detected.\n");
            return -2;
        }

        if (ticks < SYNC_PULSE_TICKS) {
            fprintf(stderr, "Bus error: Synchronization pulse out of range.\n");
            return -3;
        }

        ticks -= SYNC_PULSE_TICKS;

        if (ticks < MIN_PULSE_TICKS || ticks > MAX_PULSE_TICKS) {
            fprintf(stderr, "Bus error: Pulse width out of range.\n");
            return -4;
        }

        nibble = (ticks - MIN_PULSE_TICKS) / (MAX_PULSE_TICKS - MIN_PULSE_TICKS) * 15;
        if (i == 0) {
            *status = nibble;
        } else if (i < 4) {
            data[i - 1] = nibble;
        } else {
            *checksum = nibble;
        }
    }

    if (*checksum != (*status ^ data[0] ^ data[1] ^ data[2])) {
        fprintf(stderr, "Bus error: Checksum mismatch.\n");
        return -5;
    }

    return 0;
}

void log_pressure_data(uint8_t status, uint8_t *data) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    double pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    pressure *= 0.1; // Convert to Pascal

    fprintf(file, "%s, Pressure: %.2f Pa\n", time_str, pressure);
    fclose(file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    uint8_t status, data[3], checksum;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "sent_reader", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0) {
        fprintf(stderr, "Error requesting line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!stop) {
        ret = read_sent_data(line, &status, data, &checksum);
        if (ret == 0) {
            log_pressure_data(status, data);
        } else if (ret == -2) {
            // Sensor absent, continue to next iteration
            continue;
        } else {
            // Handle other errors
            break;
        }

        usleep(TICK_TIME_US * 1000);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

