#define TMP117_TEMP_REG 0x00
#define TMP117_DEVICE_ID_REG 0x01
#define TMP117_CONFIG_REG 0x02
#define TMP117_CONFIG_CONTINUOUS 0x80

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int check_device_id(int fd) {
    uint8_t device_id;
    if (ioctl(fd, I2C_SLAVE, TMP117_I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        return -1;
    }

    if (i2c_smbus_read_byte_data(fd, TMP117_DEVICE_ID_REG) < 0) {
        syslog(LOG_ERR, "Failed to read device ID: %s", strerror(errno));
        return -1;
    }

    if (i2c_smbus_read_byte_data(fd, TMP117_DEVICE_ID_REG) != TMP117_DEVICE_ID) {
        syslog(LOG_ERR, "Invalid device ID");
        return -1;
    }

    return 0;
}

int read_temperature(int fd, float *temperature) {
    uint8_t data[2];
    if (ioctl(fd, I2C_SLAVE, TMP117_I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        return -1;
    }

    if (i2c_smbus_read_i2c_block_data(fd, TMP117_TEMP_REG, 2, data) < 0) {
        syslog(LOG_ERR, "Failed to read temperature: %s", strerror(errno));
        return -1;
    }

    uint16_t temp_raw = (data[0] << 8) | data[1];
    *temperature = (float)temp_raw * 0.03125;

    return 0;
}

int main() {
    openlog("greenhouse_monitor", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (check_device_id(fd) < 0) {
        syslog(LOG_ERR, "Device ID check failed");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, TMP117_I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_smbus_write_byte_data(fd, TMP117_CONFIG_REG, TMP117_CONFIG_CONTINUOUS) < 0) {
        syslog(LOG_ERR, "Failed to set continuous conversion mode: %s", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }

    FILE *file = fopen("greenhouse_temps.dat", "wb");
    if (!file) {
        syslog(LOG_ERR, "Failed to open file: %s", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (keep_running) {
        float temperature;
        if (read_temperature(fd, &temperature) == 0) {
            uint32_t temp_le = htole32(*(uint32_t *)&temperature);
            fwrite(&temp_le, sizeof(temp_le), 1, file);
        } else {
            syslog(LOG_WARNING, "Failed to read temperature, retrying...");
        }

        sleep(60);
    }

    fclose(file);
    close(fd);
    closelog();

    return EXIT_SUCCESS;
}

