#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>

#define I2C_BUS 1
#define SHT40_I2C_ADDR 0x44
#define SHT40_MEASURE_TEMP_HOLD 0xE3
#define SHT40_MEASURE_HUM_HOLD 0xE5
#define SHT40_READ 0xE0
#define SHT40_CRC_POLYNOMIAL 0x31
#define SHT40_CRC_INIT 0xFF

static int i2c_fd = -1;
static FILE *log_file = NULL;

void cleanup(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

uint8_t calculate_crc(uint8_t *data, size_t length) {
    uint8_t crc = SHT40_CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(float *temperature, float *humidity) {
    uint8_t command[1];
    uint8_t data[6];
    int ret;

    // Measure temperature
    command[0] = SHT40_MEASURE_TEMP_HOLD;
    ret = write(i2c_fd, command, 1);
    if (ret != 1) {
        perror("Failed to write temperature command");
        return -1;
    }
    usleep(8500); // Wait for conversion

    ret = read(i2c_fd, data, 3);
    if (ret != 3) {
        perror("Failed to read temperature data");
        return -1;
    }
    if (calculate_crc(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC error\n");
        return -1;
    }
    *temperature = ((data[0] << 8) | data[1]) * 175.72 / 65536.0 - 46.85;

    // Measure humidity
    command[0] = SHT40_MEASURE_HUM_HOLD;
    ret = write(i2c_fd, command, 1);
    if (ret != 1) {
        perror("Failed to write humidity command");
        return -1;
    }
    usleep(8500); // Wait for conversion

    ret = read(i2c_fd, data, 3);
