#include <syslog.h>
#include <time.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TMP117_TEMP_REG 0x00
#define BUFFER_SIZE 10
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t keep_running = 1;
static int i2c_fd;
static uint8_t buffer[BUFFER_SIZE];
static size_t buffer_index = 0;
static FILE *log_file;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_error(const char *message) {
    syslog(LOG_ERR, "%s: %s", message, strerror(errno));
}

void flush_buffer_to_file() {
    if (log_file) {
        fwrite(buffer, sizeof(uint8_t), BUFFER_SIZE, log_file);
        fflush(log_file);
    }
}

void close_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    closelog();
}

int init_i2c() {
    i2c_fd = open("/dev/i2c-" PRIuMAX, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        log_error("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int read_temperature() {
    uint8_t reg = TMP117_TEMP_REG;
    uint8_t data[2];

    if (write(i2c_fd, &reg, 1) != 1) {
        log_error("Failed to write to I2C bus");
        return -1;
    }

    if (read(i2c_fd, data, 2) != 2) {
        log_error("Failed to read from I2C bus");
        return -1;
    }

    int16_t temp_raw = (data[0] << 8) | data[1];
    int16_t temp_c = (temp_raw >> 4) * 0.0625;

    buffer[buffer_index++] = (uint8_t)temp_c;
    if (buffer_index >= BUFFER_SIZE) {
        buffer_index = 0;
    }

    return 0;
}

int main() {
    openlog("TMP117_Logger", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_i2c() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    log_file = fopen("temperature_log.dat", "wb");
    if (!log_file) {
        log_error("Failed to open log file");
        close_resources();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (read_temperature() == 0) {
            flush_buffer_to_file();
        }
        sleep(SAMPLE_INTERVAL);
    }

    flush_buffer_to_file();
    close_resources();
    return EXIT_SUCCESS;
}

