#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <syslog.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SHTC3_I2C_ADDR 0x70
#define SHTC3_MEASUREMENT_PERIOD_MS 5000
#define SHTC3_CONVERSION_TIME_MS 12
#define SHTC3_LOG_FILE "shtc3_environment.log"

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_shtc3(int fd, uint8_t *data, size_t length) {
    if (write(fd, data, length) != length) {
        perror("I2C write error");
        return -1;
    }
    usleep(SHTC3_CONVERSION_TIME_MS * 1000);
    if (read(fd, data, length) != length) {
        perror("I2C read error");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, handle_sigint);

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHTC3_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(SHTC3_LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t command[2] = {0x24, 0x00}; // Command for high repeatability measurement
    uint8_t data[6];

    while (keep_running) {
        if (read_shtc3(i2c_fd, command, 2) < 0) {
            continue;
        }

        if (read_shtc3(i2c_fd, data, 6) < 0) {
            continue;
        }

        uint8_t crc_temp = crc8(data, 3);
        uint8_t crc_hum = crc8(data + 3, 3);

        if (crc_temp != data[3] || crc_hum != data[6]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        int16_t raw_temp = (data[0] << 8) | data[1];
        int16_t raw_hum = (data[3] << 8) | data[4];

        float temperature = -45 + 175 * raw_temp / 65535.0;
        float humidity = 100 * raw_hum / 65535.0;

        if (temperature < -40 || temperature > 125 || humidity < 0 || humidity > 100) {
            fprintf(stderr, "Out of range: Temp=%.2f, Hum=%.2f\n", temperature, humidity);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(stdout, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);

        fflush(stdout);
        fflush(log_file);

        usleep(SHTC3_MEASUREMENT_PERIOD_MS * 1000 - SHTC3_CONVERSION_TIME_MS * 1000);
    }

    close(i2c_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

