    buf[0] = reg;
    ret = gpiod_i2c_read(ctx, SI7202_ADDR, buf, 1, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to read register %02x: %s\n", reg, strerror(errno));
        return -1;
    }

    ret = gpiod_i2c_read(ctx, SI7202_ADDR, buf, 2, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    gpiod_ctx ctx;
    FILE *log_file;
    int16_t temp, speed;
    time_t t;
    struct tm *tm_info;

    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_i2c(&ctx) < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_ctx_close(&ctx);
        return EXIT_FAILURE;
    }

    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Speed (RPM)\n");
    }

    while (keep_running) {
        t = time(NULL);
        tm_info = localtime(&t);

        if (read_sensor(&ctx, SI7202_REG_TEMP, &temp) < 0) {
            temp = NAN;
        }

        if (read_sensor(&ctx, SI7202_REG_SPEED, &speed) < 0) {
            speed = NAN;
        }

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                temp, speed);

        fflush(log_file);
        sleep(1);
    }

    fclose(log_file);
    gpiod_ctx_close(&ctx);
    return EXIT_SUCCESS;
}
