#define TMP117_CONFIG_DR_0_5 0x00
#define TMP117_CONFIG_DR_1_0 0x20
#define TMP117_CONFIG_DR_2_0 0x40
#define TMP117_CONFIG_DR_4_0 0x60

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int init_i2c(const char *bus, int addr, int *fd) {
    *fd = open(bus, O_RDWR);
    if (*fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, addr) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

