    uint8_t config = TMP117_CONFIG_CONTINUOUS | TMP117_CONFIG_RESET | TMP117_CONFIG_DR_0_5;
    if (write(fd, &config, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to TMP117 configuration register: %s", strerror(errno));
        return -1;
    }

    usleep(100000); // Wait for reset to complete

    config = TMP117_CONFIG_CONTINUOUS | TMP117_CONFIG_DR_0_5;
    if (write(fd, &config, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to TMP117 configuration register: %s", strerror(errno));
        return -1;
    }

    return 0;
}

int read_temperature(int fd, float *temperature) {
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read from TMP117 temperature register: %s", strerror(errno));
        return -1;
    }

    int16_t raw_temp = (data[0] << 8) | data[1];
    *temperature = raw_temp * 0.03125;

    return 0;
}

void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return;
    }

    fprintf(log_file, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fclose(log_file);
}

int main() {
    openlog("TMP117_Logger", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_sigint);

    int i2c_fd = -1;
    int init_attempts = 0;
    while (init_attempts < 3 && keep_running) {
        if (init_i2c("/dev/i2c-1", TMP117_I2C_ADDR, &i2c_fd) == 0) {
            if (configure_sensor(i2c_fd) == 0) {
                break;
            }
        }
        init_attempts++;
        syslog(LOG_WARNING, "I2C initialization failed, attempt %d", init_attempts);
        sleep(1);
    }

    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to initialize I2C after 3 attempts");
        closelog();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        float temperature;
        if (read_temperature(i2c_fd, &temperature) == 0) {
            log_temperature(temperature);
        } else {
            syslog(LOG_WARNING, "Failed to read temperature, retrying...");
        }
        sleep(1);
    }

    close(i2c_fd);
    closelog();
    return EXIT_SUCCESS;
}

