#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x28 // Replace with the actual I2C address of the sensor
#define LOG_FILE "flow_log.txt"

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int init_i2c() {
    i2c_fd = open("/dev/i2c-" PRIuMAX, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int read_sensor_data(int *flow, int *temperature) {
    uint8_t buffer[4];
    ssize_t bytes_read = read(i2c_fd, buffer, sizeof(buffer));
    if (bytes_read != sizeof(buffer)) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Extract 14-bit flow value (bits 0-13)
    *flow = (buffer[0] | (buffer[1] << 8)) & 0x3FFF;

    // Extract 12-bit temperature value (bits 14-25)
    *temperature = ((buffer[1] >> 2) | (buffer[2] << 6)) & 0xFFF;

    return 0;
}

void log_data(int flow, int temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s - Flow: %.2f SLPM, Temperature: %.2f °C\n",
            time_str,
            flow / 100.0, // Convert to SLPM
            temperature / 10.0); // Convert to °C
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    int flow, temperature;
    int first_read = 1;

    while (!stop) {
        if (read_sensor_data(&flow, &temperature) != 0) {
            fprintf(stderr, "Error reading sensor data, attempting to reinitialize I2C\n");
            cleanup();
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to reinitialize I2C\n");
                break;
            }
            continue;
        }

        if (first_read) {
            first_read = 0;
            continue; // Skip the first two reads
        }

        log_data(flow, temperature);
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

