int read_dht11(gpiod_line *line, uint8_t *data) {
    uint64_t levels;
    int ret;

    // Start signal: pull line low for 18ms
    gpiod_line_request_output(line, "dht11", 0);
    usleep(DHT11_START_LOW_MS * 1000);
    gpiod_line_request_input(line, "dht11");
    usleep(40);

    // Wait for response: 80us low, 80us high
    ret = gpiod_line_get_both_edges_timeout(line, &levels, DHT11_TIMEOUT_US);
    if (ret < 0) {
        log_error("Timeout waiting for DHT11 response start");
        return -1;
    }
    if (!(levels & GPIOD_LINE_LEVEL_HIGH)) {
        log_error("DHT11 response start low pulse missing");
        return -1;
    }
    usleep(DHT11_RESPONSE_LOW_US);

    ret = gpiod_line_get_both_edges_timeout(line, &levels, DHT11_TIMEOUT_US);
    if (ret < 0) {
        log_error("Timeout waiting for DHT11 response high pulse");
        return -1;
    }
    if (!(levels & GPIOD_LINE_LEVEL_LOW)) {
        log_error("DHT11 response high pulse missing");
        return -1;
    }
    usleep(DHT11_RESPONSE_HIGH_US);

    // Read 40 bits
    for (int i = 0; i < 40; i++) {
        ret = gpiod_line_get_both_edges_timeout(line, &levels, DHT11_TIMEOUT_US);
        if (ret < 0) {
            log_error("Timeout waiting for DHT11 data bit");
            return -1;
        }
        if (!(levels & GPIOD_LINE_LEVEL_LOW)) {
            log_error("DHT11 data bit low pulse missing");
            return -1;
        }
        usleep(DHT11_BIT_LOW_US);

        ret = gpiod_line_get_both_edges_timeout(line, &levels, DHT11_TIMEOUT_US);
        if (ret < 0) {
            log_error("Timeout waiting for DHT11 data bit high pulse");
            return -1;
        }
        if (!(levels & GPIOD_LINE_LEVEL_HIGH)) {
            log_error("DHT11 data bit high pulse missing");
            return -1;
        }

        // Measure high pulse width
        uint64_t start = gpiod_line_event_time(line);
        ret = gpiod_line_get_both_edges_timeout(line, &levels, DHT11_TIMEOUT_US);
        if (ret < 0) {
            log_error("Timeout waiting for DHT11 data bit end");
            return -1;
        }
        if (!(levels & GPIOD_LINE_LEVEL_LOW)) {
            log_error("DHT11 data bit end low pulse missing");
            return -1;
        }
        uint64_t end = gpiod_line_event_time(line);
        uint64_t duration = end - start;

        // Determine bit value
        if (duration > DHT11_BIT_ZERO_HIGH_US) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    return 0;
}

void write_reading_to_file(const char *filename, uint8_t *data) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

    fprintf(file, "[%s] Humidity: %d.%d, Temperature: %d.%d\n",
            timestamp, data[0], data[1], data[2], data[3]);

    fclose(file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    gpiod_line *line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "dht11", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    uint8_t data[5] = {0};
    while (keep_running) {
        if (read_dht11(line, data) == 0) {
            uint8_t checksum = data[0] + data[1] + data[2] + data[3];
            if (checksum == data[4]) {
                write_reading_to_file("dht11_readings.txt", data);
            } else {
                log_error("Checksum failure");
            }
        }
        sleep(DHT11_READ_INTERVAL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
