#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SHT31D_ADDR 0x44
#define MEASURE_TEMP_HOLD_CMD 0x2C06
#define MEASURE_HUM_HOLD_CMD 0x306D
#define MAX_RETRIES 3

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sht31d(int fd, uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, len) == len) {
            if (read(fd, buf, len) == len) {
                return 0;
            }
        }
        usleep(100000); // Retry after 100ms
    }
    return -1;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT31D_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("sht31d_data.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint8_t cmd[2] = {MEASURE_TEMP_HOLD_CMD >> 8, MEASURE_TEMP_HOLD_CMD & 0xFF};
        if (read_sht31d(i2c_fd, cmd, sizeof(cmd)) < 0) {
            fprintf(log_file, "%s,ERROR,Failed to initiate temperature measurement\n", ctime(&time(NULL)));
            continue;
        }

        usleep(15000); // Wait at least 15ms

        uint8_t buf[6];
        if (read_sht31d(i2c_fd, buf, sizeof(buf)) < 0) {
            fprintf(log_file, "%s,ERROR,Failed to read temperature and humidity\n", ctime(&time(NULL)));
            continue;
        }

        uint8_t temp_crc = crc8(buf, 2);
        if (temp_crc != buf[2]) {
            fprintf(log_file, "%s,ERROR,Invalid temperature CRC\n", ctime(&time(NULL)));
            continue;
        }

        uint8_t hum_crc = crc8(buf + 3, 2);
        if (hum_crc != buf[5]) {
            fprintf(log_file, "%s,ERROR,Invalid humidity CRC\n", ctime(&time(NULL)));
            continue;
        }

        int16_t temp = (buf[0] << 8) | buf[1];
        float temperature = -45 + 175 * temp / 65535.0;

        int16_t hum = (buf[3] << 8) | buf[4];
        float humidity = 100 * hum / 65535.0;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        fflush(log_file);

        sleep(5);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

