#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <libi2c.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90824_ADDR 0x48
#define MLX90824_PRESSURE_REGISTER 0x00
#define MLX90824_TEMPERATURE_REGISTER 0x01
#define LOG_FILE "pressure_log.txt"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_error(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] ERROR: %s\n", timestamp, message);
        fclose(log_file);
    }
}

void log_measurement(double pressure, double temperature) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] Pressure: %.2f Pa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
        fclose(log_file);
    }
}

int main() {
    struct i2c_client *client;
    int i2c_fd;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    client = i2c_new_client(i2c_fd, MLX90824_ADDR);
    if (!client) {
        log_error("Failed to create I2C client");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint8_t pressure_data[2];
        uint8_t temperature_data[2];
        double pressure, temperature;

        ret = i2c_smbus_read_i2c_block_data(client, MLX90824_PRESSURE_REGISTER, 2, pressure_data);
        if (ret < 0) {
            log_error("Failed to read pressure data");
        } else {
            pressure = (pressure_data[0] << 8 | pressure_data[1]) * 0.1;
            ret = i2c_smbus_read_i2c_block_data(client, MLX90824_TEMPERATURE_REGISTER, 2, temperature_data);
            if (ret < 0) {
                log_error("Failed to read temperature data");
            } else {
                temperature = (temperature_data[0] << 8 | temperature_data[1]) * 0.1;
                log_measurement(pressure, temperature);
            }
        }

        sleep(2);
    }

    i2c_unregister_client(client);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

