    }

    client = i2c_new_client(i2c_fd, MLX90824_ADDR);
    if (!client) {
        log_error("Failed to create I2C client");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint8_t pressure_data[2];
        uint8_t temperature_data[2];
        double pressure, temperature;

        ret = i2c_smbus_read_i2c_block_data(client, MLX90824_PRESSURE_REGISTER, 2, pressure_data);
        if (ret < 0) {
            log_error("Failed to read pressure data");
        } else {
            pressure = (pressure_data[0] << 8 | pressure_data[1]) * 0.1;
            ret = i2c_smbus_read_i2c_block_data(client, MLX90824_TEMPERATURE_REGISTER, 2, temperature_data);
            if (ret < 0) {
                log_error("Failed to read temperature data");
            } else {
                temperature = (temperature_data[0] << 8 | temperature_data[1]) * 0.1;
                log_measurement(pressure, temperature);
            }
        }

        sleep(2);
    }

    i2c_unregister_client(client);
    close(i2c_fd);

    return EXIT_SUCCESS;
}
