#define I2C_BUS "/dev/i2c-1"
#define LM75B_ADDR 0x48
#define LM75B_TEMP_REG 0x00
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 26.0

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

double read_temperature(int i2c_fd) {
    char buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
        return -1.0;
    }
    int temp_raw = (buf[0] << 8) | buf[1];
    if (temp_raw & 0x8000) {
        temp_raw |= 0xF000; // Sign extend if negative
    }
    return temp_raw / 256.0;
}

void set_fan_state(gpiod_chip *chip, gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        fprintf(stderr, "Failed to set fan state: %s\n", strerror(errno));
    }
}

