    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75B_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    gpiod_line *line = gpiod_chip_get_line(chip, FAN_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "fan_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    double buffer[BUFFER_SIZE] = {0};
    int buffer_index = 0;
    double sum = 0.0;
    int fan_on = 0;

    while (keep_running) {
        double temp = read_temperature(i2c_fd);
        if (temp >= 0.0) {
            sum -= buffer[buffer_index];
            buffer[buffer_index] = temp;
            sum += temp;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            double average = sum / BUFFER_SIZE;
            if (average > TEMP_THRESHOLD_ON && !fan_on) {
                set_fan_state(chip, line, 1);
                fan_on = 1;
            } else if (average < TEMP_THRESHOLD_OFF && fan_on) {
                set_fan_state(chip, line, 0);
                fan_on = 0;
            }
        }
        sleep(1);
    }

    if (fan_on) {
        set_fan_state(chip, line, 0);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

