#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <syslog.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDR 0x28
#define MEASUREMENT_CMD 0x00
#define DATA_LENGTH 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define PRESSURE_THRESHOLD 5.0

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

uint8_t calculate_crc(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_reading(double timestamp, double pressure, double temperature) {
    FILE *log_file = fopen("airflow.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%f,%f,%f\n", timestamp, pressure, temperature);
    fclose(log_file);
}

int main() {
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        uint8_t cmd = MEASUREMENT_CMD;
        if (write(i2c_fd, &cmd, 1) != 1) {
            perror("Failed to write measurement command");
            break;
        }

        usleep(45000); // Wait 45 ms

        uint8_t data[DATA_LENGTH];
        if (read(i2c_fd, data, DATA_LENGTH) != DATA_LENGTH) {
            perror("Failed to read data from sensor");
            break;
        }

        uint8_t received_crc = data[DATA_LENGTH - 1];
        uint8_t calculated_crc = calculate_crc(data, DATA_LENGTH - 1);

        if (received_crc != calculated_crc) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        double pressure = (data[1] << 8 | data[0]) / 1000.0;
        double temperature = (data[3] << 8 | data[2]) / 100.0;

        if (pressure > PRESSURE_THRESHOLD) {
            fprintf(stderr, "Warning: Pressure exceeds threshold: %f Pa\n", pressure);
        }

        time_t now = time(NULL);
        log_reading(now, pressure, temperature);

        sleep(1);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

