#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x48
#define LED_GPIO 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

void cleanup_and_exit(int signum) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

void handle_signal(int signum) {
    cleanup_and_exit(signum);
}

float read_temperature() {
    char buf[3];
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }

    buf[0] = 0x00; // Temperature register
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Failed to write to I2C bus");
        return -1;
    }

    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read from I2C bus");
        return -1;
    }

    int raw_temp = (buf[0] << 8) | buf[1];
    float temperature = (raw_temp >> 3) * 0.125;
    return temperature;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "temp_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    float last_temperature = -1.0;
    int i2c_failures = 0;

    while (1) {
        float temperature = read_temperature();
        if (temperature < 0) {
            i2c_failures++;
            if (i2c_failures > 3) {
                fprintf(stderr, "Repeated I2C failures: %s\n", strerror(errno));
                cleanup_and_exit(EXIT_FAILURE);
            }
            sleep(1);
            continue;
        }

        i2c_failures = 0;

        if (temperature > TEMP_THRESHOLD_HIGH) {
            gpiod_line_set_value(led_line, 1);
        } else if (temperature < TEMP_THRESHOLD_LOW) {
            gpiod_line_set_value(led_line, 0);
        }

        if (last_temperature != temperature) {
            printf("Temperature: %.2f°C\n", temperature);
            last_temperature = temperature;
        }

        sleep(1);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

