#define SI7021_I2C_ADDR 0x40
#define SI7021_CMD_MEASURE_RELATIVE_HUMIDITY_NO_HOLD 0xF5
#define SI7021_CMD_MEASURE_TEMPERATURE_NO_HOLD 0xF3
#define SI7021_CMD_READ_TEMP_FROM_PREV_RH_MEASUREMENT 0xE3
#define SI7021_CMD_READ_ELECTRONIC_ID 0xFA
#define SI7021_CMD_READ_FIRMWARE_REVISION 0x84

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "environment.log"
#define RETRY_LIMIT 3
#define SLEEP_INTERVAL 60

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int i2c_write_read(int fd, uint8_t cmd, uint8_t *data, size_t length) {
    struct i2c_msg msgs[2];
    uint8_t tx_buf[1] = {cmd};
    uint8_t rx_buf[2] = {0};

    msgs[0].addr = SI7021_I2C_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = tx_buf;

    msgs[1].addr = SI7021_I2C_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = length;
    msgs[1].buf = rx_buf;

    if (i2c_transfer(fd, msgs, 2) != 2) {
        return -1;
    }

    memcpy(data, rx_buf, length);
    return 0;
}

int read_sensor_data(int fd, float *temperature, float *humidity) {
    uint8_t data[2];
    int retries = 0;
    int ret;

    // Measure relative humidity
    while (retries < RETRY_LIMIT) {
        ret = i2c_write_read(fd, SI7021_CMD_MEASURE_RELATIVE_HUMIDITY_NO_HOLD, data, 2);
        if (ret == 0) {
            usleep(20000); // Wait at least 20 ms
            break;
        }
        retries++;
    }
    if (retries == RETRY_LIMIT) {
        return -1;
    }

    // Measure temperature
    retries = 0;
    while (retries < RETRY_LIMIT) {
        ret = i2c_write_read(fd, SI7021_CMD_MEASURE_TEMPERATURE_NO_HOLD, data, 2);
        if (ret == 0) {
            usleep(20000); // Wait at least 20 ms
            break;
        }
        retries++;
    }
    if (retries == RETRY_LIMIT) {
        return -1;
    }

    // Calculate humidity
    uint16_t rh = (data[0] << 8) | data[1];
    *humidity = -6.0 + 125.0 * (rh / 65536.0);

    // Read temperature from previous RH measurement
    retries = 0;
    while (retries < RETRY_LIMIT) {
        ret = i2c_write_read(fd, SI7021_CMD_READ_TEMP_FROM_PREV_RH_MEASUREMENT, data, 2);
        if (ret == 0) {
            break;
        }
        retries++;
    }
    if (retries == RETRY_LIMIT) {
        return -1;
    }

    // Calculate temperature
    uint16_t temp = (data[0] << 8) | data[1];
    *temperature = -46.85 + 175.72 * (temp / 65536.0);

    return 0;
}

int validate_sensor(int fd) {
    uint8_t data[2];
    int retries = 0;
    int ret;

    // Read electronic ID
    while (retries < RETRY_LIMIT) {
        ret = i2c_write_read(fd, SI7021_CMD_READ_ELECTRONIC_ID, data, 2);
        if (ret == 0) {
            break;
        }
        retries++;
    }
    if (retries == RETRY_LIMIT) {
        return -1;
    }

    // Read firmware revision
    retries = 0;
    while (retries < RETRY_LIMIT) {
        ret = i2c_write_read(fd, SI7021_CMD_READ_FIRMWARE_REVISION, data, 2);
        if (ret == 0) {
            return 0;
        }
        retries++;
    }

    return -1;
}

void log_error(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *log_fd = fopen(LOG_FILE, "a");
    if (log_fd) {
        fprintf(log_fd, "%s ERROR: %s\n", timestamp, message);
        fflush(log_fd);
        fclose(log_fd);
    }

    fprintf(stderr, "%s ERROR: %s\n", timestamp, message);
}

int main() {
    int i2c_fd;
    FILE *log_fd;
    struct sigaction sa;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (validate_sensor(i2c_fd) < 0) {
        log_error("Sensor not present");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_fd = fopen(LOG_FILE, "a");
    if (!log_fd) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (!stop) {
        float temperature, humidity;
        if (read_sensor_data(i2c_fd, &temperature, &humidity) == 0) {
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

            char log_entry[100];
            snprintf(log_entry, sizeof(log_entry), "%s,%.2f,%.2f\n", timestamp, temperature, humidity);

            fprintf(log_fd, "%s", log_entry);
            fflush(log_fd);
            printf("%s", log_entry);
        } else {
