#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define HDC1080_ADDR 0x40
#define HDC1080_TEMP_REG 0x00
#define HDC1080_HUMIDITY_REG 0x01
#define HDC1080_CONFIG_REG 0x02
#define HDC1080_CONFIG_CONT 0x80
#define HDC1080_CONFIG_RES 0x00

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int open_i2c_bus(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    return fd;
}

int set_i2c_address(int fd, uint8_t addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }
    return 0;
}

int read_i2c_register(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, length) != length) {
        perror("Failed to read data from register");
        return -1;
    }
    return 0;
}

int write_i2c_register(int fd, uint8_t reg, uint8_t data) {
    uint8_t buffer[2] = {reg, data};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write data to register");
        return -1;
    }
    return 0;
}

int read_temperature_and_humidity(int fd, float *temperature, float *humidity) {
    uint8_t data[4];
    if (read_i2c_register(fd, HDC1080_TEMP_REG, data, 2) < 0) {
        return -1;
    }
    int16_t temp_raw = (data[0] << 8) | data[1];
    *temperature = -46.85 + 175.72 * temp_raw / 65536.0;

    if (read_i2c_register(fd, HDC1080_HUMIDITY_REG, data, 2) < 0) {
        return -1;
    }
    int16_t hum_raw = (data[0] << 8) | data[1];
    *humidity = -6.0 + 125.0 * hum_raw / 65536.0;

    return 0;
}

void log_environment_data(float temperature, float humidity) {
    FILE *file = fopen("enviro_log.txt", "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open_i2c_bus(I2C_BUS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    if (set_i2c_address(i2c_fd, HDC1080_ADDR) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write_i2c_register(i2c_fd, HDC1080_CONFIG_REG, HDC1080_CONFIG_CONT | HDC1080_CONFIG_RES) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (!stop) {
        float temperature, humidity;
        if (read_temperature_and_humidity(i2c_fd, &temperature, &humidity) == 0) {
            log_environment_data(temperature, humidity);
        }
        usleep(5000); // Wait 5 seconds
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

