int main() {
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        uint8_t command = 0x00; // Trigger temperature conversion
        if (write(i2c_fd, &command, 1) != 1) {
            fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        }

        usleep(READ_DELAY * 1000); // Wait for conversion to complete

        uint8_t buffer[3];
        if (read(i2c_fd, buffer, 3) != 3) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
            continue;
        }

        uint8_t crc = crc8(buffer, 2);
        if (crc != buffer[2]) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        int16_t raw_temperature = (buffer[0] << 8) | buffer[1];
        double temperature = raw_temperature * 175.72 / 65536.0 - 46.85;

        log_temperature(log_fd, temperature);

        usleep(POLL_INTERVAL * 1000); // Wait before next reading
    }

    close(i2c_fd);
    close(log_fd);
    return EXIT_SUCCESS;
}

