#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x28 // Sensirion SDP810 I2C address
#define I2C_BUFFER_SIZE 9
#define POLYNOMIAL 0x31
#define INITIAL_VALUE 0xFF

volatile sig_atomic_t stop = 0;

void handle_sigint(int sig) {
    stop = 1;
}

uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int validate_crc(const uint8_t *data, size_t length) {
    if (length < 3) return 0;
    uint8_t calculated_crc = crc8(data, length - 1);
    return calculated_crc == data[length - 1];
}

int main() {
    struct timespec ts;
    FILE *log_file;
    int ret;
    uint8_t buffer[I2C_BUFFER_SIZE];
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];
    struct i2c_smbus_ioctl_data ioctl_data;
    int fd;

    signal(SIGINT, handle_sigint);

    fd = open("/dev/i2c-" PRIuMAX, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("hvac_pressure_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,pressure_Pa,temperature_C\n");

    while (!stop) {
        memset(buffer, 0, I2C_BUFFER_SIZE);

        messages[0].addr = I2C_ADDRESS;
        messages[0].flags = 0;
        messages[0].len = 1;
        messages[0].buf = (uint8_t[]){0x00}; // Trigger measurement

        messages[1].addr = I2C_ADDRESS;
        messages[1].flags = I2C_M_RD;
        messages[1].len = I2C_BUFFER_SIZE;
        messages[1].buf = buffer;

        packets.msgs = messages;
        packets.nmsgs = 2;

        ret = ioctl(fd, I2C_RDWR, &packets);
        if (ret < 0) {
            fprintf(log_file, "%ld,%s\n", time(NULL), "I2C read/write error");
            perror("I2C read/write error");
            continue;
        }

        if (!validate_crc(buffer, 3) || !validate_crc(buffer + 4, 4)) {
            fprintf(log_file, "%ld,%s\n", time(NULL), "CRC error");
            continue;
        }

        int16_t pressure = (buffer[0] << 8) | buffer[1];
        int16_t temperature = (buffer[4] << 8) | buffer[5];
        float pressure_Pa = pressure * 0.1f;
        float temperature_C = temperature * 0.01f;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%f,%f\n", ts.tv_sec, ts.tv_nsec, pressure_Pa, temperature_C);

        fflush(log_file);
        usleep(50000); // Wait at least 50 ms
        usleep(950000); // Wait to complete 1 second cycle
    }

    fclose(log_file);
    close(fd);
    return EXIT_SUCCESS;
}

