code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <pthread.h>
#include <libgpiod.h>
#include <gpiod.h>
#include <syslog.h>
#include <inttypes.h>

#define I2C_BUS 1
#define SCD40_I2C_ADDR 0x61
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define CSV_HEADER "timestamp,co2,temperature,humidity\n"

typedef struct {
    uint32_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} SensorData;

typedef struct {
    SensorData buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

volatile sig_atomic_t running = 1;

CircularBuffer cb;
pthread_t logger_thread;

void log_error(const char *message) {
    FILE *log_file = fopen(ERROR_LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fclose(log_file);
    } else {
        syslog(LOG_ERR, "Failed to open error log file: %s", strerror(errno));
    }
}

void handle_signal(int sig) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t length) {
    const uint8_t polynomial = 0x31;
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(int i2c_fd, SensorData *data) {
    uint8_t command[2] = {0x20, 0x08}; // Start periodic measurement
    if (write(i2c_fd, command, sizeof(command)) != sizeof(command)) {
        log_error("Failed to write start periodic measurement command");
        return -1;
    }

    usleep(1000000); // Wait 1 second

    uint8_t read_buffer[18];
    for (int i = 0; i < 5; i++) {
        if (!running) return 0;

        if (write(i2c_fd, command, sizeof(command)) != sizeof(command)) {
            log_error("Failed to write start periodic measurement command");
            return -1;
        }

        usleep(5000000); // Wait 5 seconds

        if (read(i2c_fd, read_buffer, sizeof(read_buffer)) != sizeof(read_buffer)) {
            log_error("Failed to read sensor data");
            return -1;
        }

        uint8_t crc = crc8(read_buffer, 16);
        if (crc != read_buffer[16]) {
            log_error("CRC check failed");
            continue;
        }

        data->timestamp = (read_buffer[0] << 24) | (read_buffer[1] << 16) | (read_buffer[2] << 8) | read_buffer[3];
        data->co2 = (read_buffer[4] << 8) | read_buffer[5];
        data->temperature = ((int16_t)((read_buffer[6] << 8) | read_buffer[7])) / 100.0;
        data->humidity = ((int16_t)((read_buffer[8] << 8) | read_buffer[9])) / 100.0;

        pthread_mutex_lock(&cb.mutex);
        cb.buffer[cb.head] = *data;
        cb.head = (cb.head + 1) % BUFFER_SIZE;
        if (cb.count < BUFFER_SIZE) {
            cb.count++;
        } else {
            cb.tail = (cb.tail + 1) % BUFFER_SIZE;
        }
        pthread_mutex_unlock(&cb.mutex);

        break;
    }

    uint8_t stop_command[2] = {0x20, 0x00}; // Stop periodic measurement
    if (write(i2c_fd, stop_command, sizeof(stop_command)) != sizeof(stop_command)) {
        log_error("Failed to write stop periodic measurement command");
    }

    return 0;
}

void *logger(void *arg) {
    while (running || cb.count > 0) {
        sleep(60);

        pthread_mutex_lock(&cb.mutex);
        int count = cb.count;
        cb.count = 0;
        pthread_mutex_unlock(&cb.mutex);

        if (count == 0) continue;

        char filename[256];
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        strftime(filename, sizeof(filename), "%Y%m%d%H%M%S.csv", tm_info);
        snprintf(filename + strlen(filename), sizeof(filename) - strlen(filename), "/%s", filename);

        mkdir(LOG_DIR, 0755);
        char filepath[256];
        snprintf(filepath, sizeof(filepath), "%s/%s", LOG_DIR, filename);

        FILE *file = fopen(filepath, "a");
        if (!file) {
            log_error("Failed to open CSV file for writing");
            continue;
        }

        if (cb.count == 0) {
            fprintf(file, "%s", CSV_HEADER);
        }

        pthread_mutex_lock(&cb.mutex);
        for (int i = 0; i < count; i++) {
            SensorData data = cb.buffer[cb.tail];
            cb.tail = (cb.tail + 1) % BUFFER_SIZE;
            fprintf(file, "%" PRIu32 ",%" PRIu16 ",%.2f,%.2f\n", data.timestamp, data.co2, data.temperature, data.humidity);
        }
        pthread_mutex_unlock(&cb.mutex);

        fclose(file);
    }

    return NULL;
}

int main() {
    signal(SIGINT, handle_signal);

    if (mkdir(LOG_DIR, 0755) && errno != EEXIST) {
        log_error("Failed to create log directory");
        return EXIT_FAILURE;
    }

    int i2c_fd = open("/dev/i2c-" PRIu8, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_I2C_ADDR) < 0) {
        log_error("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    pthread_mutex_init(&cb.mutex, NULL);

    if (pthread_create(&logger_thread, NULL, logger, NULL) != 0) {
        log_error("Failed to create logger thread");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        SensorData data;
        if (read_sensor_data(i2c_fd, &data) != 0) {
            log_error("Failed to read sensor data");
        }
    }

    pthread_join(logger_thread, NULL);

    pthread_mutex_destroy(&cb.mutex);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

