#define SDP810_CMD_READ 0x01
#define SDP810_DATA_LENGTH 9

volatile sig_atomic_t stop = 0;

void handle_sigint(int sig) {
    stop = 1;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int validate_crc8(const uint8_t *data, size_t length) {
    if (length < 3) return 0;
    uint8_t crc = calculate_crc8(data, length - 1);
    return crc == data[length - 1];
}

int read_sdp810(int fd, uint16_t *pressure, int16_t *temperature, uint16_t *scale_factor) {
    uint8_t buffer[SDP810_DATA_LENGTH];
    int ret;

    // Trigger measurement
    ret = write(fd, &SDP810_CMD_MEASURE, 1);
    if (ret != 1) {
        perror("Failed to write measurement command");
        return -1;
    }

    // Wait for measurement to complete
    usleep(45000);

    // Read data
    ret = read(fd, buffer, SDP810_DATA_LENGTH);
    if (ret != SDP810_DATA_LENGTH) {
        perror("Failed to read data");
        return -1;
    }

    // Validate CRCs
    if (!validate_crc8(buffer, 3)) {
        fprintf(stderr, "CRC error in pressure data\n");
        return -1;
    }
    if (!validate_crc8(buffer + 3, 3)) {
        fprintf(stderr, "CRC error in temperature data\n");
        return -1;
    }
    if (!validate_crc8(buffer + 6, 3)) {
        fprintf(stderr, "CRC error in scale factor data\n");
        return -1;
    }

    // Parse data
    *pressure = (buffer[0] << 8) | buffer[1];
    *temperature = (buffer[3] << 8) | buffer[4];
    *scale_factor = (buffer[6] << 8) | buffer[7];

    return 0;
}

int main() {
    int i2c_fd;
    FILE *log_file;
    struct timespec ts;
    uint16_t pressure;
    int16_t temperature;
    uint16_t scale_factor;

    // Install SIGINT handler
    signal(SIGINT, handle_sigint);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("sdp810_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Log CSV header
    fprintf(log_file, "timestamp,pressure_Pa,temperature_C\n");

    while (!stop) {
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[64];
        snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

        if (read_sdp810(i2c_fd, &pressure, &temperature, &scale_factor) == 0) {
            fprintf(log_file, "%s,%u,%d\n", timestamp, pressure, temperature);
            fflush(log_file);
        }

        // Sleep for the remainder of the second
        struct timespec sleep_time = {1, 0};
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += sleep_time.tv_sec;
        ts.tv_nsec += sleep_time.tv_nsec;
        if (ts.tv_nsec >= 1000000000) {
            ts.tv_sec++;
            ts.tv_nsec -= 1000000000;
        }
        nanosleep(&ts, NULL);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

