#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define ICP10110_ADDR 0x28
#define ICP10110_PRESSURE_REG 0x00
#define ICP10110_TEMPERATURE_REG 0x01
#define SAMPLE_INTERVAL 5
#define READ_DELAY 0.01

volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int sig) {
    stop_flag = 1;
}

int open_i2c_device(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

int read_sensor(int fd, uint8_t reg, int *value) {
    uint8_t buffer[2];
    buffer[0] = reg;

    if (write(fd, buffer, 1) != 1) {
        perror("Failed to write to I2C bus");
        return -1;
    }

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from I2C bus");
        return -1;
    }

    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

void get_iso8601_timestamp(char *buffer, size_t size) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    strftime(buffer, size, "%Y-%m-%dT%H:%M:%SZ", tm_info);
}

int main() {
    signal(SIGINT, handle_sigint);

    int i2c_fd = open_i2c_device(I2C_BUS, ICP10110_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    FILE *file = fopen("environmental_data.txt", "a");
    if (!file) {
        perror("Failed to open file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        int pressure = 0, temperature = 0;
        char timestamp[20];

        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        if (read_sensor(i2c_fd, ICP10110_PRESSURE_REG, &pressure) == 0 &&
            read_sensor(i2c_fd, ICP10110_TEMPERATURE_REG, &temperature) == 0) {
            fprintf(file, "%s Pressure: %d, Temperature: %d\n", timestamp, pressure, temperature);
            fflush(file);
            printf("%s Pressure: %d, Temperature: %d\n", timestamp, pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        usleep(READ_DELAY * 1000000);
        sleep(SAMPLE_INTERVAL);
    }

    fclose(file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

