#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x77
#define GPIO_LED 17
#define DELAY_MS 20
#define POLL_INTERVAL 1000
#define NORMAL_BLINK_ON_MS 500
#define NORMAL_BLINK_OFF_MS 500
#define WARNING_BLINK_ON_MS 100
#define WARNING_BLINK_OFF_MS 100
#define PRESSURE_THRESHOLD 95000

static int i2c_fd = -1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

int calculate_crc(uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
    }
    return crc;
}

int read_sensor(uint8_t *buffer) {
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Failed to read from I2C device");
        return -1;
    }

    uint8_t crc = calculate_crc(buffer, 4);
    if (crc != buffer[4] || crc != buffer[5]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    return 0;
}

void blink_led(int on_time, int off_time) {
    gpiod_line_set_value(line, 1);
    usleep(on_time * 1000);
    gpiod_line_set_value(line, 0);
    usleep(off_time * 1000);
}

int main() {
    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "pressure_led", 0)) {
        perror("Failed to request GPIO line");
