#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x33
#define OBJECT_TEMP_REGISTER 0x07
#define FAN_GPIO 18
#define ON_TEMP 30.0
#define OFF_TEMP 28.0
#define RETRY_LIMIT 3
#define RETRY_DELAY 10

static volatile sig_atomic_t keep_running = 1;
static struct i2c_client *i2c_client = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *fan_line = NULL;

void handle_signal(int sig) {
    keep_running = 0;
}

double read_temperature() {
    uint16_t raw_temp;
    int retries = 0;
    int ret;

    while (retries < RETRY_LIMIT) {
        ret = i2c_smbus_read_word_data(i2c_client, OBJECT_TEMP_REGISTER);
        if (ret >= 0) {
            raw_temp = ret;
            break;
        }
        retries++;
        usleep(RETRY_DELAY * 1000);
    }

    if (retries == RETRY_LIMIT) {
        fprintf(stderr, "Failed to read temperature after %d retries\n", RETRY_LIMIT);
        return -1;
    }

    double temp = (double)raw_temp * 0.02 - 273.15;
    return temp;
}

void control_fan(double object_temp) {
    if (object_temp > ON_TEMP) {
        gpiod_line_set_value(fan_line, 1);
    } else if (object_temp < OFF_TEMP) {
        gpiod_line_set_value(fan_line, 0);
    }
}

void log_temperature(double ambient_temp, double object_temp) {
    FILE *log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s - Ambient: %.2f°C, Object: %.2f°C\n", time_str, ambient_temp, object_temp);
    fclose(log_file);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_client = i2c_new_client(I2C_BUS, MLX90614_ADDR);
    if (!i2c_client) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        i2c_client_free(i2c_client);
        return EXIT_FAILURE;
    }

    fan_line = gpiod_chip_get_line(chip, FAN_GPIO);
    if (!fan_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        i2c_client_free(i2c_client);
        return EXIT_FAILURE;
    }

    gpiod_line_request_output(fan_line, "fan_control", 0);
    gpiod_line_set_value(fan_line, 0);

    while (keep_running) {
        double ambient_temp = read_temperature();
        if (ambient_temp < 0) {
            continue;
        }

        double object_temp = read_temperature();
        if (object_temp < 0) {
            continue;
        }

        log_temperature(ambient_temp, object_temp);
        control_fan(object_temp);

        sleep(2);
    }

    gpiod_line_set_value(fan_line, 0);
    gpiod_line_release(fan_line);
    gpiod_chip_close(chip);
    i2c_client_free(i2c_client);

    return EXIT_SUCCESS;
}

