int setup_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int read_sht40(int retries, uint8_t *data, size_t length) {
    int fd = i2cOpen(I2C_BUS, SHT40_I2C_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    for (int attempt = 0; attempt < retries; ++attempt) {
        if (i2cWriteReg8(fd, 0x24, MEASUREMENT_COMMAND) < 0) {
            fprintf(stderr, "Failed to write measurement command: %s\n", strerror(errno));
            i2cClose(fd);
            return -1;
        }

        usleep(10000); // Wait at least 10 ms

        if (i2cRead(fd, data, length) != length) {
            fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
            i2cClose(fd);
            continue;
        }

        i2cClose(fd);
        return 0;
    }

    i2cClose(fd);
    return -1;
}

void *http_server(void *arg) {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        pthread_exit(NULL);
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        pthread_exit(NULL);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(HTTP_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        pthread_exit(NULL);
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        pthread_exit(NULL);
    }

    while (!stop) {
