            "<p>Temperature: %.2f °C</p>"
            "<p>Humidity: %.2f %%</p>"
            "</body></html>";

        char buffer[256];
        snprintf(buffer, sizeof(buffer), response, temperature, humidity);

        send(new_socket, buffer, strlen(buffer), 0);
        close(new_socket);
    }

    close(server_fd);
    pthread_exit(NULL);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (setup_i2c() != 0) {
        return EXIT_FAILURE;
    }

    pthread_t server_thread;
    if (pthread_create(&server_thread, NULL, http_server, NULL) != 0) {
        fprintf(stderr, "Failed to create HTTP server thread: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

