            int16_t raw_humidity = (data[3] << 8) | data[4];

            temperature = -45 + 175 * (raw_temperature / 65535.0);
            humidity = 100 * (raw_humidity / 65535.0);

            if (humidity < 0) humidity = 0;
            if (humidity > 100) humidity = 100;
        } else {
            fprintf(stderr, "Failed to read from SHT40 sensor\n");
        }

        usleep(100000); // 100 ms delay between readings
    }

    pthread_join(server_thread, NULL);
    gpioTerminate();
    return EXIT_SUCCESS;
}

