#define MEASUREMENT_RESULT 0x01
#define MAX_RETRIES 3
#define TIMEOUT_MS 500
#define POLL_INTERVAL_MS 10

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int sig) {
    stop_flag = 1;
}

int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    uint8_t buf[2] = {reg, 0};
    if (ioctl(fd, I2C_SLAVE, HDC2010_ADDR) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (ioctl(fd, I2C_SLAVE, HDC2010_ADDR) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }

    return 0;
}

int read_temperature_humidity(int fd, float *temperature, float *humidity) {
    uint8_t measurement_config;
    uint8_t measurement_result[2];
    int retries = 0;
    int ret;

    // Start measurement
    if (i2c_write_byte(fd, MEASUREMENT_CONFIG, 0x80) < 0) {
        return -1;
    }

    // Poll until bit 0 clears or timeout
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    do {
        if (i2c_read_byte(fd, MEASUREMENT_CONFIG, &measurement_config) < 0) {
            if (errno == EIO) {
                if (++retries > MAX_RETRIES) {
                    fprintf(stderr, "Max retries reached\n");
                    return -1;
                }
                continue;
            }
            return -1;
        }

        clock_gettime(CLOCK_MONOTONIC, &now);
        if ((now.tv_sec - start.tv_sec) * 1000 + (now.tv_nsec - start.tv_nsec) / 1000000 > TIMEOUT_MS) {
            fprintf(stderr, "Measurement timeout\n");
            return -1;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    } while (measurement_config & 0x01);

    // Read measurement result
    if (i2c_read(fd, MEASUREMENT_RESULT, measurement_result, 2) != 2) {
        perror("Failed to read measurement result");
        return -1;
    }

    // Convert to temperature and humidity
    int16_t temp_raw = (measurement_result[0] << 8) | measurement_result[1];
    *temperature = -46.85 + 175.72 * (temp_raw / 65536.0);

    if (i2c_read(fd, MEASUREMENT_RESULT, measurement_result, 2) != 2) {
        perror("Failed to read measurement result");
        return -1;
    }

    int16_t hum_raw = (measurement_result[0] << 8) | measurement_result[1];
    *humidity = -6.0 + 125.0 * (hum_raw / 65536.0);

    return 0;
}

int main() {
    int fd;
    struct sigaction sa;
    float temperature, humidity;

    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-" + std::to_string(I2C_BUS), O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        if (read_temperature_humidity(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        sleep(5);
    }

    close(fd);
    return EXIT_SUCCESS;
}

