#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <string.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x28 // Sensirion SDP800-500Pa I2C address
#define PRESSURE_CMD 0x00
#define TEMP_CMD 0x10
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int validate_crc8(const uint8_t *data, size_t length, uint8_t expected_crc) {
    return calculate_crc8(data, length) == expected_crc;
}

int main() {
    struct i2c_smbus_data data;
    struct i2c_client *client;
    struct i2c_adapter *adapter;
    int ret;

    signal(SIGINT, handle_signal);

    adapter = i2c_get_adapter(I2C_BUS);
    if (!adapter) {
        fprintf(stderr, "Failed to get I2C adapter: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    client = i2c_new_client_device(adapter, I2C_ADDRESS, NULL);
    if (!client) {
        fprintf(stderr, "Failed to create I2C client: %s\n", strerror(errno));
        i2c_free_adapter(adapter);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Read pressure
        data.read_i2c_block = (uint8_t[]){PRESSURE_CMD};
        ret = i2c_smbus_xfer(client, I2C_SMBUS_WRITE, &data);
        if (ret < 0) {
            fprintf(stderr, "I2C write error: %s\n", strerror(-ret));
            break;
        }

        usleep(45000); // Wait for measurement to complete

        data.read_i2c_block = (uint8_t[3]){0, 0, 0};
        ret = i2c_smbus_xfer(client, I2C_SMBUS_READ_I2C_BLOCK_DATA, &data);
        if (ret < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(-ret));
            break;
        }

        if (!validate_crc8(data.read_i2c_block, 2, data.read_i2c_block[2])) {
            fprintf(stderr, "Pressure CRC error\n");
            break;
        }

        uint16_t pressure = (data.read_i2c_block[0] << 8) | data.read_i2c_block[1];

        // Read temperature
        data.read_i2c_block[0] = TEMP_CMD;
        ret = i2c_smbus_xfer(client, I2C_SMBUS_WRITE, &data);
        if (ret < 0) {
            fprintf(stderr, "I2C write error: %s\n", strerror(-ret));
            break;
        }

        usleep(45000); // Wait for measurement to complete

        data.read_i2c_block[0] = 0;
        ret = i2c_smbus_xfer(client, I2C_SMBUS_READ_I2C_BLOCK_DATA, &data);
        if (ret < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(-ret));
            break;
        }

        if (!validate_crc8(data.read_i2c_block + 1, 2, data.read_i2c_block[3])) {
            fprintf(stderr, "Temperature CRC error\n");
            break;
        }

        uint16_t temperature = (data.read_i2c_block[1] << 8) | data.read_i2c_block[2];

        printf("Pressure: 0x%04X, Temperature: 0x%04X\n", pressure, temperature);

        usleep(500000); // Wait for 500 ms
    }

    i2c_unregister_device(client);
    i2c_free_adapter(adapter);

    return EXIT_SUCCESS;
}

