#include <math.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_RELAY 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define CE_PIN 0
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8

typedef struct {
    double Kp, Ki, Kd;
    double setpoint;
    double integral;
    double prev_error;
    double prev_time;
} PIDController;

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

double read_temperature(int spi_fd) {
    uint8_t tx[] = {0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI transfer failed");
        return NAN;
    }

    if (rx[2] & 0x4) {
        fprintf(stderr, "Thermocouple disconnected\n");
        return NAN;
    }

    int16_t raw = (rx[1] << 8) | rx[0];
    return raw * 0.25;
}

void write_ssr(gpiod_chip *chip, double duty_cycle) {
    gpiod_line *line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return;
    }

    if (gpiod_line_request_output(line, "ssr", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_line_release(line);
        return;
