double pid_update(PIDController *pid, double current_temp, double dt) {
    double error = pid->setpoint - current_temp;
    pid->integral += error * dt;
    double derivative = (error - pid->prev_error) / dt;
    double output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;
    pid->prev_error = error;
    return fmax(0.0, fmin(1.0, output));
}

void load_profile(const char *filename, double **times, double **temps, size_t *count) {
