    double *profile_temps = NULL;
    size_t profile_count = 0;
    load_profile(PROFILE_FILE, &profile_times, &profile_temps, &profile_count);

    PIDController pid = { .Kp = 1.0, .Ki = 0.1, .Kd = 0.01, .setpoint = 0.0, .integral = 0.0, .prev_error = 0.0, .prev_time = 0.0 };

    double last_time = 0.0;
    size_t profile_index = 0;

    while (keep_running && profile_index < profile_count) {
        double current_time = (double)clock() / CLOCKS_PER_SEC;
        double dt = current_time - last_time;
        last_time = current_time;

        double target_temp = profile_temps[profile_index];
        if (current_time >= profile_times[profile_index]) {
            profile_index++;
            if (profile_index < profile_count) {
                target_temp = profile_temps[profile_index];
            }
