#define DS18B20_PATH "/sys/bus/w1/devices/"
#define LOG_FILE "greenhouse.log"
#define RELAY_GPIO 17
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void cleanup(int relay_fd, int pwm_fd, FILE *log_file) {
    if (relay_fd >= 0) {
        gpiod_line_set_value(relay_fd, 0);
        gpiod_line_release(relay_fd);
    }
    if (pwm_fd >= 0) {
        gpioPWMStop(pwm_fd);
        gpioClose(pwm_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

double read_temperature(const char *device_path) {
    FILE *file = fopen(device_path, "r");
    if (!file) {
        perror("Failed to open temperature file");
        return -1;
    }

    char line[256];
    double temperature = -1.0;
    while (fgets(line, sizeof(line), file)) {
        if (strncmp(line, "t=", 2) == 0) {
            char *endptr;
            temperature = strtod(line + 2, &endptr);
            if (endptr == line + 2 || *endptr != '\n') {
                fprintf(stderr, "Invalid temperature reading\n");
                temperature = -1.0;
            }
            break;
        }
    }

    fclose(file);
    return temperature;
}

void log_data(FILE *log_file, time_t timestamp, double temperature, double setpoint, double pid_output, int pwm_duty) {
    fprintf(log_file, "%ld, %.2f, %.2f, %.2f, %d\n", (long)timestamp, temperature, setpoint, pid_output, pwm_duty);
    fflush(log_file);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return EXIT_FAILURE;
    }

    double setpoint = atof(argv[1]);
    double Kp = atof(argv[2]);
    double Ki = atof(argv[3]);
    double Kd = atof(argv[4]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int relay_fd = gpiod_chip_open("/dev/gpiochip0");
    if (relay_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_line = gpiod_chip_get_line(relay_fd, RELAY_GPIO);
    if (relay_line < 0) {
        fprintf(stderr, "Failed to get relay line\n");
        gpiod_chip_close(relay_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        fprintf(stderr, "Failed to request relay line\n");
        gpiod_chip_close(relay_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pwm_fd = gpioInitialise();
    if (pwm_fd < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        gpiod_line_release(relay_line);
        gpiod_chip_close(relay_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(pwm_fd, PWM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM mode\n");
        gpioPWMStop(pwm_fd);
        gpioClose(pwm_fd);
        gpiod_line_release(relay_line);
        gpiod_chip_close(relay_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioPWMStop(pwm_fd);
        gpioClose(pwm_fd);
        gpiod_line_release(relay_line);
        gpiod_chip_close(relay_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    char *device_path = malloc(256);
    if (!device_path) {
        fprintf(stderr, "Failed to allocate memory for device path\n");
        cleanup(relay_fd, pwm_fd, log_file);
        return EXIT_FAILURE;
    }

    snprintf(device_path, 256, "%s28-00000xxxxxxx/w1_slave", DS18B20_PATH);

    double prev_error = 0.0, integral = 0.0;
    time_t last_log_time = time(NULL);

    while (keep_running) {
        double temperature = read_temperature(device_path);
        if (temperature < 0) {
            fprintf(stderr, "Failed to read temperature\n");
        } else {
            double error = setpoint - temperature;
            integral += error;
            double derivative = error - prev_error;
            double pid_output = Kp * error + Ki * integral + Kd * derivative;
            prev_error = error;

            int pwm_duty = (int)(pid_output * 100); // Scale PID output to PWM duty cycle
            if (pwm_duty < 0) pwm_duty = 0;
            if (pwm_duty > 100) pwm_duty = 100;

            gpioPWM(pwm_fd, PWM_FREQUENCY, pwm_duty);
            gpiod_line_set_value(relay_fd, pid_output > 0 ? 1 : 0);

            time_t now = time(NULL);
            if (difftime(now, last_log_time) >= 5) {
                log_data(log_file, now, temperature, setpoint, pid_output, pwm_duty);
                last_log_time = now;
            }
        }

        sleep(1);
    }

    cleanup(relay_fd, pwm_fd, log_file);
    free(device_path);
    gpioTerminate();
    return EXIT_SUCCESS;
}

