#define HUMIDITY_THRESHOLD_HIGH 60
#define HUMIDITY_THRESHOLD_LOW 55
#define POLL_INTERVAL 5
#define RETRY_DELAY 10
#define MEASURE_DELAY 80

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void cleanup_and_exit(int status) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(status);
}

void handle_signal(int sig) {
    fprintf(stderr, "Received signal %d, cleaning up and exiting.\n", sig);
    cleanup_and_exit(0);
}

int i2c_write(int fd, uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_msg msgs[1];
    uint8_t buf[256];

    buf[0] = reg;
    memcpy(buf + 1, data, len);

    msgs[0].addr = AHT20_I2C_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = len + 1;
    msgs[0].buf = buf;

    if (ioctl(fd, I2C_RDWR, &msgs) < 0) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_msg msgs[2];
    uint8_t buf[1];

    buf[0] = reg;

    msgs[0].addr = AHT20_I2C_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = buf;

    msgs[1].addr = AHT20_I2C_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = len;
    msgs[1].buf = data;

    if (ioctl(fd, I2C_RDWR, &msgs) < 0) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

int trigger_measurement() {
    uint8_t data[2] = {0x00, 0x00};
    for (int attempt = 0; attempt < 3; attempt++) {
        if (i2c_write(i2c_fd, AHT20_TRIGGER_MEASURE, data, 2) == 0) {
            return 0;
        }
        usleep(RETRY_DELAY * 1000);
    }
    return -1;
}

int read_humidity(float *humidity) {
    uint8_t data[6];
    uint8_t status;
    for (int attempt = 0; attempt < 3; attempt++) {
        if (i2c_read(i2c_fd, AHT20_READ_DATA, data, 6) == 0) {
            status = data[0];
            if ((status & 0x80) == 0 && (status & 0x40) == 0) {
                int32_t raw_humidity = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
                *humidity = (float)raw_humidity / 65536 * 100;
                return 0;
            }
        }
        usleep(RETRY_DELAY * 1000);
    }
    return -1;
}

void set_relay(int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        perror("Failed to set relay state");
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        cleanup_and_exit(1);
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup_and_exit(1);
    }

    line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        cleanup_and_exit(1);
    }

    if (gpiod_line_request_output(line, "dehumidifier_relay", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        cleanup_and_exit(1);
    }

    while (1) {
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
        } else {
            usleep(MEASURE_DELAY * 1000);
            float humidity;
            if (read_humidity(&humidity) == 0) {
                time_t now = time(NULL);
                char *timestamp = ctime(&now);
                timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
                printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);

                if (humidity > HUMIDITY_THRESHOLD_HIGH) {
                    set_relay(1);
                } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
                    set_relay(0);
                }
            } else {
                fprintf(stderr, "Failed to read humidity\n");
            }
        }
        sleep(POLL_INTERVAL);
    }

    cleanup_and_exit(0);
}

