#include <arpa/inet.h>
#include <netdb.h>

#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDRESS 0x40
#define HTU21D_MEASURE_RH 0xE5
#define HTU21D_READ_DATA 0xE7
#define POLL_INTERVAL 60

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

int read_humidity(int i2c_fd, int *humidity) {
    uint8_t cmd = HTU21D_MEASURE_RH;
    if (write(i2c_fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "Failed to write command to HTU21D: %s", strerror(errno));
        return -1;
    }

    usleep(10000); // Wait for measurement

    uint8_t data[3];
    if (read(i2c_fd, data, 3) != 3) {
        syslog(LOG_ERR, "Failed to read data from HTU21D: %s", strerror(errno));
        return -1;
    }

    int raw = (data[0] << 8) | data[1];
    if (raw & 0x8000) {
        syslog(LOG_ERR, "CRC error in HTU21D data");
        return -1;
    }

    *humidity = (125 * raw) / 65536 - 6;
    return 0;
}

int send_http_post(const char *hostname, const char *path, int humidity) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        return -1;
    }

    struct hostent *host = gethostbyname(hostname);
    if (!host) {
        syslog(LOG_ERR, "Failed to resolve hostname: %s", hstrerror(h_errno));
        close(sock);
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80);
    memcpy(&server_addr.sin_addr, host->h_addr, host->h_length);

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Failed to connect to server: %s", strerror(errno));
        close(sock);
        return -1;
    }

    char request[256];
    snprintf(request, sizeof(request),
             "POST %s HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n"
             "\r\n"
             "{\"humidity\": %d}",
             path, hostname, strlen("{\"humidity\": ") + 5, humidity);

    if (write(sock, request, strlen(request)) < 0) {
        syslog(LOG_ERR, "Failed to send HTTP request: %s", strerror(errno));
        close(sock);
        return -1;
    }

    char response[1024];
    int bytes_read = read(sock, response, sizeof(response) - 1);
    if (bytes_read < 0) {
        syslog(LOG_ERR, "Failed to read HTTP response: %s", strerror(errno));
        close(sock);
        return -1;
    }
    response[bytes_read] = '\0';

    syslog(LOG_INFO, "HTTP response: %s", response);
    close(sock);
    return 0;
}

int main() {
    openlog("htu21d_reader", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open_i2c_device(I2C_DEVICE);
    if (i2c_fd < 0) {
        closelog();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int humidity = 0;
        if (read_humidity(i2c_fd, &humidity) == 0) {
            syslog(LOG_INFO, "Read humidity: %d%%", humidity);
            if (send_http_post("api.example.com", "/humidity", humidity) < 0) {
                syslog(LOG_ERR, "Failed to send HTTP POST");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }
        sleep(POLL_INTERVAL);
    }

    close(i2c_fd);
    closelog();
    return EXIT_SUCCESS;
}

