#define BMP280_I2C_ADDRESS 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_PRESSURE_MSB_REG 0xF7
#define BMP280_PRESSURE_LSB_REG 0xF8
#define BMP280_PRESSURE_XLSB_REG 0xF9
#define BMP280_CALIB_DATA_START 0x88
#define BMP280_CALIB_DATA_LEN 24
#define BMP280_CONVERSION_TIME 10 // ms
#define SAMPLE_INTERVAL 2 // seconds

static int i2c_fd = -1;
static volatile sig_atomic_t stop = 0;

struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib_data;

void handle_signal(int sig) {
    stop = 1;
}

int open_i2c_bus(const char *bus_name) {
    i2c_fd = open(bus_name, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int read_i2c_register(uint8_t reg, uint8_t *data, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(i2c_fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

int verify_chip_id() {
    uint8_t chip_id;
    if (read_i2c_register(BMP280_CHIP_ID_REG, &chip_id, 1) != 0) {
        return -1;
    }
    return chip_id == BMP280_CHIP_ID;
}

int read_calibration_data() {
    uint8_t calib_data_raw[BMP280_CALIB_DATA_LEN];
    if (read_i2c_register(BMP280_CALIB_DATA_START, calib_data_raw, BMP280_CALIB_DATA_LEN) != 0) {
        return -1;
    }

    calib_data.dig_T1 = (calib_data_raw[1] << 8) | calib_data_raw[0];
    calib_data.dig_T2 = (calib_data_raw[3] << 8) | calib_data_raw[2];
    calib_data.dig_T3 = (calib_data_raw[5] << 8) | calib_data_raw[4];
