#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <stdint.h>

#define TMP117_I2C_ADDR 0x48
#define AHT20_I2C_ADDR 0x38
#define I2C_BUS "/dev/i2c-1"
#define PIR_GPIO_CHIP 4
#define PIR_GPIO_LINE 17
#define LOG_FILE_PREFIX "/var/log/sensor_log_"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *bus, uint8_t addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

int read_i2c_device(int fd, uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read(fd, buf, len) == len) {
            return 0;
        }
        syslog(LOG_WARNING, "I2C read failed, attempt %d: %s", attempt + 1, strerror(errno));
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int read_temperature(int fd) {
    uint8_t buf[2];
    if (read_i2c_device(fd, buf, 2) < 0) {
        return -1;
    }
    int16_t temp_raw = (buf[0] << 8) | buf[1];
    return temp_raw / 128.0;
}

int read_humidity(int fd) {
    uint8_t buf[6];
    if (read_i2c_device(fd, buf, 6) < 0) {
        return -1;
    }
    uint32_t humidity = (buf[3] << 24) | (buf[2] << 16) | (buf[1] << 8) | buf[0];
    return (humidity >> 16) & 0xFFFF;
}

int read_motion(int chip, int line) {
    struct gpiod_line *motion_line = gpiod_line_request_by_chip_and_offset(chip, line, "motion_sensor", GPIOD_LINE_REQ_DIR_IN);
    if (!motion_line) {
        syslog(LOG_ERR, "Failed to request GPIO line: %s", strerror(errno));
        return -1;
    }

    int motion_detected = gpiod_line_get_value(motion_line);
    gpiod_line_release(motion_line);
    return motion_detected;
}

void log_data(FILE *log_file, double temperature, int humidity, int motion_detected) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, temperature, humidity, motion_detected);
    fflush(log_file);
}

void create_log_file(const char *prefix, char *filename) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(filename, sizeof(LOG_FILE_PREFIX) + 20, "%Y-%m-%d.csv", tm_info);
    strcat(filename, prefix);

    FILE *log_file = fopen(filename, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    }

    fclose(log_file);
}

int main() {
    openlog("sensor_logger", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int tmp117_fd = open_i2c_device(I2C_BUS, TMP117_I2C_ADDR);
    int aht20_fd = open_i2c_device(I2C_BUS, AHT20_I2C_ADDR);
    int chip_fd = gpiod_chip_open_by_number(PIR_GPIO_CHIP);
    if (chip_fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (tmp117_fd < 0) {
        syslog(LOG_WARNING, "TMP117 not found, continuing without temperature readings.");
    }
    if (aht20_fd < 0) {
        syslog(LOG_WARNING, "AHT20 not found, continuing without humidity readings.");
    }

    char log_filename[256];
    create_log_file(LOG_FILE_PREFIX, log_filename);
    FILE *log_file = fopen(log_filename, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    time_t last_midnight = time(NULL) - (time(NULL) % (24 * 60 * 60));
    while (keep_running) {
        time_t now = time(NULL);
        if (now >= last_midnight + (24 * 60 * 60)) {
            fclose(log_file);
            create_log_file(LOG_FILE_PREFIX, log_filename);
            log_file = fopen(log_filename, "a");
            if (!log_file) {
                syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
                exit(EXIT_FAILURE);
            }
            last_midnight = now;
        }

        double temperature = -999.0;
        int humidity = -999;
        int motion_detected = -1;

        if (tmp117_fd >= 0) {
            temperature = read_temperature(tmp117_fd);
        }
        if (aht20_fd >= 0) {
            humidity = read_humidity(aht20_fd);
        }
        motion_detected = read_motion(chip_fd, PIR_GPIO_LINE);

        log_data(log_file, temperature, humidity, motion_detected);
        sleep(1);
    }

    fclose(log_file);
    if (tmp117_fd >= 0) close(tmp117_fd);
    if (aht20_fd >= 0) close(aht20_fd);
    gpiod_chip_close(chip_fd);
    closelog();

    return 0;
}

