        motion_detected = read_motion(chip_fd, PIR_GPIO_LINE);

        log_data(log_file, temperature, humidity, motion_detected);
        sleep(1);
    }

    fclose(log_file);
    if (tmp117_fd >= 0) close(tmp117_fd);
    if (aht20_fd >= 0) close(aht20_fd);
    gpiod_chip_close(chip_fd);
    closelog();

