        gpiod_line_release(in2_line);
        gpiod_line_release(in1_line);
        gpiod_line_release(ena_line);
        gpiod_line_release(rain_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

