#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27
#define SAMPLE_INTERVAL 500000000 // 500 ms in nanoseconds

static volatile int keep_running = 1;

void handle_signal(int signum) {
    keep_running = 0;
}

int read_cpu_load(double *load) {
    FILE *fp;
    char buffer[256];
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    unsigned long long total, prev_total, total_diff, idle_diff;

    fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("Failed to open /proc/stat");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Failed to read /proc/stat");
        fclose(fp);
        return -1;
    }

    if (sscanf(buffer, "cpu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        perror("Failed to parse /proc/stat");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    total = user + nice + system + idle + iowait + irq + softirq + steal;
    unsigned long long idle_all = idle + iowait;

    static unsigned long long prev_total = 0, prev_idle_all = 0;
    total_diff = total - prev_total;
    idle_diff = idle_all - prev_idle_all;

    if (total_diff > 0) {
        *load = 100.0 * (total_diff - idle_diff) / total_diff;
    } else {
        *load = 0.0;
    }

    prev_total = total;
    prev_idle_all = idle_all;

    return 0;
}

void set_pwm_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value_range(line, value, 0, 255) < 0) {
        fprintf(stderr, "Failed to set PWM value: %s\n", strerror(errno));
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *red_line, *green_line, *blue_line;
    double prev_load = 0.0, current_load = 0.0;
    unsigned long long prev_time, current_time;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(red_line, "red_pwm", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0 ||
        gpiod_line_request_output(green_line, "green_pwm", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0 ||
        gpiod_line_request_output(blue_line, "blue_pwm", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    prev_time = current_time = gpiod_chip_get_monotonic(chip);

    while (keep_running) {
        current_time = gpiod_chip_get_monotonic(chip);
        if (current_time - prev_time >= SAMPLE_INTERVAL) {
            if (read_cpu_load(&current_load) < 0) {
                fprintf(stderr, "Failed to read CPU load\n");
                break;
            }

            int red_value = (int)(255.0 * current_load / 100.0);
            int green_value = (int)(255.0 * (1.0 - current_load / 100.0));
            int blue_value = 0;

            if (current_load > 50.0) {
                green_value = (int)(255.0 * (1.0 - (current_load - 50.0) / 50.0));
                red_value = 255;
            }

            set_pwm_value(red_line, 255 - red_value);
            set_pwm_value(green_line, 255 - green_value);
            set_pwm_value(blue_line, 255 - blue_value);

            prev_load = current_load;
            prev_time = current_time;
        }

        usleep(10000); // Sleep for 10 ms to prevent busy-waiting
    }

    // Turn off the LED on exit
    set_pwm_value(red_line, 255);
    set_pwm_value(green_line, 255);
    set_pwm_value(blue_line, 255);

    gpiod_line_release(red_line);
    gpiod_line_release(green_line);
    gpiod_line_release(blue_line);
    gpiod_chip_close(chip);

    return 0;
}

