#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define BUFFER_SIZE 20

typedef struct {
    time_t timestamp;
    double temperature;
    int duty_cycle;
} DataEntry;

DataEntry buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t stop = 0;

void handle_sigint(int sig) {
    stop = 1;
}

double read_temperature() {
    uint8_t tx[] = {0x0};
    uint8_t rx[3] = {0};
    double temperature = 0.0;

    if (gpioSPIDataRW(SPI_CHANNEL, tx, 1, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    int16_t raw = (rx[0] << 8) | rx[1];
    if (raw & 0x4) {
        fprintf(stderr, "MAX31855 fault detected\n");
        return -1;
    }

    temperature = raw * 0.0078125;
    return temperature;
}

int compute_duty_cycle(double temperature) {
    if (temperature < 25.0) {
        return 0;
    } else if (temperature < 40.0) {
        return (int)((temperature - 25.0) * (50.0 / 15.0));
    } else if (temperature < 60.0) {
        return 50 + (int)((temperature - 40.0) * (150.0 / 20.0));
    } else {
        return 200;
    }
}

void store_data(double temperature, int duty_cycle) {
    buffer[buffer_index].timestamp = time(NULL);
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

void print_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Timestamp: %ld, Temperature: %.2f°C, Duty Cycle: %d%%\n",
               buffer[i].timestamp, buffer[i].temperature, buffer[i].duty_cycle);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWMfrequency(PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (!stop) {
        double temperature = read_temperature();
        if (temperature < 0) {
            continue;
        }

        int duty_cycle = compute_duty_cycle(temperature);
        gpioPWMrange(PWM_PIN, PWM_RANGE);
        gpioPWM(PWM_PIN, duty_cycle);

        store_data(temperature, duty_cycle);
        sleep(1);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();

    print_buffer();
    return EXIT_SUCCESS;
}

