#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_REG_CALIB 0xAA
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_RESULT 0xF6
#define BMP180_OSS_3 0x08
#define GPIO_PIN 2

static int i2c_fd = -1;
static int log_fd = -1;
static int logging_enabled = 0;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int sig) {
    cleanup();
    exit(0);
}

int read_i2c_byte(int reg) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    unsigned char data;
    if (read(i2c_fd, &data, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return data;
}

int read_i2c_word(int reg) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    unsigned char data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

int read_calibration_data(int *ac1, int *ac2, int *ac3, unsigned short *ac4, unsigned short *ac5, unsigned short *ac6, int *b1, int *b2, int *mb, int *mc, int *md) {
    *ac1 = read_i2c_word(BMP180_REG_CALIB);
    *ac2 = read_i2c_word(BMP180_REG_CALIB + 2);
    *ac3 = read_i2c_word(BMP180_REG_CALIB + 4);
    *ac4 = read_i2c_word(BMP180_REG_CALIB + 6);
    *ac5 = read_i2c_word(BMP180_REG_CALIB + 8);
    *ac6 = read_i2c_word(BMP180_REG_CALIB + 10);
    *b1 = read_i2c_word(BMP180_REG_CALIB + 12);
    *b2 = read_i2c_word(BMP180_REG_CALIB + 14);
    *mb = read_i2c_word(BMP180_REG_CALIB + 16);
    *mc = read_i2c_word(BMP180_REG_CALIB + 18);
    *md = read_i2c_word(BMP180_REG_CALIB + 20);

    if (*ac1 == -1 || *ac2 == -1 || *ac3 == -1 || *ac4 == -1 || *ac5 == -1 || *ac6 == -1 || *b1 == -1 || *b2 == -1 || *mb == -1 || *mc == -1 || *md == -1) {
        return -1;
    }
    return 0;
}

int read_temperature(int *temperature) {
    write_i2c_byte(BMP180_REG_CONTROL, BMP180_OSS_3);
    usleep(5000); // Wait for conversion

    int ut = read_i2c_word(BMP180_REG_RESULT);
    int x1 = ((ut - (int)ac6) * (int)ac5) >> 15;
    int x2 = ((int)mc << 11) / (x1 + (int)md);
    int b5 = x1 + x2;
    *temperature = (b5 + 8) >> 4;

    return 0;
}

int read_pressure(int *pressure) {
    write_i2c_byte(BMP180_REG_CONTROL, BMP180_OSS_3 + 0x40);
    usleep(5000); // Wait for conversion

    int up = read_i2c_word(BMP180_REG_RESULT);
    int b6 = b5 - 4000;
    int x1 = (b2 * (b6 * b6 >> 12)) >> 11;
    int x2 = ac2 * b6 >> 11;
    int x3 = x1 + x2;
    int b3 = (((((int)ac1 * 4 + x3) << oss) + 2) >> 2);
    x1 = ac3 * b6 >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    unsigned int b4 = (ac4 * (unsigned int)(x3 + 32768)) >> 15;
    unsigned int b7 = ((unsigned int)up - b3) * (50000 >> oss);
    *pressure = b7 < 0x80000000 ? (b7 * 2) / b4 : (b7 / b4) * 2;
    x1 = (*pressure >> 8) * (*pressure >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * *pressure) >> 16;
    *pressure = *pressure + ((x1 + x2 + 3791) >> 4);

    return 0;
}

void toggle_logging() {
    logging_enabled = !logging_enabled;
    if (logging_enabled) {
        log_fd = open("altitude_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_fd < 0) {
            perror("Failed to open log file");
            logging_enabled = 0;
        }
    } else {
        if (log_fd >= 0) {
            close(log_fd);
            log_fd = -1;
        }
    }
}

void log_data(int temperature, int pressure) {
    if (log_fd < 0) return;

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    char log_entry[100];
    snprintf(log_entry, sizeof(log_entry), "%s,%.2f,%.2f\n", timestamp, temperature / 16.0, pressure / 256.0);

    if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
        perror("Failed to write to log file");
        logging_enabled = 0;
        close(log_fd);
        log_fd = -1;
    }
}

int main() {
    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "BMP180_INT", GPIOD_LINE_REQ_EV_FALLING | GPIOD_LINE_REQ_DEBOUNCE) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_event_wait(line) < 0) {
        perror("Failed to wait for GPIO event");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_release(line);
    line = NULL;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ac1, ac2, ac3, ac4, ac5, ac6, b1, b2, mb, mc, md;
    if (read_calibration_data(&ac1, &ac2, &ac3, &ac4, &ac5, &ac6, &b1, &b2, &mb, &mc, &md) < 0) {
        perror("Failed to read calibration data");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        if (gpiod_line_event_wait(line) == 0) {
            toggle_logging();
        }

        if (logging_enabled) {
            int temperature, pressure;
            if (read_temperature(&temperature) == 0 && read_pressure(&pressure) == 0) {
                log_data(temperature, pressure);
            }
        }

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

