#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CE_GPIO 8
#define SPI_SPEED 1000000
#define LOG_FILE "rtd_log.csv"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, CE_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "max31865_ce", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

int setup_spi(int *fd) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));

    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;
    tr.cs_change = 0;
    tr.len = 4;
    tr.tx_buf = (unsigned long)malloc(tr.len);
    tr.rx_buf = (unsigned long)malloc(tr.len);

    if (!tr.tx_buf || !tr.rx_buf) {
        perror("Failed to allocate SPI buffers");
        return -1;
    }

    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open SPI device");
        free(tr.tx_buf);
        free(tr.rx_buf);
        return -1;
    }

    return 0;
}

void cleanup(int *fd, int gpio_fd) {
    if (*fd >= 0) {
        close(*fd);
    }
    if (gpio_fd >= 0) {
        gpiod_chip_close(gpio_fd);
    }
    free(tr.tx_buf);
    free(tr.rx_buf);
}

int read_temperature(int fd, double *temperature) {
    uint8_t tx[] = {0x0, 0x0, 0x0, 0x0};
    uint8_t rx[4];
    int ret;

    // Select the device
    gpiod_line_request_output(gpiod_chip_get_line(gpiod_chip_open_by_name("gpiochip0"), CE_GPIO), "max31865_ce", 0);
    gpiod_line_set_value(gpiod_chip_get_line(gpiod_chip_open_by_name("gpiochip0"), CE_GPIO), 0);

    // Read the data
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        perror("SPI transaction failed");
        return -1;
    }

    // Deselect the device
    gpiod_line_set_value(gpiod_chip_get_line(gpiod_chip_open_by_name("gpiochip0"), CE_GPIO), 1);

    // Check fault status
    if (rx[3] & 0x1) {
        fprintf(stderr, "Fault detected: %02x\n", rx[3]);
        return -1;
    }

    // Convert to temperature using Callendar-Van Dusen equation
    int32_t raw = ((int32_t)rx[0] << 16) | ((int32_t)rx[1] << 8) | rx[2];
    *temperature = -242.02 + 2.2228 * raw * 0.0078125;

    return 0;
}

void log_temperature(double temperature) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(file, "%s, %.2f\n", timestamp, temperature);
    fclose(file);
}

int main() {
    int spi_fd = -1;
    int gpio_fd = -1;
    double temperature;
    struct sigaction sa;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (setup_spi(&spi_fd) < 0) {
        cleanup(&spi_fd, gpio_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file for writing");
        cleanup(&spi_fd, gpio_fd);
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,Temperature\n");
    fclose(log_file);

    while (keep_running) {
        if (read_temperature(spi_fd, &temperature) == 0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Error reading temperature\n");
        }
        sleep(5);
    }

    cleanup(&spi_fd, gpio_fd);
    return EXIT_SUCCESS;
}

