#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>

#define BME280_I2C_ADDR 0x76
#define BME280_CHIP_ID_REG 0xD0
#define BME280_CHIP_ID 0x60
#define BME280_TEMP_PRESS_CALIB_DATA_START 0x88
#define BME280_HUMIDITY_CALIB_DATA_START 0xA1
#define BME280_CTRL_HUMIDITY_REG 0xF2
#define BME280_CTRL_MEAS_REG 0xF4
#define BME280_CONFIG_REG 0xF5
#define BME280_PRESSURE_MSB_REG 0xF7
#define BME280_TEMP_MSB_REG 0xFA
#define BME280_HUMIDITY_MSB_REG 0xFD

#define BME280_OSR_PRESS 1
#define BME280_OSR_TEMP 1
#define BME280_OSR_HUMIDITY 1

#define BME280_MODE_NORMAL 1

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int read_i2c_byte(int file, uint8_t reg) {
    if (ioctl(file, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(file, &reg, 1) != 1) {
        perror("Failed to write to the i2c bus");
        return -1;
    }

    uint8_t data;
    if (read(file, &data, 1) != 1) {
        perror("Failed to read from the i2c bus");
        return -1;
    }

    return data;
}

int read_i2c_bytes(int file, uint8_t reg, uint8_t *data, uint8_t length) {
    if (ioctl(file, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(file, &reg, 1) != 1) {
        perror("Failed to write to the i2c bus");
        return -1;
    }

    if (read(file, data, length) != length) {
        perror("Failed to read from the i2c bus");
        return -1;
    }

    return 0;
}

int write_i2c_byte(int file, uint8_t reg, uint8_t value) {
    if (ioctl(file, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    uint8_t buffer[2] = {reg, value};
    if (write(file, buffer, 2) != 2) {
        perror("Failed to write to the i2c bus");
        return -1;
    }

    return 0;
}

int init_bme280(int file) {
    uint8_t chip_id = read_i2c_byte(file, BME280_CHIP_ID_REG);
    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "BME280 chip ID mismatch: expected 0x%02X, got 0x%02X\n", BME280_CHIP_ID, chip_id);
        return -1;
    }

    // Read calibration data
    uint8_t calib_data[26];
    if (read_i2c_bytes(file, BME280_TEMP_PRESS_CALIB_DATA_START, calib_data, 24) != 0) {
        return -1;
    }
    if (read_i2c_bytes(file, BME280_HUMIDITY_CALIB_DATA_START, &calib_data[24], 7) != 0) {
        return -1;
    }

    // Set control registers
    uint8_t ctrl_hum = BME280_OSR_HUMIDITY << 5;
    if (write_i2c_byte(file, BME280_CTRL_HUMIDITY_REG, ctrl_hum) != 0) {
        return -1;
    }

    uint8_t ctrl_meas = (BME280_OSR_TEMP << 5) | (BME280_OSR_PRESS << 2) | BME280_MODE_NORMAL;
    if (write_i2c_byte(file, BME280_CTRL_MEAS_REG, ctrl_meas) != 0) {
        return -1;
    }

    uint8_t config = 0;
    if (write_i2c_byte(file, BME280_CONFIG_REG, config) != 0) {
        return -1;
    }

    return 0;
}

void log_data(FILE *log_file, double temperature, double humidity, double pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, humidity, pressure);
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if (init_bme280(file) != 0) {
        close(file);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("bme280_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(file);
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint8_t data[8];
        if (read_i2c_bytes(file, BME280_PRESSURE_MSB_REG, data, 8) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
