static int i2c_fd = -1;

void handle_sigint(int sig) {
    if (gpio_alert_fd != -1) {
        gpiod_line_set_value(gpio_alert_fd, 0);
        gpiod_line_release(gpio_alert_fd);
        gpio_alert_fd = -1;
    }
    if (i2c_fd != -1) {
