    return 1013.25 + (rand() % 100 - 50) / 100.0;
}

void compute_rolling_average_and_check_alert(float current_pressure) {
    float sum = 0.0;
    int count = samples_count < BUFFER_SIZE ? samples_count : BUFFER_SIZE;
    for (int i = 0; i < count; i++) {
        sum += buffer[i].pressure;
    }
    float average = sum / count;

    if (fabs(current_pressure - average) > PRESSURE_THRESHOLD_HPA) {
        fprintf(stderr, "Alert: Pressure deviation detected!\n");
        gpiod_line_set_value(gpio_alert_fd, 1);
    }
}

void timer_callback(int gpio, unsigned level, uint32_t tick, void *user_data) {
