    buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (samples_count < BUFFER_SIZE) {
        samples_count++;
    }

    compute_rolling_average_and_check_alert(pressure);
}

