        fprintf(stderr, "bcm2835_i2c_begin failed.\n");
        bcm2835_close();
        return 1;
    }

    bcm2835_i2c_set_baudrate(100000);
    bcm2835_i2c_set_address(BMP180_I2C_ADDR);

    gpio_alert_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_alert_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        bcm2835_i2c_end();
        bcm2835_close();
        return 1;
    }

    gpio_alert_fd = gpiod_line_request_output(gpio_alert_fd, GPIO_ALERT_PIN, "alert", 0);
    if (gpio_alert_fd < 0) {
        fprintf(stderr, "Failed to request GPIO line.\n");
        gpiod_chip_close(gpio_alert_fd);
        bcm2835_i2c_end();
        bcm2835_close();
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        gpiod_line_release(gpio_alert_fd);
        gpiod_chip_close(gpio_alert_fd);
        bcm2835_i2c_end();
        bcm2835_close();
        return 1;
    }

    if (gpioSetMode(GPIO_ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode.\n");
        gpioTerminate();
        gpiod_line_release(gpio_alert_fd);
        gpiod_chip_close(gpio_alert_fd);
        bcm2835_i2c_end();
        bcm2835_close();
        return 1;
    }

    if (gpioSetAlertFuncEx(GPIO_ALERT_PIN, timer_callback, NULL, SAMPLE_INTERVAL_MS) < 0) {
        fprintf(stderr, "Failed to set alert function.\n");
        gpioTerminate();
        gpiod_line_release(gpio_alert_fd);
        gpiod_chip_close(gpio_alert_fd);
        bcm2835_i2c_end();
        bcm2835_close();
        return 1;
    }

    while (1) {
        pause(); // Wait for signals
    }

    handle_sigint(0); // Ensure resources are released on exit
    return 0;
}

