int open_i2c_device(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_i2c_block_data(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

int read_calibration_data(int fd, int16_t *cal_data) {
    uint8_t buf[2];
    for (int i = 0; i < 6; i++) {
        if (read_i2c_block_data(fd, BMP180_REG_CAL_AC1 + 2 * i, buf, 2) != 0) {
            return -1;
        }
        cal_data[i] = (buf[0] << 8) | buf[1];
    }

    for (int i = 0; i < 3; i++) {
        if (read_i2c_block_data(fd, BMP180_REG_CAL_B1 + 2 * i, buf, 2) != 0) {
            return -1;
        }
        cal_data[i + 6] = (buf[0] << 8) | buf[1];
    }

    return 0;
}

int read_temperature(int fd, int16_t *temperature) {
    if (write(fd, &BMP180_CMD_TEMPERATURE, 1) != 1) {
        perror("Failed to write temperature command");
        return -1;
    }

    usleep(5 * 1000); // Wait for conversion

    uint8_t buf[2];
    if (read_i2c_block_data(fd, BMP180_REG_RESULT, buf, 2) != 0) {
        return -1;
    }

    *temperature = (buf[0] << 8) | buf[1];
    return 0;
}

int read_pressure(int fd, int16_t *pressure) {
    if (write(fd, &BMP180_CMD_PRESSURE_0, 1) != 1) {
        perror("Failed to write pressure command");
        return -1;
    }

    usleep(8 * 1000); // Wait for conversion

    uint8_t buf[3];
    if (read_i2c_block_data(fd, BMP180_REG_RESULT, buf, 3) != 0) {
        return -1;
    }

    *pressure = (buf[0] << 16) | (buf[1] << 8) | buf[2];
    return 0;
}

void calculate_bmp180(int16_t *cal_data, int16_t temperature, int16_t pressure, float *temp_c, float *pressure_pa) {
    int32_t x1, x2, b5, b6, x3, b3, p;
    int32_t b1 = cal_data[6];
    int32_t b2 = cal_data[7];
    int32_t mb = cal_data[8];
    int32_t mc = cal_data[9];
    int32_t md = cal_data[10];

    x1 = ((int32_t)temperature - (int32_t)cal_data[5]) * (int32_t)cal_data[2] >> 11;
    x2 = ((int32_t)cal_data[4] << 16) / (x1 + (int32_t)cal_data[3]);
    b5 = x1 + x2;

    *temp_c = ((b5 + 8) >> 4) / 10.0;

    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6 >> 12)) >> 11;
    x2 = (cal_data[1] * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((int32_t)cal_data[0] * 4 + x3) << BMP180_OVERSAMPLING_0) + 2) >> 2);

    x1 = (cal_data[9] * b6 * b6) >> 13;
    x2 = (cal_data[8] * b6) >> 12;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = (cal_data[7] << BMP180_OVERSAMPLING_0) + (uint32_t)x3;
    uint32_t b7 = ((uint32_t)pressure - b3) * (50000 >> BMP180_OVERSAMPLING_0);

