void handle_signal(int signum) {
    stop_flag = 1;
}

int init_pwm() {
    pwm_chip_fd = gpiod_chip_open_by_name(PWM_CHIP);
    if (pwm_chip_fd < 0) {
        fprintf(stderr, "Failed to open PWM chip: %s\n", strerror(errno));
        return -1;
    }

    pwm_line = gpiod_chip_get_line(pwm_chip_fd, PWM_LINE);
    if (!pwm_line) {
        fprintf(stderr, "Failed to get PWM line: %s\n", strerror(errno));
        gpiod_chip_close(pwm_chip_fd);
        return -1;
    }

    if (gpiod_line_request(pwm_line, "fan_control", GPIOD_LINE_REQUEST_DIRECTIONS_OUT) < 0) {
        fprintf(stderr, "Failed to request PWM line: %s\n", strerror(errno));
        gpiod_chip_close(pwm_chip_fd);
        return -1;
    }

    if (gpiod_line_set_flags(pwm_line, GPIOD_LINE_FLAG_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to set PWM line flags: %s\n", strerror(errno));
        gpiod_chip_close(pwm_chip_fd);
        return -1;
    }

    if (gpiod_line_set_range(pwm_line, PWM_RANGE)) {
        fprintf(stderr, "Failed to set PWM range: %s\n", strerror(errno));
        gpiod_chip_close(pwm_chip_fd);
        return -1;
    }

    if (gpiod_line_set_period(pwm_line, 1000000000 / PWM_FREQUENCY)) {
        fprintf(stderr, "Failed to set PWM frequency: %s\n", strerror(errno));
        gpiod_chip_close(pwm_chip_fd);
        return -1;
    }

    return 0;
}

void cleanup() {
    if (pwm_chip_fd >= 0) {
        gpiod_line_release(pwm_line);
        gpiod_chip_close(pwm_chip_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
}

int read_temperature() {
    FILE *file = fopen(TEMP_FILE, "r");
    if (!file) {
        fprintf(stderr, "Failed to open temperature file: %s\n", strerror(errno));
        return -1;
    }

    int temp;
    if (fscanf(file, "%d", &temp) != 1) {
        fprintf(stderr, "Failed to read temperature\n");
        fclose(file);
        return -1;
    }

    fclose(file);
    return temp;
}

int calculate_duty_cycle(int temp) {
    if (temp < TEMP_MIN) return 0;
    if (temp > TEMP_MAX) return PWM_RANGE;

    return (temp - TEMP_MIN) * PWM_RANGE / (TEMP_MAX - TEMP_MIN);
}

void log_status(int temp, int duty_cycle) {
    if (log_fd < 0) {
        log_fd = open("fan_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_fd < 0) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return;
        }
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    dprintf(log_fd, "%s - Temperature: %d°C, Duty Cycle: %d\n", timestamp, temp / 1000, duty_cycle);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_pwm() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        int temp = read_temperature();
        if (temp < 0) {
            fprintf(stderr, "Error reading temperature, retrying...\n");
            sleep(1);
            continue;
        }

        int duty_cycle = calculate_duty_cycle(temp);
        gpiod_line_set_value(pwm_line, duty_cycle);

        static int last_log_time = 0;
        int current_time = time(NULL);
        if (current_time - last_log_time >= LOG_INTERVAL) {
            log_status(temp, duty_cycle);
            last_log_time = current_time;
        }

        usleep(100000); // Sleep for 100ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

