#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define LM75_ADDR 0x48
#define GPIO_LED 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0

static int i2c_fd = -1;
static int gpio_fd = -1;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float buffer[BUFFER_SIZE];
static int buffer_index = 0;
static float running_average = 0.0;
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

void log_error(const char *message) {
    fprintf(stderr, "%s: %s\n", message, strerror(errno));
}

void init_gpio() {
    gpio_chip *chip;
    gpio_line_request_flags_t request_flags = GPIO_LINE_REQ_DIR_OUT;
    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        log_error("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_get_by_fd(gpio_fd);
    if (!chip) {
        log_error("Failed to get GPIO chip");
        gpiod_chip_close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    gpio_line_handle_t line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line) {
        log_error("Failed to get GPIO line");
        gpiod_chip_put(chip);
        gpiod_chip_close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request(line, "alert_led", request_flags) < 0) {
        log_error("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        gpiod_chip_close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_line_release(line);
    gpiod_chip_put(chip);
}

void deinit_gpio() {
    if (gpio_fd >= 0) {
        gpiod_chip_close(gpio_fd);
        gpio_fd = -1;
    }
}

void init_i2c() {
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        log_error("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        log_error("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        exit(EXIT_FAILURE);
    }
}

void deinit_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

float read_temperature() {
    char buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        log_error("Failed to read from I2C device");
        return -1.0;
    }

    int temp_raw = (buf[0] << 8) | buf[1];
    float temp_c = temp_raw / 256.0;
    return temp_c;
}

void *temperature_reader(void *arg) {
    while (!stop) {
        float temp = read_temperature();
        if (temp < 0) {
            log_error("Sensor read error, attempting to reinitialize");
            deinit_i2c();
            init_i2c();
            continue;
        }

        pthread_mutex_lock(&buffer_mutex);
        buffer[buffer_index] = temp;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        float sum = 0.0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            sum += buffer[i];
        }
        running_average = sum / BUFFER_SIZE;
        pthread_mutex_unlock(&buffer_mutex);

        sleep(1);
    }
    return NULL;
}

void *alert_led(void *arg) {
    while (!stop) {
        pthread_mutex_lock(&buffer_mutex);
        float temp = buffer[buffer_index];
        pthread_mutex_unlock(&buffer_mutex);

        gpio_chip *chip;
        gpio_line_handle_t line;
        gpio_fd = gpiod_chip_open("/dev/gpiochip0");
        chip = gpiod_chip_get_by_fd(gpio_fd);
        line = gpiod_chip_get_line(chip, GPIO_LED);

        if (temp > TEMP_THRESHOLD) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        gpiod_line_release(line);
        gpiod_chip_put(chip);
        sleep(1);
    }
    return NULL;
}

int main() {
    signal(SIGINT, handle_signal);

    init_gpio();
    init_i2c();

    pthread_t reader_thread, led_thread;
    if (pthread_create(&reader_thread, NULL, temperature_reader, NULL) != 0) {
        log_error("Failed to create temperature reader thread");
        deinit_gpio();
        deinit_i2c();
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&led_thread, NULL, alert_led, NULL) != 0) {
        log_error("Failed to create alert LED thread");
        pthread_cancel(reader_thread);
        pthread_join(reader_thread, NULL);
        deinit_gpio();
        deinit_i2c();
        exit(EXIT_FAILURE);
    }

    pthread_join(reader_thread, NULL);
    pthread_join(led_thread, NULL);

    deinit_gpio();
    deinit_i2c();
    pthread_mutex_destroy(&buffer_mutex);

    return 0;
}

