#define DEFAULT_KD 0.01
#define MAX_TEMP 80.0
#define CONFIG_FILE "config.json"
#define LOG_ERROR(...) fprintf(stderr, __VA_ARGS__)

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

double read_temperature(int spi_fd) {
    uint8_t tx[] = {0x0, 0x0, 0x0, 0x0};
    uint8_t rx[5];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        LOG_ERROR("SPI read failed: %s\n", strerror(errno));
        return -1;
    }

    if (rx[0] & 0x1) {
        LOG_ERROR("MAX31865 fault detected\n");
        return -1;
    }

    int16_t raw = (rx[3] << 8) | rx[2];
    double resistance = (raw * 430.0) / 32768.0;
    double temperature = -242.02 + 2.2228 * resistance - 0.0000061118 * resistance * resistance;

    return temperature;
}

void load_config(const char *filename, double *target_temp, double *kp, double *ki, double *kd) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        LOG_ERROR("Failed to open config file: %s\n", strerror(errno));
        *target_temp = DEFAULT_TARGET_TEMP;
        *kp = DEFAULT_KP;
        *ki = DEFAULT_KI;
        *kd = DEFAULT_KD;
        return;
    }

    struct json_object *parsed_json;
    struct json_object *json_target_temp, *json_kp, *json_ki, *json_kd;
    char buffer[1024];

    fread(buffer, 1, sizeof(buffer), file);
    fclose(file);

    parsed_json = json_tokener_parse(buffer);

    json_object_object_get_ex(parsed_json, "target_temp", &json_target_temp);
    json_object_object_get_ex(parsed_json, "kp", &json_kp);
    json_object_object_get_ex(parsed_json, "ki", &json_ki);
    json_object_object_get_ex(parsed_json, "kd", &json_kd);

