    *kp = json_object_get_double(json_kp) != 0 ? json_object_get_double(json_kp) : DEFAULT_KP;
    *ki = json_object_get_double(json_ki) != 0 ? json_object_get_double(json_ki) : DEFAULT_KI;
    *kd = json_object_get_double(json_kd) != 0 ? json_object_get_double(json_kd) : DEFAULT_KD;

    json_object_put(parsed_json);
}

