    if (gpioInitialise() < 0) {
        LOG_ERROR("Failed to initialize pigpio: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        LOG_ERROR("Failed to set GPIO mode: %s\n", strerror(errno));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioPWM(PWM_PIN, PWM_FREQUENCY, 0) < 0) {
        LOG_ERROR("Failed to set PWM: %s\n", strerror(errno));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup(int spi_fd) {
    gpioPWM(PWM_PIN, 0, 0);
    gpioTerminate();
    close(spi_fd);
