    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        LOG_ERROR("Failed to open SPI device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        LOG_ERROR("Failed to set SPI mode: %s\n", strerror(errno));
        cleanup(spi_fd);
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        LOG_ERROR("Failed to set SPI speed: %s\n", strerror(errno));
        cleanup(spi_fd);
        return EXIT_FAILURE;
    }

    setup_pwm();

    double integral = 0.0, previous_error = 0.0;
    struct timespec last_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &last_time);

    while (!stop) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double dt = (current_time.tv_sec - last_time.tv_sec) + (current_time.tv_nsec - last_time.tv_nsec) / 1e9;
        if (dt < 0.1) continue;

        double temperature = read_temperature(spi_fd);
        if (temperature < 0 || temperature > MAX_TEMP) {
            gpioPWM(PWM_PIN, 0, 0);
            cleanup(spi_fd);
            return EXIT_FAILURE;
        }

        double error = target_temp - temperature;
        integral += error * dt;
        double derivative = (error - previous_error) / dt;
        double output = kp * error + ki * integral + kd * derivative;

        if (output < 0) output = 0;
        if (output > PWM_RANGE) output = PWM_RANGE;

        gpioPWM(PWM_PIN, PWM_FREQUENCY, (int)output);

        previous_error = error;
        last_time = current_time;

        usleep(100000); // Sleep for 100 ms
    }

    gpioPWM(PWM_PIN, 0, 0);
    cleanup(spi_fd);
    return EXIT_SUCCESS;
