#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BMP180_ADDR 0x77
#define BMP180_REG_CALIB 0xAA
#define BMP180_REG_TEMP 0xF6
#define BMP180_REG_PRESSURE 0xF6
#define BMP180_REG_PRESSURE_MSB 0xF6
#define BMP180_REG_PRESSURE_LSB 0xF7
#define BMP180_REG_PRESSURE_XLSB 0xF8
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_CONFIG 0xF5
#define BMP180_OSR_1 0x00
#define BMP180_OSR_3 0x02
#define BMP180_OSR_4 0x03
#define BMP180_OSR_5 0x04
#define BMP180_OSR_7 0x06
#define BMP180_OSR_8 0x07

#define BMP180_CALIB_SIZE 22
#define BMP180_RETRY_LIMIT 3

typedef struct {
    int16_t ac1, ac2, ac3;
    uint16_t ac4, ac5, ac6;
    int16_t b1, b2;
    int16_t mb, mc, md;
} bmp180_calibration_t;

typedef struct {
    int fd;
    bmp180_calibration_t calib;
} bmp180_t;

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int i2c_write(int fd, uint8_t reg, uint8_t *data, size_t len) {
    uint8_t buf[256];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    return write(fd, buf, len + 1);
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    return read(fd, data, len);
}

int bmp180_init(bmp180_t *bmp) {
    uint8_t calib_data[BMP180_CALIB_SIZE];
    int retries = 0;

    bmp->fd = open(I2C_DEVICE, O_RDWR);
    if (bmp->fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    while (retries < BMP180_RETRY_LIMIT) {
        if (i2c_read(bmp->fd, BMP180_REG_CALIB, calib_data, BMP180_CALIB_SIZE) == BMP180_CALIB_SIZE) {
            bmp->calib.ac1 = (calib_data[0] << 8) | calib_data[1];
            bmp->calib.ac2 = (calib_data[2] << 8) | calib_data[3];
            bmp->calib.ac3 = (calib_data[4] << 8) | calib_data[5];
            bmp->calib.ac4 = (calib_data[6] << 8) | calib_data[7];
            bmp->calib.ac5 = (calib_data[8] << 8) | calib_data[9];
            bmp->calib.ac6 = (calib_data[10] << 8) | calib_data[11];
            bmp->calib.b1 = (calib_data[12] << 8) | calib_data[13];
            bmp->calib.b2 = (calib_data[14] << 8) | calib_data[15];
            bmp->calib.mb = (calib_data[16] << 8) | calib_data[17];
            bmp->calib.mc = (calib_data[18] << 8) | calib_data[19];
            bmp->calib.md = (calib_data[20] << 8) | calib_data[21];
            return 0;
        }
        retries++;
        usleep(100000); // Retry after 100ms
    }

    perror("Failed to read calibration data");
    close(bmp->fd);
    return -1;
}

int bmp180_read_raw(bmp180_t *bmp, int *temperature, int *pressure) {
    uint8_t data[3];
    int retries = 0;

    while (retries < BMP180_RETRY_LIMIT) {
        if (i2c_write(bmp->fd, BMP180_REG_CONTROL, &BMP180_OSR_3, 1) < 0) {
            retries++;
            usleep(100000); // Retry after 100ms
            continue;
        }

        usleep(5000); // Wait for conversion

        if (i2c_read(bmp->fd, BMP180_REG_TEMP, data, 2) == 2) {
            *temperature = (data[0] << 8) | data[1];
            break;
        }
        retries++;
        usleep(100000); // Retry after 100ms
    }

    if (retries >= BMP180_RETRY_LIMIT) {
        perror("Failed to read temperature");
        return -1;
    }

    retries = 0;
    while (retries < BMP180_RETRY_LIMIT) {
        if (i2c_write(bmp->fd, BMP180_REG_CONTROL, &BMP180_OSR_4, 1) < 0) {
            retries++;
            usleep(100000); // Retry after 100ms
            continue;
        }

        usleep(5000); // Wait for conversion

        if (i2c_read(bmp->fd, BMP180_REG_PRESSURE_MSB, data, 3) == 3) {
            *pressure = (data[0] << 16) | (data[1] << 8) | data[2];
            break;
        }
        retries++;
        usleep(100000); // Retry after 100ms
    }

    if (retries >= BMP180_RETRY_LIMIT) {
        perror("Failed to read pressure");
        return -1;
    }

    return 0;
}

int bmp180_compensate_temperature(bmp180_t *bmp, int raw_temp) {
    int32_t x1, x2;
    x1 = ((raw_temp - bmp->calib.ac6) * bmp->calib.ac5) >> 15;
    x2 = (bmp->calib.mc << 11) / (x1 + bmp->calib.md);
    return x1 + x2;
}

int bmp180_compensate_pressure(bmp180_t *bmp, int raw_pressure, int raw_temp) {
    int32_t x1, x2, x3, b3, b6, p;
    uint32_t b4, b7;

    b6 = bmp180_compensate_temperature(bmp, raw_temp) - 4000;
    x1 = (bmp->calib.b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = (bmp->calib.ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((bmp->calib.ac1 * 4 + x3) << BMP180_OSR_3) + 2) >> 2;

    x1 = (bmp->calib.ac3 * b6) >> 13;
    x2 = (bmp->calib.b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (bmp->calib.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    b7 = ((uint32_t)raw_pressure - b3) * (50000 >> BMP180_OSR_4);

    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    return p;
}

void log_breach(const char *message) {
    FILE *log_file = fopen("breach_log.txt", "a");
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fclose(log_file);
    } else {
        perror("Failed to open log file");
    }
}

int main() {
    bmp180_t bmp;
    int temperature, pressure;
    int temp_comp, pressure_comp;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (bmp180_init(&bmp) != 0) {
        fprintf(stderr, "Failed to initialize BMP180 sensor\n");
        return EXIT_FAILURE;
    }

    while (!stop) {
        if (bmp180_read_raw(&bmp, &temperature, &pressure) == 0) {
            temp_comp = bmp180_compensate_temperature(&bmp, temperature);
            pressure_comp = bmp180_compensate_pressure(&bmp, pressure, temperature);

            if (temp_comp > 30000) {
                char temp_msg[64];
                snprintf(temp_msg, sizeof(temp_msg), "Temperature breach: %d.%02d°C",
                         temp_comp / 100, temp_comp % 100);
                log_breach(temp_msg);
            }

            if (pressure_comp < 95000) {
                char pressure_msg[64];
                snprintf(pressure_msg, sizeof(pressure_msg), "Pressure breach: %d.%02d hPa",
                         pressure_comp / 100, pressure_comp % 100);
                log_breach(pressure_msg);
            }
        }

        sleep(1);
    }

    close(bmp.fd);
    return EXIT_SUCCESS;
}

