    if (pi_i2c_read(i2c_fd, BMP180_CALIBRATION_START, BMP180_CALIBRATION_SIZE, calib_data) != BMP180_CALIBRATION_SIZE) {
        fprintf(stderr, "Failed to read calibration data\n");
        exit(EXIT_FAILURE);
    }
}

double read_temperature(int16_t *calib_data) {
    uint8_t data[2];
    if (pi_i2c_write(i2c_fd, BMP180_TEMPERATURE_REGISTER, &BMP180_READ_TEMP_COMMAND, 1) != 1) {
        fprintf(stderr, "Failed to write temperature command\n");
        return -1;
    }
    usleep(4500); // Wait for conversion
    if (pi_i2c_read(i2c_fd, BMP180_TEMPERATURE_REGISTER, 2, data) != 2) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1;
    }
    int16_t raw_temp = (data[0] << 8) | data[1];
    double temp = 175.0 * raw_temp / 65536.0 - 45.0;
    return temp;
}

