    pressure = (pressure - (double)calib_data[3] * 2.0 / 2048.0) * (double)calib_data[5] / 2048.0;
    pressure = pressure + (double)calib_data[2] / 2.0;
    pressure = pressure * 4.0 + (double)calib_data[1] / 4.0;
    pressure = (pressure * (1.0 + (double)calib_data[8] * pressure / 2147483648.0 + (double)calib_data[9] * temperature / 32768.0)) * (1.0 + (double)calib_data[6] * temperature / 65536.0);
    return pressure / 256.0;
}

void timer_callback(int sig) {
    static int16_t calib_data[BMP180_CALIBRATION_SIZE / 2];
    static double last_temperature = -1.0;

    if (!running) return;

    double temperature = last_temperature;
    if (temperature == -1.0) {
        temperature = read_temperature(calib_data);
        if (temperature < 0) return;
        last_temperature = temperature;
    }

    double pressure = read_pressure(calib_data, temperature);
    if (pressure < 0) return;

    time_t now = time(NULL);
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].pressure = pressure;
    buffer[buffer_index].timestamp = now;
    buffer_index = (buffer_index + 1) % MAX_BUFFER_SIZE;

    printf("Timestamp: %ld, Temperature: %.2f°C, Pressure: %.2f hPa\n", now, temperature, pressure);

    if (temperature > TEMP_THRESHOLD) {
        gpioWrite(fan_gpio, 1);
    } else {
        gpioWrite(fan_gpio, 0);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_i2c();

    static int16_t calib_data[BMP180_CALIBRATION_SIZE / 2];
    read_calibration_data(calib_data);

    struct itimerval timer;
    timer.it_value.tv_sec = 0;
    timer.it_value.tv_usec = 500000;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_usec = 500000;
    setitimer(ITIMER_REAL, &timer, NULL);

    while (running) {
        pause(); // Wait for timer interrupt
    }

