#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_REG_CALIB 0xAA
#define BMP180_REG_PRESSURE 0xF6
#define BMP180_REG_TEMP 0xF3
#define GPIO_PIN 27
#define DEBOUNCE_TIME 200000 // 200 ms in microseconds
#define LOG_INTERVAL 2 // 2 seconds

volatile sig_atomic_t logging_enabled = 0;
volatile sig_atomic_t running = 1;

int i2c_fd;
int gpio_fd;
struct gpiod_line *gpio_line;

void handle_signal(int sig) {
    running = 0;
}

void log_pressure(double pressure) {
    FILE *file = fopen("pressure_log.txt", "a");
    if (file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    fprintf(file, "%s: %f Pa\n", ctime(&now), pressure);
    fclose(file);
}

void toggle_logging() {
    logging_enabled = !logging_enabled;
    syslog(LOG_INFO, "Logging %s", logging_enabled ? "enabled" : "disabled");
}

void gpio_callback(struct gpiod_line *line, unsigned int ev_type, unsigned int ev_value) {
    if (ev_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        toggle_logging();
    }
}

void setup_gpio() {
    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_chip_get_line(gpio_fd, GPIO_PIN);
    if (!gpio_line) {
        syslog(LOG_ERR, "Failed to get GPIO line: %s", strerror(errno));
        gpiod_chip_close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(gpio_line, "pressure_logger", GPIOD_LINE_REQ_EV_FALLING_EDGE) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line: %s", strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_event_wait(gpio_line, DEBOUNCE_TIME) < 0) {
        syslog(LOG_ERR, "Failed to wait for GPIO event: %s", strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", 1); // I2C bus 1

    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void read_calibration_data(int16_t *ac1, int16_t *ac2, int16_t *ac3, uint16_t *ac4, uint16_t *ac5, uint16_t *ac6, int16_t *b1, int16_t *b2, int16_t *mb, int16_t *mc, int16_t *md) {
    uint8_t buffer[22];
    if (write(i2c_fd, &BMP180_REG_CALIB, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C: %s", strerror(errno));
        return;
    }

    if (read(i2c_fd, buffer, 22) != 22) {
        syslog(LOG_ERR, "Failed to read calibration data: %s", strerror(errno));
        return;
    }

    *ac1 = (buffer[0] << 8) | buffer[1];
    *ac2 = (buffer[2] << 8) | buffer[3];
    *ac3 = (buffer[4] << 8) | buffer[5];
    *ac4 = (buffer[6] << 8) | buffer[7];
    *ac5 = (buffer[8] << 8) | buffer[9];
    *ac6 = (buffer[10] << 8) | buffer[11];
    *b1 = (buffer[12] << 8) | buffer[13];
    *b2 = (buffer[14] << 8) | buffer[15];
    *mb = (buffer[16] << 8) | buffer[17];
    *mc = (buffer[18] << 8) | buffer[19];
    *md = (buffer[20] << 8) | buffer[21];
}

double read_temperature(int16_t *temperature) {
    uint8_t buffer[2];
    if (write(i2c_fd, &BMP180_REG_TEMP, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C: %s", strerror(errno));
        return -1;
    }

    if (read(i2c_fd, buffer, 2) != 2) {
        syslog(LOG_ERR, "Failed to read temperature data: %s", strerror(errno));
        return -1;
    }

    uint16_t raw_temp = (buffer[0] << 8) | buffer[1];
    *temperature = (int16_t)((raw_temp - 32768) * 5) / 256;
    return (double)(*temperature) / 100.0;
}

double read_pressure(int16_t ac1, int16_t ac2, int16_t ac3, uint16_t ac4, uint16_t ac5, uint16_t ac6, int16_t b1, int16_t b2, int16_t mb, int16_t mc, int16_t md) {
    uint8_t buffer[3];
    if (write(i2c_fd, &BMP180_REG_PRESSURE, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C: %s", strerror(errno));
        return -1;
    }

    if (read(i2c_fd, buffer, 3) != 3) {
        syslog(LOG_ERR, "Failed to read pressure data: %s", strerror(errno));
        return -1;
    }

    uint32_t raw_pressure = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
    int32_t ut = read_temperature(NULL);
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    int32_t x1 = (b2 * (b6 * b6 >> 12)) >> 11;
    int32_t x2 = (ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1 * 4 + x3) << over_sampling) + 2) / 4);
    x1 = (ac3 * b6) >> 13;
