#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27
#define PWM_RANGE 255

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int setup_pwm(gpiod_chip *chip, int pin, gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, pin);
    if (!*line) {
        fprintf(stderr, "Failed to get line for GPIO%d\n", pin);
        return -1;
    }

    if (gpiod_line_request(*line, "pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0) {
        fprintf(stderr, "Failed to request line for GPIO%d\n", pin);
        gpiod_line_release(*line);
        return -1;
    }

    if (gpiod_line_set_request(*line, GPIOD_LINE_REQUEST_PWM) < 0) {
        fprintf(stderr, "Failed to set PWM request for GPIO%d\n", pin);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        return EXIT_FAILURE;
    }

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    if (setup_pwm(chip, RED_PIN, &red_line) < 0 ||
        setup_pwm(chip, GREEN_PIN, &green_line) < 0 ||
        setup_pwm(chip, BLUE_PIN, &blue_line) < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *temp_file = fopen(TEMP_FILE, "r");
    if (!temp_file) {
        fprintf(stderr, "Failed to open temperature file: %s\n", strerror(errno));
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        char buffer[64];
        if (fgets(buffer, sizeof(buffer), temp_file) == NULL) {
            if (ferror(temp_file)) {
                fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
            }
            continue;
        }

        int temp;
        if (sscanf(buffer, "%d", &temp) != 1) {
            fprintf(stderr, "Failed to parse temperature\n");
            continue;
        }

        int red = 0, green = 0, blue = 0;
        if (temp < 40000) {
            blue = PWM_RANGE;
        } else if (temp < 60000) {
            green = PWM_RANGE;
        } else {
            red = PWM_RANGE;
        }

        if (gpiod_line_set_value(red_line, PWM_RANGE - red) < 0 ||
            gpiod_line_set_value(green_line, PWM_RANGE - green) < 0 ||
            gpiod_line_set_value(blue_line, PWM_RANGE - blue) < 0) {
            fprintf(stderr, "Failed to set PWM value\n");
            break;
        }

        printf("Temperature: %d m°C, Red: %d, Green: %d, Blue: %d\n", temp, red, green, blue);
        usleep(500000); // 0.5 seconds
    }

    // Turn off all channels
    gpiod_line_set_value(red_line, PWM_RANGE);
    gpiod_line_set_value(green_line, PWM_RANGE);
    gpiod_line_set_value(blue_line, PWM_RANGE);

    gpiod_line_release(red_line);
    gpiod_line_release(green_line);
    gpiod_line_release(blue_line);
    gpiod_chip_close(chip);
    fclose(temp_file);

    return EXIT_SUCCESS;
}

