#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <curl/curl.h>
#include <time.h>

#define DHT22_GPIO 4
#define DHT22_TIMEOUT 1000000 // 1 second in nanoseconds
#define DHT22_MAX_RETRIES 3

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int read_dht22(gpiod_line *line, uint8_t *humidity, uint8_t *temperature) {
    uint8_t data[5] = {0};
    int ret;

    // Start signal: pull line low for at least 1 ms
    ret = gpiod_line_request_output(line, "dht22", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line as output: %s\n", strerror(-ret));
        return -1;
    }

    usleep(18000); // 18 ms
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set line high: %s\n", strerror(-ret));
        return -1;
    }

    usleep(20000); // 20 ms
    ret = gpiod_line_request_input(line, "dht22");
    if (ret < 0) {
        fprintf(stderr, "Failed to request line as input: %s\n", strerror(-ret));
        return -1;
    }

    // Wait for the sensor to pull the line low
    ret = gpiod_line_event_wait(line, GPIOD_LINE_EVENT_FALLING_EDGE, DHT22_TIMEOUT);
    if (ret < 0) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1;
    }

    // Read 40 bits (5 bytes)
    for (int i = 0; i < 40; i++) {
        ret = gpiod_line_event_wait(line, GPIOD_LINE_EVENT_RISING_EDGE, DHT22_TIMEOUT);
        if (ret < 0) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return -1;
        }

        ret = gpiod_line_event_wait(line, GPIOD_LINE_EVENT_FALLING_EDGE, DHT22_TIMEOUT);
        if (ret < 0) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1;
        }

        uint64_t duration = gpiod_line_event_get_duration(line);
        if (duration > 50) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Validate checksum
    uint8_t checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        fprintf(stderr, "Checksum mismatch\n");
        return -1;
    }

    *humidity = data[0];
    *temperature = data[2];

    return 0;
}

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    (void)ptr;
    (void)size;
    (void)nmemb;
    (void)userdata;
    return size * nmemb;
}

int post_data(const char *url, uint8_t humidity, uint8_t temperature) {
    CURL *curl;
    CURLcode res;
    char postfields[128];

    snprintf(postfields, sizeof(postfields), "{\"humidity\": %d, \"temperature\": %d}", humidity, temperature);

    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize CURL\n");
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, postfields);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "CURL error: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_cleanup(curl);
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpiod_chip *chip;
    gpiod_line *line;
    uint8_t humidity, temperature;
    int retries = 0;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (retries < DHT22_MAX_RETRIES && !stop) {
        if (read_dht22(line, &humidity, &temperature) == 0) {
            if (post_data("http://yourserver.com/api/humidity", humidity, temperature) == 0) {
                break;
            }
        }
        retries++;
        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (stop) {
        fprintf(stderr, "Program terminated by signal\n");
    } else if (retries == DHT22_MAX_RETRIES) {
        fprintf(stderr, "Failed to read from DHT22 sensor after %d retries\n", DHT22_MAX_RETRIES);
    }

    return EXIT_SUCCESS;
}

