        return -1;
    }

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return (data[0] << 8) | data[1];
}

