    *mc = read_i2c_word(fd, BMP180_REG_MC);
    *md = read_i2c_word(fd, BMP180_REG_MD);

    if (*ac1 == 0 || *ac2 == 0 || *ac3 == 0 || *ac4 == 0 || *ac5 == 0 || *ac6 == 0) {
