int read_dht22(gpiod_line *line, uint8_t *humidity, uint8_t *temperature) {
    uint8_t bits[5] = {0};
    uint8_t bit_idx = 0;
    uint8_t byte_idx = 0;
    uint32_t data;
    uint64_t start_time, end_time;

    // Start signal
    gpiod_line_request_args_t req = {
        .consumer = "dht22_reader",
        .type = GPIOD_LINE_REQ_DIR_OUT,
        .flags = GPIOD_LINE_REQ_DIREN | GPIOD_LINE_REQ_OPEN_DRAIN,
    };
    if (gpiod_line_request(line, &req)) {
