        return -1;
    }

    gpiod_line_set_value(line, 0);
    usleep(DHT22_START_LOW_MS * 1000);
    gpiod_line_set_value(line, 1);
    usleep(DHT22_START_HIGH_US);
    gpiod_line_release(line);

    // Wait for sensor response
    gpiod_line_request_args_t req_in = {
        .consumer = "dht22_reader",
        .type = GPIOD_LINE_REQ_DIR_IN,
        .flags = GPIOD_LINE_REQ_DIREN,
    };
    if (gpiod_line_request(line, &req_in)) {
        log_event("Failed to request line for input");
        return -1;
    }

    // Wait for the sensor to pull the line low
    start_time = gpiod_line_event_wait(line, GPIOD_LINE_EVENT_FALLING_EDGE, 200000);
    if (start_time == 0) {
        log_event("Sensor did not pull line low");
        gpiod_line_release(line);
        return -1;
    }

    // Read 40 bits
    for (int i = 0; i < 40; i++) {
        start_time = gpiod_line_event_wait(line, GPIOD_LINE_EVENT_RISING_EDGE, 100000);
        if (start_time == 0) {
            log_event("Failed to read bit");
            gpiod_line_release(line);
            return -1;
        }
        end_time = gpiod_line_event_wait(line, GPIOD_LINE_EVENT_FALLING_EDGE, 100000);
        if (end_time == 0) {
            log_event("Failed to read bit");
            gpiod_line_release(line);
            return -1;
        }
        uint32_t duration = end_time - start_time;
        if (duration > 50) {
            bits[byte_idx] |= (1 << (7 - bit_idx));
