        return -1;
    }

    int value;
    if (fscanf(file, "%d", &value) != 1) {
        perror("Failed to read from file");
        fclose(file);
        return -1;
    }

    fclose(file);
    return value;
}

int write_int_to_file(const char *file_path, int value) {
    FILE *file = fopen(file_path, "w");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    if (fprintf(file, "%d", value) < 0) {
        perror("Failed to write to file");
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int max_state = read_int_from_file(MAX_STATE_FILE);
    if (max_state < 0 || max_state < 3) {
        fprintf(stderr, "Invalid max_state: %d\n", max_state);
        return EXIT_FAILURE;
    }

    int current_fan_state = 0;
    while (keep_running) {
        int temp = read_int_from_file(TEMP_FILE);
        if (temp < 0) {
            sleep(5);
            continue;
        }

        int new_fan_state = 0;
        if (temp >= 6500) {
            new_fan_state = 3;
        } else if (temp >= 5500) {
            new_fan_state = 2;
        } else if (temp >= 4500) {
            new_fan_state = 1;
        }

        if (new_fan_state != current_fan_state) {
            if (write_int_to_file(FAN_STATE_FILE, new_fan_state) == 0) {
                char log_message[256];
                snprintf(log_message, sizeof(log_message), "Fan state changed to %d", new_fan_state);
                log_event(log_message);
                current_fan_state = new_fan_state;
            } else {
                fprintf(stderr, "Failed to change fan state\n");
            }
        }

        sleep(5);
    }

    if (write_int_to_file(FAN_STATE_FILE, 0) == 0) {
        log_event("Fan state set to 0 on shutdown");
    } else {
        fprintf(stderr, "Failed to set fan state to 0 on shutdown\n");
    }

    return EXIT_SUCCESS;
}

