#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define TARGET_TEMP 50.0
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define SPI_SPEED 500000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define LOG_FILE "heater_log.txt"

#define MAX31855_FAULT_MASK 0x7
#define MAX31855_FAULT_OPEN 0x1
#define MAX31855_FAULT_SHORT_GND 0x2
#define MAX31855_FAULT_SHORT_VCC 0x4

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

double read_temperature(int spi_fd) {
    uint8_t tx[] = {0x0};
    uint8_t rx[5];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI transfer");
        return NAN;
    }

    uint32_t raw = (rx[0] << 24) | (rx[1] << 16) | (rx[2] << 8) | rx[3];
    uint8_t fault = rx[4] & MAX31855_FAULT_MASK;

    if (fault) {
        fprintf(stderr, "MAX31855 fault: 0x%02x\n", fault);
        return NAN;
    }

    double temp = (raw >> 18) & 0x7FFF;
    if (raw & 0x200000) {
        temp -= 0x100000;
    }
    temp *= 0.25;

    return temp;
}

void log_data(double temperature, int duty_cycle, double pid_output) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log, "Temperature: %.2f°C, Duty Cycle: %d%%, PID Output: %.2f\n",
            temperature, duty_cycle, pid_output);
    fclose(log);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioPWM(18, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to initialize PWM on GPIO18\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void setup_spi(int *spi_fd) {
    *spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (*spi_fd < 0) {
