#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <syslog.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS_MUX 0x70
#define I2C_ADDRESS_SENSOR1 0x28
#define I2C_ADDRESS_SENSOR2 0x29
#define I2C_BUFFER_SIZE 3
#define MAX_RETRIES 3

static struct i2c_client *mux_client = NULL;
static struct i2c_client *sensor1_client = NULL;
static struct i2c_client *sensor2_client = NULL;

void cleanup() {
    if (mux_client) {
        i2c_unregister_device(mux_client);
    }
    if (sensor1_client) {
        i2c_unregister_device(sensor1_client);
    }
    if (sensor2_client) {
        i2c_unregister_device(sensor2_client);
    }
    syslog(LOG_INFO, "Cleaned up I2C devices and exiting.");
}

void handle_signal(int sig) {
    cleanup();
    exit(0);
}

int crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(struct i2c_client *client, uint8_t *buffer) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_smbus_read_i2c_block_data(client, 0, I2C_BUFFER_SIZE, buffer) == I2C_BUFFER_SIZE) {
            return 0;
        }
        retries++;
        syslog(LOG_WARNING, "I2C read error, retrying... (%d/%d)", retries, MAX_RETRIES);
        usleep(100000); // 100 ms
    }
    return -1;
}

void select_channel(uint8_t channel) {
    uint8_t data[2] = {channel, 0x00};
    if (i2c_smbus_write_i2c_block_data(mux_client, 0, 2, data) != 2) {
        syslog(LOG_ERR, "Failed to select I2C channel %d", channel);
        exit(EXIT_FAILURE);
    }
}

void log_flow_data(int flow1, int flow2) {
    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%d,%d\n", time_str, flow1, flow2);
    fclose(log_file);
}

int main() {
    openlog("flow_sensor", LOG_PID | LOG_CONS, LOG_USER);
