#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <gpiod.h>
#include <time.h>

#define CHANNEL_A 17
#define CHANNEL_B 18
#define LOG_FILE "encoder_log.txt"

static volatile int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line_a, *line_b;
static FILE *log_file;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_position(double position) {
    if (log_file) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(log_file, "%s - Position: %.2f degrees\n", time_str, position);
        fflush(log_file);
    }
}

void process_encoder_state(int state) {
    static int last_state = 0;
    static double position = 0.0;
    static const double step_size = 360.0 / 360.0; // 1 degree per step

    int delta = (state - last_state) & 3; // 2-bit state difference
    switch (delta) {
        case 1: // 01 -> 11
        case 2: // 10 -> 00
            position += step_size;
            break;
        case 3: // 11 -> 00
        case 0: // 00 -> 01
            position -= step_size;
            break;
    }

    position = fmod(position, 360.0);
    if (position < 0) position += 360.0;

    log_position(position);
    last_state = state;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line_a = gpiod_chip_get_line(chip, CHANNEL_A);
    line_b = gpiod_chip_get_line(chip, CHANNEL_B);
    if (!line_a || !line_b) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line_a, "encoder_a", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0 ||
        gpiod_line_request_output(line_b, "encoder_b", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_flags(line_a, GPIOD_LINE_FLAG_OPEN_DRAIN) < 0 ||
        gpiod_line_set_flags(line_b, GPIOD_LINE_FLAG_OPEN_DRAIN) < 0) {
        fprintf(stderr, "Failed to set open-drain mode\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_value(line_a, 1) < 0 || gpiod_line_set_value(line_b, 1) < 0) {
        fprintf(stderr, "Failed to set pull-up resistors\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int state = 0;
    while (keep_running) {
        int a = gpiod_line_get_value(line_a);
        int b = gpiod_line_get_value(line_b);
        int new_state = (a << 1) | b;
        if (new_state != state) {
            process_encoder_state(new_state);
            state = new_state;
        }
        usleep(1000); // 1 ms delay
    }

    fclose(log_file);
    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

