#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x48
#define GPIO_LED 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_i2c(int *fd) {
    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(*fd);
        return -1;
    }

    return 0;
}

int read_sensor(int fd, int *red, int *ir) {
    unsigned char buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from sensor");
        return -1;
    }

    *red = (buffer[0] << 8) | buffer[1];
    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from sensor");
        return -1;
    }

    *ir = (buffer[0] << 8) | buffer[1];
    return 0;
}

void log_measurement(FILE *log_file, int red, int ir) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s, %d, %d\n", timestamp, red, ir);
    fflush(log_file);
}

int main() {
    int i2c_fd;
    int red, ir;
    FILE *log_file;
    struct sigaction sa;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (setup_i2c(&i2c_fd) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("adpd144ri_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (keep_running) {
        if (read_sensor(i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            continue;
        }

        log_measurement(log_file, red, ir);

        if (ir > IR_THRESHOLD) {
            gpioWrite(GPIO_LED, 1);
        } else {
            gpioWrite(GPIO_LED, 0);
        }

        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

