#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <pthread.h>
#include <unistd.h>

#define GPIO_PIN 18
#define CHANNEL_NAME "mlx90254_rpm"

volatile int pulse_count = 0;
volatile int running = 1;
pthread_mutex_t pulse_mutex;
FILE *log_file = NULL;

void signal_handler(int signum) {
    running = 0;
}

void log_rpm(int rpm) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    pthread_mutex_lock(&pulse_mutex);
    fprintf(log_file, "%s - RPM: %.2f\n", time_str, rpm);
    fflush(log_file);
    pthread_mutex_unlock(&pulse_mutex);
}

void isr_handler_cb(struct gpiod_line *line, unsigned int events, void *user_data) {
    if (events & GPIOD_LINE_EVENT_RISING_EDGE) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event_handler *handler;
    struct gpiod_line_event event;
    int ret;

    // Initialize signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, CHANNEL_NAME, GPIOD_LINE_REQUEST_DIRECTIONS);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize log file
    log_file = fopen("rpm_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
