#define LOG_FILE "adpd144ri_log.txt"
#define SAMPLE_INTERVAL 100 // milliseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_gpio_led() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "led_control", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

void cleanup_gpio_led(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int setup_i2c() {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

void cleanup_i2c(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

int read_sensor(int fd, int *red, int *infrared) {
    unsigned char buffer[4];
    int ret;

    ret = read(fd, buffer, sizeof(buffer));
    if (ret < 0) {
        perror("Failed to read from I2C device");
        return -1;
    } else if (ret != sizeof(buffer)) {
        fprintf(stderr, "Unexpected read size: %d\n", ret);
        return -1;
    }

    *red = (buffer[0] << 8) | buffer[1];
    *infrared = (buffer[2] << 8) | buffer[3];

    return 0;
}

void log_reading(FILE *log_file, time_t timestamp, int red, int infrared) {
    fprintf(log_file, "%ld,%d,%d\n", timestamp, red, infrared);
    fflush(log_file);
}

int main() {
    int i2c_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int red, infrared;
    time_t timestamp;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (setup_gpio_led() < 0) {
        fprintf(stderr, "Failed to setup GPIO LED\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        cleanup_gpio_led(chip, NULL);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "led_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        cleanup_gpio_led(chip, line);
        return EXIT_FAILURE;
    }

    i2c_fd = setup_i2c();
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to setup I2C\n");
        cleanup_gpio_led(chip, line);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup_i2c(i2c_fd);
        cleanup_gpio_led(chip, line);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        timestamp = time(NULL);

        if (read_sensor(i2c_fd, &red, &infrared) < 0) {
            fprintf(stderr, "Error reading sensor, skipping this cycle\n");
        } else {
            log_reading(log_file, timestamp, red, infrared);

            if (infrared > INFRARED_THRESHOLD) {
                gpiod_line_set_value(line, 1);
            } else {
                gpiod_line_set_value(line, 0);
            }
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    fclose(log_file);
    cleanup_i2c(i2c_fd);
    cleanup_gpio_led(chip, line);

    return EXIT_SUCCESS;
}

