#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

#define AUDIO_GPIO 17
#define GAIN_GPIO 18
#define POLL_INTERVAL_MS 10

static volatile int keep_running = 1;
static gpiod_chip *chip;
static gpiod_line *audio_line;
static gpiod_line *gain_line;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(const char *level) {
    FILE *file = fopen("audio_log.txt", "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s %s\n", time_str, level);
    fclose(file);
}

int setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    audio_line = gpiod_chip_get_line(chip, AUDIO_GPIO);
    if (!audio_line) {
        perror("Failed to get audio line");
        gpiod_chip_close(chip);
        return -1;
    }

    gain_line = gpiod_chip_get_line(chip, GAIN_GPIO);
    if (!gain_line) {
        perror("Failed to get gain line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(audio_line, "audio_input", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        perror("Failed to request audio line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(gain_line, "gain_output", 0) < 0) {
        perror("Failed to request gain line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(gain_line, 0); // Set gain to 60 dB

    return 0;
}

void cleanup_gpio() {
    if (audio_line) {
        gpiod_line_release(audio_line);
    }
    if (gain_line) {
        gpiod_line_release(gain_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    printf("Starting audio peak detection...\n");

    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(audio_line, POLL_INTERVAL_MS);
        if (ret < 0) {
            perror("Failed to wait for line event");
            break;
        }

        if (gpiod_line_event_read(audio_line, &event) < 0) {
            perror("Failed to read line event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            log_event("LEVEL 1");
        }
    }

    cleanup_gpio();
    printf("Exiting...\n");
    return EXIT_SUCCESS;
}

