#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <syslog.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SLF3S4000B_ADDR 0x28
#define POLL_INTERVAL 1000
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_flow_sensor(int i2c_fd, uint16_t *flow_rate) {
    uint8_t buffer[3];
    int ret = i2c_smbus_read_i2c_block_data(i2c_fd, SLF3S4000B_ADDR, 2, buffer);
    if (ret < 0) {
        syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
        return -1;
    } else if (ret != 3) {
        syslog(LOG_ERR, "Unexpected I2C read length: %d", ret);
        return -1;
    }

    uint8_t crc = calculate_crc8(buffer, 2);
    if (crc != buffer[2]) {
        syslog(LOG_ERR, "CRC check failed");
        return -1;
    }

    *flow_rate = (buffer[0] << 8) | buffer[1];
    return 0;
}

void log_flow_rate(FILE *log_file, time_t timestamp, uint16_t flow_rate) {
    struct tm *tm_info = localtime(&timestamp);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%u\n", time_str, flow_rate);
    fflush(log_file);
}

