int open_i2c_device(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_i2c_register(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, data, length) != length) {
        perror("Failed to read register data");
        return -1;
    }

    return 0;
}

void log_air_quality(int tvoc, int eco2, int iaq) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s, %d, %d, %d\n", time_str, tvoc, eco2, iaq);
    fclose(file);
}

int main() {
    signal(SIGINT, handle_sigint);

    int i2c_fd = open_i2c_device(I2C_BUS, VOC_SENSOR_ADDR);
    if (i2c_fd < 0) {
        exit(EXIT_FAILURE);
    }

    FILE *file = fopen(LOG_FILE, "w");
    if (file) {
        fprintf(file, "Timestamp, TVOC (ppb), eCO2 (ppm), IAQ Index\n");
        fclose(file);
    } else {
        perror("Failed to create log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (keep_running) {
        uint8_t tvoc_data[2] = {0};
        uint8_t eco2_data[2] = {0};
        uint8_t iaq_data[2] = {0};

        if (read_i2c_register(i2c_fd, VOC_SENSOR_REG_TVOC, tvoc_data, 2) == 0 &&
            read_i2c_register(i2c_fd, VOC_SENSOR_REG_ECO2, eco2_data, 2) == 0 &&
            read_i2c_register(i2c_fd, VOC_SENSOR_REG_IAQ, iaq_data, 2) == 0) {

            int tvoc = (tvoc_data[0] << 8) | tvoc_data[1];
            int eco2 = (eco2_data[0] << 8) | eco2_data[1];
            int iaq = (iaq_data[0] << 8) | iaq_data[1];

            log_air_quality(tvoc, eco2, iaq);
        } else {
            fprintf(stderr, "Error reading from sensor, skipping log entry\n");
        }

        sleep(5);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

