#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <time.h>
#include <unistd.h>

#define GPIO_CHIP_NAME "bcm2835-gpiomem"
#define GPIO_LINE_NAME "ttp223_tamper"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL 100000000 // 100 ms in nanoseconds
#define TOUCH_THRESHOLD 5 // 5 seconds

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t exit_flag = 0;

void cleanup() {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

void handle_signal(int sig) {
    exit_flag = 1;
}

int main() {
    struct timespec ts;
    struct timespec ts_start;
    struct timespec ts_current;
    int64_t touch_duration_ns = 0;
    int64_t last_touch_time_ns = 0;
    int ret;

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Request line as input
    ret = gpiod_line_request_input(line, GPIO_LINE_NAME, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!exit_flag) {
        ret = clock_gettime(CLOCK_MONOTONIC, &ts);
        if (ret < 0) {
            fprintf(stderr, "Error getting time: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        ret = gpiod_line_get_value(line, &ts);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        if (ts.tv_nsec >= POLL_INTERVAL) {
            ts.tv_nsec -= POLL_INTERVAL;
            ts.tv_sec += 1;
        } else {
            ts.tv_sec -= 1;
        }

        clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &ts, NULL);

        if (gpiod_line_get_value(line) == 1) { // Touched
            if (last_touch_time_ns == 0) {
                clock_gettime(CLOCK_MONOTONIC, &ts_start);
                last_touch_time_ns = ts_start.tv_sec * 1000000000LL + ts_start.tv_nsec;
            }
            touch_duration_ns = (ts.tv_sec * 1000000000LL + ts.tv_nsec) - last_touch_time_ns;
            if (touch_duration_ns > TOUCH_THRESHOLD * 1000000000LL) {
                printf("Intrusion alert!\n");
                last_touch_time_ns = 0; // Reset timer after alert
            }
        } else { // Released
            last_touch_time_ns = 0;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

