#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define PCM_DEVICE "hw:0,0"
#define PCM_SUBDEVICE "0"
#define PCM_FORMAT SND_PCM_FORMAT_S16_LE
#define PCM_CHANNELS 2
#define PCM_RATE 16000
#define PCM_PERIOD_SIZE 1024
#define PCM_PERIODS 4
#define GPIO_PIN 17

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "audio_capture", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(line, 1); // Select left channel

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

int init_alsa(snd_pcm_t **pcm_handle) {
    int err;

    err = snd_pcm_open(pcm_handle, PCM_DEVICE, SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Failed to open PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_t *params;
    snd_pcm_hw_params_alloca(&params);
    snd_pcm_hw_params_any(*pcm_handle, params);
    snd_pcm_hw_params_set_access(*pcm_handle, params, SND_PCM_ACCESS_RW_INTERLEAVED);
    snd_pcm_hw_params_set_format(*pcm_handle, params, PCM_FORMAT);
    snd_pcm_hw_params_set_channels(*pcm_handle, params, PCM_CHANNELS);
    snd_pcm_hw_params_set_rate_near(*pcm_handle, params, &PCM_RATE, NULL);
    snd_pcm_hw_params_set_period_size_near(*pcm_handle, params, &PCM_PERIOD_SIZE, NULL);
    snd_pcm_hw_params_set_periods_near(*pcm_handle, params, &PCM_PERIODS, NULL);

    err = snd_pcm_hw_params(*pcm_handle, params);
    if (err < 0) {
        fprintf(stderr, "Failed to set hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

int main() {
    int gpio_fd = -1;
    snd_pcm_t *pcm_handle = NULL;
    int audio_fd = -1;
    uint8_t *buffer;
    int err;

    signal(SIGINT, handle_sigint);

    if (init_gpio() < 0) {
        goto cleanup;
    }

    if (init_alsa(&pcm_handle) < 0) {
        goto cleanup;
    }

    audio_fd = open("audio_capture.pcm", O_WRONLY | O_CREAT | O_TRUNC, 0666);
    if (audio_fd < 0) {
        fprintf(stderr, "Failed to open audio file: %s\n", strerror(errno));
        goto cleanup;
    }

    buffer = malloc(PCM_PERIOD_SIZE * PCM_CHANNELS * sizeof(uint16_t));
    if (!buffer) {
        fprintf(stderr, "Failed to allocate buffer\n");
        goto cleanup;
    }

    while (keep_running) {
        err = snd_pcm_readi(pcm_handle, buffer, PCM_PERIODS);
        if (err == -EPIPE) {
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "Error reading from PCM device: %s\n", snd_strerror(err));
            break;
        } else if (err != (int)PCM_PERIODS) {
            fprintf(stderr, "Short read, read %d frames\n", err);
        }

        if (write(audio_fd, buffer, err * PCM_CHANNELS * sizeof(uint16_t)) != err * PCM_CHANNELS * sizeof(uint16_t)) {
            fprintf(stderr, "Error writing to audio file: %s\n", strerror(errno));
            break;
        }
    }

cleanup:
    if (buffer) {
        free(buffer);
    }
    if (pcm_handle) {
        snd_pcm_close(pcm_handle);
    }
