int init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "audio_capture", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(line, 1); // Select left channel

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

int init_alsa(snd_pcm_t **pcm_handle) {
    int err;

    err = snd_pcm_open(pcm_handle, PCM_DEVICE, SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Failed to open PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_t *params;
    snd_pcm_hw_params_alloca(&params);
    snd_pcm_hw_params_any(*pcm_handle, params);
    snd_pcm_hw_params_set_access(*pcm_handle, params, SND_PCM_ACCESS_RW_INTERLEAVED);
    snd_pcm_hw_params_set_format(*pcm_handle, params, PCM_FORMAT);
    snd_pcm_hw_params_set_channels(*pcm_handle, params, PCM_CHANNELS);
    snd_pcm_hw_params_set_rate_near(*pcm_handle, params, &PCM_RATE, NULL);
    snd_pcm_hw_params_set_period_size_near(*pcm_handle, params, &PCM_PERIOD_SIZE, NULL);
    snd_pcm_hw_params_set_periods_near(*pcm_handle, params, &PCM_PERIODS, NULL);

    err = snd_pcm_hw_params(*pcm_handle, params);
    if (err < 0) {
        fprintf(stderr, "Failed to set hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

