    audio_fd = open("audio_capture.pcm", O_WRONLY | O_CREAT | O_TRUNC, 0666);
    if (audio_fd < 0) {
        fprintf(stderr, "Failed to open audio file: %s\n", strerror(errno));
        goto cleanup;
    }

    buffer = malloc(PCM_PERIOD_SIZE * PCM_CHANNELS * sizeof(uint16_t));
    if (!buffer) {
        fprintf(stderr, "Failed to allocate buffer\n");
        goto cleanup;
    }

    while (keep_running) {
        err = snd_pcm_readi(pcm_handle, buffer, PCM_PERIODS);
        if (err == -EPIPE) {
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "Error reading from PCM device: %s\n", snd_strerror(err));
            break;
        } else if (err != (int)PCM_PERIODS) {
            fprintf(stderr, "Short read, read %d frames\n", err);
        }

        if (write(audio_fd, buffer, err * PCM_CHANNELS * sizeof(uint16_t)) != err * PCM_CHANNELS * sizeof(uint16_t)) {
            fprintf(stderr, "Error writing to audio file: %s\n", strerror(errno));
            break;
        }
    }

cleanup:
    if (buffer) {
        free(buffer);
    }
    if (pcm_handle) {
        snd_pcm_close(pcm_handle);
    }
    if (audio_fd >= 0) {
        close(audio_fd);
    }
    if (gpio_fd >= 0) {
        close(gpio_fd);
    }

    return 0;
}
