#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define FRAME_SIZE 32768
#define MAGIC_NUMBER 0x4144
#define GPIO_FRAME_TRIGGER 23
#define GPIO_DATA_READY 24
#define GPIO_CE0 8

volatile sig_atomic_t keep_running = 1;

typedef struct {
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint32_t chirps;
    uint32_t samples;
} RadarConfig;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_gpio(gpiod_chip *chip, int line, int flags) {
    gpiod_line *gpio_line = gpiod_chip_get_line(chip, line);
    if (!gpio_line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", line);
        return -1;
    }

    if (gpiod_line_request_rising_edge(gpio_line, "data_ready", flags) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d\n", line);
        gpiod_line_release(gpio_line);
        return -1;
    }

    return 0;
}

int setup_spi(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(*fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(*fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(*fd);
        return -1;
    }

    return 0;
}

int read_spi(int fd, uint8_t *buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)0,
        .rx_buf = (unsigned long)buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to read SPI");
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    if (setup_gpio(chip, GPIO_FRAME_TRIGGER, GPIOD_LINE_REQ_DIR_OUT) < 0 ||
        setup_gpio(chip, GPIO_DATA_READY, GPIOD_LINE_REQ_DIR_IN) < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int spi_fd;
    if (setup_spi(&spi_fd) < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("radar_log.bin", "wb");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    RadarConfig config = {77000000000, 79000000000, 64, 256};
    if (fwrite(&MAGIC_NUMBER, sizeof(MAGIC_NUMBER), 1, log_file) != 1 ||
        fwrite(&config, sizeof(config), 1, log_file) != 1) {
        perror("Failed to write header to log file");
        fclose(log_file);
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    uint8_t frame[FRAME_SIZE];
    struct timeval timestamp;
    uint32_t frame_number = 0;

    while (keep_running) {
        gpiod_line_set_value(gpiod_chip_get_line(chip, GPIO_FRAME_TRIGGER), 1);
        usleep(100);
        gpiod_line_set_value(gpiod_chip_get_line(chip, GPIO_FRAME_TRIGGER), 0);

        while (gpiod_line_event_wait(gpiod_chip_get_line(chip, GPIO_DATA_READY), -1) < 0) {
            if (!keep_running) break;
        }

        if (!keep_running) break;

        if (gettimeofday(&timestamp, NULL) < 0) {
            perror("Failed to get timestamp");
            break;
        }

        if (read_spi(spi_fd, frame, FRAME_SIZE) < 0) {
            perror("Failed to read SPI data");
            break;
        }

        if (fwrite(&timestamp, sizeof(timestamp), 1, log_file) != 1 ||
            fwrite(&frame_number, sizeof(frame_number), 1, log_file) != 1 ||
            fwrite(frame, sizeof(frame), 1, log_file) != 1) {
            perror("Failed to write frame to log file");
            break;
        }

        frame_number++;
        usleep(100000); // 100 ms period
    }

    fclose(log_file);
    close(spi_fd);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
