static volatile sig_atomic_t keep_running = 1;
static gpiod_chip *chip = NULL;
static gpiod_line *line = NULL;
static int last_state = -1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_state_change(int new_state) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    const char *state_str = (new_state == 0) ? "Flame Detected" : "Flame Cleared";
    fprintf(file, "%s: %s\n", timestamp, state_str);
    if (ferror(file)) {
        perror("Failed to write to log file");
    }

    fclose(file);
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "flame_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES)) {
        fprintf(stderr, "Failed to request line as input: %s\n", gpiod_strerror(gpiod_line_request_error(line)));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        gpiod_line_event_wait(line, POLL_INTERVAL_MS);
        int new_state = gpiod_line_get_value(line);
        if (new_state == -1) {
            fprintf(stderr, "Failed to read line value: %s\n", gpiod_strerror(gpiod_line_get_value_error(line)));
            break;
        }

        if (new_state != last_state) {
            log_state_change(new_state);
            last_state = new_state;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

