#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <syslog.h>
#include <errno.h>

#define I2C_BUS 1
#define OPT3001_I2C_ADDR 0x44
#define OPT3001_REG_CONVERSION 0x00
#define OPT3001_REG_RESULT 0x01
#define OPT3001_CONVERSION_MODE_CONTINUOUS 0x03
#define OPT3001_FULL_SCALE_AUTO 0x00
#define OPT3001_CONVERSION_MODE 0x80
#define OPT3001_FULL_SCALE 0x00
#define OPT3001_CONVERSION_TIME_100MS 0x0A

static int i2c_fd = -1;
static FILE *log_file = NULL;

void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    syslog(LOG_INFO, "Clean shutdown initiated.");
    exit(0);
}

void setup_signal_handling() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int open_i2c_device(int bus, int addr) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d: %s", bus, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int configure_sensor() {
    uint8_t config = OPT3001_CONVERSION_MODE | OPT3001_CONVERSION_MODE_CONTINUOUS |
                     OPT3001_FULL_SCALE | OPT3001_FULL_SCALE_AUTO |
                     OPT3001_CONVERSION_TIME_100MS;
    if (write(i2c_fd, &config, 1) != 1) {
        syslog(LOG_ERR, "Failed to write configuration: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int read_lux_value(uint16_t *lux) {
    uint8_t buffer[2];
    if (write(i2c_fd, &OPT3001_REG_CONVERSION, 1) != 1) {
        syslog(LOG_ERR, "Failed to write conversion register address: %s", strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buffer, 2) != 2) {
        syslog(LOG_ERR, "Failed to read lux value: %s", strerror(errno));
        return -1;
    }
    *lux = (buffer[0] << 8) | buffer[1];
    return 0;
}

void log_lux_value(uint16_t lux) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "%s %u\n", timestamp, lux);
    fflush(log_file);
}

int main() {
    openlog("OPT3001_Light_Sensor", LOG_PID | LOG_CONS, LOG_USER);
    setup_signal_handling();

    if (open_i2c_device(I2C_BUS, OPT3001_I2C_ADDR) != 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    log_file = fopen("light_data.txt", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (configure_sensor() != 0) {
        syslog(LOG_ERR, "Failed to configure sensor");
        fclose(log_file);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        uint16_t lux;
        if (read_lux_value(&lux) == 0) {
            log_lux_value(lux);
        } else {
            syslog(LOG_WARNING, "Failed to read lux value, retrying...");
        }
        usleep(100000); // Sleep for 100 ms
    }

    fclose(log_file);
    close(i2c_fd);
    closelog();
    return 0;
}

