#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL 100000000 // 100 ms in nanoseconds

static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_CHANNELS];
    int line_offset[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};
    int ret;

    // Set up signal handler for graceful shutdown
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, line_offset[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", line_offset[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_input(lines[i], "touch_sensor", GPIOD_LINE_REQ_EV_NONE);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d as input: %s\n", line_offset[i], gpiod_strerror(ret));
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Poll lines
    while (keep_running) {
        struct timespec ts = {0, POLL_INTERVAL};
        nanosleep(&ts, NULL);

        printf("%ld.%09ld: ", (long)time(NULL), (long)clock_gettime(CLOCK_REALTIME, NULL) % 1000000000);

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read value from line %d: %s\n", line_offset[i], gpiod_strerror(value));
                value = -1; // Indicate error
            }
            printf("%d", value);
        }
        printf("\n");
    }

    // Release resources
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

