#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 5
#define POLL_INTERVAL_MS 500

static volatile int keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    int ret;

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get the lines for the sensors
    line1 = gpiod_chip_get_line(chip, SENSOR_1_GPIO);
    line2 = gpiod_chip_get_line(chip, SENSOR_2_GPIO);
    if (!line1 || !line2) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the lines as input with open-drain
    ret = gpiod_line_request_input(line1, "sensor1", GPIOD_LINE_REQ_DIR_NONE);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line1 as input: %s\n", gpiod_strerror(ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line2, "sensor2", GPIOD_LINE_REQ_DIR_NONE);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line2 as input: %s\n", gpiod_strerror(ret));
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        int value1, value2;

        // Read the values from the sensors
        value1 = gpiod_line_get_value(line1);
        value2 = gpiod_line_get_value(line2);

        // Log the sensor states
        printf("Sensor 1: %s\n", value1 == 0 ? "LOW" : "HIGH");
        printf("Sensor 2: %s\n", value2 == 0 ? "LOW" : "HIGH");

        // Sleep for the poll interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

