#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static volatile int keep_running = 1;

// Signal handler for graceful shutdown
void handle_signal(int sig) {
    keep_running = 0;
}

// Function to get the current ISO-8601 timestamp
void get_iso8601_timestamp(char *buffer, size_t buffer_size) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    strftime(buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", tm_info);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_CHANNELS];
    int line_offsets[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};
    int line_values[NUM_CHANNELS];
    char timestamp[26];

    // Install signal handler
    signal(SIGINT, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, line_offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", line_offsets[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_input(lines[i], "TTP226_channel_%d", GPIOD_LINE_REQ_EV_NONE)) {
            fprintf(stderr, "Failed to request line %d as input\n", line_offsets[i]);
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Polling loop
    while (keep_running) {
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        for (int i = 0; i < NUM_CHANNELS; i++) {
            line_values[i] = gpiod_line_get_value(lines[i]);
            if (line_values[i] < 0) {
                fprintf(stderr, "Failed to read value from line %d\n", line_offsets[i]);
                // Continue to attempt to read other lines
            }
        }

        printf("%s,", timestamp);
        for (int i = 0; i < NUM_CHANNELS; i++) {
            printf("%d", line_values[i]);
            if (i < NUM_CHANNELS - 1) {
                printf(",");
            }
        }
        printf("\n");

        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Release resources
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

