#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN 4
#define GPIO_LINE "gpio4"
#define POLL_INTERVAL_MS 100

static volatile int keep_running = 1;
static gpiod_line_handle_t line = NULL;

void handle_sigint(int sig) {
    keep_running = 0;
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *gpio_line;
    int value, last_value = -1;

    // Install SIGINT handler
    signal(SIGINT, handle_sigint);

    // Print startup banner
    printf("Tilt Sensor Monitor\n");
    printf("Monitoring GPIO %s (BCM %d)\n", GPIO_LINE, GPIO_PIN);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get line
    gpio_line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line
    line = gpiod_line_request_input(gpio_line, "tilt_sensor", GPIOD_LINE_REQUEST_DIRECTIONS);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Enable internal pull-up resistor
    if (gpiod_line_set_value_cansleep(line, 1) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Read value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO value\n");
            break;
        }

        // Check for state change
        if (value != last_value) {
            fflush(stdout);
            if (value == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            last_value = value;
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

