#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define UV_INDEX_REG 0x80
#define ALS_VISIBLE_REG 0x8C

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

int read_i2c_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];
    buffer[0] = reg;

    if (write(fd, buffer, 1) != 1) {
        perror("Failed to write to I2C bus");
        return -1;
    }

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from I2C bus");
        return -1;
    }

    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

void log_to_csv(FILE *file, time_t timestamp, uint16_t uv_index, uint16_t als_visible) {
    struct tm *tm_info = localtime(&timestamp);
    fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d, %u, %u\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            uv_index, als_visible);
    fflush(file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open_i2c_device(I2C_BUS, SI1145_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("uv_als_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,uv_index,als_visible\n");
    fflush(log_file);

    while (keep_running) {
        time_t now = time(NULL);
        uint16_t uv_index, als_visible;

        if (read_i2c_register(i2c_fd, UV_INDEX_REG, &uv_index) == 0 &&
            read_i2c_register(i2c_fd, ALS_VISIBLE_REG, &als_visible) == 0) {
            printf("UV Index: %u, ALS Visible: %u\n", uv_index, als_visible);
            log_to_csv(log_file, now, uv_index, als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(1);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

