#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <string.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR1_ADDR 0x40
#define SENSOR2_ADDR 0x41
#define GPIO_PIN 17
#define LOG_FILE "flow_log.txt"
#define START_CMD 0x00
#define READ_CMD 0x01
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

uint8_t calculate_crc(uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int fd, uint8_t addr, uint8_t *flow_rate) {
    uint8_t cmd[1] = {READ_CMD};
    uint8_t response[3];
    int ret;

    ret = ioctl(fd, I2C_SLAVE, addr);
    if (ret < 0) {
        perror("Failed to set I2C address");
        return -1;
    }

    ret = write(fd, cmd, 1);
    if (ret != 1) {
        perror("Failed to write start command");
        return -1;
    }

    ret = read(fd, response, 3);
    if (ret != 3) {
        perror("Failed to read sensor data");
        return -1;
    }

    uint8_t crc = calculate_crc(response, 2);
    if (crc != response[2]) {
        fprintf(stderr, "CRC check failed for sensor at address 0x%02X\n", addr);
        return -1;
    }

    *flow_rate = (response[0] << 8) | response[1];
    return 0;
}

int main() {
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int line_request_flags = GPIOD_LINE_REQUEST_OUTPUT;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(line, "flow_alarm") < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    uint8_t flow_rate1, flow_rate2;
    int ret;

    ret = read_sensor(i2c_fd, SENSOR1_ADDR, &flow_rate1);
    if (ret == 0) {
        usleep(100000); // 100 ms delay
    }

    ret = read_sensor(i2c_fd, SENSOR2_ADDR, &flow_rate2);
    if (ret == 0) {
        usleep(100000); // 100 ms delay
    }

    while (keep_running) {
        uint8_t valid_readings = 0;
        double total_flow_rate = 0.0;

        if (read_sensor(i2c_fd, SENSOR1_ADDR, &flow_rate1) == 0) {
            total_flow_rate += flow_rate1;
            valid_readings++;
        }

        if (read_sensor(i2c_fd, SENSOR2_ADDR, &flow_rate2) == 0) {
            total_flow_rate += flow_rate2;
            valid_readings++;
        }

        if (valid_readings > 0) {
            double average_flow_rate = total_flow_rate / valid_readings;
            fprintf(log_file, "Average Flow Rate: %.2f ml/min\n", average_flow_rate);
            fflush(log_file);

            if (average_flow_rate < 0.5) {
                gpiod_line_set_value(line, 1);
            } else {
                gpiod_line_set_value(line, 0);
            }
        } else {
            fprintf(log_file, "No valid sensor readings\n");
            fflush(log_file);
        }

        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

