#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_GPIO 4
#define BUFFER_SIZE 100
#define POLL_INTERVAL_MS 50

typedef struct {
    int detection;
    time_t timestamp;
} DetectionEntry;

DetectionEntry buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int sig) {
    exit_flag = 1;
}

void print_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (buffer[i].detection != 0) {
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[i].timestamp));
            printf("Detection at %s\n", time_str);
        }
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Initialize the GPIO library
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get the line for the sensor
    line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the line as input with pull-up
    ret = gpiod_line_request_input(line, "obstacle_sensor", GPIOD_LINE_REQUEST_FLAG_NONE);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line as input: %s\n", gpiod_strerror(ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!exit_flag) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO value: %s\n", gpiod_strerror(value));
            break;
        }

        // Record detection in buffer
        buffer[buffer_index].detection = (value == 0) ? 1 : 0;
        buffer[buffer_index].timestamp = time(NULL);
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Emit alert if detection
        if (buffer[buffer_index - 1].detection) {
            printf("Obstacle detected!\n");
        }

        // Sleep for the polling interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    // Print buffer contents
    print_buffer();

    return EXIT_SUCCESS;
}

