#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x28 // Replace with the correct address for Omron D7S
#define I2C_SPEED 400000
#define SENSOR_TIMEOUT 1
#define POLL_INTERVAL 500000 // 500 ms in microseconds
#define CSV_FILE "fan_health.csv"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int address) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE_FORCE, address) < 0) {
        perror("Failed to force I2C address");
        close(fd);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C address again");
        close(fd);
        return -1;
    }

    if (ioctl(fd, I2C_TENBIT, 0) < 0) {
        perror("Failed to set 7-bit addressing");
        close(fd);
        return -1;
    }

    if (ioctl(fd, I2C_SET_BAUD_RATE, I2C_SPEED) < 0) {
        perror("Failed to set I2C speed");
        close(fd);
        return -1;
    }

    return fd;
}

int write_i2c(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int read_i2c(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, data, length) != length) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

void write_csv_header(FILE *file) {
    fprintf(file, "timestamp,x,y,z\n");
}

void write_csv_data(FILE *file, int x, int y, int z) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(file, "%s,%d,%d,%d\n", timestamp, x, y, z);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open_i2c_device(I2C_DEVICE, I2C_ADDRESS);
    if (i2c_fd < 0) {
        exit(EXIT_FAILURE);
    }

    FILE *csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (fseek(csv_file, 0, SEEK_END) == 0 && ftell(csv_file) == 0) {
        write_csv_header(csv_file);
    }

    uint8_t mode_reg = 0x00; // Replace with the correct mode register value
    uint8_t mode_value = 0x01; // Replace with the correct mode value

    if (write_i2c(i2c_fd, mode_reg, mode_value) < 0) {
        close(i2c_fd);
        fclose(csv_file);
        exit(EXIT_FAILURE);
    }

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (keep_running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed = (current_time.tv_sec - start_time.tv_sec) +
                         (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        if (elapsed > SENSOR_TIMEOUT) {
            fprintf(stderr, "Sensor did not become active within the timeout period\n");
            close(i2c_fd);
            fclose(csv_file);
            exit(EXIT_FAILURE);
        }

        uint8_t x, y, z;
        if (read_i2c(i2c_fd, 0x02, &x, 1) == 0 &&
            read_i2c(i2c_fd, 0x03, &y, 1) == 0 &&
            read_i2c(i2c_fd, 0x04, &z, 1) == 0) {
            write_csv_data(csv_file, x, y, z);
            fflush(csv_file);
        }

        usleep(POLL_INTERVAL);
    }

    close(i2c_fd);
    fclose(csv_file);
    return 0;
}

