#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 25
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define POLL_INTERVAL_MS 100

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *sensor1_line, *sensor2_line;
    int ret;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get the lines for the LED and sensors
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get line for LED\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Failed to get line for Sensor 1\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Failed to get line for Sensor 2\n");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the LED line as output
    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line as output\n");
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the sensor lines as input
    ret = gpiod_line_request_input(sensor1_line, "sensor1", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    if (ret < 0) {
        fprintf(stderr, "Failed to request Sensor 1 line as input\n");
        gpiod_line_release(led_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(sensor2_line, "sensor2", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    if (ret < 0) {
        fprintf(stderr, "Failed to request Sensor 2 line as input\n");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(led_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        int sensor1_value = gpiod_line_get_value(sensor1_line);
        int sensor2_value = gpiod_line_get_value(sensor2_line);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Failed to read sensor values\n");
            break;
        }

        if (sensor1_value == 0 || sensor2_value == 0) {
            // Turn on the LED if either sensor detects an obstacle
            gpiod_line_set_value(led_line, 1);
        } else {
            // Turn off the LED only if both sensors read HIGH
            gpiod_line_set_value(led_line, 0);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    gpiod_line_release(sensor2_line);
    gpiod_line_release(sensor1_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

