        fprintf(stderr, "Failed to request LED line as output\n");
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the sensor lines as input
    ret = gpiod_line_request_input(sensor1_line, "sensor1", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    if (ret < 0) {
        fprintf(stderr, "Failed to request Sensor 1 line as input\n");
        gpiod_line_release(led_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(sensor2_line, "sensor2", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    if (ret < 0) {
        fprintf(stderr, "Failed to request Sensor 2 line as input\n");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(led_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        int sensor1_value = gpiod_line_get_value(sensor1_line);
        int sensor2_value = gpiod_line_get_value(sensor2_line);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Failed to read sensor values\n");
            break;
        }

        if (sensor1_value == 0 || sensor2_value == 0) {
            // Turn on the LED if either sensor detects an obstacle
            gpiod_line_set_value(led_line, 1);
        } else {
            // Turn off the LED only if both sensors read HIGH
            gpiod_line_set_value(led_line, 0);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    gpiod_line_release(sensor2_line);
    gpiod_line_release(sensor1_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
