#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <syslog.h>

#define I2C_BUS 1
#define TMAG5170_I2C_ADDR 0x1E
#define TMAG5170_REG_STATUS 0x00
#define TMAG5170_REG_XOUT_L 0x01
#define TMAG5170_REG_YOUT_L 0x03
#define TMAG5170_REG_ZOUT_L 0x05
#define TMAG5170_REG_CONFIG 0x0A
#define TMAG5170_CONFIG_CONTINUOUS 0x01
#define TMAG5170_CONFIG_RANGE_50MT 0x00

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_write_byte_data(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

int i2c_read_byte_data(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

int i2c_read_word_data(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("I2C read");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

void log_magnetic_data(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-" PRIu8, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5170_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("magnetic_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t status;
    if (i2c_read_byte_data(i2c_fd, TMAG5170_REG_STATUS, &status) < 0) {
        fprintf(stderr, "Sensor not detected or bus error\n");
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (fseek(log_file, 0, SEEK_SET) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    if (i2c_write_byte_data(i2c_fd, TMAG5170_REG_CONFIG, TMAG5170_CONFIG_CONTINUOUS | TMAG5170_CONFIG_RANGE_50MT) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint16_t x, y, z;
        if (i2c_read_word_data(i2c_fd, TMAG5170_REG_XOUT_L, &x) < 0 ||
            i2c_read_word_data(i2c_fd, TMAG5170_REG_YOUT_L, &y) < 0 ||
            i2c_read_word_data(i2c_fd, TMAG5170_REG_ZOUT_L, &z) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
        } else {
            log_magnetic_data(x, y, z);
        }
        usleep(100000); // 100 ms
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

