#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_PIN 23
#define POLL_INTERVAL 2
#define REINIT_INTERVAL 60

static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_message(const char *message) {
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file);
    }
}

void log_error(const char *error_message) {
    char log_entry[256];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", tm_info);
    snprintf(log_entry + strlen(log_entry), sizeof(log_entry) - strlen(log_entry), " ERROR: %s", error_message);
    log_message(log_entry);
}

void initialize_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        gpiod_chip_close(chip);
        log_error("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line, "water_level_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES)) {
        gpiod_chip_close(chip);
        log_error("Failed to request GPIO line as input");
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void reinitialize_gpio() {
    cleanup();
    sleep(REINIT_INTERVAL);
    initialize_gpio();
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("flood_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    initialize_gpio();

    while (keep_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            log_error("Failed to read GPIO line");
            reinitialize_gpio();
            continue;
        }

        if (value == 1) {
            char log_entry[256];
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", tm_info);
            snprintf(log_entry + strlen(log_entry), sizeof(log_entry) - strlen(log_entry), " ALERT: Water detected");
            log_message(log_entry);
            printf("ALERT: Water detected\n");
        }

        usleep(POLL_INTERVAL * 1000000);
    }

    cleanup();
    return 0;
}

