    log_file = fopen("flood_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    initialize_gpio();

    while (keep_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            log_error("Failed to read GPIO line");
            reinitialize_gpio();
            continue;
        }

        if (value == 1) {
            char log_entry[256];
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", tm_info);
            snprintf(log_entry + strlen(log_entry), sizeof(log_entry) - strlen(log_entry), " ALERT: Water detected");
            log_message(log_entry);
            printf("ALERT: Water detected\n");
        }

        usleep(POLL_INTERVAL * 1000000);
    }

    cleanup();
    return 0;
}
