#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>
#include <gpiod.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE "rotation_log.txt"

static volatile int running = 1;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t state_cond = PTHREAD_COND_INITIALIZER;
static int last_state = 0;
static int current_state = 0;
static int fd_log = -1;

void handle_signal(int sig) {
    running = 0;
    pthread_cond_signal(&state_cond);
}

void log_rotation(const char *direction) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    pthread_mutex_lock(&state_mutex);
    if (fd_log != -1) {
        fprintf(fd_log, "%s - %s\n", timestamp, direction);
        fflush(fd_log);
    }
    pthread_mutex_unlock(&state_mutex);
}

void interrupt_handler_cb(struct gpiod_line *line, unsigned int events, void *user_data) {
    int new_state = gpiod_line_get_value(line);
    int direction = 0;

    pthread_mutex_lock(&state_mutex);
    if (new_state == 1) {
        if (last_state == 0) {
            direction = (current_state == 0) ? 1 : -1;
        }
        current_state = (current_state + 1) % 4;
    } else {
        if (last_state == 1) {
            direction = (current_state == 0) ? -1 : 1;
        }
        current_state = (current_state + 3) % 4;
    }
    last_state = new_state;

    if (direction == 1) {
        log_rotation("Clockwise");
    } else if (direction == -1) {
        log_rotation("Counter-Clockwise");
    }

    pthread_cond_signal(&state_cond);
    pthread_mutex_unlock(&state_mutex);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_a, *line_b;
    struct gpiod_line_event_handler handler;
    struct sigaction sa;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line_a = gpiod_chip_get_line(chip, SENSOR_A_PIN);
    if (!line_a) {
        fprintf(stderr, "Failed to get line for Sensor A\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line_b = gpiod_chip_get_line(chip, SENSOR_B_PIN);
    if (!line_b) {
        fprintf(stderr, "Failed to get line for Sensor B\n");
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_both_edges_events(line_a, "quadrature") < 0 ||
        gpiod_line_request_both_edges_events(line_b, "quadrature") < 0) {
        fprintf(stderr, "Failed to request events for lines\n");
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    handler.handler = interrupt_handler_cb;
    handler.private_data = NULL;

    if (gpiod_line_event_handler_add(line_a, &handler) < 0 ||
        gpiod_line_event_handler_add(line_b, &handler) < 0) {
        fprintf(stderr, "Failed to add event handler\n");
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    fd_log = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd_log < 0) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_event_handler_remove(line_a);
        gpiod_line_event_handler_remove(line_b);
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        pthread_mutex_lock(&state_mutex);
        pthread_cond_wait(&state_cond, &state_mutex);
        pthread_mutex_unlock(&state_mutex);
    }

    gpiod_line_event_handler_remove(line_a);
    gpiod_line_event_handler_remove(line_b);
    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);

    if (fd_log != -1) {
        close(fd_log);
    }

    return EXIT_SUCCESS;
}

