#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <gpiod.h>

#define SENSOR_PIN 23
#define LED_PIN 18
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t keep_running = 1;
static gpiod_chip *chip;
static gpiod_line *sensor_line;
static gpiod_line *led_line;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_and_exit(const char *message, int status) {
    syslog(LOG_ERR, "%s", message);
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    exit(status);
}

int main() {
    openlog("TouchSensorLED", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting Touch Sensor LED program");

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        log_and_exit("Failed to install signal handlers", EXIT_FAILURE);
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_and_exit("Failed to open GPIO chip", EXIT_FAILURE);
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        log_and_exit("Failed to get sensor line", EXIT_FAILURE);
    }
    if (gpiod_line_request_input(sensor_line, "touch_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        log_and_exit("Failed to request sensor line", EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        log_and_exit("Failed to get LED line", EXIT_FAILURE);
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        log_and_exit("Failed to request LED line", EXIT_FAILURE);
    }

    while (keep_running) {
        int value = gpiod_line_get_value(sensor_line);
        if (value < 0) {
            log_and_exit("Failed to read sensor value", EXIT_FAILURE);
        }

        if (value) {
            syslog(LOG_INFO, "Touch detected");
            if (gpiod_line_set_value(led_line, 1) < 0) {
                log_and_exit("Failed to set LED value", EXIT_FAILURE);
            }
        } else {
            if (gpiod_line_set_value(led_line, 0) < 0) {
                log_and_exit("Failed to set LED value", EXIT_FAILURE);
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down Touch Sensor LED program");
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_line_release(sensor_line);
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

