#define LED1_PIN 27
#define LED2_PIN 22
#define BUFFER_SIZE 100

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} TouchEvent;

TouchEvent touch_buffer[BUFFER_SIZE];
int buffer_index = 0;
int overflow_count = 0;
volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    int prev_state = touch_buffer[buffer_index].state;
    if (buffer_index < BUFFER_SIZE) {
        touch_buffer[buffer_index].sensor_pin = sensor_pin;
        touch_buffer[buffer_index].timestamp = now;
        touch_buffer[buffer_index].state = state;
        buffer_index++;
    } else {
        overflow_count++;
    }
    if (state != prev_state) {
        printf("Sensor %d: %s at %ld\n", sensor_pin, state ? "TOUCHED" : "RELEASED", now);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor1_line, *sensor2_line, *led1_line, *led2_line;
