    if (!sensor1_line) {
        fprintf(stderr, "Failed to get line for sensor 1\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_input(sensor1_line, "sensor1", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request sensor 1 line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Failed to get line for sensor 2\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_input(sensor2_line, "sensor2", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request sensor 2 line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    led1_line = gpiod_chip_get_line(chip, LED1_PIN);
    if (!led1_line) {
        fprintf(stderr, "Failed to get line for LED 1\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(led1_line, "led1", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED 1 line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    led2_line = gpiod_chip_get_line(chip, LED2_PIN);
    if (!led2_line) {
        fprintf(stderr, "Failed to get line for LED 2\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(led2_line, "led2", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED 2 line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int sensor1_value = gpiod_line_get_value(sensor1_line);
        int sensor2_value = gpiod_line_get_value(sensor2_line);

        if (sensor1_value >= 0) {
            log_event(SENSOR1_PIN, sensor1_value);
