        if (sensor2_value >= 0) {
            log_event(SENSOR2_PIN, sensor2_value);
            gpiod_line_set_value(led2_line, sensor2_value);
        } else {
            fprintf(stderr, "Failed to read sensor 2 value\n");
        }

        usleep(50000); // 50 ms debounce
    }

    // Turn off LEDs on shutdown
    gpiod_line_set_value(led1_line, 0);
    gpiod_line_set_value(led2_line, 0);

    // Print log buffer
    for (int i = 0; i < buffer_index; i++) {
        printf("Sensor %d: %s at %ld\n", touch_buffer[i].sensor_pin,
               touch_buffer[i].state ? "TOUCHED" : "RELEASED",
               touch_buffer[i].timestamp);
    }
    printf("Overflow count: %d\n", overflow_count);

    // Cleanup
    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);
    gpiod_line_release(led1_line);
    gpiod_line_release(led2_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

