#define GPIO_PIN 17
#define LOG_FILE "/var/log/rain_events.log"

static int log_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static int last_state = -1;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(const char *message) {
    if (log_fd < 0) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

    time_t now = time(NULL);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&now));

    dprintf(log_fd, "[%s] %s\n", time_str, message);
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fd >= 0) {
        fclose(stderr, log_fd);
        log_fd = -1;
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "raindrop_sensor", GPIOD_LINE_REQ_DIR_NONE) < 0) {
        perror("gpiod_line_request_input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_active_low(line) < 0) {
        perror("gpiod_line_set_active_low");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_pull_up(line) < 0) {
        perror("gpiod_line_set_pull_up");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_fd = fopen(LOG_FILE, "a");
    if (!log_fd) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (value != last_state) {
            if (value == 0) {
                log_event("Rain Detected");
            } else {
                log_event("No Rain");
            }
            last_state = value;
        }

        usleep(500 * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

