#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <stdbool.h>

#define DEBOUNCE_MS 5
#define CSV_FILENAME "shaft_log.txt"

static volatile bool running = true;
static struct timespec last_transition[2] = {{0, 0}, {0, 0}};
static int line_count = 0;
static int sensor1_state = 0;
static int sensor2_state = 0;
static int line_fd = -1;

static void handle_signal(int sig) {
    running = false;
}

static void log_transition(int sensor1, int sensor2) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);

    if (line_fd == -1) {
        line_fd = open(CSV_FILENAME, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (line_fd == -1) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }

    char buffer[128];
    snprintf(buffer, sizeof(buffer), "%ld.%09ld,%d,%d\n", now.tv_sec, now.tv_nsec, sensor1, sensor2);
    if (write(line_fd, buffer, strlen(buffer)) == -1) {
        perror("Failed to write to log file");
        exit(EXIT_FAILURE);
    }

    line_count++;
}

static bool debounce(int sensor, int new_state) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);

