#include <si1182.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x20 // Example I2C address for Si1182

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int main() {
    struct si1182_device *dev = NULL;
    struct si1182_data data;
    FILE *log_file = NULL;
    int ret;

    // Open syslog for error logging
    openlog("Si1182_Reader", LOG_PID | LOG_CONS, LOG_USER);

    // Install SIGINT handler
    signal(SIGINT, handle_sigint);

    // Open I2C device
    dev = si1182_open(I2C_BUS, I2C_ADDRESS);
    if (!dev) {
        syslog(LOG_ERR, "Failed to open Si1182 device");
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        si1182_close(dev);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Read heart rate and SpO2 data
        ret = si1182_read(dev, &data);
        if (ret != SI1182_SUCCESS) {
            syslog(LOG_ERR, "Failed to read from Si1182: %d", ret);
        } else {
            // Get current time
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

            // Write to log file
            fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n",
                    time_str, data.heart_rate, data.spo2);
            fflush(log_file);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    if (log_file) {
        fclose(log_file);
    }
    if (dev) {
        si1182_close(dev);
    }
    closelog();

    return EXIT_SUCCESS;
}

