void log_event(const char *event) {
    if (log_fd < 0) {
        fprintf(stderr, "Log file not open\n");
        return;
    }
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    dprintf(log_fd, "%s: %s\n", timestamp, event);
}

void activate_alarm() {
    if (gpiod_line_set_value(alarm_line, 1) < 0) {
        perror("Failed to activate alarm");
    }
    alarm_active = 1;
}

void deactivate_alarm() {
    if (gpiod_line_set_value(alarm_line, 0) < 0) {
        perror("Failed to deactivate alarm");
    }
    alarm_active = 0;
}

void cleanup() {
    if (alarm_active) {
        deactivate_alarm();
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
    if (alarm_line) {
        gpiod_line_release(alarm_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_signal(int sig) {
    cleanup();
    exit(0);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
