    if (!sensor2_line) {
        perror("Failed to get sensor2 line");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(sensor2_line, "sensor2", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        perror("Failed to request sensor2 line");
        cleanup();
        return EXIT_FAILURE;
    }

    alarm_line = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!alarm_line) {
        perror("Failed to get alarm line");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(alarm_line, "alarm", 0) < 0) {
        perror("Failed to request alarm line");
        cleanup();
        return EXIT_FAILURE;
    }

    log_fd = open("bridge_integrity.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        int sensor1_value = gpiod_line_get_value(sensor1_line);
        int sensor2_value = gpiod_line_get_value(sensor2_line);

        if (sensor1_value < 0 || sensor2_value < 0) {
            perror("Failed to read sensor values");
            cleanup();
            return EXIT_FAILURE;
        }

        if (sensor1_value || sensor2_value) {
            if (!last_tilt_time.tv_sec) {
                clock_gettime(CLOCK_MONOTONIC, &last_tilt_time);
                log_event("Tilt-start");
            } else if (clock_gettime(CLOCK_MONOTONIC, NULL) - last_tilt_time > THRESHOLD_DURATION) {
                if (!alarm_active) {
                    activate_alarm();
                    log_event("Threshold-exceeded");
                }
            }
        } else {
            if (alarm_active) {
                deactivate_alarm();
                log_event("Tilt-end");
            }
            last_tilt_time.tv_sec = 0;
        }

        nanosleep(&((struct timespec){ .tv_sec = 0, .tv_nsec = POLL_INTERVAL }), NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

