    if (gpiod_line_request_output(alert_led_line, "alert_led", 0)) {
        perror("Failed to request alert LED line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    i2c = gpiod_i2c_new(I2C_BUS, SDA_PIN, SCL_PIN);
    if (!i2c) {
        perror("Failed to create I2C device");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void initialize_sensor() {
    uint8_t ctrl1 = 0;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (gpiod_i2c_read_byte(i2c, I2C_ADDRESS, &ctrl1) == 0) {
            ctrl1 &= ~0x01; // Clear power-down bit
            if (gpiod_i2c_write_byte(i2c, I2C_ADDRESS, ctrl1) == 0) {
                return;
            }
        }
        retries++;
        usleep(100000); // 100 ms
    }
    fprintf(stderr, "Failed to initialize sensor after %d retries\n", MAX_RETRIES);
    exit(EXIT_FAILURE);
}

void log_event(double peak_vibration) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s, Peak Vibration: %.2f\n", timestamp, peak_vibration);
    fflush(log_file);
}

void alert() {
    gpiod_line_set_value(alert_led_line, 1);
    usleep(1000000); // 1 second
    gpiod_line_set_value(alert_led_line, 0);
}

double read_sensor() {
    uint8_t data[6];
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (gpiod_i2c_read(i2c, I2C_ADDRESS, data, sizeof(data)) == 0) {
            int16_t x = (data[1] << 8) | data[0];
            int16_t y = (data[3] << 8) | data[2];
            int16_t z = (data[5] << 8) | data[4];
            return sqrt(x * x + y * y + z * z);
        }
        retries++;
        usleep(100000); // 100 ms
    }
    fprintf(stderr, "Failed to read sensor after %d retries\n", MAX_RETRIES);
    return -1;
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (alert_led_line) {
        gpiod_line_release(alert_led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c) {
        gpiod_i2c_unref(i2c);
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    log_file = fopen("seismic_events.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    setup_gpio();
    setup_i2c();
    initialize_sensor();

    while (keep_running) {
        double peak_vibration = read_sensor();
        if (peak_vibration >= 0 && peak_vibration > VIBRATION_THRESHOLD) {
            log_event(peak_vibration);
            alert();
        }
        nanosleep((const struct timespec[]){{0, POLL_INTERVAL}}, NULL);
    }

    cleanup();
    return 0;
}

