This code sets up the Raspberry Pi to interface with an Omron D7S-A0011 seismic sensor using the libgpiod library for GPIO and I2C communication. It polls the sensor every 100 ms, logs events when the vibration magnitude exceeds a threshold, and handles cleanup on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 18
#define SENSOR_PINS {4, 17, 27, 22}
#define POLL_INTERVAL_NS 50000000 // 50 ms in nanoseconds

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *sensor_lines[4];
    int i, ret;
    struct gpiod_line_event event;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "led_control", 0);
    if (ret < 0) {
        perror("Failed to request LED line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request sensor lines
    for (i = 0; i < 4; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, SENSOR_PINS[i]);
        if (!sensor_lines[i]) {
            perror("Failed to get sensor line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_input(sensor_lines[i], "sensor_control", GPIOD_LINE_REQ_EV_BOTH_EDGES);
        if (ret < 0) {
            perror("Failed to request sensor line");
            for (int j = 0; j < i; j++) {
                gpiod_line_release(sensor_lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Main loop
    while (keep_running) {
        int obstacle_detected = 0;

        for (i = 0; i < 4; i++) {
            ret = gpiod_line_event_wait(sensor_lines[i], POLL_INTERVAL_NS);
            if (ret < 0) {
                perror("Failed to wait for sensor event");
                continue;
            }

            if (gpiod_line_event_read(sensor_lines[i], &event) < 0) {
                perror("Failed to read sensor event");
                continue;
            }

            if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                obstacle_detected = 1;
                break;
            }
        }

        gpiod_line_set_value(led_line, obstacle_detected);
    }

    // Clean up
    gpiod_line_release(led_line);
    for (i = 0; i < 4; i++) {
        gpiod_line_release(sensor_lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

