#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define DEBOUNCE_MS 50
#define POLL_INTERVAL 1000

static volatile sig_atomic_t terminate = 0;

const int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
const char *sensor_names[NUM_SENSORS] = {"Sensor 1", "Sensor 2", "Sensor 3", "Sensor 4", "Sensor 5"};

void handle_signal(int sig) {
    terminate = 1;
}

int log_event(const char *message) {
    FILE *log_file = fopen("/var/log/flame_events.log", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %m");
        return -1;
    }

    if (flock(fileno(log_file), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Failed to lock log file: %m");
        fclose(log_file);
        return -1;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s - %s\n", timestamp, message);
    if (fflush(log_file) == EOF) {
        syslog(LOG_ERR, "Failed to flush log file: %m");
        flock(fileno(log_file), LOCK_UN);
        fclose(log_file);
        return -1;
    }

    flock(fileno(log_file), LOCK_UN);
    fclose(log_file);
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set signal handlers: %m");
        return EXIT_FAILURE;
    }

    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Flame monitor started");

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %m");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "Failed to get line for GPIO %d: %m", sensor_pins[i]);
            continue;
        }

        if (gpiod_line_request_output(lines[i], sensor_names[i], GPIOD_LINE_REQUEST_DIRECTIONS_INPUT) < 0) {
            syslog(LOG_ERR, "Failed to request line for GPIO %d: %m", sensor_pins[i]);
            gpiod_line_release(lines[i]);
            continue;
        }
    }

    int last_state[NUM_SENSORS] = {0};
    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                syslog(LOG_WARNING, "Failed to read GPIO %d: %m", sensor_pins[i]);
                continue;
            }

            if (last_state[i] == 1 && value == 0) {
                usleep(DEBOUNCE_MS * 1000);
                int debounce_value = gpiod_line_get_value(lines[i]);
                if (debounce_value < 0) {
                    syslog(LOG_WARNING, "Failed to debounce read GPIO %d: %m", sensor_pins[i]);
                    continue;
                }

                if (debounce_value == 0) {
                    char log_message[256];
                    snprintf(log_message, sizeof(log_message), "%s - Sensor ID: %s (GPIO %d) - Flame Detected",
                             sensor_names[i], sensor_names[i], sensor_pins[i]);
                    if (log_event(log_message) < 0) {
                        syslog(LOG_ERR, "Failed to log flame event for GPIO %d", sensor_pins[i]);
                    }
                }
            }
            last_state[i] = value;
        }
        usleep(POLL_INTERVAL * 1000);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    gpiod_chip_close(chip);
    closelog();
    syslog(LOG_INFO, "Flame monitor stopped");

    return EXIT_SUCCESS;
}

