#define I2C_BUS 1
#define I2C_ADDRESS 0x10
#define GPIO_PWM 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int setup_pwm() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return -1;
    }

    if (gpioSetMode(GPIO_PWM, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(errno));
        return -1;
    }

    if (gpioPWM(GPIO_PWM, PWM_FREQUENCY, 0) < 0) {
        fprintf(stderr, "Failed to set PWM frequency: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int set_pwm_duty_cycle(int duty_cycle) {
    if (gpioPWMrange(GPIO_PWM, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range: %s\n", strerror(errno));
        return -1;
    }

    if (gpioPWM(GPIO_PWM, PWM_FREQUENCY, duty_cycle * PWM_RANGE / 100) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int read_lux(int *lux) {
    int fd = open("/dev/i2c-" + std::to_string(I2C_BUS), O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t reg = 0x00; // Control register
    uint8_t data[2] = {0x00, 0x00}; // Data buffer

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C bus: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C bus: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);

    *lux = (data[0] << 8) | data[1];

    return 0;
}

void log_data(int lux, int duty_cycle, int error_code) {
    FILE *log_file = fopen("grow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, lux, duty_cycle, error_code);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (setup_pwm() < 0) {
        log_data(0, 0, -1);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("grow_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fclose(log_file);

    while (keep_running) {
        int lux = 0;
        int error_code = 0;

        if (read_lux(&lux) < 0) {
            error_code = -1;
        }

        int duty_cycle = 100;
        if (lux >= 1000) {
            duty_cycle = 25;
        } else if (lux >= 1000) {
            duty_cycle = 50;
        } else if (lux >= 500) {
            duty_cycle = 75;
        }

        if (set_pwm_duty_cycle(duty_cycle) < 0) {
            error_code = -2;
        }

        log_data(lux, duty_cycle, error_code);
        sleep(1);
    }

    set_pwm_duty_cycle(0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

