#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL 50 // milliseconds
#define DEBOUNCE_TIME 200 // milliseconds

static volatile int running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_CHANNELS];
static struct gpiod_line *led_line;
static int debounce[NUM_CHANNELS] = {0};

void handle_signal(int sig) {
    running = 0;
    gpiod_line_set_value(led_line, 0);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    exit(0);
}

void log_touch_event(int channel) {
    FILE *file = fopen("touch_log.txt", "a");
    if (!file) {
        fprintf(stderr, "Error opening touch_log.txt for writing\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s – Channel %d Touched\n", buffer, channel + 1);
    if (ferror(file)) {
        fprintf(stderr, "Error writing to touch_log.txt\n");
    }
    fclose(file);
}

void update_led_state() {
    int touched = 0;
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_get_value(lines[i]) == 1) {
            touched = 1;
            break;
        }
    }
    gpiod_line_set_value(led_line, touched);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, 17);
    if (!led_line || gpiod_line_request_output(led_line, "alert_led", 0)) {
        fprintf(stderr, "Failed to configure LED line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i + 2);
        if (!lines[i] || gpiod_line_request_input(lines[i], "touch_sensor", GPIOD_LINE_REQ_DIR_NONE | GPIOD_LINE_REQ_DEBOUNCE)) {
            fprintf(stderr, "Failed to configure touch sensor line %d\n", i + 2);
            gpiod_line_release(led_line);
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value == 1 && debounce[i] == 0) {
                debounce[i] = DEBOUNCE_TIME;
                log_touch_event(i);
            }
            if (debounce[i] > 0) {
                debounce[i]--;
            }
        }
        update_led_state();
        usleep(POLL_INTERVAL * 1000);
    }

    gpiod_line_set_value(led_line, 0);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

