#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define OPT3001_ADDR 0x44
#define OPT3001_REG_CONFIG 0x01
#define OPT3001_REG_RESULT 0x00
#define CONFIGURATION_VALUE 0x0030 // Example configuration value

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void error_exit(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

void swap_endian_16(uint16_t *value) {
    *value = (*value >> 8) | (*value << 8);
}

int main() {
    int i2c_fd;
    uint8_t config_value = CONFIGURATION_VALUE;
    uint8_t result[2];
    uint16_t lux_value;
    FILE *log_file;

    // Install SIGINT handler
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        error_exit("Failed to open I2C bus");
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        close(i2c_fd);
        error_exit("Failed to set I2C address");
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (!log_file) {
        close(i2c_fd);
        error_exit("Failed to open log file");
    }

    while (keep_running) {
        // Write configuration
        if (write(i2c_fd, &config_value, 1) != 1) {
            fprintf(stderr, "Failed to write configuration: %s\n", strerror(errno));
            continue;
        }

        // Wait at least 100 ms after writing configuration
        usleep(100000);

        // Read result
        if (read(i2c_fd, result, 2) != 2) {
            fprintf(stderr, "Failed to read result: %s\n", strerror(errno));
            continue;
        }

        // Swap endianess of the result
        swap_endian_16((uint16_t *)result);
        lux_value = (result[0] << 8) | result[1];

        // Get current time
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        // Format the output
        char output[50];
