#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_GPIO 4
#define ALERT_GPIO 17
#define POLL_INTERVAL 500000 // 500 ms in microseconds
#define ALERT_DURATION 1000000 // 1 second in microseconds

static int log_fd = -1;
static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *alert_line;

void log_event(const char *message) {
    if (log_fd != -1) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        dprintf(log_fd, "[%s] %s\n", timestamp, message);
    }
}

void cleanup(int signum) {
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (alert_line) {
        gpiod_line_release(alert_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    alert_line = gpiod_chip_get_line(chip, ALERT_GPIO);
    if (!alert_line) {
        fprintf(stderr, "Failed to get alert line\n");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor_line, "flame_sensor", 0) < 0) {
        fprintf(stderr, "Failed to request sensor line as input\n");
        gpiod_line_release(alert_line);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(alert_line, "alert_output", 0) < 0) {
        fprintf(stderr, "Failed to request alert line as output\n");
        gpiod_line_release(sensor_line);
        gpiod_line_release(alert_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_fd = open("fire_events.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(alert_line);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int value = gpiod_line_get_value(sensor_line);
        if (value < 0) {
            log_event("Error reading sensor value");
            continue;
        }

        if (value == 0) {
            log_event("Flame detected");
            if (gpiod_line_set_value(alert_line, 1) < 0) {
                log_event("Error setting alert line HIGH");
            } else {
                usleep(ALERT_DURATION);
                if (gpiod_line_set_value(alert_line, 0) < 0) {
                    log_event("Error setting alert line LOW");
                }
            }
        }

        usleep(POLL_INTERVAL);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

