#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_PIN 4
#define DEBOUNCE_INTERVAL_MS 50

static int line_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_line *line = NULL;

void handle_signal(int signum) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (line_fd != -1) {
        close(line_fd);
        line_fd = -1;
    }
    exit(signum == SIGINT ? 0 : 1);
}

void log_touch_event(const char *event) {
    if (!log_file) return;

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: %s\n", time_str, event);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    line = gpiod_line_request_by_name(NULL, "gpio4", GPIOD_LINE_REQUEST_DIRECTIONS_INPUT);
    if (!line) {
        fprintf(stderr, "Failed to request line: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_value_cansleep(line, 0)) {
        fprintf(stderr, "Failed to set pull-down: %s\n", strerror(errno));
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    int last_state = -1;
    while (1) {
        int state = gpiod_line_get_value(line);
        if (state < 0) {
            fprintf(stderr, "Failed to read line value: %s\n", strerror(errno));
            break;
        }

        if (state != last_state) {
            if (state == 1) {
                log_touch_event("Touch Detected");
            } else {
                log_touch_event("Touch Released");
            }
            last_state = state;
        }

        usleep(DEBOUNCE_INTERVAL_MS * 1000);
    }

    handle_signal(0);
    return EXIT_FAILURE;
}

