#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SLF3S1300F_ADDR 0x28
#define POLYNOMIAL 0x31
#define INITIAL_VALUE 0xFF
#define HEADER "Timestamp,Flow Rate (ml/min),Status\n"

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int open_i2c_device(const char *device, int addr) {
    int file;
    if ((file = open(device, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }
    if (ioctl(file, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return -1;
    }
    return file;
}

int read_sensor(int file, uint8_t *buffer, size_t length) {
    if (read(file, buffer, length) != length) {
        perror("Failed to read from the sensor");
        return -1;
    }
    return 0;
}

void log_to_file(FILE *file, const char *timestamp, double flow_rate, const char *status) {
    fprintf(file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
}

int main() {
    signal(SIGINT, handle_sigint);

    int i2c_file = open_i2c_device(I2C_BUS, SLF3S1300F_ADDR);
    if (i2c_file < 0) {
        exit(EXIT_FAILURE);
    }

    FILE *log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_file);
        exit(EXIT_FAILURE);
    }

    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, HEADER);
    }

    while (keep_running) {
        usleep(2000); // Wait at least 2 ms

        uint8_t buffer[3];
        if (read_sensor(i2c_file, buffer, 3) == 0) {
            uint16_t flow_value = (buffer[0] << 8) | buffer[1];
            if (flow_value & 0x8000) {
                flow_value |= 0xFFFF0000; // Sign extend
            }
            double flow_rate = flow_value / 1000.0;

            uint8_t crc = crc8(buffer, 2);
            if (crc == buffer[2]) {
                char status[20];
                if (flow_rate >= 0.0 && flow_rate <= 100.0) {
                    snprintf(status, sizeof(status), "OK");
                } else {
                    snprintf(status, sizeof(status), "INVALID");
                }
                time_t now = time(NULL);
                char *timestamp = ctime(&now);
                timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
                log_to_file(log_file, timestamp, flow_rate, status);
            } else {
                log_to_file(log_file, "ERROR", 0.0, "CRC ERROR");
                close(i2c_file);
                i2c_file = open_i2c_device(I2C_BUS, SLF3S1300F_ADDR);
                if (i2c_file < 0) {
                    exit(EXIT_FAILURE);
                }
            }
        } else {
            log_to_file(log_file, "ERROR", 0.0, "READ ERROR");
            close(i2c_file);
            i2c_file = open_i2c_device(I2C_BUS, SLF3S1300F_ADDR);
            if (i2c_file < 0) {
                exit(EXIT_FAILURE);
            }
        }

        sleep(1); // Sample once per second
    }

    fclose(log_file);
    close(i2c_file);
    return 0;
}

