            uint16_t flow_value = (buffer[0] << 8) | buffer[1];
            if (flow_value & 0x8000) {
                flow_value |= 0xFFFF0000; // Sign extend
            }
            double flow_rate = flow_value / 1000.0;

            uint8_t crc = crc8(buffer, 2);
            if (crc == buffer[2]) {
                char status[20];
                if (flow_rate >= 0.0 && flow_rate <= 100.0) {
                    snprintf(status, sizeof(status), "OK");
                } else {
                    snprintf(status, sizeof(status), "INVALID");
                }
                time_t now = time(NULL);
                char *timestamp = ctime(&now);
                timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
                log_to_file(log_file, timestamp, flow_rate, status);
            } else {
                log_to_file(log_file, "ERROR", 0.0, "CRC ERROR");
                close(i2c_file);
                i2c_file = open_i2c_device(I2C_BUS, SLF3S1300F_ADDR);
                if (i2c_file < 0) {
                    exit(EXIT_FAILURE);
                }
            }
        } else {
            log_to_file(log_file, "ERROR", 0.0, "READ ERROR");
            close(i2c_file);
            i2c_file = open_i2c_device(I2C_BUS, SLF3S1300F_ADDR);
            if (i2c_file < 0) {
                exit(EXIT_FAILURE);
            }
        }

        sleep(1); // Sample once per second
    }

    fclose(log_file);
    close(i2c_file);
    return 0;
}
