        running = false;
    }
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR);
    if (!left_line || gpiod_line_request_input(left_line, "left_sensor", GPIOD_LINE_REQ_EV_NONE)) {
        fprintf(stderr, "Failed to request left sensor line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR);
    if (!middle_line || gpiod_line_request_input(middle_line, "middle_sensor", GPIOD_LINE_REQ_EV_NONE)) {
        fprintf(stderr, "Failed to request middle sensor line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR);
    if (!right_line || gpiod_line_request_input(right_line, "right_sensor", GPIOD_LINE_REQ_EV_NONE)) {
        fprintf(stderr, "Failed to request right sensor line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    if (left_line) gpiod_line_release(left_line);
    if (middle_line) gpiod_line_release(middle_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip) gpiod_chip_close(chip);
}

void setup_logging() {
    log_file = fopen("path_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "timestamp,left,middle,right\n");
}

void cleanup_logging() {
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
}

void log_sensor_data() {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "Failed to get timestamp: %s\n", strerror(errno));
        return;
    }

    int left_value = gpiod_line_get_value(left_line);
    int middle_value = gpiod_line_get_value(middle_line);
    int right_value = gpiod_line_get_value(right_line);

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left_value, middle_value, right_value) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    }
}

int main() {
    signal(SIGINT, handle_signal);

    setup_gpio();
    setup_logging();

    while (running) {
        log_sensor_data();
        usleep(POLL_INTERVAL * 1000);
    }

    cleanup_logging();
    cleanup_gpio();

    return EXIT_SUCCESS;
}

