#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define FLAME_SENSOR_LINE 4
#define FLAME_SENSOR_CHIP "gpiochip0"
#define EVENT_FILE "flame_events.txt"

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    printf("%s: %s\n", timestamp, message);

    FILE *file = fopen(EVENT_FILE, "a");
    if (file) {
        fprintf(file, "%s: %s\n", timestamp, message);
        fclose(file);
    } else {
        perror("Failed to open event file");
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(FLAME_SENSOR_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get line
    line = gpiod_chip_get_line(chip, FLAME_SENSOR_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line
    ret = gpiod_line_request_input(line, "flame_sensor", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line: %s\n", gpiod_strerror(ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up event detection
    ret = gpiod_line_event_both_edges(line);
    if (ret < 0) {
        fprintf(stderr, "Failed to set event detection: %s\n", gpiod_strerror(ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Monitor for events
    while (keep_running) {
        ret = gpiod_line_event_wait(line, -1);
        if (ret < 0) {
            if (errno == EINTR) {
                continue; // Interrupted by signal, continue
            }
            fprintf(stderr, "Failed to wait for event: %s\n", gpiod_strerror(ret));
            break;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read event: %s\n", gpiod_strerror(ret));
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            log_event("Flame detected");
        }
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

