#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/gpiochip.h>
#include <syslog.h>

#define GPIOCHIP "/dev/gpiochip4"
#define TOUCH_SENSOR_LINE 23
#define LED_LINE 24
#define LOG_FILE "touch_log.txt"
#define POLL_TIMEOUT_USEC 1000000

static int log_fd = -1;
static int gpio_chip_fd = -1;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(const char *event) {
    if (log_fd < 0) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    dprintf(log_fd, "%s: %s\n", timestamp, event);
}

int setup_gpio() {
    gpio_chip_fd = open(GPIOCHIP, O_RDWR);
    if (gpio_chip_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    touch_line = gpiod_chip_get_line(gpio_chip_fd, TOUCH_SENSOR_LINE);
    if (!touch_line) {
        fprintf(stderr, "Failed to get touch sensor line: %s\n", strerror(errno));
        close(gpio_chip_fd);
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip_fd, LED_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", strerror(errno));
        gpiod_line_release(touch_line);
        close(gpio_chip_fd);
        return -1;
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        fprintf(stderr, "Failed to request touch sensor line: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_line_release(touch_line);
        close(gpio_chip_fd);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        close(gpio_chip_fd);
        return -1;
    }

    return 0;
}

void cleanup() {
    if (log_fd >= 0) {
        close(log_fd);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (gpio_chip_fd >= 0) {
        close(gpio_chip_fd);
    }
}

int main() {
    struct gpiod_line_event event;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        ret = gpiod_line_event_wait(touch_line, POLL_TIMEOUT_USEC);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Failed to wait for touch event: %s\n", strerror(errno));
            break;
        }

        if (ret == 0) {
            continue; // Timeout occurred
        }

        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "Failed to read touch event: %s\n", strerror(errno));
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            int led_state = gpiod_line_get_value(led_line);
            gpiod_line_set_value(led_line, !led_state);
            char led_state_str[10] = led_state ? "ON" : "OFF";
            log_event(led_state_str);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

