#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define POLL_INTERVAL 500000 // 500 ms in microseconds
#define BUZZER_DURATION 2000000 // 2 seconds in microseconds
#define SLICE_DURATION 100000 // 100 ms in microseconds

static struct gpiod_chip *chip;
static struct gpiod_line *flame_sensor_line;
static struct gpiod_line *buzzer_line;
static FILE *log_file;
static int running = 1;

void handle_signal(int signum) {
    running = 0;
}

void log_message(const char *message) {
    if (log_file) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file);
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        fprintf(stderr, "Failed to get flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES)) {
        fprintf(stderr, "Failed to request flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0)) {
        fprintf(stderr, "Failed to request buzzer line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen("alert_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_message("System started");

    int last_state = gpiod_line_get_value(flame_sensor_line);
    int buzzer_active = 0;
    int buzzer_start_time = 0;

    while (running) {
        int current_state = gpiod_line_get_value(flame_sensor_line);
        if (current_state == 0 && last_state == 1) {
            log_message("FLAME DETECTED");
            gpiod_line_set_value(buzzer_line, 1);
            buzzer_active = 1;
            buzzer_start_time = time(NULL);
        }

        if (buzzer_active) {
            if (difftime(time(NULL), buzzer_start_time) >= 2) {
                gpiod_line_set_value(buzzer_line, 0);
                buzzer_active = 0;
            }
        }

        last_state = current_state;

        usleep(SLICE_DURATION);
    }

    if (buzzer_active) {
        gpiod_line_set_value(buzzer_line, 0);
    }

    if (log_file) {
        log_message("System stopped");
        fclose(log_file);
    }

    gpiod_line_release(flame_sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

