#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define POLL_INTERVAL 10 // milliseconds
#define DEBOUNCE_TIME 200 // milliseconds

static int log_fd = -1;
static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *led_line;
static int last_state = 0;
static int debounce_counter = 0;
static int running = 1;

void handle_signal(int signum) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

void log_touch_event() {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    if (log_fd == -1) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

    if (fprintf(log_fd, "%s\n", timestamp) < 0) {
        perror("Failed to write to log file");
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor_line, "touch_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES)) {
        fprintf(stderr, "Failed to request sensor line: %s\n", gpiod_strerror(gpiod_line_get_error(sensor_line)));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", gpiod_strerror(gpiod_line_get_error(led_line)));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "led", 0)) {
        fprintf(stderr, "Failed to request LED line: %s\n", gpiod_strerror(gpiod_line_get_error(led_line)));
        gpiod_line_release(sensor_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_fd = open("touch_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("Failed to open log file");
        gpiod_line_release(sensor_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        int value;
        if (gpiod_line_event_wait(sensor_line, POLL_INTERVAL)) {
            fprintf(stderr, "Failed to wait for sensor event: %s\n", gpiod_strerror(gpiod_line_get_error(sensor_line)));
            continue;
        }

        value = gpiod_line_get_value(sensor_line);
        if (value < 0) {
            fprintf(stderr, "Failed to read sensor value: %s\n", gpiod_strerror(gpiod_line_get_error(sensor_line)));
            continue;
        }

        if (value == 1 && last_state == 0) {
            if (debounce_counter == 0) {
                debounce_counter = DEBOUNCE_TIME / POLL_INTERVAL;
                gpiod_line_set_value(led_line, 1);
            } else {
                debounce_counter--;
            }
        } else if (value == 0 && last_state == 1) {
            debounce_counter = 0;
        }

        if (debounce_counter == 0 && last_state == 0 && value == 1) {
            log_touch_event();
            gpiod_line_set_value(led_line, !gpiod_line_get_value(led_line));
        }

        last_state = value;
    }

    handle_signal(0);
    return EXIT_SUCCESS;
}

