#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

#define SENSOR_COUNT 3
#define POLL_INTERVAL 100000000 // 100 ms in nanoseconds

// GPIO line numbers for the sensors
static const int sensor_pins[SENSOR_COUNT] = {4, 17, 27};

// File pointer for logging
static FILE *log_file = NULL;

// Function to handle signals for clean shutdown
void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    for (int i = 0; i < SENSOR_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }
    exit(0);
}

// Function to get the current timestamp in ISO-8601 format
void get_iso8601_timestamp(char *buffer, size_t buffer_size) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(buffer, buffer_size, "%Y-%m-%dT%H:%M:%S", tm_info);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[SENSOR_COUNT];
    int line_values[SENSOR_COUNT];
    int line_fds[SENSOR_COUNT];
    int ret;

    // Register signal handlers for clean shutdown
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Configure each sensor pin
    for (int i = 0; i < SENSOR_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO%d\n", sensor_pins[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_input(lines[i], "magnet_sensor", GPIOD_LINE_REQ_DIR_NONE);
        if (ret) {
            fprintf(stderr, "Failed to request line GPIO%d as input\n", sensor_pins[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_set_active_low(lines[i]);
        if (ret) {
            fprintf(stderr, "Failed to set line GPIO%d as active low\n", sensor_pins[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_set_pull(lines[i], GPIOD_LINE_PULL_UP);
        if (ret) {
            fprintf(stderr, "Failed to set pull-up for line GPIO%d\n", sensor_pins[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        line_fds[i] = gpiod_line_get_fd(lines[i]);
        if (line_fds[i] < 0) {
            fprintf(stderr, "Failed to get file descriptor for line GPIO%d\n", sensor_pins[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Open the log file
    log_file = fopen("magnet_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        for (int i = 0; i < SENSOR_COUNT; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initial read to record the initial state
    for (int i = 0; i < SENSOR_COUNT; i++) {
        ret = read(line_fds[i], &line_values[i], sizeof(line_values[i]));
        if (ret < 0) {
            fprintf(stderr, "Failed to read initial state for GPIO%d\n", sensor_pins[i]);
        }
    }

    // Main loop to poll the sensors
    while (1) {
        for (int i = 0; i < SENSOR_COUNT; i++) {
            int new_value;
            ret = read(line_fds[i], &new_value, sizeof(new_value));
            if (ret < 0) {
                fprintf(stderr, "Error reading GPIO%d\n", sensor_pins[i]);
                continue;
            }

            // Log state change
            if (new_value != line_values[i]) {
                char timestamp[20];
                get_iso8601_timestamp(timestamp, sizeof(timestamp));
                fprintf(log_file, "%s Sensor %d: %s\n", timestamp, i + 1, new_value ? "Magnet removed" : "Magnet present");
                line_values[i] = new_value;
            }
        }
        usleep(POLL_INTERVAL / 1000); // Convert nanoseconds to microseconds
    }

    // Clean up (unreachable due to infinite loop, but good practice)
    if (log_file) {
        fclose(log_file);
    }
    for (int i = 0; i < SENSOR_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

