        if (ret) {
            fprintf(stderr, "Failed to set pull-up for line GPIO%d\n", sensor_pins[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        line_fds[i] = gpiod_line_get_fd(lines[i]);
        if (line_fds[i] < 0) {
            fprintf(stderr, "Failed to get file descriptor for line GPIO%d\n", sensor_pins[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Open the log file
    log_file = fopen("magnet_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        for (int i = 0; i < SENSOR_COUNT; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initial read to record the initial state
    for (int i = 0; i < SENSOR_COUNT; i++) {
        ret = read(line_fds[i], &line_values[i], sizeof(line_values[i]));
        if (ret < 0) {
            fprintf(stderr, "Failed to read initial state for GPIO%d\n", sensor_pins[i]);
        }
    }

    // Main loop to poll the sensors
    while (1) {
        for (int i = 0; i < SENSOR_COUNT; i++) {
            int new_value;
            ret = read(line_fds[i], &new_value, sizeof(new_value));
            if (ret < 0) {
                fprintf(stderr, "Error reading GPIO%d\n", sensor_pins[i]);
                continue;
            }

            // Log state change
            if (new_value != line_values[i]) {
                char timestamp[20];
                get_iso8601_timestamp(timestamp, sizeof(timestamp));
                fprintf(log_file, "%s Sensor %d: %s\n", timestamp, i + 1, new_value ? "Magnet removed" : "Magnet present");
                line_values[i] = new_value;
            }
        }
        usleep(POLL_INTERVAL / 1000); // Convert nanoseconds to microseconds
    }

    // Clean up (unreachable due to infinite loop, but good practice)
    if (log_file) {
        fclose(log_file);
    }
    for (int i = 0; i < SENSOR_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
