#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <syslog.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define HR_REG 0x02
#define EXPECTED_PART_ID 0x12
#define EXPECTED_HW_REV 0x82

#define MAX_SAMPLES 5

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

int read_i2c_register(int fd, uint8_t reg, uint8_t *data) {
    uint8_t buffer[1] = {reg};
    if (write(fd, buffer, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C register: %s", strerror(errno));
        return -1;
    }

    if (read(fd, data, 1) != 1) {
        syslog(LOG_ERR, "Failed to read from I2C register: %s", strerror(errno));
        return -1;
    }

    return 0;
}

int validate_sensor(int fd) {
    uint8_t part_id, hw_rev;
    if (read_i2c_register(fd, PART_ID_REG, &part_id) < 0 || part_id != EXPECTED_PART_ID) {
        syslog(LOG_ERR, "Invalid PART_ID or failed to read PART_ID");
        return -1;
    }

    if (read_i2c_register(fd, HW_REV_REG, &hw_rev) < 0 || hw_rev != EXPECTED_HW_REV) {
        syslog(LOG_ERR, "Invalid HW_REV or failed to read HW_REV");
        return -1;
    }

    return 0;
}

int read_heart_rate(int fd, int *hr) {
    uint8_t hr_reg;
    int retries = 3;
    while (retries--) {
        if (read_i2c_register(fd, HR_REG, &hr_reg) == 0) {
            *hr = hr_reg;
            return 0;
        }
        usleep(100000); // Retry after 100ms
    }
    syslog(LOG_ERR, "Failed to read heart rate after retries");
    return -1;
}

void append_to_csv(FILE *file, int hr) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(file, "%s,%d\n", timestamp, hr);
    fflush(file);
}

int main() {
    openlog("heart_rate_sensor", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);

    int fd = open_i2c_device(I2C_BUS, SI1182_ADDR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        closelog();
        return EXIT_FAILURE;
    }

    if (validate_sensor(fd) < 0) {
        syslog(LOG_ERR, "Sensor validation failed");
        close(fd);
        closelog();
        return EXIT_FAILURE;
    }

    FILE *file = fopen("heart_rate.csv", "a");
    if (!file) {
        syslog(LOG_ERR, "Failed to open CSV file: %s", strerror(errno));
        close(fd);
        closelog();
        return EXIT_FAILURE;
    }

    int samples[MAX_SAMPLES] = {0};
    int sample_index = 0;
    int sum = 0;

    while (keep_running) {
        int hr;
        if (read_heart_rate(fd, &hr) == 0) {
            sum -= samples[sample_index];
            samples[sample_index] = hr;
            sum += hr;
            sample_index = (sample_index + 1) % MAX_SAMPLES;

            int avg_hr = sum / MAX_SAMPLES;
            if (avg_hr >= 30 && avg_hr <= 220) {
                append_to_csv(file, avg_hr);
            }
        }
        sleep(1);
    }

    fclose(file);
    close(fd);
    closelog();
    return EXIT_SUCCESS;
}

