#define GPIO_PIN 17
#define GPIO_LINE_NAME "flame_sensor"
#define LOG_FILE "flame_log.txt"

static int line = -1;
static int chip = -1;
static FILE *log_file = NULL;
static int flame_detected = 0;

void handle_signal(int sig) {
    if (line >= 0) {
        gpiod_line_release(line);
        line = -1;
    }
    if (chip >= 0) {
        gpiod_chip_close(chip);
        chip = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(0);
}

void log_flame_detection() {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "[%s] FLAME DETECTED\n", timestamp);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (line < 0) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, GPIO_LINE_NAME, GPIOD_LINE_REQUEST_FLAG_NONE) < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line value\n");
            break;
        }

        if (value == 0 && !flame_detected) {
            printf("FLAME DETECTED\n");
            log_flame_detection();
            flame_detected = 1;
        } else if (value == 1) {
            flame_detected = 0;
        }

        usleep(100000); // Poll every 100 ms
    }

    handle_signal(0);
    return EXIT_SUCCESS;
}

