#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_CHANNELS 8
#define OUTPUT_CHANNELS 8
#define POLL_INTERVAL 10
#define STABILIZATION_DELAY 200

static int chip;
static struct gpiod_line *sensor_lines[SENSOR_CHANNELS];
static struct gpiod_line *output_lines[OUTPUT_CHANNELS];
static int counter = 0;
static FILE *log_file = NULL;

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    for (int i = 0; i < SENSOR_CHANNELS; i++) {
        gpiod_line_release(sensor_lines[i]);
    }
    for (int i = 0; i < OUTPUT_CHANNELS; i++) {
        gpiod_line_release(output_lines[i]);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    for (int i = 0; i < OUTPUT_CHANNELS; i++) {
        gpiod_line_set_value(output_lines[i], 0);
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(0);
}

void log_event(int channel, int value) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

    if (log_file) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, value);
        fflush(log_file);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int sensor_pins[SENSOR_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
    int output_pins[OUTPUT_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

    for (int i = 0; i < SENSOR_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Failed to get sensor line %d: %s\n", sensor_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_input(sensor_lines[i], "sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES)) {
            fprintf(stderr, "Failed to request sensor line %d: %s\n", sensor_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < OUTPUT_CHANNELS; i++) {
        output_lines[i] = gpiod_chip_get_line(chip, output_pins[i]);
        if (!output_lines[i]) {
            fprintf(stderr, "Failed to get output line %d: %s\n", output_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(output_lines[i], "output", 0)) {
            fprintf(stderr, "Failed to request output line %d: %s\n", output_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    if (asprintf(&log_file, "touch_log.txt") < 0) {
        fprintf(stderr, "Failed to allocate memory for log file name: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(log_file, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
    }

    usleep(STABILIZATION_DELAY * 1000);

    while (1) {
        for (int i = 0; i < SENSOR_CHANNELS; i++) {
            struct gpiod_line_event event;
            int ret = gpiod_line_event_wait(sensor_lines[i], POLL_INTERVAL * 1000, &event);
            if (ret < 0) {
                fprintf(stderr, "Error reading sensor line %d: %s\n", sensor_pins[i], strerror(errno));
                continue;
            }

            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                counter = (counter + 1) % 256;
                char buffer[OUTPUT_CHANNELS + 1];
                memset(buffer, 0, sizeof(buffer));
                buffer[OUTPUT_CHANNELS - counter % OUTPUT_CHANNELS - 1] = 1;

                for (int j = 0; j < OUTPUT_CHANNELS; j++) {
                    if (gpiod_line_set_value(output_lines[j], buffer[j])) {
                        fprintf(stderr, "Failed to set output line %d: %s\n", output_pins[j], strerror(errno));
                    }
                }

                log_event(i + 1, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

