        if (gpiod_line_request_input(sensor_lines[i], "sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES)) {
            fprintf(stderr, "Failed to request sensor line %d: %s\n", sensor_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < OUTPUT_CHANNELS; i++) {
        output_lines[i] = gpiod_chip_get_line(chip, output_pins[i]);
        if (!output_lines[i]) {
            fprintf(stderr, "Failed to get output line %d: %s\n", output_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(output_lines[i], "output", 0)) {
            fprintf(stderr, "Failed to request output line %d: %s\n", output_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    if (asprintf(&log_file, "touch_log.txt") < 0) {
        fprintf(stderr, "Failed to allocate memory for log file name: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(log_file, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
    }

    usleep(STABILIZATION_DELAY * 1000);

    while (1) {
        for (int i = 0; i < SENSOR_CHANNELS; i++) {
            struct gpiod_line_event event;
            int ret = gpiod_line_event_wait(sensor_lines[i], POLL_INTERVAL * 1000, &event);
            if (ret < 0) {
                fprintf(stderr, "Error reading sensor line %d: %s\n", sensor_pins[i], strerror(errno));
                continue;
            }

            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                counter = (counter + 1) % 256;
                char buffer[OUTPUT_CHANNELS + 1];
                memset(buffer, 0, sizeof(buffer));
                buffer[OUTPUT_CHANNELS - counter % OUTPUT_CHANNELS - 1] = 1;

                for (int j = 0; j < OUTPUT_CHANNELS; j++) {
                    if (gpiod_line_set_value(output_lines[j], buffer[j])) {
                        fprintf(stderr, "Failed to set output line %d: %s\n", output_pins[j], strerror(errno));
                    }
                }

                log_event(i + 1, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}
```

This code sets up the GPIO lines for both input (sensor) and output (counter) on a Raspberry Pi Zero W, handles touch events, updates the counter, logs events, and handles signals for graceful shutdown. It uses the `libgpiod` library for GPIO operations and ensures proper error handling and resource cleanup.

