#include <gpiod.h>

#define GPIO17 17
#define GPIO18 18
#define POLL_INTERVAL 100000000 // 100 ms in nanoseconds
#define DEBOUNCE_WINDOW 50000000 // 50 ms in nanoseconds

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line18 = NULL;
static FILE *log_file = NULL;

void handle_signal(int signum) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum == SIGINT ? 0 : 1);
}

void log_tilt_event(int sensor) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        fprintf(stderr, "Failed to get line for GPIO17\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO18);
    if (!line18) {
        fprintf(stderr, "Failed to get line for GPIO18\n");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line17, "tilt_sensor_1", GPIOD_LINE_REQ_DIR_NONE) < 0) {
        fprintf(stderr, "Failed to request line for GPIO17\n");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line18, "tilt_sensor_2", GPIOD_LINE_REQ_DIR_NONE) < 0) {
        fprintf(stderr, "Failed to request line for GPIO18\n");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_flags(line17, GPIOD_LINE_FLAG_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to set active low for GPIO17\n");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_flags(line18, GPIOD_LINE_FLAG_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to set active low for GPIO18\n");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen("/var/log/tilt_events.log", "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int last_state17 = 1;
    int last_state18 = 1;
    struct timespec last_time17, last_time18;
    clock_gettime(CLOCK_MONOTONIC, &last_time17);
    clock_gettime(CLOCK_MONOTONIC, &last_time18);

    while (1) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        int state17 = gpiod_line_get_value(line17);
        int state18 = gpiod_line_get_value(line18);

        if (state17 < 0 || state18 < 0) {
            fprintf(stderr, "Failed to read GPIO state\n");
            continue;
        }

        if (state17 == 0 && last_state17 == 1 && (now.tv_sec - last_time17.tv_sec) * 1e9 + (now.tv_nsec - last_time17.tv_nsec) > DEBOUNCE_WINDOW) {
            log_tilt_event(1);
            last_time17 = now;
        }

        if (state18 == 0 && last_state18 == 1 && (now.tv_sec - last_time18.tv_sec) * 1e9 + (now.tv_nsec - last_time18.tv_nsec) > DEBOUNCE_WINDOW) {
            log_tilt_event(2);
            last_time18 = now;
        }

        last_state17 = state17;
        last_state18 = state18;

        struct timespec poll_interval = { .tv_sec = POLL_INTERVAL / 1e9, .tv_nsec = POLL_INTERVAL % 1e9 };
        nanosleep(&poll_interval, NULL);
    }

    return EXIT_SUCCESS;
}

