        exit(EXIT_FAILURE);
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line || gpiod_line_request_input(sensor1_line, "sensor1", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        perror("Failed to setup sensor 1");
        exit(EXIT_FAILURE);
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line || gpiod_line_request_input(sensor2_line, "sensor2", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        perror("Failed to setup sensor 2");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line || gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to setup LED");
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    setup_gpio();

    log_fd = open("obstacle_log.csv", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        int sensor1_value = gpiod_line_get_value(sensor1_line);
        int sensor2_value = gpiod_line_get_value(sensor2_line);

        int led_state = (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
        gpiod_line_set_value(led_line, led_state);

        log_data(sensor1_value, sensor2_value, led_state);

        struct timespec ts = {0, POLL_INTERVAL};
        nanosleep(&ts, NULL);
    }

    // Turn off LED on exit
    gpiod_line_set_value(led_line, 0);

    cleanup_gpio();

    if (log_fd >= 0) {
        close(log_fd);
    }

    return 0;
}
