    led_line = gpiod_chip_get_line(chip, 17);
    if (!led_line) {
        fprintf(stderr, "Failed to get line for GPIO17\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure microphone line as input
    ret = gpiod_line_request_input(mic_line, "mic_input", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request microphone line as input\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure LED line as output
    ret = gpiod_line_request_output(led_line, "led_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set LED to off initially
    gpiod_line_set_value(led_line, 0);

    // Sampling loop
    while (!stop_flag) {
        // Read microphone value
        mic_value = gpiod_line_get_value(mic_line);
        if (mic_value < 0) {
            fprintf(stderr, "Failed to read microphone value\n");
            break;
        }

        // Check for sound peak
        if (mic_value) {
            // Get current time
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                perror("clock_gettime");
                break;
            }

            // Print timestamp
            printf("%ld.%09ld\n", ts.tv_sec, ts.tv_nsec);

            // Turn on LED
            gpiod_line_set_value(led_line, 1);

            // Record start time
            clock_gettime(CLOCK_REALTIME, &start_time);

            // Wait for 100 ms
            do {
                clock_gettime(CLOCK_REALTIME, &end_time);
            } while ((end_time.tv_sec - start_time.tv_sec) * 1000000000L + (end_time.tv_nsec - start_time.tv_nsec) < 100000000);

            // Turn off LED
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 125 microseconds
        nanosleep(&ts, NULL);
        ts.tv_nsec += 125000; // 125 microseconds
        if (ts.tv_nsec >= 1000000000L) {
            ts.tv_nsec -= 1000000000L;
            ts.tv_sec += 1;
        }
    }

    // Clean up
    gpiod_line_release(mic_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

