#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x39 // Default I2C address for Si1175
#define ALS_LSB_REG 0x02
#define ALS_MSB_REG 0x03
#define INTERVAL 100 // 100 ms

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_init(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

int read_als(int fd, uint16_t *als_value) {
    uint8_t buffer[2];
    int ret;

    // Read LSB
    ret = read(fd, buffer, 1);
    if (ret != 1) {
        perror("Failed to read ALS LSB");
        return -1;
    }

    // Read MSB
    ret = read(fd, buffer + 1, 1);
    if (ret != 1) {
        perror("Failed to read ALS MSB");
        return -1;
    }

    *als_value = (buffer[1] << 8) | buffer[0];
    return 0;
}

int main() {
    int i2c_fd;
    uint16_t als_value;
    struct sigaction sa;

    // Setup signal handler for Ctrl+C
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        if (read_als(i2c_fd, &als_value) == 0) {
            printf("ALS Raw Value: %u\n", als_value);
        } else {
            fprintf(stderr, "Error reading ALS data\n");
        }

        usleep(INTERVAL * 1000); // Sleep for 100 ms
    }

    // Clean up
    close(i2c_fd);
    return EXIT_SUCCESS;
}

