#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define POLL_INTERVAL_MS 200

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    struct timespec ts;
    struct gpiod_chip *chip;
    struct gpiod_line *lines[8];
    int line_offset[] = {5, 6, 13, 19, 26, 12, 16, 20};
    int line_values[8];
    int ret;

    // Install signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    for (int i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, line_offset[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", line_offset[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        ret = gpiod_line_request_input(lines[i], "touch_poll", GPIOD_LINE_REQ_EV_NONE);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d\n", line_offset[i]);
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    while (keep_running) {
        // Get monotonic timestamp
        if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
            fprintf(stderr, "Failed to get monotonic time\n");
            break;
        }

        // Read lines
        for (int i = 0; i < 8; i++) {
            line_values[i] = gpiod_line_get_value(lines[i]);
            if (line_values[i] < 0) {
                fprintf(stderr, "Failed to read line %d\n", line_offset[i]);
                break;
            }
        }

        // Print values
        printf("[%f] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               ts.tv_sec + ts.tv_nsec / 1e9, line_values[0], line_values[1],
               line_values[2], line_values[3], line_values[4], line_values[5],
               line_values[6], line_values[7]);

        // Sleep for the poll interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Release resources
    for (int i = 0; i < 8; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

