#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>
#include <time.h>

#define PWM_FREQ 1000
#define PWM_RANGE 255
#define PWM_PERIOD (1000000 / PWM_FREQ)
#define NUM_STEPS 50
#define FADE_DURATION 5

static struct gpiod_chip *chip;
static struct gpiod_line *red_line, *green_line, *blue_line;
static struct gpiod_line_request *red_req, *green_req, *blue_req;
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
}

void cleanup() {
    if (red_req) gpiod_line_release(red_req);
    if (green_req) gpiod_line_release(green_req);
    if (blue_req) gpiod_line_release(blue_req);
    if (chip) gpiod_chip_close(chip);
    closelog();
}

void fade_led(uint8_t start_red, uint8_t start_green, uint8_t start_blue, uint8_t end_red, uint8_t end_green, uint8_t end_blue) {
    uint8_t red, green, blue;
    int step;
    int delay = FADE_DURATION * 1000 / NUM_STEPS;

    for (step = 0; step <= NUM_STEPS && !stop; step++) {
        red = start_red + (end_red - start_red) * step / NUM_STEPS;
        green = start_green + (end_green - start_green) * step / NUM_STEPS;
        blue = start_blue + (end_blue - start_blue) * step / NUM_STEPS;

        gpiod_pwm_set_value(red_req, PWM_RANGE - red);
        gpiod_pwm_set_value(green_req, PWM_RANGE - green);
        gpiod_pwm_set_value(blue_req, PWM_RANGE - blue);

        usleep(delay * 1000);
    }
}

int main() {
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);
    if (setvbuf(stdout, NULL, _IONBF, 0) != 0) {
        log_error("Failed to set stdout to unbuffered");
    }

    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        log_error("Failed to set SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        log_error("Failed to set SIGTERM handler");
        cleanup();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, 17);
    green_line = gpiod_chip_get_line(chip, 18);
    blue_line = gpiod_chip_get_line(chip, 27);

    if (!red_line || !green_line || !blue_line) {
        log_error("Failed to get GPIO lines");
        cleanup();
        return EXIT_FAILURE;
    }

    red_req = gpiod_line_request(red_line, "red_pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    green_req = gpiod_line_request(green_line, "green_pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    blue_req = gpiod_line_request(blue_line, "blue_pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);

    if (!red_req || !green_req || !blue_req) {
        log_error("Failed to request GPIO lines");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_flags(red_req, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW) ||
        gpiod_line_set_flags(green_req, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW) ||
        gpiod_line_set_flags(blue_req, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        log_error("Failed to set active low flag");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_consumer_count(red_req, 1) ||
        gpiod_line_set_consumer_count(green_req, 1) ||
        gpiod_line_set_consumer_count(blue_req, 1)) {
        log_error("Failed to set consumer count");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_config(red_req, PWM_PERIOD, PWM_RANGE, 0) ||
        gpiod_line_request_config(green_req, PWM_PERIOD, PWM_RANGE, 0) ||
        gpiod_line_request_config(blue_req, PWM_PERIOD, PWM_RANGE, 0)) {
        log_error("Failed to configure PWM");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(red_req) ||
        gpiod_line_request(green_req) ||
        gpiod_line_request(blue_req)) {
        log_error("Failed to request GPIO lines");
        cleanup();
        return EXIT_FAILURE;
    }

    FILE *urandom = fopen("/dev/urandom", "rb");
    if (!urandom) {
        log_error("Failed to open /dev/urandom");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t start_red, start_green, start_blue, end_red, end_green, end_blue;
    srand((unsigned int)fgetc(urandom));
    fclose(urandom);

    while (!stop) {
        start_red = rand() % (PWM_RANGE + 1);
        start_green = rand() % (PWM_RANGE + 1);
        start_blue = rand() % (PWM_RANGE + 1);

        end_red = rand() % (PWM_RANGE + 1);
        end_green = rand() % (PWM_RANGE + 1);
        end_blue = rand() % (PWM_RANGE + 1);

        fade_led(start_red, start_green, start_blue, end_red, end_green, end_blue);
    }

    gpiod_pwm_set_value(red_req, 0);
    gpiod_pwm_set_value(green_req, 0);
    gpiod_pwm_set_value(blue_req, 0);

    cleanup();
    return EXIT_SUCCESS;
}

