#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <stdint.h>
#include <math.h>

#define BH1750_I2C_ADDR 0x23
#define BH1750_CMD_CONTINUOUS_HIGH_RES_MODE 0x10
#define I2C_BUS "/dev/i2c-1"
#define GPIO_PWM "/dev/pwmchip0"
#define PWM_CHANNEL 0
#define PWM_FREQUENCY 800000 // 800kHz for WS2812B
#define PWM_DUTY_CYCLE_MAX 1024
#define WS2812B_T0H_NS 350
#define WS2812B_T1H_NS 900
#define WS2812B_T0L_NS 800
#define WS2812B_T1L_NS 450
#define WS2812B_BIT_TIME_NS (1000000000 / PWM_FREQUENCY)
#define WS2812B_RESET_TIME_NS 50

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int i2c_write_read(int fd, uint8_t *write_buf, size_t write_len, uint8_t *read_buf, size_t read_len) {
    if (ioctl(fd, I2C_SLAVE, BH1750_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(fd, write_buf, write_len) != write_len) {
        perror("Failed to write to the i2c bus");
        return -1;
    }

    usleep(180000); // Wait 180 ms

    if (read(fd, read_buf, read_len) != read_len) {
        perror("Failed to read from the i2c bus");
        return -1;
    }

    return 0;
}

int setup_i2c() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }

    uint8_t cmd[] = {BH1750_CMD_CONTINUOUS_HIGH_RES_MODE};
    if (i2c_write_read(fd, cmd, sizeof(cmd), NULL, 0) < 0) {
        close(fd);
        return -1;
    }

    return fd;
}

int setup_pwm() {
    int fd = open(GPIO_PWM, O_RDWR);
    if (fd < 0) {
        perror("Failed to open PWM device");
        return -1;
    }

    struct pwm_chip_info info;
    if (ioctl(fd, PWM_GET_INFO, &info) < 0) {
        perror("Failed to get PWM info");
        close(fd);
        return -1;
    }

    struct pwm_config config;
    config.polarity = 0;
    config.flags = PWM_CONFIG_BIAS_DISABLE;
    config.period = PWM_FREQUENCY;
    config.duty_cycle = 0;

    if (ioctl(fd, PWM_CONFIG, PWM_CHANNEL, &config) < 0) {
        perror("Failed to configure PWM");
        close(fd);
        return -1;
    }

    if (ioctl(fd, PWM_ENABLE, PWM_CHANNEL) < 0) {
        perror("Failed to enable PWM");
        close(fd);
        return -1;
    }

    return fd;
}

void send_ws2812b_data(int pwm_fd, uint8_t *data, size_t len) {
    for (size_t i = 0; i < len; i++) {
        uint8_t byte = data[i];
        for (int bit = 7; bit >= 0; bit--) {
            uint8_t level = (byte & (1 << bit)) ? WS2812B_T1H_NS : WS2812B_T0H_NS;
            uint8_t width = level / WS2812B_BIT_TIME_NS;
            uint8_t duty_cycle = (width * PWM_DUTY_CYCLE_MAX) / 1000;

            struct pwm_set_data data;
            data.pulse = duty_cycle;
            data.led = 0;

            if (ioctl(pwm_fd, PWM_WRITE, PWM_CHANNEL, &data) < 0) {
                perror("Failed to write PWM data");
                return;
            }

            usleep(WS2812B_BIT_TIME_NS - WS2812B_RESET_TIME_NS);
        }
    }
}

void generate_led_pattern(int brightness) {
    uint8_t led_data[10 * 3] = {0};
    for (int i = 0; i < 10; i++) {
        uint8_t color = (uint8_t)(brightness * 255 / 100);
        led_data[i * 3] = 0xFF; // Red
        led_data[i * 3 + 1] = color; // Green
        led_data[i * 3 + 2] = 0x00; // Blue
    }
    send_ws2812b_data(pwm_fd, led_data, sizeof(led_data));
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = setup_i2c();
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    int pwm_fd = setup_pwm();
    if (pwm_fd < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t read_buf[2];
    while (!stop) {
        if (i2c_write_read(i2c_fd, NULL, 0, read_buf, sizeof(read_buf)) < 0) {
            fprintf(stderr, "I2C read error, retrying...\n");
            continue;
        }

        uint16_t lux = (read_buf[0] << 8) | read_buf[1];
        double brightness = log10(lux + 1) * 100 / log10(65535 + 1);

        generate_led_pattern(brightness);
    }

    close(pwm_fd);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

