#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x23
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define LED_COUNT 1

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_init(int *fd) {
    *fd = open(I2C_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(*fd);
        return -1;
    }

    return 0;
}

int i2c_read_light_level(int fd, uint16_t *light_level) {
    uint8_t buffer[2];
    uint8_t cmd = 0x20; // Power on and continuous high resolution mode

    if (write(fd, &cmd, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    usleep(120000); // Wait for conversion

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *light_level = (buffer[0] << 8) | buffer[1];
    return 0;
}

int spi_init(int *fd) {
    struct spi_ioc_transfer transfer;
    struct spi_ioc_rdwr rdwr;

    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0 ||
        ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0 ||
        ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI parameters");
        close(*fd);
        return -1;
    }

    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)malloc(4 * LED_COUNT);
    transfer.len = 4 * LED_COUNT;
    transfer.speed_hz = SPI_SPEED;
    transfer.bits_per_word = 8;

    memset(&rdwr, 0, sizeof(rdwr));
    rdwr.tx_buf = (unsigned long)transfer.tx_buf;
    rdwr.rx_buf = 0;
    rdwr.len = transfer.len;
    rdwr.speed_hz = transfer.speed_hz;
    rdwr.bits_per_word = transfer.bits_per_word;

    return 0;
}

void spi_close(int fd) {
    free((void *)(long)spi.xfer.tx_buf);
    close(fd);
}

void set_led_brightness(int fd, uint16_t light_level) {
    uint8_t *data = (uint8_t *)(long)spi.xfer.tx_buf;
    uint8_t brightness = (light_level > 65535) ? 31 : (light_level * 31) / 65535;

    // Start frame
    data[0] = 0x00;
    data[1] = 0x00;
    data[2] = 0x00;
    data[3] = 0x00;

    // LED frame
    data[4] = 0xE0 | brightness;
    data[5] = 0x00; // Blue
    data[6] = 0x00; // Green
