#define BH1750_ADDR1 0x23
#define BH1750_ADDR2 0x5C
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define LED_COUNT 30
#define FADE_DURATION 500
#define DELAY_BETWEEN_CYCLES 100
#define READ_DELAY 180

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void fade_brightness(int spi_handle, int target_brightness) {
    int current_brightness = 0;
    int step = (target_brightness - current_brightness) / (FADE_DURATION / DELAY_BETWEEN_CYCLES);
    for (int i = 0; i <= FADE_DURATION / DELAY_BETWEEN_CYCLES; i++) {
        current_brightness += step;
        if (current_brightness < 0) current_brightness = 0;
        if (current_brightness > 255) current_brightness = 255;
        for (int j = 0; j < LED_COUNT; j++) {
            pi_spi_writenb(spi_handle, &current_brightness, 1);
        }
        usleep(DELAY_BETWEEN_CYCLES * 1000);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int spi_handle = pi_spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        pi_spi_close(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[2];
    lines[0] = gpiod_chip_get_line(chip, BH1750_ADDR1);
    lines[1] = gpiod_chip_get_line(chip, BH1750_ADDR2);

    if (!lines[0] || !lines[1]) {
        fprintf(stderr, "Failed to get I2C lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        pi_spi_close(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(lines[0], "bh1750_1", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0 ||
        gpiod_line_request_output(lines[1], "bh1750_2", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0) {
        fprintf(stderr, "Failed to request I2C lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        pi_spi_close(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        int valid_readings = 0;
        int total_lux = 0;

        for (int i = 0; i < 2; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "Failed to set I2C line value: %s\n", strerror(errno));
                continue;
            }
            usleep(1000); // Power on time

            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set I2C line value: %s\n", strerror(errno));
                continue;
            }
            usleep(70000); // Measurement time

            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "Failed to set I2C line value: %s\n", strerror(errno));
                continue;
            }
            usleep(1000); // Wait for conversion

            uint16_t lux;
            if (gpiod_line_get_value(lines[i], &lux) < 0) {
                fprintf(stderr, "Failed to read I2C line value: %s\n", strerror(errno));
                continue;
            }

            total_lux += lux;
            valid_readings++;
        }

        int average_lux = valid_readings > 0 ? total_lux / valid_readings : 0;
        int target_brightness = average_lux > 65535 ? 255 : (average_lux * 255) / 65535;

        fade_brightness(spi_handle, target_brightness);

        usleep(DELAY_BETWEEN_CYCLES * 1000);
    }

    // Turn off the LED strip
    for (int i = 0; i < LED_COUNT; i++) {
        pi_spi_writenb(spi_handle, &target_brightness, 1);
    }

    gpiod_line_release(lines[0]);
    gpiod_line_release(lines[1]);
    gpiod_chip_close(chip);
    pi_spi_close(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

