#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <string.h>
#include <errno.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_REG_ID 0x00
#define VEML7700_REG_RESULT 0x04
#define VEML7700_REG_CONFIG 0x01
#define VEML7700_REG_CONFIG_POWERON 0x01
#define VEML7700_REG_CONFIG_CONTINUOUS 0x02
#define GPIO_PIN 18
#define WS2812B_T0H_NS 350
#define WS2812B_T1H_NS 900
#define WS2812B_T0L_NS 800
#define WS2812B_T1L_NS 450
#define WS2812B_BIT_PERIOD_NS 1000
#define WS2812B_LED_COUNT 1
#define WS2812B_COLOR_ORDER GRB
#define WS2812B_COLOR_CHANNELS 3
#define WS2812B_COLOR_BITS 8
#define WS2812B_COLOR_MAX 255
#define WS2812B_COLOR_SCALE 1.0
#define WS2812B_COLOR_OFFSET 0
#define WS2812B_COLOR_CORRECTION 2.8
#define WS2812B_COLOR_CORRECTION_OFFSET 0
#define WS2812B_COLOR_CORRECTION_SCALE 1.0
#define WS2812B_COLOR_CORRECTION_MAX 255
#define WS2812B_COLOR_CORRECTION_MIN 0
#define WS2812B_COLOR_CORRECTION_LEVELS 256
#define WS2812B_COLOR_CORRECTION_LEVELS_LOG2 8
#define WS2812B_COLOR_CORRECTION_LEVELS_MASK (WS2812B_COLOR_CORRECTION_LEVELS - 1)
#define WS2812B_COLOR_CORRECTION_LEVELS_SHIFT (8 - WS2812B_COLOR_CORRECTION_LEVELS_LOG2)
#define WS2812B_COLOR_CORRECTION_LEVELS_INV (1 << WS2812B_COLOR_CORRECTION_LEVELS_LOG2) - 1

static int i2c_fd = -1;
static int gpio_fd = -1;
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

uint8_t read_i2c_register(uint8_t reg) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write to I2C device");
        return 0;
    }
    if (read(i2c_fd, buffer, 1) != 1) {
        perror("Failed to read from I2C device");
        return 0;
    }
    return buffer[0];
}

int write_i2c_register(uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

uint16_t read_ambient_light() {
    uint8_t result_high = read_i2c_register(VEML7700_REG_RESULT);
    uint8_t result_low = read_i2c_register(VEML7700_REG_RESULT + 1);
    return (result_high << 8) | result_low;
}

void setup_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (write_i2c_register(VEML7700_REG_CONFIG, VEML7700_REG_CONFIG_POWERON | VEML7700_REG_CONFIG_CONTINUOUS) != 0) {
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_gpio() {
    gpio_fd = open("/sys/class/gpio/gpio" STRINGIFY(GPIO_PIN) "/value", O_WRONLY);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO value file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (gpio_fd >= 0) {
        close(gpio_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    write(gpio_fd, "0", 1);
}

uint8_t gamma_correct(uint8_t value) {
    uint16_t corrected = (uint16_t)value * (uint16_t)value * (uint16_t)value;
    return (uint8_t)(corrected >> 8);
}

void send_bit(int value) {
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    if (value) {
        write(gpio_fd, "1", 1);
        clock_gettime(CLOCK_MONOTONIC, &t1);
        while ((t1.tv_nsec - t0.tv_nsec) < WS2812B_T1H_NS) {
            clock_gettime(CLOCK_MONOTONIC, &t1);
        }
    } else {
        write(gpio_fd, "0", 1);
        clock_gettime(CLOCK_MONOTONIC, &t1);
        while ((t1.tv_nsec - t0.tv_nsec) < WS2812B_T0H_NS) {
            clock_gettime(CLOCK_MONOTONIC, &t1);
        }
    }
    write(gpio_fd, "0", 1);
    clock_gettime(CLOCK_MONOTONIC, &t1);
    while ((t1.tv_nsec - t0.tv_nsec) < WS2812B_BIT_PERIOD_NS) {
        clock_gettime(CLOCK_MONOTONIC, &t1);
    }
}

void send_color(uint8_t r, uint8_t g, uint8_t b) {
    for (int i = 7; i >= 0; i--) {
        send_bit((r >> i) & 1);
        send_bit((g >> i) & 1);
        send_bit((b >> i) & 1);
    }
}

void drive_led_strip(uint16_t lux) {
    uint8_t brightness = gamma_correct((uint8_t)(lux / 100.0 * WS2812B_COLOR_MAX));
    send_color(brightness, brightness, brightness);
}

int main() {
