uint8_t read_i2c_register(uint8_t reg) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write to I2C device");
        return 0;
    }
    if (read(i2c_fd, buffer, 1) != 1) {
        perror("Failed to read from I2C device");
        return 0;
    }
    return buffer[0];
}

int write_i2c_register(uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

uint16_t read_ambient_light() {
    uint8_t result_high = read_i2c_register(VEML7700_REG_RESULT);
    uint8_t result_low = read_i2c_register(VEML7700_REG_RESULT + 1);
    return (result_high << 8) | result_low;
}

