    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    write(gpio_fd, "0", 1);
}

uint8_t gamma_correct(uint8_t value) {
    uint16_t corrected = (uint16_t)value * (uint16_t)value * (uint16_t)value;
    return (uint8_t)(corrected >> 8);
}

void send_bit(int value) {
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    if (value) {
        write(gpio_fd, "1", 1);
        clock_gettime(CLOCK_MONOTONIC, &t1);
        while ((t1.tv_nsec - t0.tv_nsec) < WS2812B_T1H_NS) {
            clock_gettime(CLOCK_MONOTONIC, &t1);
        }
    } else {
