    for (int i = 7; i >= 0; i--) {
        send_bit((r >> i) & 1);
        send_bit((g >> i) & 1);
        send_bit((b >> i) & 1);
    }
}

void drive_led_strip(uint16_t lux) {
    uint8_t brightness = gamma_correct((uint8_t)(lux / 100.0 * WS2812B_COLOR_MAX));
    send_color(brightness, brightness, brightness);
}

