int configure_line(gpiod_line *line, int flags) {
    if (gpiod_line_request(line, "app", flags) < 0) {
        fprintf(stderr, "Failed to request line\n");
        return -1;
    }
    return 0;
}

void cleanup(gpiod_line *flame_sensor, gpiod_line *buzzer, gpiod_line *led) {
    if (flame_sensor) gpiod_line_release(flame_sensor);
    if (buzzer) gpiod_line_release(buzzer);
    if (led) gpiod_line_release(led);
}

void blink_led(gpiod_line *led, int on_time, int off_time, int cycles) {
    for (int i = 0; i < cycles; i++) {
        gpiod_line_set_value(led, 1);
        usleep(on_time * 1000);
        gpiod_line_set_value(led, 0);
        usleep(off_time * 1000);
    }
}

