    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

void cleanup_i2c(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

int read_light_sensor(int i2c_fd) {
    uint8_t cmd = BH1750_CMD_CONT_HIGH_RES_MODE;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    int lux = (data[0] << 8) | data[1];
    return lux / 1.2; // Convert to lux
}

void blink_led(int gpio_fd, int frequency) {
    struct gpiohandle_data data = {0};
    int period = 1000000000 / (frequency * 2); // nanoseconds per half cycle

    data.values[0] = 1;
    if (write(gpio_fd, &data, sizeof(data)) < 0) {
        perror("Failed to set GPIO value");
        return;
    }
    usleep(period / 1000);

    data.values[0] = 0;
    if (write(gpio_fd, &data, sizeof(data)) < 0) {
        perror("Failed to set GPIO value");
        return;
    }
    usleep(period / 1000);
}

int main() {
    signal(SIGINT, handle_sigint);

    int gpio_fd = init_gpio();
    if (gpio_fd < 0) {
        return EXIT_FAILURE;
    }

    int i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        cleanup_gpio(gpio_fd);
        return EXIT_FAILURE;
    }

    int buffer[BUFFER_SIZE] = {0};
    int buffer_index = 0;
    int sum = 0;

    while (keep_running) {
        int lux = read_light_sensor(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Error reading light sensor, skipping sample\n");
        } else {
            sum -= buffer[buffer_index];
            buffer[buffer_index] = lux;
            sum += lux;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        }

        double average_lux = sum / (double)BUFFER_SIZE;
        double frequency = 0.5 + (average_lux / 1000.0) * 4.5;
        frequency = frequency > 5.0 ? 5.0 : frequency;

        blink_led(gpio_fd, (int)frequency);

        usleep(1000000); // Sleep for 1 second
    }

    cleanup_gpio(gpio_fd);
    cleanup_i2c(i2c_fd);

    return EXIT_SUCCESS;
}
