        int bit = (value >> (NUM_BITS - 1 - i)) & 0x01;
        gpiod_line_set_value(data_line, bit);
        if (gpiod_line_set_value(clock_line, 1) < 0) {
            error_exit("Failed to set clock high");
        }
        if (gpiod_line_set_value(clock_line, 0) < 0) {
            error_exit("Failed to set clock low");
        }
