    if (!chip) {
        error_exit("Failed to open GPIO chip");
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    if (!data_line) {
        gpiod_chip_close(chip);
        error_exit("Failed to get data line");
    }
    if (gpiod_line_request_output(data_line, "data", 0) < 0) {
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        error_exit("Failed to request data line as output");
    }

    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    if (!clock_line) {
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        error_exit("Failed to get clock line");
    }
    if (gpiod_line_request_output(clock_line, "clock", 0) < 0) {
        gpiod_line_release(clock_line);
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        error_exit("Failed to request clock line as output");
    }

    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!latch_line) {
        gpiod_line_release(clock_line);
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        error_exit("Failed to get latch line");
    }
    if (gpiod_line_request_output(latch_line, "latch", 0) < 0) {
        gpiod_line_release(latch_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        error_exit("Failed to request latch line as output");
    }

    while (1) {
        shift_out(data_line, clock_line, latch_line, digit_5);
        usleep(500000); // 500 ms

        shift_out(data_line, clock_line, latch_line, 0x00);
        usleep(500000); // 500 ms
    }

    gpiod_line_release(latch_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(data_line);
    gpiod_chip_close(chip);

    return 0;
}

