#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *button_line;
    int ret;

    // Set up signal handler for graceful termination
    signal(SIGINT, handle_signal);

    // Open GPIO chip 0
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO17 as an output line, initially set low
    led_line = gpiod_chip_get_line(chip, 17);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO18 as an input line with pull-up and falling-edge detection
    button_line = gpiod_chip_get_line(chip, 18);
    if (!button_line) {
        perror("Failed to get button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(button_line, "button", GPIOD_LINE_REQUEST_DIRECTIONS);
    if (ret < 0) {
        perror("Failed to request button line as input");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_both_edges(button_line, 0);
    if (ret < 0) {
        perror("Failed to set both edges on button line");
        gpiod_line_release(button_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_rising_edge_events(button_line, 0);
    if (ret < 0) {
        perror("Failed to request rising edge events on button line");
        gpiod_line_release(button_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Blink LED with 2-second period (1 second on, 1 second off)
    while (keep_running) {
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("Failed to set LED value to high");
            break;
        }

        ret = gpiod_line_event_wait(button_line, 1000000); // 1-second timeout
        if (ret > 0) {
            // Falling edge detected
            break;
        } else if (ret < 0) {
            perror("Failed to wait for button event");
            break;
        }

        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("Failed to set LED value to low");
            break;
        }

        ret = gpiod_line_event_wait(button_line, 1000000); // 1-second timeout
        if (ret > 0) {
            // Falling edge detected
            break;
        } else if (ret < 0) {
            perror("Failed to wait for button event");
            break;
        }
    }

    // Turn off LED and print message if button was pressed
    gpiod_line_set_value(led_line, 0);
    if (ret > 0) {
        printf("Button pressed, stopping blink and exiting.\n");
    }

    // Release resources
    gpiod_line_release(button_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

