#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN 5
#define GPIO_CHIP "gpiochip0"
#define LED_ON_DELAY 750000000 // 750 ms in nanoseconds
#define LED_OFF_DELAY 750000000 // 750 ms in nanoseconds

static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void handle_sigint(int sig) {
    keep_running = 0;
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct gpiod_line_request req = {
        .consumer = "led_blinker",
        .type = GPIOD_LINE_REQ_DIR_OUT,
        .flags = GPIOD_LINE_REQUEST_DIRECTIONS,
    };

    // Register signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get line for GPIO5
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO5\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request line
    if (gpiod_line_request(line, &req) < 0) {
        fprintf(stderr, "Failed to request line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Blink LED
    while (keep_running) {
        // Turn LED on
        gpiod_line_set_value(line, 1);
        printf("LED ON\n");
        fflush(stdout);
        gpiod_line_sleep(line, LED_ON_DELAY);

        if (!keep_running) break;

        // Turn LED off
        gpiod_line_set_value(line, 0);
        printf("LED OFF\n");
        fflush(stdout);
        gpiod_line_sleep(line, LED_OFF_DELAY);
    }

    // Cleanup
    cleanup();
    return EXIT_SUCCESS;
}

