This program uses the `libgpiod` library to control the GPIO pins on a Raspberry Pi. It blinks an LED connected to GPIO5 with a 750 ms on and off delay, handles SIGINT to clean up resources, and ensures proper error handling and resource management.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 24
#define BUTTON_PIN 22
#define LED_ON 1
#define LED_OFF 0
#define BLINK_INTERVAL 500000000 // 500 ms in nanoseconds

static volatile int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *button_line;

void handle_signal(int sig) {
    keep_running = 0;
}

void check_error(int err, const char *msg) {
    if (err < 0) {
        fprintf(stderr, "%s: %s\n", msg, gpiod_strerror(err));
        exit(EXIT_FAILURE);
    }
}

int main() {
    struct gpiod_line_request req;
    struct gpiod_line_event event;
    int ret;

    // Set up signal handling for graceful exit
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    check_error(chip ? 0 : -errno, "Failed to open GPIO chip");

    // Get the LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    check_error(led_line, "Failed to get LED line");

    // Get the button line
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    check_error(button_line, "Failed to get button line");

    // Configure LED as output, initially low
    ret = gpiod_line_request_output(led_line, "led_control", LED_OFF, 0);
    check_error(ret, "Failed to request LED line as output");

    // Configure button as input with pull-down
    ret = gpiod_line_request_input(button_line, "button_control", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    check_error(ret, "Failed to request button line as input");

    // Main loop
    while (keep_running) {
        // Wait for button press event
        ret = gpiod_line_event_wait(button_line, &event, -1);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for button event: %s\n", gpiod_strerror(ret));
            break;
        }

        // Check if button is pressed
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Button pressed, start blinking
            while (keep_running) {
                // Turn LED on
                ret = gpiod_line_set_value(led_line, LED_ON);
                check_error(ret, "Failed to set LED value to ON");

                // Wait for 500 ms
                usleep(BLINK_INTERVAL / 1000);

                // Check if button is still pressed
                if (gpiod_line_event_wait(button_line, &event, 0) < 0 || event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
