#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18
#define PWM_PERIOD_NS 10000000 // 10 ms
#define PWM_FREQUENCY 100 // 100 Hz
#define PWM_DUTY_CYCLE_MAX 100
#define COLOR_CHANGE_INTERVAL_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *red_line, *green_line, *blue_line;
static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    exit(signum);
}

void setup_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
}

int main() {
    srand(time(NULL));
    setup_signal_handler();

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    if (!red_line || gpiod_line_request_output(red_line, "red", 0) < 0) {
        fprintf(stderr, "Failed to configure red line: %s\n", gpiod_strerror(gpiod_line_request_output(red_line, "red", 0)));
        cleanup_and_exit(EXIT_FAILURE);
    }

    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    if (!green_line || gpiod_line_request_output(green_line, "green", 0) < 0) {
        fprintf(stderr, "Failed to configure green line: %s\n", gpiod_strerror(gpiod_line_request_output(green_line, "green", 0)));
        cleanup_and_exit(EXIT_FAILURE);
    }

    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!blue_line || gpiod_line_request_output(blue_line, "blue", 0) < 0) {
        fprintf(stderr, "Failed to configure blue line: %s\n", gpiod_strerror(gpiod_line_request_output(blue_line, "blue", 0)));
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (keep_running) {
        int red_intensity = rand() % (PWM_DUTY_CYCLE_MAX + 1);
        int green_intensity = rand() % (PWM_DUTY_CYCLE_MAX + 1);
        int blue_intensity = rand() % (PWM_DUTY_CYCLE_MAX + 1);

        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = PWM_PERIOD_NS / PWM_DUTY_CYCLE_MAX * red_intensity;
        gpiod_line_set_value(red_line, 1);
        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
        gpiod_line_set_value(red_line, 0);

        ts.tv_nsec = PWM_PERIOD_NS / PWM_DUTY_CYCLE_MAX * green_intensity;
        gpiod_line_set_value(green_line, 1);
        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
        gpiod_line_set_value(green_line, 0);

        ts.tv_nsec = PWM_PERIOD_NS / PWM_DUTY_CYCLE_MAX * blue_intensity;
        gpiod_line_set_value(blue_line, 1);
        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
        gpiod_line_set_value(blue_line, 0);

        struct timespec interval;
        interval.tv_sec = 0;
        interval.tv_nsec = COLOR_CHANGE_INTERVAL_MS * 1000000;
        clock_nanosleep(CLOCK_MONOTONIC, 0, &interval, NULL);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

