#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define LSM303_ADDR 0x19
#define GPIO_PIN 17
#define DEFAULT_THRESHOLD 2.0
#define PULSE_DURATION 50 // milliseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

double compute_g_force(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z) / 16384.0; // Assuming 2g range
}

void trigger_impact(gpiod_chip *chip, gpiod_line *line) {
    gpiod_line_request_config req = {
        .consumer = "impact_trigger",
        .request_type = GPIOD_LINE_REQ_DIR_OUT,
        .default_value = 0
    };
    if (gpiod_line_request(line, &req) < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(line, 1);
    usleep(PULSE_DURATION * 1000);
    gpiod_line_set_value(line, 0);

    gpiod_line_release(line);
}

void log_accel_data(FILE *log_file, int16_t x, int16_t y, int16_t z, double g_force) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s - X: %d, Y: %d, Z: %d, G-force: %.2f\n", time_str, x, y, z, g_force);
    fflush(log_file);
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t buffer[6];
    while (keep_running) {
        if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
            perror("Failed to read from I2C device");
            break;
        }

        int16_t x = (buffer[1] << 8) | buffer[0];
        int16_t y = (buffer[3] << 8) | buffer[2];
        int16_t z = (buffer[5] << 8) | buffer[4];

        double g_force = compute_g_force(x, y, z);
        log_accel_data(log_file, x, y, z, g_force);

        if (g_force > threshold) {
            trigger_impact(chip, line);
        }

        usleep(100000); // 10 Hz polling
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

