#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <syslog.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define ADPD188BI_ADDR 0x48
#define GPIO_LED 18
#define PWM_PERIOD 1000000 // 1 second period for PWM
#define PWM_DUTY_MAX 1000000 // Max duty cycle for PWM

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_gpio_pwm(gpiod_chip *chip, gpiod_line *line) {
    line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", GPIO_LED);
        return -1;
    }

    if (gpiod_line_request(line, "led_pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0) {
        fprintf(stderr, "Failed to request line for GPIO %d\n", GPIO_LED);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

int setup_i2c(int *fd) {
    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, ADPD188BI_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(*fd);
        return -1;
    }

    return 0;
}

int read_sensor(int fd, uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buffer[8];
    int ret;

    ret = read(fd, buffer, sizeof(buffer));
    if (ret < 0) {
        perror("Failed to read from I2C device");
        return -1;
    } else if (ret != sizeof(buffer)) {
        fprintf(stderr, "Unexpected read size: %d\n", ret);
        return -1;
    }

    *als = (buffer[0] << 8) | buffer[1];
    *red = (buffer[2] << 8) | buffer[3];
    *green = (buffer[4] << 8) | buffer[5];
    *blue = (buffer[6] << 8) | buffer[7];

    return 0;
}

void log_data(FILE *file, time_t timestamp, uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    fprintf(file, "%ld,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(file);
}

void adjust_led_brightness(gpiod_line *line, uint16_t als) {
    uint32_t duty_cycle = (als * PWM_DUTY_MAX) / 0xFFFF;
    gpiod_line_set_value_with_flags(line, duty_cycle, GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
}

int main() {
    int i2c_fd;
    gpiod_chip *chip;
    gpiod_line *line;
    FILE *file;
    struct timespec ts;
    uint16_t als, red, green, blue;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (setup_i2c(&i2c_fd) < 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (setup_gpio_pwm(chip, line) < 0) {
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    file = fopen("color_log.csv", "w");
    if (!file) {
        perror("Failed to open CSV file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(file, "timestamp,als,red,green,blue\n");
    fflush(file);

