#define GPIO_LED 18
#define PWM_PERIOD 1000000 // 1 second period for PWM
#define PWM_DUTY_MAX 1000000 // Max duty cycle for PWM

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_gpio_pwm(gpiod_chip *chip, gpiod_line *line) {
    line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", GPIO_LED);
        return -1;
    }

    if (gpiod_line_request(line, "led_pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0) {
        fprintf(stderr, "Failed to request line for GPIO %d\n", GPIO_LED);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

int setup_i2c(int *fd) {
    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, ADPD188BI_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(*fd);
        return -1;
    }

    return 0;
}

int read_sensor(int fd, uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buffer[8];
    int ret;

    ret = read(fd, buffer, sizeof(buffer));
    if (ret < 0) {
        perror("Failed to read from I2C device");
        return -1;
    } else if (ret != sizeof(buffer)) {
        fprintf(stderr, "Unexpected read size: %d\n", ret);
        return -1;
    }

    *als = (buffer[0] << 8) | buffer[1];
    *red = (buffer[2] << 8) | buffer[3];
    *green = (buffer[4] << 8) | buffer[5];
    *blue = (buffer[6] << 8) | buffer[7];

    return 0;
}

void log_data(FILE *file, time_t timestamp, uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    fprintf(file, "%ld,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(file);
}

void adjust_led_brightness(gpiod_line *line, uint16_t als) {
    uint32_t duty_cycle = (als * PWM_DUTY_MAX) / 0xFFFF;
    gpiod_line_set_value_with_flags(line, duty_cycle, GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
}

