        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(file, "timestamp,als,red,green,blue\n");
    fflush(file);

    while (keep_running) {
        if (read_sensor(i2c_fd, &als, &red, &green, &blue) < 0) {
