#define FXOS8700CQ_WHO_AM_I 0x0D
#define FXOS8700CQ_WHO_AM_I_VALUE 0xC7
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_CTRL_REG2 0x2B
#define FXOS8700CQ_CTRL_REG3 0x2C
#define FXOS8700CQ_STATUS_REG 0x27
#define FXOS8700CQ_OUT_X_MSB 0x01
#define IMPACT_THRESHOLD 2.0
#define I2C_BUS 1

static volatile int keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_write_byte_data(int file, uint8_t reg, uint8_t value) {
    int ret = i2c_smbus_write_byte_data(file, reg, value);
    if (ret < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
    }
    return ret;
}

int i2c_read_byte_data(int file, uint8_t reg, uint8_t *value) {
    int ret = i2c_smbus_read_byte_data(file, reg, value);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
    }
    return ret;
}

int i2c_read_i2c_block_data(int file, uint8_t reg, uint8_t *values, int length) {
    int ret = i2c_smbus_read_i2c_block_data(file, reg, length, values);
    if (ret < 0) {
        fprintf(stderr, "I2C block read error: %s\n", strerror(errno));
    }
    return ret;
}

double compute_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z) / 16384.0; // ±2g range, 14-bit resolution
}

void log_impact(int16_t x, int16_t y, int16_t z, double magnitude) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *log_file = fopen("impact_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x / 16.0, y / 16.0, z / 16.0, magnitude);
        fclose(log_file);
    } else {
        fprintf(stderr, "Failed to open impact_log.txt for writing\n");
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int file = open("/dev/i2c-" + std::to_string(I2C_BUS), O_RDWR);
    if (file < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, FXOS8700CQ_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        close(file);
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (i2c_read_byte_data(file, FXOS8700CQ_WHO_AM_I, &who_am_i) < 0 || who_am_i != FXOS8700CQ_WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I check failed\n");
        close(file);
        return EXIT_FAILURE;
    }

    i2c_write_byte_data(file, FXOS8700CQ_CTRL_REG1, 0x00); // Standby mode
    i2c_write_byte_data(file, FXOS8700CQ_CTRL_REG2, 0x00); // ±2g range
    i2c_write_byte_data(file, FXOS8700CQ_CTRL_REG3, 0x08); // 200 Hz data rate

    while (keep_running) {
        uint8_t status;
        if (i2c_read_byte_data(file, FXOS8700CQ_STATUS_REG, &status) < 0) {
            continue;
        }

        if (status & 0x01) { // Data ready
            uint8_t data[6];
            if (i2c_read_i2c_block_data(file, FXOS8700CQ_OUT_X_MSB, data, 6) < 0) {
                continue;
            }

            int16_t x = (data[1] << 8) | data[0];
            int16_t y = (data[3] << 8) | data[2];
            int16_t z = (data[5] << 8) | data[4];

            double magnitude = compute_magnitude(x, y, z);
            if (magnitude > IMPACT_THRESHOLD) {
                log_impact(x, y, z, magnitude);
            }
        }

        usleep(50000); // 50 ms interval
    }

    close(file);
    return EXIT_SUCCESS;
}

