#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>

#define I2C_BUS "/dev/i2c-1"
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xD4
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_Y_L 0x2A
#define OUT_Z_L 0x2C
#define SAMPLES 100
#define LOG_FILE "gyro_log.txt"
#define ALERT_THRESHOLD 50.0

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int open_i2c_device(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_register(int fd, uint8_t reg) {
    uint8_t buffer[1] = {reg};
    if (write(fd, buffer, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    buffer[0] = 0;
    if (read(fd, buffer, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }

    return buffer[0];
}

int read_16bit(int fd, uint8_t reg) {
    uint8_t buffer[2];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read register value");
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

void log_message(FILE *log_file, const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open_i2c_device(I2C_BUS, GYRO_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    int who_am_i = read_register(i2c_fd, WHO_AM_I_REG);
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Sensor not detected. WHO_AM_I = 0x%02X\n", who_am_i);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t ctrl_reg1 = 0x0F; // Normal power mode, all axes enabled
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("Failed to write CTRL_REG1");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t ctrl_reg4 = 0x20; // 200 dps full scale
    if (write(i2c_fd, &ctrl_reg4, 1) != 1) {
        perror("Failed to write CTRL_REG4");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    double offsets[3] = {0.0, 0.0, 0.0};
    for (int i = 0; i < SAMPLES; i++) {
        int16_t x = read_16bit(i2c_fd, OUT_X_L);
        int16_t y = read_16bit(i2c_fd, OUT_Y_L);
        int16_t z = read_16bit(i2c_fd, OUT_Z_L);

        offsets[0] += x;
        offsets[1] += y;
        offsets[2] += z;

        usleep(10000); // 10 ms delay
    }

    offsets[0] /= SAMPLES;
    offsets[1] /= SAMPLES;
    offsets[2] /= SAMPLES;

    while (!stop) {
        int16_t x = read_16bit(i2c_fd, OUT_X_L) - offsets[0];
        int16_t y = read_16bit(i2c_fd, OUT_Y_L) - offsets[1];
        int16_t z = read_16bit(i2c_fd, OUT_Z_L) - offsets[2];

        double x_dps = x * 8.75 / 1000.0;
        double y_dps = y * 8.75 / 1000.0;
        double z_dps = z * 8.75 / 1000.0;

        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "X: %.2f Y: %.2f Z: %.2f", x_dps, y_dps, z_dps);
        log_message(log_file, log_buffer);

        if (fabs(x_dps) > ALERT_THRESHOLD || fabs(y_dps) > ALERT_THRESHOLD || fabs(z_dps) > ALERT_THRESHOLD) {
            snprintf(log_buffer, sizeof(log_buffer), "ALERT: X: %.2f Y: %.2f Z: %.2f", x_dps, y_dps, z_dps);
            log_message(log_file, log_buffer);
            fprintf(stderr, "Warning: Axis exceeded threshold. X: %.2f Y: %.2f Z: %.2f\n", x_dps, y_dps, z_dps);
        }

        usleep(50000); // 50 ms delay
    }

    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

