    uint8_t ctrl_reg4 = 0x20; // 200 dps full scale
    if (write(i2c_fd, &ctrl_reg4, 1) != 1) {
        perror("Failed to write CTRL_REG4");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    double offsets[3] = {0.0, 0.0, 0.0};
    for (int i = 0; i < SAMPLES; i++) {
        int16_t x = read_16bit(i2c_fd, OUT_X_L);
        int16_t y = read_16bit(i2c_fd, OUT_Y_L);
        int16_t z = read_16bit(i2c_fd, OUT_Z_L);

        offsets[0] += x;
        offsets[1] += y;
        offsets[2] += z;

        usleep(10000); // 10 ms delay
    }

    offsets[0] /= SAMPLES;
    offsets[1] /= SAMPLES;
    offsets[2] /= SAMPLES;

    while (!stop) {
        int16_t x = read_16bit(i2c_fd, OUT_X_L) - offsets[0];
        int16_t y = read_16bit(i2c_fd, OUT_Y_L) - offsets[1];
        int16_t z = read_16bit(i2c_fd, OUT_Z_L) - offsets[2];

        double x_dps = x * 8.75 / 1000.0;
        double y_dps = y * 8.75 / 1000.0;
        double z_dps = z * 8.75 / 1000.0;

        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "X: %.2f Y: %.2f Z: %.2f", x_dps, y_dps, z_dps);
        log_message(log_file, log_buffer);

        if (fabs(x_dps) > ALERT_THRESHOLD || fabs(y_dps) > ALERT_THRESHOLD || fabs(z_dps) > ALERT_THRESHOLD) {
            snprintf(log_buffer, sizeof(log_buffer), "ALERT: X: %.2f Y: %.2f Z: %.2f", x_dps, y_dps, z_dps);
            log_message(log_file, log_buffer);
            fprintf(stderr, "Warning: Axis exceeded threshold. X: %.2f Y: %.2f Z: %.2f\n", x_dps, y_dps, z_dps);
        }

        usleep(50000); // 50 ms delay
    }

    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}
