#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define DEVICE_ID_REG 0x00
#define DEVICE_ID_VALUE 0xE5
#define POWER_CTL_REG 0x2D
#define DATA_FORMAT_REG 0x31
#define FULL_RES_MODE 0x08
#define RANGE_2G 0x00
#define X_AXIS_DATA 0x32
#define Y_AXIS_DATA 0x34
#define Z_AXIS_DATA 0x36
#define GPIO_LED 17

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    if (read(fd, data, length) != length) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int configure_adxl345(int fd) {
    uint8_t value;

    // Verify device ID
    if (i2c_read(fd, DEVICE_ID_REG, &value, 1) != 0 || value != DEVICE_ID_VALUE) {
        fprintf(stderr, "ADXL345 device ID verification failed\n");
        return -1;
    }

    // Set to measurement mode
    if (i2c_write(fd, POWER_CTL_REG, 0x08) != 0) {
        return -1;
    }

    // Set full resolution mode and ±2g range
    if (i2c_write(fd, DATA_FORMAT_REG, FULL_RES_MODE | RANGE_2G) != 0) {
        return -1;
    }

    return 0;
}

int main() {
    int i2c_fd, gpio_fd;
    struct timespec ts;
    struct gpiod_line *led_line;
    struct gpiod_chip *chip;
    uint8_t data[6];
    float x, y, z;
    FILE *log_file;

    // Setup signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure ADXL345
    if (configure_adxl345(i2c_fd) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip and line
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "accel_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("accel_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        if (i2c_read(i2c_fd, X_AXIS_DATA, data, 6) == 0) {
            x = (int16_t)(data[1] << 8 | data[0]) * 0.00390625;
            y = (int16_t)(data[3] << 8 | data[2]) * 0.00390625;
            z = (int16_t)(data[5] << 8 | data[4]) * 0.00390625;

            // Log data
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld,%0.3f,%0.3f,%0.3f\n", ts.tv_sec, ts.tv_nsec, x, y, z);
            fflush(log_file);

            // Control LED
            if (fabs(x) > 2.0 || fabs(y) > 2.0 || fabs(z) > 2.0) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            fprintf(stderr, "Failed to read from ADXL345\n");
        }

        usleep(100000); // Sleep for 100 ms
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

