#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <syslog.h>
#include <math.h>

#define LSM303_ADDRESS_ACCEL 0x19
#define LSM303_ADDRESS_MAG   0x1E

#define ACCEL_CTRL_REG1_A 0x20
#define ACCEL_CTRL_REG4_A 0x23
#define ACCEL_OUT_X_L_A   0x28
#define MAG_CRA_REG_M     0x00
#define MAG_CRB_REG_M     0x01
#define MAG_MR_REG_M      0x02
#define MAG_OUT_X_H_M     0x03

#define SAMPLE_INTERVAL_MS 100

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_msg msgs[1];
    uint8_t buf[256];
    buf[0] = reg;
    memcpy(buf + 1, data, len);

    msgs[0].addr  = LSM303_ADDRESS_ACCEL;
    msgs[0].flags = 0;
    msgs[0].len   = len + 1;
    msgs[0].buf   = buf;

    if (write(fd, msgs, 1) != 1) {
        syslog(LOG_ERR, "I2C write error");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_msg msgs[2];
    uint8_t buf[256];

    msgs[0].addr  = LSM303_ADDRESS_ACCEL;
    msgs[0].flags = 0;
    msgs[0].len   = 1;
    msgs[0].buf   = &reg;

    msgs[1].addr  = LSM303_ADDRESS_ACCEL;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len   = len;
    msgs[1].buf   = data;

    if (write(fd, msgs, 2) != 2) {
        syslog(LOG_ERR, "I2C read error");
        return -1;
    }
    return 0;
}

void init_accelerometer(int fd) {
    uint8_t data = 0x27; // 100Hz, 2g
    if (i2c_write(fd, ACCEL_CTRL_REG1_A, &data, 1) != 0) {
        syslog(LOG_ERR, "Failed to initialize accelerometer");
        exit(EXIT_FAILURE);
    }
}

void init_magnetometer(int fd) {
    uint8_t data = 0x00; // Continuous-conversion mode
    if (i2c_write(fd, MAG_MR_REG_M, &data, 1) != 0) {
        syslog(LOG_ERR, "Failed to initialize magnetometer");
        exit(EXIT_FAILURE);
    }
}

void read_accelerometer(int fd, float *ax, float *ay, float *az) {
    uint8_t data[6];
    if (i2c_read(fd, ACCEL_OUT_X_L_A | 0x80, data, 6) != 0) {
        syslog(LOG_ERR, "Failed to read accelerometer data");
        exit(EXIT_FAILURE);
    }

    *ax = (int16_t)(data[1] << 8 | data[0]) / 16384.0f;
    *ay = (int16_t)(data[3] << 8 | data[2]) / 16384.0f;
    *az = (int16_t)(data[5] << 8 | data[4]) / 16384.0f;
}

void read_magnetometer(int fd, float *mx, float *my, float *mz) {
    uint8_t data[6];
    if (i2c_read(fd, MAG_OUT_X_H_M, data, 6) != 0) {
        syslog(LOG_ERR, "Failed to read magnetometer data");
        exit(EXIT_FAILURE);
    }

    *mx = (int16_t)(data[1] << 8 | data[0]);
    *my = (int16_t)(data[3] << 8 | data[2]);
    *mz = (int16_t)(data[5] << 8 | data[4]);
}

float compute_heading(float mx, float my) {
    return atan2(my, mx) * 180.0f / M_PI;
}

int main() {
    int fd;
    struct timespec ts;
    FILE *log_file;
    float ax, ay, az, mx, my, mz, heading;
    char log_filename[] = "compass_log.txt";

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, LSM303_ADDRESS_ACCEL) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to accelerometer");
        close(fd);
        return EXIT_FAILURE;
    }

    init_accelerometer(fd);

    if (ioctl(fd, I2C_SLAVE, LSM303_ADDRESS_MAG) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to magnetometer");
        close(fd);
        return EXIT_FAILURE;
    }

    init_magnetometer(fd);

    log_file = fopen(log_filename, "w");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file");
        close(fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");

    while (keep_running) {
        clock_gettime(CLOCK_REALTIME, &ts);
        read_accelerometer(fd, &ax, &ay, &az);
        read_magnetometer(fd, &mx, &my, &mz);
        heading = compute_heading(mx, my);

        fprintf(log_file, "%ld.%06ld,%f,%f,%f,%f,%d,%d,%d\n",
                ts.tv_sec, ts.tv_nsec / 1000, heading, ax, ay, az, mx, my, mz);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    close(fd);
    return EXIT_SUCCESS;
}

