#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x1A // Replace with actual I2C address
#define SENSOR2_ADDR 0x1B // Replace with actual I2C address
#define SAMPLE_INTERVAL_MS 10

static int i2c_fd1 = -1;
static int i2c_fd2 = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t stop = 0;

void cleanup() {
    if (i2c_fd1 != -1) {
        close(i2c_fd1);
    }
    if (i2c_fd2 != -1) {
        close(i2c_fd2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void signal_handler(int sig) {
    stop = 1;
}

int open_i2c_device(int addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

int read_i2c_sensor(int fd, int16_t *sample) {
    char buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *sample = (int16_t)(buf[0] << 8 | buf[1]);
    return 0;
}

void log_sample(int sec, int nsec, int16_t sensor1, int16_t sensor2, int64_t tdoa) {
    fprintf(log_file, "%d,%ld,%d,%d,%lld\n", sec, nsec, sensor1, sensor2, tdoa);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    log_file = fopen("audio_log.dat", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    i2c_fd1 = open_i2c_device(SENSOR1_ADDR);
    if (i2c_fd1 < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    i2c_fd2 = open_i2c_device(SENSOR2_ADDR);
    if (i2c_fd2 < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct timespec ts;
    int16_t sample1, sample2;
    int64_t tdoa;

    while (!stop) {
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("Failed to get time");
            break;
        }

        int16_t sample1_read = read_i2c_sensor(i2c_fd1, &sample1);
        int16_t sample2_read = read_i2c_sensor(i2c_fd2, &sample2);

        if (sample1_read == 0 && sample2_read == 0) {
            struct timespec ts2;
            if (clock_gettime(CLOCK_REALTIME, &ts2) != 0) {
                perror("Failed to get time");
                break;
            }

            tdoa = (ts2.tv_sec - ts.tv_sec) * 1e9 + (ts2.tv_nsec - ts.tv_nsec);
            log_sample(ts.tv_sec, ts.tv_nsec, sample1, sample2, tdoa);
        } else {
            fprintf(stderr, "Error reading from sensors, retrying...\n");
        }

        struct timespec interval = {0, SAMPLE_INTERVAL_MS * 1000000};
        nanosleep(&interval, NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

