#include <sys/ioctl.h>
#include <fcntl.h>
#include <poll.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 16
#define GPIO_CE0 8
#define STALL_TIME_US 40
#define SAMPLE_INTERVAL_MS 100

#define GYRO_SENSITIVITY 0.005
#define ACCEL_SENSITIVITY 0.00025

volatile sig_atomic_t running = 1;

void cleanup(int signum) {
    running = 0;
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        cleanup(signum);
    }
}

int setup_spi(int *spi_fd) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)0,
        .rx_buf = (unsigned long)0,
        .len = 4,
        .delay_usecs = STALL_TIME_US,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0
    };

    *spi_fd = open(SPI_DEVICE, O_RDWR);
    if (*spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(*spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(*spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0 ||
        ioctl(*spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI parameters: %s\n", strerror(errno));
        close(*spi_fd);
        return -1;
    }

    return 0;
}

int read_imu(int spi_fd, uint8_t reg, int16_t *data) {
    uint8_t tx[2] = {0x00, reg};
    uint8_t rx[2] = {0, 0};
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .delay_usecs = STALL_TIME_US,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *data = (rx[0] << 8) | rx[1];
    return 0;
}

void convert_and_log(FILE *file, struct timespec *timestamp, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    double gyro_x_deg = gyro_x * GYRO_SENSITIVITY;
    double gyro_y_deg = gyro_y * GYRO_SENSITIVITY;
    double gyro_z_deg = gyro_z * GYRO_SENSITIVITY;
    double accel_x_g = accel_x * ACCEL_SENSITIVITY;
    double accel_y_g = accel_y * ACCEL_SENSITIVITY;
    double accel_z_g = accel_z * ACCEL_SENSITIVITY;

    fprintf(file, "%ld.%09ld,%f,%f,%f,%f,%f,%f\n",
            timestamp->tv_sec, timestamp->tv_nsec / 1000,
            gyro_x_deg, gyro_y_deg, gyro_z_deg,
            accel_x_g, accel_y_g, accel_z_g);
}

void cleanup_resources(int spi_fd, FILE *file) {
    if (file) {
        fclose(file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void atexit_cleanup() {
    cleanup_resources(spi_fd, file);
}

int main() {
    int spi_fd;
    FILE *file;
    struct timespec timestamp;
    int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    if (setup_spi(&spi_fd) < 0) {
        return EXIT_FAILURE;
    }

    file = fopen("imu_data.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        cleanup_resources(spi_fd, NULL);
        return EXIT_FAILURE;
    }

    fprintf(file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    atexit(atexit_cleanup);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        clock_gettime(CLOCK_REALTIME, &timestamp);

        if (read_imu(spi_fd, 0x00, &gyro_x) < 0 ||
            read_imu(spi_fd, 0x01, &gyro_y) < 0 ||
            read_imu(spi_fd, 0x02, &gyro_z) < 0 ||
            read_imu(spi_fd, 0x03, &accel_x) < 0 ||
            read_imu(spi_fd, 0x04, &accel_y) < 0 ||
            read_imu(spi_fd, 0x05, &accel_z) < 0) {
            continue;
        }

        convert_and_log(file, &timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        struct pollfd fds;
        fds.fd = STDIN_FILENO;
        fds.events = POLLIN;
        poll(&fds, 1, SAMPLE_INTERVAL_MS - 10);

        if (fds.revents & POLLIN) {
            char c;
            read(STDIN_FILENO, &c, 1);
        }
    }

    cleanup_resources(spi_fd, file);
    return EXIT_SUCCESS;
}

