#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_3
#define SPI_MAX_SPEED_HZ 1000000
#define CS_GPIO 8
#define REG_READ_MASK 0x80

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_gpio_chip(gpiod_chip *chip, int line, int flags) {
    gpiod_line *cs_line = gpiod_chip_get_line(chip, line);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", line);
        return -1;
    }
    if (gpiod_line_request(cs_line, "spi_cs", flags) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d\n", line);
        gpiod_line_release(cs_line);
        return -1;
    }
    return 0;
}

int setup_spi(int *fd) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)0,
        .rx_buf = (unsigned long)0,
        .len = 4,
        .delay_usecs = 0,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = 8,
        .cs_change = 0
    };

    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(*fd);
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) < 0) {
        perror("Failed to set SPI max speed");
        close(*fd);
        return -1;
    }

    return 0;
}

int read_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t tx[4] = {reg | REG_READ_MASK, 0, 0, 0};
    uint8_t rx[4] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .delay_usecs = 0,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = 8,
        .cs_change = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    *value = (rx[1] << 8) | rx[2];
    return 0;
}

void cleanup(int fd, gpiod_chip *chip) {
    if (fd >= 0) {
        close(fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int spi_fd = -1;
    gpiod_chip *chip = NULL;
    gpiod_line *cs_line = NULL;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    if (setup_gpio_chip(chip, CS_GPIO, GPIOD_LINE_REQUEST_OUTPUT) < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO);
    gpiod_line_set_value(cs_line, 0);

    if (setup_spi(&spi_fd) < 0) {
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (read_register(spi_fd, 0x02, &gyro_x) < 0 ||
            read_register(spi_fd, 0x04, &gyro_y) < 0 ||
            read_register(spi_fd, 0x06, &gyro_z) < 0 ||
            read_register(spi_fd, 0x08, &accel_x) < 0 ||
            read_register(spi_fd, 0x0A, &accel_y) < 0 ||
            read_register(spi_fd, 0x0C, &accel_z) < 0) {
            fprintf(stderr, "Failed to read registers\n");
            break;
        }

        double gyro_scale = 0.02;
        double accel_scale = 0.00025;

        printf("Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps\n",
               gyro_x * gyro_scale, gyro_y * gyro_scale, gyro_z * gyro_scale);
        printf("Accel X: %.4f g, Accel Y: %.4f g, Accel Z: %.4f g\n",
               accel_x * accel_scale, accel_y * accel_scale, accel_z * accel_scale);

        usleep(100000); // 100 ms
    }

    cleanup(spi_fd, chip);
    return EXIT_SUCCESS;
}

