#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define CE_PIN 8
#define STALL_TIME_USEC 40
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.00025

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int open_spi_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

int setup_gpio_chip() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, CE_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "spi_ce", 0)) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return gpiod_chip_close(chip);
}

int read_imu_data(int fd, uint16_t *gyro_x, uint16_t *gyro_y, uint16_t *gyro_z,
                  uint16_t *accel_x, uint16_t *accel_y, uint16_t *accel_z) {
    uint8_t tx[4] = {0};
    uint8_t rx[4] = {0};
    struct spi_ioc_transfer tr[2];
    int ret;

    // Gyro X
    tx[0] = 0x80 | 0x00; // Read command for gyro X
    tr[0].tx_buf = (unsigned long)tx;
    tr[0].rx_buf = (unsigned long)rx;
    tr[0].len = 2;
    tr[0].delay_usecs = STALL_TIME_USEC;
    tr[0].speed_hz = SPI_SPEED;
