#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define RETRY_LIMIT 3
#define READ_INTERVAL 50

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    uint8_t cmd[1] = {reg};
    if (write(fd, cmd, 1) != 1) {
        perror("Failed to write to I2C bus");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Failed to read from I2C bus");
        return -1;
    }

    return 0;
}

int read_sensor_data(int fd, int16_t *accel, int16_t *gyro) {
    uint8_t buf[14];
    int retries = 0;
    int result;

    while (retries < RETRY_LIMIT) {
        result = i2c_read(fd, ACCEL_XOUT_H, buf, 14);
        if (result == 0) {
            accel[0] = (int16_t)(buf[0] << 8 | buf[1]);
            accel[1] = (int16_t)(buf[2] << 8 | buf[3]);
            accel[2] = (int16_t)(buf[4] << 8 | buf[5]);
            gyro[0] = (int16_t)(buf[8] << 8 | buf[9]);
            gyro[1] = (int16_t)(buf[10] << 8 | buf[11]);
            gyro[2] = (int16_t)(buf[12] << 8 | buf[13]);
            return 0;
        }
        retries++;
        usleep(100000); // Wait 100ms before retrying
    }

    return -1;
}

int main() {
    int fd;
    struct sigaction sa;
    int16_t accel[3], gyro[3];

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (read_sensor_data(fd, accel, gyro) == 0) {
            printf("Accel: X=%d Y=%d Z=%d\n", accel[0], accel[1], accel[2]);
            printf("Gyro: X=%d Y=%d Z=%d\n", gyro[0], gyro[1], gyro[2]);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        usleep(READ_INTERVAL * 1000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

