#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_DEVID_VALUE 0xE5
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_X0 0x32
#define ADXL345_REG_FULL_RES 0x08
#define ADXL345_REG_RANGE_2G 0x00
#define GPIO_LED 17
#define THRESHOLD 2.5
#define LED_ON_TIME 500000 // 500 ms in microseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(double magnitude, int16_t x, int16_t y, int16_t z) {
    FILE *log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s - Magnitude: %.2f, X: %d, Y: %d, Z: %d\n", timestamp, magnitude, x, y, z);
    fclose(log_file);
}

void cleanup(int i2c_fd, gpiod_line_handle_t *led_line) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (led_line != NULL) {
        gpiod_line_release(*led_line);
    }
}

int main() {
    int i2c_fd = -1;
    gpiod_line_handle_t *led_line = NULL;
    struct timespec sleep_time = {0, 10000000}; // 10 ms

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C address");
        cleanup(i2c_fd, NULL);
        return EXIT_FAILURE;
    }

    // Initialize LED GPIO
    led_line = gpiod_line_request(GPIO_LED, "led_control", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    if (led_line == NULL) {
        perror("Failed to request LED GPIO");
        cleanup(i2c_fd, NULL);
        return EXIT_FAILURE;
    }

    // Verify device ID
    uint8_t devid;
    if (read(i2c_fd, &devid, 1) != 1 || devid != ADXL345_REG_DEVID_VALUE) {
        fprintf(stderr, "Device ID verification failed\n");
        cleanup(i2c_fd, led_line);
        return EXIT_FAILURE;
    }

    // Configure ADXL345
    uint8_t data_format = ADXL345_REG_FULL_RES | ADXL345_REG_RANGE_2G;
    if (write(i2c_fd, &data_format, 1) != 1) {
        perror("Failed to write data format");
        cleanup(i2c_fd, led_line);
        return EXIT_FAILURE;
    }

    uint8_t power_ctl = 0x08; // Measure mode
    if (write(i2c_fd, &power_ctl, 1) != 1) {
        perror("Failed to write power control");
        cleanup(i2c_fd, led_line);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int16_t data[3];
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read accelerometer data");
            continue;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        double magnitude = sqrt(x * x + y * y + z * z) / 256.0;

        if (magnitude > THRESHOLD) {
            gpiod_line_set_value(*led_line, 1);
            usleep(LED_ON_TIME);
            gpiod_line_set_value(*led_line, 0);
            log_event(magnitude, x, y, z);
        }

        nanosleep(&sleep_time, NULL);
    }

    cleanup(i2c_fd, led_line);
    return EXIT_SUCCESS;
}

