    uint8_t devid;
    if (read(i2c_fd, &devid, 1) != 1 || devid != ADXL345_REG_DEVID_VALUE) {
        fprintf(stderr, "Device ID verification failed\n");
        cleanup(i2c_fd, led_line);
        return EXIT_FAILURE;
    }

    // Configure ADXL345
    uint8_t data_format = ADXL345_REG_FULL_RES | ADXL345_REG_RANGE_2G;
    if (write(i2c_fd, &data_format, 1) != 1) {
        perror("Failed to write data format");
        cleanup(i2c_fd, led_line);
        return EXIT_FAILURE;
    }

    uint8_t power_ctl = 0x08; // Measure mode
    if (write(i2c_fd, &power_ctl, 1) != 1) {
        perror("Failed to write power control");
        cleanup(i2c_fd, led_line);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int16_t data[3];
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read accelerometer data");
            continue;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        double magnitude = sqrt(x * x + y * y + z * z) / 256.0;

        if (magnitude > THRESHOLD) {
            gpiod_line_set_value(*led_line, 1);
            usleep(LED_ON_TIME);
            gpiod_line_set_value(*led_line, 0);
            log_event(magnitude, x, y, z);
        }

        nanosleep(&sleep_time, NULL);
    }

    cleanup(i2c_fd, led_line);
    return EXIT_SUCCESS;
}
