#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MMA8451Q_I2C_ADDR 0x1D
#define MMA8451Q_WHO_AM_I_REG 0x0D
#define MMA8451Q_WHO_AM_I_VALUE 0x1A
#define MMA8451Q_OUT_X_MSB_REG 0x01
#define MMA8451Q_OUT_Y_MSB_REG 0x03
#define MMA8451Q_OUT_Z_MSB_REG 0x05
#define GPIO_LED 17
#define G_THRESHOLD 2048
#define POLL_INTERVAL 100000000 // 100 ms in nanoseconds
#define LED_ON_DURATION 500000000 // 500 ms in nanoseconds

static int i2c_fd = -1;
static int log_fd = -1;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    syslog(LOG_INFO, "Cleaned up resources and exiting.");
}

void handle_signal(int sig) {
    cleanup();
    exit(0);
}

int i2c_read_byte_data(int addr, uint8_t reg) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        return -1;
    }
    if (write(i2c_fd, buffer, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C: %s", strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buffer, 1) != 1) {
        syslog(LOG_ERR, "Failed to read from I2C: %s", strerror(errno));
        return -1;
    }
    return buffer[0];
}

int verify_sensor_identity() {
    int who_am_i = i2c_read_byte_data(MMA8451Q_I2C_ADDR, MMA8451Q_WHO_AM_I_REG);
    if (who_am_i == -1) {
        syslog(LOG_ERR, "Failed to read sensor identity.");
        return 0;
    }
    return who_am_i == MMA8451Q_WHO_AM_I_VALUE;
}

int read_acceleration(int *x, int *y, int *z) {
    uint8_t buffer[6];
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        return -1;
    }
    buffer[0] = MMA8451Q_OUT_X_MSB_REG | 0x80; // Auto-increment
    if (write(i2c_fd, buffer, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C: %s", strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buffer, 6) != 6) {
        syslog(LOG_ERR, "Failed to read from I2C: %s", strerror(errno));
        return -1;
    }
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);
    return 0;
}

void log_acceleration(int x, int y, int z) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    dprintf(log_fd, "%s - X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
}

int main() {
    openlog("accelerometer", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    log_fd = open("impact_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (!verify_sensor_identity()) {
        syslog(LOG_ERR, "Sensor identity verification failed.");
        cleanup();
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip.");
        cleanup();
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        syslog(LOG_ERR, "Failed to get GPIO line.");
        gpiod_chip_close(chip);
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "accelerometer_led", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line.");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        int x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            log_acceleration(x, y, z);
            if (abs(x) > G_THRESHOLD || abs(y) > G_THRESHOLD || abs(z) > G_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
                usleep(LED_ON_DURATION / 1000);
                gpiod_line_set_value(led_line, 0);
            }
        }
        nanosleep((const struct timespec[]){{0, POLL_INTERVAL}}, NULL);
    }

    cleanup();
    closelog();
    return 0;
}

