#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDR 0x1E
#define REG_DATA_X_MSB 0x01
#define REG_DATA_Y_MSB 0x03
#define REG_DATA_Z_MSB 0x05
#define REG_STATUS 0x06
#define REG_CONFIG 0x07

static int i2c_fd = -1;
static FILE *log_file = NULL;

void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int read_sensor(int reg, int *data) {
    char buf[2];
    buf[0] = reg;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *data = (buf[0] << 8) | buf[1];
    return 0;
}

int read_magnetic_field(int *x, int *y, int *z) {
    int status;
    if (read_sensor(REG_STATUS, &status) < 0) {
        return -1;
    }

    if (!(status & 0x01)) { // Check if data is ready
        return -1;
    }

    if (read_sensor(REG_DATA_X_MSB, x) < 0 ||
        read_sensor(REG_DATA_Y_MSB, y) < 0 ||
        read_sensor(REG_DATA_Z_MSB, z) < 0) {
        return -1;
    }

    return 0;
}

void log_data(int x, int y, int z) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_i2c() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("magnetic_field_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
