            tv.tv_hour, tv.tv_min, tv.tv_sec,
            tv.tv_usec / 1000, x, y, z);
    fflush(log_file);
}

int main() {
    int i2c_fd, gpio_fd;
    struct gpiod_line *int1_line;
    struct gpiod_chip *chip;
    FILE *log_file;
    int16_t x, y, z;
