    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (write_i2c_byte(i2c_fd, ADXL345_REG_POWER_CTL, ADXL345_REG_POWER_CTL_STANDBY) < 0) {
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (read_i2c_byte(i2c_fd, ADXL345_REG_DEVID, &dev_id) < 0 || dev_id != 0xE5) {
        fprintf(stderr, "ADXL345 not found or incorrect device ID\n");
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (write_i2c_byte(i2c_fd, ADXL345_REG_DATA_FORMAT, ADXL345_REG_DATA_FORMAT_FULL_RES | ADXL345_REG_DATA_FORMAT_SELF_TEST_NORMAL | ADXL345_REG_DATA_FORMAT_JUSTIFY_RIGHT | ADXL345_REG_DATA_FORMAT_RANGE_16G) < 0) {
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (write_i2c_byte(i2c_fd, ADXL345_REG_POWER_CTL, ADXL345_REG_POWER_CTL_MEASURE) < 0) {
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (write_i2c_byte(i2c_fd, ADXL345_REG_INT_ENABLE, ADXL345_REG_INT_ENABLE_FREE_FALL) < 0) {
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    int1_line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!int1_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge(int1_line, "ADXL345_INT1") < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(int1_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    gpio_fd = gpiod_line_event_get_fd(int1_line);
    if (gpio_fd < 0) {
        perror("Failed to get event file descriptor");
        gpiod_line_release(int1_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int ret = read(gpio_fd, &int_source, sizeof(int_source));
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("Failed to read from event file descriptor");
            break;
        }

        if (int_source & ADXL345_REG_INT_SOURCE_FREE_FALL) {
            if (read_i2c_bytes(i2c_fd, ADXL345_REG_DATAX0, (uint8_t *)&x, 6) < 0) {
                break;
            }
            x = (int16_t)((x << 8) | x >> 8);
            y = (int16_t)((y << 8) | y >> 8);
            z = (int16_t)((z << 8) | z >> 8);
            log_acceleration(log_file, x, y, z);
        }
    }

    if (write_i2c_byte(i2c_fd, ADXL345_REG_INT_ENABLE, 0x00) < 0) {
        fprintf(stderr, "Failed to disable interrupts\n");
    }

    gpiod_line_release(int1_line);
    gpiod_chip_close(chip);
    close(gpio_fd);
    close(i2c_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

