#define LSM6DSR_I2C_ADDR 0x6A
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0x69
#define CTRL1_XL_REG 0x10
#define CTRL2_G_REG 0x11
#define OUTX_L_G_REG 0x22
#define OUTX_L_XL_REG 0x28
#define OUTSCALE_G 0.00875f // ±250 dps
#define OUTSCALE_XL 0.061f  // ±2 g

#define FALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define DETECTION_WINDOW 1.0f

#define I2C_BUS "/dev/i2c-1"

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int i2c_read_byte(int fd, uint8_t reg) {
    if (ioctl(fd, I2C_SLAVE, LSM6DSR_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to the i2c bus");
        return -1;
    }

    uint8_t data;
    if (read(fd, &data, 1) != 1) {
        perror("Failed to read from the i2c bus");
        return -1;
    }

    return data;
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, LSM6DSR_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

