#include <gpiod.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>

#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VALUE 0x3A
#define ANGULAR_RATE_X_REG 0x0C
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_CE0 8
#define SPI_MODE 3
#define SPI_SPEED 1000000
#define SCALE_FACTOR 0.0305
#define SAMPLE_INTERVAL 10

static int spi_fd = -1;
static int log_fd = -1;
static struct gpiod_line *ce0_line = NULL;

void handle_sigint(int sig) {
    if (ce0_line) {
        gpiod_line_release(ce0_line);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_fd >= 0) {
        fclose(stderr);
    }
    exit(EXIT_SUCCESS);
}

int init_spi() {
    struct spi_ioc_transfer transfer;
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)malloc(3);
    transfer.rx_buf = (unsigned long)malloc(2);
    transfer.len = 2;
    transfer.speed_hz = SPI_SPEED;
    transfer.bits_per_word = 8;
    transfer.cs_change = 0;

    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int init_gpio() {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    ce0_line = gpiod_chip_get_line(chip, GPIO_CE0);
    if (!ce0_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(ce0_line, "ce0", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

int read_register(uint8_t reg) {
    uint8_t tx[3];
    uint8_t rx[2];
    int ret;

    tx[0] = reg | 0x80; // Read command
    tx[1] = 0x00;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 1) {
        perror("SPI transfer failed");
        return -1;
    }

    memcpy(rx, (void *)transfer.rx_buf, 2);
    return (rx[0] << 8) | rx[1];
}

int verify_who_am_i() {
    uint8_t who_am_i = read_register(WHO_AM_I_REG);
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I verification failed: 0x%02X\n", who_am_i);
        return -1;
    }
    return 0;
}

void log_angular_rate(double rate) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_fd, "%04d-%02d-%02d %02d:%02d:%02d, %.6f\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, rate);
}

int main() {
    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (init_spi() < 0) {
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (verify_who_am_i() < 0) {
        return EXIT_FAILURE;
    }

    if ((log_fd = fopen("gyro_log.csv", "w")) == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    fprintf(log_fd, "Timestamp,Angular Rate (deg/sec)\n");

    while (1) {
        uint16_t raw_rate = read_register(ANGULAR_RATE_X_REG);
        if (raw_rate < 0) {
            break;
        }

        double rate = raw_rate * SCALE_FACTOR;
        log_angular_rate(rate);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    handle_sigint(0);
    return EXIT_SUCCESS;
}

