#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xD4
#define CTRL_REG1 0x20
#define OUT_X_L 0x28
#define OUT_Y_L 0x2A
#define OUT_Z_L 0x2C
#define SAMPLE_INTERVAL_MS 10

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

int initialize_sensor(int fd) {
    uint8_t who_am_i;
    for (int attempt = 0; attempt < 3; attempt++) {
        if (i2c_read(fd, WHO_AM_I_REG, &who_am_i, 1) == 0 && who_am_i == WHO_AM_I_VALUE) {
            if (i2c_write(fd, CTRL_REG1, 0x0F) == 0) { // Enable all axes, normal mode
                return 0;
            }
        }
        usleep(100000); // Wait 100ms before retrying
    }
    fprintf(stderr, "Failed to initialize sensor\n");
    return -1;
}

void log_data(int fd, FILE *file) {
    uint8_t buf[6];
    struct timespec ts;
    double x, y, z;

    while (keep_running) {
        if (i2c_read(fd, OUT_X_L | 0x80, buf, 6) == 0) {
            x = (int16_t)(buf[1] << 8 | buf[0]) / 114.285;
            y = (int16_t)(buf[3] << 8 | buf[2]) / 114.285;
            z = (int16_t)(buf[5] << 8 | buf[4]) / 114.285;

            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(file, "%ld.%09ld,%f,%f,%f\n", ts.tv_sec, ts.tv_nsec, x, y, z);
            fflush(file);
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }
}

int main() {
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_fd) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *file = fopen("gyro_log.csv", "w");
    if (!file) {
        perror("Failed to open file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    fprintf(file, "Timestamp,X,Y,Z\n");

    signal(SIGINT, handle_sigint);
    log_data(i2c_fd, file);

    fclose(file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

