void log_event(FILE *log_file, int flame_detected) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    if (flame_detected) {
        fprintf(log_file, "%s – Flame detected: YES\n", time_str);
        printf("FLAME DETECTED!\n");
    } else {
        fprintf(log_file, "%s – Flame detected: NO\n", time_str);
    }
    fflush(log_file);
}

