    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        int level = gpioRead(GPIO_PIN);
        if (level == PI_BAD_GPIO) {
            fprintf(log_file, "Error reading GPIO pin\n");
            fflush(log_file);
        } else {
