#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <string.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_1 17
#define GPIO_LINE_2 27
#define LOG_INTERVAL_MS 50
#define LOG_FILE "conveyor_log.txt"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_sensor_state(int line1_state, int line2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Sensor 1: %d, Sensor 2: %d\n", buffer, line1_state, line2_state);
    fflush(log_file);
}

void cleanup() {
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    struct gpiod_line_request req1 = {
        .consumer = "conveyor_monitor",
        .type = GPIOD_LINE_REQ_DIR_IN,
        .flags = GPIOD_LINE_REQ_FLAG_ACTIVE_LOW | GPIOD_LINE_REQ_FLAG_OPEN_DRAIN,
    };
    struct gpiod_line_request req2 = {
        .consumer = "conveyor_monitor",
        .type = GPIOD_LINE_REQ_DIR_IN,
        .flags = GPIOD_LINE_REQ_FLAG_ACTIVE_LOW | GPIOD_LINE_REQ_FLAG_OPEN_DRAIN,
    };

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    if (!line1) {
        fprintf(stderr, "Failed to get GPIO line 1\n");
        cleanup();
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (!line2) {
        fprintf(stderr, "Failed to get GPIO line 2\n");
        gpiod_line_release(line1);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line1, &req1)) {
        fprintf(stderr, "Failed to request GPIO line 1\n");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(line2, &req2)) {
        fprintf(stderr, "Failed to request GPIO line 2\n");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int line1_state = gpiod_line_get_value(line1);
        int line2_state = gpiod_line_get_value(line2);

        if (line1_state < 0 || line2_state < 0) {
            fprintf(stderr, "Failed to read GPIO line values\n");
            break;
        }

        log_sensor_state(line1_state, line2_state);

        if (line1_state == 0 && line2_state == 0) {
            printf("Conveyor halted\n");
        }

        usleep(LOG_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

