#define WHO_AM_I_VALUE 0x2A
#define CTRL_REG1 0x2A
#define CTRL_REG4 0x2D
#define OUT_X_MSB 0x01
#define LOG_FILE "fall_log.txt"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int address) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
