    return fd;
}

void read_i2c_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (read(fd, buf, len) != len) {
        syslog(LOG_ERR, "Failed to read from I2C device: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }
