#define I2C_DEVICE "/dev/i2c-1"
#define LIS3MDL_ADDR 0x1E
#define LIS3MDL_REG_OUT_X_H 0x03
#define LIS3MDL_REG_CTRL_REG1 0x20
#define LIS3MDL_REG_CTRL_REG2 0x21
#define LIS3MDL_REG_CTRL_REG3 0x22
#define LIS3MDL_REG_CTRL_REG4 0x23
#define LIS3MDL_REG_CTRL_REG5 0x24
#define LIS3MDL_REG_STATUS 0x27
#define LIS3MDL_REG_WHO_AM_I 0x0F
#define LIS3MDL_WHO_AM_I_VAL 0x3D
#define SCALE_FACTOR 0.146 // mG per LSB
#define CALIBRATION_OFFSET_X 0.0
#define CALIBRATION_OFFSET_Y 0.0
#define CALIBRATION_OFFSET_Z 0.0
#define CALIBRATION_SCALE_X 1.0
#define CALIBRATION_SCALE_Y 1.0
#define CALIBRATION_SCALE_Z 1.0
#define MAGNETIC_THRESHOLD 800.0 // mG

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t *data, size_t length) {
    uint8_t buffer[256];
    buffer[0] = reg;
    memcpy(buffer + 1, data, length);
    if (write(fd, buffer, length + 1) != length + 1) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, data, length) != length) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

int initialize_sensor(int fd) {
    uint8_t data;
    for (int attempt = 0; attempt < 3; ++attempt) {
        if (i2c_read(fd, LIS3MDL_REG_WHO_AM_I, &data, 1) == 0 && data == LIS3MDL_WHO_AM_I_VAL) {
            // Set continuous conversion mode
            data = 0x77; // 1001 0111
            if (i2c_write(fd, LIS3MDL_REG_CTRL_REG1, &data, 1) == 0) {
                return 0;
            }
        }
        usleep(100000); // Wait 100ms before retrying
    }
    return -1;
}

int main() {
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("magnetic_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    uint8_t buffer[6];
    while (keep_running) {
        if (i2c_read(i2c_fd, LIS3MDL_REG_OUT_X_H, buffer, 6) == 0) {
            int16_t x = (buffer[1] << 8) | buffer[0];
            int16_t y = (buffer[3] << 8) | buffer[2];
            int16_t z = (buffer[5] << 8) | buffer[4];

            double mag_x = (x * SCALE_FACTOR + CALIBRATION_OFFSET_X) * CALIBRATION_SCALE_X;
            double mag_y = (y * SCALE_FACTOR + CALIBRATION_OFFSET_Y) * CALIBRATION_SCALE_Y;
            double mag_z = (z * SCALE_FACTOR + CALIBRATION_OFFSET_Z) * CALIBRATION_SCALE_Z;

            double magnitude = sqrt(mag_x * mag_x + mag_y * mag_y + mag_z * mag_z);
            if (magnitude > MAGNETIC_THRESHOLD) {
                fprintf(stderr, "Metal-detector alert: %f mG\n", magnitude);
            }

            fprintf(log_file, "%f,%f,%f\n", mag_x, mag_y, mag_z);
            fflush(log_file);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        usleep(100000); // 10 Hz
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

