#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <syslog.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>

#define SPI_CHANNEL 0
#define CE_PIN 8
#define SPI_SPEED 1000000
#define RESET_REGISTER 0x1F
#define RESET_VALUE 0x52
#define POWER_CONTROL_REGISTER 0x2D
#define STATUS_REGISTER 0x2E
#define PARTID_REGISTER 0x00
#define PARTID_VALUE 0x34
#define ACCEL_X_REGISTER 0x08
#define ACCEL_Y_REGISTER 0x0A
#define ACCEL_Z_REGISTER 0x0C
#define RUN_BIT 0x01
#define STABLE_BIT 0x80
#define LOG_INTERVAL 100000000 // 100 ms in nanoseconds
#define MAX_RETRIES 3

static int spi_fd = -1;
static FILE *log_file = NULL;
static bool running = true;

void handle_signal(int sig) {
    running = false;
}

void log_error(const char *message) {
    syslog(LOG_ERR, "%s: %s", message, strerror(errno));
}

void log_info(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct iovec iov[2];
    struct msghdr msg = {0};
    int ret;

    iov[0].iov_base = tx;
    iov[0].iov_len = len;
    iov[1].iov_base = rx;
    iov[1].iov_len = len;

    msg.msg_iov = iov;
    msg.msg_iovlen = 2;

    ret = sendmsg(spi_fd, &msg, 0);
    if (ret < 0) {
        log_error("SPI transfer failed");
        return -1;
    }
    return 0;
}

int spi_write(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = {reg, value};
    uint8_t rx[2] = {0};

    for (int i = 0; i < MAX_RETRIES; i++) {
        if (spi_transfer(tx, rx, 2) == 0) {
            return 0;
        }
        usleep(1000); // Retry after 1 ms
    }
    return -1;
}

int spi_read(uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = {reg | 0x80 | 0x40, 0};
    uint8_t rx[3] = {0};

    for (int i = 0; i < MAX_RETRIES; i++) {
        if (spi_transfer(tx, rx, 3) == 0) {
            *value = (rx[1] << 8) | rx[2];
            return 0;
        }
        usleep(1000); // Retry after 1 ms
    }
    return -1;
}

int configure_spi() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)0,
        .rx_buf = (unsigned long)0,
        .len = 0,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        log_error("Failed to configure SPI");
        close(spi_fd);
        return -1;
    }
    return 0;
}

int reset_sensor() {
    if (spi_write(RESET_REGISTER, RESET_VALUE) < 0) {
        return -1;
    }
    usleep(1000); // Wait 1 ms
    if (spi_write(POWER_CONTROL_REGISTER, 0x00) < 0) {
        return -1;
    }

    uint8_t status;
    while (1) {
        if (spi_read(STATUS_REGISTER, &status) < 0) {
            return -1;
        }
        if (status & STABLE_BIT) {
            break;
        }
        usleep(1000); // Poll every 1 ms
    }

    if (spi_write(POWER_CONTROL_REGISTER, RUN_BIT) < 0) {
        return -1;
    }
    return 0;
}

int verify_sensor() {
    uint8_t partid;
    if (spi_read(PARTID_REGISTER, &partid) < 0) {
        return -1;
    }
    if (partid != PARTID_VALUE) {
        log_error("Sensor verification failed");
        return -1;
    }
    return 0;
}

int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6] = {0};

    if (spi_transfer(&ACCEL_X_REGISTER, data, 6) < 0) {
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[2]);
    *y = (int16_t)((data[3] << 8) | data[4]);
    *z = (int16_t)((data[5] << 8) | data[6]);

    return 0;
}

void log_acceleration(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: X=%d, Y=%d, Z=%d\n", time_str, x, y, z);
    fflush(log_file);
}

int main() {
    openlog("ADXL354B", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (configure_spi() < 0) {
        syslog(LOG_ERR, "Failed to configure SPI");
        exit(EXIT_FAILURE);
    }

    if (reset_sensor() < 0) {
        syslog(LOG_ERR, "Failed to reset sensor");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (verify_sensor() < 0) {
