    if (reset_sensor() < 0) {
        syslog(LOG_ERR, "Failed to reset sensor");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (verify_sensor() < 0) {
        syslog(LOG_ERR, "Failed to verify sensor");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    log_file = fopen("vibration_log.txt", "w");
    if (!log_file) {
        log_error("Failed to open log file");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    int16_t x, y, z;
    struct timespec last_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &last_time);

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (current_time.tv_nsec - last_time.tv_nsec >= LOG_INTERVAL) {
            if (read_acceleration(&x, &y, &z) < 0) {
