        ret = gpiod_line_get_value(line, &ts);
        if (ret < 0) {
            fprintf(stderr, "Failed to read line value\n");
            break;
        }

        if (ret == 0) { // LOW level detected
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Self-parking sequence started\n", time_str);

            // Simulate self-parking routine
            sleep(2); // Simulate time taken for self-parking

            time_t now2 = time(NULL);
            tm_info = localtime(&now2);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Self-parking sequence completed\n", time_str);
        }

        // Poll every second
        sleep(1);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
