#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_3
#define SPI_BITS_PER_WORD 8
#define SPI_CS_PIN 8
#define SCALE_FACTOR 0.02
#define POLL_INTERVAL 100000000 // 100 ms in nanoseconds

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int init_spi(int *fd) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)0,
        .rx_buf = (unsigned long)0,
        .len = 4,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0,
        .pad = 0
    };

    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(*fd);
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(*fd);
        return -1;
    }

    return 0;
}

int read_gyroscope(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx[4];
    uint8_t rx[4];
    int ret;

    // X-axis
    tx[0] = 0x80 | 0x00; // Address byte with MSB set
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        perror("SPI transfer failed");
        return -1;
    }
    *x = (int16_t)((rx[1] << 8) | rx[2]);

    // Y-axis
    tx[0] = 0x80 | 0x02; // Address byte with MSB set
    ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        perror("SPI transfer failed");
        return -1;
    }
    *y = (int16_t)((rx[1] << 8) | rx[2]);

    // Z-axis
    tx[0] = 0x80 | 0x04; // Address byte with MSB set
    ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        perror("SPI transfer failed");
        return -1;
    }
    *z = (int16_t)((rx[1] << 8) | rx[2]);

    return 0;
}

int main() {
    int spi_fd;
    struct timespec interval = {0, POLL_INTERVAL};
    int16_t x, y, z;

    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Error setting signal handler\n");
        return EXIT_FAILURE;
    }

    if (init_spi(&spi_fd) != 0) {
        return EXIT_FAILURE;
    }

    while (!stop) {
        if (read_gyroscope(spi_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
            break;
        }

        printf("X: %.2f deg/sec, Y: %.2f deg/sec, Z: %.2f deg/sec\n",
               x * SCALE_FACTOR, y * SCALE_FACTOR, z * SCALE_FACTOR);

        nanosleep(&interval, NULL);
    }

    close(spi_fd);
    return EXIT_SUCCESS;
}

