#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define LSM6DSR_I2C_ADDR 0x6A
#define LSM6DSR_WHO_AM_I 0x0F
#define LSM6DSR_CTRL1_XL 0x10
#define LSM6DSR_CTRL2_G 0x11
#define LSM6DSR_OUTX_L_XL 0x28
#define LSM6DSR_OUTX_L_G 0x22
#define LSM6DSR_OUTSCALE 0x06
#define LSM6DSR_OUTSCALE_DEFAULT 0x00
#define LSM6DSR_OUTSCALE_2G 0x00
#define LSM6DSR_OUTSCALE_16G 0x10
#define LSM6DSR_OUTSCALE_4G 0x08
#define LSM6DSR_OUTSCALE_8G 0x18
#define LSM6DSR_OUTSCALE_245DPS 0x00
#define LSM6DSR_OUTSCALE_500DPS 0x10
#define LSM6DSR_OUTSCALE_2000DPS 0x18

static int i2c_fd = -1;
static volatile sig_atomic_t stop = 0;

void handle_sigint(int sig) {
    stop = 1;
}

int i2c_write_byte_data(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM6DSR_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (i2c_read_bytes(i2c_fd, LSM6DSR_WHO_AM_I, &who_am_i, 1) < 0 || who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I register mismatch or read error\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_byte_data(i2c_fd, LSM6DSR_CTRL1_XL, 0x47) < 0 || // Enable accelerometer
        i2c_write_byte_data(i2c_fd, LSM6DSR_CTRL2_G, 0x47) < 0) {   // Enable gyroscope
        fprintf(stderr, "Failed to write to control registers\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t outscale;
    if (i2c_read_bytes(i2c_fd, LSM6DSR_OUTSCALE, &outscale, 1) < 0) {
        fprintf(stderr, "Failed to read OUTSCALE register\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int accel_scale = 0, gyro_scale = 0;
    switch (outscale & 0x30) {
        case LSM6DSR_OUTSCALE_2G:
            accel_scale = 2;
            break;
        case LSM6DSR_OUTSCALE_4G:
            accel_scale = 4;
            break;
        case LSM6DSR_OUTSCALE_8G:
            accel_scale = 8;
            break;
        case LSM6DSR_OUTSCALE_16G:
            accel_scale = 16;
            break;
        default:
            fprintf(stderr, "Unknown accelerometer scale\n");
            close(i2c_fd);
            return EXIT_FAILURE;
    }

    switch (outscale & 0xC0) {
        case LSM6DSR_OUTSCALE_245DPS:
            gyro_scale = 245;
            break;
        case LSM6DSR_OUTSCALE_500DPS:
            gyro_scale = 500;
            break;
        case LSM6DSR_OUTSCALE_2000DPS:
            gyro_scale = 2000;
            break;
        default:
            fprintf(stderr, "Unknown gyroscope scale\n");
            close(i2c_fd);
            return EXIT_FAILURE;
    }

    while (!stop) {
        uint8_t data[12];
        if (i2c_read_bytes(i2c_fd, LSM6DSR_OUTX_L_XL, data, 12) < 0) {
            fprintf(stderr, "Failed to read accelerometer and gyroscope data\n");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        int16_t ax = (data[1] << 8) | data[0];
        int16_t ay = (data[3] << 8) | data[2];
        int16_t az = (data[5] << 8) | data[4];
        int16_t gx = (data[9] << 8) | data[8];
        int16_t gy = (data[11] << 8) | data[10];
        int16_t gz = (data[7] << 8) | data[6];

        printf("%d %d %d %d %d %d\n",
               ax * 1000 / accel_scale,
               ay * 1000 / accel_scale,
               az * 1000 / accel_scale,
               gx * 1000 / gyro_scale,
               gy * 1000 / gyro_scale,
               gz * 1000 / gyro_scale);

        struct timespec ts = {0, 100000000}; // 100 ms
        nanosleep(&ts, NULL);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

