int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    struct i2c_msg msgs[2];
    uint8_t tx_buf[1] = {reg};
    int retries = 0;

    msgs[0].addr = FXOS8700_ADDR;
    msgs[0].flags = 0;
