#include <linux/i2c-dev.h>
#include <errno.h>
#include <math.h>

#define ADXL345_I2C_ADDR 0x53
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_BW_RATE_100HZ 0x0A
#define ADXL345_POWER_CTL_MEASURE 0x08
#define ADXL345_DATA_FORMAT_FULL_RES 0x08
#define ADXL345_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_i2c_block_data(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double magnitude = sqrt(x * x + y * y + z * z);
    double angle = acos(z / magnitude) * 180.0 / M_PI;
    return angle;
}

void log_tilt_event(double angle) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "[%s] Tilt angle: %.2f degrees\n", timestamp, angle);
    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_signal);

    int fd = open_i2c_device("/dev/i2c-1", ADXL345_I2C_ADDR);
    if (fd < 0) {
        exit(EXIT_FAILURE);
    }

    uint8_t devid;
    if (read_i2c_block_data(fd, ADXL345_REG_DEVID, &devid, 1) < 0 || devid != 0xE5) {
        fprintf(stderr, "ADXL345 not found\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    uint8_t data_format = ADXL345_DATA_FORMAT_FULL_RES;
    if (write(fd, &data_format, 1) != 1) {
        perror("Failed to set data format");
        close(fd);
        exit(EXIT_FAILURE);
    }

    uint8_t power_ctl = ADXL345_POWER_CTL_MEASURE;
    if (write(fd, &power_ctl, 1) != 1) {
        perror("Failed to set power control");
        close(fd);
        exit(EXIT_FAILURE);
    }

    uint8_t bw_rate = ADXL345_BW_RATE_100HZ;
    if (write(fd, &bw_rate, 1) != 1) {
        perror("Failed to set bandwidth rate");
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (keep_running) {
        uint8_t data[6];
        if (read_i2c_block_data(fd, ADXL345_REG_DATAX0, data, 6) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        double angle = calculate_tilt_angle(x, y, z);
        if (angle > ADXL345_THRESHOLD) {
            log_tilt_event(angle);
        }

        usleep(100000); // Sleep for 100 ms
    }

    close(fd);
    return EXIT_SUCCESS;
}

