int parse_threshold(const char *arg) {
    char *endptr;
    long threshold = strtol(arg, &endptr, 10);

    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Please provide a positive integer.\n");
        return -1;
    }

    return (int)threshold;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int threshold = parse_threshold(argv[1]);
    if (threshold == -1) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "sound_sensor", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line as input\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int high_count = 0;
        struct timespec start_time, current_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        for (int i = 0; i < WINDOW_DURATION_MS; i += SAMPLE_INTERVAL_MS) {
            if (!keep_running) break;

            ret = gpiod_line_get_value(line, &high_count);
            if (ret < 0) {
                fprintf(stderr, "Error: Failed to read GPIO line value\n");
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                return EXIT_FAILURE;
            }

            if (high_count) {
                high_count++;
            }

            usleep(SAMPLE_INTERVAL_MS * 1000);
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) +
                              (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        if (elapsed_time < WINDOW_DURATION_MS / 1000.0) {
            usleep((WINDOW_DURATION_MS - elapsed_time * 1000) * 1000);
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        if (high_count > threshold) {
            printf("%s ALERT\n", time_str);
        } else {
            printf("%s Status: %d high readings\n", time_str, high_count);
        }

        usleep(PAUSE_DURATION_MS * 1000);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
