volatile sig_atomic_t terminate = 0;

void handle_signal(int sig) {
    terminate = 1;
}

int setup_gpio(gpiod_chip *chip, int pin, int line_offset, int active_state) {
    gpiod_line *line = gpiod_chip_get_line(chip, line_offset);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", line_offset, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(line, "door_lock", active_state ? gpiod_line_request_invert : 0) < 0) {
        fprintf(stderr, "Failed to request line %d: %s\n", line_offset, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

void unlock_door(gpiod_line *line) {
    gpiod_line_set_value(line, UNLOCKED_STATE);
    sleep(UNLOCK_DURATION);
    gpiod_line_set_value(line, LOCKED_STATE);
}

int generate_security_code(int *code) {
    srand(time(NULL) ^ getpid());
    *code = rand() % 900000 + 100000;
    return 0;
}

int read_user_input(int *user_code) {
    char buffer[10];
    while (1) {
        printf("Enter the security code: ");
        if (fgets(buffer, sizeof(buffer), stdin) == NULL) {
            fprintf(stderr, "Error reading input: %s\n", strerror(errno));
            return -1;
        }

        if (sscanf(buffer, "%d", user_code) == 1) {
            return 0;
        } else {
            printf("Invalid input. Please enter a numeric code.\n");
            while (getchar() != '\n'); // Clear buffer
        }
    }
}

int log_access(const char *filename, int code) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fprintf(file, "%s,%06d\n", time_str, code) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

