        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (setup_gpio(chip, DOOR_A_PIN, DOOR_A_PIN, RELAY_ACTIVE_HIGH) < 0 ||
        setup_gpio(chip, DOOR_B_PIN, DOOR_B_PIN, RELAY_ACTIVE_HIGH) < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line *door_a_line = gpiod_chip_get_line(chip, DOOR_A_PIN);
    gpiod_line *door_b_line = gpiod_chip_get_line(chip, DOOR_B_PIN);

    if (!door_a_line || !door_b_line) {
        fprintf(stderr, "Failed to get door lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int security_code;
    while (!terminate) {
        if (generate_security_code(&security_code) < 0) {
            gpiod_line_release(door_a_line);
            gpiod_line_release(door_b_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        printf("Security code: %06d\n", security_code);

        int user_code;
        if (read_user_input(&user_code) < 0) {
            gpiod_line_release(door_a_line);
            gpiod_line_release(door_b_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        unlock_door(door_a_line);
        unlock_door(door_b_line);

        if (user_code == security_code) {
            if (log_access("access_log.txt", security_code) < 0) {
                gpiod_line_release(door_a_line);
                gpiod_line_release(door_b_line);
                gpiod_chip_close(chip);
                return EXIT_FAILURE;
            }
        } else {
            printf("Access denied\n");
        }
    }

    gpiod_line_set_value(door_a_line, LOCKED_STATE);
    gpiod_line_set_value(door_b_line, LOCKED_STATE);
    gpiod_line_release(door_a_line);
    gpiod_line_release(door_b_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

