#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>

#define BH1750_ADDR 0x23
#define BH1750_POWER_ON 0x01
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define I2C_BUS 1
#define LOG_FILE "light_log.txt"

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != len) {
        perror("I2C read error");
        return -1;
    }
    return 0;
}

int open_i2c_device(int bus, uint8_t addr) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, handle_sigint);

    int i2c_fd = open_i2c_device(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, BH1750_POWER_ON, 0x00) < 0 || 
        i2c_write(i2c_fd, BH1750_CONTINUOUS_HIGH_RES_MODE, 0x10) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint8_t data[2];
        if (i2c_read(i2c_fd, data, 2) < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            break;
        }

        uint16_t lux = (data[0] << 8) | data[1];
        lux /= 1.2;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "Timestamp: %s, Lux: %u\n", timestamp, lux);
        fflush(log_file);

        sleep(5);
    }

    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

