#include <gpiod.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define PWM_PIN 18
#define TCP_PORT 12345
#define LOG_FILE "frequency_log.txt"
#define TOUCH_INTERVAL_MS 20
#define PLAY_DURATION 5
#define SECRET "MySecretKey"
#define AUTH_PREFIX "MOTION_DETECTED:"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int init_mpr121() {
    int fd = open("/dev/i2c-" + std::to_string(I2C_BUS), O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    // Soft reset
    uint8_t reset_cmd = 0x06;
    if (write(fd, &reset_cmd, 1) != 1) {
        perror("Failed to write soft reset command");
        close(fd);
        return -1;
    }

    // Electrode configuration
    uint8_t config_cmd[2] = {0x5B, 0x00}; // Set touch threshold
    if (write(fd, config_cmd, 2) != 2) {
        perror("Failed to write electrode configuration");
        close(fd);
        return -1;
    }

    return fd;
}

