#define SAMPLE_INTERVAL_MS 100
#define GPIO_LED 17

static int i2c_fd = -1;
static int pwm_fd = -1;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *pwm_line;
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int init_i2c(const char *device) {
    i2c_fd = open(device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303DLHC_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int read_magnetometer(int *z_axis) {
    uint8_t buffer[6];
    if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read from I2C device");
        return -1;
    }

    int16_t z = (buffer[4] << 8) | buffer[5];
    *z_axis = z;
    return 0;
}

int init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led_control", 0)) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    pwm_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!pwm_line) {
        perror("Failed to get PWM line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request pwm_line, "pwm_control", GPIOD_LINE_REQUEST_DIRECTIONS_MASK) {
        perror("Failed to request PWM line");
        gpiod_chip_close(chip);
        return -1;
    }

    pwm_fd = gpiod_line_request pwm_line, "pwm_control", GPIOD_LINE_REQUEST_DIRECTIONS_MASK);
    if (pwm_fd < 0) {
        perror("Failed to request PWM line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    if (pwm_fd >= 0) {
        gpiod_line_release(pwm_line);
        pwm_fd = -1;
    }

    if (led_line) {
        gpiod_line_release(led_line);
    }

    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_i2c("/dev/i2c-1") < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (!stop) {
        int z_axis;
        if (read_magnetometer(&z_axis) == 0) {
            int magnitude = abs(z_axis);
            int duty_cycle = (magnitude * 1023) / 32768; // Scale to 10-bit PWM
            if (ioctl(pwm_fd, GPIOD_LINE_SET_REQUEST, duty_cycle) < 0) {
                perror("Failed to set PWM duty cycle");
            }
        } else {
            fprintf(stderr, "I2C read error, skipping sample\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

