#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <gpiod.h>
#include <errno.h>

#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define CONFIG_REG_A 0x00
#define CONFIG_REG_B 0x01
#define MODE_REG 0x02
#define DATA_REG_START 0x03
#define SAMPLES 100

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int i2c_write(int fd, uint8_t reg, uint8_t *data, size_t len) {
    uint8_t buf[1 + len];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if (write(fd, buf, 1 + len) != 1 + len) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open("/dev/i2c-" + std::to_string(I2C_BUS), O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HMC5883L_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t configA = 0x70; // 8-average, 15 Hz default, normal measurement
    uint8_t configB = 0xA0; // Gain = 5
    uint8_t mode = 0x00;    // Continuous measurement mode

    if (i2c_write(fd, CONFIG_REG_A, &configA, 1) < 0 ||
        i2c_write(fd, CONFIG_REG_B, &configB, 1) < 0 ||
        i2c_write(fd, MODE_REG, &mode, 1) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t data[6];
    int16_t x_avg = 0, y_avg = 0, z_avg = 0;
    int16_t x_samples[SAMPLES] = {0}, y_samples[SAMPLES] = {0}, z_samples[SAMPLES] = {0};
    int sample_index = 0;

    while (!stop) {
        if (i2c_read(fd, DATA_REG_START, data, 6) < 0) {
            continue;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[4] << 8) | data[5];
        int16_t z = (data[2] << 8) | data[3];

        x_samples[sample_index] = x;
        y_samples[sample_index] = y;
        z_samples[sample_index] = z;

        sample_index = (sample_index + 1) % SAMPLES;

        x_avg = 0;
        y_avg = 0;
        z_avg = 0;
        for (int i = 0; i < SAMPLES; i++) {
            x_avg += x_samples[i];
            y_avg += y_samples[i];
            z_avg += z_samples[i];
        }
        x_avg /= SAMPLES;
        y_avg /= SAMPLES;
        z_avg /= SAMPLES;

        int16_t x_corrected = x - x_avg;
        int16_t y_corrected = y - y_avg;
        int16_t z_corrected = z - z_avg;

        printf("X: %d, Y: %d, Z: %d\n", x_corrected, y_corrected, z_corrected);

        usleep(500000); // 500 ms
    }

    close(fd);
    return EXIT_SUCCESS;
}

