#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

#define SOL1_PIN 17
#define SOL2_PIN 27

static volatile int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;

void handle_signal(int sig) {
    keep_running = 0;
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    line1 = gpiod_chip_get_line(chip, SOL1_PIN);
    if (!line1) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", SOL1_PIN);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line2 = gpiod_chip_get_line(chip, SOL2_PIN);
    if (!line2) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", SOL2_PIN);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line1, "solenoid1", GPIOD_LINE_REQUEST_DIRECTIONS) < 0) {
        fprintf(stderr, "Failed to request line %d as output\n", SOL1_PIN);
        gpiod_line_release(line2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line2, "solenoid2", GPIOD_LINE_REQUEST_DIRECTIONS) < 0) {
        fprintf(stderr, "Failed to request line %d as output\n", SOL2_PIN);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);
}

void cleanup_gpio() {
    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);
}

int main() {
    struct sigaction sa;
    struct timespec ts;

    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        return EXIT_FAILURE;
    }

    setup_gpio();

    while (keep_running) {
        gpiod_line_set_value(line1, 1);
        gpiod_line_set_value(line2, 0);
        ts.tv_sec = 0;
        ts.tv_nsec = 500 * 1000000;
        nanosleep(&ts, NULL);

        gpiod_line_set_value(line1, 0);
        gpiod_line_set_value(line2, 1);
        nanosleep(&ts, NULL);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

