#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <gpiod.h>
#include <time.h>

#define PIR_GPIO_LINE "gpio4"
#define RELAY_GPIO_LINE "gpio17"
#define PIR_POLL_INTERVAL_NS 50000000 // 50 ms in nanoseconds
#define RELAY_ON_DURATION_MS 1000 // 1 second
#define PIR_HIGH_THRESHOLD_MS 10000 // 10 seconds

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *relay_line = NULL;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_and_exit(const char *message, int status) {
    syslog(LOG_ERR, "%s", message);
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    exit(status);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    openlog("pir_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting PIR sensor and relay monitoring");

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_and_exit("Failed to open GPIO chip", EXIT_FAILURE);
    }

    pir_line = gpiod_chip_get_line(chip, gpiod_chip_get_line_by_name(chip, PIR_GPIO_LINE));
    if (!pir_line) {
        log_and_exit("Failed to get PIR line", EXIT_FAILURE);
    }
    if (gpiod_line_request_input(pir_line, "pir_monitor", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        log_and_exit("Failed to request PIR line", EXIT_FAILURE);
    }

    relay_line = gpiod_chip_get_line(chip, gpiod_chip_get_line_by_name(chip, RELAY_GPIO_LINE));
    if (!relay_line) {
        log_and_exit("Failed to get relay line", EXIT_FAILURE);
    }
    if (gpiod_line_request_output(relay_line, "relay_control", 0) < 0) {
        log_and_exit("Failed to request relay line", EXIT_FAILURE);
    }

    struct timespec last_motion_time;
    clock_gettime(CLOCK_MONOTONIC, &last_motion_time);
    struct timespec current_time;
    struct timespec motion_start_time;
    int motion_detected = 0;

    while (keep_running) {
        if (gpiod_line_event_wait(pir_line, PIR_POLL_INTERVAL_NS) > 0) {
            int value = gpiod_line_get_value(pir_line);
            if (value == 1) {
                if (!motion_detected) {
                    motion_detected = 1;
                    clock_gettime(CLOCK_MONOTONIC, &motion_start_time);
                    syslog(LOG_INFO, "Motion detected");
                }
                clock_gettime(CLOCK_MONOTONIC, &current_time);
                if (current_time.tv_sec - motion_start_time.tv_sec > PIR_HIGH_THRESHOLD_MS / 1000) {
                    syslog(LOG_WARNING, "PIR signal continuously HIGH for more than 10 seconds, triggering failsafe");
                    gpiod_line_set_value(relay_line, 0);
                    syslog(LOG_INFO, "Relay de-energized due to failsafe");
                    break;
                }
            } else {
                if (motion_detected) {
                    motion_detected = 0;
                    gpiod_line_set_value(relay_line, 1);
                    syslog(LOG_INFO, "Relay activated");
                    usleep(RELAY_ON_DURATION_MS * 1000);
                    gpiod_line_set_value(relay_line, 0);
                    syslog(LOG_INFO, "Relay deactivated");
                }
            }
        }
    }

    if (motion_detected) {
        gpiod_line_set_value(relay_line, 0);
        syslog(LOG_WARNING, "PIR signal continuously HIGH, triggering failsafe");
        syslog(LOG_INFO, "Relay de-energized due to failsafe");
    }

    syslog(LOG_INFO, "Shutting down");
    gpiod_line_release(relay_line);
    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

