#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <gpiod.h>
#include <time.h>

#define RELAY1 4
#define RELAY2 17
#define RELAY3 27
#define RELAY4 22

#define NUM_RELAYS 4
#define RELAY_GPIO_PINS {RELAY1, RELAY2, RELAY3, RELAY4}

#define ON_TIME 300 // 5 minutes
#define OFF_TIME 60 // 1 minute

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int sig) {
    stop_flag = 1;
}

void log_message(const char *message) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "%s", message);
    closelog();
}

int initialize_gpio(gpiod_chip *chip, gpiod_line *lines[], int pins[], int num_lines) {
    for (int i = 0; i < num_lines; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            log_message("Failed to get GPIO line");
            return -1;
        }
        if (gpiod_line_request_output(lines[i], "irrigation_system", 1) < 0) {
            log_message("Failed to request GPIO line as output");
            return -1;
        }
    }
    return 0;
}

void cleanup(gpiod_chip *chip, gpiod_line *lines[], int num_lines) {
    for (int i = 0; i < num_lines; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
}

void activate_relay(gpiod_line *line) {
    if (gpiod_line_set_value(line, 0) < 0) {
        log_message("Failed to set relay ON");
    }
}

void deactivate_relay(gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        log_message("Failed to set relay OFF");
    }
}

void log_state_change(int relay, int state) {
    char buffer[256];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    char *state_str = state ? "ON" : "OFF";
    char message[256];
    snprintf(message, sizeof(message), "[%s] Relay %d is %s", buffer, relay, state_str);
    log_message(message);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_message("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    gpiod_line *lines[NUM_RELAYS];
    int pins[NUM_RELAYS] = RELAY_GPIO_PINS;

    if (initialize_gpio(chip, lines, pins, NUM_RELAYS) < 0) {
        cleanup(chip, lines, NUM_RELAYS);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        deactivate_relay(lines[i]);
    }

    int current_relay = 0;
    while (!stop_flag) {
        activate_relay(lines[current_relay]);
        log_state_change(current_relay + 1, 1);

        sleep(ON_TIME);

        deactivate_relay(lines[current_relay]);
        log_state_change(current_relay + 1, 0);

        if (current_relay == NUM_RELAYS - 1) {
            sleep(OFF_TIME);
        } else {
            sleep(1);
        }

        current_relay = (current_relay + 1) % NUM_RELAYS;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        deactivate_relay(lines[i]);
    }

    cleanup(chip, lines, NUM_RELAYS);
    return EXIT_SUCCESS;
}

