#define BUFFER_SIZE 100

volatile sig_atomic_t keep_running = 1;

typedef struct {
    int16_t x, y, z;
} AccelerationSample;

AccelerationSample buffer[BUFFER_SIZE];
int buffer_index = 0;
int i2c_fd = -1;
int timer_fd = -1;
int epoll_fd = -1;
int latest_fd = -1;

void handle_signal(int sig) {
    keep_running = 0;
}

void write_latest_sample() {
    if (latest_fd < 0) return;

    char latest_path[256];
    snprintf(latest_path, sizeof(latest_path), "/sys/kernel/mpu6050_accel/latest");
    int latest_file = open(latest_path, O_WRONLY);
    if (latest_file < 0) {
        perror("Failed to open latest file");
        return;
    }

    char sample_str[32];
    snprintf(sample_str, sizeof(sample_str), "%d %d %d", buffer[buffer_index].x, buffer[buffer_index].y, buffer[buffer_index].z);
    if (write(latest_file, sample_str, strlen(sample_str)) < 0) {
        perror("Failed to write latest sample");
    }

    close(latest_file);
}

int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
        perror("Failed to read from MPU6050");
        return -1;
    }

    *x = (data[0] << 8) | data[1];
    *y = (data[2] << 8) | data[3];
    *z = (data[4] << 8) | data[5];

    return 0;
}

void setup_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_timer() {
    struct itimerspec its;
    timer_fd = timerfd_create(CLOCK_REALTIME, 0);
    if (timer_fd < 0) {
        perror("Failed to create timer");
        exit(EXIT_FAILURE);
    }

    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 10ms
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000; // 10ms

    if (timerfd_settime(timer_fd, 0, &its, NULL) < 0) {
        perror("Failed to set timer");
        close(timer_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_epoll() {
    epoll_fd = epoll_create1(0);
    if (epoll_fd < 1) {
        perror("Failed to create epoll instance");
        exit(EXIT_FAILURE);
    }

    struct epoll_event event;
    event.data.fd = timer_fd;
    event.events = EPOLLIN;
    if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, timer_fd, &event) < 0) {
        perror("Failed to add timer_fd to epoll");
        exit(EXIT_FAILURE);
    }
}

void setup_latest_file() {
    latest_fd = open("/sys/kernel/mpu6050_accel/latest", O_WRONLY);
    if (latest_fd < 0) {
        perror("Failed to open latest file");
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (i2c_fd >= 0) close(i2c_fd);
    if (timer_fd >= 0) close(timer_fd);
    if (epoll_fd >= 0) close(epoll_fd);
    if (latest_fd >= 0) close(latest_fd);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_i2c();
    setup_timer();
    setup_epoll();
    setup_latest_file();

    struct epoll_event events[1];
    while (keep_running) {
        int n = epoll_wait(epoll_fd, events, 1, -1);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("epoll_wait");
            break;
        }

        if (events[0].data.fd == timer_fd) {
            uint64_t expirations;
            if (read(timer_fd, &expirations, sizeof(expirations)) != sizeof(expirations)) {
                perror("Failed to read from timer");
                break;
            }

            int16_t x, y, z;
            if (read_acceleration(&x, &y, &z) == 0) {
                buffer[buffer_index].x = x;
                buffer[buffer_index].y = y;
                buffer[buffer_index].z = z;
                buffer_index = (buffer_index + 1) % BUFFER_SIZE;
                write_latest_sample();
            }
        }
    }

    cleanup();
    return 0;
}

