#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>
#include <unistd.h>

#define RELAY1 18
#define RELAY2 23
#define RELAY3 24
#define RELAY4 25

#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void toggle_relay(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, gpiod_line_get_value(line) ^ 1) < 0) {
        fprintf(stderr, "Failed to toggle GPIO line\n");
    }
}

void cleanup(struct gpiod_chip *chip, struct gpiod_line *lines[], int num_lines) {
    for (int i = 0; i < num_lines; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[4];
    struct timespec start, now;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    lines[0] = gpiod_chip_get_line(chip, RELAY1);
    lines[1] = gpiod_chip_get_line(chip, RELAY2);
    lines[2] = gpiod_chip_get_line(chip, RELAY3);
    lines[3] = gpiod_chip_get_line(chip, RELAY4);

    for (int i = 0; i < 4; i++) {
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", i + 1);
            cleanup(chip, lines, i);
            return EXIT_FAILURE;
        }
        ret = gpiod_line_request_output(lines[i], "relay%d", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %d\n", i + 1);
            cleanup(chip, lines, i + 1);
            return EXIT_FAILURE;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (keep_running) {
        for (int i = 0; i < 4; i++) {
            clock_gettime(CLOCK_MONOTONIC, &now);
            long elapsed = (now.tv_sec - start.tv_sec) * 1000000000L + (now.tv_nsec - start.tv_nsec);
            long interval = (i == 0) ? INTERVAL1 : (i == 1) ? INTERVAL2 : (i == 2) ? INTERVAL3 : INTERVAL4;
            long interval_ns = interval * 1000000000L;

            if (elapsed >= interval_ns) {
                toggle_relay(lines[i]);
                start.tv_sec = now.tv_sec;
                start.tv_nsec = now.tv_nsec;
            }
        }
        usleep(100000); // Sleep for 100ms to reduce CPU usage
    }

    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(lines[i], 0);
    }

    cleanup(chip, lines, 4);

    return EXIT_SUCCESS;
}

