#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR_PIN 17
#define RELAY_PIN 27
#define POLL_INTERVAL 100000000 // 100 ms in nanoseconds
#define RELAY_ON_TIME 3000000000 // 3 seconds in nanoseconds
#define DEBOUNCE_TIME 500000000 // 0.5 seconds in nanoseconds

static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *relay_line;
static FILE *log_file;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_timestamp() {
    time_t now = time(NULL);
    if (log_file) {
        fprintf(log_file, "Alarm activated at: %s", ctime(&now));
        fflush(log_file);
    }
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(sensor_line, "sound_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        perror("Failed to request sensor line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        perror("Failed to request relay line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    struct timespec ts;
    struct gpiod_line_event event;
    int ret;
    uint64_t last_activation_time = 0;

    log_file = fopen("alarm_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    setup_gpio();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        ret = gpiod_line_event_wait(sensor_line, POLL_INTERVAL);
        if (ret < 0) {
            perror("Failed to wait for sensor event");
            break;
        }

        if (ret > 0) {
            ret = gpiod_line_event_read(sensor_line, &event);
            if (ret < 0) {
                perror("Failed to read sensor event");
                break;
            }

            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                uint64_t current_time = gpiod_chip_get_monotonic(chip);
                if (current_time - last_activation_time > DEBOUNCE_TIME) {
                    gpiod_line_set_value(relay_line, 1);
                    log_timestamp();
                    last_activation_time = current_time;

                    ts.tv_sec = current_time / 1000000000;
                    ts.tv_nsec = current_time % 1000000000;
                    nanosleep(&ts, NULL);

                    ts.tv_sec += 3;
                    ts.tv_nsec += RELAY_ON_TIME % 1000000000;
                    if (ts.tv_nsec >= 1000000000) {
                        ts.tv_sec += 1;
                        ts.tv_nsec -= 1000000000;
                    }
                    nanosleep(&ts, NULL);

                    gpiod_line_set_value(relay_line, 0);
                }
            }
        }
    }

    cleanup_gpio();
    return 0;
}

