    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    struct timespec ts;
    struct gpiod_line_event event;
    int ret;
    uint64_t last_activation_time = 0;

    log_file = fopen("alarm_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    setup_gpio();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        ret = gpiod_line_event_wait(sensor_line, POLL_INTERVAL);
        if (ret < 0) {
            perror("Failed to wait for sensor event");
            break;
        }

        if (ret > 0) {
            ret = gpiod_line_event_read(sensor_line, &event);
            if (ret < 0) {
                perror("Failed to read sensor event");
                break;
            }

            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                uint64_t current_time = gpiod_chip_get_monotonic(chip);
                if (current_time - last_activation_time > DEBOUNCE_TIME) {
                    gpiod_line_set_value(relay_line, 1);
                    log_timestamp();
                    last_activation_time = current_time;

                    ts.tv_sec = current_time / 1000000000;
                    ts.tv_nsec = current_time % 1000000000;
                    nanosleep(&ts, NULL);

                    ts.tv_sec += 3;
                    ts.tv_nsec += RELAY_ON_TIME % 1000000000;
                    if (ts.tv_nsec >= 1000000000) {
                        ts.tv_sec += 1;
                        ts.tv_nsec -= 1000000000;
                    }
                    nanosleep(&ts, NULL);

                    gpiod_line_set_value(relay_line, 0);
                }
            }
        }
    }

    cleanup_gpio();
    return 0;
}
