    int fd;
    uint8_t buffer[2];
    int16_t gyro_x, gyro_y, gyro_z;
    float angular_velocity;
    int16_t buffer[BUFFER_SIZE];
    int buffer_index = 0;

    signal(SIGINT, handle_sigint);

