        close(fd);
        error_exit("Failed to select I2C device");
    }

    buffer[0] = MPU6050_PWR_MGMT_1;
    buffer[1] = 0x00; // Wake up the MPU-6050
    if (write(fd, buffer, 2) != 2) {
