#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <termios.h>
#include <libgpiod.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B9600
#define TXD_PIN 14
#define RXD_PIN 15
#define READ_TIMEOUT 1000
#define SAMPLE_INTERVAL 5000
#define RESPONSE_LENGTH 9
#define COMMAND_SEQUENCE "\xff\x01\x86\x00\x00\x00\x00\x00\x79"

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int open_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("open_uart: open");
        return -1;
    }

    struct termios options;
    if (tcgetattr(fd, &options) != 0) {
        perror("open_uart: tcgetattr");
        close(fd);
        return -1;
    }

    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);

    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CRTSCTS;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;

    if (tcsetattr(fd, TCSANOW, &options) != 0) {
        perror("open_uart: tcsetattr");
        close(fd);
        return -1;
    }

    return fd;
}

int send_command(int fd, const char *command) {
    if (write(fd, command, strlen(command)) != strlen(command)) {
        perror("send_command: write");
        return -1;
    }
    return 0;
}

int read_response(int fd, unsigned char *buffer, size_t length) {
    struct timeval timeout = {0, READ_TIMEOUT * 1000};
    fd_set read_fds;
    int total_read = 0;
    int start_time = time(NULL);

    while (total_read < length && (time(NULL) - start_time) < 1) {
        FD_ZERO(&read_fds);
        FD_SET(fd, &read_fds);

        int ret = select(fd + 1, &read_fds, NULL, NULL, &timeout);
        if (ret < 0) {
            perror("read_response: select");
            return -1;
        } else if (ret == 0) {
            continue;
        }

        int bytes_read = read(fd, buffer + total_read, length - total_read);
        if (bytes_read < 0) {
            perror("read_response: read");
            return -1;
        } else if (bytes_read == 0) {
            continue;
        }

        total_read += bytes_read;
    }

    return (total_read == length) ? 0 : -1;
}

int calculate_checksum(const unsigned char *data, size_t length) {
    int checksum = 0;
    for (size_t i = 0; i < length - 2; i++) {
        checksum += data[i];
    }
    return checksum;
}

void log_error(const char *message) {
    FILE *error_log = fopen("co2_error.log", "a");
    if (error_log == NULL) {
        perror("log_error: fopen");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(error_log, "[%s] %s\n", timestamp, message);
    fclose(error_log);
}

void log_reading(int fd, unsigned char *buffer) {
    FILE *log_file = fopen("co2_log.json", "a");
    if (log_file == NULL) {
        perror("log_reading: fopen");
        return;
    }

    time_t now = time(NULL);
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp = (long long)now * 1000000 + ts.tv_nsec / 1000;

    int checksum = calculate_checksum(buffer, RESPONSE_LENGTH);
    if (checksum != buffer[8]) {
        char error_message[256];
        snprintf(error_message, sizeof(error_message), "Checksum mismatch: expected %02x, got %02x", checksum, buffer[8]);
        log_error(error_message);
        fprintf(log_file, "{\"timestamp\": %lld, \"ppm\": 0, \"error\": \"%s\"}\n", timestamp, error_message);
    } else {
        int ppm = (buffer[2] << 8) | buffer[3];
        fprintf(log_file, "{\"timestamp\": %lld, \"ppm\": %d, \"error\": \"null\"}\n", timestamp, ppm);
    }

    fflush(log_file);
    fclose(log_file);

    printf("{\"timestamp\": %lld, \"ppm\": %d, \"error\": \"null\"}\n", timestamp, ppm);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TXD_PIN, PI_OUTPUT) != 0 || gpioSetMode(RXD_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int uart_fd = open_uart(UART_DEVICE);
    if (uart_fd == -1) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("co2_log.json", "w");
    if (log_file == NULL) {
        perror("main: fopen");
        close(uart_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fclose(log_file);

    FILE *error_log = fopen("co2_error.log", "w");
    if (error_log == NULL) {
        perror("main: fopen");
        close(uart_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fclose(error_log);

    while (!stop) {
        unsigned char buffer[RESPONSE_LENGTH];
        if (send_command(uart_fd, COMMAND_SEQUENCE) == 0 &&
            read_response(uart_fd, buffer, RESPONSE_LENGTH) == 0) {
            log_reading(uart_fd, buffer);
        } else {
            log_error("Failed to read response from sensor");
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    close(uart_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

