#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>

#define I2C_BUS "/dev/i2c-1"
#define HMC5883L_ADDR 0x1E
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL 100000000 // 100 ms in nanoseconds
#define GPIO_PIN 17
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define HARD_IRON_OFFSET_X 100
#define HARD_IRON_OFFSET_Y -50

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int i2c_init() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, HMC5883L_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

int read_hmc5883l(int fd, int *x, int *y, int *z) {
    char buf[6];
    if (read(fd, buf, sizeof(buf)) != sizeof(buf)) {
        perror("Failed to read from HMC5883L");
        return -1;
    }

    *x = (buf[0] << 8) | buf[1];
    *y = (buf[4] << 8) | buf[5];
    *z = (buf[2] << 8) | buf[3];

    return 0;
}

double calculate_heading(int x, int y) {
    double heading = atan2((double)y, (double)x) * 180.0 / M_PI;
    if (heading < 0) {
        heading += 360.0;
    }
    return heading;
}

void set_gpio_high(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (gpiod_line_request_output(line, "heading_control", 1) < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }
}

void set_gpio_low(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set GPIO line low");
        exit(EXIT_FAILURE);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    set_gpio_high(chip, line);

    int i2c_fd = i2c_init();
    if (i2c_fd < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int buffer[BUFFER_SIZE];
    int buffer_index = 0;
