int read_hmc5883l(int fd, int *x, int *y, int *z) {
    char buf[6];
    if (read(fd, buf, sizeof(buf)) != sizeof(buf)) {
        perror("Failed to read from HMC5883L");
        return -1;
    }

    *x = (buf[0] << 8) | buf[1];
    *y = (buf[4] << 8) | buf[5];
    *z = (buf[2] << 8) | buf[3];

    return 0;
}

