#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BH1750_I2C_BUS "/dev/i2c-1"
#define BH1750_ADDRESS 0x23
#define BH1750_CMD_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_CMD_RESET 0x07
#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(RED_GPIO, PI_OUTPUT);
    gpioSetMode(GREEN_GPIO, PI_OUTPUT);
    gpioSetMode(BLUE_GPIO, PI_OUTPUT);
}

void cleanup_gpio() {
    gpioTerminate();
}

void setup_i2c(int *fd) {
    *fd = open(BH1750_I2C_BUS, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void cleanup_i2c(int fd) {
    close(fd);
}

void reset_bh1750(int fd) {
    char cmd = BH1750_CMD_RESET;
    if (write(fd, &cmd, 1) != 1) {
        perror("Failed to reset BH1750");
        exit(EXIT_FAILURE);
    }
    usleep(10000); // Wait 10ms for reset
}

float read_lux(int fd) {
    char cmd = BH1750_CMD_CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &cmd, 1) != 1) {
        perror("Failed to set BH1750 mode");
        exit(EXIT_FAILURE);
    }

    usleep(120000); // Wait 120ms for conversion

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("Failed to read from BH1750");
        exit(EXIT_FAILURE);
    }

    uint16_t raw = (data[0] << 8) | data[1];
    return raw / 1.2; // Convert to lux
}

void control_relays(float lux) {
    gpioWrite(RED_GPIO, lux < 50 ? 1 : 0);
    gpioWrite(GREEN_GPIO, (lux >= 50 && lux <= 150) ? 1 : 0);
    gpioWrite(BLUE_GPIO, (lux > 150 && lux <= 300) ? 1 : 0);

    if (lux > 300) {
        gpioWrite(RED_GPIO, 1);
        gpioWrite(GREEN_GPIO, 1);
        gpioWrite(BLUE_GPIO, 1);
    }
}

void log_lux(float lux, int red, int green, int blue) {
    FILE *log_file = fopen("lighting_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s, %.2f, %d, %d, %d\n", timestamp, lux, red, green, blue);
    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    int i2c_fd;
    setup_i2c(&i2c_fd);
    reset_bh1750(i2c_fd);

    FILE *log_file = fopen("lighting_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup_i2c(i2c_fd);
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }
    fclose(log_file);

    while (keep_running) {
        float lux = read_lux(i2c_fd);
        int red = gpioRead(RED_GPIO);
        int green = gpioRead(GREEN_GPIO);
        int blue = gpioRead(BLUE_GPIO);
        control_relays(lux);
        log_lux(lux, red, green, blue);
        sleep(1);
    }

    cleanup_i2c(i2c_fd);
    cleanup_gpio();

    return 0;
}

