#include <gpiod.h>
#include <string.h>

#define PWM_FREQUENCY 1000
#define PWM_PERIOD_NS (1000000000 / PWM_FREQUENCY)
#define PWM_MAX_DUTY 255

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_gpio(gpiod_line_handle_t *line, int chip_num, int line_offset, int flags) {
    gpiod_chip *chip = gpiod_chip_open_by_num(chip_num);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    *line = gpiod_chip_get_line(chip, line_offset);
    if (!*line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request(*line, "motor_control", flags) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int setup_pwm(gpiod_line_handle_t *line, int chip_num, int line_offset) {
    gpiod_chip *chip = gpiod_chip_open_by_num(chip_num);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    *line = gpiod_chip_get_line(chip, line_offset);
    if (!*line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request(*line, "motor_pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_set_flags(*line, GPIOD_LINE_FLAG_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to set GPIO line flags\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_set_range_ns(*line, PWM_PERIOD_NS) < 0) {
        fprintf(stderr, "Failed to set PWM period\n");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void cleanup(gpiod_line_handle_t *lines, int num_lines) {
    for (int i = 0; i < num_lines; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_motor_a> <distance_motor_b>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int distance_motor_a = atoi(argv[1]);
    int distance_motor_b = atoi(argv[2]);

    if (distance_motor_a < 10 || distance_motor_a > 100 || distance_motor_b < 10 || distance_motor_b > 100) {
        fprintf(stderr, "Distances must be in the range 10-100 cm\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpiod_line_handle_t lines[4];
    int setup_result;

    setup_result = setup_gpio(&lines[0], 0, MOTOR_A_IN1, GPIOD_LINE_REQUEST_OUTPUT);
    if (setup_result < 0) goto cleanup_and_exit;

    setup_result = setup_gpio(&lines[1], 0, MOTOR_A_IN2, GPIOD_LINE_REQUEST_OUTPUT);
    if (setup_result < 0) goto cleanup_and_exit;

    setup_result = setup_gpio(&lines[2], 0, MOTOR_B_IN3, GPIOD_LINE_REQUEST_OUTPUT);
    if (setup_result < 0) goto cleanup_and_exit;

    setup_result = setup_gpio(&lines[3], 0, MOTOR_B_IN4, GPIOD_LINE_REQUEST_OUTPUT);
    if (setup_result < 0) goto cleanup_and_exit;

    setup_result = setup_pwm(&lines[1], 0, MOTOR_A_IN2);
    if (setup_result < 0) goto cleanup_and_exit;

    setup_result = setup_pwm(&lines[3], 0, MOTOR_B_IN4);
    if (setup_result < 0) goto cleanup_and_exit;

    while (keep_running) {
        int duty_a = (distance_motor_a < 50) ? (PWM_MAX_DUTY * (50 - distance_motor_a) / 50) : (PWM_MAX_DUTY * (distance_motor_a - 50) / 50);
        int duty_b = (distance_motor_b < 50) ? (PWM_MAX_DUTY * (50 - distance_motor_b) / 50) : (PWM_MAX_DUTY * (distance_motor_b - 50) / 50);

        if (distance_motor_a < 50) {
            gpiod_line_set_value(lines[0], 1);
            gpiod_line_set_value(lines[2], 1);
        } else {
            gpiod_line_set_value(lines[0], 0);
            gpiod_line_set_value(lines[2], 0);
        }

        if (distance_motor_b < 50) {
            gpiod_line_set_value(lines[2], 1);
            gpiod_line_set_value(lines[3], 1);
        } else {
            gpiod_line_set_value(lines[2], 0);
            gpiod_line_set_value(lines[3], 0);
        }

        gpiod_line_set_value(lines[1], 1);
        gpiod_line_set_value(lines[3], 1);

        gpiod_line_set_value_fd(lines[1], duty_a);
        gpiod_line_set_value_fd(lines[3], duty_b);

        usleep(100000); // 100 ms
    }

cleanup_and_exit:
    cleanup(lines, 4);
    return EXIT_SUCCESS;
}

