#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/poll.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <syslog.h>
#include <pigpio.h>

#define MPU6050_ADDRESS 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_CONFIG 0x1A
#define I2C_BUS "/dev/i2c-1"
#define PWM_PIN 18
#define PWM_FREQUENCY 50
#define PWM_DUTY_CYCLE_MAX 20000
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 5

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

double calculate_pitch_roll(int16_t ax, int16_t ay, int16_t az) {
    double roll = atan2(ax, sqrt(ay * ay + az * az)) * 180.0 / M_PI;
    double pitch = atan2(ay, sqrt(ax * ax + az * az)) * 180.0 / M_PI;
    return roll, pitch;
}

void log_data(double pitch, double roll, int position) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, position);
    fclose(log_file);
}

int initialize_i2c(int *fd) {
    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(*fd);
        return -1;
    }

    uint8_t data = 0x00;
    if (write(*fd, &data, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C bus: %s", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

int read_mpu6050(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "Failed to write register address: %s", strerror(errno));
        return -1;
    }

    if (read(fd, data, length) != length) {
        syslog(LOG_ERR, "Failed to read data from I2C bus: %s", strerror(errno));
        return -1;
    }

    return 0;
}

int initialize_pwm() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO: %s", strerror(errno));
        return -1;
    }

    if (gpioPWM(PWM_PIN, PWM_FREQUENCY, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialize PWM: %s", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

void cleanup(int i2c_fd, int keep_running) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    gpioTerminate();
    syslog(LOG_INFO, "Cleaned up resources");
}

int main() {
    int i2c_fd = -1;
    int retries = 0;
    int16_t ax, ay, az;
    uint8_t data[6];
    double pitch, roll;
    int position = 0;

    openlog("solar_tracker", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (retries < MAX_RETRIES && keep_running) {
        if (initialize_i2c(&i2c_fd) == 0) {
            break;
        }
        retries++;
        sleep(1 << retries); // Exponential backoff
    }

    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to initialize I2C after retries");
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_pwm() < 0) {
        syslog(LOG_ERR, "Failed to initialize PWM");
        cleanup(i2c_fd, keep_running);
        closelog();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (read_mpu6050(i2c_fd, MPU6050_ACCEL_XOUT_H, data, 6) == 0) {
            ax = (int16_t)(data[0] << 8 | data[1]);
            ay = (int16_t)(data[2] << 8 | data[3]);
            az = (int16_t)(data[4] << 8 | data[5]);

            roll, pitch = calculate_pitch_roll(ax, ay, az);

            position = (int)(pitch + 90) * (PWM_DUTY_CYCLE_MAX / 180);
            if (position < 0) position = 0;
            if (position > PWM_DUTY_CYCLE_MAX) position = PWM_DUTY_CYCLE_MAX;

            gpioPWM(PWM_PIN, PWM_FREQUENCY, position);
            log_data(pitch, roll, position);
        } else {
            syslog(LOG_WARNING, "Failed to read MPU6050 data");
        }

        usleep(100000); // 100 ms delay
    }

    cleanup(i2c_fd, keep_running);
    closelog();
    return EXIT_SUCCESS;
}

