#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define PWM_FREQ 100
#define FADE_DURATION 1800
#define SCHEDULE_FILE "lighting_schedule.txt"
#define GPIO_PINS {4, 17, 27, 22}

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_RELAYS];
static struct gpiod_line *pwm_lines[NUM_RELAYS];
static int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void cleanup() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) gpiod_line_release(lines[i]);
        if (pwm_lines[i]) gpiod_line_release(pwm_lines[i]);
    }
    if (chip) gpiod_chip_close(chip);
}

int setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i] || gpiod_line_request_output(lines[i], "relay", 0) < 0) {
            perror("Failed to request GPIO line");
            cleanup();
            return -1;
        }

        pwm_lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!pwm_lines[i] || gpiod_line_request_output(pwm_lines[i], "pwm", 0) < 0) {
            perror("Failed to request PWM line");
            cleanup();
            return -1;
        }

        if (gpiod_line_set_request(pwm_lines[i], GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0) {
            perror("Failed to set PWM line request");
            cleanup();
            return -1;
        }
    }
    return 0;
}

void fade_lights(int relay, int target_state) {
    int step = (target_state == 1) ? 1 : -1;
    for (int duty_cycle = (target_state == 1) ? 0 : 100; (step == 1) ? duty_cycle <= 100 : duty_cycle >= 0; duty_cycle += step) {
        if (!running) break;
        gpiod_line_set_value(pwm_lines[relay], duty_cycle);
        usleep(FADE_DURATION * 1000000 / 100);
    }
    gpiod_line_set_value(pwm_lines[relay], target_state ? 100 : 0);
}

void process_schedule(const char *line) {
    int hour, minute, second, relay, state;
    if (sscanf(line, "%d:%d:%d,%d,%d", &hour, &minute, &second, &relay, &state) != 5) {
        fprintf(stderr, "Invalid schedule entry: %s\n", line);
        return;
    }

    struct tm now;
    time_t now_time = time(NULL);
    localtime_r(&now_time, &now);

    int current_time = now.tm_hour * 3600 + now.tm_min * 60 + now.tm_sec;
    int schedule_time = hour * 3600 + minute * 60 + second;

    if (current_time == schedule_time && relay >= 0 && relay < NUM_RELAYS && (state == 0 || state == 1)) {
        fade_lights(relay, state);
    }
}

void check_schedule() {
    FILE *file = fopen(SCHEDULE_FILE, "r");
    if (!file) {
        perror("Failed to open schedule file");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        process_schedule(line);
    }

    fclose(file);
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR || signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

