#define MIN_DISTANCE_CM 2
#define MIN_FREQUENCY_HZ 20
#define MAX_FREQUENCY_HZ 2000
#define MEASUREMENT_INTERVAL_MS 60
#define MAIN_LOOP_FREQUENCY_HZ 50

static volatile int keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int setup_gpio(gpiod_line_handle_t *trigger, gpiod_line_handle_t *echo, gpiod_line_handle_t *buzzer) {
    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    *trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!*trigger || gpiod_line_request(*trigger, "trigger", GPIOD_LINE_REQUEST_DIRECTIONS_OUT) < 0) {
        fprintf(stderr, "Failed to request trigger line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!*echo || gpiod_line_request(*echo, "echo", GPIOD_LINE_REQUEST_DIRECTIONS_IN) < 0) {
        fprintf(stderr, "Failed to request echo line\n");
        gpiod_line_release(*trigger);
        gpiod_chip_close(chip);
        return -1;
    }

    *buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!*buzzer || gpiod_line_request(*buzzer, "buzzer", GPIOD_LINE_REQUEST_DIRECTIONS_OUT) < 0) {
        fprintf(stderr, "Failed to request buzzer line\n");
        gpiod_line_release(*echo);
        gpiod_line_release(*trigger);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

int measure_distance(gpiod_line_handle_t *echo) {
    gpiod_line_handle_t *line = *echo;
    gpiod_line_set_value(line, 1);
    usleep(10);
    gpiod_line_set_value(line, 0);

    struct gpiod_line_event event;
    int ret = gpiod_line_event_wait(line, &event, -1);
    if (ret < 0) {
        fprintf(stderr, "Failed to wait for echo event\n");
        return -1;
    }

    if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
        fprintf(stderr, "Unexpected event type\n");
        return -1;
    }

    struct timespec start, end;
    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
        fprintf(stderr, "Failed to get start time\n");
        return -1;
    }

    ret = gpiod_line_event_wait(line, &event, -1);
    if (ret < 0) {
        fprintf(stderr, "Failed to wait for echo event\n");
        return -1;
    }

    if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
        fprintf(stderr, "Unexpected event type\n");
        return -1;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
        fprintf(stderr, "Failed to get end time\n");
        return -1;
    }

    long duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    if (duration_us <= 0) {
        fprintf(stderr, "Invalid duration\n");
        return -1;
    }

    int distance_cm = duration_us / 58;
    return distance_cm;
}

int set_pwm_frequency(gpiod_line_handle_t *buzzer, int frequency) {
    if (frequency < MIN_FREQUENCY_HZ || frequency > MAX_FREQUENCY_HZ) {
        fprintf(stderr, "Frequency out of range\n");
        return -1;
    }

    int period_ns = 1000000000 / frequency;
    int duty_cycle_ns = period_ns / 2;

    if (gpiod_line_set_value(buzzer, 1) < 0 || gpiod_line_set_value(buzzer, 0) < 0) {
        fprintf(stderr, "Failed to set buzzer value\n");
        return -1;
    }

    usleep(period_ns / 1000);
    return 0;
}

int main() {
    signal(SIGINT, handle_sigint);

    gpiod_line_handle_t trigger, echo, buzzer;
    if (setup_gpio(&trigger, &echo, &buzzer) < 0) {
        return EXIT_FAILURE;
    }

    struct timespec last_measurement;
    clock_gettime(CLOCK_MONOTONIC, &last_measurement);

    while (keep_running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        if (now.tv_sec > last_measurement.tv_sec || (now.tv_sec == last_measurement.tv_sec && (now.tv_nsec - last_measurement.tv_nsec) >= 60000000)) {
            int distance = measure_distance(&echo);
            if (distance < 0) {
                fprintf(stderr, "Error measuring distance\n");
                continue;
            }

            if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
            if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

            int frequency = MIN_FREQUENCY_HZ + (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) * (distance - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
            set_pwm_frequency(&buzzer, frequency);

            last_measurement = now;
        }

        usleep(1000000 / MAIN_LOOP_FREQUENCY_HZ);
    }

    gpiod_line_set_value(&buzzer, 0);
    gpiod_line_release(&trigger);
    gpiod_line_release(&echo);
    gpiod_line_release(&buzzer);

    return EXIT_SUCCESS;
}

