#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <math.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27
#define PWM_FREQ 1000

static volatile int keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void cleanup(gpiod_chip *chip, gpiod_line *red_line, gpiod_line *green_line, gpiod_line *blue_line) {
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
}

int main() {
    struct timespec ts = {0, 10000000}; // 10ms interval
    gpiod_chip *chip;
    gpiod_line *red_line, *green_line, *blue_line;
    int ret;

    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup(chip, red_line, green_line, blue_line);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(red_line, "red_pwm", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request red line\n");
        cleanup(chip, red_line, green_line, blue_line);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(green_line, "green_pwm", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request green line\n");
        cleanup(chip, red_line, green_line, blue_line);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(blue_line, "blue_pwm", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request blue line\n");
        cleanup(chip, red_line, green_line, blue_line);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_request(red_line, "pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set red line request\n");
        cleanup(chip, red_line, green_line, blue_line);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_request(green_line, "pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set green line request\n");
        cleanup(chip, red_line, green_line, blue_line);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_request(blue_line, "pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set blue line request\n");
        cleanup(chip, red_line, green_line, blue_line);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_flags(red_line, GPIOD_LINE_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to set red line flags\n");
        cleanup(chip, red_line, green_line, blue_line);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_flags(green_line, GPIOD_LINE_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to set green line flags\n");
        cleanup(chip, red_line, green_line, blue_line);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_flags(blue_line, GPIOD_LINE_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to set blue line flags\n");
        cleanup(chip, red_line, green_line, blue_line);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_value(red_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set red line value\n");
        cleanup(chip, red_line, green_line, blue_line);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_value(green_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set green line value\n");
        cleanup(chip, red_line, green_line, blue_line);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_value(blue_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set blue line value\n");
        cleanup(chip, red_line, green_line, blue_line);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        double t = (double)clock() / CLOCKS_PER_SEC;
        double proximity = (sin(t * 2 * M_PI) + 1) / 2; // Sine wave from 0 to 1

        int red_value = (1 - proximity) * 1023;
        int green_value = proximity * 1023;
        int blue_value = (1 - proximity) * 1023;

        ret = gpiod_line_set_value(red_line, red_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set red line PWM value\n");
            cleanup(chip, red_line, green_line, blue_line);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_set_value(green_line, green_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set green line PWM value\n");
            cleanup(chip, red_line, green_line, blue_line);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_set_value(blue_line, blue_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set blue line PWM value\n");
            cleanup(chip, red_line, green_line, blue_line);
            return EXIT_FAILURE;
        }

        nanosleep(&ts, NULL);
    }

    // Turn off the LED
    gpiod_line_set_value(red_line, 0);
    gpiod_line_set_value(green_line, 0);
    gpiod_line_set_value(blue_line, 0);

    cleanup(chip, red_line, green_line, blue_line);

    return EXIT_SUCCESS;
}

