    if (ret < 0) {
        fprintf(stderr, "Failed to set blue line value\n");
        cleanup(chip, red_line, green_line, blue_line);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        double t = (double)clock() / CLOCKS_PER_SEC;
        double proximity = (sin(t * 2 * M_PI) + 1) / 2; // Sine wave from 0 to 1

        int red_value = (1 - proximity) * 1023;
        int green_value = proximity * 1023;
        int blue_value = (1 - proximity) * 1023;

        ret = gpiod_line_set_value(red_line, red_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set red line PWM value\n");
            cleanup(chip, red_line, green_line, blue_line);
            return EXIT_FAILURE;
