            cleanup(chip, red_line, green_line, blue_line);
            return EXIT_FAILURE;
        }

        nanosleep(&ts, NULL);
    }

    // Turn off the LED
    gpiod_line_set_value(red_line, 0);
    gpiod_line_set_value(green_line, 0);
    gpiod_line_set_value(blue_line, 0);

    cleanup(chip, red_line, green_line, blue_line);

    return EXIT_SUCCESS;
}
