#define I2C_DEVICE "/dev/i2c-1"
#define MPU6050_ADDRESS 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_FULL_SCALE_250_DPS 0x00

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_init(int *fd) {
    *fd = open(I2C_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(*fd);
        return -1;
    }

    return 0;
}

int mpu6050_init(int fd) {
    uint8_t data = MPU6050_GYRO_FULL_SCALE_250_DPS;
    if (write(fd, &data, 1) != 1) {
        perror("Failed to write to MPU6050");
        return -1;
    }

    data = 0x00; // Wake up the MPU6050
    if (write(fd, &data, 1) != 1) {
        perror("Failed to write to MPU6050");
        return -1;
    }

    return 0;
}

int read_gyro(int fd, int16_t *gyro_data) {
    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read from MPU6050");
        return -1;
    }

    gyro_data[0] = (int16_t)(buffer[0] << 8 | buffer[1]);
    gyro_data[1] = (int16_t)(buffer[2] << 8 | buffer[3]);
    gyro_data[2] = (int16_t)(buffer[4] << 8 | buffer[5]);

    return 0;
}

int main() {
    int i2c_fd;
    FILE *log_file;
    int16_t gyro_data[3];
    struct timespec ts;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (i2c_init(&i2c_fd) < 0) {
        return EXIT_FAILURE;
    }

    if (mpu6050_init(i2c_fd) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (read_gyro(i2c_fd, gyro_data) < 0) {
            fprintf(stderr, "Error reading gyro data\n");
            break;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld %d %d %d\n",
                ts.tv_sec, ts.tv_nsec, gyro_data[0], gyro_data[1], gyro_data[2]);
        fflush(log_file);

        usleep(100000); // Sleep for 100 ms
    }

    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

