#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <pigpio.h>

#define BUTTON_GPIO 17
#define BUZZER_GPIO 18
#define DEBOUNCE_INTERVAL 50 // milliseconds
#define MELODY_LENGTH 8

// Melody lookup table (frequency in Hz)
const int melody[MELODY_LENGTH] = {262, 294, 330, 349, 392, 440, 494, 523};
const int durations[MELODY_LENGTH] = {500, 500, 500, 500, 500, 500, 500, 1000}; // durations in milliseconds

volatile sig_atomic_t stop_flag = 0;
volatile sig_atomic_t button_pressed = 0;

void handle_signal(int sig) {
    stop_flag = 1;
}

void play_melody() {
    for (int i = 0; i < MELODY_LENGTH; i++) {
        if (stop_flag) {
            gpioWrite(BUZZER_GPIO, 0);
            return;
        }
        gpioWaveAddTone(0, melody[i], durations[i]);
        gpioWaveCreate();
        if (gpioWaveTxSend(0, GPIO_WAVE_MODE_ONE_SHOT) != 0) {
            fprintf(stderr, "Failed to send wave\n");
            return;
        }
        while (gpioWaveTxBusy()) {
            usleep(1000);
        }
    }
    gpioWaveDelete();
    gpioWrite(BUZZER_GPIO, 0);
}

void button_callback(int gpio, unsigned level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_INTERVAL) {
        button_pressed = 1;
        last_tick = current_tick;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_GPIO, PI_INPUT) < 0 ||
        gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP) < 0 ||
        gpioSetAlertFunc(BUTTON_GPIO, button_callback) < 0) {
        fprintf(stderr, "Failed to configure button GPIO\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to configure buzzer GPIO\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        if (button_pressed) {
            button_pressed = 0;
            if (stop_flag) {
                gpioWrite(BUZZER_GPIO, 0);
            } else {
                play_melody();
            }
        }
        usleep(10000); // Sleep for 10ms to reduce CPU usage
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

