#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <stdbool.h>

#define GPIO_PIN 17
#define DEFAULT_TIMEOUT 1000
#define WINDOW_SIZE 5

volatile sig_atomic_t stop_flag = 0;
gpiod_line_handle_t line = NULL;
FILE *log_file = NULL;

void handle_signal(int sig) {
    stop_flag = 1;
}

void log_event(int value) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    if (fprintf(log_file, "%s %d\n", timestamp, value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }

    if (fflush(log_file) != 0 || fsync(fileno(log_file)) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

void print_earthquake_alert() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    printf("EARTHQUAKE ALERT at %s\n", timestamp);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int timeout = DEFAULT_TIMEOUT;
    if (argc > 1) {
        timeout = atoi(argv[1]);
    }

    line = gpiod_line_request_by_name(NULL, "gpiochip0-line17", GPIOD_LINE_REQUEST_DIRECTIONS);
    if (!line) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_active_low(line, false) < 0) {
        fprintf(stderr, "Error setting active high: %s\n", strerror(errno));
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    log_file = fopen("vibration_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    int values[WINDOW_SIZE] = {0};
    int index = 0;
    int high_count = 0;

    while (!stop_flag) {
        gpiod_line_event_wait(line, timeout);
        if (gpiod_line_event_read(line, NULL) < 0) {
            fprintf(stderr, "Error reading line event: %s\n", strerror(errno));
            break;
        }

        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error getting line value: %s\n", strerror(errno));
            break;
        }

        log_event(value);

        values[index] = value;
        index = (index + 1) % WINDOW_SIZE;

        high_count = 0;
        for (int i = 0; i < WINDOW_SIZE; i++) {
            if (values[i] == 1) {
                high_count++;
            }
        }

        if (high_count >= 3) {
            print_earthquake_alert();
        }
    }

    if (line) {
        gpiod_line_release(line);
    }

    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

