#define I2C_DEVICE "/dev/i2c-1"
#define LSM303DLHC_ADDRESS 0x1D
#define LSM303DLHC_REG_MAG_X_H 0x03
#define LSM303DLHC_REG_MAG_Y_H 0x05
#define LSM303DLHC_REG_MAG_Z_H 0x07
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

static int i2c_fd = -1;
static FILE *csv_file = NULL;

void cleanup(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    exit(0);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int open_i2c_device() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303DLHC_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int read_magnetometer(int reg, int *value) {
    char buf[2];
    buf[0] = reg;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

double calculate_heading(int x, int y) {
    double heading = atan2((double)y, (double)x) * 180.0 / M_PI;
    if (heading < 0) {
        heading += 360.0;
    }
    return heading;
}

const char* get_compass_direction(double heading) {
    if (heading < 22.5 || heading >= 337.5) return "N";
    if (heading < 67.5) return "NE";
    if (heading < 112.5) return "E";
    if (heading < 157.5) return "SE";
    if (heading < 202.5) return "S";
    if (heading < 247.5) return "SW";
    if (heading < 292.5) return "W";
    return "NW";
}

int main() {
    setup_signal_handlers();

    if (open_i2c_device() != 0) {
        return EXIT_FAILURE;
    }

    if ((csv_file = fopen("mag_log.csv", "a+")) == NULL) {
        perror("Failed to open CSV file");
        cleanup(0);
        return EXIT_FAILURE;
    }

    char header[] = "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n";
    if (fseek(csv_file, 0, SEEK_SET) == 0) {
        if (fgetc(csv_file) == EOF) {
            fwrite(header, 1, sizeof(header) - 1, csv_file);
        }
    }

    while (1) {
        int x_raw, y_raw, z_raw;
        if (read_magnetometer(LSM303DLHC_REG_MAG_X_H, &x_raw) != 0 ||
            read_magnetometer(LSM303DLHC_REG_MAG_Y_H, &y_raw) != 0 ||
            read_magnetometer(LSM303DLHC_REG_MAG_Z_H, &z_raw) != 0) {
            continue;
        }

        int x_calibrated = x_raw + X_OFFSET;
        int y_calibrated = y_raw + Y_OFFSET;
        int z_calibrated = z_raw + Z_OFFSET;

        double heading = calculate_heading(x_calibrated, y_calibrated);
        const char *direction = get_compass_direction(heading);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(csv_file, "%s, %d, %d, %d, %.2f\n", timestamp, x_calibrated, y_calibrated, z_calibrated, heading);
        fflush(csv_file);

        printf("Direction: %s, Heading: %.2f\n", direction, heading);

        sleep(1);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

