#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <json-c/json.h>

#define TOUCH_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_MS 200

static volatile int running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *touch_line;
static struct gpiod_line *relay_line;
static FILE *log_file;
static time_t last_touch_time = 0;

void handle_sigint(int sig) {
    running = 0;
    gpiod_line_set_value(relay_line, 0);
    log_relay_state("OFF");
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

void log_relay_state(const char *state) {
    json_object *jobj = json_object_new_object();
    json_object *jstate = json_object_new_string(state);
    json_object *jtimestamp = json_object_new_string(ctime(&time(NULL)));
    json_object_object_add(jobj, "relay_state", jstate);
    json_object_object_add(jobj, "timestamp", jtimestamp);

    fprintf(log_file, "%s\n", json_object_to_json_string(jobj));
    fflush(log_file);

    json_object_put(jobj);
}

void touch_handler(struct gpiod_line *line) {
    time_t current_time = time(NULL);
    if (difftime(current_time, last_touch_time) >= DEBOUNCE_MS / 1000.0) {
        last_touch_time = current_time;
        int relay_state = gpiod_line_get_value(relay_line);
        gpiod_line_set_value(relay_line, !relay_state);
        log_relay_state(gpiod_line_get_value(relay_line) ? "ON" : "OFF");
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_GPIO);
    if (!touch_line) {
        perror("Failed to get touch line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(touch_line, "touch_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES | GPIOD_LINE_REQ_DIR_IN) < 0) {
        perror("Failed to request touch line");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(relay_line, "relay", GPIOD_LINE_REQ_DIR_OUT) < 0) {
        perror("Failed to request relay line");
        gpiod_line_release(relay_line);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_set_value(relay_line, 0);

    log_file = fopen("relay_log.json", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(relay_line);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        gpiod_line_event_wait(touch_line, -1);
        touch_handler(touch_line);
    }

    handle_sigint(0);
    return EXIT_SUCCESS;
}

