This code sets up a Raspberry Pi to monitor a TTP223 capacitive touch sensor and toggle a relay with debouncing and logging. It handles signals for clean termination and logs state changes in JSON format.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define RELAY_COUNT 4
#define RELAY_GPIO_PINS {17, 23, 24, 25}
#define MOISTURE_THRESHOLD 30
#define RELAY_ACTIVE_LOW 0
#define RELAY_INACTIVE_HIGH 1
#define RELAY_ON_DURATION 5
#define RELAY_GAP_DURATION 1
#define LOG_FILE "irrigation_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *lines[RELAY_COUNT];
static int log_fd = -1;
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

void log_irrigation(int relay, int moisture) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    char log_entry[100];
    snprintf(log_entry, sizeof(log_entry), "%s Relay %d Moisture %d\n", timestamp, relay + 1, moisture);

    if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    }
    if (fsync(log_fd) < 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
    }
}

void activate_relay(int relay) {
    if (gpiod_line_set_value(lines[relay], RELAY_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to activate relay %d: %s\n", relay + 1, strerror(errno));
    }
    sleep(RELAY_ON_DURATION);
}

void deactivate_relay(int relay) {
    if (gpiod_line_set_value(lines[relay], RELAY_INACTIVE_HIGH) < 0) {
        fprintf(stderr, "Failed to deactivate relay %d: %s\n", relay + 1, strerror(errno));
    }
}

void cleanup() {
    if (log_fd != -1) {
        close(log_fd);
    }
    for (int i = 0; i < RELAY_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
}

int main() {
    srand(time(NULL));

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, RELAY_GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d: %s\n", RELAY_GPIO_PINS[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], "relay", 0) < 0) {
            fprintf(stderr, "Failed to request line %d as output: %s\n", RELAY_GPIO_PINS[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (!stop) {
        int moisture = rand() % 101;
        if (moisture < MOISTURE_THRESHOLD) {
            for (int i = 0; i < RELAY_COUNT; i++) {
                activate_relay(i);
                log_irrigation(i, moisture);
                deactivate_relay(i);
                if (i < RELAY_COUNT - 1) {
                    sleep(RELAY_GAP_DURATION);
                }
            }
        }
        sleep(10);
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
        deactivate_relay(i);
    }

    cleanup();
    return EXIT_SUCCESS;
}

