int safe_gpio_servo(int pin, int pulse_width) {
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (gpioServo(pin, pulse_width) == 0) {
            return 0;
        }
        if (attempt < MAX_RETRIES - 1) {
            usleep(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioServo(VALVE_PIN, 0) != 0 || gpioServo(NOZZLE_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize servos: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int moisture_values[] = {20, 40, 60, 80, 100};
    int num_values = sizeof(moisture_values) / sizeof(moisture_values[0]);
    int current_value_index = 0;

    while (!stop_flag) {
        int moisture = moisture_values[current_value_index];
        printf("Current moisture level: %d\n", moisture);

        if (moisture < 50) {
            if (safe_gpio_servo(VALVE_PIN, 1500) != 0) {
                fprintf(stderr, "Critical: Failed to open valve\n");
                gpioTerminate();
                return EXIT_FAILURE;
            }

            int angles[] = {500, 1000, 1500, 2000, 2500};
            int num_angles = sizeof(angles) / sizeof(angles[0]);

            for (int i = 0; i < num_angles; ++i) {
                if (stop_flag) break;

                if (safe_gpio_servo(NOZZLE_PIN, angles[i]) != 0) {
                    fprintf(stderr, "Warning: Failed to set nozzle to %d degrees\n", angles[i] * 0.1);
                    continue;
                }

                sleep(2);
            }

            sleep(5);

            if (safe_gpio_servo(VALVE_PIN, 500) != 0) {
                fprintf(stderr, "Critical: Failed to close valve\n");
            }

            sleep(5);
        }

        current_value_index = (current_value_index + 1) % num_values;
        sleep(1);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

