#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <string.h>

#define MPU6050_ADDRESS 0x68
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_GYRO_YOUT_H 0x45
#define MPU6050_REG_GYRO_ZOUT_H 0x47

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int i2c_init(const char *device) {
    int file;
    if ((file = open(device, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }
    return file;
}

int mpu6050_init(int file) {
    if (ioctl(file, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    // Wake up the MPU-6050
    if (write(file, &MPU6050_REG_PWR_MGMT_1, 1) != 1 ||
        write(file, &0x00, 1) != 1) {
        perror("Failed to write to MPU-6050");
        return -1;
    }
    return 0;
}

int read_gyro(int file, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[6];
    if (read(file, buffer, 6) != 6) {
        perror("Failed to read from MPU-6050");
        return -1;
    }

    *gyro_x = (int16_t)(buffer[0] << 8 | buffer[1]);
    *gyro_y = (int16_t)(buffer[2] << 8 | buffer[3]);
    *gyro_z = (int16_t)(buffer[4] << 8 | buffer[5]);

    return 0;
}

void log_data(FILE *file, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s, %d, %d, %d\n", timestamp, gyro_x, gyro_y, gyro_z);
    fflush(file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    const char *i2c_device = "/dev/i2c-1";
    int i2c_file = i2c_init(i2c_device);
    if (i2c_file < 0) {
        return EXIT_FAILURE;
    }

    if (mpu6050_init(i2c_file) < 0) {
        close(i2c_file);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_file);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int16_t gyro_x, gyro_y, gyro_z;
        if (read_gyro(i2c_file, &gyro_x, &gyro_y, &gyro_z) == 0) {
            log_data(log_file, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error reading gyro data\n");
        }
        usleep(100000); // Sleep for 100ms to achieve 10Hz sampling rate
    }

    fclose(log_file);
    close(i2c_file);
    return EXIT_SUCCESS;
}

