#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22

#define DEBOUNCE_DELAY 200000 // 200 ms in nanoseconds
#define STEP_DELAY 3000000    // 3 ms in nanoseconds
#define STEPS 512

static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void set_pins(gpiod_chip *chip, int *pins, int value) {
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_set_value(pins[i], value) < 0) {
            fprintf(stderr, "Error setting pin value\n");
            exit(EXIT_FAILURE);
        }
    }
}

void rotate_motor(gpiod_chip *chip, int *pins, int steps, int direction) {
    int sequence[4] = {0x09, 0x05, 0x06, 0x03};
    if (direction == -1) {
        // Reverse the sequence for counter-clockwise
        int temp[4];
        for (int i = 0; i < 4; i++) {
            temp[i] = sequence[3 - i];
        }
        for (int i = 0; i < 4; i++) {
            sequence[i] = temp[i];
        }
    }

    for (int i = 0; i < steps; i++) {
        for (int j = 0; j < 4; j++) {
            if (gpiod_line_set_value(pins[j], (sequence[j] >> i % 4) & 0x01) < 0) {
                fprintf(stderr, "Error setting pin value during rotation\n");
                exit(EXIT_FAILURE);
            }
            usleep(STEP_DELAY / 1000);
        }
    }
    set_pins(chip, pins, 0); // De-energize all coils
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lock_button, *unlock_button;
    struct gpiod_line *pins[4];
    int pin_numbers[4] = {IN1, IN2, IN3, IN4};

    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    lock_button = gpiod_chip_get_line(chip, LOCK_BUTTON);
    if (!lock_button) {
        fprintf(stderr, "Failed to get lock button line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(lock_button, "lock_button", GPIOD_LINE_REQ_EV_BOTH_EDGES | GPIOD_LINE_REQ_DEBOUNCE) < 0) {
        fprintf(stderr, "Failed to request lock button line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    unlock_button = gpiod_chip_get_line(chip, UNLOCK_BUTTON);
    if (!unlock_button) {
        fprintf(stderr, "Failed to get unlock button line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(unlock_button, "unlock_button", GPIOD_LINE_REQ_EV_BOTH_EDGES | GPIOD_LINE_REQ_DEBOUNCE) < 0) {
        fprintf(stderr, "Failed to request unlock button line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        pins[i] = gpiod_chip_get_line(chip, pin_numbers[i]);
        if (!pins[i]) {
            fprintf(stderr, "Failed to get pin line for pin %d\n", pin_numbers[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(pins[i], "motor_pin", 0) < 0) {
            fprintf(stderr, "Failed to request output for pin %d\n", pin_numbers[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    set_pins(chip, pins, 0); // Ensure all pins are low initially

    while (keep_running) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(lock_button, DEBOUNCE_DELAY) > 0) {
            if (gpiod_line_event_read(lock_button, &event) == 0) {
                if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                    printf("Lock button pressed\n");
                    rotate_motor(chip, pins, STEPS, 1);
                }
            }
        }

        if (gpiod_line_event_wait(unlock_button, DEBOUNCE_DELAY) > 0) {
            if (gpiod_line_event_read(unlock_button, &event) == 0) {
                if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                    printf("Unlock button pressed\n");
                    rotate_motor(chip, pins, STEPS, -1);
                }
            }
        }
    }

    set_pins(chip, pins, 0); // De-energize all coils on exit

    for (int i = 0; i < 4; i++) {
        gpiod_line_release(pins[i]);
    }
    gpiod_line_release(lock_button);
    gpiod_line_release(unlock_button);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

