    ret = gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, TIMEOUT_MS * 1000);
    if (ret < 0) {
        fprintf(stderr, "Timeout waiting for rising edge: %s\n", strerror(-ret));
        return -1;
