    ret = gpiod_line_event_read(echo_line, &event);
    if (ret < 0) {
        fprintf(stderr, "Failed to read falling edge event: %s\n", strerror(-ret));
        return -1;
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate pulse width
    pulse_width_ns = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);

