#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_ADDR 0x29
#define GPIO_RELAY 18
#define POLL_INTERVAL 100000 // 100 ms in microseconds
#define MAX_DISTANCE 50 // cm

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int setup_gpio(gpiod_chip *chip, gpiod_line *line) {
    line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(line, "relay_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

int setup_i2c(int *fd) {
    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

int read_distance(int fd, int *distance) {
    uint8_t data[2];
    int ret;

    // Read distance from the sensor
    ret = read(fd, data, sizeof(data));
    if (ret < 0) {
        fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
        return -1;
    } else if (ret != sizeof(data)) {
        fprintf(stderr, "Incomplete read from sensor\n");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];

    return 0;
}

void cleanup(gpiod_chip *chip, gpiod_line *line, int i2c_fd) {
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main() {
    struct sigaction sa;
    gpiod_chip *chip;
    gpiod_line *line = NULL;
    int i2c_fd = -1;
    int distance;

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (setup_gpio(chip, line) < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (setup_i2c(&i2c_fd) < 0) {
        cleanup(chip, line, i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (read_distance(i2c_fd, &distance) < 0) {
            fprintf(stderr, "Error reading distance\n");
        } else {
            printf("Distance: %d cm\n", distance);
            if (distance <= MAX_DISTANCE) {
                gpiod_line_set_value(line, 1);
            } else {
                gpiod_line_set_value(line, 0);
            }
        }
        usleep(POLL_INTERVAL);
    }

    cleanup(chip, line, i2c_fd);
    return EXIT_SUCCESS;
}

