#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDRESS 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_write_byte_data(int file, uint8_t reg, uint8_t data) {
    if (ioctl(file, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(file, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (write(file, &data, 1) != 1) {
        perror("Failed to write data");
        return -1;
    }

    return 0;
}

int i2c_read_bytes(int file, uint8_t reg, uint8_t *buf, int length) {
    if (ioctl(file, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(file, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(file, buf, length) != length) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

int main() {
    int file;
    uint8_t data[6];
    float gyro_x, gyro_y, gyro_z;

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    // Initialize MPU6050
    if (i2c_write_byte_data(file, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        close(file);
        return EXIT_FAILURE;
    }

    if (i2c_write_byte_data(file, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        close(file);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (i2c_read_bytes(file, MPU6050_GYRO_XOUT_H, data, 6) < 0) {
            fprintf(stderr, "Error reading from MPU6050\n");
            continue;
        }

        gyro_x = (float)((int16_t)(data[0] << 8 | data[1])) / 131.0;
        gyro_y = (float)((int16_t)(data[2] << 8 | data[3])) / 131.0;
        gyro_z = (float)((int16_t)(data[4] << 8 | data[5])) / 131.0;

        printf("Gyro X: %.2f, Gyro Y: %.2f, Gyro Z: %.2f\n", gyro_x, gyro_y, gyro_z);
        usleep(100000); // 100 ms delay
    }

    close(file);
    return EXIT_SUCCESS;
}

