#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define PWM_FREQ 1000
#define PWM_PERIOD 1000
#define PWM_MAX_DUTY 255
#define DURATION 1800 // 30 minutes in seconds
#define STEP_INTERVAL 1 // 1 second

const char *relay_pins[] = {"gpio17", "gpio18", "gpio27", "gpio22"};
const int wiringPi_pins[] = {0, 1, 2, 3};

gpiod_chip *chip;
gpiod_line *lines[NUM_RELAYS];
gpiod_line *pwm_lines[NUM_RELAYS];
int pwm_fds[NUM_RELAYS];
FILE *log_file;

void log_event(const char *event) {
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", timestamp, event);
        fflush(log_file);
    }
}

void cleanup() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (pwm_lines[i]) {
            gpiod_line_release(pwm_lines[i]);
        }
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void handle_signal(int sig) {
    log_event("Received termination signal");
    cleanup();
    exit(0);
}

int setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpiod_chip_get_line_by_name(chip, relay_pins[i]));
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            cleanup();
            return -1;
        }

        if (gpiod_line_request_output(lines[i], "relay", 0) < 0) {
            perror("Failed to request GPIO line as output");
            cleanup();
            return -1;
        }
    }

    return 0;
}

int setup_pwm() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        pwm_lines[i] = gpiod_chip_get_line(chip, gpiod_chip_get_line_by_name(chip, relay_pins[i]));
        if (!pwm_lines[i]) {
            perror("Failed to get PWM line");
            cleanup();
            return -1;
        }

        if (gpiod_line_request(pwm_lines[i], "pwm", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0) {
            perror("Failed to request PWM line");
            cleanup();
            return -1;
        }

        if (gpiod_line_set_flags(pwm_lines[i], GPIOD_LINE_FLAG_ACTIVE_LOW) < 0) {
            perror("Failed to set PWM line flags");
            cleanup();
            return -1;
        }

        pwm_fds[i] = gpiod_line_handle_event_rising(pwm_lines[i], NULL, NULL);
        if (pwm_fds[i] < 0) {
            perror("Failed to handle PWM line event");
            cleanup();
            return -1;
        }

        if (gpiod_line_set_request(pwm_lines[i], "pwm", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0) {
            perror("Failed to set PWM line request");
            cleanup();
            return -1;
        }

        if (gpiod_line_set_consumer(pwm_lines[i], "pwm") < 0) {
            perror("Failed to set PWM line consumer");
            cleanup();
            return -1;
        }

        if (gpiod_line_set_range(pwm_lines[i], PWM_FREQ, PWM_PERIOD) < 0) {
            perror("Failed to set PWM line range");
            cleanup();
            return -1;
        }
    }

    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen("smart_lighting.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    log_event("Program started");

    if (setup_gpio() < 0) {
        log_event("GPIO setup failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (setup_pwm() < 0) {
        log_event("PWM setup failed");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("GPIO and PWM setup completed");

    for (int i = 0; i <= PWM_MAX_DUTY; i++) {
        for (int j = 0; j < NUM_RELAYS; j++) {
            if (gpiod_line_set_value(pwm_lines[j], i) < 0) {
                perror("Failed to set PWM value");
                cleanup();
                return EXIT_FAILURE;
            }
        }
        log_event("Increased PWM duty cycle");
        sleep(STEP_INTERVAL);
    }

    log_event("Sunrise effect completed");

    cleanup();
    return EXIT_SUCCESS;
}

