#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <time.h>

#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_BUFFER_SIZE 100
#define LED_GPIO 17
#define LED_ACTIVE_HIGH 1
#define LED_ACTIVE_LOW 0
#define GYRO_THRESHOLD 250
#define SAMPLE_PERIOD_MS 50

struct gyro_data {
    time_t timestamp;
    int16_t x, y, z;
};

struct gyro_data gyro_buffer[MPU6050_BUFFER_SIZE];
int buffer_index = 0;
int i2c_fd = -1;
int led_chip, led_line;

void handle_signal(int sig) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (led_chip >= 0) {
        gpiod_line_set_value(led_line, LED_ACTIVE_LOW);
        gpiod_chip_close(led_chip);
    }
    exit(0);
}

int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    uint8_t data = 0x00;
    if (write(i2c_fd, &data, 1) != 1) {
        perror("Failed to write to MPU6050");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int read_gyro(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Failed to read from MPU6050");
        return -1;
    }

    *x = (int16_t)(buffer[0] << 8 | buffer[1]);
    *y = (int16_t)(buffer[2] << 8 | buffer[3]);
    *z = (int16_t)(buffer[4] << 8 | buffer[5]);

    return 0;
}

void init_led() {
    led_chip = gpiod_chip_open("/dev/gpiochip0");
    if (led_chip < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    led_line = gpiod_chip_get_line(led_chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(led_chip);
        exit(1);
    }

    if (gpiod_line_request_output(led_line, "gyro_led", LED_ACTIVE_LOW) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(led_chip);
        exit(1);
    }
}

void update_led(int16_t x, int16_t y, int16_t z) {
    if (abs(x) > GYRO_THRESHOLD || abs(y) > GYRO_THRESHOLD || abs(z) > GYRO_THRESHOLD) {
        gpiod_line_set_value(led_line, LED_ACTIVE_HIGH);
    } else {
        gpiod_line_set_value(led_line, LED_ACTIVE_LOW);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        exit(1);
    }

    init_led();

    while (1) {
        int16_t x, y, z;
        int retries = 3;

        while (retries-- > 0) {
            if (read_gyro(&x, &y, &z) == 0) {
                break;
            }
            if (retries == 0) {
                fprintf(stderr, "Failed to read from MPU6050 after 3 attempts\n");
                close(i2c_fd);
                i2c_fd = -1;
                exit(1);
            }
            if (init_i2c() < 0) {
                fprintf(stderr, "I2C re-initialization failed\n");
                exit(1);
            }
        }

        gyro_buffer[buffer_index].timestamp = time(NULL);
        gyro_buffer[buffer_index].x = x;
        gyro_buffer[buffer_index].y = y;
        gyro_buffer[buffer_index].z = z;
        buffer_index = (buffer_index + 1) % MPU6050_BUFFER_SIZE;

        update_led(x, y, z);

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    return 0;
}

