        gpiod_line_set_value(led_line, LED_ACTIVE_HIGH);
    } else {
        gpiod_line_set_value(led_line, LED_ACTIVE_LOW);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        exit(1);
    }

    init_led();

    while (1) {
        int16_t x, y, z;
        int retries = 3;

        while (retries-- > 0) {
            if (read_gyro(&x, &y, &z) == 0) {
                break;
            }
            if (retries == 0) {
                fprintf(stderr, "Failed to read from MPU6050 after 3 attempts\n");
                close(i2c_fd);
                i2c_fd = -1;
                exit(1);
            }
            if (init_i2c() < 0) {
                fprintf(stderr, "I2C re-initialization failed\n");
                exit(1);
            }
        }

        gyro_buffer[buffer_index].timestamp = time(NULL);
        gyro_buffer[buffer_index].x = x;
        gyro_buffer[buffer_index].y = y;
        gyro_buffer[buffer_index].z = z;
        buffer_index = (buffer_index + 1) % MPU6050_BUFFER_SIZE;

        update_led(x, y, z);

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    return 0;
}
