#define SPI_CS_HIGH 1
#define SPI_RETRY_LIMIT 3
#define READ_INTERVAL_MS 10

static int spi_fd = -1;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;

void cleanup() {
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void handle_signal(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int setup_spi() {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)0,
        .rx_buf = (unsigned long)malloc(6),
        .len = 6,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0,
        .pad = 0
    };

    if (transfer.rx_buf == NULL) {
        perror("Failed to allocate memory for SPI transfer");
        return -1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        free(transfer.rx_buf);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI parameters");
        close(spi_fd);
        free(transfer.rx_buf);
        return -1;
    }

    return 0;
}

int setup_gpio() {
    int line = gpiod_chip_open(GPIO_CHIP);
    if (line < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(line, GPIO_LINE_OFFSET);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(line);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "MPU9250_CS", SPI_CS_HIGH) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(cs_line);
        gpiod_chip_close(line);
        return -1;
    }

    return 0;
}

int read_gyro_data(int16_t *x_rate, int16_t *y_rate, int16_t *z_rate) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)0,
        .rx_buf = (unsigned long)malloc(6),
        .len = 6,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0,
        .pad = 0
    };

    if (transfer.rx_buf == NULL) {
        perror("Failed to allocate memory for SPI transfer");
        return -1;
    }

    gpiod_line_set_value(cs_line, SPI_CS_LOW);

    for (int attempt = 0; attempt < SPI_RETRY_LIMIT; ++attempt) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
            perror("SPI transfer failed");
            gpiod_line_set_value(cs_line, SPI_CS_HIGH);
            free(transfer.rx_buf);
            return -1;
        }

        *x_rate = (int16_t)(transfer.rx_buf[0] << 8 | transfer.rx_buf[1]);
        *y_rate = (int16_t)(transfer.rx_buf[2] << 8 | transfer.rx_buf[3]);
        *z_rate = (int16_t)(transfer.rx_buf[4] << 8 | transfer.rx_buf[5]);

        gpiod_line_set_value(cs_line, SPI_CS_HIGH);
        free(transfer.rx_buf);
        return 0;
    }

    gpiod_line_set_value(cs_line, SPI_CS_HIGH);
    free(transfer.rx_buf);
    return -1;
}

void log_gyro_data(int16_t x_rate, int16_t y_rate, int16_t z_rate) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("Failed to get current time");
        return;
    }

    char timestamp[64];
    snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02dT%02d:%02d:%02d.%09ld",
             1900 + ts.tv_sec / 31557600,
             1 + (ts.tv_sec / 31557600 / 12) % 12,
             ts.tv_sec / 31557600 % 12 % 12 + 1,
             ts.tv_sec / 86400 % 24,
             ts.tv_sec / 3600 % 24,
             ts.tv_sec / 60 % 60,
             ts.tv_nsec);

    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        perror("Failed to write to log file");
    }
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR ||
        signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (setup_spi() != 0 || setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        int16_t x_rate, y_rate, z_rate;
        if (read_gyro_data(&x_rate, &y_rate, &z_rate) == 0) {
            log_gyro_data(x_rate, y_rate, z_rate);
        } else {
            fprintf(stderr, "SPI communication error\n");
        }

        usleep(READ_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

