#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 3900000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_CS_PIN 8
#define LED_PIN 17
#define BUFFER_SIZE 64
#define WARNING_THRESHOLD 200

typedef struct {
    struct timespec timestamp;
    int16_t x, y, z;
} GyroSample;

GyroSample buffer[BUFFER_SIZE];
int buffer_index = 0;
int spi_fd = -1;
int led_gpio_chip;
struct gpiod_line *led_line;
volatile bool running = true;

void handle_sigint(int sig) {
    running = false;
}

void blink_led() {
    gpiod_line_set_value(led_line, 1);
    usleep(500000);
    gpiod_line_set_value(led_line, 0);
    usleep(500000);
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx[] = {0x43, 0x00}; // Register address for X-axis
    uint8_t rx[6];

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    *x = (int16_t)(rx[0] << 8 | rx[1]);
    *y = (int16_t)(rx[2] << 8 | rx[3]);
    *z = (int16_t)(rx[4] << 8 | rx[5]);

    return 0;
}

void print_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%ld.%09ld,%d,%d,%d\n",
               buffer[i].timestamp.tv_sec,
               buffer[i].timestamp.tv_nsec,
               buffer[i].x,
               buffer[i].y,
               buffer[i].z);
    }
}

void cleanup() {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (led_gpio_chip) {
        gpiod_chip_close(led_gpio_chip);
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    led_gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!led_gpio_chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(led_gpio_chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(led_gpio_chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "warning_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(led_gpio_chip);
        return EXIT_FAILURE;
    }

    if (init_spi() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        int16_t x, y, z;
        if (read_gyro_data(&x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read gyro data\n");
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &buffer[buffer_index].timestamp);
        buffer[buffer_index].x = x;
        buffer[buffer_index].y = y;
        buffer[buffer_index].z = z;

        if (abs(x) > WARNING_THRESHOLD || abs(y) > WARNING_THRESHOLD || abs(z) > WARNING_THRESHOLD) {
            blink_led();
        }

        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        usleep(10000); // 10 ms delay
    }

    print_buffer();
    cleanup();
    return EXIT_SUCCESS;
}

