#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <poll.h>
#include <linux/gpio.h>
#include <sys/types.h>
#include <sys/stat.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x60
#define GPIO_LED 17
#define RETRY_LIMIT 3
#define RETRY_DELAY 10 // milliseconds
#define READ_INTERVAL 100 // milliseconds

int i2c_fd = -1;
int gpio_fd = -1;
FILE *log_file = NULL;

void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpio_fd != -1) {
        ioctl(gpio_fd, GPIO_CLEAR, GPIO_LED);
        close(gpio_fd);
    }
    exit(0);
}

int setup_gpio() {
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO");
        return -1;
    }

    struct gpiohandle_request req = {
        .lineoffsets = &GPIO_LED,
        .flags = GPIOHANDLE_REQUEST_OUTPUT,
        .lines = 1
    };

    int gpio_handle = ioctl(gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, &req);
    if (gpio_handle < 0) {
        perror("Failed to get GPIO line handle");
        close(gpio_fd);
        return -1;
    }

    return 0;
}

int read_sensor(int *ambient_light, int *proximity) {
    char buf[3];
    int retries = 0;
    int result = -1;

    while (retries < RETRY_LIMIT) {
        buf[0] = 0x80; // Command to read ambient light
        if (write(i2c_fd, buf, 1) != 1) {
            perror("Failed to write to I2C");
            retries++;
            usleep(RETRY_DELAY * 1000);
            continue;
        }

        if (read(i2c_fd, buf, 2) != 2) {
            perror("Failed to read from I2C");
            retries++;
            usleep(RETRY_DELAY * 1000);
            continue;
        }

        *ambient_light = (buf[0] << 8) | buf[1];
        result = 0;

        buf[0] = 0x81; // Command to read proximity
        if (write(i2c_fd, buf, 1) != 1) {
            perror("Failed to write to I2C");
            retries++;
            usleep(RETRY_DELAY * 1000);
            continue;
        }

        if (read(i2c_fd, buf, 2) != 2) {
            perror("Failed to read from I2C");
            retries++;
            usleep(RETRY_DELAY * 1000);
            continue;
        }

        *proximity = (buf[0] << 8) | buf[1];
        result = 0;
        break;
    }

    return result;
}

void log_data(int ambient_light, int proximity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,AmbientLight:%04X,Proximity:%04X\n", time_str, ambient_light, proximity);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct pollfd fds[1];
    fds[0].fd = i2c_fd;
    fds[0].events = POLLIN;

    int ambient_light, proximity;

    while (1) {
        int ret = poll(fds, 1, READ_INTERVAL);
        if (ret < 0) {
            perror("Poll error");
            break;
        }

        if (ret > 0) {
            if (read_sensor(&ambient_light, &proximity) == 0) {
                log_data(ambient_light, proximity);
                if (proximity > 100) {
                    ioctl(gpio_fd, GPIO_SET_LINE_VALUES_IOCTL, GPIO_LED);
                } else {
                    ioctl(gpio_fd, GPIO_CLEAR, GPIO_LED);
                }
            }
        }
    }

    handle_signal(0);
    return EXIT_SUCCESS;
}

