    exit_flag = 1;
}

int init_spi() {
    struct spi_ioc_transfer transfer;
    uint8_t tx_buf[3] = {0};
    uint8_t rx_buf[3] = {0};

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI parameters");
        close(spi_fd);
        return -1;
    }

    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)tx_buf;
    transfer.rx_buf = (unsigned long)rx_buf;
    transfer.len = 3;
    transfer.speed_hz = SPI_SPEED;
    transfer.bits_per_word = SPI_BITS_PER_WORD;

    return 0;
}

int init_gpio() {
    cs_fd = gpiod_chip_open("/dev/gpiochip0");
    if (cs_fd < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    struct gpiod_line_request req = {
        .consumer_label = "SPI_CS",
        .flags = GPIOD_LINE_REQUEST_OUTPUT,
        .line_offset = SPI_CS_LINE,
        .default_value = 1
    };

    cs_fd = gpiod_line_request(cs_fd, &req);
    if (cs_fd < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(cs_fd);
        return -1;
    }

    return 0;
}

void cleanup() {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (cs_fd >= 0) {
        gpiod_line_release(cs_fd);
        gpiod_chip_close(cs_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int read_gyro(uint8_t reg, int16_t *value) {
    struct spi_ioc_transfer transfer;
    uint8_t tx_buf[3] = {reg | 0x80, 0x00, 0x00};
    uint8_t rx_buf[3] = {0};

    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)tx_buf;
    transfer.rx_buf = (unsigned long)rx_buf;
    transfer.len = 3;
    transfer.speed_hz = SPI_SPEED;
    transfer.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    *value = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
    return 0;
