#define SEISMIC_THRESHOLD 500

static int alert_fd = -1;
static int sensor1_fd = -1;
static int sensor2_fd = -1;
static int log_fd = -1;
static int alert_state = 0;
static int sensor1_state = 0;
static int sensor2_state = 0;
static int seismic_timer = 0;
static struct timespec last_event_time;

static void log_seismic_event() {
    if (log_fd < 0) return;

    char buffer[256];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", tm_info);
    dprintf(log_fd, "%s - Seismic event detected!\n", buffer);
}

static void handle_alert(int fd, unsigned int events, void *user_data) {
    (void)fd;
    (void)events;
    (void)user_data;

    if (sensor1_state && sensor2_state) {
        if (seismic_timer == 0) {
            clock_gettime(CLOCK_MONOTONIC, &last_event_time);
        }

        clock_gettime(CLOCK_MONOTONIC, &last_event_time);
        long elapsed_ms = (last_event_time.tv_sec - last_event_time.tv_sec) * 1000 +
                          (last_event_time.tv_nsec - last_event_time.tv_nsec) / 1000000;

        if (elapsed_ms >= SEISMIC_THRESHOLD) {
            if (alert_state == 0) {
                gpiod_line_set_value(alert_fd, 1);
                alert_state = 1;
                seismic_timer = ALERT_DURATION * 1000;
                log_seismic_event();
            }
        }
    } else {
        seismic_timer = 0;
    }

    if (alert_state == 1) {
        seismic_timer -= 10; // Assuming callback is called every 10ms
        if (seismic_timer <= 0) {
            gpiod_line_set_value(alert_fd, 0);
            alert_state = 0;
        }
    }
}

static void cleanup(int signum) {
    if (alert_fd >= 0) {
        gpiod_line_set_value(alert_fd, 0);
        gpiod_line_release(alert_fd);
    }
    if (sensor1_fd >= 0) {
        gpiod_line_release(sensor1_fd);
    }
    if (sensor2_fd >= 0) {
        gpiod_line_release(sensor2_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *alert_line, *sensor1_line, *sensor2_line;
    struct gpiod_line_event_handler event_handler = {
        .handler = handle_alert,
        .private_data = NULL
    };

    // Initialize signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO library
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Open alert line
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!alert_line) {
        perror("Failed to get alert line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    alert_fd = gpiod_line_request(alert_line, "alert", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    if (alert_fd < 0) {
        perror("Failed to request alert line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open sensor1 line
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        perror("Failed to get sensor1 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    sensor1_fd = gpiod_line_request(sensor1_line, "sensor1", GPIOD_LINE_REQUEST_DIRECTIONS_INPUT);
    if (sensor1_fd < 0) {
        perror("Failed to request sensor1 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open sensor2 line
    sensor2_line = gpiod_chip_get_line(chip);
    if (!sensor2_line) {
        perror("Failed to get sensor2 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    sensor2_fd = gpiod_line_request(sensor2_line, "sensor2", GPIOD_LINE_REQUEST_DIRECTIONS_INPUT);
    if (sensor2_fd < 0) {
        perror("Failed to request sensor2 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Register event handlers
    if (gpiod_line_event_both_edges(sensor1_line) < 0 ||
        gpiod_line_event_both_edges(sensor2_line) < 0 ||
        gpiod_line_event_register(sensor1_line, &event_handler, NULL) < 0 ||
        gpiod_line_event_register(sensor2_line, &event_handler, NULL) < 0) {
        perror("Failed to register event handlers");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_fd = open("seismic_events.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        usleep(10000); // Sleep for 10ms
    }

    // Cleanup
    cleanup(0);
    return EXIT_SUCCESS;
}

