#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CE_PIN 8
#define LED_PIN 17
#define BUFFER_SIZE 100
#define THRESHOLD 20.0

typedef struct {
    double rate;
    struct timespec timestamp;
} GyroData;

typedef struct {
    GyroData buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    int full;
    pthread_mutex_t lock;
} CircularBuffer;

CircularBuffer gyroBuffer;
volatile sig_atomic_t keepRunning = 1;

void signalHandler(int sig) {
    keepRunning = 0;
}

void initGyroBuffer() {
    gyroBuffer.head = 0;
    gyroBuffer.tail = 0;
    gyroBuffer.count = 0;
    gyroBuffer.full = 0;
    pthread_mutex_init(&gyroBuffer.lock, NULL);
}

void pushGyroData(double rate, struct timespec ts) {
    pthread_mutex_lock(&gyroBuffer.lock);
    gyroBuffer.buffer[gyroBuffer.head].rate = rate;
    gyroBuffer.buffer[gyroBuffer.head].timestamp = ts;
    if (gyroBuffer.full) {
        gyroBuffer.tail = (gyroBuffer.tail + 1) % BUFFER_SIZE;
    } else {
        gyroBuffer.count++;
    }
    gyroBuffer.head = (gyroBuffer.head + 1) % BUFFER_SIZE;
    gyroBuffer.full = gyroBuffer.count == BUFFER_SIZE;
    pthread_mutex_unlock(&gyroBuffer.lock);
}

double readGyroXRate() {
    uint8_t address = 0x00 | 0x80; // Read X-axis rate, MSB set to 1
    uint8_t data[2];
    int result;

    result = pi_spi_writeread(SPI_CHANNEL, &address, 1, data, 2);
    if (result < 0) {
        fprintf(stderr, "SPI read error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    int16_t rawRate = (data[0] << 8) | data[1];
    double rate = rawRate * 0.07; // Conversion factor for ADXRS290
    return rate;
}

void setupGPIO() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(CE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CE pin mode: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    gpioWrite(LED_PIN, 0);
    gpioWrite(CE_PIN, 1);
}

void cleanup() {
    gpioTerminate();
    pthread_mutex_destroy(&gyroBuffer.lock);
}

int main() {
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    initGyroBuffer();
    setupGPIO();

    if (pi_spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel: %s\n", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (keepRunning) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        double rate = readGyroXRate();
        pushGyroData(rate, ts);

        if (rate > THRESHOLD) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        usleep(10000); // 10 ms delay
    }

    pi_spi_close(SPI_CHANNEL);
    cleanup();
    return 0;
}

