        exit(EXIT_FAILURE);
    }

    while (keepRunning) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        double rate = readGyroXRate();
        pushGyroData(rate, ts);

        if (rate > THRESHOLD) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        usleep(10000); // 10 ms delay
    }

    pi_spi_close(SPI_CHANNEL);
    cleanup();
    return 0;
}
