#define YELLOW_PIN 22
#define GREEN_PIN 23
#define YELLOW2_PIN 24

#define RED 0
#define YELLOW 1
#define GREEN 2
#define YELLOW2 3

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        exit(EXIT_FAILURE);
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        exit(EXIT_FAILURE);
    }
}

int main() {
    setup_signal_handlers();

    struct gpiod_chip *chip;
    struct gpiod_line *lines[4];
    int line_offset[] = {RED_PIN, YELLOW_PIN, GREEN_PIN, YELLOW2_PIN};
    int line_flags[] = {GPIO_LINE_REQUEST_OUTPUT, GPIO_LINE_REQUEST_OUTPUT, GPIO_LINE_REQUEST_OUTPUT, GPIO_LINE_REQUEST_OUTPUT};
    int line_values[] = {0, 1, 1, 1}; // Active low: 0 to activate, 1 to deactivate

