                fprintf(stderr, "gpiod_line_set_value %d\n", line_offset[i]);
                break;
            }
        }
        sleep(2);

        // Green
        printf("Green\n");
        for (int i = 0; i < 4; i++) {
            if (gpiod_line_set_value(lines[i], (i == GREEN) ? 0 : 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value %d\n", line_offset[i]);
                break;
            }
        }
        sleep(10);

        // Yellow
        printf("Yellow\n");
        for (int i = 0; i < 4; i++) {
