                fprintf(stderr, "gpiod_line_set_value %d\n", line_offset[i]);
                break;
            }
        }
        sleep(3);
    }

    for (int i = 0; i < 4; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

