#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define GPIO_RELAY 17
#define DEBOUNCE_DELAY 100000 // 100 ms in microseconds
#define TOUCH_READ_INTERVAL 10000 // 10 ms in milliseconds

static int i2c_fd = -1;
static int gpio_fd = -1;
static FILE *log_file = NULL;

void log_error(const char *message) {
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file);
    }
}

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (gpio_fd != -1) {
        gpiod_line_release(gpio_fd);
        gpio_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        log_error("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int init_gpio() {
    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_fd) {
        log_error("Failed to open GPIO chip");
        return -1;
    }

    struct gpiod_line_request req = {
        .consumer_label = "relay_control",
        .flags = GPIOD_LINE_REQUEST_OUTPUT,
        .line_offset = GPIO_RELAY,
        .default_value = 0
    };

    gpio_fd = gpiod_line_request(gpio_fd, &req);
    if (!gpio_fd) {
        log_error("Failed to request GPIO line");
        gpiod_chip_close(gpio_fd);
        gpio_fd = -1;
        return -1;
    }
    return 0;
}

int read_touch_status() {
    uint8_t buffer[2];
    if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        log_error("Failed to read touch status");
        return -1;
    }
    return buffer[0] & (1 << 0); // Check if electrode 0 is touched
}

void toggle_relay() {
    int value = gpiod_line_get_value(gpio_fd);
    gpiod_line_set_value(gpio_fd, !value);
}

int main() {
    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        log_error("Failed to set signal handler");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0 || init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int last_touch_status = -1;
    int debounce_counter = 0;

    while (1) {
        int touch_status = read_touch_status();
        if (touch_status < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        if (touch_status != last_touch_status) {
            debounce_counter = 0;
            last_touch_status = touch_status;
        } else if (debounce_counter < DEBOUNCE_DELAY / TOUCH_READ_INTERVAL) {
            debounce_counter++;
        } else if (debounce_counter == DEBOUNCE_DELAY / TOUCH_READ_INTERVAL) {
            if (touch_status) {
                toggle_relay();
            }
            debounce_counter++;
        }

        usleep(TOUCH_READ_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

