                    log_flame_detection();
                    gpiod_line_set_value(buzzer_line, HIGH_LEVEL);
                    gpiod_line_set_value(led_line, HIGH_LEVEL);
                    flame_detected = 1;
                }
            }
        } else {
            consecutive_low_reads = 0;
            if (flame_detected) {
                gpiod_line_set_value(buzzer_line, LOW_LEVEL);
                gpiod_line_set_value(led_line, LOW_LEVEL);
                flame_detected = 0;
            }
        }

        usleep(DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

