#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define SOL1_PIN 17
#define SOL2_PIN 27
#define DISPENSE_INTERVAL_MS 1000
#define DISPENSE_PERIOD_MS 500

static volatile int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static FILE *log_file;

void handle_sigint(int sig) {
    keep_running = 0;
    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);
    if (log_file) {
        fclose(log_file);
    }
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    line1 = gpiod_chip_get_line(chip, SOL1_PIN);
    if (!line1) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", SOL1_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    line2 = gpiod_chip_get_line(chip, SOL2_PIN);
    if (!line2) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", SOL2_PIN);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line1, "solenoid1", 0) < 0) {
        fprintf(stderr, "Failed to request line for GPIO %d\n", SOL1_PIN);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line2, "solenoid2", 0) < 0) {
        fprintf(stderr, "Failed to request line for GPIO %d\n", SOL2_PIN);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int setup_logging() {
    log_file = fopen("dispense_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }
    return 0;
}

void log_event(const char *solenoid, int duration) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s - Solenoid %s activated for %d ms\n", time_str, solenoid, duration);
    fflush(log_file);
}

int main() {
    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (setup_logging() != 0) {
        return EXIT_FAILURE;
    }

    while (keep_running) {
        gpiod_line_set_value(line1, 1);
        log_event("1", DISPENSE_PERIOD_MS);
        usleep(DISPENSE_PERIOD_MS * 1000);

        gpiod_line_set_value(line1, 0);
        gpiod_line_set_value(line2, 1);
        log_event("2", DISPENSE_PERIOD_MS);
        usleep(DISPENSE_PERIOD_MS * 1000);

        gpiod_line_set_value(line2, 0);
        usleep((DISPENSE_INTERVAL_MS - 2 * DISPENSE_PERIOD_MS) * 1000);
    }

    if (log_file) {
        fclose(log_file);
    }
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

