This program sets up GPIO pins using the `libgpiod` library, handles signals for graceful shutdown, logs events to a file, and runs in a loop to control the solenoids as specified.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <string.h>
#include <gpiod.h>
#include <pigpio.h>

#define MOTOR_A_FWD 17
#define MOTOR_A_BWD 18
#define MOTOR_B_FWD 22
#define MOTOR_B_BWD 23
#define ENA 24
#define ENB 25
#define PWM_FREQUENCY 1000
#define LOG_INTERVAL 50 // milliseconds
#define OBSTACLE_DISTANCE_THRESHOLD 20.0
#define OBSTACLE_REVERSE_SPEED 127

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void log_data(FILE *log_file, float timestamp, float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f, %d, %d\n",
            2023, 10, 10, (int)timestamp / 3600, ((int)timestamp / 60) % 60, (int)timestamp % 60,
            tilt_error, distance, motor_a_speed, motor_b_speed);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    int motor_a_fwd = gpioServo(MOTOR_A_FWD);
    int motor_a_bwd = gpioServo(MOTOR_A_BWD);
    int motor_b_fwd = gpioServo(MOTOR_B_FWD);
    int motor_b_bwd = gpioServo(MOTOR_B_BWD);
    int ena = gpioServo(ENA);
    int enb = gpioServo(ENB);

    if (motor_a_fwd < 0 || motor_a_bwd < 0 || motor_b_fwd < 0 || motor_b_bwd < 0 || ena < 0 || enb < 0) {
        fprintf(stderr, "Failed to initialize GPIO pins\n");
        gpioTerminate();
        return 1;
    }

    gpioPWM(ena, PWM_FREQUENCY);
    gpioPWM(enb, PWM_FREQUENCY);
    gpioWrite(ena, 1);
    gpioWrite(enb, 1);

    FILE *log_file = fopen("balance_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    srand(time(NULL));
    time_t start_time = time(NULL);

    while (keep_running) {
        float timestamp = difftime(time(NULL), start_time);
        float tilt_error = ((float)rand() / RAND_MAX) * 20.0 - 10.0;
        float distance = ((float)rand() / RAND_MAX) * 398.0 + 2.0;

        int motor_a_speed = 0;
        int motor_b_speed = 0;

        if (distance < OBSTACLE_DISTANCE_THRESHOLD) {
            motor_a_speed = -OBSTACLE_REVERSE_SPEED;
            motor_b_speed = -OBSTACLE_REVERSE_SPEED;
        } else {
            // Simple PID control logic (for demonstration purposes)
            motor_a_speed = (int)(tilt_error * 10);
            motor_b_speed = (int)(tilt_error * 10);
        }

        motor_a_speed = motor_a_speed > 255 ? 255 : (motor_a_speed < -255 ? -255 : motor_a_speed);
        motor_b_speed = motor_b_speed > 255 ? 255 : (motor_b_speed < -255 ? -255 : motor_b_speed);

        if (motor_a_speed > 0) {
            gpioPWM(motor_a_fwd, motor_a_speed);
            gpioWrite(motor_a_bwd, 0);
        } else if (motor_a_speed < 0) {
            gpioPWM(motor_a_bwd, -motor_a_speed);
            gpioWrite(motor_a_fwd, 0);
        } else {
            gpioWrite(motor_a_fwd, 0);
            gpioWrite(motor_a_bwd, 0);
        }

        if (motor_b_speed > 0) {
            gpioPWM(motor_b_fwd, motor_b_speed);
            gpioWrite(motor_b_bwd, 0);
        } else if (motor_b_speed < 0) {
            gpioPWM(motor_b_bwd, -motor_b_speed);
            gpioWrite(motor_b_fwd, 0);
        } else {
            gpioWrite(motor_b_fwd, 0);
            gpioWrite(motor_b_bwd, 0);
        }

        log_data(log_file, timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
        fflush(log_file);

        usleep(LOG_INTERVAL * 1000);
    }

    gpioWrite(ena, 0);
    gpioWrite(enb, 0);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

