    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request sensor line as input with a pull-down resistor
    ret = gpiod_line_request_input(sensor_line, "touch_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    if (ret < 0) {
        fprintf(stderr, "Failed to request sensor line: %s\n", gpiod_strerror(-ret));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line\n");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request relay line as output
    ret = gpiod_line_request_output(relay_line, "relay", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request relay line: %s\n", gpiod_strerror(-ret));
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize relay to LOW
    gpiod_line_set_value(relay_line, 0);

    // Main loop
    while (keep_running) {
        struct gpiod_line_event event;
        ret = gpiod_line_event_wait(sensor_line, DEBOUNCE_DELAY_MS);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for sensor event: %s\n", gpiod_strerror(-ret));
            break;
        }

        if (gpiod_line_event_read(sensor_line, &event) < 0) {
            fprintf(stderr, "Error reading sensor event: %s\n", gpiod_strerror(-ret));
            break;
        }

        // Toggle relay on touch detected
        int current_value = gpiod_line_get_value(relay_line);
        if (current_value < 0) {
            fprintf(stderr, "Error reading relay value: %s\n", gpiod_strerror(-current_value));
            break;
        }

        gpiod_line_set_value(relay_line, !current_value);
    }

    // Cleanup
    gpiod_line_release(relay_line);
    gpiod_line_release(sensor_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

