#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>

#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif

#include <pigpio.h>

#define SAMPLE_RATE 8000
#define CHANNELS 1
#define FORMAT SND_PCM_FORMAT_S16_LE
#define PERIOD_SIZE 1024
#define LED_RED 17
#define LED_GREEN 18
#define LED_BLUE 27
#define PWM_FREQUENCY 1000

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void cleanup(int *alsa_handle, int *gpio_handle) {
    if (alsa_handle && *alsa_handle >= 0) {
#ifdef ALSA_AVAILABLE
        snd_pcm_close(*alsa_handle);
#endif
        *alsa_handle = -1;
    }
    if (gpio_handle && *gpio_handle >= 0) {
        gpioTerminate(*gpio_handle);
        *gpio_handle = -1;
    }
}

double compute_rms(const int16_t *buffer, size_t size) {
    double sum = 0.0;
    for (size_t i = 0; i < size; ++i) {
        sum += buffer[i] * buffer[i];
    }
    return sqrt(sum / size);
}

void map_rms_to_color(double rms, double sensitivity, int gpio_handle) {
    double intensity = rms * sensitivity;
    int red = (int)(255 * intensity);
    int green = (int)(255 * (1 - intensity));
    int blue = 0;

    red = red > 255 ? 255 : red;
    green = green > 255 ? 255 : green;
    blue = blue > 255 ? 255 : blue;

    gpioPWM(gpio_handle, LED_RED, PWM_FREQUENCY, red * 1000 / 255);
    gpioPWM(gpio_handle, LED_GREEN, PWM_FREQUENCY, green * 1000 / 255);
    gpioPWM(gpio_handle, LED_BLUE, PWM_FREQUENCY, blue * 1000 / 255);
}

void simulate_audio_input(int16_t *buffer, size_t size, double sensitivity) {
    double amplitude = 32767 * sensitivity;
    double frequency = 440.0; // A4 note
    double phase = 0.0;
    double phase_increment = 2.0 * M_PI * frequency / SAMPLE_RATE;

    for (size_t i = 0; i < size; ++i) {
        buffer[i] = (int16_t)(amplitude * sin(phase));
        phase += phase_increment;
    }
}

int main(int argc, char *argv[]) {
    int alsa_handle = -1;
    int gpio_handle = -1;
    double sensitivity = 1.0;

    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0) {
            fprintf(stderr, "Invalid sensitivity value. Using default 1.0.\n");
            sensitivity = 1.0;
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return EXIT_FAILURE;
    }
    gpio_handle = 1;

    int16_t buffer[PERIOD_SIZE];

    #ifdef ALSA_AVAILABLE
    snd_pcm_t *pcm_handle;
    snd_pcm_hw_params_t *hw_params;
    snd_pcm_uframes_t frames;

    if (snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0) < 0) {
        fprintf(stderr, "Failed to open PCM device.\n");
        cleanup(&alsa_handle, &gpio_handle);
        return EXIT_FAILURE;
    }
    alsa_handle = pcm_handle;

    if (snd_pcm_hw_params_malloc(&hw_params) < 0) {
        fprintf(stderr, "Failed to allocate hardware parameters.\n");
        cleanup(&alsa_handle, &gpio_handle);
        return EXIT_FAILURE;
    }

    if (snd_pcm_hw_params_any(pcm_handle, hw_params) < 0) {
        fprintf(stderr, "Failed to initialize hardware parameters.\n");
        snd_pcm_hw_params_free(hw_params);
        cleanup(&alsa_handle, &gpio_handle);
        return EXIT_FAILURE;
    }

    if (snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED) < 0) {
        fprintf(stderr, "Failed to set access type.\n");
        snd_pcm_hw_params_free(hw_params);
        cleanup(&alsa_handle, &gpio_handle);
        return EXIT_FAILURE;
    }

    if (snd_pcm_hw_params_set_format(pcm_handle, hw_params, FORMAT) < 0) {
        fprintf(stderr, "Failed to set sample format.\n");
        snd_pcm_hw_params_free(hw_params);
        cleanup(&alsa_handle, &gpio_handle);
        return EXIT_FAILURE;
    }

    if (snd_pcm_hw_params_set_channels(pcm_handle, hw_params, CHANNELS) < 0) {
        fprintf(stderr, "Failed to set channel count.\n");
        snd_pcm_hw_params_free(hw_params);
        cleanup(&alsa_handle, &gpio_handle);
        return EXIT_FAILURE;
    }

    if (snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &SAMPLE_RATE, NULL) < 0) {
        fprintf(stderr, "Failed to set sample rate.\n");
        snd_pcm_hw_params_free(hw_params);
        cleanup(&alsa_handle, &gpio_handle);
        return EXIT_FAILURE;
    }

    if (snd_pcm_hw_params_set_period_size_near(pcm_handle, hw_params, &frames, NULL) < 0) {
        fprintf(stderr, "Failed to set period size.\n");
        snd_pcm_hw_params_free(hw_params);
        cleanup(&alsa_handle, &gpio_handle);
        return EXIT_FAILURE;
    }

    if (frames != PERIOD_SIZE) {
        fprintf(stderr, "Period size mismatch.\n");
        snd_pcm_hw_params_free(hw_params);
        cleanup(&alsa_handle, &gpio_handle);
        return EXIT_FAILURE;
    }

    if (snd_pcm_hw_params(pcm_handle, hw_params) < 0) {
        fprintf(stderr, "Failed to set hardware parameters.\n");
        snd_pcm_hw_params_free(hw_params);
        cleanup(&alsa_handle, &gpio_handle);
        return EXIT_FAILURE;
    }

    snd_pcm_hw_params_free(hw_params);

    if (snd_pcm_prepare(pcm_handle) < 0) {
        fprintf(stderr, "Failed to prepare PCM device.\n");
        cleanup(&alsa_handle, &gpio_handle);
        return EXIT_FAILURE;
    }
    #endif

    while (keep_running) {
        #ifdef ALSA_AVAILABLE
        int err = snd_pcm_readi(pcm_handle, buffer, PERIOD_SIZE);
        if (err == -EPIPE) {
            fprintf(stderr, "Buffer overrun occurred. Preparing PCM device.\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err == -EAGAIN || err == -ESTRPIPE) {
            fprintf(stderr, "PCM device suspended. Resuming.\n");
            snd_pcm_resume(pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "Failed to read from PCM device: %s\n", snd_strerror(err));
            cleanup(&alsa_handle, &gpio_handle);
            return EXIT_FAILURE;
        } else if (err != (int)PERIOD_SIZE) {
            fprintf(stderr, "Short read, read %d frames.\n", err);
        }
        #else
        simulate_audio_input(buffer, PERIOD_SIZE, sensitivity);
        #endif

        double rms = compute_rms(buffer, PERIOD_SIZE);
        map_rms_to_color(rms, sensitivity, gpio_handle);

        printf("RMS: %f\n", rms);
        usleep(10000); // 10 ms
    }

    cleanup(&alsa_handle, &gpio_handle);
    return EXIT_SUCCESS;
}

