#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>
#include <tcs34725.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define INTEGRATION_TIME 154
#define SAMPLE_INTERVAL 500

static int i2c_fd = -1;
static FILE *csv_file = NULL;
static struct tcs34725_dev *tcs34725_dev = NULL;

void cleanup_and_exit(int signum) {
    if (tcs34725_dev) {
        tcs34725_close(tcs34725_dev);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file) {
        fclose(csv_file);
    }
    exit(0);
}

int setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);

