#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RELAY1 17
#define RELAY2 27
#define RELAY3 22
#define RELAY4 23

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 51840

#define PWM_PERIOD 1000
#define PWM_STEP 10

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void error_exit(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

void set_relay(gpiod_chip *chip, int line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        error_exit("Failed to set GPIO value");
    }
}

void toggle_relay(gpiod_chip *chip, int line, int duty_cycle) {
    gpiod_line_request_config req = {
        .consumer = "sunrise_sunset_simulator",
        .type = GPIOD_LINE_REQ_DIR_OUT,
        .flags = GPIOD_LINE_REQUEST_DIRECTIONS_MASK,
    };

    gpiod_line *line = gpiod_chip_get_line(chip, line);
    if (!line) {
        error_exit("Failed to get GPIO line");
    }

    if (gpiod_line_request(line, &req) < 0) {
        gpiod_line_release(line);
        error_exit("Failed to request GPIO line");
    }

    int on_time = (PWM_PERIOD * duty_cycle) / 100;
    int off_time = PWM_PERIOD - on_time;

    for (int i = 0; i < PWM_PERIOD; i++) {
        if (i < on_time) {
            set_relay(chip, line, 0);
        } else {
            set_relay(chip, line, 1);
        }
        usleep(1000); // 1 ms
    }

    gpiod_line_release(line);
}

void simulate_phase(gpiod_chip *chip, int start_line, int end_line, int duration, int step) {
    for (int duty_cycle = 0; duty_cycle <= 100; duty_cycle += step) {
        if (!keep_running) break;
        for (int line = start_line; line <= end_line; line++) {
            toggle_relay(chip, line, duty_cycle);
        }
        usleep((duration / 100) * 1000); // Convert to microseconds
    }
}

void simulate_sunrise(gpiod_chip *chip) {
    simulate_phase(chip, RELAY1, RELAY4, SUNRISE_DURATION, PWM_STEP);
}

void simulate_daytime(gpiod_chip *chip) {
    for (int line = RELAY1; line <= RELAY4; line++) {
        set_relay(chip, line, 0);
    }
    usleep(DAYTIME_DURATION * 1000);
}

void simulate_sunset(gpiod_chip *chip) {
    simulate_phase(chip, RELAY1, RELAY4, SUNSET_DURATION, -PWM_STEP);
}

void simulate_nighttime(gpiod_chip *chip) {
    for (int line = RELAY1; line <= RELAY4; line++) {
        set_relay(chip, line, 1);
    }
    usleep(NIGHTTIME_DURATION * 1000);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        error_exit("Failed to set signal handler");
    }

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        error_exit("Failed to open GPIO chip");
    }

    while (keep_running) {
        simulate_sunrise(chip);
        simulate_daytime(chip);
        simulate_sunset(chip);
        simulate_nighttime(chip);
    }

    for (int line = RELAY1; line <= RELAY4; line++) {
        set_relay(chip, line, 1);
    }

    gpiod_chip_close(chip);
    return 0;
}

