#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <sys/wait.h>

#define GPIO_PIN 17
#define DEBOUNCE_INTERVAL 200000000 // 200 ms in nanoseconds
#define VIDEO_DURATION 5000 // 5 seconds in milliseconds

static int log_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void handle_signal(int sig) {
    if (log_fd != -1) {
        close(log_fd);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

void log_motion_event() {
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", tm_info);

    char log_entry[50];
    snprintf(log_entry, sizeof(log_entry), "%s\n", timestamp);

    if (write(log_fd, log_entry, strlen(log_entry)) != strlen(log_entry)) {
        perror("Failed to write to log file");
    }
}

void capture_video() {
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", tm_info);

    char filename[50];
    snprintf(filename, sizeof(filename), "/home/pi/videos/%s.h264", timestamp);

    char command[200];
    snprintf(command, sizeof(command), "raspivid -t %d -o %s", VIDEO_DURATION, filename);

    int status = system(command);
    if (status != 0) {
        fprintf(stderr, "Failed to execute raspivid command\n");
    }
}

int main() {
    signal(SIGINT, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "IR Sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES)) {
        perror("Failed to request line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_fd = open("/home/pi/logs/motion_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct timespec last_trigger;
    clock_gettime(CLOCK_MONOTONIC, &last_trigger);

    while (1) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line, DEBOUNCE_INTERVAL, &event)) {
            if (errno == EAGAIN) {
                continue;
            }
            perror("Failed to wait for line event");
            break;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        if (event.event_type == GPIOD_LINE_EVENT_FALLING && 
            (now.tv_sec > last_trigger.tv_sec || 
             (now.tv_sec == last_trigger.tv_sec && now.tv_nsec > last_trigger.tv_nsec + DEBOUNCE_INTERVAL))) {

            last_trigger = now;
            log_motion_event();
            capture_video();
        }
    }

    handle_signal(0);
    return EXIT_SUCCESS;
}

