#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_YOUT_H 0x45
#define MPU6050_GYRO_ZOUT_H 0x47

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int i2c_write_byte_data(int fd, uint8_t reg, uint8_t data) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (write(fd, &data, 1) != 1) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

int initialize_mpu6050() {
    uint8_t data;

    if (i2c_write_byte_data(i2c_fd, MPU6050_PWR_MGMT_1, 0x00) != 0) {
        return -1;
    }

    if (i2c_write_byte_data(i2c_fd, MPU6050_GYRO_CONFIG, 0x00) != 0) {
        return -1;
    }

    if (i2c_read_bytes(i2c_fd, MPU6050_PWR_MGMT_1, &data, 1) != 0) {
        return -1;
    }

    return 0;
}

int open_i2c_device() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

void close_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (open_i2c_device() != 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return EXIT_FAILURE;
