static int log_fd = -1;
static struct gpiod_chip *chip;
static struct gpiod_line *lines[4];

void cleanup_and_exit(int signum) {
    if (log_fd != -1) {
        close(log_fd);
    }
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    int line_offsets[] = {RELAY_ZONE_1, RELAY_ZONE_2, RELAY_ZONE_3, RELAY_ZONE_4};
    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, line_offsets[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            cleanup_and_exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(lines[i], "relay", 0) < 0) {
            perror("Failed to request GPIO line as output");
            cleanup_and_exit(EXIT_FAILURE);
        }
    }

    if ((log_fd = open("irrigation_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        cleanup_and_exit(EXIT_FAILURE);
    }

    signal(SIGINT, cleanup_and_exit);

    srand(time(NULL));

    while (1) {
        int moisture_value = rand() % 100;
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        char log_entry[256];
        snprintf(log_entry, sizeof(log_entry), "%s - Moisture: %d\n", timestamp, moisture_value);

        for (int i = 0; i < 4; i++) {
            int state = (moisture_value < DRY_THRESHOLD) ? 0 : 1;
            if (gpiod_line_set_value(lines[i], state) < 0) {
                perror("Failed to set GPIO line value");
                cleanup_and_exit(EXIT_FAILURE);
            }
            snprintf(log_entry + strlen(log_entry), sizeof(log_entry) - strlen(log_entry),
                     " Relay %d: %s\n", i + 1, state ? "OFF" : "ON");
        }

        if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
            perror("Failed to write to log file");
            cleanup_and_exit(EXIT_FAILURE);
        }

        sleep(5);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

