#include <libgpiod.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define FREE_FALL_THRESHOLD 0.2
#define POLL_INTERVAL 100000000 // 100 ms in nanoseconds
#define CONFIRM_DELAY 500000000 // 0.5 seconds in nanoseconds
#define ALARM_DURATION 5000000000 // 5 seconds in nanoseconds
#define GPIO_PIN 27

static volatile sig_atomic_t keep_running = 1;
static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void handle_sigint(int sig) {
    keep_running = 0;
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

void log_freefall(double x, double y, double z) {
    FILE *log_file = fopen("freefall.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(log_file);
}

int read_acceleration(double *x, double *y, double *z) {
    char buf[6];
    if (read(i2c_fd, buf, 6) != 6) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw_x = (buf[0] << 8) | buf[1];
    int16_t raw_y = (buf[2] << 8) | buf[3];
    int16_t raw_z = (buf[4] << 8) | buf[5];

    *x = raw_x * 0.0039;
    *y = raw_y * 0.0039;
    *z = raw_z * 0.0039;

    return 0;
}

int main() {
    signal(SIGINT, handle_sigint);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "freefall_alarm", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure ADXL345
    uint8_t data = 0x08; // Measure mode
    if (write(i2c_fd, &data, 1) != 1) {
        perror("Failed to write to I2C bus");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    double x, y, z;
    struct timespec ts = {0, POLL_INTERVAL};
    struct timespec confirm_ts = {1, 0}; // 1 second for confirmation delay

    while (keep_running) {
        if (read_acceleration(&x, &y, &z) < 0) {
            continue;
        }

        if (fabs(x) < FREE_FALL_THRESHOLD && fabs(y) < FREE_FALL_THRESHOLD && fabs(z) < FREE_FALL_THRESHOLD) {
            nanosleep(&confirm_ts, NULL);

            if (read_acceleration(&x, &y, &z) < 0) {
                continue;
            }

            if (fabs(x) < FREE_FALL_THRESHOLD && fabs(y) < FREE_FALL_THRESHOLD && fabs(z) < FREE_FALL_THRESHOLD) {
                gpiod_line_set_value(line, 1);
                nanosleep(&ts, NULL);
                ts.tv_sec += 5; // 5 seconds for alarm duration
                nanosleep(&ts, NULL);
                gpiod_line_set_value(line, 0);

                log_freefall(x, y, z);
            }
        }

        nanosleep(&ts, NULL);
    }

    // Clean up
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

