#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define LIS3DH_ADDR 0x18
#define FREE_FALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5
#define BZ_GPIO 17

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, LIS3DH_ADDR) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    int retries = 3;

    while (retries--) {
        if (i2c_read(fd, 0x28, buf, 6) == 0) {
            *x = (int16_t)(buf[1] << 8 | buf[0]) * 0.061;
            *y = (int16_t)(buf[3] << 8 | buf[2]) * 0.061;
            *z = (int16_t)(buf[5] << 8 | buf[4]) * 0.061;
            return 0;
        }
        usleep(100000); // Retry after 100ms
    }

    return -1;
}

float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

int main(int argc, char *argv[]) {
    float free_fall_threshold = FREE_FALL_THRESHOLD;
    float impact_threshold = IMPACT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "f:i:")) != -1) {
        switch (opt) {
            case 'f':
                free_fall_threshold = atof(optarg);
                break;
            case 'i':
                impact_threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-f free_fall_threshold] [-i impact_threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    signal(SIGINT, handle_sigint);

    int bz_fd = gpiod_chip_open("/dev/gpiochip0");
    if (bz_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *bz_line = gpiod_chip_get_line(bz_fd, BZ_GPIO);
    if (!bz_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(bz_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(bz_line, "buzzer", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(bz_line);
        gpiod_chip_close(bz_fd);
        exit(EXIT_FAILURE);
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(bz_line);
        gpiod_chip_close(bz_fd);
        exit(EXIT_FAILURE);
    }

    float x, y, z;
    float magnitude;
    int free_fall_detected = 0;

    while (keep_running) {
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude < free_fall_threshold && !free_fall_detected) {
                free_fall_detected = 1;
            } else if (magnitude > impact_threshold && free_fall_detected) {
                gpiod_line_set_value(bz_line, 1);
                usleep(1000000); // Buzzer on for 1 second
                gpiod_line_set_value(bz_line, 0);
                free_fall_detected = 0;
            } else if (magnitude >= free_fall_threshold) {
                free_fall_detected = 0;
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data\n");
        }

        usleep(100000); // Read every 100ms
    }

    close(i2c_fd);
    gpiod_line_release(bz_line);
    gpiod_chip_close(bz_fd);

    return 0;
}

