    motor1_lines[1] = gpiod_chip_get_line(chip, MOTOR_1_IN2);
    motor1_lines[2] = gpiod_chip_get_line(chip, MOTOR_1_IN3);
    motor1_lines[3] = gpiod_chip_get_line(chip, MOTOR_1_IN4);

