            perror("Failed to request motor 1 line");
            cleanup_and_exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(motor2_lines[i], "motor2", 0) < 0) {
            perror("Failed to request motor 2 line");
            cleanup_and_exit(EXIT_FAILURE);
        }
    }
}

