        step_motor(motor2_lines, motor2_sequence[i], SQUARE_STEPS);
    }
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    setup_gpio();
    move_square();

    cleanup_and_exit(EXIT_SUCCESS);
}

