#define LIS3DH_I2C_ADDR_MIN 0x18
#define LIS3DH_I2C_ADDR_MAX 0x1F
#define LIS3DH_REG_CTRL1 0x20
#define LIS3DH_REG_CTRL4 0x23
#define LIS3DH_REG_CTRL5 0x24
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D

static int i2c_fd = -1;
static int threshold_g = 2.0;
static int i2c_address = LIS3DH_I2C_ADDR_DEFAULT;

void handle_sigint(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int write_register(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write register");
        return -1;
    }
    return 0;
}

int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (read(i2c_fd, buf, 6) != 6) {
        perror("Failed to read acceleration");
        *x = *y = *z = 0;
        return -1;
    }
    *x = (int16_t)(buf[1] | (buf[0] << 8));
    *y = (int16_t)(buf[3] | (buf[2] << 8));
    *z = (int16_t)(buf[5] | (buf[4] << 8));
    return 0;
}

void log_acceleration(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    syslog(LOG_INFO, "%s - X: %d, Y: %d, Z: %d", timestamp, x, y, z);
    system("sudo shutdown -h now");
}

