    if (write_register(LIS3DH_REG_CTRL1, 0x57) != 0) return -1; // ±2g, 100Hz, normal mode
    if (write_register(LIS3DH_REG_CTRL4, 0x08) != 0) return -1; // High-resolution mode
    if (write_register(LIS3DH_REG_CTRL5, 0x00) != 0) return -1; // Left-justified
    return 0;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_sigint);

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            i2c_address = (int)strtol(argv[++i], NULL, 16);
            if (i2c_address < LIS3DH_I2C_ADDR_MIN || i2c_address > LIS3DH_I2C_ADDR_MAX) {
                fprintf(stderr, "Invalid I2C address\n");
                return 0;
            }
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold_g = atof(argv[++i]);
            if (threshold_g <= 0) {
                fprintf(stderr, "Threshold must be greater than 0\n");
                return 0;
            }
        }
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 0;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 0;
    }

    if (configure_sensor() != 0) {
        perror("Failed to configure sensor");
        close(i2c_fd);
        return 0;
    }

    openlog("high_acceleration", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting acceleration monitoring");

    while (1) {
        int16_t x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            double x_g = x * 0.061; // ±2g range, 12-bit resolution
            double y_g = y * 0.061;
            double z_g = z * 0.061;
            if (fabs(x_g) > threshold_g || fabs(y_g) > threshold_g || fabs(z_g) > threshold_g) {
                log_acceleration(x, y, z);
            }
        }
        usleep(100000); // 100 ms
    }

    closelog();
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    return 0;
}

