#include <stdbool.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN 22
#define POLL_INTERVAL 10 // in milliseconds
#define BUFFER_SIZE 5

static gpiod_chip *chip;
static gpiod_line *left_sensor, *center_sensor, *right_sensor, *alert;
static int buffer[BUFFER_SIZE][3];
static int buffer_index = 0;
static int no_line_count = 0;
static volatile bool running = true;

void handle_signal(int sig) {
    running = false;
}

void log_reading(int left, int center, int right) {
    buffer[buffer_index][0] = left;
    buffer[buffer_index][1] = center;
    buffer[buffer_index][2] = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

void check_buffer() {
    int center_no_line_count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (buffer[i][1] == 1) {
            center_no_line_count++;
        }
    }
    if (center_no_line_count == BUFFER_SIZE) {
        no_line_count++;
    } else {
        no_line_count = 0;
    }
}

void drive_robot(int left, int center, int right) {
    if (center == 0) {
        // Move forward
        printf("Moving forward\n");
    } else if (left == 0) {
        // Turn left
        printf("Turning left\n");
    } else if (right == 0) {
        // Turn right
        printf("Turning right\n");
    } else {
        // Stop
        printf("Stopping\n");
    }
}

void set_alert(bool state) {
    gpiod_line_set_value(alert, state ? 1 : 0);
}

void cleanup() {
    if (left_sensor) gpiod_line_release(left_sensor);
    if (center_sensor) gpiod_line_release(center_sensor);
    if (right_sensor) gpiod_line_release(right_sensor);
    if (alert) gpiod_line_release(alert);
    if (chip) gpiod_chip_close(chip);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    left_sensor = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    if (!left_sensor || gpiod_line_request_input(left_sensor, "left_sensor", GPIOD_LINE_REQ_EV_NONE)) {
        fprintf(stderr, "Failed to configure left sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    center_sensor = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    if (!center_sensor || gpiod_line_request_input(center_sensor, "center_sensor", GPIOD_LINE_REQ_EV_NONE)) {
        fprintf(stderr, "Failed to configure center sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    right_sensor = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (!right_sensor || gpiod_line_request_input(right_sensor, "right_sensor", GPIOD_LINE_REQ_EV_NONE)) {
        fprintf(stderr, "Failed to configure right sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    alert = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!alert || gpiod_line_request_output(alert, "alert", 0)) {
        fprintf(stderr, "Failed to configure alert pin\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        int left = gpiod_line_get_value(left_sensor);
        int center = gpiod_line_get_value(center_sensor);
        int right = gpiod_line_get_value(right_sensor);

        if (left == -1 || center == -1 || right == -1) {
            fprintf(stderr, "Error reading sensor values\n");
            cleanup();
            return EXIT_FAILURE;
        }

        log_reading(left, center, right);
        check_buffer();

        drive_robot(left, center, right);

        if (no_line_count >= BUFFER_SIZE) {
            set_alert(true);
            usleep(2000000); // 2 seconds
            set_alert(false);
            no_line_count = 0;
        }

        usleep(POLL_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

