void log_event(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    syslog(LOG_INFO, "[%s] %s", timestamp, message);
    FILE *file = fopen("magnetic_events.txt", "a");
    if (file) {
        fprintf(file, "[%s] %s\n", timestamp, message);
        fclose(file);
    }
}

void handle_signal(int sig) {
    stop = 1;
    log_event("SIGINT received, shutting down...");
}

int init_gpio() {
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        log_event("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_RELAY);
    if (!gpio_line) {
        log_event("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "relay_control", 0)) {
        log_event("Failed to request GPIO line");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

int init_i2c() {
    char i2c_path[20];
    snprintf(i2c_path, sizeof(i2c_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_path, O_RDWR);
    if (i2c_fd < 0) {
        log_event("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        log_event("Failed to set I2C address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_magnetic_field(float *field) {
    uint8_t buffer[2];
    int attempts = 0;

    while (attempts < MAX_POLL_ATTEMPTS) {
        if (read(i2c_fd, buffer, sizeof(buffer)) == sizeof(buffer)) {
            *field = (buffer[0] << 8 | buffer[1]) * 0.1; // Example conversion
            return 0;
        }
        attempts++;
        usleep(1000); // 1 ms delay
    }

    log_event("Timeout waiting for magnetic field data");
    return -1;
}

void cleanup() {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    log_event("Resources released, exiting...");
}

int main() {
    openlog("magnetic_sensor", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);

    if (init_gpio() < 0 || init_i2c() < 0) {
        cleanup();
        exit(EXIT_FAILURE);
    }

    log_event("Initialization successful, starting main loop");

    while (!stop) {
        float field;
        if (read_magnetic_field(&field) == 0) {
            char event[100];
            snprintf(event, sizeof(event), "Magnetic field: %.2f mT", field);
            log_event(event);

            if (field > FIELD_THRESHOLD) {
                if (gpiod_line_set_value(gpio_line, 1) < 0) {
                    log_event("Failed to activate relay");
                } else {
                    log_event("Relay activated");
                }
            } else {
                if (gpiod_line_set_value(gpio_line, 0) < 0) {
                    log_event("Failed to deactivate relay");
                } else {
                    log_event("Relay deactivated");
                }
            }
        } else {
            if (gpiod_line_set_value(gpio_line, 0) < 0) {
                log_event("Failed to deactivate relay on error");
            }
        }

        nanosleep((const struct timespec[]){{0, SAMPLE_INTERVAL}}, NULL);
    }

    cleanup();
    closelog();
    return EXIT_SUCCESS;
}
