    }
    if (log_file) {
        fclose(log_file);
    }
    if (relay_fd >= 0) {
        gpiod_line_release(relay_fd);
    }
    exit(0);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int initialize_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "relay_control", 0)) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    relay_fd = gpiod_line_get_fd(line);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

int setup_server_socket() {
    struct sockaddr_in server_addr;

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Failed to create socket");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to bind socket");
        close(server_fd);
        return -1;
    }

    if (listen(server_fd, 1) < 0) {
        perror("Failed to listen on socket");
        close(server_fd);
        return -1;
    }

    return 0;
}

void process_command(const char *command) {
    if (strcasecmp(command, "ON") == 0) {
        if (gpiod_line_set_value(relay_fd, 1) < 0) {
            perror("Failed to set GPIO line to ON");
        } else {
            log_event("Relay turned ON");
        }
    } else if (strcasecmp(command, "OFF") == 0) {
        if (gpiod_line_set_value(relay_fd, 0) < 0) {
            perror("Failed to set GPIO line to OFF");
        } else {
            log_event("Relay turned OFF");
        }
    } else {
        log_event("Invalid command received");
    }
}

