        return EXIT_FAILURE;
    }

    uint8_t start_measurement[] = {0x00, 0x01}; // Example command, replace with actual
    if (read_sensor(i2c_fd_1, start_measurement, sizeof(start_measurement)) != 0 ||
        read_sensor(i2c_fd_2, start_measurement, sizeof(start_measurement)) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip;
    struct gpiod_line *line;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "relay_control", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        cleanup();
        return EXIT_FAILURE;
    }

    gpio_fd = gpiod_line_get_fd(line);
    if (gpio_fd < 0) {
        perror("Failed to get GPIO file descriptor");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        cleanup();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint8_t buffer[3];
        int flow1_valid = 0, flow2_valid = 0;
        double flow1 = 0.0, flow2 = 0.0;

        if (read_sensor(i2c_fd_1, buffer, sizeof(buffer)) == 0) {
            if (crc8(buffer, 2) == buffer[2]) {
                flow1 = (buffer[0] << 8 | buffer[1]) / 100.0;
                flow1_valid = 1;
            } else {
                fprintf(stderr, "CRC check failed for sensor 1\n");
            }
        } else {
            fprintf(stderr, "Failed to read from sensor 1\n");
        }

        if (read_sensor(i2c_fd_2, buffer, sizeof(buffer)) == 0) {
            if (crc8(buffer, 2) == buffer[2]) {
                flow2 = (buffer[0] << 8 | buffer[1]) / 100.0;
                flow2_valid = 1;
            } else {
                fprintf(stderr, "CRC check failed for sensor 2\n");
            }
        } else {
            fprintf(stderr, "Failed to read from sensor 2\n");
        }

        if (flow1_valid && flow2_valid) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld\t%.2f\t%.2f\n", ts.tv_sec, ts.tv_nsec, flow1, flow2);
            fflush(log_file);

            if (flow1 < MIN_FLOW || flow2 < MIN_FLOW) {
                gpiod_line_set_value(line, 1);
            } else {
                gpiod_line_set_value(line, 0);
            }
        }
        usleep(POLL_INTERVAL);
    }

    gpiod_line_set_value(line, 0);
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    cleanup();

    return EXIT_SUCCESS;
}
