#define IN2_GPIO 24
#define POLL_INTERVAL 200000 // 200 ms in microseconds
#define MOTOR_HOLD_TIME 5000000 // 5 seconds in microseconds
#define DRY_THRESHOLD 3

static volatile bool running = true;
static int dry_count = 0;

void handle_signal(int sig) {
    running = false;
}

void log_event(const char *message, int level) {
    syslog(level, "rain_window: %s", message);
}

void setup_gpio(gpiod_line_handle_t *line, int chip_offset, const char *name) {
    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_event("Failed to open GPIO chip", LOG_ERR);
        exit(EXIT_FAILURE);
    }

    *line = gpiod_chip_get_line(chip, chip_offset);
    if (!*line) {
        log_event("Failed to get GPIO line", LOG_ERR);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request(*line, name, GPIOD_LINE_REQUEST_DIRECTIONS_IN) < 0) {
        log_event("Failed to request GPIO line", LOG_ERR);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_chip_close(chip);
}

void setup_output(gpiod_line_handle_t *line, int chip_offset, const char *name) {
    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_event("Failed to open GPIO chip", LOG_ERR);
        exit(EXIT_FAILURE);
    }

    *line = gpiod_chip_get_line(chip, chip_offset);
    if (!*line) {
        log_event("Failed to get GPIO line", LOG_ERR);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request(*line, name, GPIOD_LINE_REQUEST_OUTPUT) < 0) {
        log_event("Failed to request GPIO line", LOG_ERR);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(*line, 0);
    gpiod_chip_close(chip);
}

void cleanup(gpiod_line_handle_t *lines, int num_lines) {
    for (int i = 0; i < num_lines; i++) {
        if (gpiod_line_release(lines[i]) < 0) {
            log_event("Failed to release GPIO line", LOG_WARNING);
        }
    }
}

int main() {
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    log_event("Program started", LOG_INFO);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpiod_line_handle_t sensor_line, ena_line, in1_line, in2_line;
    setup_gpio(&sensor_line, SENSOR_GPIO, "Rain Sensor");
    setup_output(&ena_line, ENA_GPIO, "Motor ENA");
    setup_output(&in1_line, IN1_GPIO, "Motor IN1");
    setup_output(&in2_line, IN2_GPIO, "Motor IN2");

    bool last_state = true;
    while (running) {
        int value = gpiod_line_get_value(sensor_line);
        if (value < 0) {
            log_event("Failed to read sensor value", LOG_ERR);
            break;
        }

        bool current_state = (value == 0);

        if (current_state && !last_state) {
            dry_count++;
            if (dry_count >= DRY_THRESHOLD) {
                dry_count = 0;
                if (gpiod_line_set_value(ena_line, 1) < 0 ||
                    gpiod_line_set_value(in1_line, 1) < 0 ||
                    gpiod_line_set_value(in2_line, 0) < 0) {
                    log_event("Failed to start motor", LOG_ERR);
                } else {
                    log_event("Motor started", LOG_INFO);
                    usleep(MOTOR_HOLD_TIME);
                    if (gpiod_line_set_value(ena_line, 0) < 0 ||
                        gpiod_line_set_value(in1_line, 0) < 0 ||
                        gpiod_line_set_value(in2_line, 0) < 0) {
                        log_event("Failed to stop motor", LOG_ERR);
                    } else {
                        log_event("Motor stopped", LOG_INFO);
                    }
                }
            }
        } else if (!current_state) {
            dry_count = 0;
        }

        last_state = current_state;
        usleep(POLL_INTERVAL);
    }

    if (gpiod_line_set_value(ena_line, 0) < 0 ||
        gpiod_line_set_value(in1_line, 0) < 0 ||
        gpiod_line_set_value(in2_line, 0) < 0) {
        log_event("Failed to stop motor on shutdown", LOG_ERR);
    }

    cleanup((gpiod_line_handle_t[]){sensor_line, ena_line, in1_line, in2_line}, 4);
    closelog();

    log_event("Program shutdown", LOG_INFO);
    return EXIT_SUCCESS;
}

