#include <gpiod.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define DEBOUNCE_DELAY_MS 50
#define PULSE_WIDTH_LOCK 2000
#define PULSE_WIDTH_UNLOCK 1000
#define PULSE_WIDTH_STOP 0

static volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

int setup_gpio(gpiod_chip *chip, int line, int flags) {
    gpiod_line *gpio_line = gpiod_chip_get_line(chip, line);
    if (!gpio_line) {
        fprintf(stderr, "Failed to get line %d\n", line);
        return -1;
    }
    if (gpiod_line_request_rising_edge(gpio_line, "button") < 0) {
        fprintf(stderr, "Failed to request line %d\n", line);
        gpiod_line_release(gpio_line);
        return -1;
    }
    return 0;
}

int setup_servo(gpiod_chip *chip, int line) {
    gpiod_line *gpio_line = gpiod_chip_get_line(chip, line);
    if (!gpio_line) {
        fprintf(stderr, "Failed to get servo line %d\n", line);
        return -1;
    }
    if (gpiod_line_request_output(gpio_line, "servo", 0) < 0) {
        fprintf(stderr, "Failed to request servo line %d\n", line);
        gpiod_line_release(gpio_line);
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        return EXIT_FAILURE;
    }

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    if (setup_gpio(chip, LOCK_BUTTON_PIN, GPIOD_LINE_REQ_DIR_IN) < 0 ||
        setup_gpio(chip, UNLOCK_BUTTON_PIN, GPIOD_LINE_REQ_DIR_IN) < 0 ||
        setup_servo(chip, SERVO_PIN) < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line *lock_button = gpiod_chip_get_line(chip, LOCK_BUTTON_PIN);
    gpiod_line *unlock_button = gpiod_chip_get_line(chip, UNLOCK_BUTTON_PIN);
    gpiod_line *servo = gpiod_chip_get_line(chip, SERVO_PIN);

    while (running) {
        if (gpiod_line_event_wait(lock_button, DEBOUNCE_DELAY_MS) > 0) {
            usleep(DEBOUNCE_DELAY_MS * 1000);
            if (gpiod_line_get_value(lock_button) == 0) {
                if (gpiod_line_set_value(servo, 1) < 0 || gpiod_line_set_value(servo, 0) < 0) {
                    fprintf(stderr, "Failed to set servo pulse width\n");
                    break;
                }
                printf("Locking door\n");
                usleep(PULSE_WIDTH_LOCK * 1000);
                gpiod_line_set_value(servo, 0);
            }
        }

        if (gpiod_line_event_wait(unlock_button, DEBOUNCE_DELAY_MS) > 0) {
            usleep(DEBOUNCE_DELAY_MS * 1000);
            if (gpiod_line_get_value(unlock_button) == 0) {
                if (gpiod_line_set_value(servo, 1) < 0 || gpiod_line_set_value(servo, 0) < 0) {
                    fprintf(stderr, "Failed to set servo pulse width\n");
                    break;
                }
                printf("Unlocking door\n");
                usleep(PULSE_WIDTH_UNLOCK * 1000);
                gpiod_line_set_value(servo, 0);
            }
        }

        usleep(10000); // Sleep to reduce CPU usage
    }

    // Stop the servo on exit
    if (gpiod_line_set_value(servo, 1) < 0 || gpiod_line_set_value(servo, 0) < 0) {
        fprintf(stderr, "Failed to stop servo\n");
    } else {
        printf("Stopping servo\n");
    }

    gpiod_line_release(lock_button);
    gpiod_line_release(unlock_button);
    gpiod_line_release(servo);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

