#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <gpiod.h>

#define PIR_GPIO 4
#define RELAY_GPIO 17
#define POLL_INTERVAL_MS 100
#define LIGHT_DURATION_SEC 60

static volatile int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *pir_line;
static struct gpiod_line *relay_line;
static FILE *log_file;

void handle_signal(int sig) {
    keep_running = 0;
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

void log_event(const char *event, int duration) {
    if (!log_file) return;

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    if (strcmp(event, "activation") == 0) {
        if (fprintf(log_file, "%s: %s\n", timestamp, event) < 0) {
            perror("fprintf");
            handle_signal(SIGTERM);
        }
    } else if (strcmp(event, "deactivation") == 0) {
        if (fprintf(log_file, "%s: %s, duration: %d seconds\n", timestamp, event, duration) < 0) {
            perror("fprintf");
            handle_signal(SIGTERM);
        }
    }

    fflush(log_file);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(pir_line, "PIR Sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

