#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define GPIO_RELAY 17
#define DEBOUNCE_TIME_MS 200
#define ELECTRODE_COUNT 12

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t *data, size_t length) {
    uint8_t buffer[2 + length];
    buffer[0] = reg;
    memcpy(&buffer[1], data, length);
    if (write(fd, buffer, length + 1) != length + 1) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, data, length) != length) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

int mpr121_init(int fd) {
    uint8_t data[2];

    // Soft reset
    data[0] = 0x00;
    data[1] = 0x63;
    if (i2c_write(fd, 0x80, data, 2) != 0) return -1;

    usleep(10000); // Wait for reset

    // Set MHD, NHD, NCL, FDL
    data[0] = 0x2B;
    data[1] = 0x1E;
    if (i2c_write(fd, 0x00, data, 2) != 0) return -1;

    data[0] = 0x2C;
    data[1] = 0x1E;
    if (i2c_write(fd, 0x00, data, 2) != 0) return -1;

    data[0] = 0x2D;
    data[1] = 0x0A;
    if (i2c_write(fd, 0x00, data, 2) != 0) return -1;

    data[0] = 0x2E;
    data[1] = 0x0A;
    if (i2c_write(fd, 0x00, data, 2) != 0) return -1;

    // Set debounce
    data[0] = 0x24;
    data[1] = 0x0F;
    if (i2c_write(fd, 0x00, data, 2) != 0) return -1;

    // Set FFI, SFI, CDT
    data[0] = 0x01;
    data[1] = 0x0F;
    if (i2c_write(fd, 0x00, data, 2) != 0) return -1;

    data[0] = 0x02;
    data[1] = 0x00;
    if (i2c_write(fd, 0x00, data, 2) != 0) return -1;

    data[0] = 0x05;
    data[1] = 0x80;
    if (i2c_write(fd, 0x00, data, 2) != 0) return -1;

    // Enable auto-config
    data[0] = 0x0A;
    data[1] = 0x0F;
    if (i2c_write(fd, 0x00, data, 2) != 0) return -1;

    // Enable 12 electrodes
    data[0] = 0x0D;
    data[1] = 0x0F;
    if (i2c_write(fd, 0x00, data, 2) != 0) return -1;

    return 0;
}

int main() {
    int i2c_fd, gpio_fd;
    uint8_t touch_status[2];
    struct timespec last_touch_time;
    int relay_state = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    int line = gpiod_chip_get_line(gpio_fd, GPIO_RELAY);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "relay", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_fd);
        return EXIT_FAILURE;
    }

    gpiod_line_set_value(line, relay_state);
    gpiod_line_release(line);
    gpiod_chip_close(gpio_fd);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize MPR121\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (i2c_read(i2c_fd, 0x00, touch_status, 2) != 0) {
            fprintf(stderr, "Failed to read touch status\n");
            break;
        }

        if (touch_status[0] & (1 << 0)) {
            clock_gettime(CLOCK_MONOTONIC, &last_touch_time);
            usleep(DEBOUNCE_TIME_MS * 1000);
            if (i2c_read(i2c_fd, 0x00, touch_status, 2) != 0) {
                fprintf(stderr, "Failed to read touch status\n");
                break;
            }

            if (!(touch_status[0] & (1 << 0))) {
                struct timespec now;
                clock_gettime(CLOCK_MONOTONIC, &now);
                if (now.tv_sec > last_touch_time.tv_sec ||
                    (now.tv_sec == last_touch_time.tv_sec && now.tv_nsec > last_touch_time.tv_nsec + 100000000)) {
                    relay_state = !relay_state;
                    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
                    if (gpio_fd < 0) {
                        perror("Failed to open GPIO chip");
                        close(i2c_fd);
                        return EXIT_FAILURE;
                    }

                    line = gpiod_chip_get_line(gpio_fd, GPIO_RELAY);
                    if (!line) {
                        perror("Failed to get GPIO line");
                        gpiod_chip_close(gpio_fd);
                        close(i2c_fd);
                        return EXIT_FAILURE;
                    }

                    if (gpiod_line_set_value(line, relay_state) < 0) {
                        perror("Failed to set GPIO value");
                    }

                    gpiod_line_release(line);
                    gpiod_chip_close(gpio_fd);
                }
            }
        }
    }

    // Ensure relay is off on shutdown
    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_fd >= 0) {
        line = gpiod_chip_get_line(gpio_fd, GPIO_RELAY);
        if (line) {
            if (gpiod_line_request_output(line, "relay", 0) >= 0) {
                gpiod_line_set_value(line, 0);
            }
            gpiod_line_release(line);
        }
        gpiod_chip_close(gpio_fd);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

