#define SERVO_PIN 17
#define PIR_PIN 4
#define TCP_PORT 5000
#define LOG_FILE "security.log"
#define PWM_FREQUENCY 50
#define PWM_RANGE 20000

volatile sig_atomic_t keep_running = 1;

void log_event(const char *format, ...) {
    va_list args;
    char buffer[256];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S", tm_info);

    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    syslog(LOG_USER, "%s %s", time_str, buffer);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s %s\n", time_str, buffer);
        fclose(log_file);
    }
}

void handle_signal(int sig) {
    keep_running = 0;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        log_event("Failed to initialize GPIO library");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        log_event("Failed to set PIR pin mode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        log_event("Failed to set servo pin mode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    gpioTerminate();
    close(server_fd);
    fclose(log_file);
    closelog();
}

void handle_client(int client_fd) {
    char buffer[256];
    int bytes_read = read(client_fd, buffer, sizeof(buffer) - 1);
    if (bytes_read < 0) {
        log_event("Failed to read from client: %s", strerror(errno));
        return;
    }
    buffer[bytes_read] = '\0';

    log_event("Received command: %s", buffer);

    if (strncmp(buffer, "set_servo", 9) == 0) {
        int angle;
        if (sscanf(buffer + 10, "%d", &angle) == 1 && angle >= 0 && angle <= 180) {
            int pulse_width = 1000 + (angle * 10);
            gpioPWM(SERVO_PIN, PWM_FREQUENCY, pulse_width);
            log_event("Set servo to angle: %d", angle);
        } else {
            log_event("Invalid angle: %s", buffer + 10);
        }
    } else if (strncmp(buffer, "PIR", 3) == 0) {
        int pir_state = gpioRead(PIR_PIN);
        char response[16];
        snprintf(response, sizeof(response), "PIR:%d", pir_state);
        write(client_fd, response, strlen(response));
        log_event("PIR state: %d", pir_state);
    } else {
        log_event("Unknown command: %s", buffer);
    }
}

int main() {
    openlog("servo_control", LOG_PID | LOG_CONS, LOG_USER);
    log_event("Program started");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_event("Failed to create socket: %s", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(TCP_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_event("Failed to bind socket: %s", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, 3) < 0) {
        log_event("Failed to listen on socket: %s", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }

    log_event("Listening on port %d", TCP_PORT);

    while (keep_running) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (errno == EINTR) {
                continue;
            }
            log_event("Failed to accept client: %s", strerror(errno));
            continue;
        }

        handle_client(client_fd);
        close(client_fd);
    }

    cleanup();
    log_event("Program terminated");
    return 0;
