#define WAIT_INTERVAL 0.12

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_gpio() {
    int fd = gpiod_chip_open("/dev/gpiochip0");
    if (fd < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    struct gpiod_line_request req = {
        .consumer_label = "grow-light-relay",
        .flags = GPIOD_LINE_REQUEST_OUTPUT,
        .line_offset = RELAY_GPIO,
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_value = 0
    };

    int line = gpiod_chip_get_line(fd, RELAY_GPIO);
    if (line < 0) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(fd);
        return -1;
    }

    int ret = gpiod_line_request(line, &req);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(fd);
        return -1;
    }

    return fd;
}

void cleanup(int gpio_fd, int log_fd) {
    if (gpio_fd >= 0) {
        gpiod_chip_close(gpio_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
}

int read_lux(int i2c_fd) {
    unsigned char cmd = 0x20; // Continuously H-Resolution Mode
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Failed to write to BH1750");
        return -1;
    }

    usleep(120000); // Wait for the measurement

    unsigned char data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from BH1750");
        return -1;
    }

    int lux = (data[0] << 8) | data[1];
    return lux / 1.2; // Convert to lux
}

