    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int gpio_fd = setup_gpio();
    if (gpio_fd < 0) {
        return EXIT_FAILURE;
    }

    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        cleanup(gpio_fd, -1);
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        cleanup(gpio_fd, log_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        cleanup(gpio_fd, log_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int lux = read_lux(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Error reading lux, retrying...\n");
            sleep(READ_INTERVAL);
            continue;
        }

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        dprintf(log_fd, "%s - Lux: %d\n", timestamp, lux);

        if (lux < LUX_THRESHOLD) {
            gpiod_line_set_value(gpiod_chip_get_line(gpio_fd, RELAY_GPIO), 1);
        } else {
            gpiod_line_set_value(gpiod_chip_get_line(gpio_fd, RELAY_GPIO), 0);
        }

        sleep(READ_INTERVAL);
    }

    cleanup(gpio_fd, log_fd);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

