#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>
#include <getopt.h>
#include <errno.h>

#define DOUT_PIN 23
#define SCK_PIN 24
#define SOLENOID_PIN 25
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_DURATION 200
#define DEFAULT_SCALE 1.0
#define MAX_RETRIES 3
#define TIMEOUT 1000000 // 1 second in nanoseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int read_hx711(gpiod_chip *chip, int *dout_line, int *sck_line, int retries) {
    uint64_t dout_value;
    uint32_t sck_value;
    uint32_t count = 0;
    uint32_t data = 0;

    for (int attempt = 0; attempt < retries; attempt++) {
        if (gpiod_line_get_value(*dout_line, &dout_value) < 0) {
            syslog(LOG_ERR, "Failed to read DOUT value");
            return -1;
        }

        if (dout_value == 1) {
            usleep(1000); // Wait for DOUT to go LOW
            if (gpiod_line_get_value(*dout_line, &dout_value) < 0) {
                syslog(LOG_ERR, "Failed to read DOUT value");
                return -1;
            }
        }

        if (dout_value == 0) {
            for (int i = 0; i < 24; i++) {
                if (gpiod_line_set_value(*sck_line, 1) < 0) {
                    syslog(LOG_ERR, "Failed to set SCK high");
                    return -1;
                }
                usleep(1); // Short delay

                if (gpiod_line_get_value(*dout_line, &dout_value) < 0) {
                    syslog(LOG_ERR, "Failed to read DOUT value");
                    return -1;
                }

                if (dout_value == 1) {
                    data |= (1ULL << (23 - i));
                }

                if (gpiod_line_set_value(*sck_line, 0) < 0) {
                    syslog(LOG_ERR, "Failed to set SCK low");
                    return -1;
                }
                usleep(1); // Short delay
            }

            // Read the 25th bit (gain bit)
            if (gpiod_line_set_value(*sck_line, 1) < 0) {
                syslog(LOG_ERR, "Failed to set SCK high");
                return -1;
            }
            usleep(1); // Short delay

            if (gpiod_line_get_value(*dout_line, &dout_value) < 0) {
                syslog(LOG_ERR, "Failed to read DOUT value");
                return -1;
            }

            if (dout_value == 1) {
                data |= (1ULL << 24);
            }

            if (gpiod_line_set_value(*sck_line, 0) < 0) {
                syslog(LOG_ERR, "Failed to set SCK low");
                return -1;
            }
            usleep(1); // Short delay

            return (int)data;
        }

        usleep(100000); // Wait before retrying
    }

    syslog(LOG_ERR, "DOUT did not go LOW within timeout");
    return -1;
}

void tare(gpiod_chip *chip, int *dout_line, int *sck_line) {
    int sum = 0;
    for (int i = 0; i < 10; i++) {
        int value = read_hx711(chip, dout_line, sck_line, MAX_RETRIES);
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read HX711 during tare");
            exit(EXIT_FAILURE);
        }
        sum += value;
    }
    int tare_value = sum / 10;
    syslog(LOG_INFO, "Tare value: %d", tare_value);
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    double scale = DEFAULT_SCALE;
    int duration = DEFAULT_DURATION;
    int opt;

    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    openlog("hx711_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting HX711 weight monitor");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        closelog();
        exit(EXIT_FAILURE);
    }

    int *dout_line = gpiod_chip_get_line(chip, DOUT_PIN);
    int *sck_line = gpiod_chip_get_line(chip, SCK_PIN);
    int *solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);

    if (!dout_line || !sck_line || !solenoid_line) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        gpiod_chip_close(chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(dout_line, "dout", GPIOD_LINE_REQ_DIR_NONE) < 0) {
        syslog(LOG_ERR, "Failed to request DOUT line");
        gpiod_chip_close(chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(sck_line, "sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK line");
        gpiod_chip_close(chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(solenoid_line, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid line");
        gpiod_chip_close(chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    tare(chip, dout_line, sck_line);

    while (keep_running) {
        int sum = 0;
        for (int i = 0; i < 5; i++) {
            int value = read_hx711(chip, dout_line, sck_line, MAX_RETRIES);
            if (value < 0) {
                syslog(LOG_ERR, "Failed to read HX711");
                continue;
            }
            sum += value;
        }
        int average = sum / 5;
        double weight = (average * scale) / 1000.0; // Convert to grams
        syslog(LOG_INFO, "Measured weight: %.2f grams", weight);

        if (weight > threshold) {
            if (gpiod_line_set_value(solenoid_line, 1) < 0) {
                syslog(LOG_ERR, "Failed to activate solenoid");
            } else {
                usleep(duration * 1000);
                if (gpiod_line_set_value(solenoid_line, 0) < 0) {
                    syslog(LOG_ERR, "Failed to deactivate solenoid");
                }
            }
        }

        usleep(500000); // Poll every 500 ms
    }

    if (gpiod_line_set_value(solenoid_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to deactivate solenoid on exit");
    }

    gpiod_line_release(dout_line);
    gpiod_line_release(sck_line);
    gpiod_line_release(solenoid_line);
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

