    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    openlog("hx711_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting HX711 weight monitor");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        closelog();
        exit(EXIT_FAILURE);
    }

    int *dout_line = gpiod_chip_get_line(chip, DOUT_PIN);
    int *sck_line = gpiod_chip_get_line(chip, SCK_PIN);
    int *solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);

    if (!dout_line || !sck_line || !solenoid_line) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        gpiod_chip_close(chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(dout_line, "dout", GPIOD_LINE_REQ_DIR_NONE) < 0) {
        syslog(LOG_ERR, "Failed to request DOUT line");
        gpiod_chip_close(chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(sck_line, "sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK line");
        gpiod_chip_close(chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(solenoid_line, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid line");
        gpiod_chip_close(chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    tare(chip, dout_line, sck_line);

    while (keep_running) {
        int sum = 0;
        for (int i = 0; i < 5; i++) {
            int value = read_hx711(chip, dout_line, sck_line, MAX_RETRIES);
            if (value < 0) {
                syslog(LOG_ERR, "Failed to read HX711");
                continue;
            }
            sum += value;
        }
        int average = sum / 5;
        double weight = (average * scale) / 1000.0; // Convert to grams
        syslog(LOG_INFO, "Measured weight: %.2f grams", weight);

        if (weight > threshold) {
            if (gpiod_line_set_value(solenoid_line, 1) < 0) {
                syslog(LOG_ERR, "Failed to activate solenoid");
            } else {
                usleep(duration * 1000);
                if (gpiod_line_set_value(solenoid_line, 0) < 0) {
                    syslog(LOG_ERR, "Failed to deactivate solenoid");
                }
            }
        }

        usleep(500000); // Poll every 500 ms
    }

    if (gpiod_line_set_value(solenoid_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to deactivate solenoid on exit");
    }

    gpiod_line_release(dout_line);
    gpiod_line_release(sck_line);
    gpiod_line_release(solenoid_line);
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}
