#define MQTT_TOPIC "home/lights/control"
#define KEEP_ALIVE 60
#define RECONNECT_DELAY 5

static volatile int running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct mosquitto *mosq;

void handle_signal(int sig) {
    running = 0;
}

void log_message(int priority, const char *message) {
    openlog("mqtt_relay", LOG_PID, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

void gpio_init() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        log_message(LOG_ERR, "Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "relay_controller", 0) < 0) {
        log_message(LOG_ERR, "Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(line, 0); // Set relay OFF at startup
}

void mqtt_on_connect(struct mosquitto *mosq, void *obj, int rc) {
    if (rc == 0) {
        log_message(LOG_INFO, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_message(LOG_ERR, "Failed to connect to MQTT broker");
    }
}

void mqtt_on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *message) {
    if (message->payloadlen > 0 && message->payloadlen < 4) {
        if (strcmp((char *)message->payload, "ON") == 0) {
            gpiod_line_set_value(line, 1);
            log_message(LOG_INFO, "Relay set to ON");
        } else if (strcmp((char *)message->payload, "OFF") == 0) {
            gpiod_line_set_value(line, 0);
            log_message(LOG_INFO, "Relay set to OFF");
        } else {
            log_message(LOG_ERR, "Invalid payload received");
        }
    } else {
        log_message(LOG_ERR, "Empty or invalid payload received");
    }
}

void mqtt_on_disconnect(struct mosquitto *mosq, void *obj, int rc) {
    log_message(LOG_INFO, "Disconnected from MQTT broker");
}

void mqtt_on_subscribe(struct mosquitto *mosq, void *obj, int mid, int qos_count, const int *granted_qos) {
    log_message(LOG_INFO, "Subscribed to MQTT topic");
}

void mqtt_on_log(struct mosquitto *mosq, void *obj, int level, const char *str) {
    log_message(LOG_INFO, str);
}

void mqtt_loop() {
    while (running) {
        int rc = mosquitto_loop(mosq, -1, 1);
        if (rc) {
            log_message(LOG_ERR, "MQTT loop error");
            sleep(RECONNECT_DELAY);
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpio_init();

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, 1, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create MQTT client");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    mosquitto_connect_callback_set(mosq, mqtt_on_connect);
    mosquitto_message_callback_set(mosq, mqtt_on_message);
    mosquitto_disconnect_callback_set(mosq, mqtt_on_disconnect);
    mosquitto_subscribe_callback_set(mosq, mqtt_on_subscribe);
    mosquitto_log_callback_set(mosq, mqtt_on_log);

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, KEEP_ALIVE)) {
        log_message(LOG_ERR, "Failed to initiate MQTT connection");
        mosquitto_destroy(mosq);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        mosquitto_lib_cleanup();
        exit(EXIT_FAILURE);
    }

    mqtt_loop();

    gpiod_line_set_value(line, 0); // Ensure relay is OFF on exit
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    return 0;
}

