#define PERIOD_NS 20000 // 20 ms period for 50 Hz
#define MIN_PULSE_WIDTH_NS 500000 // 500 µs
#define MAX_PULSE_WIDTH_NS 2500000 // 2500 µs

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[5];
    int line_ids[] = {7, 8, 9, 10, 11};
    int pulse_widths_ns[] = {1000000, 1500000, 2000000, 500000, 2500000}; // Target pulse widths in ns
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    for (int i = 0; i < 5; i++) {
        lines[i] = gpiod_chip_get_line(chip, line_ids[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", line_ids[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_output(lines[i], "servo_pwm", GPIO_LINE_REQUEST_DIRECTIONS_OUTPUT);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d as output\n", line_ids[i]);
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Set PWM parameters and start PWM
    for (int i = 0; i < 5; i++) {
        if (pulse_widths_ns[i] < MIN_PULSE_WIDTH_NS) {
            pulse_widths_ns[i] = MIN_PULSE_WIDTH_NS;
        } else if (pulse_widths_ns[i] > MAX_PULSE_WIDTH_NS) {
            pulse_widths_ns[i] = MAX_PULSE_WIDTH_NS;
        }

        ret = gpiod_line_set_request_state(lines[i], GPIOD_LINE_REQUEST_STATE_ACTIVE);
        if (ret < 0) {
            fprintf(stderr, "Failed to activate line %d\n", line_ids[i]);
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_set_value(lines[i], 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line %d high\n", line_ids[i]);
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        usleep(pulse_widths_ns[i] / 1000); // Convert ns to us

        ret = gpiod_line_set_value(lines[i], 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line %d low\n", line_ids[i]);
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        usleep((PERIOD_NS - pulse_widths_ns[i]) / 1000); // Convert ns to us
    }

    // Hold the pulse for 3 seconds
    sleep(3);

    // Clean up
    for (int i = 0; i < 5; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

