#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>
#include <stdatomic.h>
#include <string.h>

#define PWM_FREQ 10000
#define CONTROL_PERIOD_MS 100
#define TICKS_PER_REV 64
#define TARGET_RPM 50
#define MAX_PWM 255
#define STALL_THRESHOLD_MS 2000

static atomic_int32_t encoder_ticks_a = 0;
static atomic_int32_t encoder_ticks_b = 0;
static volatile sig_atomic_t stop_requested = 0;

static struct gpiod_chip *chip;
static struct gpiod_line *motor_a_pwm, *motor_a_dir, *motor_b_pwm, *motor_b_dir;
static struct gpiod_line *encoder_a_a, *encoder_a_b, *encoder_b_a, *encoder_b_b;
static struct gpiod_line_event_iterator *iter;
static struct timespec last_tick_time_a, last_tick_time_b;
static int last_tick_count_a = 0, last_tick_count_b = 0;

static void handle_sigint(int sig) {
    stop_requested = 1;
}

static void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    motor_a_pwm = gpiod_chip_get_line(chip, 17);
    motor_a_dir = gpiod_chip_get_line(chip, 18);
    motor_b_pwm = gpiod_chip_get_line(chip, 22);
    motor_b_dir = gpiod_chip_get_line(chip, 23);

    encoder_a_a = gpiod_chip_get_line(chip, 4);
    encoder_a_b = gpiod_chip_get_line(chip, 5);
    encoder_b_a = gpiod_chip_get_line(chip, 6);
    encoder_b_b = gpiod_chip_get_line(chip, 12);

    if (!motor_a_pwm || !motor_a_dir || !motor_b_pwm || !motor_b_dir ||
        !encoder_a_a || !encoder_a_b || !encoder_b_a || !encoder_b_b) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(motor_a_pwm, "motor_a_pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    gpiod_line_request_output(motor_a_dir, "motor_a_dir", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    gpiod_line_request_output(motor_b_pwm, "motor_b_pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    gpiod_line_request_output(motor_b_dir, "motor_b_dir", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);

    gpiod_line_request_input(encoder_a_a, "encoder_a_a", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    gpiod_line_request_input(encoder_a_b, "encoder_a_b", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    gpiod_line_request_input(encoder_b_a, "encoder_b_a", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    gpiod_line_request_input(encoder_b_b, "encoder_b_b", GPIOD_LINE_REQ_EV_BOTH_EDGES);

    if (gpiod_line_event_iterator_init(&iter, encoder_a_a) < 0 ||
        gpiod_line_event_iterator_init(&iter, encoder_a_b) < 0 ||
        gpiod_line_event_iterator_init(&iter, encoder_b_a) < 0 ||
        gpiod_line_event_iterator_init(&iter, encoder_b_b) < 0) {
        fprintf(stderr, "Failed to initialize event iterator\n");
        exit(EXIT_FAILURE);
    }
}

static void cleanup_gpio() {
    gpiod_line_release(motor_a_pwm);
    gpiod_line_release(motor_a_dir);
    gpiod_line_release(motor_b_pwm);
    gpiod_line_release(motor_b_dir);
    gpiod_line_release(encoder_a_a);
    gpiod_line_release(encoder_a_b);
    gpiod_line_release(encoder_b_a);
    gpiod_line_release(encoder_b_b);
    gpiod_chip_close(chip);
}

static void update_encoder_ticks(struct gpiod_line *line) {
    struct gpiod_line_event event;
    while (gpiod_line_event_read(line, &event) == 0) {
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            if (line == encoder_a_a || line == encoder_a_b) {
