#include <libgpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define BH1750_I2C_ADDR 0x23
#define BH1750_MODE_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_MODE_POWER_DOWN 0x00
#define GPIO_RELAY_PIN 17
#define LOG_FILE "chicken_coop_log.txt"
#define POLL_INTERVAL 5
#define READ_DELAY 180
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200

static int relay_fd = -1;
static int i2c_fd = -1;
static int log_fd = -1;
static int relay_state = 0;

void log_message(const char *message) {
    if (log_fd < 0) {
        log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_fd < 0) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    dprintf(log_fd, "%s: %s\n", timestamp, message);
    fsync(log_fd);
}

void handle_signal(int sig) {
    if (relay_fd >= 0) {
        gpiod_line_set_value(relay_fd, 0);
        relay_state = 0;
        log_message("Relay = OFF");
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fd >= 0) {
        close(log_fd);
        log_fd = -1;
    }
    if (relay_fd >= 0) {
        gpiod_chip_close(relay_fd);
        relay_fd = -1;
    }
    exit(EXIT_SUCCESS);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_RELAY_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "relay_control", 1)) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    relay_fd = gpiod_chip_open("/dev/gpiochip0");
    if (!relay_fd) {
        perror("Failed to open GPIO chip for relay");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int setup_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_light_level() {
    unsigned char buffer[2];
    int ret;

    buffer[0] = BH1750_MODE_CONTINUOUS_HIGH_RES_MODE;
    ret = write(i2c_fd, buffer, 1);
    if (ret != 1) {
        perror("Failed to write mode command");
        return -1;
    }

    usleep(READ_DELAY * 1000);

    ret = read(i2c_fd, buffer, 2);
    if (ret != 2) {
        perror("Failed to read light level");
        return -1;
    }

    int lux = (buffer[0] << 8) | buffer[1];
    return lux / 1.2;
}

void control_relay(int lux) {
    static int last_state = -1;

    if (lux < LUX_THRESHOLD_DUSK && last_state != 1) {
        gpiod_line_set_value(relay_fd, 1);
        relay_state = 1;
        log_message("Relay = ON");
        last_state = 1;
    } else if (lux > LUX_THRESHOLD_DAWN && last_state != 0) {
        gpiod_line_set_value(relay_fd, 0);
        relay_state = 0;
        log_message("Relay = OFF");
        last_state = 0;
    }
}

int main() {
    setup_signal_handlers();

    if (setup_gpio() < 0) {
        exit(EXIT_FAILURE);
    }

    if (setup_i2c() < 0) {
        exit(EXIT_FAILURE);
    }

    log_message("System initialized");

    while (1) {
        int lux = read_light_level();
        if (lux < 0) {
            log_message("Sensor non-response, turning relay off");
            gpiod_line_set_value(relay_fd, 0);
            relay_state = 0;
            log_message("Relay = OFF");
        } else {
            char log_buffer[100];
            snprintf(log_buffer, sizeof(log_buffer), "Lux = %d", lux);
            log_message(log_buffer);
            control_relay(lux);
        }

        sleep(POLL_INTERVAL);
    }

    return 0;
}

