#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <pthread.h>
#include <time.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define LOG_FILE "water_flow.log"
#define DEBOUNCE_TIMEOUT 1000000 // 1 second in nanoseconds
#define OPEN_STATE 1
#define CLOSED_STATE 0
#define HIGH 1
#define LOW 0

static volatile int running = 1;
static int solenoid_state = OPEN_STATE;
static unsigned long pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

void log_event(const char *event) {
    if (log_file) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(log_file, "[%s] %s\n", time_str, event);
        fflush(log_file);
    }
}

void handle_signal(int sig) {
    running = 0;
    log_event("Received termination signal");
    if (solenoid_state == CLOSED_STATE) {
        gpiod_line_set_value(solenoid_line, HIGH);
        solenoid_state = OPEN_STATE;
        log_event("Solenoid opened");
    }
}

void *flow_sensor_isr(void *arg) {
    struct gpiod_line *line = (struct gpiod_line *)arg;
    struct gpiod_line_event event;
    while (running) {
        if (gpiod_line_event_wait(line, DEBOUNCE_TIMEOUT, &event) == 0) {
            pthread_mutex_lock(&pulse_mutex);
            pulse_count++;
            pthread_mutex_unlock(&pulse_mutex);
        }
    }
    return NULL;
}

void calculate_and_log_flow() {
    pthread_mutex_lock(&pulse_mutex);
    unsigned long pulses = pulse_count;
    pulse_count = 0;
    pthread_mutex_unlock(&pulse_mutex);

    double lpm = (pulses / 7.5); // 7.5 pulses per liter
    char log_buffer[100];
    snprintf(log_buffer, sizeof(log_buffer), "Flow: %.2f LPM", lpm);
    log_event(log_buffer);

    if (lpm > 5.0 && solenoid_state == OPEN_STATE) {
        gpiod_line_set_value(solenoid_line, LOW);
        solenoid_state = CLOSED_STATE;
        log_event("Solenoid closed");
    } else if (lpm < 4.5 && solenoid_state == CLOSED_STATE) {
        gpiod_line_set_value(solenoid_line, HIGH);
        solenoid_state = OPEN_STATE;
        log_event("Solenoid opened");
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *flow_sensor_line, *solenoid_line;
    struct gpiod_line_event_config event_config;
    pthread_t isr_thread;
    struct sigaction sa;

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    flow_sensor_line = gpiod_chip_get_line(chip, FLOW_SENSOR_PIN);
    if (!flow_sensor_line) {
        fprintf(stderr, "Failed to get flow sensor line\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!solenoid_line) {
        fprintf(stderr, "Failed to get solenoid line\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(flow_sensor_line, "flow_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        fprintf(stderr, "Failed to request flow sensor line\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(solenoid_line, "solenoid", HIGH) < 0) {
        fprintf(stderr, "Failed to request solenoid line\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    gpiod_line_event_config_init(&event_config);
    if (gpiod_line_event_configure_with_callbacks(flow_sensor_line, &event_config, NULL, NULL, flow_sensor_isr, flow_sensor_line) < 0) {
        fprintf(stderr, "Failed to configure flow sensor event\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (pthread_create(&isr_thread, NULL, flow_sensor_isr, flow_sensor_line) != 0) {
        fprintf(stderr, "Failed to create ISR thread\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        sleep(1);
        calculate_and_log_flow();
    }

    pthread_cancel(isr_thread);
    pthread_join(isr_thread, NULL);
    pthread_mutex_destroy(&pulse_mutex);

    if (solenoid_state == CLOSED_STATE) {
        gpiod_line_set_value(solenoid_line, HIGH);
        solenoid_state = OPEN_STATE;
        log_event("Solenoid opened");
    }

    fclose(log_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

