#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <json-c/json.h>
#include <gpiod.h>
#include <pigpio.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <fcntl.h>

#define DATA_PIN 23
#define SCK_PIN 24
#define SERVO_PIN 18
#define SERVER_IP "127.0.0.1"
#define SERVER_PORT 12345
#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define MAX_ATTEMPTS 1000
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_KNOWN_WEIGHT 100.0

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int read_config(const char *filename, double *calibration_factor, double *known_weight) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (strncmp(line, "calibration_factor=", 19) == 0) {
            *calibration_factor = atof(line + 19);
        } else if (strncmp(line, "known_weight=", 12) == 0) {
            *known_weight = atof(line + 12);
        }
    }

    fclose(file);

    if (*calibration_factor == 0.0) {
        *calibration_factor = DEFAULT_CALIBRATION_FACTOR;
    }
    if (*known_weight == 0.0) {
        *known_weight = DEFAULT_KNOWN_WEIGHT;
    }

    return 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return -1;
    }

    if (gpioSetMode(DATA_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SCK_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

int initialize_socket() {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Failed to create socket: %s\n", strerror(errno));
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(SERVER_IP);
    server_addr.sin_port = htons(SERVER_PORT);

    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Failed to bind socket: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    if (listen(sockfd, 5) < 0) {
        fprintf(stderr, "Failed to listen on socket: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    return sockfd;
}

int read_hx711(int *value) {
    int count = 0;
    int result = 0;

    gpioWrite(SCK_PIN, 0);
    gpioDelay(1);

    while (gpioRead(DATA_PIN) == 1) {
        if (++count > MAX_ATTEMPTS) {
            fprintf(stderr, "HX711 timeout\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1);
        result = (result << 1) | gpioRead(DATA_PIN);
        gpioWrite(SCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(SCK_PIN, 0);

    *value = result;
    return 0;
}

int calibrate_hx711(double calibration_factor, double known_weight) {
    int value;
    if (read_hx711(&value) < 0) {
        return -1;
    }

    return (int)(value / known_weight * calibration_factor);
}

int map_weight_to_pulse_width(int weight, int *pulse_width) {
    *pulse_width = 1000 + (weight * (2000 - 1000) / 1000);
    return 0;
}

void log_event(const char *target_weight, const char *actual_weight, const char *error) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    json_object *jobj = json_object_new_object();
    json_object *jtarget = json_object_new_string(target_weight);
    json_object *jactual = json_object_new_string(actual_weight);
    json_object *jtime = json_object_new_string(time_str);
    json_object *jerror = json_object_new_string(error ? error : "");

    json_object_object_add(jobj, "time", jtime);
    json_object_object_add(jobj, "target_weight", jtarget);
    json_object_object_add(jobj, "actual_weight", jactual);
    json_object_object_add(jobj, "error", jerror);

    fprintf(log_file, "%s\n", json_object_to_json_string(jobj));
    json_object_put(jobj);

    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
    double known_weight = DEFAULT_KNOWN_WEIGHT;

    if (read_config(CONFIG_FILE, &calibration_factor, &known_weight) < 0) {
        fprintf(stderr, "Failed to read config file, using defaults\n");
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    int sockfd = initialize_socket();
    if (sockfd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int client_sockfd;
    struct sockaddr_in client_addr;
    socklen_t client_addr_len = sizeof(client_addr);

    while (keep_running) {
        client_sockfd = accept(sockfd, (struct sockaddr *)&client_addr, &client_addr_len);
        if (client_sockfd < 0) {
            if (errno == EINTR) {
                break;
