            fprintf(stderr, "Failed to accept connection: %s\n", strerror(errno));
            continue;
        }

        char buffer[256];
        int bytes_received = recv(client_sockfd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            fprintf(stderr, "Failed to receive data: %s\n", strerror(errno));
            close(client_sockfd);
            continue;
        }

        buffer[bytes_received] = '\0';
        int target_weight = atoi(buffer);

        int pulse_width;
        if (map_weight_to_pulse_width(target_weight, &pulse_width) < 0) {
            char error_msg[] = "Failed to map weight to pulse width";
            send(client_sockfd, error_msg, sizeof(error_msg), 0);
            log_event(buffer, "N/A", error_msg);
            close(client_sockfd);
            continue;
        }

        gpioPWM(SERVO_PIN, 50, pulse_width);

        sleep(1);

        int actual_value;
        if (read_hx711(&actual_value) < 0) {
            char error_msg[] = "HX711 read error";
            send(client_sockfd, error_msg, sizeof(error_msg), 0);
            log_event(buffer, "N/A", error_msg);
