#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50

static volatile int keep_running = 1;
static int debounce_ms = DEFAULT_DEBOUNCE_MS;
static struct gpiod_chip *chip;
static struct gpiod_line *touch_line;
static struct gpiod_line *relay_line;

void print_timestamp() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[20];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("%s ", buffer);
}

void log_relay_state(int state) {
    print_timestamp();
    if (state) {
        printf("Relay: ON\n");
    } else {
        printf("Relay: OFF\n");
    }
}

void cleanup() {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_signal(int sig) {
    keep_running = 0;
    cleanup();
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Failed to get touch sensor line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES)) {
        fprintf(stderr, "Failed to request touch sensor line\n");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line\n");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0)) {
        fprintf(stderr, "Failed to request relay line\n");
        gpiod_line_release(relay_line);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (argc > 2 && strcmp(argv[1], "-d") == 0) {
        debounce_ms = atoi(argv[2]);
    }

    int last_state = gpiod_line_get_value(touch_line);
    int relay_state = 0;
    log_relay_state(relay_state);
    gpiod_line_set_value(relay_line, relay_state);

    while (keep_running) {
        int current_state = gpiod_line_get_value(touch_line);
        if (current_state != last_state) {
            usleep(debounce_ms * 1000);
            current_state = gpiod_line_get_value(touch_line);
            if (current_state != last_state) {
                last_state = current_state;
                relay_state = !relay_state;
                gpiod_line_set_value(relay_line, relay_state);
                log_relay_state(relay_state);
            }
        }
        usleep(1000); // Polling interval
    }

    cleanup();
    return EXIT_SUCCESS;
}

