#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <termios.h>
#include <gpiod.h>

#define SERVO_GPIO 18
#define PWM_PERIOD_NS 20000 // 20 ms period
#define MIN_PULSE_WIDTH_US 500
#define MAX_PULSE_WIDTH_US 2500
#define DEGREE_STEP 10

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct termios orig_termios;
static int current_angle = 90;

void restore_terminal_settings() {
    tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    restore_terminal_settings();
}

void handle_signal(int sig) {
    cleanup();
    exit(EXIT_FAILURE);
}

int setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, SERVO_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request(line, "servo_control", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT)) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_set_flags(line, GPIOD_LINE_FLAG_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to set line flags\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_set_request_type(line, GPIOD_LINE_REQ_TYPE_PULSE)) {
        fprintf(stderr, "Failed to set request type\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_set_consumer(line, "servo_control")) {
        fprintf(stderr, "Failed to set consumer\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_set_polarity(line, GPIOD_LINE_POLARITY_NORMAL)) {
        fprintf(stderr, "Failed to set polarity\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_set_flags(line, GPIOD_LINE_FLAG_REQUEST_OUTPUT)) {
        fprintf(stderr, "Failed to set request output flag\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int set_servo_angle(int angle) {
    int pulse_width_us = (angle * (MAX_PULSE_WIDTH_US - MIN_PULSE_WIDTH_US) / 180) + MIN_PULSE_WIDTH_US;
    int pulse_width_ns = pulse_width_us * 1000;

    if (gpiod_line_set_request_type(line, GPIOD_LINE_REQ_TYPE_PULSE)) {
        fprintf(stderr, "Failed to set request type\n");
        return -1;
    }

    if (gpiod_line_set_polarity(line, GPIOD_LINE_POLARITY_NORMAL)) {
        fprintf(stderr, "Failed to set polarity\n");
        return -1;
    }

    if (gpiod_line_set_flags(line, GPIOD_LINE_FLAG_REQUEST_OUTPUT)) {
        fprintf(stderr, "Failed to set request output flag\n");
        return -1;
    }

    if (gpiod_line_set_request(line, pulse_width_ns, PWM_PERIOD_NS)) {
        fprintf(stderr, "Failed to set pulse width\n");
        return -1;
    }

    return 0;
}

void setup_terminal() {
    struct termios new_termios;
    tcgetattr(STDIN_FILENO, &orig_termios);
    new_termios = orig_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &new_termios);
}

int main() {
    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    setup_terminal();

    signal(SIGINT, handle_signal);

    if (set_servo_angle(current_angle) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    char c;
    while (1) {
        if (read(STDIN_FILENO, &c, 1) != 1) {
            break;
        }

        if (c == '+') {
            current_angle += DEGREE_STEP;
            if (current_angle > 180) {
                current_angle = 180;
            }
        } else if (c == '-') {
            current_angle -= DEGREE_STEP;
            if (current_angle < 0) {
                current_angle = 0;
            }
        } else if (c == 'q') {
            break;
        }

        if (set_servo_angle(current_angle) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        printf("Current angle: %d°\n", current_angle);
    }

    if (gpiod_line_set_request(line, 0, 0) != 0) {
        fprintf(stderr, "Failed to stop PWM\n");
    }

    cleanup();
    return EXIT_SUCCESS;
}

