#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <syslog.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define RPM_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;
static int chip_fd = -1;
static int line_fd = -1;
static FILE *log_file = NULL;
static unsigned long pulse_count = 0;
static struct timespec last_time;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s: %s\n", message, strerror(errno));
    syslog(LOG_ERR, "%s: %s", message, strerror(errno));
}

void write_log(const char *timestamp, double rpm) {
    if (fprintf(log_file, "%s,%0.2f\n", timestamp, rpm) < 0) {
        log_error("Failed to write to log file");
    }
    fflush(log_file);
}

void get_iso8601_timestamp(char *buffer, size_t buffer_size) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(buffer, buffer_size, "%Y-%m-%dT%H:%M:%S", tm_info);
}

double calculate_rpm(struct timespec *start_time, unsigned long pulses) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    double elapsed_seconds = (now.tv_sec - start_time->tv_sec) + 
                             (now.tv_nsec - start_time->tv_nsec) / 1e9;
    return (pulses / elapsed_seconds) * 60.0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip_fd = gpiod_chip_open("/dev/gpiochip0");
    if (chip_fd < 0) {
        log_error("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line_fd = gpiod_line_request(chip_fd, GPIO_PIN, "motor_rpm_monitor", GPIOD_LINE_REQ_DIR_IN | GPIOD_LINE_REQ_EDGE_RISING | GPIOD_LINE_REQ_DEBOUNCE_MS(DEBOUNCE_MS));
    if (line_fd < 0) {
        log_error("Failed to request GPIO line");
        gpiod_chip_close(chip_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("motor_rpm.log", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        gpiod_line_release(chip_fd, line_fd);
        gpiod_chip_close(chip_fd);
        return EXIT_FAILURE;
    }

    clock_gettime(CLOCK_MONOTONIC, &last_time);

    while (keep_running) {
        unsigned long events;
        int ret = gpiod_line_event_wait(line_fd, DEBOUNCE_MS * 1000, &events);
        if (ret < 0) {
            log_error("Failed to wait for GPIO event");
            break;
        }

        if (events & GPIOD_LINE_EVENT_RISING_EDGE) {
            pulse_count++;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec - last_time.tv_sec >= RPM_INTERVAL_SEC) {
            double rpm = calculate_rpm(&last_time, pulse_count);
            char timestamp[26];
            get_iso8601_timestamp(timestamp, sizeof(timestamp));
            printf("RPM: %0.2f\n", rpm);
            write_log(timestamp, rpm);
            pulse_count = 0;
            last_time = now;
        }
    }

    gpiod_line_release(chip_fd, line_fd);
    gpiod_chip_close(chip_fd);
    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

