#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_INTERVAL 50 // milliseconds
#define TOUCH_HOLD_TIME 10000 // milliseconds
#define LOG_FILE "error_log.txt"

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signal) {
    exit_flag = 1;
}

void log_error(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s\n", message);
        fclose(log);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        log_error("Failed to set touch sensor pin mode");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        log_error("Failed to set relay pin mode");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_UP) != 0) {
        log_error("Failed to set pull-up/down for touch sensor pin");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        log_error("Failed to initialize relay to OFF");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_touch_state = 0;
    int relay_state = 0;
    time_t last_touch_time = 0;
    time_t current_time;

    while (!exit_flag) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            log_error("Failed to read touch sensor state");
            break;
        }

        if (touch_state != last_touch_state) {
            last_touch_state = touch_state;
            if (touch_state == 1) {
                last_touch_time = time(NULL);
            }
        }

        if (touch_state == 1) {
            current_time = time(NULL);
            if (difftime(current_time, last_touch_time) > TOUCH_HOLD_TIME / 1000) {
                if (relay_state == 1) {
                    gpioWrite(RELAY_PIN, 0);
                    relay_state = 0;
                }
                last_touch_state = 0; // Reset touch state to ignore further toggles
            } else if (last_touch_state == 0) {
                gpioWrite(RELAY_PIN, !relay_state);
                relay_state = !relay_state;
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    // Cleanup
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();

    return 0;
}

