#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

#define PWM_PIN 18
#define PWM_CHIP 0
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24
#define LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_MS 100
#define Kp 1.0

static volatile int running = 1;
static int pwm_chip_fd = -1;
static int valve_enable_fd = -1;
static int flow_sensor_fd = -1;
static int pwm_line = -1;
static int valve_enable_line = -1;
static int flow_sensor_line = -1;
static int target_flow_rate = 0;
static int flow_count = 0;
static FILE *log_file = NULL;

void handle_signal(int sig) {
    running = 0;
}

void log_flow_rate(int flow_rate, int valve_position) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    int timestamp_ms = (tm_info->tm_sec * 1000) + (tm_info->tm_usec / 1000);

    fprintf(log_file, "%d,%d,%d\n", timestamp_ms, flow_rate, valve_position);
    fflush(log_file);
}

void flow_sensor_callback(void *user_data) {
    flow_count++;
}

void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_number(PWM_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open PWM chip\n");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get PWM line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    pwm_line = gpiod_line_request(line, "pwm_control", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    if (pwm_line < 0) {
        fprintf(stderr, "Failed to request PWM line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(pwm_line, 0);

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpiod_line_release(pwm_line);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, VALVE_ENABLE_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get valve enable line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(pwm_line);
        exit(EXIT_FAILURE);
    }

    valve_enable_line = gpiod_line_request(line, "valve_enable", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    if (valve_enable_line < 0) {
        fprintf(stderr, "Failed to request valve enable line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(pwm_line);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(valve_enable_line, 1);

    line = gpiod_chip_get_line(chip, FLOW_SENSOR_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get flow sensor line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(valve_enable_line);
        gpiod_line_release(pwm_line);
        exit(EXIT_FAILURE);
    }

    flow_sensor_line = gpiod_line_request(line, "flow_sensor", GPIOD_LINE_REQUEST_DIRECTIONS_INPUT);
    if (flow_sensor_line < 0) {
        fprintf(stderr, "Failed to request flow sensor line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(valve_enable_line);
        gpiod_line_release(pwm_line);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_both_edges(flow_sensor_line);
    gpiod_line_event_handler_add(flow_sensor_line, flow_sensor_callback, NULL);

    gpiod_chip_close(chip);
}

void cleanup() {
    if (pwm_line >= 0) {
        gpiod_line_release(pwm_line);
    }
    if (valve_enable_line >= 0) {
        gpiod_line_set_value(valve_enable_line, 0);
        gpiod_line_release(valve_enable_line);
    }
    if (flow_sensor_line >= 0) {
        gpiod_line_event_handler_remove(flow_sensor_line);
        gpiod_line_release(flow_sensor_line);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                if (sscanf(optarg, "%d", &target_flow_rate) != 1 || target_flow_rate <= 0) {
                    fprintf(stderr, "Invalid target flow rate\n");
                    exit(EXIT_FAILURE);
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (target_flow_rate <= 0) {
        fprintf(stderr, "Target flow rate must be specified and positive\n");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "timestamp_ms,flow_rate,valve_position\n");

    struct timespec last_sample_time;
    clock_gettime(CLOCK_MONOTONIC, &last_sample_time);

    while (running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        if (now.tv_sec > last_sample_time.tv_sec || (now.tv_sec == last_sample_time.tv_sec && now.tv_nsec - last_sample_time.tv_nsec >= 100000000)) {
            int flow_rate = (flow_count * 60) / 7; // Convert pulses per second to L/min
            flow_count = 0;

            int error = target_flow_rate - flow_rate;
            int valve_position = Kp * error;
            valve_position = valve_position < 0 ? 0 : (valve_position > 255 ? 255 : valve_position);

            gpiod_pwm_set_duty_cycle(pwm_line, valve_position);
            log_flow_rate(flow_rate, valve_position);

            last_sample_time = now;
        }

        usleep(1000); // Sleep for 1ms to prevent busy-waiting
    }

    cleanup();
    return 0;
}

