#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <gpiod.h>
#include <math.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

#define SAMPLE_TIME_MS 100
#define PWM_FREQUENCY_HZ 100
#define TARGET_RPM 60

#define PWM_PERIOD_NS (1000000000 / PWM_FREQUENCY_HZ)

typedef struct {
    int16_t kp, ki, kd;
    int16_t integral;
    int16_t prev_error;
    int16_t prev_output;
} PIDController;

typedef struct {
    gpiod_chip *chip;
    gpiod_line *ena, *in1, *in2, *enb, *in3, *in4;
    gpiod_line *enc_a, *enc_b;
    int32_t count;
    pthread_mutex_t mutex;
    PIDController pid;
    int duty_cycle;
} Motor;

Motor motor1, motor2;
FILE *log_file;
pthread_t encoder_thread1, encoder_thread2;
volatile bool running = true;

void handle_signal(int sig) {
    running = false;
}

void setup_gpio(Motor *motor) {
    motor->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!motor->chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    motor->ena = gpiod_chip_get_line(motor->chip, MOTOR1_ENA);
    motor->in1 = gpiod_chip_get_line(motor->chip, MOTOR1_IN1);
    motor->in2 = gpiod_chip_get_line(motor->chip, MOTOR1_IN2);
    motor->enb = gpiod_chip_get_line(motor->chip, MOTOR2_ENB);
    motor->in3 = gpiod_chip_get_line(motor->chip, MOTOR2_IN3);
    motor->in4 = gpiod_chip_get_line(motor->chip, MOTOR2_IN4);
    motor->enc_a = gpiod_chip_get_line(motor->chip, ENCODER1_A);
    motor->enc_b = gpiod_chip_get_line(motor->chip, ENCODER1_B);

    if (!motor->ena || !motor->in1 || !motor->in2 || !motor->enb || !motor->in3 || !motor->in4 || !motor->enc_a || !motor->enc_b) {
        perror("Failed to get GPIO lines");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(motor->ena, "motor1_ena", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0 ||
        gpiod_line_request_output(motor->in1, "motor1_in1", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0 ||
        gpiod_line_request_output(motor->in2, "motor1_in2", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0 ||
        gpiod_line_request_output(motor->enb, "motor2_enb", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0 ||
        gpiod_line_request_output(motor->in3, "motor2_in3", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0 ||
        gpiod_line_request_output(motor->in4, "motor2_in4", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0) {
        perror("Failed to request GPIO lines");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_both_edges(motor->enc_a, "encoder1_a") < 0 ||
        gpiod_line_request_input(motor->enc_b, "encoder1_b") < 0) {
        perror("Failed to request encoder lines");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&motor->mutex, NULL);
    motor->count = 0;
    motor->pid.kp = 1;
    motor->pid.ki = 0;
    motor->pid.kd = 0;
    motor->pid.integral = 0;
    motor->pid.prev_error = 0;
    motor->pid.prev_output = 0;
    motor->duty_cycle = 0;
}

void cleanup_gpio(Motor *motor) {
    gpiod_line_release(motor->ena);
    gpiod_line_release(motor->in1);
    gpiod_line_release(motor->in2);
    gpiod_line_release(motor->enb);
    gpiod_line_release(motor->in3);
    gpiod_line_release(motor->in4);
    gpiod_line_release(motor->enc_a);
    gpiod_line_release(motor->enc_b);
    gpiod_chip_close(motor->chip);
    pthread_mutex_destroy(&motor->mutex);
}

void *encoder_thread(void *arg) {
    Motor *motor = (Motor *)arg;
    struct gpiod_line_event event;
    int ret;

    while (running) {
        ret = gpiod_line_event_wait(motor->enc_a, &event, -1);
        if (ret < 0) {
            perror("Failed to wait for encoder event");
            continue;
        }

        pthread_mutex_lock(&motor->mutex);
        int b_state = gpiod_line_get_value(motor->enc_b);
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            motor->count += (b_state == 1) ? 1 : -1;
        } else {
            motor->count += (b_state == 1) ? -1 : 1;
        }
        pthread_mutex_unlock(&motor->mutex);
    }

    return NULL;
}

void calculate_pid(Motor *motor, int target_rpm) {
    pthread_mutex_lock(&motor->mutex);
    int32_t count = motor->count;
    motor->count = 0;
    pthread_mutex_unlock(&motor->mutex);

    int32_t current_rpm = (count * 60) / (2 * SAMPLE_TIME_MS); // Assuming 2 pulses per revolution
    int32_t error = target_rpm - current_rpm;
    motor->pid.integral += error;
    int32_t derivative = error - motor->pid.prev_error;
    int32_t output = motor->pid.kp * error + motor->pid.ki * motor->pid.integral + motor->pid.kd * derivative;

    motor->pid.prev_error = error;
    motor->duty_cycle = (output > 0) ? output : 0;
}

void set_motor_speed(Motor *motor) {
    int period_ns = PWM_PERIOD_NS;
    int on_time_ns = (motor->duty_cycle * period_ns) / 100;
    int off_time_ns = period_ns - on_time_ns;

    gpiod_line_set_value(motor->ena, 1);
    usleep(on_time_ns / 1000);
    gpiod_line_set_value(motor->ena, 0);
    usleep(off_time_ns / 1000);
}

void log_data(Motor *motor1, Motor *motor2) {
    int32_t count1, count2;
    pthread_mutex_lock(&motor1->mutex);
    count1 = motor1->count;
    motor1->count = 0;
    pthread_mutex_unlock(&motor1->mutex);

    pthread_mutex_lock(&motor2->mutex);
    count2 = motor2->count;
    motor2->count = 0;
    pthread_mutex_unlock(&motor2->mutex);

    int32_t rpm1 = (count1 * 60) / (2 * SAMPLE_TIME_MS);
    int32_t rpm2 = (count2 * 60) / (2 * SAMPLE_TIME_MS);

    fprintf(log_file, "%d,%d,%d,%d,%d,%d,%d,%d,%d\n",
            rpm1, motor1->pid.kp * (TARGET_RPM - rpm1), motor1->pid.ki * motor1->pid.integral, motor1->pid.kd * (TARGET_RPM - rpm1 - motor1->pid.prev_error), motor1->duty_cycle,
