void setup_gpio(Motor *motor) {
    motor->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!motor->chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    motor->ena = gpiod_chip_get_line(motor->chip, MOTOR1_ENA);
    motor->in1 = gpiod_chip_get_line(motor->chip, MOTOR1_IN1);
