void *encoder_thread(void *arg) {
    Motor *motor = (Motor *)arg;
    struct gpiod_line_event event;
    int ret;

    while (running) {
        ret = gpiod_line_event_wait(motor->enc_a, &event, -1);
        if (ret < 0) {
            perror("Failed to wait for encoder event");
            continue;
        }

        pthread_mutex_lock(&motor->mutex);
        int b_state = gpiod_line_get_value(motor->enc_b);
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            motor->count += (b_state == 1) ? 1 : -1;
        } else {
            motor->count += (b_state == 1) ? -1 : 1;
        }
        pthread_mutex_unlock(&motor->mutex);
    }

    return NULL;
}

void calculate_pid(Motor *motor, int target_rpm) {
    pthread_mutex_lock(&motor->mutex);
    int32_t count = motor->count;
    motor->count = 0;
    pthread_mutex_unlock(&motor->mutex);

    int32_t current_rpm = (count * 60) / (2 * SAMPLE_TIME_MS); // Assuming 2 pulses per revolution
    int32_t error = target_rpm - current_rpm;
    motor->pid.integral += error;
    int32_t derivative = error - motor->pid.prev_error;
    int32_t output = motor->pid.kp * error + motor->pid.ki * motor->pid.integral + motor->pid.kd * derivative;

    motor->pid.prev_error = error;
    motor->duty_cycle = (output > 0) ? output : 0;
}

