#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define GPIO_RELAY 17
#define RELAY_LOG "relay_log.txt"

static volatile int keep_running = 1;
static int relay_fd = -1;
static int i2c_fd = -1;

void handle_sigint(int sig) {
    keep_running = 0;
    if (relay_fd >= 0) {
        gpiod_line_set_value(relay_fd, 0);
        gpiod_line_release(relay_fd);
        relay_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    printf("Exiting gracefully...\n");
    exit(0);
}

int init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    relay_fd = gpiod_line_request_output(line, "relay_control", 0);
    if (relay_fd < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int mpr121_write_register(uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int mpr121_read_register(uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(i2c_fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return 0;
}

int mpr121_init() {
    uint8_t value;

    // Soft reset
    if (mpr121_write_register(0x80, 0x63) < 0) return -1;

    // Check ECR register
    if (mpr121_read_register(0x05, &value) < 0) return -1;
    if ((value & 0x0A) != 0x0A) {
        fprintf(stderr, "MPR121 not found\n");
        return -1;
    }

    // Configure filtering parameters
    if (mpr121_write_register(0x2A, 0x0F) < 0) return -1;
    if (mpr121_write_register(0x2B, 0x00) < 0) return -1;

    // Set touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_register(0x41 + i, 0x0A) < 0) return -1;
        if (mpr121_write_register(0x42 + i, 0x00) < 0) return -1;
    }

    // Enable run mode
    if (mpr121_write_register(0x00, 0x00) < 0) return -1;

    return 0;
}

void log_relay_state(int state) {
    FILE *log_file = fopen(RELAY_LOG, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s Relay state: %d\n", timestamp, state);
    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_sigint);

    if (init_gpio() < 0) return EXIT_FAILURE;
    if (init_i2c() < 0) return EXIT_FAILURE;

    if (mpr121_init() < 0) {
        fprintf(stderr, "Failed to initialize MPR121\n");
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    while (keep_running) {
        uint8_t touch_status[2];
        if (mpr121_read_register(0x00, touch_status) < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            break;
        }

        int touched = touch_status[0] | (touch_status[1] << 8);
        int new_relay_state = (touched != 0);

        if (new_relay_state != relay_state) {
            relay_state = new_relay_state;
            gpiod_line_set_value(relay_fd, relay_state);
            log_relay_state(relay_state);
        }

        usleep(50000); // 50 ms
    }

    if (relay_fd >= 0) {
        gpiod_line_set_value(relay_fd, 0);
        gpiod_line_release(relay_fd);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

