        i2c_free_context(ctx);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    usleep(100000); // 100 ms delay

    if (i2c_write(ctx, MPR121_REG_CONFIG, 0x0A) < 0) {
        fprintf(stderr, "Failed to set MPR121 to run mode\n");
        i2c_free_context(ctx);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint8_t touch_status = 0;
        if (i2c_read(ctx, MPR121_REG_ELE0_TCH, &touch_status) < 0) {
