#define RATE_LIMIT_MS 2000

static int fd_log;
static struct timespec last_motion_time = {0, 0};
static struct timespec last_unlock_time = {0, 0};
static int relay_fd = -1;
static int pir_fd = -1;

void log_event(const char *event) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    fprintf(fd_log, "%ld.%09ld: %s\n", now.tv_sec, now.tv_nsec / 1000, event);
    fflush(fd_log);
}

void cleanup() {
    if (fd_log != -1) {
        fclose(fd_log);
    }
    if (relay_fd != -1) {
        gpiod_line_set_value(relay_fd, 0);
        gpiod_line_release(relay_fd);
    }
    if (pir_fd != -1) {
        gpiod_line_release(pir_fd);
    }
    exit(0);
}

void handle_signal(int sig) {
    cleanup();
}

