    fd_log = fopen("door_events.log", "a");
    if (fd_log == -1) {
        perror("Failed to open log file");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup();
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line\n");
        gpiod_chip_close(chip);
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "door_strike_relay", 0)) {
        fprintf(stderr, "Failed to request relay line\n");
        gpiod_chip_close(chip);
        cleanup();
        return 1;
    }
    relay_fd = gpiod_line_get_fd(relay_line);

    pir_line = gpiod_chip_get_line(chip, PIR_SENSOR_PIN);
    if (!pir_line) {
        fprintf(stderr, "Failed to get PIR sensor line\n");
        gpiod_chip_close(chip);
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(pir_line, "pir_sensor", GPIOD_LINE_REQ_DIR_NONE)) {
        fprintf(stderr, "Failed to request PIR sensor line\n");
        gpiod_chip_close(chip);
        cleanup();
        return 1;
    }
    pir_fd = gpiod_line_get_fd(pir_line);

    gpiod_chip_close(chip);

    while (1) {
        if (gpiod_line_event_wait(pir_fd, POLL_INTERVAL_MS)) {
            fprintf(stderr, "Failed to wait for PIR sensor event\n");
            cleanup();
            return 1;
        }

        value = gpiod_line_get_value(pir_fd);
        if (value == 1) {
            clock_gettime(CLOCK_REALTIME, &now);
            if (last_unlock_time.tv_sec == 0 || 
                (now.tv_sec - last_unlock_time.tv_sec) * 1000 + 
                (now.tv_nsec - last_unlock_time.tv_nsec) / 1000000 > RATE_LIMIT_MS) {

                gpiod_line_set_value(relay_fd, 1);
                log_event("Motion detected, door unlocked");
                clock_gettime(CLOCK_REALTIME, &last_unlock_time);
                usleep(RELAY_ON_DURATION_MS * 1000);
                gpiod_line_set_value(relay_fd, 0);
                rate_limited = 0;
            } else {
                log_event("Rate limited, ignoring motion");
                rate_limited = 1;
            }
        }

        if (!rate_limited) {
            clock_gettime(CLOCK_REALTIME, &last_motion_time);
        }
    }

    cleanup();
    return 0;
}

