#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define PWM_PERIOD_NS 20000000 // 20ms period for PWM

volatile sig_atomic_t shutdown_flag = 0;

void handle_sigint(int sig) {
    shutdown_flag = 1;
}

int setup_pwm(gpiod_chip *chip, int pin, gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, pin);
    if (!*line) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", pin);
        return -1;
    }

    if (gpiod_line_request(*line, "pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0) {
        fprintf(stderr, "Failed to request line for GPIO %d\n", pin);
        gpiod_line_release(*line);
        return -1;
    }

    if (gpiod_line_set_flags(*line, GPIOD_LINE_FLAG_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to set flags for GPIO %d\n", pin);
        gpiod_line_release(*line);
        return -1;
    }

    if (gpiod_line_set_value(*line, 0) < 0) {
        fprintf(stderr, "Failed to set initial value for GPIO %d\n", pin);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

void cleanup(gpiod_chip *chip, gpiod_line *line1, gpiod_line *line2) {
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    gpiod_chip_close(chip);
}

void generate_and_play_pattern(gpiod_line *line1, gpiod_line *line2) {
    int steps = rand() % 11 + 5; // 5 to 15 steps
    for (int i = 0; i < steps; i++) {
        uint32_t duty_cycle1 = rand() % 256;
        uint32_t duty_cycle2 = rand() % 256;
        uint32_t duration = (rand() % 151) + 50; // 50ms to 200ms

        gpiod_line_set_value(line1, 1);
        gpiod_line_set_value(line2, 1);
        usleep(PWM_PERIOD_NS / 1000 * duty_cycle1 / 256);
        gpiod_line_set_value(line1, 0);
        usleep(PWM_PERIOD_NS / 1000 * (256 - duty_cycle1) / 256);

        gpiod_line_set_value(line2, 1);
        usleep(PWM_PERIOD_NS / 1000 * duty_cycle2 / 256);
        gpiod_line_set_value(line2, 0);
        usleep(PWM_PERIOD_NS / 1000 * (256 - duty_cycle2) / 256);

        usleep(duration * 1000);
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    gpiod_line *line1 = NULL, *line2 = NULL;
    if (setup_pwm(chip, MOTOR1_PIN, &line1) < 0 || setup_pwm(chip, MOTOR2_PIN, &line2) < 0) {
        cleanup(chip, line1, line2);
        return EXIT_FAILURE;
    }

    srand(time(NULL));

    while (!shutdown_flag) {
        generate_and_play_pattern(line1, line2);
    }

    cleanup(chip, line1, line2);
    return EXIT_SUCCESS;
}

