#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>

#define HX711_DOUT 4
#define HX711_SCK 17
#define SOLENOID_LOCK 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define DEFAULT_SCALE 1.0
#define DEFAULT_OFFSET 0.0
#define CALIBRATION_THRESHOLD 10.0
#define READ_INTERVAL 500000000 // 500 ms in nanoseconds
#define READ_TIMEOUT 500000000 // 500 ms in nanoseconds
#define CALIBRATION_READINGS 100

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

double read_hx711(gpiod_chip *chip, gpiod_line *dout, gpiod_line *sck) {
    uint32_t count = 0;
    uint64_t start_time = gpiod_monotonic_time();
    int bit;

    // Wait for the DOUT to go low
    while (gpiod_line_get_value(dout) == 1) {
        if (gpiod_monotonic_time() - start_time > READ_TIMEOUT) {
            fprintf(stderr, "Read timeout occurred\n");
            return -1;
        }
    }

    // Read 24 bits
    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(sck, 1);
        usleep(1); // Short delay
        bit = gpiod_line_get_value(dout);
        gpiod_line_set_value(sck, 0);
        count = (count << 1) | bit;
    }

    // Read the 25th bit (gain)
    gpiod_line_set_value(sck, 1);
    usleep(1);
    gpiod_line_set_value(sck, 0);

    // Pulse the clock 128 times to reset the chip
    for (int i = 0; i < 128; i++) {
        gpiod_line_set_value(sck, 1);
        usleep(1);
        gpiod_line_set_value(sck, 0);
    }

    return count;
}

double calculate_weight(double raw_value, double scale, double offset) {
    return (raw_value - offset) * scale;
}

void log_reading(double weight, time_t timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%ld %.2f\n", (long)timestamp, weight);
    fclose(log_file);
}

void load_calibration(double *scale, double *offset) {
    FILE *file = fopen(CALIBRATION_FILE, "r");
    if (!file) {
        *scale = DEFAULT_SCALE;
        *offset = DEFAULT_OFFSET;
        return;
    }

    if (fscanf(file, "%lf %lf", scale, offset) != 2) {
        *scale = DEFAULT_SCALE;
        *offset = DEFAULT_OFFSET;
    }

    fclose(file);
}

void save_calibration(double scale, double offset) {
    FILE *file = fopen(CALIBRATION_FILE, "w");
    if (!file) {
        perror("Failed to save calibration file");
        return;
    }
    fprintf(file, "%lf %lf\n", scale, offset);
    fclose(file);
}

void startup_calibration(gpiod_chip *chip, gpiod_line *dout, gpiod_line *sck, double *offset) {
    double sum = 0.0;
    for (int i = 0; i < CALIBRATION_READINGS; i++) {
        double raw_value = read_hx711(chip, dout, sck);
        if (raw_value >= 0) {
            sum += raw_value;
        }
    }
    *offset = sum / CALIBRATION_READINGS;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    gpiod_line *dout = gpiod_chip_get_line(chip, HX711_DOUT);
    gpiod_line *sck = gpiod_chip_get_line(chip, HX711_SCK);
    gpiod_line *lock = gpiod_chip_get_line(chip, SOLENOID_LOCK);

    if (!dout || !sck || !lock) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(lock, "solenoid_lock", 0) < 0) {
        perror("Failed to request solenoid lock line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(dout, "hx711_dout", GPIOD_LINE_REQ_DIR_NONE) < 0) {
        perror("Failed to request HX711 DOUT line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
        perror("Failed to request HX711 SCK line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    double scale, offset;
    load_calibration(&scale, &offset);
    startup_calibration(chip, dout, sck, &offset);

    while (keep_running) {
        double raw_value = read_hx711(chip, dout, sck);
        if (raw_value >= 0) {
            double weight = calculate_weight(raw_value, scale, offset);
            log_reading(weight, time(NULL));

            if (weight > CALIBRATION_THRESHOLD) {
                gpiod_line_set_value(lock, 1);
            } else {
                gpiod_line_set_value(lock, 0);
            }
        }

        struct timespec ts = {0, READ_INTERVAL};
        nanosleep(&ts, NULL);
    }

    save_calibration(scale, offset);
    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(lock);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

