#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define DT_PIN 23
#define SCK_PIN 24
#define LOCK_PIN 17
#define WEIGHT_THRESHOLD 100
#define LOCK_DURATION 5

static volatile int keep_running = 1;
static gpiod_chip *chip;
static gpiod_line *dt_line, *sck_line, *lock_line;
static FILE *log_file;

void log_event(const char *event) {
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", timestamp, event);
        fflush(log_file);
    }
}

void handle_signal(int sig) {
    keep_running = 0;
}

unsigned long read_hx711() {
    unsigned long count = 0;
    int bit;

    // Set SCK low
    gpiod_line_set_value(sck_line, 0);
    usleep(1);

    // Read 24 bits
    for (int i = 0; i < 24; i++) {
        // Pulse SCK
        gpiod_line_set_value(sck_line, 1);
        usleep(1);
        gpiod_line_set_value(sck_line, 0);
        usleep(1);

        // Read bit
        bit = gpiod_line_get_value(dt_line);
        if (bit < 0) {
            log_event("Error reading DT line");
            return 0;
        }
        count = (count << 1) | bit;
    }

    // Read 8-bit checksum
    for (int i = 0; i < 8; i++) {
        gpiod_line_set_value(sck_line, 1);
        usleep(1);
        gpiod_line_set_value(sck_line, 0);
        usleep(1);
    }

    // Set SCK high to put HX711 in standby
    gpiod_line_set_value(sck_line, 1);
    usleep(1);

    return count;
}

void activate_lock() {
    gpiod_line_set_value(lock_line, 1);
    log_event("Solenoid lock activated");
    sleep(LOCK_DURATION);
    gpiod_line_set_value(lock_line, 0);
    log_event("Solenoid lock deactivated");
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("stock_events.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    dt_line = gpiod_chip_get_line(chip, DT_PIN);
    if (!dt_line) {
        perror("Failed to get DT line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(dt_line, "DT", 0) < 0) {
        perror("Failed to request DT line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    sck_line = gpiod_chip_get_line(chip, SCK_PIN);
    if (!sck_line) {
        perror("Failed to get SCK line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(sck_line, "SCK", 0) < 0) {
        perror("Failed to request SCK line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    lock_line = gpiod_chip_get_line(chip, LOCK_PIN);
    if (!lock_line) {
        perror("Failed to get LOCK line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(lock_line, "LOCK", 0) < 0) {
        perror("Failed to request LOCK line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        unsigned long weight = read_hx711();
        if (weight == 0) {
            log_event("HX711 read error or timeout");
            continue;
        }

        if (weight < WEIGHT_THRESHOLD) {
            activate_lock();
        }

        log_event("Weight checked");
        sleep(1);
    }

    gpiod_line_release(dt_line);
    gpiod_line_release(sck_line);
    gpiod_line_release(lock_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

