int read_hx711() {
    struct gpiod_line *data_line = gpiod_chip_get_line(data_fd, DATA_PIN);
    struct gpiod_line *clock_line = gpiod_chip_get_line(clock_fd, CLOCK_PIN);

    uint32_t data = 0;
    int timeout = 0;

    // Wait for the data line to go low
    while (gpiod_line_get_value(data_line) && timeout < TIMEOUT_MS) {
        usleep(1);
        timeout++;
    }
    if (timeout >= TIMEOUT_MS) {
        fprintf(stderr, "Communication timeout\n");
        return -1;
    }

    // Read 24 bits
    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(clock_line, 1);
        usleep(1);
        data = (data << 1) | gpiod_line_get_value(data_line);
        gpiod_line_set_value(clock_line, 0);
        usleep(1);
