#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

#define SENSOR_GPIO 16
#define RELAY_GPIO 20
#define LOG_FILE "relay_events.log"

static volatile sig_atomic_t keep_running = 1;
static gpiod_chip *chip;
static gpiod_line *sensor_line;
static gpiod_line *relay_line;
static FILE *log_file;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(const char *event) {
    if (log_file) {
        fprintf(log_file, "%s\n", event);
        fflush(log_file);
    }
}

void get_iso8601_timestamp(char *buffer, size_t buffer_size) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    strftime(buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", tm_info);
}

void toggle_relay(int sensor_value) {
    int relay_state = gpiod_line_get_value(relay_line);
    if (sensor_value == 0) { // Active-low sensor, LOW means obstacle
        relay_state = !relay_state;
        gpiod_line_set_value(relay_line, relay_state);
        char timestamp[26];
        get_iso8601_timestamp(timestamp, sizeof(timestamp));
        char log_buffer[64];
        snprintf(log_buffer, sizeof(log_buffer), "%s Relay %s", timestamp, relay_state ? "ON" : "OFF");
        log_event(log_buffer);
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor_line, "IR Sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        fprintf(stderr, "Failed to request sensor line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "Relay", 0) < 0) {
        fprintf(stderr, "Failed to request relay line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value\n");
            break;
        }
        toggle_relay(sensor_value);
        usleep(100000); // 100 ms delay
    }

    if (log_file) {
        fclose(log_file);
    }
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

