#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"
#define MAX_DURATION 3600
#define MIN_DURATION 1

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int sig) {
    stop_flag = 1;
}

int read_duration_from_config(const char *filename, unsigned int *duration) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening config file: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), file) == NULL) {
        fprintf(stderr, "Error reading config file: %s\n", strerror(errno));
        fclose(file);
        return -1;
    }

    fclose(file);

    if (strlen(line) == 0) {
        fprintf(stderr, "Config file is empty\n");
        return -1;
    }

    char *key = strtok(line, "=");
    char *value = strtok(NULL, "\n");

    if (!key || !value || strcmp(key, "duration") != 0) {
        fprintf(stderr, "Malformed config line: %s\n", line);
        return -1;
    }

    *duration = (unsigned int)atoi(value);
    if (*duration < MIN_DURATION || *duration > MAX_DURATION) {
        fprintf(stderr, "Duration out of range: %u\n", *duration);
        return -1;
    }

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    unsigned int duration;
    int ret;

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Read duration from config file
    if (read_duration_from_config(CONFIG_FILE, &duration) != 0) {
        return EXIT_FAILURE;
    }

    printf("Configured duration: %u seconds\n", duration);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line
    ret = gpiod_line_request_output(line, "watering_valve", 0, GPIOD_LINE_REQUEST_DIRECTIONS_MASK);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", gpiod_strerror(ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set line low (valve off)
    gpiod_line_set_value(line, 0);
    printf("Valve turned off\n");

    // Main loop
    while (!stop_flag) {
        // Set line high (valve on)
        gpiod_line_set_value(line, 1);
        printf("Valve turned on\n");

        // Wait for the configured duration
        struct timespec ts = { .tv_sec = duration, .tv_nsec = 0 };
        while (duration > 0 && !stop_flag) {
            struct timespec rem;
            ret = nanosleep(&ts, &rem);
            if (ret == -1 && errno == EINTR) {
                ts = rem;
            } else if (ret < 0) {
                fprintf(stderr, "Error during sleep: %s\n", strerror(errno));
                break;
            }
            duration -= ts.tv_sec;
            ts.tv_sec = duration;
        }

        // Set line low (valve off)
        gpiod_line_set_value(line, 0);
        printf("Valve turned off\n");

        if (stop_flag) {
            break;
        }

        // Reset duration for next cycle
        duration = read_duration_from_config(CONFIG_FILE, &duration);
        if (duration == 0) {
            fprintf(stderr, "Error reading config file on next cycle\n");
            break;
        }
    }

    // Ensure valve is off before exiting
    gpiod_line_set_value(line, 0);
    printf("Valve turned off on exit\n");

    // Release resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

