#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <pigpio.h>

#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define LEFT_PWM 22
#define RIGHT_PWM 23
#define LEFT_IN1 24
#define LEFT_IN2 25
#define RIGHT_IN1 26
#define RIGHT_IN2 27

#define BASE_SPEED 150
#define PWM_FREQUENCY 1000
#define SAMPLE_INTERVAL 10

volatile sig_atomic_t stop_flag = 0;
FILE *log_file = NULL;
struct gpiod_chip *chip = NULL;
struct gpiod_line *left_sensor_line = NULL;
struct gpiod_line *middle_sensor_line = NULL;
struct gpiod_line *right_sensor_line = NULL;
struct gpiod_line *left_pwm_line = NULL;
struct gpiod_line *right_pwm_line = NULL;
struct gpiod_line *left_in1_line = NULL;
struct gpiod_line *left_in2_line = NULL;
struct gpiod_line *right_in1_line = NULL;
struct gpiod_line *right_in2_line = NULL;

void handle_sigint(int sig) {
    stop_flag = 1;
}

void log_control_cycle(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s, %d, %d, %d, %d, %d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
    fflush(log_file);
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (left_sensor_line) {
        gpiod_line_release(left_sensor_line);
    }
    if (middle_sensor_line) {
        gpiod_line_release(middle_sensor_line);
    }
    if (right_sensor_line) {
        gpiod_line_release(right_sensor_line);
    }
    if (left_pwm_line) {
        gpiod_line_release(left_pwm_line);
    }
    if (right_pwm_line) {
        gpiod_line_release(right_pwm_line);
    }
    if (left_in1_line) {
        gpiod_line_release(left_in1_line);
    }
    if (left_in2_line) {
        gpiod_line_release(left_in2_line);
    }
    if (right_in1_line) {
        gpiod_line_release(right_in1_line);
    }
    if (right_in2_line) {
        gpiod_line_release(right_in2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    left_sensor_line = gpiod_chip_get_line(chip, LEFT_SENSOR);
    middle_sensor_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR);
    right_sensor_line = gpiod_chip_get_line(chip, RIGHT_SENSOR);
    left_pwm_line = gpiod_chip_get_line(chip, LEFT_PWM);
    right_pwm_line = gpiod_chip_get_line(chip, RIGHT_PWM);
    left_in1_line = gpiod_chip_get_line(chip, LEFT_IN1);
    left_in2_line = gpiod_chip_get_line(chip, LEFT_IN2);
    right_in1_line = gpiod_chip_get_line(chip, RIGHT_IN1);
    right_in2_line = gpiod_chip_get_line(chip, RIGHT_IN2);

    if (!left_sensor_line || !middle_sensor_line || !right_sensor_line ||
        !left_pwm_line || !right_pwm_line || !left_in1_line || !left_in2_line ||
        !right_in1_line || !right_in2_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(left_sensor_line, "left_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0 ||
        gpiod_line_request_input(middle_sensor_line, "middle_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0 ||
        gpiod_line_request_input(right_sensor_line, "right_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0 ||
        gpiod_line_request_output(left_pwm_line, "left_pwm", 0) < 0 ||
        gpiod_line_request_output(right_pwm_line, "right_pwm", 0) < 0 ||
        gpiod_line_request_output(left_in1_line, "left_in1", 1) < 0 ||
        gpiod_line_request_output(left_in2_line, "left_in2", 0) < 0 ||
        gpiod_line_request_output(right_in1_line, "right_in1", 1) < 0 ||
        gpiod_line_request_output(right_in2_line, "right_in2", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("trace_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpiod_line_set_value(left_in1_line, 1);
    gpiod_line_set_value(left_in2_line, 0);
    gpiod_line_set_value(right_in1_line, 1);
    gpiod_line_set_value(right_in2_line, 0);

