#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define LOG_FILE "grow_log.txt"

static volatile int keep_running = 1;
static int relay_fd = -1;
static int i2c_fd = -1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(log_file, "[%s.%03ld] %s\n", time_str, (long) (1000 * (now - (time_t)tm_info)), message);
        fclose(log_file);
    }
}

int setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_message("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!line) {
        gpiod_chip_close(chip);
        log_message("Failed to get GPIO line");
        return -1;
    }

    if (gpiod_line_request_output(line, "relay", 0)) {
        gpiod_chip_close(chip);
        log_message("Failed to request GPIO line");
        return -1;
    }

    relay_fd = gpiod_line_get_fd(line);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

int setup_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_message("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        log_message("Failed to set I2C address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_lux() {
    uint8_t data[2];
    int ret = read(i2c_fd, data, sizeof(data));
    if (ret != sizeof(data)) {
        log_message("Failed to read from BH1750");
        return -1;
    }

    int lux = (data[1] << 8) | data[0];
    return lux;
}

void cleanup() {
    if (relay_fd >= 0) {
        gpiod_line_set_value_fd(relay_fd, 0);
        close(relay_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main() {
    signal(SIGINT, handle_signal);

    if (setup_gpio() < 0 || setup_i2c() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t config = 0x10; // Continuous high resolution mode
    if (write(i2c_fd, &config, 1) != 1) {
        log_message("Failed to configure BH1750");
    }

    int relay_state = 0;
    while (keep_running) {
        usleep(180000); // 180 ms delay

        int lux = read_lux();
        if (lux >= 0) {
            char log_buf[100];
            snprintf(log_buf, sizeof(log_buf), "Lux: %d", lux);
            log_message(log_buf);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                gpiod_line_set_value_fd(relay_fd, 1);
                relay_state = 1;
                log_message("Relay turned ON");
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                gpiod_line_set_value_fd(relay_fd, 0);
                relay_state = 0;
                log_message("Relay turned OFF");
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

