#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SERVO_GPIO 18
#define LOCK_BUTTON_GPIO 21
#define UNLOCK_BUTTON_GPIO 22
#define DEBOUNCE_DELAY 100000 // 100 ms in microseconds

static volatile int keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int setup_gpio_line(gpiod_line_handle_t *line, int gpio, int flags) {
    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    *line = gpiod_chip_get_line(chip, gpio);
    if (!*line) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", gpio);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request(*line, "servo_lock_unlock", flags) < 0) {
        fprintf(stderr, "Failed to request line for GPIO %d\n", gpio);
        gpiod_line_release(*line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

int setup_pwm(gpiod_line_handle_t *line) {
    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    *line = gpiod_chip_get_line(chip, SERVO_GPIO);
    if (!*line) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", SERVO_GPIO);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request(*line, "servo_pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0) {
        fprintf(stderr, "Failed to request line for GPIO %d\n", SERVO_GPIO);
        gpiod_line_release(*line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

void set_servo_pulse_width(gpiod_line_handle_t *line, int pulse_width) {
    if (pulse_width < 500 || pulse_width > 2500) {
        fprintf(stderr, "Pulse width out of range: %d\n", pulse_width);
        return;
    }

    if (gpiod_line_set_value(*line, 1) < 0) {
        fprintf(stderr, "Failed to set line value to 1\n");
        return;
    }
    usleep(pulse_width);
    if (gpiod_line_set_value(*line, 0) < 0) {
        fprintf(stderr, "Failed to set line value to 0\n");
        return;
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    gpiod_line_handle_t lock_button_line, unlock_button_line, servo_line;
    if (setup_gpio_line(&lock_button_line, LOCK_BUTTON_GPIO, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW) < 0 ||
        setup_gpio_line(&unlock_button_line, UNLOCK_BUTTON_GPIO, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW) < 0 ||
        setup_pwm(&servo_line) < 0) {
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (gpiod_line_get_value(lock_button_line) == 0) {
            printf("Lock button pressed\n");
            set_servo_pulse_width(&servo_line, 1000);
            usleep(DEBOUNCE_DELAY);
        } else if (gpiod_line_get_value(unlock_button_line) == 0) {
            printf("Unlock button pressed\n");
            set_servo_pulse_width(&servo_line, 2000);
            usleep(DEBOUNCE_DELAY);
        }
        usleep(10000); // Polling delay
    }

    gpiod_line_release(&lock_button_line);
    gpiod_line_release(&unlock_button_line);
    gpiod_line_release(&servo_line);

    printf("Exiting and releasing resources\n");
    return EXIT_SUCCESS;
}

