#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MOTOR1_ON 1
#define MOTOR1_OFF 0
#define MOTOR2_ON 1
#define MOTOR2_OFF 0
#define MOTOR1_DURATION 200000000 // 200 ms in nanoseconds
#define MOTOR2_DURATION 300000000 // 300 ms in nanoseconds

static volatile int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *motor1_line;
static struct gpiod_line *motor2_line;

void handle_signal(int signum) {
    keep_running = 0;
}

int setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    motor1_line = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!motor1_line) {
        fprintf(stderr, "Failed to get line for motor 1\n");
        gpiod_chip_close(chip);
        return -1;
    }

    motor2_line = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!motor2_line) {
        fprintf(stderr, "Failed to get line for motor 2\n");
        gpiod_line_release(motor1_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(motor1_line, "motor1", GPIOD_LINE_REQUEST_DIRECTIONS) < 0) {
        fprintf(stderr, "Failed to request line for motor 1\n");
        gpiod_line_release(motor2_line);
        gpiod_line_release(motor1_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(motor2_line, "motor2", GPIOD_LINE_REQUEST_DIRECTIONS) < 0) {
        fprintf(stderr, "Failed to request line for motor 2\n");
        gpiod_line_release(motor2_line);
        gpiod_line_release(motor1_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void cleanup_gpio() {
    if (motor1_line) {
        gpiod_line_release(motor1_line);
    }
    if (motor2_line) {
        gpiod_line_release(motor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        if (gpiod_line_set_value(motor1_line, MOTOR1_ON) < 0) {
            fprintf(stderr, "Failed to set motor 1 on\n");
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        usleep(MOTOR1_DURATION / 1000);

        if (gpiod_line_set_value(motor1_line, MOTOR1_OFF) < 0) {
            fprintf(stderr, "Failed to set motor 1 off\n");
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        if (gpiod_line_set_value(motor2_line, MOTOR2_ON) < 0) {
            fprintf(stderr, "Failed to set motor 2 on\n");
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        usleep(MOTOR2_DURATION / 1000);

        if (gpiod_line_set_value(motor2_line, MOTOR2_OFF) < 0) {
            fprintf(stderr, "Failed to set motor 2 off\n");
            cleanup_gpio();
            return EXIT_FAILURE;
        }
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

