#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define POLL_INTERVAL_NS 10 * 1000 * 1000 // 10 ms in nanoseconds
#define ALARM_DURATION_MS 1000 // 1 second

static volatile int running = 1;
static gpiod_chip *chip;
static gpiod_line *sound_sensor_line;
static gpiod_line *alarm_led_line;
static void (*cleanup)(void) = NULL;

void handle_signal(int signum) {
    running = 0;
}

void cleanup_resources(void) {
    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (cleanup) {
        cleanup();
    }
}

void sound_sensor_mode(void) {
    struct gpiod_line_event event;
    int ret;

    while (running) {
        ret = gpiod_line_event_wait(sound_sensor_line, &event, POLL_INTERVAL_NS);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        }
        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            void *context = zmq_ctx_new();
            if (!context) {
                perror("zmq_ctx_new");
                break;
            }

            void *publisher = zmq_socket(context, ZMQ_PUB);
            if (!publisher) {
                perror("zmq_socket");
                zmq_ctx_term(context);
                break;
            }

            if (zmq_bind(publisher, "tcp://*:5555") != 0) {
                perror("zmq_bind");
                zmq_close(publisher);
                zmq_ctx_term(context);
                break;
            }

            if (zmq_send(publisher, "SOUND_ALERTS", 13, 0) != 13) {
                perror("zmq_send");
            }

            zmq_close(publisher);
            zmq_ctx_term(context);
        }
    }
}

void alarm_node_mode(void) {
    void *context = zmq_ctx_new();
    if (!context) {
        perror("zmq_ctx_new");
        return;
    }

    void *subscriber = zmq_socket(context, ZMQ_SUB);
    if (!subscriber) {
        perror("zmq_socket");
        zmq_ctx_term(context);
        return;
    }

    if (zmq_connect(subscriber, "tcp://localhost:5555") != 0) {
        perror("zmq_connect");
        zmq_close(subscriber);
        zmq_ctx_term(context);
        return;
    }

    if (zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, "SOUND_ALERTS", 13) != 0) {
        perror("zmq_setsockopt");
        zmq_close(subscriber);
        zmq_ctx_term(context);
        return;
    }

    while (running) {
        char buffer[10];
        int bytes = zmq_recv(subscriber, buffer, sizeof(buffer), 0);
        if (bytes > 0) {
            gpiod_line_request_output(alarm_led_line, "Alarm LED", 1);
            usleep(ALARM_DURATION_MS * 1000);
            gpiod_line_request_output(alarm_led_line, "Alarm LED", 0);
        }
    }

    zmq_close(subscriber);
    zmq_ctx_term(context);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "Modes: sound_sensor, alarm_node\n");
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    if (strcmp(mode, "sound_sensor") != 0 && strcmp(mode, "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    sound_sensor_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_sensor_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sound_sensor_line, "Sound Sensor", GPIOD_LINE_REQ_EV_FALLING_EDGE) < 0) {
        perror("gpiod_line_request_input");
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    alarm_led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!alarm_led_line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(alarm_led_line, "Alarm LED", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(alarm_led_line);
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    cleanup = cleanup_resources;

    if (strcmp(mode, "sound_sensor") == 0) {
        sound_sensor_mode();
    } else {
        alarm_node_mode();
    }

    cleanup_resources();
    return EXIT_SUCCESS;
}

