    mosquitto_publish(mqtt_client, NULL, MQTT_TOPIC, message.payloadlen, message.payload, message.qos, message.retained);
    free((void *)message.payload);
}

void alert_callback(struct gpiod_line *line, gpiod_value_t value, void *user_data) {
