int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    struct gpiod_line_event_config event_config;
    mosquitto *mqtt_client;
    int rc;

    // Signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize syslog
    openlog("IRDecoder", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        syslog(LOG_ERR, "Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "IRDecoder") < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize libmosquitto
    mqtt_client = mosquitto_new(NULL, true, NULL);
    if (!mqtt_client) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    rc = mosquitto_connect(mqtt_client, MQTT_HOST, MQTT_PORT, 60);
    if (rc) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mqtt_client);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up event callback
    event_config.event_callback = alert_callback;
    event_config.event_callback_data = NULL;
    event_config.consumer_label = "IRDecoder";

    if (gpiod_line_event_configure(line, &event_config, &event) < 0) {
        syslog(LOG_ERR, "Failed to configure GPIO line event");
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        if (gpiod_line_event_wait(&event, -1) < 0) {
            syslog(LOG_ERR, "Failed to wait for GPIO line event");
            break;
        }
        gpiod_line_event_free(&event);
    }

    // Clean up
    gpiod_line_event_unconfig(line);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    mosquitto_disconnect(mqtt_client);
    mosquitto_destroy(mqtt_client);
    closelog();

    return EXIT_SUCCESS;
}
