#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_SLAVE_ADDR 0x23
#define I2C_SLAVE_CMD 0x10
#define I2C_CONVERSION_TIME 180
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SENSOR_COUNT 4

volatile sig_atomic_t terminate = 0;

void handle_signal(int sig) {
    terminate = 1;
}

int open_i2c_device(int *fd, int addr) {
    *fd = open(I2C_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C address");
        close(*fd);
        return -1;
    }

    return 0;
}

int write_i2c_device(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int read_i2c_device(int fd, uint8_t *data, size_t length) {
    if (read(fd, data, length) != length) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

double get_lux(int fd) {
    if (write_i2c_device(fd, I2C_SLAVE_CMD, 0x10) < 0) {
        return NAN;
    }

    usleep(I2C_CONVERSION_TIME * 1000);

    uint8_t data[2];
    if (read_i2c_device(fd, data, 2) < 0) {
        return NAN;
    }

    uint16_t lux = (data[0] << 8) | data[1];
    return lux / 1.2;
}

int setup_multicast_socket(int *sockfd) {
    *sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (*sockfd < 0) {
        perror("Failed to create socket");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (bind(*sockfd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Failed to bind socket");
        close(*sockfd);
        return -1;
    }

    return 0;
}

void send_multicast_packet(int sockfd, const char *message) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(sockfd, message, strlen(message), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Failed to send multicast packet");
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fds[SENSOR_COUNT];
    for (int i = 0; i < SENSOR_COUNT; i++) {
        if (open_i2c_device(&i2c_fds[i], I2C_SLAVE_ADDR) < 0) {
            i2c_fds[i] = -1;
        }
    }

    int sockfd;
    if (setup_multicast_socket(&sockfd) < 0) {
        sockfd = -1;
    }

    while (!terminate) {
        char message[256] = "";
        for (int i = 0; i < SENSOR_COUNT; i++) {
            double lux = NAN;
            if (i2c_fds[i] >= 0) {
                lux = get_lux(i2c_fds[i]);
            }
            char sensor_data[32];
            if (isnan(lux)) {
                snprintf(sensor_data, sizeof(sensor_data), "%d,NAN;", i + 1);
            } else {
                snprintf(sensor_data, sizeof(sensor_data), "%d,%.1f;", i + 1, lux);
            }
            strcat(message, sensor_data);
        }

        send_multicast_packet(sockfd, message);
        sleep(1);
    }

    for (int i = 0; i < SENSOR_COUNT; i++) {
        if (i2c_fds[i] >= 0) {
            close(i2c_fds[i]);
        }
    }

    if (sockfd >= 0) {
        close(sockfd);
    }

    return 0;
}

