#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x28
#define MAX_RETRIES 3
#define RETRY_DELAY 100000 // 100 ms in microseconds

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

void handle_sigint(int sig) {
    keep_running = 0;
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int open_i2c_device() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int read_sensor_data(uint8_t *data) {
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (write(i2c_fd, NULL, 0) < 0) {
            if (errno == EIO) {
                fprintf(stderr, "I2C bus error, retrying...\n");
                usleep(RETRY_DELAY);
                continue;
            } else if (errno == ENXIO) {
                fprintf(stderr, "Sensor not found\n");
                return -1;
            } else {
                perror("Failed to generate start condition");
                return -1;
            }
        }

        if (read(i2c_fd, data, 2) != 2) {
            if (errno == EIO) {
                fprintf(stderr, "I2C read error, retrying...\n");
                usleep(RETRY_DELAY);
                continue;
            } else {
                perror("Failed to read from sensor");
                return -1;
            }
        }
        return 0;
    }
    return -1;
}

double convert_to_slpm(uint16_t raw_value) {
    // Convert the 14-bit raw value to SLPM
    // Assuming the conversion formula is provided in the sensor documentation
    // Example: SLPM = (raw_value * 0.1) / 1000
    return (raw_value * 0.1) / 1000.0;
}

void log_flow_rate(double slpm) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: %f SLPM\n", time_str, slpm);
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_sigint);

    if (open_i2c_device() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("airflow_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint8_t data[2];
        if (read_sensor_data(data) == 0) {
            uint16_t raw_value = (data[0] << 6) | (data[1] >> 2);
            double slpm = convert_to_slpm(raw_value);
            log_flow_rate(slpm);
        }
        sleep(1);
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

