        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, AS7341_ENABLE_REG, AS7341_PON_BIT) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, AS7341_CFG6_REG, AS7341_SP_EN_BIT) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("spectral_log.csv", "a");
