#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define AS7341_I2C_ADDRESS 0x49
#define AS7341_ID_REG 0x00
#define AS7341_ENABLE_REG 0x01
#define AS7341_CFG6_REG 0x06
#define AS7341_SP_EN_BIT 0x01
#define AS7341_PON_BIT 0x80
#define AS7341_SPECTRAL_CHANNELS 10

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    if (read(fd, data, length) != length) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int main() {
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t id;
    if (i2c_read(i2c_fd, AS7341_ID_REG, &id, 1) < 0 || id != 0x73) {
        fprintf(stderr, "Sensor not found or ID mismatch\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, AS7341_ENABLE_REG, AS7341_PON_BIT) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, AS7341_CFG6_REG, AS7341_SP_EN_BIT) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("spectral_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        uint8_t spectral_data[AS7341_SPECTRAL_CHANNELS];
        if (i2c_read(i2c_fd, 0x10, spectral_data, AS7341_SPECTRAL_CHANNELS) < 0) {
            fprintf(stderr, "Failed to read spectral data\n");
            break;
        }

        // Simplified lux approximation (example calculation)
        int lux = spectral_data[0] - spectral_data[1]; // Placeholder for actual calculation

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,", timestamp);
        for (int i = 0; i < AS7341_SPECTRAL_CHANNELS; i++) {
            fprintf(log_file, "%d,", spectral_data[i]);
        }
        fprintf(log_file, "%d\n", lux);

        fclose(log_file);
        log_file = fopen("spectral_log.csv", "a");
        if (!log_file) {
            perror("Failed to reopen log file");
            break;
        }

        sleep(5);
    }

    if (log_file) {
        fclose(log_file);
    }
    close(i2c_fd);

    return EXIT_SUCCESS;
}
