#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define DEFAULT_I2C_ADDRESS 0x1D
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define MAX_RETRIES 3
#define BACKOFF_MS 10

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_error(const char *message) {
    FILE *error_log = fopen("seismic_error.log", "a");
    if (error_log) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(error_log, "[%s] %s\n", timestamp, message);
        fclose(error_log);
    }
}

int read_sensor(int fd, uint8_t address, float *x, float *y, float *z) {
    uint8_t buffer[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2c_smbus_read_i2c_block_data(fd, address, 6, buffer);
        if (result == 6) {
            *x = (buffer[1] << 8 | buffer[0]) / 16384.0;
            *y = (buffer[3] << 8 | buffer[2]) / 16384.0;
            *z = (buffer[5] << 8 | buffer[4]) / 16384.0;
            return 0;
        } else if (result < 0) {
            if (errno == EIO || errno == ENXIO) {
                log_error("Sensor absent or bus error");
                return -1;
            }
            log_error("I2C read error");
            retries++;
            usleep(BACKOFF_MS * 1000);
        } else {
            log_error("Unexpected I2C read result");
            return -1;
        }
    }
    return -1;
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int interval = DEFAULT_INTERVAL;
    char *filename = DEFAULT_FILENAME;
    int opt;

    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = (int)strtol(optarg, NULL, 0);
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, i2c_address) < 0) {
        log_error("Failed to acquire bus access and/or talk to slave");
        close(fd);
        exit(EXIT_FAILURE);
    }

    FILE *csv_file = fopen(filename, "w");
    if (!csv_file) {
        log_error("Failed to open CSV file");
        close(fd);
        exit(EXIT_FAILURE);
    }
    fprintf(csv_file, "timestamp,x_g,y_g,z_g\n");

    float x, y, z;
    while (keep_running) {
        if (read_sensor(fd, i2c_address, &x, &y, &z) == 0) {
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
            fprintf(csv_file, "%s,%f,%f,%f\n", timestamp, x, y, z);
            fflush(csv_file);
        }
        sleep(interval);
    }

    fclose(csv_file);
    close(fd);
    return 0;
}

