#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

int i2c_fd = -1;
int udp_fd = -1;

void cleanup(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_fd != -1) {
        close(udp_fd);
    }
    exit(0);
}

int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    uint8_t mode = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &mode, 1) != 1) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int read_light_sensor(uint16_t *lux) {
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *lux = (data[0] << 8) | data[1];
    return 0;
}

float convert_to_lux(uint16_t raw_value) {
    return raw_value / 1.2;
}

int init_udp() {
    udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_fd < 0) {
        perror("Failed to create UDP socket");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (bind(udp_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Failed to bind UDP socket");
        close(udp_fd);
        udp_fd = -1;
        return -1;
    }

    struct ip_mreq mreq;
    mreq.imr_multiaddr.s_addr = inet_addr(MULTICAST_ADDR);
    mreq.imr_interface.s_addr = htonl(INADDR_ANY);

    if (setsockopt(udp_fd, IPPROTO_IP, IP_ADD_MEMBERSHIP, &mreq, sizeof(mreq)) < 0) {
        perror("Failed to join multicast group");
        close(udp_fd);
        udp_fd = -1;
        return -1;
    }

    if (setsockopt(udp_fd, IPPROTO_IP, IP_MULTICAST_TTL, &TTL, sizeof(TTL)) < 0) {
        perror("Failed to set multicast TTL");
        close(udp_fd);
        udp_fd = -1;
        return -1;
    }

    return 0;
}

void send_lux(float lux) {
    char buffer[32];
    snprintf(buffer, sizeof(buffer), "%f", lux);

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(udp_fd, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Failed to send UDP packet");
    }
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        if (i2c_fd == -1) {
            if (init_i2c() == 0) {
                printf("I2C initialized successfully\n");
            } else {
                fprintf(stderr, "I2C initialization failed, retrying in 1 second...\n");
                sleep(1);
                continue;
            }
        }

        if (udp_fd == -1) {
            if (init_udp() == 0) {
                printf("UDP initialized successfully\n");
            } else {
                fprintf(stderr, "UDP initialization failed, retrying in 1 second...\n");
                sleep(1);
                continue;
            }
        }

        uint16_t raw_value;
        if (read_light_sensor(&raw_value) == 0) {
            float lux = convert_to_lux(raw_value);
            send_lux(lux);
        } else {
            fprintf(stderr, "Failed to read light sensor, retrying in 1 second...\n");
            close(i2c_fd);
            i2c_fd = -1;
            sleep(1);
        }

        sleep(1);
    }

    return 0;
}

