#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define INTER_BYTE_TIMEOUT_USEC 500000

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int configure_uart(int fd) {
    struct termios options;
    if (tcgetattr(fd, &options) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        return -1;
    }

    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);

    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~(PARENB | CSTOPB);
    options.c_cflag &= ~CCTS_OFLOW;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;

    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = 5; // 0.5 seconds

    if (tcsetattr(fd, TCSANOW, &options) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

void log_detection(const char *line) {
    char timestamp_str[20];
    double range_meters;
    time_t timestamp_seconds;

    if (sscanf(line, "%lf,%lf\n", &timestamp_seconds, &range_meters) == 2) {
        struct tm *tm_info = localtime(&timestamp_seconds);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range_meters);
    }
}

int main() {
    int uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (uart_fd < 0) {
        fprintf(stderr, "Failed to open UART device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (configure_uart(uart_fd) != 0) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    char buffer[256];
    ssize_t bytes_read;
    fd_set read_fds;
    struct timeval timeout;

    while (keep_running) {
        FD_ZERO(&read_fds);
        FD_SET(uart_fd, &read_fds);

        timeout.tv_sec = TIMEOUT_SEC;
        timeout.tv_usec = 0;

        int select_result = select(uart_fd + 1, &read_fds, NULL, NULL, &timeout);
        if (select_result < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select failed: %s\n", strerror(errno));
            break;
        } else if (select_result == 0) {
            fprintf(stderr, "Timeout: No data received\n");
            continue;
        }

        if (FD_ISSET(uart_fd, &read_fds)) {
            bytes_read = read(uart_fd, buffer + strlen(buffer), sizeof(buffer) - strlen(buffer) - 1);
            if (bytes_read < 0) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) continue;
                fprintf(stderr, "read failed: %s\n", strerror(errno));
                break;
            } else if (bytes_read == 0) {
                fprintf(stderr, "UART connection closed\n");
                break;
            }

            buffer[bytes_read + strlen(buffer)] = '\0';

            char *line = strtok(buffer, "\n");
            while (line != NULL) {
                log_detection(line);
                line = strtok(NULL, "\n");
            }
        }
    }

    close(uart_fd);
    return EXIT_SUCCESS;
}

