#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/serial.h>
#include <gpiod.h>

#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE B115200
#define UART_FLAGS (O_WRONLY | O_NOCTTY | O_NONBLOCK)

static int uart_fd = -1;
static struct gpiod_chip *chip;
static struct gpiod_line *left_line, *middle_line, *right_line;

void cleanup() {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_signal(int sig) {
    fprintf(stderr, "Signal %d received, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

int init_uart() {
    struct termios tty;

    uart_fd = open(UART_DEVICE, UART_FLAGS);
    if (uart_fd < 0) {
        perror("Failed to open UART device");
        return -1;
    }

    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Failed to get UART attributes");
        close(uart_fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;
    tty.c_lflag &= ~ICANON;
    tty.c_lflag &= ~ECHO;
    tty.c_lflag &= ~ECHOE;
    tty.c_lflag &= ~ECHONL;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Failed to set UART attributes");
        close(uart_fd);
        return -1;
    }

    return 0;
}

void send_uart(const char *message) {
    if (uart_fd < 0) {
        return;
    }

    ssize_t bytes_written = write(uart_fd, message, strlen(message));
    if (bytes_written < 0) {
        perror("Failed to write to UART");
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    left_line = gpiod_chip_get_line(chip, 4);
    middle_line = gpiod_chip_get_line(chip, 17);
    right_line = gpiod_chip_get_line(chip, 27);

    if (!left_line || !middle_line || !right_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(left_line, "left_sensor", GPIOD_LINE_REQ_EV_NONE) < 0 ||
        gpiod_line_request_input(middle_line, "middle_sensor", GPIOD_LINE_REQ_EV_NONE) < 0 ||
        gpiod_line_request_input(right_line, "right_sensor", GPIOD_LINE_REQ_EV_NONE) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_set_flags(left_line, GPIOD_LINE_FLAG_ACTIVE_LOW) < 0 ||
        gpiod_line_set_flags(middle_line, GPIOD_LINE_FLAG_ACTIVE_LOW) < 0 ||
        gpiod_line_set_flags(right_line, GPIOD_LINE_FLAG_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to set GPIO line flags\n");
        cleanup();
        return 1;
    }

    if (init_uart() < 0) {
        cleanup();
        return 1;
    }

    while (1) {
        int left_state = gpiod_line_get_value(left_line);
        int middle_state = gpiod_line_get_value(middle_line);
        int right_state = gpiod_line_get_value(right_line);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);

        printf("[%02d:%02d:%02d] Left: %d, Middle: %d, Right: %d\n",
               tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
               left_state, middle_state, right_state);

        if (left_state == 0 && middle_state == 0 && right_state == 0) {
            send_uart("EMERGENCY STOP!\n");
        }

        usleep(100000); // 100 ms
    }

    cleanup();
    return 0;
}

