    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    left_line = gpiod_chip_get_line(chip, 4);
    middle_line = gpiod_chip_get_line(chip, 17);
    right_line = gpiod_chip_get_line(chip, 27);

    if (!left_line || !middle_line || !right_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(left_line, "left_sensor", GPIOD_LINE_REQ_EV_NONE) < 0 ||
        gpiod_line_request_input(middle_line, "middle_sensor", GPIOD_LINE_REQ_EV_NONE) < 0 ||
        gpiod_line_request_input(right_line, "right_sensor", GPIOD_LINE_REQ_EV_NONE) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_set_flags(left_line, GPIOD_LINE_FLAG_ACTIVE_LOW) < 0 ||
        gpiod_line_set_flags(middle_line, GPIOD_LINE_FLAG_ACTIVE_LOW) < 0 ||
        gpiod_line_set_flags(right_line, GPIOD_LINE_FLAG_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to set GPIO line flags\n");
        cleanup();
        return 1;
    }

    if (init_uart() < 0) {
        cleanup();
        return 1;
    }

    while (1) {
        int left_state = gpiod_line_get_value(left_line);
        int middle_state = gpiod_line_get_value(middle_line);
        int right_state = gpiod_line_get_value(right_line);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);

        printf("[%02d:%02d:%02d] Left: %d, Middle: %d, Right: %d\n",
               tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
               left_state, middle_state, right_state);

        if (left_state == 0 && middle_state == 0 && right_state == 0) {
            send_uart("EMERGENCY STOP!\n");
        }

        usleep(100000); // 100 ms
    }

    cleanup();
    return 0;
}
